const PARTIAL_NATIVE_CORE_SYMBOL: usize = 7;
const PARTIAL_RUNTIME_SYMBOL: usize = 8;
const PREPARED_FALLBACK_RUNTIME_SYMBOL: usize = 9;
// The mutually exclusive Ordered-TNFA prepared layout gives these established
// slots explicit object/private/gate meanings. Its Span-fill compatibility
// helper occupies the first free slot after the search fallback.
const ORDERED_NFA_OBJECT_SYMBOL: usize = 5;
const ORDERED_NFA_IDENTITY_SYMBOL: usize = 6;
const ORDERED_NFA_PRIVATE_ENTRY_SYMBOL: usize = 7;
const ORDERED_NFA_BULK_GATE_ENTRY_SYMBOL: usize = 8;
const ORDERED_NFA_SEARCH_FALLBACK_RUNTIME_SYMBOL: usize = 9;
const ORDERED_NFA_SPAN_FILL_RUNTIME_SYMBOL: usize = 10;
const PREPARED_PREFLIGHT_RUNTIME_SYMBOL: usize = 10;
const PARTIAL_SPAN_RECOVERY_RUNTIME_SYMBOL: usize = 11;
// Dynamic-row and partial-Span entries are mutually exclusive layouts, so
// their one layout-specific helper occupies the same deterministic slot.
const DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL: usize = 11;
// Static-prefix and dynamic-row entries are likewise disjoint. Slot 12 names
// either the generated local-exit retirement boundary or the dynamic-row
// continuation selected by that exact prepared layout.
const STATIC_PREFIX_RETIRE_RUNTIME_SYMBOL: usize = 12;
const DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL: usize = 12;
// Static-prefix and dynamic-row entries are disjoint. Slot 13 is therefore
// either the dynamic-row Span postflight or the lazy direct static-prefix Span
// postflight selected after an inline-authenticated native endpoint.
const STATIC_PREFIX_LAZY_SPAN_RECOVERY_RUNTIME_SYMBOL: usize = 13;
const DYNAMIC_ROWS_SPAN_RECOVERY_RUNTIME_SYMBOL: usize = 13;
const DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL: usize = 14;
const DYNAMIC_ROWS_SPAN_FILL_RUNTIME_SYMBOL: usize = 15;

