/// Build a native table for the concrete emitted target.
///
/// Architecture-only test builders conservatively retain AArch64 first-lane
/// data because their eventual feature set is unknown. Once the target is
/// concrete, a target without ASIMD cannot enter an ASIMD scanner, loop, or
/// sparse-lookup route, so its ASIMD-only constants are dead data.
fn build_native_dfa_table_for_target_with_cost_model_and_data_limit(
    view: NativeProgramView<'_>,
    target: Target,
    vector_cost_model: NativeVectorFilterCostModel,
    relation_vector_owns_route: bool,
    max_native_data_bytes: usize,
) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
    build_native_dfa_table_for_target_with_cost_model_data_limit_and_sync_policy(
        view,
        target,
        vector_cost_model,
        relation_vector_owns_route,
        max_native_data_bytes,
        true,
    )
}

fn build_native_dfa_table_for_target_with_cost_model_data_limit_and_sync_policy(
    view: NativeProgramView<'_>,
    target: Target,
    vector_cost_model: NativeVectorFilterCostModel,
    relation_vector_owns_route: bool,
    max_native_data_bytes: usize,
    allow_synchronizing_accept_reverse: bool,
) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
    build_native_dfa_table_with_cost_model_data_limit_and_asimd_policy(
        view,
        target.architecture,
        vector_cost_model,
        relation_vector_owns_route,
        max_native_data_bytes,
        target.features.has(CpuFeature::Aarch64Asimd),
        Some(target),
        allow_synchronizing_accept_reverse,
    )
}

fn build_native_dfa_table_with_cost_model_data_limit_and_asimd_policy(
    view: NativeProgramView<'_>,
    architecture: Architecture,
    vector_cost_model: NativeVectorFilterCostModel,
    relation_vector_owns_route: bool,
    max_native_data_bytes: usize,
    permit_asimd_candidate_mask: bool,
    ranking_target: Option<Target>,
    allow_synchronizing_accept_reverse: bool,
) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
    // Seeded reverse currently has scalar and ASIMD AArch64 scanners, but no
    // SVE lowering. Preserve every pure or mixed SVE suffix incumbent until
    // that route has an independently measured seeded implementation.
    let permit_synchronizing_accept_reverse = allow_synchronizing_accept_reverse
        && ranking_target.is_none_or(|target| {
            target.architecture == Architecture::X86_64
                || (target.features.has(CpuFeature::Aarch64Asimd)
                    && !target.features.has(CpuFeature::Aarch64Sve))
        });
    let exact_rows = native_exact_row_intern_candidate_plan(view, architecture);
    // Derivation retains only maps and representative class ordinals. The
    // selected candidate reads representative cells directly from the graph;
    // no rows-by-quotient matrix is speculatively materialized.
    let column_quotient = derive_native_column_quotient_plan(
        view.dfa,
        view.partial_discovered_states,
        view.collapse_partial_holes,
    );
    // Phase one owns at most one emitted table. Keep only six compact costs,
    // then drop each table before probing the next descriptor. This makes the
    // optimizer's peak table allocation independent of enumeration order.
    let mut ranked = [None; NativeDenseCandidateId::ALL.len()];
    let mut canonical_decline = None;
    for stable_id in NativeDenseCandidateId::ALL {
        match build_native_dense_candidate(
            stable_id,
            view,
            architecture,
            vector_cost_model,
            relation_vector_owns_route,
            max_native_data_bytes,
            exact_rows.as_ref(),
            column_quotient.as_ref(),
            permit_asimd_candidate_mask,
            permit_synchronizing_accept_reverse,
        ) {
            Ok(Some(lowering)) => {
                let cost = if let Some(target) = ranking_target {
                    native_dense_candidate_cost_for_target(
                        target,
                        lowering,
                        max_native_data_bytes,
                        stable_id,
                    )?
                } else {
                    native_dense_candidate_cost(
                        architecture,
                        lowering.0.len(),
                        lowering.1,
                        stable_id,
                    )
                }
                .ok_or(ObjectError::InvalidModule(
                    "dense native candidate has a sparse layout",
                ))?;
                ranked[stable_id.index()] = Some(cost);
            }
            Ok(None) => {}
            Err(error) if is_optional_native_table_decline(&error) => {
                if stable_id == NativeDenseCandidateId::CanonicalNatural {
                    canonical_decline = Some(error);
                }
            }
            Err(error) => return Err(error),
        }
    }

    // Phase two reconstructs descriptors by ranked cost. A transient bounded
    // or allocation refusal falls through to the next proved descriptor;
    // malformed, overflowing, and unsupported builds remain hard failures.
    while let Some(cost) = ranked.iter().flatten().copied().min() {
        ranked[cost.stable_id.index()] = None;
        match build_native_dense_candidate(
            cost.stable_id,
            view,
            architecture,
            vector_cost_model,
            relation_vector_owns_route,
            max_native_data_bytes,
            exact_rows.as_ref(),
            column_quotient.as_ref(),
            permit_asimd_candidate_mask,
            permit_synchronizing_accept_reverse,
        ) {
            Ok(Some(lowering)) => return Ok(lowering),
            Ok(None) => {}
            Err(error) if is_optional_native_table_decline(&error) => {
                if cost.stable_id == NativeDenseCandidateId::CanonicalNatural {
                    canonical_decline = Some(error);
                }
            }
            Err(error) => return Err(error),
        }
    }

    let dense_error = canonical_decline.ok_or(ObjectError::InvalidModule(
        "native dense candidate ranking lost the canonical lowering",
    ))?;
    // Sparse and local-map rows remain resource-only alternates after every
    // feasible dense representation. This prevents a branchier modal or
    // bitmap row from shadowing a smaller exact or column-quotient dense table.
    // Exact duplicate normalized rows produce identical records, so try those
    // proved compositions before the uninterned record. Boundary records keep
    // their established uninterned route until they have an independent oracle.
    let comparison_plan =
        native_default_exception_retry_plan(view, architecture, &dense_error);
    if let Some(lowering) = build_native_ordinal_retry(
        view,
        architecture,
        vector_cost_model,
        relation_vector_owns_route,
        max_native_data_bytes,
        &dense_error,
        exact_rows.as_ref(),
        column_quotient.as_ref(),
        comparison_plan,
        permit_asimd_candidate_mask,
        permit_synchronizing_accept_reverse,
        ranking_target,
    )? {
        return Ok(lowering);
    }
    if let Some(comparison) = comparison_plan {
        for use_exact_rows in [true, false] {
            let candidate_exact = if use_exact_rows {
                if comparison.keys == NativeDefaultExceptionKeys::Boundaries {
                    continue;
                }
                let Some(exact) = exact_rows.as_ref() else {
                    continue;
                };
                Some(exact)
            } else {
                None
            };
            let fixed = optional_native_lowering(
                build_native_dfa_table_with_cost_model_and_data_limit_once_with_exact_rows_and_asimd_policy(
                    view,
                    architecture,
                    vector_cost_model,
                    relation_vector_owns_route,
                    max_native_data_bytes,
                    Some(comparison),
                    candidate_exact,
                    false,
                    None,
                    None,
                    None,
                    permit_asimd_candidate_mask,
                    permit_synchronizing_accept_reverse,
                )
                .and_then(|lowering| {
                    require_native_start_scanner(view, max_native_data_bytes, lowering)
                }),
            )?;
            let hybrid_plan = derive_native_hybrid_sparse_plan(
                view,
                comparison,
                candidate_exact,
            );
            let hybrid = if let Some(plan) = hybrid_plan.as_ref() {
                optional_native_lowering(
                    build_native_dfa_table_with_cost_model_and_data_limit_once_with_exact_rows_and_asimd_policy(
                        view,
                        architecture,
                        vector_cost_model,
                        relation_vector_owns_route,
                        max_native_data_bytes,
                        None,
                        candidate_exact,
                        false,
                        None,
                        None,
                        Some(plan),
                        permit_asimd_candidate_mask,
                        permit_synchronizing_accept_reverse,
                    )
                    .and_then(|lowering| {
                        require_native_start_scanner(view, max_native_data_bytes, lowering)
                    }),
                )?
            } else {
                None
            };
            match (fixed, hybrid) {
                (Some(fixed), Some(hybrid)) => {
                    let fixed_cost = native_target_finalized_data_cost(
                        ranking_target,
                        &fixed,
                        max_native_data_bytes,
                    )?;
                    let hybrid_cost = native_target_finalized_data_cost(
                        ranking_target,
                        &hybrid,
                        max_native_data_bytes,
                    )?;
                    let profitable = ranking_target.is_some_and(|target| {
                        comparison.sparse_boundary_profile.is_some_and(|profile| {
                            native_hybrid_sparse_guard_is_profitable(
                                profile,
                                comparison.exception_capacity,
                                hybrid.1.cells,
                                target,
                            )
                        })
                    });
                    if native_profitable_hybrid_is_preferred(
                        fixed_cost,
                        hybrid_cost,
                        profitable,
                    ) {
                        return Ok(hybrid);
                    }
                    return Ok(fixed);
                }
                (Some(fixed), None) => return Ok(fixed),
                (None, Some(hybrid)) => return Ok(hybrid),
                (None, None) => {}
            }
        }
    }
    // Optional resource pressure preserves the canonical resource decline.
    Err(dense_error)
}

#[cfg(test)]
fn preserve_dense_decline_after_optional_retry(
    dense_error: ObjectError,
    retry: Result<(Vec<u8>, NativeDfaLayout), ObjectError>,
) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
    match retry {
        Ok(lowering) => Ok(lowering),
        Err(error) if is_optional_native_table_decline(&error) => Err(dense_error),
        Err(error) => Err(error),
    }
}

