#[allow(
    clippy::too_many_arguments,
    reason = "partial packing keeps semantic holes and a bounded accelerator set separate from physical rows"
)]
fn pack_native_partial_forward_cell_with_exact_rows_and_loop_states(
    next: u32,
    accepted: bool,
    machine_offset: usize,
    row_bytes: usize,
    complete_states: usize,
    initial_scannable: bool,
    loop_states: [Option<u32>; 2],
    partial: NativePartialDfaLayout,
    cells: NativeCellEncoding,
    exact_rows: Option<&NativeExactRowInternPlan>,
) -> Result<u32, ObjectError> {
    if next == NO_DFA_STATE
        || usize::try_from(next)
            .ok()
            .is_some_and(|next| next < complete_states)
    {
        return pack_native_forward_cell_with_exact_rows_and_loop_states(
            next,
            accepted,
            machine_offset,
            row_bytes,
            complete_states,
            initial_scannable,
            loop_states,
            cells,
            exact_rows,
        );
    }
    let next = usize::try_from(next)
        .map_err(|_| ObjectError::ArithmeticOverflow("native partial destination"))?;
    let resume = next
        .checked_sub(complete_states)
        .ok_or(ObjectError::InvalidModule(
            "native partial destination precedes completed rows",
        ))?;
    let resume = u32::try_from(resume)
        .map_err(|_| ObjectError::ArithmeticOverflow("native partial resume index"))?;
    if resume >= partial.resume_states {
        return Err(ObjectError::InvalidModule(
            "native partial destination exceeds resume-key extent",
        ));
    }
    let token = if partial.collapse_holes {
        partial.hole_token_base
    } else {
        partial
            .hole_token_base
            .checked_add(resume)
            .ok_or(ObjectError::ArithmeticOverflow("native partial hole token"))?
    };
    if token == 0 || token > cells.next_mask() || cells.is_compact() && token == cells.dead_token()
    {
        return Err(ObjectError::InvalidModule(
            "native partial hole token exceeds its cell encoding",
        ));
    }
    Ok(token | cells.accelerated() | if accepted { cells.accepts() } else { 0 })
}

#[allow(
    clippy::too_many_arguments,
    reason = "variable sparse packing authenticates semantic rows, absolute starts, holes and accelerators together"
)]
#[cfg(test)]
fn pack_native_partial_forward_cell_with_variable_rows(
    next: u32,
    accepted: bool,
    complete_states: usize,
    initial_scannable: bool,
    loop_state: Option<u32>,
    partial: NativePartialDfaLayout,
    cells: NativeCellEncoding,
    exact_rows: Option<&NativeExactRowInternPlan>,
    row_offsets: &[u32],
) -> Result<u32, ObjectError> {
    pack_native_partial_forward_cell_with_variable_rows_and_loop_states(
        next,
        accepted,
        complete_states,
        initial_scannable,
        [loop_state, None],
        partial,
        cells,
        exact_rows,
        row_offsets,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "variable sparse packing authenticates rows, holes and a bounded accelerator set together"
)]
fn pack_native_partial_forward_cell_with_variable_rows_and_loop_states(
    next: u32,
    accepted: bool,
    complete_states: usize,
    initial_scannable: bool,
    loop_states: [Option<u32>; 2],
    partial: NativePartialDfaLayout,
    cells: NativeCellEncoding,
    exact_rows: Option<&NativeExactRowInternPlan>,
    row_offsets: &[u32],
) -> Result<u32, ObjectError> {
    if !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32) {
        return Err(ObjectError::InvalidModule(
            "variable sparse rows have an invalid cell width",
        ));
    }
    if next == NO_DFA_STATE {
        return pack_native_encoded_cell(
            usize::try_from(cells.dead_token())
                .map_err(|_| ObjectError::ArithmeticOverflow("native DFA dead token"))?,
            accepted,
            false,
            true,
            cells,
            NativeDeadCellPolicy::ForwardTagged,
        );
    }
    let logical = usize::try_from(next)
        .map_err(|_| ObjectError::ArithmeticOverflow("native partial destination"))?;
    if logical < complete_states {
        let physical = exact_rows
            .map(|plan| {
                plan.physical_state(logical).ok_or(ObjectError::InvalidModule(
                    "native DFA next state has no physical variable row",
                ))
            })
            .transpose()?
            .unwrap_or(logical);
        let row_offset = row_offsets
            .get(physical)
            .copied()
            .and_then(|offset| usize::try_from(offset).ok())
            .ok_or(ObjectError::InvalidModule(
                "native DFA next state has no variable row offset",
            ))?;
        let encoded = encode_native_row_offset(row_offset, cells).ok_or(
            ObjectError::InvalidModule("native variable row is not encodable"),
        )?;
        let accelerated =
            (initial_scannable && next == 0) || loop_states.contains(&Some(next));
        return pack_native_encoded_cell(
            encoded,
            accepted,
            accelerated,
            false,
            cells,
            NativeDeadCellPolicy::ForwardTagged,
        );
    }

    let resume = logical.checked_sub(complete_states).ok_or(
        ObjectError::InvalidModule("native partial destination precedes completed rows"),
    )?;
    let resume = u32::try_from(resume)
        .map_err(|_| ObjectError::ArithmeticOverflow("native partial resume index"))?;
    if resume >= partial.resume_states {
        return Err(ObjectError::InvalidModule(
            "native partial destination exceeds resume-key extent",
        ));
    }
    let token = if partial.collapse_holes {
        partial.hole_token_base
    } else {
        partial
            .hole_token_base
            .checked_add(resume)
            .ok_or(ObjectError::ArithmeticOverflow("native partial hole token"))?
    };
    if token == 0 || token > cells.next_mask() || cells.is_compact() && token == cells.dead_token()
    {
        return Err(ObjectError::InvalidModule(
            "native partial hole token exceeds its variable-row cell encoding",
        ));
    }
    Ok(token | cells.accelerated() | if accepted { cells.accepts() } else { 0 })
}

fn pack_native_cell_with_acceleration(
    next: u32,
    flag: bool,
    machine_offset: usize,
    row_bytes: usize,
    states: usize,
    accelerated: bool,
    cells: NativeCellEncoding,
) -> Result<u32, ObjectError> {
    let dead = next == NO_DFA_STATE;
    let encoded_next = encode_native_next(
        next,
        machine_offset,
        row_bytes,
        states,
        cells,
    )?;
    pack_native_encoded_cell(
        encoded_next,
        flag,
        accelerated,
        dead,
        cells,
        NativeDeadCellPolicy::LegacyZero,
    )
}

fn pack_native_encoded_cell(
    encoded_next: usize,
    flag: bool,
    accelerated: bool,
    dead: bool,
    cells: NativeCellEncoding,
    dead_policy: NativeDeadCellPolicy,
) -> Result<u32, ObjectError> {
    let encoded_next = u32::try_from(encoded_next)
        .map_err(|_| ObjectError::ArithmeticOverflow("native DFA encoded next row"))?;
    if dead && accelerated {
        return Err(ObjectError::InvalidModule(
            "dead native DFA cell cannot enter semantic accelerator dispatch",
        ));
    }
    if encoded_next > cells.next_mask()
        || !dead && cells.is_compact() && encoded_next == cells.dead_token()
    {
        return Err(ObjectError::InvalidModule(
            "native DFA state exceeds packed cell",
        ));
    }
    // Compact zero-based tokens make row zero a valid ordinary destination,
    // so their dead sentinel is always tagged. Forward wide cells tag their
    // zero dead payload as well. Ordinary and seeded wide reverse cells
    // deliberately keep their historical literal-zero representation;
    // compact cells stay tagged under either policy. `accelerated` itself is
    // still a semantic graph tag and remains invalid for dead inputs above.
    let encoded_accelerated = accelerated || dead && dead_policy.tags_dead(cells);
    Ok(encoded_next
        | if encoded_accelerated {
            cells.accelerated()
        } else {
            0
        }
        | if flag { cells.accepts() } else { 0 })
}

fn append_native_packed_cell(
    bytes: &mut Vec<u8>,
    packed: u32,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    match cells {
        NativeCellEncoding::Compact8Direct => {
            let packed = u8::try_from(packed)
                .map_err(|_| ObjectError::InvalidModule("byte-compact native cell overflowed"))?;
            bytes.push(packed);
        }
        NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            let packed = u16::try_from(packed)
                .map_err(|_| ObjectError::InvalidModule("compact native cell overflowed"))?;
            bytes.extend_from_slice(&packed.to_le_bytes());
        }
        NativeCellEncoding::Wide32 => bytes.extend_from_slice(&packed.to_le_bytes()),
    }
    Ok(())
}

/// Fill non-semantic physical row cells with the encoding's exact dead value.
///
/// Indexed class rows can contain power-of-two padding that the authenticated
/// class map never addresses. Keeping those cells dead anyway preserves the
/// packed decoder invariant under structural inspection: zero is a valid
/// compact token for row zero and must not be used as generic cell padding.
fn pad_native_packed_row(
    bytes: &mut Vec<u8>,
    row_end: usize,
    cells: NativeCellEncoding,
    dead_policy: NativeDeadCellPolicy,
) -> Result<(), ObjectError> {
    if bytes.len() > row_end
        || !row_end
            .checked_sub(bytes.len())
            .is_some_and(|padding| padding.is_multiple_of(cells.bytes()))
    {
        return Err(ObjectError::InvalidModule("native packed row padding"));
    }
    let dead = cells.dead_token()
        | if dead_policy.tags_dead(cells) {
            cells.accelerated()
        } else {
            0
        };
    while bytes.len() < row_end {
        append_native_packed_cell(bytes, dead, cells)?;
    }
    Ok(())
}

const REGEX_REDUX_TEXT_SECTION: usize = 0;
const REGEX_REDUX_DATA_SECTION: usize = 1;
const REGEX_REDUX_ENTRY_SYMBOL: usize = 0;
const REGEX_REDUX_DATA_SYMBOL: usize = 1;
const REGEX_REDUX_COMPONENT_SYMBOL_BASE: usize = 2;

#[derive(Clone, Debug)]
struct NativeRegexReduxDataLayout {
    bytes: Vec<u8>,
    variant_prefixes: Vec<(usize, usize)>,
    replacements: Vec<(usize, usize)>,
}

fn native_regex_redux_data_layout(
    identity: [u8; 32],
    variants: &[&str; 9],
    substitutions: &[(&str, &[u8]); 5],
) -> Result<NativeRegexReduxDataLayout, ObjectError> {
    let mut bytes = Vec::new();
    bytes
        .try_reserve_exact(1024)
        .map_err(|_| ObjectError::Allocation("regex-redux native data"))?;
    bytes.extend_from_slice(&identity);
    let mut variant_prefixes = Vec::new();
    variant_prefixes
        .try_reserve_exact(variants.len())
        .map_err(|_| ObjectError::Allocation("regex-redux report prefixes"))?;
    for variant in variants {
        let offset = bytes.len();
        bytes.extend_from_slice(variant.as_bytes());
        bytes.push(b' ');
        variant_prefixes.push((offset, bytes.len() - offset));
    }
    let mut replacements = Vec::new();
    replacements
        .try_reserve_exact(substitutions.len())
        .map_err(|_| ObjectError::Allocation("regex-redux replacements"))?;
    for (_, replacement) in substitutions {
        let offset = bytes.len();
        bytes.extend_from_slice(replacement);
        replacements.push((offset, replacement.len()));
    }
    Ok(NativeRegexReduxDataLayout {
        bytes,
        variant_prefixes,
        replacements,
    })
}

fn native_regex_redux_module(
    target: Target,
    identity: [u8; 32],
    code: Vec<u8>,
    data: Vec<u8>,
    component_entries: &[String],
    relocations: Vec<ModuleRelocation>,
) -> Result<CompiledModule, ObjectError> {
    let entry_name = identity_symbol("fre_aot_regex_rebar_regex_redux_v1_", &identity)?;
    let mut symbols = Vec::new();
    symbols
        .try_reserve_exact(REGEX_REDUX_COMPONENT_SYMBOL_BASE + component_entries.len())
        .map_err(|_| ObjectError::Allocation("regex-redux symbols"))?;
    symbols.push(ModuleSymbol {
        name: entry_name,
        binding: SymbolBinding::Global,
        kind: SymbolKind::Function,
        section: Some(REGEX_REDUX_TEXT_SECTION),
        offset: 0,
        size: u64::try_from(code.len())
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux text extent"))?,
    });
    symbols.push(ModuleSymbol {
        name: ".Lfre_aot_regex_rebar_regex_redux_data_v1".to_owned(),
        binding: SymbolBinding::Local,
        kind: SymbolKind::Object,
        section: Some(REGEX_REDUX_DATA_SECTION),
        offset: 0,
        size: u64::try_from(data.len())
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux data extent"))?,
    });
    for entry in component_entries {
        symbols.push(ModuleSymbol {
            name: entry.clone(),
            binding: SymbolBinding::Global,
            kind: SymbolKind::Function,
            section: None,
            offset: 0,
            size: 0,
        });
    }
    Ok(CompiledModule {
        target,
        sections: vec![
            ModuleSection {
                name: ".text",
                kind: SectionKind::Text,
                alignment: if target.architecture == Architecture::X86_64 {
                    16
                } else {
                    4
                },
                data: code.into_boxed_slice(),
            },
            ModuleSection {
                name: ".rodata.fre.regex-redux",
                kind: SectionKind::ReadOnlyData,
                alignment: 16,
                data: data.into_boxed_slice(),
            },
        ]
        .into_boxed_slice(),
        symbols: symbols.into_boxed_slice(),
        relocations: relocations.into_boxed_slice(),
        entry_symbol_index: REGEX_REDUX_ENTRY_SYMBOL,
        prepared_entry_symbol_index: None,
        prepared_span_fill_symbol_index: None,
        prepared_exists_batch_symbol_index: None,
        prepared_count_symbol_index: None,
        prepared_span_sum_symbol_index: None,
        prepared_grep_count_symbol_index: None,
        prepared_bulk_strategy: None,
        required_prepare_capabilities: 0,
        native_prepared_bulk_search_target: None,
        ordered_nfa_bulk_gate_target: None,
        prepared_aggregate_exports: PreparedAggregateExports::NONE,
        prepared_aggregate_strategy: None,
        runtime_symbol_index: None,
        runtime_program_symbol_index: None,
        start_accelerator: StartAccelerator::None,
        anchored_prefix_filter_bytes: 0,
        slow_aot_report: None,
        slow_context_aot_report: None,
        compiler_k0_aot_report: None,
        exact_finite_exists_leaf_report: None,
        exact_finite_selected_end_teddy_aot_report: None,
        exact_finite_selected_end_teddy_aot_report_v2: None,
        ordered_finite_language_aot_report: None,
        slow_retained_forward_minimized: false,
        optimizing_fallbacks_may_continue: true,
        bit_parallel_endpoint_oracle_lowered: false,
        bit_parallel_exact_endpoint_lowered: false,
        synchronizing_accept_reverse_lowered: false,
        ordered_nfa_start_closure_dispatch_lowered: false,
        ordered_nfa_start_prefix_lowered: false,
        ordered_nfa_terminal_exact_set_lowered: None,
        ordered_nfa_whole_window_width_gate_lowered: false,
    })
}

pub(crate) fn lower_native_regex_redux_operation_v1(
    target: Target,
    identity: [u8; 32],
    component_entries: &[String],
    variants: &[&str; 9],
    substitutions: &[(&str, &[u8]); 5],
) -> Result<CompiledModule, ObjectError> {
    if component_entries.len() != crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS
        || target.abi
            != match target.architecture {
                Architecture::X86_64 => CallAbi::SystemV,
                Architecture::Aarch64 => CallAbi::Aapcs64,
            }
    {
        return Err(ObjectError::InvalidModule(
            "regex-redux target or component closure",
        ));
    }
    let data = native_regex_redux_data_layout(identity, variants, substitutions)?;
    let (code, relocations) = match target.architecture {
        Architecture::X86_64 => lower_x86_64_native_regex_redux_v1(identity, &data)?,
        Architecture::Aarch64 => lower_aarch64_native_regex_redux_v1(identity, &data)?,
    };
    native_regex_redux_module(
        target,
        identity,
        code,
        data.bytes,
        component_entries,
        relocations,
    )
}

type X86Label = usize;

#[derive(Clone, Copy, Debug)]
struct X86Fixup {
    instruction: usize,
    displacement: usize,
    label: X86Label,
    short_opcode: Option<u8>,
    long_bytes: usize,
}

struct X86Finished {
    code: Vec<u8>,
    label_offsets: Vec<Option<usize>>,
}

impl X86Finished {
    fn label_offset(&self, label: X86Label) -> Result<usize, ObjectError> {
        self.label_offsets
            .get(label)
            .copied()
            .flatten()
            .ok_or(ObjectError::InvalidModule("unbound x86 offset label"))
    }
}

struct X86Assembler {
    code: Vec<u8>,
    labels: Vec<Option<usize>>,
    fixups: Vec<X86Fixup>,
    instruction_offsets: Vec<usize>,
}

struct NativeCaptureMaterializerLowering {
    code: Vec<u8>,
    plan_relocation_offset: usize,
}

struct NativeCaptureNextLowering {
    code: Vec<u8>,
    selector_call_offset: usize,
    materializer_call_offset: usize,
}

struct Aarch64NativeCaptureMaterializerLowering {
    code: Vec<u8>,
    plan_page_relocation_offset: usize,
    plan_page_offset_relocation_offset: usize,
}

struct Aarch64NativeCaptureNextLowering {
    code: Vec<u8>,
    selector_call_offset: usize,
    materializer_call_offset: usize,
}

struct X86NativeParticipationLowering {
    code: Vec<u8>,
    plan_relocation_offset: usize,
}

struct Aarch64NativeParticipationLowering {
    code: Vec<u8>,
    plan_page_relocation_offset: usize,
    plan_page_offset_relocation_offset: usize,
}

enum NativeParticipationLowering {
    X86(X86NativeParticipationLowering),
    Aarch64(Aarch64NativeParticipationLowering),
    Negative(Vec<u8>),
}

impl NativeParticipationLowering {
    fn code(&self) -> &[u8] {
        match self {
            Self::X86(lowered) => &lowered.code,
            Self::Aarch64(lowered) => &lowered.code,
            Self::Negative(code) => code,
        }
    }
}

enum NativeCapturePlanLink {
    None,
    X86 {
        displacement: usize,
        geometry: crate::capture_aot::NativeCapturePlanGeometryV1,
    },
    Aarch64 {
        page: usize,
        page_offset: usize,
        geometry: crate::capture_aot::NativeCapturePlanGeometryV1,
    },
}

enum NativeCaptureLocalCalls {
    None,
    X86 { selector: usize, materializer: usize },
    Aarch64 { selector: usize, materializer: usize },
}

fn native_participation_negative(architecture: Architecture) -> Result<Vec<u8>, ObjectError> {
    match architecture {
        Architecture::X86_64 => Ok(vec![
            0xb8,
            u8::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_STATUS_UNAVAILABLE)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation status"))?,
            0,
            0,
            0,
            0xc3,
        ]),
        Architecture::Aarch64 => {
            let mut code = Vec::new();
            push_bytes(
                &mut code,
                &aarch64_movz_w(
                    0,
                    u16::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_STATUS_UNAVAILABLE)
                        .map_err(|_| ObjectError::ArithmeticOverflow("participation status"))?,
                )?
                .to_le_bytes(),
            )?;
            push_bytes(&mut code, &0xd65f_03c0_u32.to_le_bytes())?;
            Ok(code)
        }
    }
}

fn native_participation_target_word(target: Target) -> Result<u32, ObjectError> {
    let architecture = match target.architecture {
        Architecture::X86_64 => 1_u32,
        Architecture::Aarch64 => 2,
    };
    let operating_system = match target.operating_system {
        OperatingSystem::Linux => 1_u32,
        OperatingSystem::Macos => 2,
    };
    let abi = match target.abi {
        CallAbi::SystemV => 1_u32,
        CallAbi::Aapcs64 => 2,
    };
    operating_system
        .checked_shl(8)
        .and_then(|os| abi.checked_shl(16).map(|abi| architecture | os | abi))
        .ok_or(ObjectError::ArithmeticOverflow(
            "native participation target header",
        ))
}

fn validate_native_participation_geometry(
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<(), ObjectError> {
    if geometry.kind != crate::participation_aot::NativeParticipationPlanKindV1::Dfa {
        return Err(ObjectError::InvalidModule(
            "native participation DFA geometry kind",
        ));
    }
    let expected_transitions = geometry
        .state_count
        .checked_mul(geometry.alphabet_len)
        .and_then(|cells| cells.checked_mul(geometry.signature_count))
        .ok_or(ObjectError::ArithmeticOverflow(
            "native participation transition geometry",
        ))?;
    let starts_end = geometry
        .start_states_offset
        .checked_add(geometry.signature_count.checked_mul(4).ok_or(
            ObjectError::ArithmeticOverflow("native participation start states"),
        )?)
        .ok_or(ObjectError::ArithmeticOverflow(
            "native participation start states",
        ))?;
    let transitions_end = geometry
        .transitions_offset
        .checked_add(geometry.transition_count.checked_mul(4).ok_or(
            ObjectError::ArithmeticOverflow("native participation transitions"),
        )?)
        .ok_or(ObjectError::ArithmeticOverflow(
            "native participation transitions",
        ))?;
    let accepts_end = geometry
        .accept_counts_offset
        .checked_add(geometry.state_count)
        .ok_or(ObjectError::ArithmeticOverflow(
            "native participation accepts",
        ))?;
    if geometry.total_bytes < crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES
        || geometry.group_count == 0
        || geometry.group_count > 64
        || geometry.signature_count == 0
        || geometry.signature_count > 256
        || geometry.alphabet_len == 0
        || geometry.alphabet_len > 256
        || geometry.state_count == 0
        || geometry.transition_count != expected_transitions
        || geometry.assertions_offset != crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES
        || geometry.signatures_offset < geometry.assertions_offset
        || geometry.byte_classes_offset < geometry.signatures_offset
        || geometry.boundary_map_offset < geometry.byte_classes_offset + 256
        || geometry.start_states_offset < geometry.boundary_map_offset + 4
        || geometry.transitions_offset < starts_end
        || geometry.accept_counts_offset < transitions_end
        || geometry.total_bytes != accepts_end
        || [
            geometry.total_bytes,
            geometry.assertions_offset,
            geometry.signatures_offset,
            geometry.byte_classes_offset,
            geometry.boundary_map_offset,
            geometry.start_states_offset,
            geometry.transitions_offset,
            geometry.accept_counts_offset,
            geometry.group_count,
            geometry.assertion_count,
            geometry.signature_count,
            geometry.alphabet_len,
            geometry.state_count,
            geometry.transition_count,
        ]
        .iter()
        .any(|&value| u32::try_from(value).is_err())
    {
        return Err(ObjectError::InvalidModule(
            "native participation geometry does not close",
        ));
    }
    Ok(())
}

fn validate_ordered_nfa_participation_geometry(
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<(), ObjectError> {
    use crate::participation_aot::{
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES, NativeParticipationPlanKindV1,
    };
    let frontier_bytes = geometry
        .state_count
        .checked_mul(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation frontier",
        ))?;
    let expected_next = frontier_bytes;
    let expected_stack = expected_next.checked_add(frontier_bytes).ok_or(
        ObjectError::ArithmeticOverflow("ordered-NFA participation stack"),
    )?;
    let expected_seen = expected_stack.checked_add(frontier_bytes).ok_or(
        ObjectError::ArithmeticOverflow("ordered-NFA participation seen"),
    )?;
    let seen_bytes = geometry
        .state_count
        .checked_mul(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_SEEN_BYTES)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation seen",
        ))?;
    let expected_scratch = expected_seen
        .checked_add(seen_bytes)
        .and_then(|bytes| bytes.checked_add(7))
        .map(|bytes| bytes & !7)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation scratch",
        ))?;
    let expected_states = crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES
        .checked_add(NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES)
        .and_then(|bytes| bytes.checked_add(7))
        .map(|bytes| bytes & !7)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation states",
        ))?;
    let states_bytes = geometry
        .state_count
        .checked_mul(NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation states",
        ))?;
    let expected_ranges = expected_states
        .checked_add(states_bytes)
        .and_then(|bytes| bytes.checked_add(7))
        .map(|bytes| bytes & !7)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation ranges",
        ))?;
    let ranges_bytes = geometry
        .ordered_nfa_byte_range_count
        .checked_mul(NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES)
        .ok_or(ObjectError::ArithmeticOverflow(
            "ordered-NFA participation ranges",
        ))?;
    let expected_total = expected_ranges.checked_add(ranges_bytes).ok_or(
        ObjectError::ArithmeticOverflow("ordered-NFA participation plan"),
    )?;
    let fallback_closes = matches!(
        geometry.dfa_fallback_resource,
        Some(
            crate::NativeParticipationAotResourceV1::DfaStates
                | crate::NativeParticipationAotResourceV1::BuildWork
        )
    ) && geometry.dfa_fallback_limit.checked_add(1)
        == Some(geometry.dfa_fallback_required);
    if geometry.kind != NativeParticipationPlanKindV1::OrderedNfa
        || geometry.total_bytes != expected_total
        || geometry.build_work == 0
        || geometry.group_count == 0
        || geometry.group_count > 64
        || geometry.assertion_count > 2
        || geometry.signature_count != 0
        || geometry.alphabet_len != 0
        || geometry.state_count == 0
        || geometry.transition_count != 0
        || usize::try_from(geometry.ordered_nfa_start_state)
            .ok()
            .is_none_or(|start| start >= geometry.state_count)
        || geometry.ordered_nfa_metadata_offset
            != crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES
        || geometry.ordered_nfa_states_offset != expected_states
        || geometry.ordered_nfa_byte_ranges_offset != expected_ranges
        || geometry.replay_current_offset != 0
        || geometry.replay_next_offset != expected_next
        || geometry.replay_stack_offset != expected_stack
        || geometry.replay_seen_offset != expected_seen
        || geometry.replay_scratch_bytes != expected_scratch
        || geometry.replay_scratch_bytes == 0
        || !geometry.replay_scratch_bytes.is_multiple_of(8)
        || !fallback_closes
        || [
            geometry.total_bytes,
            geometry.build_work,
            geometry.group_count,
            geometry.assertion_count,
            geometry.state_count,
            geometry.ordered_nfa_byte_range_count,
            geometry.ordered_nfa_metadata_offset,
            geometry.ordered_nfa_states_offset,
            geometry.ordered_nfa_byte_ranges_offset,
            geometry.replay_current_offset,
            geometry.replay_next_offset,
            geometry.replay_stack_offset,
            geometry.replay_seen_offset,
            geometry.replay_scratch_bytes,
            geometry.dfa_fallback_required,
            geometry.dfa_fallback_limit,
        ]
        .iter()
        .any(|&value| u32::try_from(value).is_err())
    {
        return Err(ObjectError::InvalidModule(
            "ordered-NFA participation geometry does not close",
        ));
    }
    Ok(())
}

fn aarch64_native_participation_alignment_mask(
    destination: u8,
    source: u8,
) -> Result<u32, ObjectError> {
    let alignment = crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_ALIGN;
    if alignment != 8 {
        return Err(ObjectError::InvalidModule(
            "native participation ABI alignment",
        ));
    }
    // `aarch64_and_low_x` accepts a low-bit count, so log2(8) encodes the
    // required 0x7 mask for request, scratch, and count pointers.
    let low_bits = u8::try_from(alignment.trailing_zeros())
        .map_err(|_| ObjectError::ArithmeticOverflow("native participation alignment"))?;
    aarch64_and_low_x(destination, source, low_bits)
}

fn aarch64_emit_participation_boundary_signature(
    assembler: &mut Aarch64Assembler,
    plan: u8,
    position: u8,
    haystack_len: u8,
    destination: u8,
    temporary: u8,
    boundary_map_offset: usize,
) -> Result<(), ObjectError> {
    let not_start = assembler.label()?;
    let not_end = assembler.label()?;
    aarch64_load_u32_constant(assembler, destination, 0)?;
    assembler.instruction(aarch64_cmp_x_imm(position, 0)?)?;
    assembler.branch_cond(AARCH64_NE, not_start)?;
    aarch64_load_u32_constant(assembler, temporary, 1)?;
    assembler.instruction(aarch64_add_w_reg(destination, destination, temporary)?)?;
    assembler.bind(not_start)?;
    assembler.instruction(aarch64_cmp_x(position, haystack_len)?)?;
    assembler.branch_cond(AARCH64_NE, not_end)?;
    aarch64_load_u32_constant(assembler, temporary, 2)?;
    assembler.instruction(aarch64_add_w_reg(destination, destination, temporary)?)?;
    assembler.bind(not_end)?;
    aarch64_load_u64_constant(
        assembler,
        temporary,
        u64::try_from(boundary_map_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation boundary map"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(temporary, plan, temporary)?)?;
    assembler.instruction(aarch64_load_byte_reg(destination, temporary, destination)?)?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "complete request, object geometry, exact-span loop, and transactional return form one native leaf"
)]
fn lower_aarch64_native_participation_v1(
    target: Target,
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<Aarch64NativeParticipationLowering, ObjectError> {
    validate_native_participation_geometry(geometry)?;
    const FRAME_BYTES: u16 = 80;
    let mut assembler = Aarch64Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let loop_head = assembler.label()?;
    let accept = assembler.label()?;
    let returned = assembler.label()?;

    assembler.branch_zero_x(0, invalid_before_frame)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(8, 0)?)?;
    assembler.branch_nonzero_x(8, invalid_before_frame)?;
    assembler.instruction(aarch64_add_x_imm(8, 0, 64)?)?;
    assembler.instruction(aarch64_cmp_x(8, 0)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_before_frame)?;
    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
    ] {
        assembler.instruction(aarch64_store_pair_x(first, second, 31, offset)?)?;
    }
    let plan_page_relocation_offset = assembler.instruction(0x9000_0013)?; // adrp x19, bundle
    let plan_page_offset_relocation_offset =
        assembler.instruction(aarch64_add_x_imm(19, 19, 0)?)?;

    assembler.instruction(aarch64_load_x_imm(8, 0, 0)?)?;
    assembler.instruction(aarch64_cmp_x(8, 19)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_load_x_imm(20, 0, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(21, 0, 16)?)?;
    assembler.instruction(aarch64_load_x_imm(22, 0, 24)?)?;
    assembler.instruction(aarch64_load_x_imm(23, 0, 32)?)?;
    assembler.instruction(aarch64_load_x_imm(24, 0, 40)?)?;
    assembler.instruction(aarch64_load_x_imm(8, 0, 48)?)?;
    assembler.instruction(aarch64_load_x_imm(25, 0, 56)?)?;
    assembler.branch_zero_x(20, invalid)?;
    assembler.instruction(aarch64_cmp_x(22, 23)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_zero_x(24, invalid)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(9, 24)?)?;
    assembler.branch_nonzero_x(9, invalid)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        u64::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation scratch"))?,
    )?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.branch_zero_x(25, invalid)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(9, 25)?)?;
    assembler.branch_nonzero_x(9, invalid)?;
    assembler.instruction(aarch64_add_x_reg(9, 20, 21)?)?;
    assembler.instruction(aarch64_cmp_x(9, 20)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_add_x_imm(
        9,
        24,
        u16::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation scratch"))?,
    )?)?;
    assembler.instruction(aarch64_cmp_x(9, 24)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_add_x_imm(9, 25, 8)?)?;
    assembler.instruction(aarch64_cmp_x(9, 25)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;

    // Authenticate the immutable bundle header and every code-addressed
    // geometry word before reading the haystack. Reserved scratch is never
    // read or written.
    assembler.instruction(aarch64_load_x_imm(8, 19, 0)?)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        u64::from_le_bytes(crate::NATIVE_PARTICIPATION_AOT_V1_MAGIC),
    )?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    assembler.instruction(aarch64_load_w_imm(8, 19, 8)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        9,
        (u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation header"))?
            << 16)
            | u32::from(crate::NATIVE_PARTICIPATION_AOT_V1_ABI_VERSION),
    )?;
    assembler.instruction(aarch64_cmp_w(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    assembler.instruction(aarch64_load_w_imm(8, 19, 12)?)?;
    aarch64_load_u32_constant(&mut assembler, 9, 3)?;
    assembler.instruction(aarch64_cmp_w(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    assembler.instruction(aarch64_load_x_imm(8, 19, 16)?)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        u64::try_from(geometry.total_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation bytes"))?,
    )?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    assembler.instruction(aarch64_load_x_imm(8, 19, 24)?)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        crate::NATIVE_PARTICIPATION_AOT_V1_READY_SEAL,
    )?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    for (offset, expected) in [
        (32_u16, native_participation_target_word(target)?),
        (
            36,
            u32::try_from(target.features.bits())
                .map_err(|_| ObjectError::ArithmeticOverflow("participation features"))?,
        ),
        (
            40,
            u32::from(crate::NativeParticipationAotStrategyV1::DfaAarch64 as u16),
        ),
    ] {
        assembler.instruction(aarch64_load_w_imm(8, 19, offset)?)?;
        aarch64_load_u32_constant(&mut assembler, 9, expected)?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    }
    for (offset, expected) in [
        (
            44_u16,
            u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation scratch"))?,
        ),
        (48, u32::try_from(geometry.group_count).unwrap()),
        (52, u32::try_from(geometry.assertion_count).unwrap()),
        (56, u32::try_from(geometry.signature_count).unwrap()),
        (60, u32::try_from(geometry.alphabet_len).unwrap()),
        (64, u32::try_from(geometry.state_count).unwrap()),
        (68, u32::try_from(geometry.transition_count).unwrap()),
    ] {
        assembler.instruction(aarch64_load_w_imm(8, 19, offset)?)?;
        aarch64_load_u32_constant(&mut assembler, 9, expected)?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    }
    for (offset, expected) in [
        (72_u16, geometry.build_work),
        (80, geometry.signatures_offset),
        (88, geometry.byte_classes_offset),
        (96, geometry.boundary_map_offset),
        (104, geometry.start_states_offset),
        (112, geometry.transitions_offset),
        (120, geometry.accept_counts_offset),
    ] {
        assembler.instruction(aarch64_load_x_imm(8, 19, offset)?)?;
        aarch64_load_u64_constant(
            &mut assembler,
            9,
            u64::try_from(expected)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation offset"))?,
        )?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    }

    assembler.instruction(aarch64_mov_x(27, 22)?)?;
    aarch64_emit_participation_boundary_signature(
        &mut assembler,
        19,
        27,
        21,
        8,
        9,
        geometry.boundary_map_offset,
    )?;
    aarch64_load_u32_constant(
        &mut assembler,
        9,
        u32::try_from(geometry.signature_count).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(8, 9)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        u64::try_from(geometry.start_states_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation starts"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(9, 19, 9)?)?;
    assembler.instruction(aarch64_load_w_uxtw(26, 9, 8)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.state_count).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(26, 8)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    aarch64_load_u64_constant(
        &mut assembler,
        28,
        u64::try_from(geometry.transitions_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation transitions"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(28, 19, 28)?)?;

    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_cmp_x(27, 23)?)?;
    assembler.branch_cond(AARCH64_EQ, accept)?;
    assembler.instruction(aarch64_load_byte_reg(8, 20, 27)?)?;
    aarch64_load_u64_constant(
        &mut assembler,
        9,
        u64::try_from(geometry.byte_classes_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation byte classes"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(9, 19, 9)?)?;
    assembler.instruction(aarch64_load_byte_reg(10, 9, 8)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.alphabet_len).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(10, 8)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.instruction(aarch64_add_x_imm(27, 27, 1)?)?;
    aarch64_emit_participation_boundary_signature(
        &mut assembler,
        19,
        27,
        21,
        11,
        12,
        geometry.boundary_map_offset,
    )?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.signature_count).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(11, 8)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.alphabet_len).unwrap(),
    )?;
    assembler.instruction(aarch64_madd_w(10, 26, 8, 10)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.signature_count).unwrap(),
    )?;
    assembler.instruction(aarch64_madd_w(10, 10, 8, 11)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.transition_count).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(10, 8)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.instruction(aarch64_load_w_uxtw(26, 28, 10)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        8,
        u32::try_from(geometry.state_count).unwrap(),
    )?;
    assembler.instruction(aarch64_cmp_w(26, 8)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(loop_head)?;

    assembler.bind(accept)?;
    aarch64_load_u64_constant(
        &mut assembler,
        8,
        u64::try_from(geometry.accept_counts_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation accepts"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(8, 19, 8)?)?;
    assembler.instruction(aarch64_load_byte_reg(8, 8, 26)?)?;
    assembler.instruction(aarch64_cmp_w_imm(8, 255)?)?;
    assembler.branch_cond(AARCH64_EQ, runtime_failure)?;
    assembler.instruction(aarch64_cmp_w_imm(
        8,
        u16::try_from(geometry.group_count)
            .map_err(|_| ObjectError::ArithmeticOverflow("participation groups"))?,
    )?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.branch_zero_w(8, runtime_failure)?;
    assembler.instruction(aarch64_store_x(8, 25, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.branch(returned)?;
    assembler.bind(returned)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
    ] {
        assembler.instruction(aarch64_load_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(invalid_before_frame)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut relocation_offsets = [
        plan_page_relocation_offset,
        plan_page_offset_relocation_offset,
    ];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    Ok(Aarch64NativeParticipationLowering {
        code,
        plan_page_relocation_offset: relocation_offsets[0],
        plan_page_offset_relocation_offset: relocation_offsets[1],
    })
}

fn x86_ordered_nfa_compare_plan_u32(
    assembler: &mut X86Assembler,
    offset: u8,
    expected: u32,
    failed: X86Label,
) -> Result<(), ObjectError> {
    let mut instruction = vec![0x41, 0x81, 0x7f, offset];
    instruction.extend_from_slice(&expected.to_le_bytes());
    assembler.instruction(&instruction)?;
    assembler.branch(&[0x0f, 0x85], failed)?;
    Ok(())
}

fn x86_ordered_nfa_compare_plan_u64(
    assembler: &mut X86Assembler,
    offset: u8,
    expected: usize,
    failed: X86Label,
) -> Result<(), ObjectError> {
    let mut constant = vec![0x48, 0xb8];
    constant.extend_from_slice(
        &u64::try_from(expected)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA plan field"))?
            .to_le_bytes(),
    );
    assembler.instruction(&constant)?;
    assembler.instruction(&[0x49, 0x39, 0x47, offset])?;
    assembler.branch(&[0x0f, 0x85], failed)?;
    Ok(())
}

fn x86_ordered_nfa_compare_metadata_u64(
    assembler: &mut X86Assembler,
    offset: u8,
    expected: u64,
    failed: X86Label,
) -> Result<(), ObjectError> {
    let mut constant = vec![0x48, 0xb8];
    constant.extend_from_slice(&expected.to_le_bytes());
    assembler.instruction(&constant)?;
    if offset == 0 {
        assembler.instruction(&[0x49, 0x39, 0x02])?;
    } else {
        assembler.instruction(&[0x49, 0x39, 0x42, offset])?;
    }
    assembler.branch(&[0x0f, 0x85], failed)?;
    Ok(())
}

/// Push `(eax, rdx, rcx)` onto the ordered-NFA closure stack. The internal
/// closure keeps its stack cardinality in `r11`; only `r8/r9` are temporary.
fn x86_ordered_nfa_push_thread(
    assembler: &mut X86Assembler,
    state_count: u32,
    stack_pointer_offset: u8,
    failed: X86Label,
) -> Result<(), ObjectError> {
    let mut bound = vec![0x49, 0x81, 0xfb];
    bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&bound)?;
    assembler.branch(&[0x0f, 0x83], failed)?;
    assembler.instruction(&[0x4d, 0x6b, 0xc3, 24])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, stack_pointer_offset])?;
    assembler.instruction(&[0x4d, 0x01, 0xc1])?;
    assembler.instruction(&[0x41, 0x89, 0x01])?;
    assembler.instruction(&[0x41, 0xc7, 0x41, 4, 0, 0, 0, 0])?;
    assembler.instruction(&[0x49, 0x89, 0x51, 8])?;
    assembler.instruction(&[0x49, 0x89, 0x49, 16])?;
    assembler.instruction(&[0x49, 0xff, 0xc3])?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "the authenticated ordered-NFA request, closure, and exact-span replay are one helper-free leaf"
)]
fn lower_x86_64_ordered_nfa_participation_v1(
    target: Target,
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<X86NativeParticipationLowering, ObjectError> {
    validate_ordered_nfa_participation_geometry(geometry)?;
    use crate::participation_aot::{
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_ASSERT,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_EPSILON,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_FAIL,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SAVE,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SPLIT,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_MAGIC,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_VERSION,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES,
    };
    const FRAME_BYTES: u32 = 104;
    const SCRATCH_POINTER: u8 = 0;
    const COUNT_POINTER: u8 = 8;
    const CURRENT_POINTER: u8 = 16;
    const NEXT_POINTER: u8 = 24;
    const STACK_POINTER: u8 = 32;
    const SEEN_POINTER: u8 = 40;
    const CURRENT_COUNT: u8 = 48;
    const NEXT_COUNT: u8 = 56;
    const GENERATION: u8 = 64;
    const STATES_POINTER: u8 = 72;
    const RANGES_POINTER: u8 = 80;
    const TARGET_PC: u8 = 88;
    const SCRATCH_END: u8 = 96;
    // A local `call` pushes one return address before the closure sees these.
    const CLOSURE_STACK_POINTER: u8 = STACK_POINTER + 8;
    const CLOSURE_SEEN_POINTER: u8 = SEEN_POINTER + 8;
    const CLOSURE_GENERATION: u8 = GENERATION + 8;
    const CLOSURE_STATES_POINTER: u8 = STATES_POINTER + 8;

    let state_count = u32::try_from(geometry.state_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA states"))?;
    let range_count = u32::try_from(geometry.ordered_nfa_byte_range_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA ranges"))?;
    let group_count = u32::try_from(geometry.group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA groups"))?;
    let slot_count = group_count
        .checked_mul(2)
        .ok_or(ObjectError::ArithmeticOverflow("ordered-NFA slots"))?;
    let fallback_resource = match geometry.dfa_fallback_resource {
        Some(crate::NativeParticipationAotResourceV1::DfaStates) => 1_u64,
        Some(crate::NativeParticipationAotResourceV1::BuildWork) => 2_u64,
        _ => {
            return Err(ObjectError::InvalidModule(
                "ordered-NFA fallback resource",
            ));
        }
    };

    let mut assembler = X86Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let replay_loop = assembler.label()?;
    let generation_ready = assembler.label()?;
    let clear_seen = assembler.label()?;
    let clear_seen_loop = assembler.label()?;
    let thread_loop = assembler.label()?;
    let next_thread = assembler.label()?;
    let range_loop = assembler.label()?;
    let range_next = assembler.label()?;
    let byte_matched = assembler.label()?;
    let swap_frontiers = assembler.label()?;
    let accept_loop = assembler.label()?;
    let accept_match = assembler.label()?;
    let popcount_loop = assembler.label()?;
    let popcount_done = assembler.label()?;
    let closure = assembler.label()?;
    let closure_loop = assembler.label()?;
    let closure_append = assembler.label()?;
    let closure_epsilon = assembler.label()?;
    let closure_assert = assembler.label()?;
    let closure_assert_start = assembler.label()?;
    let closure_assert_end = assembler.label()?;
    let closure_save = assembler.label()?;
    let closure_save_close = assembler.label()?;
    let closure_split = assembler.label()?;
    let closure_done = assembler.label()?;
    let closure_failure = assembler.label()?;
    let scratch_haystack_disjoint = assembler.label()?;
    let scratch_request_disjoint = assembler.label()?;
    let scratch_count_disjoint = assembler.label()?;
    let scratch_plan_disjoint = assembler.label()?;

    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid_before_frame)?;
    assembler.instruction(&[0x40, 0xf6, 0xc7, 7])?;
    assembler.branch(&[0x0f, 0x85], invalid_before_frame)?;
    assembler.instruction(&[0x48, 0x89, 0xf8])?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 64])?;
    assembler.branch(&[0x0f, 0x82], invalid_before_frame)?;

    for instruction in [
        &[0x55][..],
        &[0x53],
        &[0x41, 0x54],
        &[0x41, 0x55],
        &[0x41, 0x56],
        &[0x41, 0x57],
    ] {
        assembler.instruction(instruction)?;
    }
    let mut reserve = vec![0x48, 0x81, 0xec];
    reserve.extend_from_slice(&FRAME_BYTES.to_le_bytes());
    assembler.instruction(&reserve)?;
    assembler.instruction(&[0x4c, 0x8d, 0x3d])?;
    let plan_relocation = assembler.label()?;
    assembler.bind(plan_relocation)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.instruction(&[0x48, 0x8b, 0x07])?;
    assembler.instruction(&[0x4c, 0x39, 0xf8])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x8b, 0x5f, 8])?;
    assembler.instruction(&[0x4c, 0x8b, 0x67, 16])?;
    assembler.instruction(&[0x4c, 0x8b, 0x6f, 24])?;
    assembler.instruction(&[0x4c, 0x8b, 0x77, 32])?;
    assembler.instruction(&[0x4c, 0x8b, 0x47, 40])?;
    assembler.instruction(&[0x48, 0x8b, 0x47, 48])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4f, 56])?;
    assembler.instruction(&[0x4c, 0x89, 0x04, 0x24])?;
    assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, COUNT_POINTER])?;

    assembler.instruction(&[0x48, 0x85, 0xdb])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xf5])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xe6])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 7])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut scratch_bound = vec![0x48, 0x3d];
    scratch_bound.extend_from_slice(
        &u32::try_from(geometry.replay_scratch_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?
            .to_le_bytes(),
    );
    assembler.instruction(&scratch_bound)?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc1, 7])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    for (load, add) in [
        (&[0x48, 0x89, 0xd9][..], &[0x4c, 0x01, 0xe1][..]),
        (&[0x4c, 0x89, 0xc1][..], &[0x48, 0x01, 0xc1][..]),
        (&[0x4c, 0x89, 0xc9][..], &[0x48, 0x83, 0xc1, 8][..]),
    ] {
        assembler.instruction(load)?;
        assembler.instruction(add)?;
        assembler.branch(&[0x0f, 0x82], invalid)?;
    }

    assembler.instruction(&[0x4c, 0x89, 0xc1])?;
    assembler.instruction(&[0x48, 0x01, 0xc1])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, SCRATCH_END])?;
    assembler.instruction(&[0x4d, 0x85, 0xe4])?;
    assembler.branch(&[0x0f, 0x84], scratch_haystack_disjoint)?;
    assembler.instruction(&[0x48, 0x89, 0xda])?;
    assembler.instruction(&[0x4c, 0x01, 0xe2])?;
    assembler.instruction(&[0x49, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x83], scratch_haystack_disjoint)?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, SCRATCH_END])?;
    assembler.instruction(&[0x48, 0x39, 0xcb])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_haystack_disjoint)?;
    assembler.instruction(&[0x48, 0x8d, 0x57, 64])?;
    assembler.instruction(&[0x49, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x83], scratch_request_disjoint)?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, SCRATCH_END])?;
    assembler.instruction(&[0x48, 0x39, 0xcf])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_request_disjoint)?;
    assembler.instruction(&[0x49, 0x8d, 0x51, 8])?;
    assembler.instruction(&[0x49, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x83], scratch_count_disjoint)?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, SCRATCH_END])?;
    assembler.instruction(&[0x49, 0x39, 0xc9])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_count_disjoint)?;
    let mut plan_bytes = vec![0x48, 0xb9];
    plan_bytes.extend_from_slice(
        &u64::try_from(geometry.total_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA plan bytes"))?
            .to_le_bytes(),
    );
    assembler.instruction(&plan_bytes)?;
    assembler.instruction(&[0x4c, 0x89, 0xfa])?;
    assembler.instruction(&[0x48, 0x01, 0xca])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.instruction(&[0x49, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x83], scratch_plan_disjoint)?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, SCRATCH_END])?;
    assembler.instruction(&[0x49, 0x39, 0xcf])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_plan_disjoint)?;

    let mut magic = vec![0x48, 0xb8];
    magic.extend_from_slice(
        &u64::from_le_bytes(crate::NATIVE_PARTICIPATION_AOT_V1_MAGIC).to_le_bytes(),
    );
    assembler.instruction(&magic)?;
    assembler.instruction(&[0x49, 0x39, 0x07])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    let header_word = (u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA header"))?
        << 16)
        | u32::from(crate::NATIVE_PARTICIPATION_AOT_V1_ABI_VERSION);
    for (offset, expected) in [
        (8, header_word),
        (12, 7),
        (32, native_participation_target_word(target)?),
        (
            36,
            u32::try_from(target.features.bits())
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA features"))?,
        ),
        (
            40,
            u32::from(crate::NativeParticipationAotStrategyV1::OrderedNfaX86_64 as u16),
        ),
        (
            44,
            u32::try_from(geometry.replay_scratch_bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?,
        ),
        (48, group_count),
        (
            52,
            u32::try_from(geometry.assertion_count)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA assertions"))?,
        ),
        (56, 0),
        (60, 0),
        (64, state_count),
        (68, range_count),
    ] {
        x86_ordered_nfa_compare_plan_u32(&mut assembler, offset, expected, runtime_failure)?;
    }
    for (offset, expected) in [
        (16, geometry.total_bytes),
        (
            24,
            usize::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_READY_SEAL)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA seal"))?,
        ),
        (72, geometry.build_work),
        (80, geometry.ordered_nfa_metadata_offset),
        (88, geometry.ordered_nfa_states_offset),
        (96, geometry.ordered_nfa_byte_ranges_offset),
        (104, geometry.replay_current_offset),
        (112, geometry.replay_next_offset),
        (120, geometry.replay_stack_offset),
    ] {
        x86_ordered_nfa_compare_plan_u64(&mut assembler, offset, expected, runtime_failure)?;
    }

    let metadata_offset = i32::try_from(geometry.ordered_nfa_metadata_offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA metadata"))?;
    let mut metadata = vec![0x4d, 0x8d, 0x97];
    metadata.extend_from_slice(&metadata_offset.to_le_bytes());
    assembler.instruction(&metadata)?;
    x86_ordered_nfa_compare_metadata_u64(
        &mut assembler,
        0,
        u64::from_le_bytes(NATIVE_PARTICIPATION_ORDERED_NFA_V1_MAGIC),
        runtime_failure,
    )?;
    let metadata_shape = u64::from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_VERSION)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA metadata"))?
            << 16)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA state width"))?
            << 32)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA range width"))?
            << 48);
    x86_ordered_nfa_compare_metadata_u64(
        &mut assembler,
        8,
        metadata_shape,
        runtime_failure,
    )?;
    x86_ordered_nfa_compare_metadata_u64(
        &mut assembler,
        16,
        fallback_resource,
        runtime_failure,
    )?;
    for (offset, expected) in [
        (
            24,
            u64::try_from(geometry.dfa_fallback_required)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA fallback"))?,
        ),
        (
            32,
            u64::try_from(geometry.dfa_fallback_limit)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA fallback"))?,
        ),
        (
            40,
            u64::from(geometry.ordered_nfa_start_state) | (u64::from(state_count) << 32),
        ),
        (48, u64::from(range_count) | (u64::from(group_count) << 32)),
        (
            56,
            u64::try_from(geometry.ordered_nfa_states_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA states"))?,
        ),
        (
            64,
            u64::try_from(geometry.ordered_nfa_byte_ranges_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA ranges"))?,
        ),
        (72, 0),
        (
            80,
            u64::try_from(geometry.replay_next_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA next"))?,
        ),
        (
            88,
            u64::try_from(geometry.replay_stack_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA stack"))?,
        ),
        (
            96,
            u64::try_from(geometry.replay_seen_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA seen"))?,
        ),
        (
            104,
            u64::try_from(geometry.replay_scratch_bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?,
        ),
    ] {
        x86_ordered_nfa_compare_metadata_u64(
            &mut assembler,
            offset,
            expected,
            runtime_failure,
        )?;
    }

    for (offset, displacement, site) in [
        (
            CURRENT_POINTER,
            geometry.replay_current_offset,
            "ordered-NFA current",
        ),
        (NEXT_POINTER, geometry.replay_next_offset, "ordered-NFA next"),
        (
            STACK_POINTER,
            geometry.replay_stack_offset,
            "ordered-NFA stack",
        ),
        (SEEN_POINTER, geometry.replay_seen_offset, "ordered-NFA seen"),
    ] {
        let mut address = vec![0x4d, 0x8d, 0x90];
        address.extend_from_slice(
            &i32::try_from(displacement)
                .map_err(|_| ObjectError::ArithmeticOverflow(site))?
                .to_le_bytes(),
        );
        assembler.instruction(&address)?;
        assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, offset])?;
    }
    for (offset, displacement, site) in [
        (
            STATES_POINTER,
            geometry.ordered_nfa_states_offset,
            "ordered-NFA states",
        ),
        (
            RANGES_POINTER,
            geometry.ordered_nfa_byte_ranges_offset,
            "ordered-NFA ranges",
        ),
    ] {
        let mut address = vec![0x4d, 0x8d, 0x97];
        address.extend_from_slice(
            &i32::try_from(displacement)
                .map_err(|_| ObjectError::ArithmeticOverflow(site))?
                .to_le_bytes(),
        );
        assembler.instruction(&address)?;
        assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, offset])?;
    }

    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, SEEN_POINTER])?;
    assembler.instruction(&[0x31, 0xc0])?;
    let mut seen_count = vec![0xb9];
    seen_count.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&seen_count)?;
    assembler.instruction(&[0xf3, 0xab])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, CURRENT_COUNT, 0, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, NEXT_COUNT, 0, 0, 0, 0])?;
    assembler.instruction(&[0xc7, 0x44, 0x24, GENERATION, 1, 0, 0, 0])?;
    let mut start_pc = vec![0xb8];
    start_pc.extend_from_slice(&geometry.ordered_nfa_start_state.to_le_bytes());
    assembler.instruction(&start_pc)?;
    assembler.instruction(&[0x31, 0xd2])?;
    assembler.instruction(&[0x31, 0xc9])?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, CURRENT_POINTER])?;
    assembler.instruction(&[0x48, 0x8d, 0x74, 0x24, CURRENT_COUNT])?;
    assembler.branch(&[0xe8], closure)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;

    assembler.bind(replay_loop)?;
    assembler.instruction(&[0x4d, 0x39, 0xf5])?;
    assembler.branch(&[0x0f, 0x84], accept_loop)?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, NEXT_COUNT, 0, 0, 0, 0])?;
    assembler.instruction(&[0x8b, 0x44, 0x24, GENERATION])?;
    assembler.instruction(&[0x83, 0xc0, 1])?;
    assembler.instruction(&[0x89, 0x44, 0x24, GENERATION])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], generation_ready)?;
    assembler.branch(&[0xe9], clear_seen)?;

    assembler.bind(clear_seen)?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, SEEN_POINTER])?;
    let mut seen_count = vec![0xb9];
    seen_count.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&seen_count)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.bind(clear_seen_loop)?;
    assembler.instruction(&[0xf3, 0xab])?;
    assembler.instruction(&[0xc7, 0x44, 0x24, GENERATION, 1, 0, 0, 0])?;
    assembler.bind(generation_ready)?;
    assembler.instruction(&[0x48, 0x31, 0xed])?;

    assembler.bind(thread_loop)?;
    assembler.instruction(&[0x48, 0x3b, 0x6c, 0x24, CURRENT_COUNT])?;
    assembler.branch(&[0x0f, 0x83], swap_frontiers)?;
    assembler.instruction(&[0x4c, 0x6b, 0xc5, 24])?;
    assembler.instruction(&[0x4c, 0x03, 0x44, 0x24, CURRENT_POINTER])?;
    assembler.instruction(&[0x41, 0x8b, 0x00])?;
    assembler.instruction(&[0x49, 0x8b, 0x50, 8])?;
    assembler.instruction(&[0x49, 0x8b, 0x48, 16])?;
    let mut pc_bound = vec![0x3d];
    pc_bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&pc_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, STATES_POINTER])?;
    assembler.instruction(&[0x49, 0xc1, 0xe0, 4])?;
    assembler.instruction(&[0x4d, 0x01, 0xc2])?;
    assembler.instruction(&[0x45, 0x0f, 0xb6, 0x1a])?;
    assembler.instruction(&[0x41, 0x83, 0xfb, NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH])?;
    assembler.branch(&[0x0f, 0x84], next_thread)?;
    assembler.instruction(&[0x41, 0x83, 0xfb, NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    assembler.instruction(&[0x41, 0x8b, 0x42, 4])?;
    assembler.instruction(&[0x89, 0x44, 0x24, TARGET_PC])?;
    assembler.instruction(&[0x45, 0x8b, 0x42, 8])?;
    assembler.instruction(&[0x45, 0x8b, 0x4a, 12])?;
    assembler.instruction(&[0x45, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.instruction(&[0x45, 0x89, 0xcb])?;
    assembler.instruction(&[0x45, 0x01, 0xc3])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    let mut range_bound = vec![0x41, 0x81, 0xfb];
    range_bound.extend_from_slice(&range_count.to_le_bytes());
    assembler.instruction(&range_bound)?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;

    assembler.bind(range_loop)?;
    assembler.instruction(&[0x45, 0x39, 0xd8])?;
    assembler.branch(&[0x0f, 0x83], next_thread)?;
    assembler.instruction(&[0x4c, 0x89, 0xc0])?;
    assembler.instruction(&[0x48, 0x01, 0xc0])?;
    assembler.instruction(&[0x48, 0x03, 0x44, 0x24, RANGES_POINTER])?;
    assembler.instruction(&[0x46, 0x0f, 0xb6, 0x1c, 0x2b])?;
    assembler.instruction(&[0x44, 0x0f, 0xb6, 0x10])?;
    assembler.instruction(&[0x45, 0x39, 0xd3])?;
    assembler.branch(&[0x0f, 0x82], range_next)?;
    assembler.instruction(&[0x44, 0x0f, 0xb6, 0x50, 1])?;
    assembler.instruction(&[0x45, 0x39, 0xd3])?;
    assembler.branch(&[0x0f, 0x86], byte_matched)?;
    assembler.bind(range_next)?;
    assembler.instruction(&[0x41, 0x83, 0xc0, 1])?;
    assembler.branch(&[0xe9], range_loop)?;

    assembler.bind(byte_matched)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, TARGET_PC])?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, NEXT_POINTER])?;
    assembler.instruction(&[0x48, 0x8d, 0x74, 0x24, NEXT_COUNT])?;
    assembler.branch(&[0xe8], closure)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    assembler.bind(next_thread)?;
    assembler.instruction(&[0x48, 0x83, 0xc5, 1])?;
    assembler.branch(&[0xe9], thread_loop)?;

    assembler.bind(swap_frontiers)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, CURRENT_POINTER])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, NEXT_POINTER])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, CURRENT_POINTER])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, NEXT_POINTER])?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, NEXT_COUNT])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, CURRENT_COUNT])?;
    assembler.instruction(&[0x49, 0x83, 0xc5, 1])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.branch(&[0xe9], replay_loop)?;

    assembler.bind(accept_loop)?;
    assembler.instruction(&[0x48, 0x31, 0xed])?;
    let accept_scan = assembler.label()?;
    assembler.bind(accept_scan)?;
    assembler.instruction(&[0x48, 0x3b, 0x6c, 0x24, CURRENT_COUNT])?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x4c, 0x6b, 0xc5, 24])?;
    assembler.instruction(&[0x4c, 0x03, 0x44, 0x24, CURRENT_POINTER])?;
    assembler.instruction(&[0x41, 0x8b, 0x00])?;
    assembler.instruction(&[0x49, 0x8b, 0x50, 8])?;
    assembler.instruction(&[0x49, 0x8b, 0x48, 16])?;
    assembler.instruction(&[0x3d])?;
    push_bytes(&mut assembler.code, &state_count.to_le_bytes())?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, STATES_POINTER])?;
    assembler.instruction(&[0x49, 0xc1, 0xe0, 4])?;
    assembler.instruction(&[0x4d, 0x01, 0xc2])?;
    assembler.instruction(&[0x41, 0x80, 0x3a, NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH])?;
    assembler.branch(&[0x0f, 0x84], accept_match)?;
    assembler.instruction(&[0x48, 0x83, 0xc5, 1])?;
    assembler.branch(&[0xe9], accept_scan)?;

    assembler.bind(accept_match)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    assembler.instruction(&[0xf6, 0xc1, 1])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x31, 0xd2])?;
    assembler.bind(popcount_loop)?;
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], popcount_done)?;
    assembler.instruction(&[0x48, 0x8d, 0x48, 0xff])?;
    assembler.instruction(&[0x48, 0x21, 0xc8])?;
    assembler.instruction(&[0x48, 0x83, 0xc2, 1])?;
    assembler.branch(&[0xe9], popcount_loop)?;
    assembler.bind(popcount_done)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    let mut group_bound = vec![0x48, 0x81, 0xfa];
    group_bound.extend_from_slice(&group_count.to_le_bytes());
    assembler.instruction(&group_bound)?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, COUNT_POINTER])?;
    assembler.instruction(&[0x48, 0x89, 0x10])?;
    assembler.instruction(&[0xb8, 1, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;

    // Internal ordered epsilon closure. `rdi/rsi` retain the selected output
    // frontier and its count pointer; `r11` is the private LIFO count.
    assembler.bind(closure)?;
    assembler.instruction(&[0x4d, 0x31, 0xdb])?;
    x86_ordered_nfa_push_thread(
        &mut assembler,
        state_count,
        CLOSURE_STACK_POINTER,
        closure_failure,
    )?;
    assembler.bind(closure_loop)?;
    assembler.instruction(&[0x4d, 0x85, 0xdb])?;
    assembler.branch(&[0x0f, 0x84], closure_done)?;
    assembler.instruction(&[0x49, 0xff, 0xcb])?;
    assembler.instruction(&[0x4d, 0x6b, 0xc3, 24])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, CLOSURE_STACK_POINTER])?;
    assembler.instruction(&[0x4d, 0x01, 0xc1])?;
    assembler.instruction(&[0x41, 0x8b, 0x01])?;
    assembler.instruction(&[0x49, 0x8b, 0x51, 8])?;
    assembler.instruction(&[0x49, 0x8b, 0x49, 16])?;
    let mut pc_bound = vec![0x3d];
    pc_bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&pc_bound)?;
    assembler.branch(&[0x0f, 0x83], closure_failure)?;
    assembler.instruction(&[0x49, 0x89, 0xc2])?;
    assembler.instruction(&[0x49, 0xc1, 0xe2, 2])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, CLOSURE_SEEN_POINTER])?;
    assembler.instruction(&[0x4d, 0x01, 0xca])?;
    assembler.instruction(&[0x44, 0x8b, 0x44, 0x24, CLOSURE_GENERATION])?;
    assembler.instruction(&[0x45, 0x39, 0x02])?;
    assembler.branch(&[0x0f, 0x84], closure_loop)?;
    assembler.instruction(&[0x45, 0x89, 0x02])?;
    assembler.instruction(&[0x49, 0x89, 0xc2])?;
    assembler.instruction(&[0x49, 0xc1, 0xe2, 4])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, CLOSURE_STATES_POINTER])?;
    assembler.instruction(&[0x4d, 0x01, 0xca])?;
    assembler.instruction(&[0x45, 0x0f, 0xb6, 0x02])?;
    for (tag, destination) in [
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE, closure_append),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH, closure_append),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_FAIL, closure_loop),
        (
            NATIVE_PARTICIPATION_ORDERED_NFA_STATE_EPSILON,
            closure_epsilon,
        ),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_ASSERT, closure_assert),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SAVE, closure_save),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SPLIT, closure_split),
    ] {
        assembler.instruction(&[0x41, 0x83, 0xf8, tag])?;
        assembler.branch(&[0x0f, 0x84], destination)?;
    }
    assembler.branch(&[0xe9], closure_failure)?;

    assembler.bind(closure_append)?;
    assembler.instruction(&[0x4c, 0x8b, 0x0e])?;
    let mut output_bound = vec![0x49, 0x81, 0xf9];
    output_bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&output_bound)?;
    assembler.branch(&[0x0f, 0x83], closure_failure)?;
    assembler.instruction(&[0x4d, 0x6b, 0xc1, 24])?;
    assembler.instruction(&[0x49, 0x01, 0xf8])?;
    assembler.instruction(&[0x41, 0x89, 0x00])?;
    assembler.instruction(&[0x41, 0xc7, 0x40, 4, 0, 0, 0, 0])?;
    assembler.instruction(&[0x49, 0x89, 0x50, 8])?;
    assembler.instruction(&[0x49, 0x89, 0x48, 16])?;
    assembler.instruction(&[0x49, 0xff, 0xc1])?;
    assembler.instruction(&[0x4c, 0x89, 0x0e])?;
    assembler.branch(&[0xe9], closure_loop)?;

    assembler.bind(closure_epsilon)?;
    assembler.instruction(&[0x41, 0x8b, 0x42, 4])?;
    x86_ordered_nfa_push_thread(
        &mut assembler,
        state_count,
        CLOSURE_STACK_POINTER,
        closure_failure,
    )?;
    assembler.branch(&[0xe9], closure_loop)?;

    assembler.bind(closure_assert)?;
    assembler.instruction(&[0x41, 0x80, 0x7a, 2, 0])?;
    assembler.branch(&[0x0f, 0x85], closure_failure)?;
    assembler.instruction(&[0x45, 0x0f, 0xb6, 0x42, 1])?;
    assembler.instruction(&[0x41, 0x83, 0xf8, 1])?;
    assembler.branch(&[0x0f, 0x84], closure_assert_start)?;
    assembler.instruction(&[0x41, 0x83, 0xf8, 2])?;
    assembler.branch(&[0x0f, 0x84], closure_assert_end)?;
    assembler.branch(&[0xe9], closure_failure)?;
    assembler.bind(closure_assert_start)?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.branch(&[0x0f, 0x85], closure_loop)?;
    assembler.branch(&[0xe9], closure_epsilon)?;
    assembler.bind(closure_assert_end)?;
    assembler.instruction(&[0x4d, 0x39, 0xe5])?;
    assembler.branch(&[0x0f, 0x85], closure_loop)?;
    assembler.branch(&[0xe9], closure_epsilon)?;

    assembler.bind(closure_save)?;
    assembler.instruction(&[0x45, 0x0f, 0xb6, 0x42, 1])?;
    let mut slot_bound = vec![0x41, 0x81, 0xf8];
    slot_bound.extend_from_slice(&slot_count.to_le_bytes());
    assembler.instruction(&slot_bound)?;
    assembler.branch(&[0x0f, 0x83], closure_failure)?;
    assembler.instruction(&[0x45, 0x89, 0xc1])?;
    assembler.instruction(&[0x41, 0xd1, 0xe9])?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 1])?;
    assembler.branch(&[0x0f, 0x85], closure_save_close)?;
    assembler.instruction(&[0x4c, 0x0f, 0xa3, 0xca])?;
    assembler.branch(&[0x0f, 0x82], closure_failure)?;
    assembler.instruction(&[0x4c, 0x0f, 0xab, 0xca])?;
    assembler.branch(&[0xe9], closure_epsilon)?;
    assembler.bind(closure_save_close)?;
    assembler.instruction(&[0x4c, 0x0f, 0xa3, 0xca])?;
    assembler.branch(&[0x0f, 0x83], closure_failure)?;
    assembler.instruction(&[0x4c, 0x0f, 0xb3, 0xca])?;
    assembler.instruction(&[0x4c, 0x0f, 0xab, 0xc9])?;
    assembler.branch(&[0xe9], closure_epsilon)?;

    assembler.bind(closure_split)?;
    assembler.instruction(&[0x41, 0x8b, 0x42, 8])?;
    x86_ordered_nfa_push_thread(
        &mut assembler,
        state_count,
        CLOSURE_STACK_POINTER,
        closure_failure,
    )?;
    assembler.instruction(&[0x41, 0x8b, 0x42, 4])?;
    x86_ordered_nfa_push_thread(
        &mut assembler,
        state_count,
        CLOSURE_STACK_POINTER,
        closure_failure,
    )?;
    assembler.branch(&[0xe9], closure_loop)?;

    assembler.bind(closure_done)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(closure_failure)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(returned)?;
    let mut release = vec![0x48, 0x81, 0xc4];
    release.extend_from_slice(&FRAME_BYTES.to_le_bytes());
    assembler.instruction(&release)?;
    for instruction in [
        &[0x41, 0x5f][..],
        &[0x41, 0x5e],
        &[0x41, 0x5d],
        &[0x41, 0x5c],
        &[0x5b],
        &[0x5d],
        &[0xc3],
    ] {
        assembler.instruction(instruction)?;
    }
    assembler.bind(invalid_before_frame)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let plan_relocation_offset = finished.label_offset(plan_relocation)?;
    Ok(X86NativeParticipationLowering {
        code: finished.code,
        plan_relocation_offset,
    })
}

fn aarch64_ordered_nfa_compare_u32(
    assembler: &mut Aarch64Assembler,
    base: u8,
    offset: u16,
    expected: u32,
    failed: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_load_w_imm(8, base, offset)?)?;
    aarch64_load_u32_constant(assembler, 9, expected)?;
    assembler.instruction(aarch64_cmp_w(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, failed)?;
    Ok(())
}

fn aarch64_ordered_nfa_compare_u64(
    assembler: &mut Aarch64Assembler,
    base: u8,
    offset: u16,
    expected: u64,
    failed: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_load_x_imm(8, base, offset)?)?;
    aarch64_load_u64_constant(assembler, 9, expected)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, failed)?;
    Ok(())
}

/// Emit one bounded ordered-NFA stack push. The closure keeps its stack
/// cardinality in `x5`; `(w0, x1, x2)` is the thread and `x25` is the
/// authenticated caller-owned stack base. Only `x6/x7` are clobbered.
fn aarch64_ordered_nfa_push_thread(
    assembler: &mut Aarch64Assembler,
    state_count: u32,
    failed: Aarch64Label,
) -> Result<(), ObjectError> {
    aarch64_load_u32_constant(assembler, 6, state_count)?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_HS, failed)?;
    aarch64_load_u32_constant(
        assembler,
        6,
        u32::try_from(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA thread width"))?,
    )?;
    assembler.instruction(aarch64_madd_x(7, 5, 6, 25)?)?;
    assembler.instruction(aarch64_store_w(0, 7, 0)?)?;
    assembler.instruction(aarch64_store_w(31, 7, 4)?)?;
    assembler.instruction(aarch64_store_x(1, 7, 8)?)?;
    assembler.instruction(aarch64_store_x(2, 7, 16)?)?;
    assembler.instruction(aarch64_add_x_imm(5, 5, 1)?)?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "the authenticated ordered-NFA request, closure, and exact-span replay are one helper-free leaf"
)]
fn lower_aarch64_ordered_nfa_participation_v1(
    target: Target,
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<Aarch64NativeParticipationLowering, ObjectError> {
    validate_ordered_nfa_participation_geometry(geometry)?;
    use crate::participation_aot::{
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_ASSERT,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_EPSILON,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_FAIL,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SAVE,
        NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SPLIT,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_MAGIC,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_VERSION,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES,
        NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES,
    };
    const FRAME_BYTES: u16 = 160;
    const COUNT_POINTER: u16 = 96;
    const MATCH_END: u16 = 104;
    const CURRENT_COUNT: u16 = 112;
    const NEXT_COUNT: u16 = 120;
    const GENERATION: u16 = 128;
    const TARGET_PC: u16 = 132;
    const CLOSURE_OUTPUT: u16 = 136;
    const CLOSURE_COUNT: u16 = 144;
    const SCRATCH_POINTER: u16 = 152;

    let state_count = u32::try_from(geometry.state_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA states"))?;
    let range_count = u32::try_from(geometry.ordered_nfa_byte_range_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA ranges"))?;
    let group_count = u32::try_from(geometry.group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA groups"))?;
    let slot_count = group_count
        .checked_mul(2)
        .ok_or(ObjectError::ArithmeticOverflow("ordered-NFA slots"))?;
    let fallback_resource = match geometry.dfa_fallback_resource {
        Some(crate::NativeParticipationAotResourceV1::DfaStates) => 1_u64,
        Some(crate::NativeParticipationAotResourceV1::BuildWork) => 2_u64,
        _ => {
            return Err(ObjectError::InvalidModule(
                "ordered-NFA fallback resource",
            ));
        }
    };

    let mut assembler = Aarch64Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let clear_seen = assembler.label()?;
    let clear_seen_loop = assembler.label()?;
    let clear_seen_done = assembler.label()?;
    let replay_loop = assembler.label()?;
    let generation_ready = assembler.label()?;
    let thread_loop = assembler.label()?;
    let next_thread = assembler.label()?;
    let range_loop = assembler.label()?;
    let range_next = assembler.label()?;
    let byte_matched = assembler.label()?;
    let swap_frontiers = assembler.label()?;
    let accept_loop = assembler.label()?;
    let accept_scan = assembler.label()?;
    let accept_match = assembler.label()?;
    let popcount_loop = assembler.label()?;
    let popcount_done = assembler.label()?;
    let closure = assembler.label()?;
    let closure_loop = assembler.label()?;
    let closure_append = assembler.label()?;
    let closure_epsilon = assembler.label()?;
    let closure_assert = assembler.label()?;
    let closure_assert_start = assembler.label()?;
    let closure_assert_end = assembler.label()?;
    let closure_save = assembler.label()?;
    let closure_save_open = assembler.label()?;
    let closure_save_close = assembler.label()?;
    let closure_split = assembler.label()?;
    let closure_done = assembler.label()?;
    let closure_failure = assembler.label()?;

    // Validate the complete request object before touching the stack.
    assembler.branch_zero_x(0, invalid_before_frame)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(8, 0)?)?;
    assembler.branch_nonzero_x(8, invalid_before_frame)?;
    assembler.instruction(aarch64_add_x_imm(8, 0, 64)?)?;
    assembler.instruction(aarch64_cmp_x(8, 0)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_before_frame)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_store_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_mov_x(29, 0)?)?;
    let plan_page_relocation_offset = assembler.instruction(0x9000_0016)?; // adrp x22, bundle
    let plan_page_offset_relocation_offset =
        assembler.instruction(aarch64_add_x_imm(22, 22, 0)?)?;

    assembler.instruction(aarch64_load_x_imm(8, 29, 0)?)?;
    assembler.instruction(aarch64_cmp_x(8, 22)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_load_x_imm(19, 29, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(20, 29, 16)?)?;
    assembler.instruction(aarch64_load_x_imm(21, 29, 24)?)?;
    assembler.instruction(aarch64_load_x_imm(8, 29, 32)?)?;
    assembler.instruction(aarch64_store_x(8, 31, MATCH_END)?)?;
    assembler.instruction(aarch64_load_x_imm(10, 29, 48)?)?;
    assembler.instruction(aarch64_load_x_imm(9, 29, 40)?)?;
    assembler.instruction(aarch64_store_x(9, 31, SCRATCH_POINTER)?)?;
    assembler.instruction(aarch64_load_x_imm(11, 29, 56)?)?;

    assembler.branch_zero_x(19, invalid)?;
    assembler.instruction(aarch64_cmp_x(21, 8)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_cmp_x(8, 20)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_zero_x(9, invalid)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(12, 9)?)?;
    assembler.branch_nonzero_x(12, invalid)?;
    aarch64_load_u64_constant(
        &mut assembler,
        12,
        u64::try_from(geometry.replay_scratch_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?,
    )?;
    assembler.instruction(aarch64_cmp_x(10, 12)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.branch_zero_x(11, invalid)?;
    assembler.instruction(aarch64_native_participation_alignment_mask(12, 11)?)?;
    assembler.branch_nonzero_x(12, invalid)?;
    assembler.instruction(aarch64_add_x_reg(12, 19, 20)?)?;
    assembler.instruction(aarch64_cmp_x(12, 19)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_add_x_reg(13, 9, 10)?)?;
    assembler.instruction(aarch64_cmp_x(13, 9)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_add_x_imm(14, 11, 8)?)?;
    assembler.instruction(aarch64_cmp_x(14, 11)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_store_x(11, 31, COUNT_POINTER)?)?;

    // Scratch is written during replay, so it must be disjoint from every
    // object that remains live for the call. Empty haystacks have no extent.
    let scratch_haystack_disjoint = assembler.label()?;
    assembler.branch_zero_x(20, scratch_haystack_disjoint)?;
    assembler.instruction(aarch64_cmp_x(9, 12)?)?; // scratch >= haystack_end
    assembler.branch_cond(AARCH64_HS, scratch_haystack_disjoint)?;
    assembler.instruction(aarch64_cmp_x(19, 13)?)?; // haystack < scratch_end
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_haystack_disjoint)?;
    let scratch_request_disjoint = assembler.label()?;
    assembler.instruction(aarch64_add_x_imm(15, 29, 64)?)?;
    assembler.instruction(aarch64_cmp_x(9, 15)?)?;
    assembler.branch_cond(AARCH64_HS, scratch_request_disjoint)?;
    assembler.instruction(aarch64_cmp_x(29, 13)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_request_disjoint)?;
    let scratch_count_disjoint = assembler.label()?;
    assembler.instruction(aarch64_cmp_x(9, 14)?)?;
    assembler.branch_cond(AARCH64_HS, scratch_count_disjoint)?;
    assembler.instruction(aarch64_cmp_x(11, 13)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_count_disjoint)?;
    let scratch_plan_disjoint = assembler.label()?;
    aarch64_load_u64_constant(
        &mut assembler,
        15,
        u64::try_from(geometry.total_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA plan bytes"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(15, 22, 15)?)?;
    assembler.instruction(aarch64_cmp_x(15, 22)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(9, 15)?)?;
    assembler.branch_cond(AARCH64_HS, scratch_plan_disjoint)?;
    assembler.instruction(aarch64_cmp_x(22, 13)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_plan_disjoint)?;

    aarch64_ordered_nfa_compare_u64(
        &mut assembler,
        22,
        0,
        u64::from_le_bytes(crate::NATIVE_PARTICIPATION_AOT_V1_MAGIC),
        runtime_failure,
    )?;
    let header_word = (u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA header"))?
        << 16)
        | u32::from(crate::NATIVE_PARTICIPATION_AOT_V1_ABI_VERSION);
    for (offset, expected) in [
        (8_u16, header_word),
        (12, 7),
        (32, native_participation_target_word(target)?),
        (
            36,
            u32::try_from(target.features.bits())
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA features"))?,
        ),
        (
            40,
            u32::from(crate::NativeParticipationAotStrategyV1::OrderedNfaAarch64 as u16),
        ),
        (
            44,
            u32::try_from(geometry.replay_scratch_bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?,
        ),
        (48, group_count),
        (
            52,
            u32::try_from(geometry.assertion_count)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA assertions"))?,
        ),
        (56, 0),
        (60, 0),
        (64, state_count),
        (68, range_count),
    ] {
        aarch64_ordered_nfa_compare_u32(&mut assembler, 22, offset, expected, runtime_failure)?;
    }
    for (offset, expected) in [
        (16_u16, geometry.total_bytes),
        (
            24,
            usize::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_READY_SEAL)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA seal"))?,
        ),
        (72, geometry.build_work),
        (80, geometry.ordered_nfa_metadata_offset),
        (88, geometry.ordered_nfa_states_offset),
        (96, geometry.ordered_nfa_byte_ranges_offset),
        (104, geometry.replay_current_offset),
        (112, geometry.replay_next_offset),
        (120, geometry.replay_stack_offset),
    ] {
        aarch64_ordered_nfa_compare_u64(
            &mut assembler,
            22,
            offset,
            u64::try_from(expected)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA plan field"))?,
            runtime_failure,
        )?;
    }

    aarch64_load_u64_constant(
        &mut assembler,
        12,
        u64::try_from(geometry.ordered_nfa_metadata_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA metadata"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(12, 22, 12)?)?;
    aarch64_ordered_nfa_compare_u64(
        &mut assembler,
        12,
        0,
        u64::from_le_bytes(NATIVE_PARTICIPATION_ORDERED_NFA_V1_MAGIC),
        runtime_failure,
    )?;
    let metadata_shape = u64::from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_VERSION)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_METADATA_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA metadata"))?
            << 16)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_STATE_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA state width"))?
            << 32)
        | (u64::try_from(NATIVE_PARTICIPATION_ORDERED_NFA_V1_RANGE_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA range width"))?
            << 48);
    for (offset, expected) in [
        (8_u16, metadata_shape),
        (16, fallback_resource),
        (
            24,
            u64::try_from(geometry.dfa_fallback_required)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA fallback"))?,
        ),
        (
            32,
            u64::try_from(geometry.dfa_fallback_limit)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA fallback"))?,
        ),
        (
            40,
            u64::from(geometry.ordered_nfa_start_state) | (u64::from(state_count) << 32),
        ),
        (48, u64::from(range_count) | (u64::from(group_count) << 32)),
        (
            56,
            u64::try_from(geometry.ordered_nfa_states_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA states"))?,
        ),
        (
            64,
            u64::try_from(geometry.ordered_nfa_byte_ranges_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA ranges"))?,
        ),
        (72, 0),
        (
            80,
            u64::try_from(geometry.replay_next_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA next"))?,
        ),
        (
            88,
            u64::try_from(geometry.replay_stack_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA stack"))?,
        ),
        (
            96,
            u64::try_from(geometry.replay_seen_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA seen"))?,
        ),
        (
            104,
            u64::try_from(geometry.replay_scratch_bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA scratch"))?,
        ),
    ] {
        aarch64_ordered_nfa_compare_u64(
            &mut assembler,
            12,
            offset,
            expected,
            runtime_failure,
        )?;
    }

    for (register, displacement, site) in [
        (23, geometry.replay_current_offset, "ordered-NFA current"),
        (24, geometry.replay_next_offset, "ordered-NFA next"),
        (25, geometry.replay_stack_offset, "ordered-NFA stack"),
        (26, geometry.replay_seen_offset, "ordered-NFA seen"),
    ] {
        assembler.instruction(aarch64_load_x_imm(9, 31, SCRATCH_POINTER)?)?;
        aarch64_load_u64_constant(
            &mut assembler,
            8,
            u64::try_from(displacement).map_err(|_| ObjectError::ArithmeticOverflow(site))?,
        )?;
        assembler.instruction(aarch64_add_x_reg(register, 9, 8)?)?;
    }
    for (register, displacement, site) in [
        (
            27,
            geometry.ordered_nfa_states_offset,
            "ordered-NFA states",
        ),
        (
            28,
            geometry.ordered_nfa_byte_ranges_offset,
            "ordered-NFA ranges",
        ),
    ] {
        aarch64_load_u64_constant(
            &mut assembler,
            8,
            u64::try_from(displacement).map_err(|_| ObjectError::ArithmeticOverflow(site))?,
        )?;
        assembler.instruction(aarch64_add_x_reg(register, 22, 8)?)?;
    }

    // Clear generation marks and seed the first prioritized closure.
    assembler.bind(clear_seen)?;
    assembler.instruction(aarch64_movz_x(5, 0, 0)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, state_count)?;
    assembler.bind(clear_seen_loop)?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_HS, clear_seen_done)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 26, 5, 2)?)?;
    assembler.instruction(aarch64_store_w(31, 7, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(5, 5, 1)?)?;
    assembler.branch(clear_seen_loop)?;
    assembler.bind(clear_seen_done)?;
    assembler.instruction(aarch64_store_x(31, 31, CURRENT_COUNT)?)?;
    assembler.instruction(aarch64_store_x(31, 31, NEXT_COUNT)?)?;
    assembler.instruction(aarch64_movz_w(6, 1)?)?;
    assembler.instruction(aarch64_store_w(6, 31, GENERATION)?)?;
    aarch64_load_u32_constant(&mut assembler, 0, geometry.ordered_nfa_start_state)?;
    assembler.instruction(aarch64_movz_x(1, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(2, 0, 0)?)?;
    assembler.instruction(aarch64_mov_x(3, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(4, 31, CURRENT_COUNT)?)?;
    assembler.call(closure)?;
    assembler.branch_nonzero_w(0, runtime_failure)?;

    assembler.bind(replay_loop)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, MATCH_END)?)?;
    assembler.instruction(aarch64_cmp_x(21, 5)?)?;
    assembler.branch_cond(AARCH64_EQ, accept_loop)?;
    assembler.instruction(aarch64_store_x(31, 31, NEXT_COUNT)?)?;
    assembler.instruction(aarch64_load_w_imm(6, 31, GENERATION)?)?;
    assembler.instruction(aarch64_movz_w(7, 1)?)?;
    assembler.instruction(aarch64_add_w_reg(6, 6, 7)?)?;
    assembler.instruction(aarch64_store_w(6, 31, GENERATION)?)?;
    assembler.branch_nonzero_w(6, generation_ready)?;
    assembler.instruction(aarch64_movz_x(5, 0, 0)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, state_count)?;
    let generation_clear_loop = assembler.label()?;
    let generation_clear_done = assembler.label()?;
    assembler.bind(generation_clear_loop)?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_HS, generation_clear_done)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 26, 5, 2)?)?;
    assembler.instruction(aarch64_store_w(31, 7, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(5, 5, 1)?)?;
    assembler.branch(generation_clear_loop)?;
    assembler.bind(generation_clear_done)?;
    assembler.instruction(aarch64_movz_w(6, 1)?)?;
    assembler.instruction(aarch64_store_w(6, 31, GENERATION)?)?;
    assembler.bind(generation_ready)?;
    assembler.instruction(aarch64_movz_x(29, 0, 0)?)?;

    assembler.bind(thread_loop)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, CURRENT_COUNT)?)?;
    assembler.instruction(aarch64_cmp_x(29, 6)?)?;
    assembler.branch_cond(AARCH64_HS, swap_frontiers)?;
    aarch64_load_u32_constant(
        &mut assembler,
        7,
        u32::try_from(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA thread width"))?,
    )?;
    assembler.instruction(aarch64_madd_x(8, 29, 7, 23)?)?;
    assembler.instruction(aarch64_load_w_imm(0, 8, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(1, 8, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(2, 8, 16)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, state_count)?;
    assembler.instruction(aarch64_cmp_w(0, 6)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.instruction(aarch64_add_x_uxtw(9, 27, 0, 4)?)?;
    assembler.instruction(aarch64_load_byte_imm(10, 9, 0)?)?;
    assembler.instruction(aarch64_cmp_w_imm(
        10,
        u16::from(NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH),
    )?)?;
    assembler.branch_cond(AARCH64_EQ, next_thread)?;
    assembler.instruction(aarch64_cmp_w_imm(
        10,
        u16::from(NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE),
    )?)?;
    assembler.branch_cond(AARCH64_NE, runtime_failure)?;
    assembler.instruction(aarch64_load_w_imm(11, 9, 4)?)?;
    assembler.instruction(aarch64_store_w(11, 31, TARGET_PC)?)?;
    assembler.instruction(aarch64_load_w_imm(12, 9, 8)?)?;
    assembler.instruction(aarch64_load_w_imm(13, 9, 12)?)?;
    assembler.branch_zero_w(13, runtime_failure)?;
    assembler.instruction(aarch64_add_w_reg(14, 12, 13)?)?;
    assembler.instruction(aarch64_cmp_w(14, 12)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    aarch64_load_u32_constant(&mut assembler, 10, range_count)?;
    assembler.instruction(aarch64_cmp_w(14, 10)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_load_byte_reg(15, 19, 21)?)?;

    assembler.bind(range_loop)?;
    assembler.instruction(aarch64_cmp_w(12, 14)?)?;
    assembler.branch_cond(AARCH64_HS, next_thread)?;
    assembler.instruction(aarch64_add_x_uxtw(16, 28, 12, 1)?)?;
    assembler.instruction(aarch64_load_byte_imm(17, 16, 0)?)?;
    assembler.instruction(aarch64_load_byte_imm(10, 16, 1)?)?;
    assembler.instruction(aarch64_cmp_w(15, 17)?)?;
    assembler.branch_cond(AARCH64_LO, range_next)?;
    assembler.instruction(aarch64_cmp_w(15, 10)?)?;
    assembler.branch_cond(AARCH64_LS, byte_matched)?;
    assembler.bind(range_next)?;
    assembler.instruction(aarch64_movz_w(6, 1)?)?;
    assembler.instruction(aarch64_add_w_reg(12, 12, 6)?)?;
    assembler.branch(range_loop)?;

    assembler.bind(byte_matched)?;
    assembler.instruction(aarch64_load_w_imm(0, 31, TARGET_PC)?)?;
    assembler.instruction(aarch64_mov_x(3, 24)?)?;
    assembler.instruction(aarch64_add_x_imm(4, 31, NEXT_COUNT)?)?;
    assembler.call(closure)?;
    assembler.branch_nonzero_w(0, runtime_failure)?;
    assembler.bind(next_thread)?;
    assembler.instruction(aarch64_adds_x_imm(29, 29, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(thread_loop)?;

    assembler.bind(swap_frontiers)?;
    assembler.instruction(aarch64_mov_x(5, 23)?)?;
    assembler.instruction(aarch64_mov_x(23, 24)?)?;
    assembler.instruction(aarch64_mov_x(24, 5)?)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, NEXT_COUNT)?)?;
    assembler.instruction(aarch64_store_x(5, 31, CURRENT_COUNT)?)?;
    assembler.instruction(aarch64_adds_x_imm(21, 21, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(replay_loop)?;

    assembler.bind(accept_loop)?;
    assembler.instruction(aarch64_movz_x(29, 0, 0)?)?;
    assembler.bind(accept_scan)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, CURRENT_COUNT)?)?;
    assembler.instruction(aarch64_cmp_x(29, 6)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    aarch64_load_u32_constant(
        &mut assembler,
        7,
        u32::try_from(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA thread width"))?,
    )?;
    assembler.instruction(aarch64_madd_x(8, 29, 7, 23)?)?;
    assembler.instruction(aarch64_load_w_imm(0, 8, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(1, 8, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(2, 8, 16)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, state_count)?;
    assembler.instruction(aarch64_cmp_w(0, 6)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.instruction(aarch64_add_x_uxtw(9, 27, 0, 4)?)?;
    assembler.instruction(aarch64_load_byte_imm(10, 9, 0)?)?;
    assembler.instruction(aarch64_cmp_w_imm(
        10,
        u16::from(NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH),
    )?)?;
    assembler.branch_cond(AARCH64_EQ, accept_match)?;
    assembler.instruction(aarch64_adds_x_imm(29, 29, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(accept_scan)?;

    assembler.bind(accept_match)?;
    assembler.branch_nonzero_x(1, runtime_failure)?;
    assembler.instruction(aarch64_movz_x(5, 1, 0)?)?;
    assembler.instruction(aarch64_tst_x(2, 5)?)?;
    assembler.branch_cond(AARCH64_EQ, runtime_failure)?;
    assembler.instruction(aarch64_movz_x(3, 0, 0)?)?;
    assembler.bind(popcount_loop)?;
    assembler.branch_zero_x(2, popcount_done)?;
    assembler.instruction(aarch64_sub_x_imm(4, 2, 1)?)?;
    assembler.instruction(aarch64_and_x(2, 2, 4)?)?;
    assembler.instruction(aarch64_add_x_imm(3, 3, 1)?)?;
    assembler.branch(popcount_loop)?;
    assembler.bind(popcount_done)?;
    assembler.branch_zero_x(3, runtime_failure)?;
    aarch64_load_u32_constant(&mut assembler, 5, group_count)?;
    assembler.instruction(aarch64_cmp_x(3, 5)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, COUNT_POINTER)?)?;
    assembler.instruction(aarch64_store_x(3, 5, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;

    // Internal prioritized epsilon closure. It has no nested calls, so the
    // main leaf's saved link register remains sufficient.
    assembler.bind(closure)?;
    assembler.instruction(aarch64_store_x(3, 31, CLOSURE_OUTPUT)?)?;
    assembler.instruction(aarch64_store_x(4, 31, CLOSURE_COUNT)?)?;
    assembler.instruction(aarch64_movz_x(5, 0, 0)?)?;
    aarch64_ordered_nfa_push_thread(&mut assembler, state_count, closure_failure)?;
    assembler.bind(closure_loop)?;
    assembler.branch_zero_x(5, closure_done)?;
    assembler.instruction(aarch64_sub_x_imm(5, 5, 1)?)?;
    aarch64_load_u32_constant(
        &mut assembler,
        6,
        u32::try_from(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA thread width"))?,
    )?;
    assembler.instruction(aarch64_madd_x(7, 5, 6, 25)?)?;
    assembler.instruction(aarch64_load_w_imm(0, 7, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(1, 7, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(2, 7, 16)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, state_count)?;
    assembler.instruction(aarch64_cmp_w(0, 6)?)?;
    assembler.branch_cond(AARCH64_HS, closure_failure)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 26, 0, 2)?)?;
    assembler.instruction(aarch64_load_w_imm(6, 7, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(9, 31, GENERATION)?)?;
    assembler.instruction(aarch64_cmp_w(6, 9)?)?;
    assembler.branch_cond(AARCH64_EQ, closure_loop)?;
    assembler.instruction(aarch64_store_w(9, 7, 0)?)?;
    assembler.instruction(aarch64_add_x_uxtw(8, 27, 0, 4)?)?;
    assembler.instruction(aarch64_load_byte_imm(9, 8, 0)?)?;
    for (tag, destination) in [
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_BYTE, closure_append),
        (
            NATIVE_PARTICIPATION_ORDERED_NFA_STATE_MATCH,
            closure_append,
        ),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_FAIL, closure_loop),
        (
            NATIVE_PARTICIPATION_ORDERED_NFA_STATE_EPSILON,
            closure_epsilon,
        ),
        (
            NATIVE_PARTICIPATION_ORDERED_NFA_STATE_ASSERT,
            closure_assert,
        ),
        (NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SAVE, closure_save),
        (
            NATIVE_PARTICIPATION_ORDERED_NFA_STATE_SPLIT,
            closure_split,
        ),
    ] {
        assembler.instruction(aarch64_cmp_w_imm(9, u16::from(tag))?)?;
        assembler.branch_cond(AARCH64_EQ, destination)?;
    }
    assembler.branch(closure_failure)?;

    assembler.bind(closure_append)?;
    assembler.instruction(aarch64_load_x_imm(3, 31, CLOSURE_OUTPUT)?)?;
    assembler.instruction(aarch64_load_x_imm(4, 31, CLOSURE_COUNT)?)?;
    assembler.instruction(aarch64_load_x_imm(6, 4, 0)?)?;
    aarch64_load_u32_constant(&mut assembler, 7, state_count)?;
    assembler.instruction(aarch64_cmp_x(6, 7)?)?;
    assembler.branch_cond(AARCH64_HS, closure_failure)?;
    aarch64_load_u32_constant(
        &mut assembler,
        7,
        u32::try_from(fre_capture_lab::EXACT_SPAN_PARTICIPATION_NATIVE_V1_THREAD_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("ordered-NFA thread width"))?,
    )?;
    assembler.instruction(aarch64_madd_x(7, 6, 7, 3)?)?;
    assembler.instruction(aarch64_store_w(0, 7, 0)?)?;
    assembler.instruction(aarch64_store_w(31, 7, 4)?)?;
    assembler.instruction(aarch64_store_x(1, 7, 8)?)?;
    assembler.instruction(aarch64_store_x(2, 7, 16)?)?;
    assembler.instruction(aarch64_add_x_imm(6, 6, 1)?)?;
    assembler.instruction(aarch64_store_x(6, 4, 0)?)?;
    assembler.branch(closure_loop)?;

    assembler.bind(closure_epsilon)?;
    assembler.instruction(aarch64_load_w_imm(0, 8, 4)?)?;
    aarch64_ordered_nfa_push_thread(&mut assembler, state_count, closure_failure)?;
    assembler.branch(closure_loop)?;

    assembler.bind(closure_assert)?;
    assembler.instruction(aarch64_load_byte_imm(9, 8, 2)?)?;
    assembler.branch_nonzero_w(9, closure_failure)?;
    assembler.instruction(aarch64_load_byte_imm(9, 8, 1)?)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, closure_assert_start)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 2)?)?;
    assembler.branch_cond(AARCH64_EQ, closure_assert_end)?;
    assembler.branch(closure_failure)?;
    assembler.bind(closure_assert_start)?;
    assembler.branch_nonzero_x(21, closure_loop)?;
    assembler.branch(closure_epsilon)?;
    assembler.bind(closure_assert_end)?;
    assembler.instruction(aarch64_cmp_x(21, 20)?)?;
    assembler.branch_cond(AARCH64_NE, closure_loop)?;
    assembler.branch(closure_epsilon)?;

    assembler.bind(closure_save)?;
    assembler.instruction(aarch64_load_byte_imm(9, 8, 1)?)?;
    aarch64_load_u32_constant(&mut assembler, 10, slot_count)?;
    assembler.instruction(aarch64_cmp_w(9, 10)?)?;
    assembler.branch_cond(AARCH64_HS, closure_failure)?;
    assembler.instruction(aarch64_lsr_w_imm(10, 9, 1)?)?;
    assembler.instruction(aarch64_movz_x(11, 1, 0)?)?;
    assembler.instruction(aarch64_lslv_x(11, 11, 10)?)?;
    assembler.branch_bit_clear_w(9, 0, closure_save_open)?;
    assembler.branch(closure_save_close)?;
    assembler.bind(closure_save_open)?;
    assembler.instruction(aarch64_tst_x(1, 11)?)?;
    assembler.branch_cond(AARCH64_NE, closure_failure)?;
    assembler.instruction(aarch64_orr_x(1, 1, 11)?)?;
    assembler.branch(closure_epsilon)?;
    assembler.bind(closure_save_close)?;
    assembler.instruction(aarch64_tst_x(1, 11)?)?;
    assembler.branch_cond(AARCH64_EQ, closure_failure)?;
    assembler.instruction(aarch64_bic_x(1, 1, 11)?)?;
    assembler.instruction(aarch64_orr_x(2, 2, 11)?)?;
    assembler.branch(closure_epsilon)?;

    assembler.bind(closure_split)?;
    assembler.instruction(aarch64_load_w_imm(9, 8, 4)?)?;
    assembler.instruction(aarch64_load_w_imm(0, 8, 8)?)?;
    aarch64_ordered_nfa_push_thread(&mut assembler, state_count, closure_failure)?;
    assembler.instruction(aarch64_add_w_reg(0, 9, 31)?)?;
    aarch64_ordered_nfa_push_thread(&mut assembler, state_count, closure_failure)?;
    assembler.branch(closure_loop)?;

    assembler.bind(closure_done)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(closure_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_load_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(invalid_before_frame)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut relocation_offsets = [
        plan_page_relocation_offset,
        plan_page_offset_relocation_offset,
    ];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    Ok(Aarch64NativeParticipationLowering {
        code,
        plan_page_relocation_offset: relocation_offsets[0],
        plan_page_offset_relocation_offset: relocation_offsets[1],
    })
}

fn lower_x86_64_native_participation_v1(
    target: Target,
    geometry: crate::participation_aot::NativeParticipationPlanGeometryV1,
) -> Result<X86NativeParticipationLowering, ObjectError> {
    validate_native_participation_geometry(geometry)?;
    let displacement = |value: usize, site| {
        i32::try_from(value)
            .map(i32::to_le_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow(site))
    };
    let boundary_map_offset = displacement(
        geometry.boundary_map_offset,
        "x86 participation boundary map",
    )?;
    let start_states_offset = displacement(
        geometry.start_states_offset,
        "x86 participation start states",
    )?;
    let byte_classes_offset = displacement(
        geometry.byte_classes_offset,
        "x86 participation byte classes",
    )?;
    let transitions_offset =
        displacement(geometry.transitions_offset, "x86 participation transitions")?;
    let accept_counts_offset =
        displacement(geometry.accept_counts_offset, "x86 participation accepts")?;
    let alphabet = u32::try_from(geometry.alphabet_len).unwrap();
    let signature_count = u32::try_from(geometry.signature_count).unwrap();
    let state_count = u32::try_from(geometry.state_count).unwrap();
    let transition_count = u32::try_from(geometry.transition_count).unwrap();

    let mut assembler = X86Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let loop_head = assembler.label()?;
    let accept = assembler.label()?;
    let returned = assembler.label()?;

    // Validate the complete request object before saving registers. The entry
    // never dereferences a merely non-null wrapping request extent.
    assembler.instruction(&[0x48, 0x85, 0xff])?; // request
    assembler.branch(&[0x0f, 0x84], invalid_before_frame)?;
    assembler.instruction(&[0x40, 0xf6, 0xc7, 0x07])?; // alignof(request)
    assembler.branch(&[0x0f, 0x85], invalid_before_frame)?;
    assembler.instruction(&[0x48, 0x89, 0xf8])?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 64])?;
    assembler.branch(&[0x0f, 0x82], invalid_before_frame)?;

    assembler.instruction(&[0x55])?;
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x4c, 0x8d, 0x3d])?; // bundle(%rip) -> r15
    let plan_relocation = assembler.label()?;
    assembler.bind(plan_relocation)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.instruction(&[0x48, 0x8b, 0x07])?; // paired bundle
    assembler.instruction(&[0x4c, 0x39, 0xf8])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x8b, 0x5f, 0x08])?; // haystack
    assembler.instruction(&[0x4c, 0x8b, 0x67, 0x10])?; // haystack_len
    assembler.instruction(&[0x4c, 0x8b, 0x6f, 0x18])?; // match_start
    assembler.instruction(&[0x4c, 0x8b, 0x77, 0x20])?; // match_end
    assembler.instruction(&[0x4c, 0x8b, 0x47, 0x28])?; // scratch
    assembler.instruction(&[0x48, 0x8b, 0x47, 0x30])?; // scratch_len
    assembler.instruction(&[0x4c, 0x8b, 0x4f, 0x38])?; // count_out

    assembler.instruction(&[0x48, 0x85, 0xdb])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xf5])?; // start <= end
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xe6])?; // end <= length
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x83, 0xf8, 16])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc1, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    for (move_pointer, add_extent) in [
        (&[0x48, 0x89, 0xd9][..], &[0x4c, 0x01, 0xe1][..]),
        (&[0x4c, 0x89, 0xc1][..], &[0x48, 0x83, 0xc1, 16][..]),
        (&[0x4c, 0x89, 0xc9][..], &[0x48, 0x83, 0xc1, 8][..]),
    ] {
        assembler.instruction(move_pointer)?;
        assembler.instruction(add_extent)?;
        assembler.branch(&[0x0f, 0x82], invalid)?;
    }

    // The relocated bundle address authenticates ownership; validate every
    // code-addressed immutable geometry word before reading input. Reserved
    // scratch is never read or written.
    let mut magic = vec![0x48, 0xb8];
    magic.extend_from_slice(
        &u64::from_le_bytes(crate::NATIVE_PARTICIPATION_AOT_V1_MAGIC).to_le_bytes(),
    );
    assembler.instruction(&magic)?;
    assembler.instruction(&[0x49, 0x39, 0x07])?;
    assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    let abi_header = (u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_HEADER_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("participation header"))?
        << 16)
        | u32::from(crate::NATIVE_PARTICIPATION_AOT_V1_ABI_VERSION);
    for (offset, expected) in [
        (8_u8, abi_header),
        (12, 3),
        (32, native_participation_target_word(target)?),
        (
            36,
            u32::try_from(target.features.bits())
                .map_err(|_| ObjectError::ArithmeticOverflow("participation features"))?,
        ),
        (
            40,
            u32::from(crate::NativeParticipationAotStrategyV1::DfaX86_64 as u16),
        ),
        (
            44,
            u32::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation scratch"))?,
        ),
        (48, u32::try_from(geometry.group_count).unwrap()),
        (52, u32::try_from(geometry.assertion_count).unwrap()),
        (56, signature_count),
        (60, alphabet),
        (64, state_count),
        (68, transition_count),
    ] {
        let mut compare = vec![0x41, 0x81, 0x7f, offset];
        compare.extend_from_slice(&expected.to_le_bytes());
        assembler.instruction(&compare)?;
        assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    }
    for (offset, expected) in [
        (16_u8, geometry.total_bytes),
        (
            24,
            usize::try_from(crate::NATIVE_PARTICIPATION_AOT_V1_READY_SEAL)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation seal"))?,
        ),
        (72, geometry.build_work),
        (80, geometry.signatures_offset),
        (88, geometry.byte_classes_offset),
        (96, geometry.boundary_map_offset),
        (104, geometry.start_states_offset),
        (112, geometry.transitions_offset),
        (120, geometry.accept_counts_offset),
    ] {
        let mut expected_value = vec![0x48, 0xb8];
        expected_value.extend_from_slice(
            &u64::try_from(expected)
                .map_err(|_| ObjectError::ArithmeticOverflow("participation geometry"))?
                .to_le_bytes(),
        );
        assembler.instruction(&expected_value)?;
        assembler.instruction(&[0x49, 0x39, 0x47, offset])?;
        assembler.branch(&[0x0f, 0x85], runtime_failure)?;
    }

    // Initial boundary signature and DFA state.
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.instruction(&[0x0f, 0x94, 0xc0])?;
    assembler.instruction(&[0x31, 0xc9])?;
    assembler.instruction(&[0x4d, 0x39, 0xe5])?;
    assembler.instruction(&[0x0f, 0x94, 0xc1])?;
    assembler.instruction(&[0xd1, 0xe1])?;
    assembler.instruction(&[0x09, 0xc8])?;
    let mut map_signature = vec![0x41, 0x0f, 0xb6, 0x84, 0x07];
    map_signature.extend_from_slice(&boundary_map_offset);
    assembler.instruction(&map_signature)?;
    let mut signature_bound = vec![0x3d];
    signature_bound.extend_from_slice(&signature_count.to_le_bytes());
    assembler.instruction(&signature_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    let mut load_start = vec![0x41, 0x8b, 0xac, 0x87];
    load_start.extend_from_slice(&start_states_offset);
    assembler.instruction(&load_start)?;
    let mut state_bound = vec![0x81, 0xfd];
    state_bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&state_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    let mut transitions = vec![0x4d, 0x8d, 0x97];
    transitions.extend_from_slice(&transitions_offset);
    assembler.instruction(&transitions)?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x4d, 0x39, 0xf5])?;
    assembler.branch(&[0x0f, 0x84], accept)?;
    assembler.instruction(&[0x42, 0x0f, 0xb6, 0x04, 0x2b])?;
    let mut map_class = vec![0x41, 0x0f, 0xb6, 0x94, 0x07];
    map_class.extend_from_slice(&byte_classes_offset);
    assembler.instruction(&map_class)?;
    let mut class_bound = vec![0x81, 0xfa];
    class_bound.extend_from_slice(&alphabet.to_le_bytes());
    assembler.instruction(&class_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x49, 0x83, 0xc5, 0x01])?;

    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.instruction(&[0x0f, 0x94, 0xc0])?;
    assembler.instruction(&[0x31, 0xc9])?;
    assembler.instruction(&[0x4d, 0x39, 0xe5])?;
    assembler.instruction(&[0x0f, 0x94, 0xc1])?;
    assembler.instruction(&[0xd1, 0xe1])?;
    assembler.instruction(&[0x09, 0xc8])?;
    let mut map_signature = vec![0x41, 0x0f, 0xb6, 0x84, 0x07];
    map_signature.extend_from_slice(&boundary_map_offset);
    assembler.instruction(&map_signature)?;
    let mut signature_bound = vec![0x3d];
    signature_bound.extend_from_slice(&signature_count.to_le_bytes());
    assembler.instruction(&signature_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x89, 0xc1])?; // signature
    assembler.instruction(&[0x89, 0xe8])?; // state
    let mut multiply = vec![0x69, 0xc0];
    multiply.extend_from_slice(&alphabet.to_le_bytes());
    assembler.instruction(&multiply)?;
    assembler.instruction(&[0x01, 0xd0])?; // class
    let mut multiply = vec![0x69, 0xc0];
    multiply.extend_from_slice(&signature_count.to_le_bytes());
    assembler.instruction(&multiply)?;
    assembler.instruction(&[0x01, 0xc8])?; // signature
    let mut transition_bound = vec![0x3d];
    transition_bound.extend_from_slice(&transition_count.to_le_bytes());
    assembler.instruction(&transition_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.instruction(&[0x41, 0x8b, 0x2c, 0x82])?;
    let mut state_bound = vec![0x81, 0xfd];
    state_bound.extend_from_slice(&state_count.to_le_bytes());
    assembler.instruction(&state_bound)?;
    assembler.branch(&[0x0f, 0x83], runtime_failure)?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(accept)?;
    let mut load_accept = vec![0x41, 0x0f, 0xb6, 0x84, 0x2f];
    load_accept.extend_from_slice(&accept_counts_offset);
    assembler.instruction(&load_accept)?;
    assembler.instruction(&[0x3d, 0xff, 0, 0, 0])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    let mut group_bound = vec![0x3d];
    group_bound.extend_from_slice(&u32::try_from(geometry.group_count).unwrap().to_le_bytes());
    assembler.instruction(&group_bound)?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.instruction(&[0x49, 0x89, 0x01])?;
    assembler.instruction(&[0xb8, 1, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(returned)?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0x5d])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_before_frame)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let plan_relocation_offset = finished.label_offset(plan_relocation)?;
    Ok(X86NativeParticipationLowering {
        code: finished.code,
        plan_relocation_offset,
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "exact tag replay, complete validation, and transactional publication form one generated leaf"
)]
fn lower_aarch64_native_capture_materialize_v1(
    geometry: crate::capture_aot::NativeCapturePlanGeometryV1,
) -> Result<Aarch64NativeCaptureMaterializerLowering, ObjectError> {
    const SAVED_BYTES: usize = 96;
    if geometry.group_count == 0
        || geometry.group_count.checked_mul(2) != Some(geometry.tag_slot_count)
        || geometry.tag_slot_count > 32
        || geometry.native_stack_bytes == 0
        || !geometry.native_stack_bytes.is_multiple_of(16)
        || geometry.alphabet_len == 0
        || usize::try_from(geometry.start_state).ok().is_none_or(|start| start >= geometry.state_count)
    {
        return Err(ObjectError::InvalidModule("AArch64 capture materializer geometry"));
    }
    let frame_bytes = SAVED_BYTES.checked_add(geometry.native_stack_bytes)
        .and_then(|bytes| u16::try_from(bytes).ok())
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture frame"))?;
    let scratch_offset = u16::try_from(SAVED_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture scratch"))?;
    let output_bytes = geometry.group_count.checked_mul(16)
        .and_then(|bytes| u16::try_from(bytes).ok())
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture output"))?;
    let transition_delta = geometry.transitions_offset.checked_sub(geometry.byte_classes_offset)
        .ok_or(ObjectError::InvalidModule("AArch64 capture transition order"))?;
    let state_delta = geometry.states_offset.checked_sub(geometry.byte_classes_offset)
        .and_then(|offset| u16::try_from(offset).ok())
        .filter(|offset| *offset <= 0x0fff)
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture state offset"))?;
    let mut assembler = Aarch64Assembler::new();
    let loop_head = assembler.label()?;
    let final_state = assembler.label()?;
    let transition_action = assembler.label()?;
    let transition_done = assembler.label()?;
    let match_action = assembler.label()?;
    let match_done = assembler.label()?;
    let runtime_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.branch_zero_x(0, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(1, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_cmp_x(3, 1)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_zero_x(4, invalid)?;
    assembler.instruction(aarch64_and_low_x(6, 4, 3)?)?;
    assembler.branch_nonzero_x(6, invalid)?;
    aarch64_load_u64_constant(
        &mut assembler,
        6,
        u64::try_from(geometry.group_count)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture groups"))?,
    )?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_add_x_imm(6, 4, output_bytes)?)?;
    assembler.instruction(aarch64_cmp_x(6, 4)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, frame_bytes)?)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_store_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_mov_x(23, 4)?)?;
    let plan_page = assembler.instruction(0x9000_0018)?; // adrp x24, classes
    let plan_page_offset = assembler.instruction(aarch64_add_x_imm(24, 24, 0)?)?;
    aarch64_load_u64_constant(
        &mut assembler,
        27,
        u64::try_from(transition_delta)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 transition offset"))?,
    )?;
    assembler.instruction(aarch64_add_x_reg(27, 24, 27)?)?; // transition base
    aarch64_load_u32_constant(&mut assembler, 17, u32::try_from(geometry.alphabet_len)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 alphabet"))?)?;
    aarch64_load_u64_constant(&mut assembler, 6, u64::MAX)?;
    for slot in 0..geometry.tag_slot_count {
        assembler.instruction(aarch64_store_x(
            6,
            31,
            scratch_offset.checked_add(u16::try_from(slot * 8)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture slot"))?)
                .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture slot"))?,
        )?)?;
    }
    aarch64_load_u32_constant(&mut assembler, 25, geometry.start_state)?;
    assembler.instruction(aarch64_mov_x(26, 21)?)?;

    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_cmp_x(26, 22)?)?;
    assembler.branch_cond(AARCH64_EQ, final_state)?;
    assembler.instruction(aarch64_load_byte_reg(6, 19, 26)?)?;
    assembler.instruction(aarch64_load_byte_reg(6, 24, 6)?)?;
    assembler.instruction(aarch64_madd_w(6, 25, 17, 6)?)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 27, 6, 3)?)?;
    assembler.instruction(aarch64_load_w_imm(25, 7, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(28, 7, 4)?)?;
    aarch64_load_u32_constant(&mut assembler, 6, u32::MAX)?;
    assembler.instruction(aarch64_cmp_w(25, 6)?)?;
    assembler.branch_cond(AARCH64_EQ, runtime_error)?;
    assembler.branch_zero_w(28, transition_done)?;
    assembler.bind(transition_action)?;
    assembler.instruction(aarch64_rbit_w(6, 28)?)?;
    assembler.instruction(aarch64_clz_w(6, 6)?)?;
    assembler.instruction(aarch64_add_x_imm(7, 31, scratch_offset)?)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 7, 6, 3)?)?;
    assembler.instruction(aarch64_store_x(26, 7, 0)?)?;
    assembler.instruction(aarch64_sub_w_imm(6, 28, 1)?)?;
    assembler.instruction(aarch64_and_w(28, 28, 6)?)?;
    assembler.branch_nonzero_w(28, transition_action)?;
    assembler.bind(transition_done)?;
    assembler.instruction(aarch64_add_x_imm(26, 26, 1)?)?;
    assembler.branch(loop_head)?;

    assembler.bind(final_state)?;
    assembler.instruction(aarch64_add_x_imm(7, 24, state_delta)?)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 7, 25, 3)?)?;
    assembler.instruction(aarch64_load_w_imm(28, 7, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(6, 7, 4)?)?;
    assembler.branch_bit_clear_w(6, 0, runtime_error)?;
    assembler.branch_zero_w(28, match_done)?;
    assembler.bind(match_action)?;
    assembler.instruction(aarch64_rbit_w(6, 28)?)?;
    assembler.instruction(aarch64_clz_w(6, 6)?)?;
    assembler.instruction(aarch64_add_x_imm(7, 31, scratch_offset)?)?;
    assembler.instruction(aarch64_add_x_uxtw(7, 7, 6, 3)?)?;
    assembler.instruction(aarch64_store_x(26, 7, 0)?)?;
    assembler.instruction(aarch64_sub_w_imm(6, 28, 1)?)?;
    assembler.instruction(aarch64_and_w(28, 28, 6)?)?;
    assembler.branch_nonzero_w(28, match_action)?;
    assembler.bind(match_done)?;

    assembler.instruction(aarch64_load_x_imm(6, 31, scratch_offset)?)?;
    assembler.instruction(aarch64_cmp_x(6, 21)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_error)?;
    assembler.instruction(aarch64_load_x_imm(7, 31, scratch_offset + 8)?)?;
    assembler.instruction(aarch64_cmp_x(7, 22)?)?;
    assembler.branch_cond(AARCH64_NE, runtime_error)?;
    aarch64_load_u64_constant(&mut assembler, 8, u64::MAX)?;
    for group in 1..geometry.group_count {
        let valid = assembler.label()?;
        let unset = assembler.label()?;
        let offset = scratch_offset.checked_add(u16::try_from(group * 16)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 group offset"))?)
            .ok_or(ObjectError::ArithmeticOverflow("AArch64 group offset"))?;
        assembler.instruction(aarch64_load_pair_x(6, 7, 31, i16::try_from(offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 group offset"))?)?)?;
        assembler.instruction(aarch64_cmp_x(6, 8)?)?;
        assembler.branch_cond(AARCH64_EQ, unset)?;
        assembler.instruction(aarch64_cmp_x(7, 8)?)?;
        assembler.branch_cond(AARCH64_EQ, runtime_error)?;
        assembler.instruction(aarch64_cmp_x(6, 7)?)?;
        assembler.branch_cond(AARCH64_HI, runtime_error)?;
        assembler.instruction(aarch64_cmp_x(6, 21)?)?;
        assembler.branch_cond(AARCH64_LO, runtime_error)?;
        assembler.instruction(aarch64_cmp_x(7, 22)?)?;
        assembler.branch_cond(AARCH64_HI, runtime_error)?;
        assembler.branch(valid)?;
        assembler.bind(unset)?;
        assembler.instruction(aarch64_cmp_x(7, 8)?)?;
        assembler.branch_cond(AARCH64_NE, runtime_error)?;
        assembler.bind(valid)?;
    }
    for group in 0..geometry.group_count {
        let scratch = i16::try_from(SAVED_BYTES + group * 16)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture commit"))?;
        let output = i16::try_from(group * 16)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture commit"))?;
        assembler.instruction(aarch64_load_pair_x(6, 7, 31, scratch)?)?;
        assembler.instruction(aarch64_store_pair_x(6, 7, 23, output)?)?;
    }
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_error)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_load_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [plan_page, plan_page_offset];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(Aarch64NativeCaptureMaterializerLowering {
        code,
        plan_page_relocation_offset: offsets[0],
        plan_page_offset_relocation_offset: offsets[1],
    })
}

fn aarch64_rbit_w(destination: u8, source: u8) -> Result<u32, ObjectError> {
    Ok(0x5ac0_0000 | aarch64_reg(source, 5)? | aarch64_reg(destination, 0)?)
}

fn aarch64_clz_w(destination: u8, source: u8) -> Result<u32, ObjectError> {
    Ok(0x5ac0_1000 | aarch64_reg(source, 5)? | aarch64_reg(destination, 0)?)
}

#[allow(
    clippy::too_many_lines,
    reason = "iterator validation, nullable progress, two local calls, and transactional publication stay auditable together"
)]
fn lower_aarch64_native_capture_next_v1(
    group_count: usize,
) -> Result<Aarch64NativeCaptureNextLowering, ObjectError> {
    const FRAME_BYTES: u16 = 160;
    const NEXT_OFFSET: u16 = 96;
    const LAST_OFFSET: u16 = 104;
    const FLAGS_OFFSET: u16 = 112;
    const SPAN_OFFSET: u16 = 120;
    if group_count == 0 {
        return Err(ObjectError::InvalidModule("AArch64 capture-next groups"));
    }
    let output_bytes = group_count.checked_mul(16)
        .and_then(|bytes| u16::try_from(bytes).ok())
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture-next output"))?;
    let group_count_u64 = u64::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture-next groups"))?;
    let mut assembler = Aarch64Assembler::new();
    let disjoint = assembler.label()?;
    let no_pending_validation = assembler.label()?;
    let has_last_validation = assembler.label()?;
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted_empty = assembler.label()?;
    let accepted = assembler.label()?;
    let finished = assembler.label()?;
    let runtime_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.branch_zero_x(0, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(1, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(2, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 2, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 3, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    aarch64_load_u64_constant(&mut assembler, 5, group_count_u64)?;
    assembler.instruction(aarch64_cmp_x(4, 5)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_add_x_imm(5, 2, 24)?)?;
    assembler.instruction(aarch64_cmp_x(5, 2)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_add_x_imm(6, 3, output_bytes)?)?;
    assembler.instruction(aarch64_cmp_x(6, 3)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_cmp_x(5, 3)?)?;
    assembler.branch_cond(AARCH64_LS, disjoint)?;
    assembler.instruction(aarch64_cmp_x(6, 2)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.bind(disjoint)?;

    assembler.instruction(aarch64_load_w_imm(5, 2, 20)?)?;
    assembler.branch_nonzero_w(5, invalid)?;
    assembler.instruction(aarch64_load_w_imm(5, 2, 16)?)?;
    assembler.instruction(aarch64_and_low_w(6, 5, 3)?)?;
    assembler.instruction(aarch64_cmp_w(5, 6)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_load_x_imm(7, 2, 0)?)?;
    assembler.instruction(aarch64_cmp_x(7, 1)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_load_x_imm(8, 2, 8)?)?;
    assembler.instruction(aarch64_cmp_x(8, 1)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_bit_clear_w(5, 1, no_pending_validation)?;
    assembler.branch_bit_clear_w(5, 0, invalid)?;
    assembler.instruction(aarch64_cmp_x(7, 8)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.branch_bit_set_w(5, 2, invalid)?;
    assembler.bind(no_pending_validation)?;
    assembler.branch_bit_set_w(5, 0, has_last_validation)?;
    assembler.branch_nonzero_x(7, invalid)?;
    assembler.branch_nonzero_x(8, invalid)?;
    assembler.branch(validated)?;
    assembler.bind(has_last_validation)?;
    assembler.instruction(aarch64_cmp_x(7, 8)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(validated)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_store_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_load_pair_x(5, 6, 21, 0)?)?;
    assembler.instruction(aarch64_store_pair_x(5, 6, 31, i16::try_from(NEXT_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture-next local"))?)?)?;
    assembler.instruction(aarch64_load_x_imm(5, 21, 16)?)?;
    assembler.instruction(aarch64_store_x(5, 31, FLAGS_OFFSET)?)?;

    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_load_w_imm(5, 31, FLAGS_OFFSET)?)?;
    assembler.branch_bit_set_w(5, 2, finished)?;
    assembler.branch_bit_clear_w(5, 1, search)?;
    assembler.instruction(aarch64_movz_w(6, 2)?)?;
    assembler.instruction(aarch64_eor_w(5, 5, 6)?)?;
    assembler.instruction(aarch64_store_w(5, 31, FLAGS_OFFSET)?)?;
    assembler.instruction(aarch64_load_x_imm(7, 31, NEXT_OFFSET)?)?;
    assembler.instruction(aarch64_cmp_x(7, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(7, 7, 1)?)?;
    assembler.instruction(aarch64_store_x(7, 31, NEXT_OFFSET)?)?;

    assembler.bind(search)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_load_x_imm(2, 31, NEXT_OFFSET)?)?;
    assembler.instruction(aarch64_mov_x(3, 20)?)?;
    assembler.instruction(aarch64_add_x_imm(4, 31, SPAN_OFFSET)?)?;
    let selector_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(returned)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_pair_x(7, 8, 31, i16::try_from(SPAN_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture span"))?)?)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, NEXT_OFFSET)?)?;
    assembler.instruction(aarch64_cmp_x(7, 6)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_error)?;
    assembler.instruction(aarch64_cmp_x(8, 7)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_error)?;
    assembler.instruction(aarch64_cmp_x(8, 20)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_error)?;
    assembler.instruction(aarch64_cmp_x(7, 8)?)?;
    assembler.branch_cond(AARCH64_NE, nonempty)?;
    assembler.instruction(aarch64_load_w_imm(5, 31, FLAGS_OFFSET)?)?;
    assembler.branch_bit_clear_w(5, 0, accepted_empty)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, LAST_OFFSET)?)?;
    assembler.instruction(aarch64_cmp_x(6, 8)?)?;
    assembler.branch_cond(AARCH64_NE, accepted_empty)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, NEXT_OFFSET)?)?;
    assembler.instruction(aarch64_cmp_x(6, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(6, 6, 1)?)?;
    assembler.instruction(aarch64_store_x(6, 31, NEXT_OFFSET)?)?;
    assembler.branch(search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(aarch64_movz_w(5, 1)?)?;
    assembler.branch(accepted)?;
    assembler.bind(accepted_empty)?;
    assembler.instruction(aarch64_movz_w(5, 3)?)?;
    assembler.bind(accepted)?;
    assembler.instruction(aarch64_store_x(8, 31, NEXT_OFFSET)?)?;
    assembler.instruction(aarch64_store_x(8, 31, LAST_OFFSET)?)?;
    assembler.instruction(aarch64_store_w(5, 31, FLAGS_OFFSET)?)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_mov_x(2, 7)?)?;
    assembler.instruction(aarch64_mov_x(3, 8)?)?;
    assembler.instruction(aarch64_mov_x(4, 22)?)?;
    aarch64_load_u64_constant(&mut assembler, 5, group_count_u64)?;
    let materializer_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_NE, returned)?;
    assembler.instruction(aarch64_load_pair_x(6, 7, 31, i16::try_from(NEXT_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture-next local"))?)?)?;
    assembler.instruction(aarch64_store_pair_x(6, 7, 21, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(8, 31, FLAGS_OFFSET)?)?;
    assembler.instruction(aarch64_store_w(8, 21, 16)?)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_load_w_imm(5, 31, FLAGS_OFFSET)?)?;
    assembler.instruction(aarch64_and_low_w(5, 5, 1)?)?;
    assembler.instruction(aarch64_movz_w(6, 4)?)?;
    assembler.instruction(aarch64_orr_w(5, 5, 6)?)?;
    assembler.instruction(aarch64_store_w(5, 31, FLAGS_OFFSET)?)?;
    aarch64_load_u64_constant(&mut assembler, 6, u64::MAX)?;
    assembler.instruction(aarch64_mov_x(7, 6)?)?;
    for group in 0..group_count {
        assembler.instruction(aarch64_store_pair_x(
            6,
            7,
            22,
            i16::try_from(group * 16)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture output"))?,
        )?)?;
    }
    assembler.instruction(aarch64_load_pair_x(6, 7, 31, i16::try_from(NEXT_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture-next local"))?)?)?;
    assembler.instruction(aarch64_store_pair_x(6, 7, 21, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(8, 31, FLAGS_OFFSET)?)?;
    assembler.instruction(aarch64_store_w(8, 21, 16)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_error)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;

    assembler.bind(returned)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_load_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [selector_call, materializer_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(Aarch64NativeCaptureNextLowering {
        code,
        selector_call_offset: offsets[0],
        materializer_call_offset: offsets[1],
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "exact tag replay, complete validation, and transactional publication form one generated leaf"
)]
fn lower_x86_64_native_capture_materialize_v1(
    geometry: crate::capture_aot::NativeCapturePlanGeometryV1,
) -> Result<NativeCaptureMaterializerLowering, ObjectError> {
    if geometry.group_count == 0
        || geometry.group_count.checked_mul(2) != Some(geometry.tag_slot_count)
        || geometry.tag_slot_count > 32
        || geometry.native_stack_bytes == 0
        || !geometry.native_stack_bytes.is_multiple_of(16)
        || geometry.alphabet_len == 0
        || usize::try_from(geometry.start_state).ok().is_none_or(|start| start >= geometry.state_count)
    {
        return Err(ObjectError::InvalidModule("native capture materializer geometry"));
    }
    let alphabet = u32::try_from(geometry.alphabet_len)
        .map_err(|_| ObjectError::ArithmeticOverflow("capture alphabet"))?;
    let output_bytes = geometry.group_count.checked_mul(16)
        .ok_or(ObjectError::ArithmeticOverflow("capture output bytes"))?;
    let output_bytes_u32 = u32::try_from(output_bytes)
        .map_err(|_| ObjectError::ArithmeticOverflow("capture output bytes"))?;
    let class_delta = i64::try_from(geometry.byte_classes_offset)
        .ok()
        .and_then(|classes| {
            i64::try_from(geometry.transitions_offset).ok()
                .and_then(|transitions| classes.checked_sub(transitions))
        })
        .and_then(|delta| i32::try_from(delta).ok())
        .ok_or(ObjectError::ArithmeticOverflow("capture class delta"))?;
    let state_delta = i64::try_from(geometry.states_offset)
        .ok()
        .and_then(|states| {
            i64::try_from(geometry.transitions_offset).ok()
                .and_then(|transitions| states.checked_sub(transitions))
        })
        .and_then(|delta| i32::try_from(delta).ok())
        .ok_or(ObjectError::ArithmeticOverflow("capture state delta"))?;
    let mut assembler = X86Assembler::new();
    let loop_head = assembler.label()?;
    let final_state = assembler.label()?;
    let transition_action = assembler.label()?;
    let transition_done = assembler.label()?;
    let match_action = assembler.label()?;
    let match_done = assembler.label()?;
    let runtime_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    // Raw boundary validation. Output remains untouched on every rejection.
    assembler.instruction(&[0x48, 0x85, 0xff])?; // haystack
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // signed-domain length
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xca])?; // start <= end
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xf1])?; // end <= length
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?; // output
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut exact_count = vec![0x49, 0x81, 0xf9];
    exact_count.extend_from_slice(
        &u32::try_from(geometry.group_count)
            .map_err(|_| ObjectError::ArithmeticOverflow("capture group count"))?
            .to_le_bytes(),
    );
    assembler.instruction(&exact_count)?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4c, 0x89, 0xc0])?; // output extent must not wrap
    let mut add_output = vec![0x48, 0x05];
    add_output.extend_from_slice(&output_bytes_u32.to_le_bytes());
    assembler.instruction(&add_output)?;
    assembler.branch(&[0x0f, 0x82], invalid)?;

    // Five saved registers leave the variable 16-byte stack owner aligned.
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    let mut allocate = vec![0x48, 0x81, 0xec];
    allocate.extend_from_slice(
        &u32::try_from(geometry.native_stack_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("capture stack"))?
            .to_le_bytes(),
    );
    assembler.instruction(&allocate)?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // haystack -> rbx
    assembler.instruction(&[0x49, 0x89, 0xd4])?; // start -> r12
    assembler.instruction(&[0x49, 0x89, 0xcd])?; // end -> r13
    assembler.instruction(&[0x4d, 0x89, 0xc6])?; // output -> r14
    assembler.instruction(&[0x4c, 0x8d, 0x3d])?; // transitions(%rip) -> r15
    let plan_relocation = assembler.label()?;
    assembler.bind(plan_relocation)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    for slot in 0..geometry.tag_slot_count {
        x86_capture_store_rsp_imm64(&mut assembler, slot * 8, u64::MAX)?;
    }
    let mut initial_state = vec![0x41, 0xb9];
    initial_state.extend_from_slice(&geometry.start_state.to_le_bytes());
    assembler.instruction(&initial_state)?;
    assembler.instruction(&[0x4d, 0x89, 0xe3])?; // position = start

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x4d, 0x39, 0xeb])?; // position == end
    assembler.branch(&[0x0f, 0x84], final_state)?;
    assembler.instruction(&[0x42, 0x0f, 0xb6, 0x04, 0x1b])?; // haystack[position]
    let mut map_class = vec![0x41, 0x0f, 0xb6, 0x84, 0x07];
    map_class.extend_from_slice(&class_delta.to_le_bytes());
    assembler.instruction(&map_class)?;
    let mut row = vec![0x45, 0x69, 0xd1]; // r10d = state * alphabet
    row.extend_from_slice(&alphabet.to_le_bytes());
    assembler.instruction(&row)?;
    assembler.instruction(&[0x41, 0x01, 0xc2])?; // + class
    assembler.instruction(&[0x47, 0x8b, 0x0c, 0xd7])?; // next state
    assembler.instruction(&[0x43, 0x8b, 0x7c, 0xd7, 0x04])?; // action mask
    assembler.instruction(&[0x41, 0x83, 0xf9, 0xff])?;
    assembler.branch(&[0x0f, 0x84], runtime_error)?;
    assembler.instruction(&[0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], transition_done)?;
    assembler.bind(transition_action)?;
    assembler.instruction(&[0x0f, 0xbc, 0xc7])?; // bsf action -> slot
    assembler.instruction(&[0x4c, 0x89, 0x1c, 0xc4])?; // slots[slot] = position
    assembler.instruction(&[0x0f, 0xb3, 0xc7])?; // clear selected action bit
    assembler.instruction(&[0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x85], transition_action)?;
    assembler.bind(transition_done)?;
    assembler.instruction(&[0x49, 0x83, 0xc3, 0x01])?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(final_state)?;
    let mut load_match_flag = vec![0x43, 0x8b, 0x84, 0xcf];
    load_match_flag.extend_from_slice(
        &state_delta.checked_add(4)
            .ok_or(ObjectError::ArithmeticOverflow("capture state flags"))?
            .to_le_bytes(),
    );
    assembler.instruction(&load_match_flag)?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], runtime_error)?;
    let mut load_match_action = vec![0x43, 0x8b, 0xbc, 0xcf];
    load_match_action.extend_from_slice(&state_delta.to_le_bytes());
    assembler.instruction(&load_match_action)?;
    assembler.instruction(&[0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], match_done)?;
    assembler.bind(match_action)?;
    assembler.instruction(&[0x0f, 0xbc, 0xc7])?;
    assembler.instruction(&[0x4c, 0x89, 0x1c, 0xc4])?;
    assembler.instruction(&[0x0f, 0xb3, 0xc7])?;
    assembler.instruction(&[0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x85], match_action)?;
    assembler.bind(match_done)?;

    // Group zero must be the exact selector span.
    x86_capture_load_rsp_rax(&mut assembler, 0)?;
    assembler.instruction(&[0x4c, 0x39, 0xe0])?;
    assembler.branch(&[0x0f, 0x85], runtime_error)?;
    x86_capture_load_rsp_rdi(&mut assembler, 8)?;
    assembler.instruction(&[0x4c, 0x39, 0xef])?;
    assembler.branch(&[0x0f, 0x85], runtime_error)?;
    for group in 1..geometry.group_count {
        let valid = assembler.label()?;
        let unset = assembler.label()?;
        x86_capture_load_rsp_rax(&mut assembler, group * 16)?;
        x86_capture_load_rsp_rdi(&mut assembler, group * 16 + 8)?;
        assembler.instruction(&[0x48, 0x83, 0xf8, 0xff])?;
        assembler.branch(&[0x0f, 0x84], unset)?;
        assembler.instruction(&[0x48, 0x83, 0xff, 0xff])?;
        assembler.branch(&[0x0f, 0x84], runtime_error)?;
        assembler.instruction(&[0x48, 0x39, 0xf8])?; // start <= end
        assembler.branch(&[0x0f, 0x87], runtime_error)?;
        assembler.instruction(&[0x4c, 0x39, 0xe0])?; // start >= span start
        assembler.branch(&[0x0f, 0x82], runtime_error)?;
        assembler.instruction(&[0x4c, 0x39, 0xef])?; // end <= span end
        assembler.branch(&[0x0f, 0x87], runtime_error)?;
        assembler.branch(&[0xe9], valid)?;
        assembler.bind(unset)?;
        assembler.instruction(&[0x48, 0x83, 0xff, 0xff])?;
        assembler.branch(&[0x0f, 0x85], runtime_error)?;
        assembler.bind(valid)?;
    }
    // Commit only after every raw pair and group zero have closed.
    for group in 0..geometry.group_count {
        x86_capture_load_rsp_rax(&mut assembler, group * 16)?;
        x86_capture_store_r14_rax(&mut assembler, group * 16)?;
        x86_capture_load_rsp_rdi(&mut assembler, group * 16 + 8)?;
        x86_capture_store_r14_rdi(&mut assembler, group * 16 + 8)?;
    }
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_error)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(returned)?;
    let mut release = vec![0x48, 0x81, 0xc4];
    release.extend_from_slice(
        &u32::try_from(geometry.native_stack_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("capture stack"))?
            .to_le_bytes(),
    );
    assembler.instruction(&release)?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativeCaptureMaterializerLowering {
        plan_relocation_offset: finished.label_offset(plan_relocation)?,
        code: finished.code,
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "iterator validation, nullable progress, two local calls, and transactional publication stay auditable together"
)]
fn lower_x86_64_native_capture_next_v1(
    group_count: usize,
) -> Result<NativeCaptureNextLowering, ObjectError> {
    const FRAME_BYTES: u8 = 48;
    if group_count == 0 {
        return Err(ObjectError::InvalidModule("native capture-next group count"));
    }
    let group_count_u32 = u32::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("capture-next groups"))?;
    let output_bytes = group_count.checked_mul(16)
        .and_then(|bytes| u32::try_from(bytes).ok())
        .ok_or(ObjectError::ArithmeticOverflow("capture-next output"))?;
    let mut assembler = X86Assembler::new();
    let disjoint = assembler.label()?;
    let no_pending_validation = assembler.label()?;
    let has_last_validation = assembler.label()?;
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted_empty = assembler.label()?;
    let accepted = assembler.label()?;
    let finished = assembler.label()?;
    let runtime_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    // (haystack, length, state, slots, exact_slot_count)
    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc2, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut exact_count = vec![0x49, 0x81, 0xf8];
    exact_count.extend_from_slice(&group_count_u32.to_le_bytes());
    assembler.instruction(&exact_count)?;
    assembler.branch(&[0x0f, 0x85], invalid)?;

    // The mutable state and output arrays must be complete, nonwrapping, and
    // disjoint. Haystack aliasing is harmless because all source reads finish
    // before either successful publication.
    assembler.instruction(&[0x49, 0x89, 0xd1])?; // state end
    assembler.instruction(&[0x49, 0x83, 0xc1, 0x18])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.instruction(&[0x49, 0x89, 0xca])?; // output end
    let mut add_output = vec![0x49, 0x81, 0xc2];
    add_output.extend_from_slice(&output_bytes.to_le_bytes());
    assembler.instruction(&add_output)?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.instruction(&[0x49, 0x39, 0xc9])?; // state_end <= output
    assembler.branch(&[0x0f, 0x86], disjoint)?;
    assembler.instruction(&[0x49, 0x39, 0xd2])?; // output_end <= state
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.bind(disjoint)?;

    assembler.instruction(&[0x83, 0x7a, 0x14, 0x00])?; // reserved
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x8b, 0x42, 0x10])?; // flags
    assembler.instruction(&[0x41, 0x89, 0xc2])?;
    assembler.instruction(&[0x41, 0x83, 0xe2, 0x07])?;
    assembler.instruction(&[0x44, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4c, 0x8b, 0x0a])?; // next
    assembler.instruction(&[0x49, 0x39, 0xf1])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4c, 0x8b, 0x52, 0x08])?; // last
    assembler.instruction(&[0x49, 0x39, 0xf2])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0xa8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], no_pending_validation)?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xd1])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0xa8, 0x04])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.bind(no_pending_validation)?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x85], has_last_validation)?;
    assembler.instruction(&[0x4d, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.branch(&[0xe9], validated)?;
    assembler.bind(has_last_validation)?;
    assembler.instruction(&[0x4d, 0x39, 0xd1])?; // next >= last
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(validated)?;

    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // haystack
    assembler.instruction(&[0x49, 0x89, 0xf4])?; // length
    assembler.instruction(&[0x49, 0x89, 0xd5])?; // state
    assembler.instruction(&[0x49, 0x89, 0xce])?; // output
    assembler.instruction(&[0x49, 0x8b, 0x45, 0x00])?;
    assembler.instruction(&[0x48, 0x89, 0x04, 0x24])?;
    assembler.instruction(&[0x49, 0x8b, 0x45, 0x08])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x08])?;
    assembler.instruction(&[0x49, 0x8b, 0x45, 0x10])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x10])?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0xa8, 0x04])?;
    assembler.branch(&[0x0f, 0x85], finished)?;
    assembler.instruction(&[0xa8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], search)?;
    assembler.instruction(&[0x83, 0xe0, 0xfd])?;
    assembler.instruction(&[0x89, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x4c, 0x8b, 0x0c, 0x24])?;
    assembler.instruction(&[0x4d, 0x39, 0xe1])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x48, 0x83, 0x04, 0x24, 0x01])?;

    assembler.bind(search)?;
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x4c, 0x89, 0xe6])?;
    assembler.instruction(&[0x48, 0x8b, 0x14, 0x24])?;
    assembler.instruction(&[0x4c, 0x89, 0xe1])?;
    assembler.instruction(&[0x4c, 0x8d, 0x44, 0x24, 0x18])?;
    assembler.instruction(&[0xe8])?;
    let selector_call = assembler.label()?;
    assembler.bind(selector_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x18])?; // start
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x20])?; // end
    assembler.instruction(&[0x4c, 0x3b, 0x0c, 0x24])?;
    assembler.branch(&[0x0f, 0x82], runtime_error)?;
    assembler.instruction(&[0x4d, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x82], runtime_error)?;
    assembler.instruction(&[0x4d, 0x39, 0xe2])?;
    assembler.branch(&[0x0f, 0x87], runtime_error)?;
    assembler.instruction(&[0x4d, 0x39, 0xd1])?;
    assembler.branch(&[0x0f, 0x85], nonempty)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], accepted_empty)?;
    assembler.instruction(&[0x4c, 0x3b, 0x54, 0x24, 0x08])?;
    assembler.branch(&[0x0f, 0x85], accepted_empty)?;
    assembler.instruction(&[0x4c, 0x3b, 0x24, 0x24])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x48, 0x83, 0x04, 0x24, 0x01])?;
    assembler.branch(&[0xe9], search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], accepted)?;
    assembler.bind(accepted_empty)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(accepted)?;
    assembler.instruction(&[0x4c, 0x89, 0x14, 0x24])?;
    assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, 0x08])?;
    assembler.instruction(&[0x89, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x4c, 0x89, 0xe6])?;
    assembler.instruction(&[0x4c, 0x89, 0xca])?;
    assembler.instruction(&[0x4c, 0x89, 0xd1])?;
    assembler.instruction(&[0x4d, 0x89, 0xf0])?;
    let mut materialize_count = vec![0x41, 0xb9];
    materialize_count.extend_from_slice(&group_count_u32.to_le_bytes());
    assembler.instruction(&materialize_count)?;
    assembler.instruction(&[0xe8])?;
    let materializer_call = assembler.label()?;
    assembler.bind(materializer_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x85], returned)?;
    assembler.instruction(&[0x4c, 0x8b, 0x0c, 0x24])?;
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x4d, 0x89, 0x4d, 0x00])?;
    assembler.instruction(&[0x4d, 0x89, 0x55, 0x08])?;
    assembler.instruction(&[0x49, 0x89, 0x45, 0x10])?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x83, 0xe0, 0x01])?;
    assembler.instruction(&[0x83, 0xc8, 0x04])?;
    assembler.instruction(&[0x89, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0xc7, 0xc0, 0xff, 0xff, 0xff, 0xff])?;
    assembler.instruction(&[0x48, 0x89, 0xc7])?;
    for group in 0..group_count {
        x86_capture_store_r14_rax(&mut assembler, group * 16)?;
        x86_capture_store_r14_rdi(&mut assembler, group * 16 + 8)?;
    }
    assembler.instruction(&[0x4c, 0x8b, 0x0c, 0x24])?;
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x4d, 0x89, 0x4d, 0x00])?;
    assembler.instruction(&[0x4d, 0x89, 0x55, 0x08])?;
    assembler.instruction(&[0x49, 0x89, 0x45, 0x10])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_error)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished_code = assembler.finish_with_label_offsets()?;
    Ok(NativeCaptureNextLowering {
        selector_call_offset: finished_code.label_offset(selector_call)?,
        materializer_call_offset: finished_code.label_offset(materializer_call)?,
        code: finished_code.code,
    })
}

fn x86_capture_store_rsp_imm64(
    assembler: &mut X86Assembler,
    offset: usize,
    value: u64,
) -> Result<(), ObjectError> {
    if value != u64::MAX {
        return Err(ObjectError::InvalidModule("capture stack immediate"));
    }
    if let Some(offset) = u8::try_from(offset).ok().filter(|offset| *offset <= 127) {
        assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, offset, 0xff, 0xff, 0xff, 0xff])?;
    } else {
        let mut instruction = vec![0x48, 0xc7, 0x84, 0x24];
        instruction.extend_from_slice(
            &u32::try_from(offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("capture stack offset"))?
                .to_le_bytes(),
        );
        instruction.extend_from_slice(&[0xff; 4]);
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_capture_load_rsp_rax(
    assembler: &mut X86Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    x86_capture_rsp_load(assembler, offset, 0)
}

fn x86_capture_load_rsp_rdi(
    assembler: &mut X86Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    x86_capture_rsp_load(assembler, offset, 7)
}

fn x86_capture_rsp_load(
    assembler: &mut X86Assembler,
    offset: usize,
    register: u8,
) -> Result<(), ObjectError> {
    if register > 7 {
        return Err(ObjectError::InvalidModule("capture load register"));
    }
    if offset == 0 {
        assembler.instruction(&[0x48, 0x8b, 0x04 | register << 3, 0x24])?;
    } else if let Some(offset) = u8::try_from(offset).ok().filter(|offset| *offset <= 127) {
        assembler.instruction(&[0x48, 0x8b, 0x44 | register << 3, 0x24, offset])?;
    } else {
        let mut instruction = vec![0x48, 0x8b, 0x84 | register << 3, 0x24];
        instruction.extend_from_slice(
            &u32::try_from(offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("capture stack offset"))?
                .to_le_bytes(),
        );
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_capture_store_r14_rax(
    assembler: &mut X86Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    x86_capture_r14_store(assembler, offset, 0)
}

fn x86_capture_store_r14_rdi(
    assembler: &mut X86Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    x86_capture_r14_store(assembler, offset, 7)
}

fn x86_capture_r14_store(
    assembler: &mut X86Assembler,
    offset: usize,
    register: u8,
) -> Result<(), ObjectError> {
    if register > 7 {
        return Err(ObjectError::InvalidModule("capture store register"));
    }
    if offset == 0 {
        assembler.instruction(&[0x49, 0x89, 0x06 | register << 3])?;
    } else if let Some(offset) = u8::try_from(offset).ok().filter(|offset| *offset <= 127) {
        assembler.instruction(&[0x49, 0x89, 0x46 | register << 3, offset])?;
    } else {
        let mut instruction = vec![0x49, 0x89, 0x86 | register << 3];
        instruction.extend_from_slice(
            &u32::try_from(offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("capture output offset"))?
                .to_le_bytes(),
        );
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

impl X86Assembler {
    fn new() -> Self {
        Self {
            code: Vec::with_capacity(256),
            labels: Vec::new(),
            fixups: Vec::new(),
            instruction_offsets: Vec::new(),
        }
    }

    fn label(&mut self) -> Result<X86Label, ObjectError> {
        let label = self.labels.len();
        self.labels
            .try_reserve(1)
            .map_err(|_| ObjectError::Allocation("x86 labels"))?;
        self.labels.push(None);
        Ok(label)
    }

    fn bind(&mut self, label: X86Label) -> Result<(), ObjectError> {
        let slot = self
            .labels
            .get_mut(label)
            .ok_or(ObjectError::InvalidModule("x86 label index"))?;
        if slot.is_some() {
            return Err(ObjectError::InvalidModule("x86 label bound twice"));
        }
        *slot = Some(self.code.len());
        Ok(())
    }

    fn instruction(&mut self, bytes: &[u8]) -> Result<usize, ObjectError> {
        let offset = self.code.len();
        self.instruction_offsets
            .try_reserve(1)
            .map_err(|_| ObjectError::Allocation("x86 audit"))?;
        self.instruction_offsets.push(offset);
        push_bytes(&mut self.code, bytes)?;
        Ok(offset)
    }

    fn branch(&mut self, opcode: &[u8], label: X86Label) -> Result<(), ObjectError> {
        if self.labels.get(label).is_none() {
            return Err(ObjectError::InvalidModule("x86 branch label index"));
        }
        // Record one stable rel32 representation while lowering. `finish`
        // relaxes every eligible edge together after all labels are bound;
        // doing that transactionally lets forward and backward branches both
        // use rel8 without invalidating labels, fixups, or relocation fields.
        let short_opcode = match opcode {
            [0xe9] => Some(0xeb),
            [0x0f, condition @ 0x80..=0x8f] => condition.checked_sub(0x10),
            _ => None,
        };
        let instruction = self.instruction(opcode)?;
        let displacement = self.code.len();
        push_bytes(&mut self.code, &[0; 4])?;
        self.fixups
            .try_reserve(1)
            .map_err(|_| ObjectError::Allocation("x86 fixups"))?;
        self.fixups.push(X86Fixup {
            instruction,
            displacement,
            label,
            short_opcode,
            long_bytes: opcode
                .len()
                .checked_add(4)
                .ok_or(ObjectError::ArithmeticOverflow("x86 branch size"))?,
        });
        Ok(())
    }

    fn remap_offset(
        &self,
        offset: usize,
        removed_branches: &[bool],
        shortened: &[bool],
    ) -> Result<usize, ObjectError> {
        let mut removed_bytes = 0_usize;
        for ((fixup, &is_removed), &is_short) in
            self.fixups.iter().zip(removed_branches).zip(shortened)
        {
            if !is_removed && !is_short {
                continue;
            }
            let end = fixup
                .instruction
                .checked_add(fixup.long_bytes)
                .ok_or(ObjectError::ArithmeticOverflow("x86 relaxed branch extent"))?;
            if end <= offset {
                removed_bytes = removed_bytes
                    .checked_add(
                        fixup
                            .long_bytes
                            .checked_sub(if is_removed { 0 } else { 2 })
                            .ok_or(ObjectError::InvalidModule("x86 relaxed branch size"))?,
                    )
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 relaxed offset removal",
                    ))?;
            } else if fixup.instruction < offset {
                return Err(ObjectError::InvalidModule(
                    "x86 offset falls inside a relaxed branch",
                ));
            }
        }
        offset
            .checked_sub(removed_bytes)
            .ok_or(ObjectError::ArithmeticOverflow("x86 relaxed offset"))
    }

    fn invert_branch_fallthroughs(&mut self, removed: &mut [bool]) -> Result<(), ObjectError> {
        let mut shortened = Vec::new();
        shortened
            .try_reserve_exact(self.fixups.len())
            .map_err(|_| ObjectError::Allocation("x86 inversion"))?;
        shortened.resize(self.fixups.len(), false);
        loop {
            let mut changed = false;
            for conditional_index in 0..self.fixups.len() {
                if removed[conditional_index] {
                    continue;
                }
                let conditional = self.fixups[conditional_index];
                if !matches!(conditional.short_opcode, Some(0x70..=0x7f)) {
                    continue;
                }
                let Some(jump_index) =
                    (conditional_index + 1..self.fixups.len()).find(|&index| !removed[index])
                else {
                    continue;
                };
                let jump = self.fixups[jump_index];
                if jump.short_opcode != Some(0xeb) {
                    continue;
                }
                let conditional_end = self.remap_offset(
                    conditional
                        .instruction
                        .checked_add(conditional.long_bytes)
                        .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?,
                    removed,
                    &shortened,
                )?;
                let jump_instruction = self.remap_offset(jump.instruction, removed, &shortened)?;
                if conditional_end != jump_instruction {
                    continue;
                }
                let target = self.labels[conditional.label]
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                let target = self.remap_offset(target, removed, &shortened)?;
                let jump_end = self.remap_offset(
                    jump.instruction
                        .checked_add(jump.long_bytes)
                        .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?,
                    removed,
                    &shortened,
                )?;
                if target != jump_end {
                    continue;
                }
                let jump_target = self.labels[jump.label]
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                if jump_target == jump.instruction
                    || self
                        .fixups
                        .binary_search_by_key(&jump_target, |candidate| candidate.instruction)
                        .is_ok_and(|index| removed[index])
                {
                    continue;
                }

                let opcode = self.code.get_mut(conditional.instruction + 1).ok_or(
                    ObjectError::InvalidModule("x86 conditional branch outside code"),
                )?;
                if *opcode & 0xf0 != 0x80 {
                    return Err(ObjectError::InvalidModule(
                        "x86 conditional branch opcode mismatch",
                    ));
                }
                *opcode ^= 1;
                self.fixups[conditional_index].short_opcode =
                    conditional.short_opcode.map(|v| v ^ 1);
                self.fixups[conditional_index].label = jump.label;
                removed[jump_index] = true;
                changed = true;
            }
            if !changed {
                return Ok(());
            }
        }
    }

    fn thread_branch_targets(&mut self, removed: &[bool]) -> Result<(), ObjectError> {
        let mut labels = Vec::new();
        labels
            .try_reserve_exact(self.fixups.len())
            .map_err(|_| ObjectError::Allocation("x86 threading"))?;
        let mut shortened = Vec::new();
        shortened
            .try_reserve_exact(self.fixups.len())
            .map_err(|_| ObjectError::Allocation("x86 threading"))?;
        shortened.resize(self.fixups.len(), false);

        for (index, fixup) in self.fixups.iter().enumerate() {
            let original = fixup.label;
            let mut label = original;
            let mut resolved = None;
            let mut retained_cycle_label = None;
            let mut direct_target_removed = false;

            // There can be at most one direct branch at an instruction
            // boundary and at most `fixups.len()` distinct trampoline
            // instructions. One additional lookup therefore distinguishes a
            // finite chain from a cycle without allocating a visited set.
            for _ in 0..=self.fixups.len() {
                let target = self
                    .labels
                    .get(label)
                    .copied()
                    .flatten()
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                let Ok(index) = self
                    .fixups
                    .binary_search_by_key(&target, |candidate| candidate.instruction)
                else {
                    resolved = Some(label);
                    break;
                };
                let trampoline = self.fixups[index];
                if trampoline.short_opcode != Some(0xeb) {
                    resolved = Some(label);
                    break;
                }
                if removed[index] {
                    direct_target_removed |= label == original;
                } else {
                    retained_cycle_label = Some(label);
                }
                label = trampoline.label;
            }

            // Retaining the original edge for a jump cycle preserves the
            // exact looping CFG. Thread a finite chain only when its resolved
            // edge can use rel8 before any other shortening; later monotone
            // compaction can only bring the destination closer. This avoids
            // trading a nearby trampoline for a larger source branch.
            let label = if let Some(label) = resolved {
                label
            } else if direct_target_removed {
                retained_cycle_label
                    .ok_or(ObjectError::InvalidModule("x86 removed trampoline cycle"))?
            } else {
                original
            };
            let raw_target =
                self.labels[label].ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
            let instruction = self.remap_offset(fixup.instruction, removed, &shortened)?;
            let mut target = self.remap_offset(raw_target, removed, &shortened)?;
            let raw_end = fixup
                .instruction
                .checked_add(fixup.long_bytes)
                .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?;
            if raw_end <= raw_target {
                target = target
                    .checked_sub(
                        fixup
                            .long_bytes
                            .checked_sub(2)
                            .ok_or(ObjectError::InvalidModule("x86 relaxed branch size"))?,
                    )
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 hypothetical threaded target",
                    ))?;
            }
            let after = instruction
                .checked_add(2)
                .ok_or(ObjectError::ArithmeticOverflow("x86 short branch base"))?;
            let delta = i64::try_from(target)
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 threaded branch target"))?
                .checked_sub(
                    i64::try_from(after)
                        .map_err(|_| ObjectError::ArithmeticOverflow("x86 short branch base"))?,
                )
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 threaded branch displacement",
                ))?;
            labels.push(
                if !removed[index]
                    && (direct_target_removed
                        || fixup.short_opcode.is_some() && i8::try_from(delta).is_ok())
                {
                    label
                } else {
                    original
                },
            );
        }
        for (fixup, label) in self.fixups.iter_mut().zip(labels) {
            fixup.label = label;
        }
        Ok(())
    }

    fn remove_unreachable_branches(&self, removed: &mut [bool]) -> Result<(), ObjectError> {
        if removed.len() != self.fixups.len() {
            return Err(ObjectError::InvalidModule("x86 reachability bitmap extent"));
        }
        let instruction_count = self
            .instruction_offsets
            .len()
            .checked_sub(1)
            .ok_or(ObjectError::InvalidModule("x86 instruction sentinel"))?;
        if instruction_count == 0 {
            return Ok(());
        }

        let mut reachable = Vec::new();
        reachable
            .try_reserve_exact(instruction_count)
            .map_err(|_| ObjectError::Allocation("x86 reachability"))?;
        reachable.resize(instruction_count, false);
        let mut worklist = Vec::new();
        worklist
            .try_reserve_exact(instruction_count)
            .map_err(|_| ObjectError::Allocation("x86 reachability"))?;
        reachable[0] = true;
        worklist.push(0_usize);

        while let Some(index) = worklist.pop() {
            let instruction = self.instruction_offsets[index];
            let next = index.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
                "x86 reachability successor",
            ))?;
            let enqueue = |successor: usize, reachable: &mut [bool], worklist: &mut Vec<usize>| {
                if successor < instruction_count && !reachable[successor] {
                    reachable[successor] = true;
                    worklist.push(successor);
                }
            };

            if let Ok(fixup_index) = self
                .fixups
                .binary_search_by_key(&instruction, |candidate| candidate.instruction)
            {
                if removed[fixup_index] {
                    enqueue(next, &mut reachable, &mut worklist);
                    continue;
                }
                let fixup = self.fixups[fixup_index];
                let target = self.labels[fixup.label]
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                let target = self
                    .instruction_offsets
                    .binary_search(&target)
                    .map_err(|_| {
                        ObjectError::InvalidModule(
                            "x86 branch target is not an instruction boundary",
                        )
                    })?;
                enqueue(target, &mut reachable, &mut worklist);
                if fixup.short_opcode != Some(0xeb) {
                    enqueue(next, &mut reachable, &mut worklist);
                }
                continue;
            }

            let end = self.instruction_offsets[next];
            let bytes = self
                .code
                .get(instruction..end)
                .ok_or(ObjectError::InvalidModule("x86 instruction outside code"))?;
            // Raw bytes do not carry enough information to distinguish an
            // internal `jmp rel32` from a relocated external tail jump. The
            // fixups above are the only branch targets this pass can resolve,
            // while a RET is unambiguously a local terminator.
            let terminates = bytes == [0xc3];
            if !terminates {
                enqueue(next, &mut reachable, &mut worklist);
            }
        }

        for (index, fixup) in self.fixups.iter().enumerate() {
            let instruction = self
                .instruction_offsets
                .binary_search(&fixup.instruction)
                .map_err(|_| ObjectError::InvalidModule("x86 fixup instruction boundary"))?;
            if instruction >= instruction_count {
                return Err(ObjectError::InvalidModule("x86 fixup after code"));
            }
            if !reachable[instruction] {
                removed[index] = true;
            }
        }
        Ok(())
    }

    fn finish_with_label_offsets(mut self) -> Result<X86Finished, ObjectError> {
        self.instruction_offsets.try_reserve(1).map_err(|_| {
            ObjectError::Allocation("x86 instruction sentinel")
        })?;
        self.instruction_offsets.push(self.code.len());
        for fixup in &self.fixups {
            let target = self
                .labels
                .get(fixup.label)
                .copied()
                .flatten()
                .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
            if self.instruction_offsets.binary_search(&target).is_err() {
                return Err(ObjectError::InvalidModule(
                    "x86 branch target is not an instruction boundary",
                ));
            }
        }
        // A direct branch to its own fallthrough has no observable effect,
        // conditional or unconditional. Remove these edges before sizing the
        // remaining branches so their bytes can also make more rel8 forms fit.
        let mut removed = Vec::new();
        removed
            .try_reserve_exact(self.fixups.len())
            .map_err(|_| ObjectError::Allocation("x86 dead branches"))?;
        removed.resize(self.fixups.len(), false);
        self.invert_branch_fallthroughs(&mut removed)?;
        self.thread_branch_targets(&removed)?;
        self.remove_unreachable_branches(&mut removed)?;
        let mut shortened = Vec::new();
        shortened
            .try_reserve_exact(self.fixups.len())
            .map_err(|_| ObjectError::Allocation("x86 relaxation"))?;
        shortened.resize(self.fixups.len(), false);

        // Deletion is monotone too: removing one fallthrough edge can expose
        // another branch whose entire intervening path has disappeared.
        loop {
            let mut changed = false;
            for (index, fixup) in self.fixups.iter().enumerate() {
                if removed[index] || fixup.short_opcode.is_none() {
                    continue;
                }
                let raw_target = self.labels[fixup.label]
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                let raw_end = fixup
                    .instruction
                    .checked_add(fixup.long_bytes)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?;
                if raw_end > raw_target {
                    continue;
                }
                let instruction = self.remap_offset(fixup.instruction, &removed, &shortened)?;
                let target = self
                    .remap_offset(raw_target, &removed, &shortened)?
                    .checked_sub(fixup.long_bytes)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 hypothetical dead branch target",
                    ))?;
                if target == instruction {
                    removed[index] = true;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }

        // Branch relaxation is monotone: shortening an intervening edge can
        // only bring a target closer. Iterate to a fixed point so an edge
        // made rel8-reachable by another shrink is also selected.
        loop {
            let mut changed = false;
            for (index, fixup) in self.fixups.iter().enumerate() {
                if removed[index] || shortened[index] || fixup.short_opcode.is_none() {
                    continue;
                }
                let raw_target = self.labels[fixup.label]
                    .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
                let instruction = self.remap_offset(fixup.instruction, &removed, &shortened)?;
                let mut target = self.remap_offset(raw_target, &removed, &shortened)?;
                let raw_end = fixup
                    .instruction
                    .checked_add(fixup.long_bytes)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?;
                if raw_end <= raw_target {
                    target = target
                        .checked_sub(
                            fixup
                                .long_bytes
                                .checked_sub(2)
                                .ok_or(ObjectError::InvalidModule("x86 relaxed branch size"))?,
                        )
                        .ok_or(ObjectError::ArithmeticOverflow(
                            "x86 hypothetical relaxed target",
                        ))?;
                }
                let after = instruction
                    .checked_add(2)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 short branch base"))?;
                let delta =
                    i64::try_from(target)
                        .map_err(|_| ObjectError::ArithmeticOverflow("x86 short branch target"))?
                        .checked_sub(i64::try_from(after).map_err(|_| {
                            ObjectError::ArithmeticOverflow("x86 short branch base")
                        })?)
                        .ok_or(ObjectError::ArithmeticOverflow(
                            "x86 short branch displacement",
                        ))?;
                if i8::try_from(delta).is_ok() {
                    shortened[index] = true;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }

        let mut code = Vec::new();
        code.try_reserve_exact(self.remap_offset(self.code.len(), &removed, &shortened)?)
            .map_err(|_| ObjectError::Allocation("x86 relaxed code"))?;
        let mut cursor = 0_usize;
        for (index, fixup) in self.fixups.iter().enumerate() {
            push_bytes(
                &mut code,
                self.code
                    .get(cursor..fixup.instruction)
                    .ok_or(ObjectError::InvalidModule("x86 fixup order"))?,
            )?;
            let end = fixup
                .instruction
                .checked_add(fixup.long_bytes)
                .ok_or(ObjectError::ArithmeticOverflow("x86 branch extent"))?;
            if removed[index] {
                // The branch targets the instruction that now follows it.
            } else if shortened[index] {
                push_bytes(
                    &mut code,
                    &[
                        fixup.short_opcode.ok_or(ObjectError::InvalidModule(
                            "x86 relaxed branch has no short opcode",
                        ))?,
                        0,
                    ],
                )?;
            } else {
                push_bytes(
                    &mut code,
                    self.code
                        .get(fixup.instruction..end)
                        .ok_or(ObjectError::InvalidModule("x86 fixup outside code"))?,
                )?;
            }
            cursor = end;
        }
        push_bytes(
            &mut code,
            self.code
                .get(cursor..)
                .ok_or(ObjectError::InvalidModule("x86 relaxed code tail"))?,
        )?;

        let mut label_offsets = Vec::new();
        label_offsets
            .try_reserve_exact(self.labels.len())
            .map_err(|_| ObjectError::Allocation("x86 label remap"))?;
        for &offset in &self.labels {
            label_offsets.push(
                offset
                    .map(|offset| self.remap_offset(offset, &removed, &shortened))
                    .transpose()?,
            );
        }
        for (index, fixup) in self.fixups.iter().enumerate() {
            if removed[index] {
                continue;
            }
            let instruction = self.remap_offset(fixup.instruction, &removed, &shortened)?;
            let target = label_offsets[fixup.label]
                .ok_or(ObjectError::InvalidModule("unbound x86 branch label"))?;
            if shortened[index] {
                let after = instruction
                    .checked_add(2)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 short branch base"))?;
                let delta =
                    i64::try_from(target)
                        .map_err(|_| ObjectError::ArithmeticOverflow("x86 short branch target"))?
                        .checked_sub(i64::try_from(after).map_err(|_| {
                            ObjectError::ArithmeticOverflow("x86 short branch base")
                        })?)
                        .ok_or(ObjectError::ArithmeticOverflow(
                            "x86 short branch displacement",
                        ))?;
                let delta = i8::try_from(delta)
                    .map_err(|_| ObjectError::InvalidModule("x86 short branch is out of range"))?;
                *code
                    .get_mut(instruction + 1)
                    .ok_or(ObjectError::InvalidModule("x86 short fixup outside code"))? =
                    delta.to_le_bytes()[0];
            } else {
                let opcode_bytes = fixup
                    .displacement
                    .checked_sub(fixup.instruction)
                    .ok_or(ObjectError::InvalidModule("x86 branch opcode extent"))?;
                let displacement = instruction
                    .checked_add(opcode_bytes)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 branch displacement"))?;
                let after = displacement
                    .checked_add(4)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 branch base"))?;
                let delta = i64::try_from(target)
                    .map_err(|_| ObjectError::ArithmeticOverflow("x86 branch target"))?
                    .checked_sub(
                        i64::try_from(after)
                            .map_err(|_| ObjectError::ArithmeticOverflow("x86 branch base"))?,
                    )
                    .ok_or(ObjectError::ArithmeticOverflow("x86 branch displacement"))?;
                let delta = i32::try_from(delta)
                    .map_err(|_| ObjectError::InvalidModule("x86 branch is out of range"))?;
                let end = displacement
                    .checked_add(4)
                    .ok_or(ObjectError::ArithmeticOverflow("x86 fixup extent"))?;
                code.get_mut(displacement..end)
                    .ok_or(ObjectError::InvalidModule("x86 fixup outside code"))?
                    .copy_from_slice(&delta.to_le_bytes());
            }
        }
        Ok(X86Finished {
            code,
            label_offsets,
        })
    }

    #[cfg(test)]
    fn finish(self) -> Result<Vec<u8>, ObjectError> {
        Ok(self.finish_with_label_offsets()?.code)
    }
}

// The regex-redux entry has one public pointer argument. Its fixed request is
// nine native words: haystack pointer/length, two scratch pointer/capacity
// pairs, report pointer/capacity, and the receipt pointer. The frame keeps all
// untrusted request words and stage scalars away from the 1 KiB private report
// transaction. Six callee-saved pushes leave entry RSP at 8 (mod 16), so this
// 8 (mod 16) frame aligns every ordinary Span call.
const X86_REGEX_REDUX_FRAME_BYTES: u32 = 1_352;
const X86_REGEX_REDUX_SPAN_OFFSET: usize = 0;
const X86_REGEX_REDUX_HAYSTACK_OFFSET: usize = 32;
const X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET: usize = 40;
const X86_REGEX_REDUX_SCRATCH_A_OFFSET: usize = 48;
const X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET: usize = 56;
const X86_REGEX_REDUX_SCRATCH_B_OFFSET: usize = 64;
const X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET: usize = 72;
const X86_REGEX_REDUX_REPORT_OFFSET: usize = 80;
const X86_REGEX_REDUX_REPORT_CAP_OFFSET: usize = 88;
const X86_REGEX_REDUX_RECEIPT_OFFSET: usize = 96;
const X86_REGEX_REDUX_START_OFFSET: usize = 104;
const X86_REGEX_REDUX_COPIED_OFFSET: usize = 112;
const X86_REGEX_REDUX_DEST_LEN_OFFSET: usize = 120;
const X86_REGEX_REDUX_CLEAN_LEN_OFFSET: usize = 128;
const X86_REGEX_REDUX_COUNTS_OFFSET: usize = 136;
const X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET: usize = 208;
const X86_REGEX_REDUX_REQUEST_OFFSET: usize = 248;
const X86_REGEX_REDUX_REQUEST_END_OFFSET: usize = 256;
const X86_REGEX_REDUX_HAYSTACK_END_OFFSET: usize = 264;
const X86_REGEX_REDUX_SCRATCH_A_END_OFFSET: usize = 272;
const X86_REGEX_REDUX_SCRATCH_B_END_OFFSET: usize = 280;
const X86_REGEX_REDUX_REPORT_END_OFFSET: usize = 288;
const X86_REGEX_REDUX_RECEIPT_END_OFFSET: usize = 296;
const X86_REGEX_REDUX_REPORT_TEMP_OFFSET: usize = 320;

fn x86_regex_redux_rsp_load(
    assembler: &mut X86Assembler,
    register: u8,
    offset: usize,
) -> Result<(), ObjectError> {
    if register > 7 {
        return Err(ObjectError::InvalidModule(
            "regex-redux stack load register",
        ));
    }
    let offset = u32::try_from(offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux stack load"))?;
    let mut instruction = vec![0x48, 0x8b, 0x84 | register << 3, 0x24];
    instruction.extend_from_slice(&offset.to_le_bytes());
    assembler.instruction(&instruction)?;
    Ok(())
}

fn x86_regex_redux_rsp_store(
    assembler: &mut X86Assembler,
    register: u8,
    offset: usize,
) -> Result<(), ObjectError> {
    if register > 7 {
        return Err(ObjectError::InvalidModule(
            "regex-redux stack store register",
        ));
    }
    let offset = u32::try_from(offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux stack store"))?;
    let mut instruction = vec![0x48, 0x89, 0x84 | register << 3, 0x24];
    instruction.extend_from_slice(&offset.to_le_bytes());
    assembler.instruction(&instruction)?;
    Ok(())
}

fn x86_regex_redux_rsp_zero(
    assembler: &mut X86Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x31, 0xc0])?;
    x86_regex_redux_rsp_store(assembler, 0, offset)
}

fn x86_regex_redux_load_request_word(
    assembler: &mut X86Assembler,
    request_offset: u8,
    stack_offset: usize,
) -> Result<(), ObjectError> {
    if request_offset == 0 {
        assembler.instruction(&[0x48, 0x8b, 0x07])?;
    } else {
        assembler.instruction(&[0x48, 0x8b, 0x47, request_offset])?;
    }
    x86_regex_redux_rsp_store(assembler, 0, stack_offset)
}

fn x86_regex_redux_pointer_end(
    assembler: &mut X86Assembler,
    base_offset: usize,
    length_offset: usize,
    end_offset: usize,
    invalid: X86Label,
) -> Result<(), ObjectError> {
    x86_regex_redux_rsp_load(assembler, 0, base_offset)?;
    x86_regex_redux_rsp_load(assembler, 1, length_offset)?;
    assembler.instruction(&[0x48, 0x01, 0xc8])?; // add rcx, rax
    assembler.branch(&[0x0f, 0x82], invalid)?; // carry
    x86_regex_redux_rsp_store(assembler, 0, end_offset)
}

fn x86_regex_redux_fixed_pointer_end(
    assembler: &mut X86Assembler,
    base_offset: usize,
    bytes: u32,
    end_offset: usize,
    invalid: X86Label,
) -> Result<(), ObjectError> {
    x86_regex_redux_rsp_load(assembler, 0, base_offset)?;
    let mut add = vec![0x48, 0x05];
    add.extend_from_slice(&bytes.to_le_bytes());
    assembler.instruction(&add)?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    x86_regex_redux_rsp_store(assembler, 0, end_offset)
}

/// Require two complete caller-declared ranges to be disjoint. Empty ranges
/// naturally pass because either end is equal to its base.
fn x86_regex_redux_disjoint(
    assembler: &mut X86Assembler,
    first_base: usize,
    first_end: usize,
    second_base: usize,
    second_end: usize,
    invalid: X86Label,
) -> Result<(), ObjectError> {
    let disjoint = assembler.label()?;
    x86_regex_redux_rsp_load(assembler, 0, first_end)?;
    x86_regex_redux_rsp_load(assembler, 1, first_base)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // first_end - first_base
    assembler.branch(&[0x0f, 0x84], disjoint)?;
    x86_regex_redux_rsp_load(assembler, 0, second_end)?;
    x86_regex_redux_rsp_load(assembler, 1, second_base)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // second_end - second_base
    assembler.branch(&[0x0f, 0x84], disjoint)?;
    x86_regex_redux_rsp_load(assembler, 0, first_end)?;
    x86_regex_redux_rsp_load(assembler, 1, second_base)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // first_end - second_base
    assembler.branch(&[0x0f, 0x86], disjoint)?;
    x86_regex_redux_rsp_load(assembler, 0, second_end)?;
    x86_regex_redux_rsp_load(assembler, 1, first_base)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // second_end - first_base
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.bind(disjoint)
}

fn x86_regex_redux_component_call(
    assembler: &mut X86Assembler,
    component: usize,
    call_displacements: &mut Vec<(usize, X86Label)>,
) -> Result<(), ObjectError> {
    if component >= crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS {
        return Err(ObjectError::InvalidModule(
            "regex-redux component call index",
        ));
    }
    assembler.instruction(&[0x4c, 0x89, 0xf7])?; // rdi = source
    assembler.instruction(&[0x4c, 0x89, 0xfe])?; // rsi = source length
    x86_regex_redux_rsp_load(assembler, 2, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.instruction(&[0x4c, 0x89, 0xf9])?; // rcx = source length
    assembler.instruction(&[0x4c, 0x8d, 0x84, 0x24])?; // r8 = result
    push_bytes(
        &mut assembler.code,
        &u32::try_from(X86_REGEX_REDUX_SPAN_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux result offset"))?
            .to_le_bytes(),
    )?;
    assembler.instruction(&[0xe8])?;
    let displacement = assembler.label()?;
    assembler.bind(displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    call_displacements.push((component, displacement));
    Ok(())
}

fn x86_regex_redux_validate_span(
    assembler: &mut X86Assembler,
    runtime_failure: X86Label,
) -> Result<(), ObjectError> {
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_SPAN_OFFSET)?;
    x86_regex_redux_rsp_load(assembler, 1, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // start - requested start
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    x86_regex_redux_rsp_load(assembler, 2, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    assembler.instruction(&[0x48, 0x39, 0xc2])?; // end - start
    assembler.branch(&[0x0f, 0x86], runtime_failure)?;
    assembler.instruction(&[0x4c, 0x39, 0xfa])?; // end - source length
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    Ok(())
}

fn x86_regex_redux_emit_count(
    assembler: &mut X86Assembler,
    component: usize,
    output_offset: usize,
    runtime_failure: X86Label,
    call_displacements: &mut Vec<(usize, X86Label)>,
) -> Result<(), ObjectError> {
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let finished = assembler.label()?;
    x86_regex_redux_rsp_zero(assembler, X86_REGEX_REDUX_START_OFFSET)?;
    x86_regex_redux_rsp_zero(assembler, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;

    assembler.bind(loop_head)?;
    x86_regex_redux_component_call(assembler, component, call_displacements)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], runtime_failure)?;

    assembler.bind(matched)?;
    x86_regex_redux_validate_span(assembler, runtime_failure)?;
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    x86_regex_redux_rsp_store(assembler, 0, X86_REGEX_REDUX_START_OFFSET)?;
    let mut increment = vec![0x48, 0xff, 0x84, 0x24];
    increment.extend_from_slice(
        &u32::try_from(X86_REGEX_REDUX_DEST_LEN_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux count offset"))?
            .to_le_bytes(),
    );
    assembler.instruction(&increment)?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?; // u64 overflow wraps through zero
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(finished)?;
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    x86_regex_redux_rsp_store(assembler, 0, output_offset)
}

fn x86_regex_redux_emit_copy(
    assembler: &mut X86Assembler,
    destination_offset: usize,
    destination_capacity_offset: usize,
    source_count_in_r9: bool,
    replacement: Option<(usize, usize)>,
    runtime_failure: X86Label,
) -> Result<(), ObjectError> {
    if !source_count_in_r9 {
        return Err(ObjectError::InvalidModule(
            "regex-redux copy count register",
        ));
    }
    let replacement_len = replacement.map_or(0, |(_, len)| len);
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    assembler.instruction(&[0x49, 0x89, 0xc0])?; // r8 = old destination length
    assembler.instruction(&[0x48, 0x89, 0xc3])?; // rbx = prospective length
    assembler.instruction(&[0x4c, 0x01, 0xcb])?; // add unmatched bytes
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    if replacement_len != 0 {
        let replacement_len = u8::try_from(replacement_len)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux replacement length"))?;
        assembler.instruction(&[0x48, 0x83, 0xc3, replacement_len])?;
        assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    }
    x86_regex_redux_rsp_load(assembler, 0, destination_capacity_offset)?;
    assembler.instruction(&[0x48, 0x39, 0xc3])?; // prospective - capacity
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;

    x86_regex_redux_rsp_load(assembler, 7, destination_offset)?;
    assembler.instruction(&[0x4c, 0x01, 0xc7])?; // destination += old length
    assembler.instruction(&[0x4c, 0x89, 0xf6])?; // source = current sequence
    x86_regex_redux_rsp_load(assembler, 1, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(&[0x48, 0x01, 0xce])?; // source += copied
    assembler.instruction(&[0x4c, 0x89, 0xc9])?; // count = unmatched bytes
    assembler.instruction(&[0xf3, 0xa4])?;

    if let Some((replacement_offset, replacement_len)) = replacement
        && replacement_len != 0
    {
        let replacement_offset = u32::try_from(replacement_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux replacement offset"))?;
        let mut address = vec![0x49, 0x8d, 0xb5]; // rsi = data + replacement offset
        address.extend_from_slice(&replacement_offset.to_le_bytes());
        assembler.instruction(&address)?;
        let replacement_len = u32::try_from(replacement_len)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux replacement length"))?;
        let mut count = vec![0xb9];
        count.extend_from_slice(&replacement_len.to_le_bytes());
        assembler.instruction(&count)?;
        assembler.instruction(&[0xf3, 0xa4])?;
    }
    x86_regex_redux_rsp_store(assembler, 3, X86_REGEX_REDUX_DEST_LEN_OFFSET)
}

fn x86_regex_redux_emit_replacement(
    assembler: &mut X86Assembler,
    component: usize,
    destination_offset: usize,
    destination_capacity_offset: usize,
    replacement: Option<(usize, usize)>,
    stage_length_offset: usize,
    runtime_failure: X86Label,
    call_displacements: &mut Vec<(usize, X86Label)>,
) -> Result<(), ObjectError> {
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let tail = assembler.label()?;
    let finished = assembler.label()?;
    x86_regex_redux_rsp_zero(assembler, X86_REGEX_REDUX_START_OFFSET)?;
    x86_regex_redux_rsp_zero(assembler, X86_REGEX_REDUX_COPIED_OFFSET)?;
    x86_regex_redux_rsp_zero(assembler, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;

    assembler.bind(loop_head)?;
    x86_regex_redux_component_call(assembler, component, call_displacements)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], tail)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], runtime_failure)?;

    assembler.bind(matched)?;
    x86_regex_redux_validate_span(assembler, runtime_failure)?;
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_SPAN_OFFSET)?;
    x86_regex_redux_rsp_load(assembler, 1, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(&[0x48, 0x39, 0xc8])?; // match start - copied
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.instruction(&[0x48, 0x29, 0xc8])?; // unmatched length
    assembler.instruction(&[0x49, 0x89, 0xc1])?; // r9 = unmatched length
    x86_regex_redux_emit_copy(
        assembler,
        destination_offset,
        destination_capacity_offset,
        true,
        replacement,
        runtime_failure,
    )?;
    x86_regex_redux_rsp_load(assembler, 0, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    x86_regex_redux_rsp_store(assembler, 0, X86_REGEX_REDUX_COPIED_OFFSET)?;
    x86_regex_redux_rsp_store(assembler, 0, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(tail)?;
    x86_regex_redux_rsp_load(assembler, 1, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(&[0x4c, 0x39, 0xf9])?; // copied - source length
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x4d, 0x89, 0xf9])?; // r9 = source length
    assembler.instruction(&[0x49, 0x29, 0xc9])?; // r9 -= copied
    x86_regex_redux_emit_copy(
        assembler,
        destination_offset,
        destination_capacity_offset,
        true,
        None,
        runtime_failure,
    )?;
    assembler.bind(finished)?;
    x86_regex_redux_rsp_load(assembler, 0, destination_offset)?;
    assembler.instruction(&[0x49, 0x89, 0xc6])?; // r14 = new source
    assembler.instruction(&[0x49, 0x89, 0xdf])?; // r15 = new length
    x86_regex_redux_rsp_store(assembler, 3, stage_length_offset)
}

fn x86_regex_redux_report_byte(assembler: &mut X86Assembler, byte: u8) -> Result<(), ObjectError> {
    let mut instruction = vec![0xc6, 0x84, 0x1c]; // [rsp + rbx + report temporary]
    instruction.extend_from_slice(
        &u32::try_from(X86_REGEX_REDUX_REPORT_TEMP_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report temporary"))?
            .to_le_bytes(),
    );
    instruction.push(byte);
    assembler.instruction(&instruction)?;
    assembler.instruction(&[0x48, 0xff, 0xc3])?; // report length += 1
    Ok(())
}

fn x86_regex_redux_report_prefix(
    assembler: &mut X86Assembler,
    data_offset: usize,
    bytes: usize,
) -> Result<(), ObjectError> {
    let data_offset = u32::try_from(data_offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report prefix offset"))?;
    let bytes = u32::try_from(bytes)
        .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report prefix length"))?;
    let mut source = vec![0x49, 0x8d, 0xb5]; // rsi = immutable data + offset
    source.extend_from_slice(&data_offset.to_le_bytes());
    assembler.instruction(&source)?;
    let mut destination = vec![0x48, 0x8d, 0xbc, 0x1c]; // rdi = rsp + rbx + temporary
    destination.extend_from_slice(
        &u32::try_from(X86_REGEX_REDUX_REPORT_TEMP_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report temporary"))?
            .to_le_bytes(),
    );
    assembler.instruction(&destination)?;
    let mut count = vec![0xb9];
    count.extend_from_slice(&bytes.to_le_bytes());
    assembler.instruction(&count)?;
    assembler.instruction(&[0xf3, 0xa4])?;
    if bytes <= u32::from(i8::MAX.cast_unsigned()) {
        assembler.instruction(&[
            0x48,
            0x83,
            0xc3,
            u8::try_from(bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report prefix"))?,
        ])?;
    } else {
        let mut add = vec![0x48, 0x81, 0xc3];
        add.extend_from_slice(&bytes.to_le_bytes());
        assembler.instruction(&add)?;
    }
    Ok(())
}

/// Append the unsigned value in RAX to the private report transaction. At
/// most twenty reversed digits occupy the 32-byte scratch prefix containing
/// the now-dead Span result.
fn x86_regex_redux_report_u64(assembler: &mut X86Assembler) -> Result<(), ObjectError> {
    let nonzero = assembler.label()?;
    let divide = assembler.label()?;
    let reverse = assembler.label()?;
    let finished = assembler.label()?;
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], nonzero)?;
    x86_regex_redux_report_byte(assembler, b'0')?;
    assembler.branch(&[0xe9], finished)?;

    assembler.bind(nonzero)?;
    assembler.instruction(&[0x45, 0x31, 0xd2])?; // r10 = digit count
    assembler.bind(divide)?;
    assembler.instruction(&[0x31, 0xd2])?; // high dividend = 0
    assembler.instruction(&[0xb9, 10, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xf7, 0xf1])?; // div rcx
    assembler.instruction(&[0x80, 0xc2, b'0'])?;
    assembler.instruction(&[0x42, 0x88, 0x14, 0x14])?; // [rsp+r10] = digit
    assembler.instruction(&[0x49, 0xff, 0xc2])?;
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], divide)?;

    assembler.bind(reverse)?;
    assembler.instruction(&[0x49, 0xff, 0xca])?;
    assembler.instruction(&[0x42, 0x8a, 0x14, 0x14])?;
    let mut store = vec![0x88, 0x94, 0x1c];
    store.extend_from_slice(
        &u32::try_from(X86_REGEX_REDUX_REPORT_TEMP_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report temporary"))?
            .to_le_bytes(),
    );
    assembler.instruction(&store)?;
    assembler.instruction(&[0x48, 0xff, 0xc3])?;
    assembler.instruction(&[0x4d, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], reverse)?;
    assembler.bind(finished)
}

fn x86_regex_redux_publish_receipt(assembler: &mut X86Assembler) -> Result<(), ObjectError> {
    x86_regex_redux_rsp_load(assembler, 7, X86_REGEX_REDUX_RECEIPT_OFFSET)?;
    let sources = [
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_CLEAN_LEN_OFFSET,
        X86_REGEX_REDUX_COUNTS_OFFSET,
        X86_REGEX_REDUX_COUNTS_OFFSET + 8,
        X86_REGEX_REDUX_COUNTS_OFFSET + 16,
        X86_REGEX_REDUX_COUNTS_OFFSET + 24,
        X86_REGEX_REDUX_COUNTS_OFFSET + 32,
        X86_REGEX_REDUX_COUNTS_OFFSET + 40,
        X86_REGEX_REDUX_COUNTS_OFFSET + 48,
        X86_REGEX_REDUX_COUNTS_OFFSET + 56,
        X86_REGEX_REDUX_COUNTS_OFFSET + 64,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 8,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 16,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 24,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 32,
    ];
    for (word, source) in sources.into_iter().enumerate() {
        x86_regex_redux_rsp_load(assembler, 0, source)?;
        let offset = u32::try_from(
            word.checked_mul(8)
                .ok_or(ObjectError::ArithmeticOverflow("regex-redux receipt word"))?,
        )
        .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux receipt offset"))?;
        let mut store = vec![0x48, 0x89, 0x87];
        store.extend_from_slice(&offset.to_le_bytes());
        assembler.instruction(&store)?;
    }
    assembler.instruction(&[0x4c, 0x89, 0xf8])?; // final length
    assembler.instruction(&[0x48, 0x89, 0x87, 0x80, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0x89, 0x9f, 0x88, 0, 0, 0])?; // report length
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "one validated request, fifteen fixed semantic loops, canonical formatting, and transactional publication form one native operation"
)]
fn lower_x86_64_native_regex_redux_v1(
    identity: [u8; 32],
    data: &NativeRegexReduxDataLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    if data.bytes.get(..identity.len()) != Some(identity.as_slice())
        || data.variant_prefixes.len() != 9
        || data.replacements.len() != 5
    {
        return Err(ObjectError::InvalidModule(
            "regex-redux immutable data layout",
        ));
    }
    let mut maximum_report_bytes = 1_usize; // blank line before terminal lengths
    for &(offset, bytes) in &data.variant_prefixes {
        if bytes == 0
            || offset
                .checked_add(bytes)
                .is_none_or(|end| end > data.bytes.len())
        {
            return Err(ObjectError::InvalidModule(
                "regex-redux report prefix layout",
            ));
        }
        maximum_report_bytes = maximum_report_bytes
            .checked_add(bytes)
            .and_then(|total| total.checked_add(21)) // u64 decimal and newline
            .ok_or(ObjectError::ArithmeticOverflow("regex-redux report bound"))?;
    }
    maximum_report_bytes =
        maximum_report_bytes
            .checked_add(3 * 21)
            .ok_or(ObjectError::ArithmeticOverflow(
                "regex-redux terminal report bound",
            ))?;
    if maximum_report_bytes > crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES {
        return Err(ObjectError::InvalidModule("regex-redux report bound"));
    }
    for &(offset, bytes) in &data.replacements {
        if offset
            .checked_add(bytes)
            .is_none_or(|end| end > data.bytes.len())
        {
            return Err(ObjectError::InvalidModule("regex-redux replacement layout"));
        }
    }

    let mut assembler = X86Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let mut call_displacements = Vec::new();
    call_displacements
        .try_reserve_exact(crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS)
        .map_err(|_| ObjectError::Allocation("regex-redux call relocations"))?;

    // Authenticate the single-pointer request before changing RSP. The
    // complete fixed request must be aligned and addressable.
    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid_before_frame)?;
    assembler.instruction(&[0x40, 0xf6, 0xc7, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid_before_frame)?;
    assembler.instruction(&[0x48, 0x89, 0xf8])?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 72])?;
    assembler.branch(&[0x0f, 0x82], invalid_before_frame)?;

    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x55])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    let mut reserve = vec![0x48, 0x81, 0xec];
    reserve.extend_from_slice(&X86_REGEX_REDUX_FRAME_BYTES.to_le_bytes());
    assembler.instruction(&reserve)?;
    x86_regex_redux_rsp_store(&mut assembler, 7, X86_REGEX_REDUX_REQUEST_OFFSET)?;
    for (request_offset, stack_offset) in [
        (0, X86_REGEX_REDUX_HAYSTACK_OFFSET),
        (8, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET),
        (16, X86_REGEX_REDUX_SCRATCH_A_OFFSET),
        (24, X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET),
        (32, X86_REGEX_REDUX_SCRATCH_B_OFFSET),
        (40, X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET),
        (48, X86_REGEX_REDUX_REPORT_OFFSET),
        (56, X86_REGEX_REDUX_REPORT_CAP_OFFSET),
        (64, X86_REGEX_REDUX_RECEIPT_OFFSET),
    ] {
        x86_regex_redux_load_request_word(&mut assembler, request_offset, stack_offset)?;
    }

    assembler.instruction(&[0x4c, 0x8d, 0x2d])?; // r13 = immutable data
    let data_displacement = assembler.label()?;
    assembler.bind(data_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    for pointer_offset in [
        X86_REGEX_REDUX_HAYSTACK_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_OFFSET,
        X86_REGEX_REDUX_REPORT_OFFSET,
        X86_REGEX_REDUX_RECEIPT_OFFSET,
    ] {
        x86_regex_redux_rsp_load(&mut assembler, 0, pointer_offset)?;
        assembler.instruction(&[0x48, 0x85, 0xc0])?;
        assembler.branch(&[0x0f, 0x84], invalid)?;
    }
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_RECEIPT_OFFSET)?;
    assembler.instruction(&[0xa8, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    for length_offset in [
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
        X86_REGEX_REDUX_REPORT_CAP_OFFSET,
    ] {
        x86_regex_redux_rsp_load(&mut assembler, 0, length_offset)?;
        assembler.instruction(&[0x48, 0x85, 0xc0])?;
        assembler.branch(&[0x0f, 0x88], invalid)?;
    }
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_REPORT_CAP_OFFSET)?;
    let mut report_capacity = vec![0x48, 0x3d];
    report_capacity.extend_from_slice(
        &u32::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report capacity"))?
            .to_le_bytes(),
    );
    assembler.instruction(&report_capacity)?;
    assembler.branch(&[0x0f, 0x82], invalid)?;

    // The third substitution can expand every disjoint `BY` pair from two
    // bytes to three. No other fixed stage expands, so n + floor(n/2) is an
    // exact all-input capacity envelope for both ping-pong buffers.
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    assembler.instruction(&[0x48, 0x89, 0xc1])?;
    assembler.instruction(&[0x48, 0xd1, 0xe9])?;
    assembler.instruction(&[0x48, 0x01, 0xc8])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x88], invalid)?;
    for capacity_offset in [
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
    ] {
        x86_regex_redux_rsp_load(&mut assembler, 2, capacity_offset)?;
        assembler.instruction(&[0x48, 0x39, 0xc2])?;
        assembler.branch(&[0x0f, 0x82], invalid)?;
    }

    x86_regex_redux_fixed_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_REQUEST_OFFSET,
        u32::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REQUEST_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux request extent"))?,
        X86_REGEX_REDUX_REQUEST_END_OFFSET,
        invalid,
    )?;
    x86_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_HAYSTACK_OFFSET,
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_HAYSTACK_END_OFFSET,
        invalid,
    )?;
    x86_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_END_OFFSET,
        invalid,
    )?;
    x86_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_SCRATCH_B_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_END_OFFSET,
        invalid,
    )?;
    x86_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_REPORT_OFFSET,
        X86_REGEX_REDUX_REPORT_CAP_OFFSET,
        X86_REGEX_REDUX_REPORT_END_OFFSET,
        invalid,
    )?;
    x86_regex_redux_fixed_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_RECEIPT_OFFSET,
        u32::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_RECEIPT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux receipt extent"))?,
        X86_REGEX_REDUX_RECEIPT_END_OFFSET,
        invalid,
    )?;
    let ranges = [
        (
            X86_REGEX_REDUX_REQUEST_OFFSET,
            X86_REGEX_REDUX_REQUEST_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_HAYSTACK_OFFSET,
            X86_REGEX_REDUX_HAYSTACK_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_SCRATCH_A_OFFSET,
            X86_REGEX_REDUX_SCRATCH_A_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_SCRATCH_B_OFFSET,
            X86_REGEX_REDUX_SCRATCH_B_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_REPORT_OFFSET,
            X86_REGEX_REDUX_REPORT_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_RECEIPT_OFFSET,
            X86_REGEX_REDUX_RECEIPT_END_OFFSET,
        ),
    ];
    for first in 0..ranges.len() {
        for second in first + 1..ranges.len() {
            x86_regex_redux_disjoint(
                &mut assembler,
                ranges[first].0,
                ranges[first].1,
                ranges[second].0,
                ranges[second].1,
                invalid,
            )?;
        }
    }

    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_HAYSTACK_OFFSET)?;
    assembler.instruction(&[0x49, 0x89, 0xc6])?;
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    assembler.instruction(&[0x49, 0x89, 0xc7])?;

    x86_regex_redux_emit_replacement(
        &mut assembler,
        0,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        None,
        X86_REGEX_REDUX_CLEAN_LEN_OFFSET,
        runtime_failure,
        &mut call_displacements,
    )?;
    for variant in 0..data.variant_prefixes.len() {
        x86_regex_redux_emit_count(
            &mut assembler,
            variant + 1,
            X86_REGEX_REDUX_COUNTS_OFFSET + variant * 8,
            runtime_failure,
            &mut call_displacements,
        )?;
    }
    for substitution in 0..data.replacements.len() {
        let destination_is_b = substitution.is_multiple_of(2);
        x86_regex_redux_emit_replacement(
            &mut assembler,
            10 + substitution,
            if destination_is_b {
                X86_REGEX_REDUX_SCRATCH_B_OFFSET
            } else {
                X86_REGEX_REDUX_SCRATCH_A_OFFSET
            },
            if destination_is_b {
                X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET
            } else {
                X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET
            },
            Some(data.replacements[substitution]),
            X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + substitution * 8,
            runtime_failure,
            &mut call_displacements,
        )?;
    }

    // Format the exact Rebar report privately. No caller-visible report or
    // receipt byte is touched until every semantic stage has succeeded.
    assembler.instruction(&[0x31, 0xdb])?; // report length = 0
    for (variant, &(offset, bytes)) in data.variant_prefixes.iter().enumerate() {
        x86_regex_redux_report_prefix(&mut assembler, offset, bytes)?;
        x86_regex_redux_rsp_load(
            &mut assembler,
            0,
            X86_REGEX_REDUX_COUNTS_OFFSET + variant * 8,
        )?;
        x86_regex_redux_report_u64(&mut assembler)?;
        x86_regex_redux_report_byte(&mut assembler, b'\n')?;
    }
    x86_regex_redux_report_byte(&mut assembler, b'\n')?;
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    x86_regex_redux_report_u64(&mut assembler)?;
    x86_regex_redux_report_byte(&mut assembler, b'\n')?;
    x86_regex_redux_rsp_load(&mut assembler, 0, X86_REGEX_REDUX_CLEAN_LEN_OFFSET)?;
    x86_regex_redux_report_u64(&mut assembler)?;
    x86_regex_redux_report_byte(&mut assembler, b'\n')?;
    assembler.instruction(&[0x4c, 0x89, 0xf8])?;
    x86_regex_redux_report_u64(&mut assembler)?;
    x86_regex_redux_report_byte(&mut assembler, b'\n')?;
    let mut report_bound = vec![0x48, 0x81, 0xfb];
    report_bound.extend_from_slice(
        &u32::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report bound"))?
            .to_le_bytes(),
    );
    assembler.instruction(&report_bound)?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;

    x86_regex_redux_rsp_load(&mut assembler, 7, X86_REGEX_REDUX_REPORT_OFFSET)?;
    let mut report_source = vec![0x48, 0x8d, 0xb4, 0x24];
    report_source.extend_from_slice(
        &u32::try_from(X86_REGEX_REDUX_REPORT_TEMP_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report temporary"))?
            .to_le_bytes(),
    );
    assembler.instruction(&report_source)?;
    assembler.instruction(&[0x48, 0x89, 0xd9])?;
    assembler.instruction(&[0xf3, 0xa4])?;
    x86_regex_redux_publish_receipt(&mut assembler)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(returned)?;
    let mut release = vec![0x48, 0x81, 0xc4];
    release.extend_from_slice(&X86_REGEX_REDUX_FRAME_BYTES.to_le_bytes());
    assembler.instruction(&release)?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5d])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_before_frame)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    if call_displacements.len() != crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS
        || call_displacements
            .iter()
            .enumerate()
            .any(|(expected, &(component, _))| component != expected)
    {
        return Err(ObjectError::InvalidModule("regex-redux call closure"));
    }
    let finished = assembler.finish_with_label_offsets()?;
    let mut relocations = Vec::new();
    relocations
        .try_reserve_exact(1 + call_displacements.len())
        .map_err(|_| ObjectError::Allocation("regex-redux relocations"))?;
    relocations.push(ModuleRelocation {
        section: REGEX_REDUX_TEXT_SECTION,
        offset: offset_u64(
            finished.label_offset(data_displacement)?,
            "regex-redux data relocation",
        )?,
        kind: RelocationKind::X86PcRelative32,
        symbol: REGEX_REDUX_DATA_SYMBOL,
        addend: -4,
    });
    for (component, displacement) in call_displacements {
        relocations.push(ModuleRelocation {
            section: REGEX_REDUX_TEXT_SECTION,
            offset: offset_u64(
                finished.label_offset(displacement)?,
                "regex-redux component relocation",
            )?,
            kind: RelocationKind::X86PltRelative32,
            symbol: REGEX_REDUX_COMPONENT_SYMBOL_BASE + component,
            addend: -4,
        });
    }
    Ok((finished.code, relocations))
}

// AAPCS64 keeps SP 16-byte aligned at every call. The semantic workspace uses
// the same offsets as the x86-64 lowering; the extra tail preserves X19..X24,
// FP, and LR without encroaching on the 1 KiB private report transaction.
const AARCH64_REGEX_REDUX_FRAME_BYTES: u16 = 1_408;
const AARCH64_REGEX_REDUX_SAVED_OFFSET: u16 = 1_344;

fn aarch64_regex_redux_stack_load(
    assembler: &mut Aarch64Assembler,
    register: u8,
    offset: usize,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_load_x_imm(
        register,
        31,
        u16::try_from(offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux stack load"))?,
    )?)?;
    Ok(())
}

fn aarch64_regex_redux_stack_store(
    assembler: &mut Aarch64Assembler,
    register: u8,
    offset: usize,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_store_x(
        register,
        31,
        u16::try_from(offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux stack store"))?,
    )?)?;
    Ok(())
}

fn aarch64_regex_redux_stack_zero(
    assembler: &mut Aarch64Assembler,
    offset: usize,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_movz_x(9, 0, 0)?)?;
    aarch64_regex_redux_stack_store(assembler, 9, offset)
}

fn aarch64_regex_redux_adds_x_reg(
    destination: u8,
    left: u8,
    right: u8,
) -> Result<u32, ObjectError> {
    Ok(
        0xab00_0000
            | aarch64_reg(right, 16)?
            | aarch64_reg(left, 5)?
            | aarch64_reg(destination, 0)?,
    )
}

fn aarch64_regex_redux_store_byte_reg(source: u8, base: u8, index: u8) -> Result<u32, ObjectError> {
    Ok(0x3820_6800 | aarch64_reg(index, 16)? | aarch64_reg(base, 5)? | aarch64_reg(source, 0)?)
}

fn aarch64_regex_redux_load_x_reg(
    destination: u8,
    base: u8,
    index: u8,
) -> Result<u32, ObjectError> {
    Ok(
        0xf860_6800
            | aarch64_reg(index, 16)?
            | aarch64_reg(base, 5)?
            | aarch64_reg(destination, 0)?,
    )
}

fn aarch64_regex_redux_store_x_reg(source: u8, base: u8, index: u8) -> Result<u32, ObjectError> {
    Ok(0xf820_6800 | aarch64_reg(index, 16)? | aarch64_reg(base, 5)? | aarch64_reg(source, 0)?)
}

fn aarch64_regex_redux_pointer_end(
    assembler: &mut Aarch64Assembler,
    base_offset: usize,
    length_offset: usize,
    end_offset: usize,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    aarch64_regex_redux_stack_load(assembler, 9, base_offset)?;
    aarch64_regex_redux_stack_load(assembler, 10, length_offset)?;
    assembler.instruction(aarch64_regex_redux_adds_x_reg(9, 9, 10)?)?;
    assembler.branch_cond(AARCH64_HS, invalid)?;
    aarch64_regex_redux_stack_store(assembler, 9, end_offset)
}

fn aarch64_regex_redux_fixed_pointer_end(
    assembler: &mut Aarch64Assembler,
    base_offset: usize,
    bytes: u16,
    end_offset: usize,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    aarch64_regex_redux_stack_load(assembler, 9, base_offset)?;
    assembler.instruction(aarch64_adds_x_imm(9, 9, bytes)?)?;
    assembler.branch_cond(AARCH64_HS, invalid)?;
    aarch64_regex_redux_stack_store(assembler, 9, end_offset)
}

fn aarch64_regex_redux_disjoint(
    assembler: &mut Aarch64Assembler,
    first_base: usize,
    first_end: usize,
    second_base: usize,
    second_end: usize,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    let disjoint = assembler.label()?;
    aarch64_regex_redux_stack_load(assembler, 9, first_end)?;
    aarch64_regex_redux_stack_load(assembler, 10, first_base)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_EQ, disjoint)?;
    aarch64_regex_redux_stack_load(assembler, 9, second_end)?;
    aarch64_regex_redux_stack_load(assembler, 10, second_base)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_EQ, disjoint)?;
    aarch64_regex_redux_stack_load(assembler, 9, first_end)?;
    aarch64_regex_redux_stack_load(assembler, 10, second_base)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_LS, disjoint)?;
    aarch64_regex_redux_stack_load(assembler, 9, second_end)?;
    aarch64_regex_redux_stack_load(assembler, 10, first_base)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.bind(disjoint)
}

fn aarch64_regex_redux_component_call(
    assembler: &mut Aarch64Assembler,
    component: usize,
    call_offsets: &mut Vec<(usize, usize)>,
) -> Result<(), ObjectError> {
    if component >= crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS {
        return Err(ObjectError::InvalidModule(
            "regex-redux AArch64 component call index",
        ));
    }
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    aarch64_regex_redux_stack_load(assembler, 2, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.instruction(aarch64_mov_x(3, 20)?)?;
    assembler.instruction(aarch64_add_x_imm(
        4,
        31,
        u16::try_from(X86_REGEX_REDUX_SPAN_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux Span result"))?,
    )?)?;
    let call = assembler.instruction(0x9400_0000)?;
    call_offsets
        .try_reserve(1)
        .map_err(|_| ObjectError::Allocation("regex-redux AArch64 calls"))?;
    call_offsets.push((component, call));
    Ok(())
}

fn aarch64_regex_redux_validate_span(
    assembler: &mut Aarch64Assembler,
    runtime_failure: Aarch64Label,
) -> Result<(), ObjectError> {
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_SPAN_OFFSET)?;
    aarch64_regex_redux_stack_load(assembler, 10, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    aarch64_regex_redux_stack_load(assembler, 11, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    assembler.instruction(aarch64_cmp_x(11, 9)?)?;
    assembler.branch_cond(AARCH64_LS, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(11, 20)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    Ok(())
}

fn aarch64_regex_redux_emit_count(
    assembler: &mut Aarch64Assembler,
    component: usize,
    output_offset: usize,
    runtime_failure: Aarch64Label,
    call_offsets: &mut Vec<(usize, usize)>,
) -> Result<(), ObjectError> {
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let finished = assembler.label()?;
    aarch64_regex_redux_stack_zero(assembler, X86_REGEX_REDUX_START_OFFSET)?;
    aarch64_regex_redux_stack_zero(assembler, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;

    assembler.bind(loop_head)?;
    aarch64_regex_redux_component_call(assembler, component, call_offsets)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(runtime_failure)?;

    assembler.bind(matched)?;
    aarch64_regex_redux_validate_span(assembler, runtime_failure)?;
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    aarch64_regex_redux_stack_store(assembler, 9, X86_REGEX_REDUX_START_OFFSET)?;
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    assembler.instruction(aarch64_adds_x_imm(9, 9, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    aarch64_regex_redux_stack_store(assembler, 9, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    assembler.branch(loop_head)?;

    assembler.bind(finished)?;
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    aarch64_regex_redux_stack_store(assembler, 9, output_offset)
}

/// Append X9 bytes from `source + copied` to the selected destination and then
/// append the fixed replacement, if any. The prospective length is committed
/// only to the private frame until the complete operation succeeds.
fn aarch64_regex_redux_emit_copy(
    assembler: &mut Aarch64Assembler,
    destination_offset: usize,
    destination_capacity_offset: usize,
    replacement: Option<(usize, usize)>,
    runtime_failure: Aarch64Label,
) -> Result<(), ObjectError> {
    let bulk_check = assembler.label()?;
    let byte_check = assembler.label()?;
    let byte_loop = assembler.label()?;
    let copied = assembler.label()?;
    let replacement_len = replacement.map_or(0, |(_, bytes)| bytes);
    aarch64_regex_redux_stack_load(assembler, 10, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    assembler.instruction(aarch64_regex_redux_adds_x_reg(11, 10, 9)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    if replacement_len != 0 {
        assembler.instruction(aarch64_adds_x_imm(
            11,
            11,
            u16::try_from(replacement_len)
                .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux replacement length"))?,
        )?)?;
        assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    }
    aarch64_regex_redux_stack_load(assembler, 12, destination_capacity_offset)?;
    assembler.instruction(aarch64_cmp_x(11, 12)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    aarch64_regex_redux_stack_store(assembler, 11, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;

    aarch64_regex_redux_stack_load(assembler, 12, destination_offset)?;
    assembler.instruction(aarch64_add_x_reg(12, 12, 10)?)?;
    aarch64_regex_redux_stack_load(assembler, 10, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(aarch64_add_x_reg(11, 19, 10)?)?;
    assembler.instruction(aarch64_movz_x(10, 0, 0)?)?;
    assembler.bind(bulk_check)?;
    assembler.instruction(aarch64_sub_x_reg(14, 9, 10)?)?;
    assembler.instruction(aarch64_cmp_x_imm(14, 8)?)?;
    assembler.branch_cond(AARCH64_LO, byte_check)?;
    assembler.instruction(aarch64_regex_redux_load_x_reg(13, 11, 10)?)?;
    assembler.instruction(aarch64_regex_redux_store_x_reg(13, 12, 10)?)?;
    assembler.instruction(aarch64_add_x_imm(10, 10, 8)?)?;
    assembler.branch(bulk_check)?;
    assembler.bind(byte_check)?;
    assembler.instruction(aarch64_cmp_x(10, 9)?)?;
    assembler.branch_cond(AARCH64_HS, copied)?;
    assembler.bind(byte_loop)?;
    assembler.instruction(aarch64_load_byte_reg(13, 11, 10)?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(13, 12, 10)?)?;
    assembler.instruction(aarch64_add_x_imm(10, 10, 1)?)?;
    assembler.instruction(aarch64_cmp_x(10, 9)?)?;
    assembler.branch_cond(AARCH64_LO, byte_loop)?;
    assembler.bind(copied)?;

    if let Some((replacement_offset, replacement_len)) = replacement {
        assembler.instruction(aarch64_add_x_reg(12, 12, 9)?)?;
        for byte in 0..replacement_len {
            let source_offset = replacement_offset
                .checked_add(byte)
                .and_then(|offset| u16::try_from(offset).ok())
                .ok_or(ObjectError::ArithmeticOverflow(
                    "regex-redux replacement offset",
                ))?;
            assembler.instruction(aarch64_load_byte_imm(13, 21, source_offset)?)?;
            assembler.instruction(aarch64_store_byte(
                13,
                12,
                u16::try_from(byte)
                    .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux replacement byte"))?,
            )?)?;
        }
    }
    Ok(())
}

fn aarch64_regex_redux_emit_replacement(
    assembler: &mut Aarch64Assembler,
    component: usize,
    destination_offset: usize,
    destination_capacity_offset: usize,
    replacement: Option<(usize, usize)>,
    stage_length_offset: usize,
    runtime_failure: Aarch64Label,
    call_offsets: &mut Vec<(usize, usize)>,
) -> Result<(), ObjectError> {
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let tail = assembler.label()?;
    aarch64_regex_redux_stack_zero(assembler, X86_REGEX_REDUX_START_OFFSET)?;
    aarch64_regex_redux_stack_zero(assembler, X86_REGEX_REDUX_COPIED_OFFSET)?;
    aarch64_regex_redux_stack_zero(assembler, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;

    assembler.bind(loop_head)?;
    aarch64_regex_redux_component_call(assembler, component, call_offsets)?;
    assembler.branch_zero_w(0, tail)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(runtime_failure)?;

    assembler.bind(matched)?;
    aarch64_regex_redux_validate_span(assembler, runtime_failure)?;
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_SPAN_OFFSET)?;
    aarch64_regex_redux_stack_load(assembler, 10, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    assembler.instruction(aarch64_sub_x_reg(9, 9, 10)?)?;
    aarch64_regex_redux_emit_copy(
        assembler,
        destination_offset,
        destination_capacity_offset,
        replacement,
        runtime_failure,
    )?;
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_SPAN_OFFSET + 8)?;
    aarch64_regex_redux_stack_store(assembler, 9, X86_REGEX_REDUX_COPIED_OFFSET)?;
    aarch64_regex_redux_stack_store(assembler, 9, X86_REGEX_REDUX_START_OFFSET)?;
    assembler.branch(loop_head)?;

    assembler.bind(tail)?;
    aarch64_regex_redux_stack_load(assembler, 10, X86_REGEX_REDUX_COPIED_OFFSET)?;
    assembler.instruction(aarch64_cmp_x(10, 20)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_sub_x_reg(9, 20, 10)?)?;
    aarch64_regex_redux_emit_copy(
        assembler,
        destination_offset,
        destination_capacity_offset,
        None,
        runtime_failure,
    )?;
    aarch64_regex_redux_stack_load(assembler, 19, destination_offset)?;
    aarch64_regex_redux_stack_load(assembler, 20, X86_REGEX_REDUX_DEST_LEN_OFFSET)?;
    aarch64_regex_redux_stack_store(assembler, 20, stage_length_offset)
}

fn aarch64_regex_redux_report_byte(
    assembler: &mut Aarch64Assembler,
    byte: u8,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_movz_w(9, u16::from(byte))?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(9, 24, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    Ok(())
}

fn aarch64_regex_redux_report_prefix(
    assembler: &mut Aarch64Assembler,
    data_offset: usize,
    bytes: usize,
) -> Result<(), ObjectError> {
    let loop_head = assembler.label()?;
    let finished = assembler.label()?;
    assembler.instruction(aarch64_add_x_imm(
        11,
        21,
        u16::try_from(data_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report prefix"))?,
    )?)?;
    assembler.instruction(aarch64_movz_x(9, 0, 0)?)?;
    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_cmp_x_imm(
        9,
        u16::try_from(bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report prefix"))?,
    )?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_load_byte_reg(10, 11, 9)?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(10, 24, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(9, 9, 1)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.branch(loop_head)?;
    assembler.bind(finished)
}

/// Append the unsigned value in X9 to the private report. At most twenty
/// reversed digits occupy the 32-byte scratch prefix at SP containing the
/// now-dead Span result.
fn aarch64_regex_redux_report_u64(assembler: &mut Aarch64Assembler) -> Result<(), ObjectError> {
    let nonzero = assembler.label()?;
    let divide = assembler.label()?;
    let reverse = assembler.label()?;
    let finished = assembler.label()?;
    assembler.branch_nonzero_x(9, nonzero)?;
    aarch64_regex_redux_report_byte(assembler, b'0')?;
    assembler.branch(finished)?;

    assembler.bind(nonzero)?;
    assembler.instruction(aarch64_movz_x(10, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(12, 10, 0)?)?;
    assembler.bind(divide)?;
    assembler.instruction(aarch64_udiv_x(11, 9, 12)?)?;
    assembler.instruction(aarch64_msub_x(13, 11, 12, 9)?)?;
    assembler.instruction(aarch64_add_x_imm(13, 13, u16::from(b'0'))?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(13, 31, 10)?)?;
    assembler.instruction(aarch64_add_x_imm(10, 10, 1)?)?;
    assembler.instruction(aarch64_mov_x(9, 11)?)?;
    assembler.branch_nonzero_x(9, divide)?;

    assembler.bind(reverse)?;
    assembler.instruction(aarch64_sub_x_imm(10, 10, 1)?)?;
    assembler.instruction(aarch64_load_byte_reg(13, 31, 10)?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(13, 24, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.branch_nonzero_x(10, reverse)?;
    assembler.bind(finished)
}

fn aarch64_regex_redux_publish_receipt(
    assembler: &mut Aarch64Assembler,
) -> Result<(), ObjectError> {
    aarch64_regex_redux_stack_load(assembler, 9, X86_REGEX_REDUX_RECEIPT_OFFSET)?;
    let sources = [
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_CLEAN_LEN_OFFSET,
        X86_REGEX_REDUX_COUNTS_OFFSET,
        X86_REGEX_REDUX_COUNTS_OFFSET + 8,
        X86_REGEX_REDUX_COUNTS_OFFSET + 16,
        X86_REGEX_REDUX_COUNTS_OFFSET + 24,
        X86_REGEX_REDUX_COUNTS_OFFSET + 32,
        X86_REGEX_REDUX_COUNTS_OFFSET + 40,
        X86_REGEX_REDUX_COUNTS_OFFSET + 48,
        X86_REGEX_REDUX_COUNTS_OFFSET + 56,
        X86_REGEX_REDUX_COUNTS_OFFSET + 64,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 8,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 16,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 24,
        X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + 32,
    ];
    for (word, source) in sources.into_iter().enumerate() {
        aarch64_regex_redux_stack_load(assembler, 10, source)?;
        assembler.instruction(aarch64_store_x(
            10,
            9,
            u16::try_from(
                word.checked_mul(8)
                    .ok_or(ObjectError::ArithmeticOverflow("regex-redux receipt word"))?,
            )
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux receipt offset"))?,
        )?)?;
    }
    assembler.instruction(aarch64_store_x(20, 9, 128)?)?;
    assembler.instruction(aarch64_store_x(23, 9, 136)?)?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "the AAPCS64 operation mirrors the complete validated x86-64 transaction"
)]
fn lower_aarch64_native_regex_redux_v1(
    identity: [u8; 32],
    data: &NativeRegexReduxDataLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    if data.bytes.get(..identity.len()) != Some(identity.as_slice())
        || data.variant_prefixes.len() != 9
        || data.replacements.len() != 5
    {
        return Err(ObjectError::InvalidModule(
            "regex-redux AArch64 immutable data layout",
        ));
    }
    let mut maximum_report_bytes = 1_usize;
    for &(offset, bytes) in &data.variant_prefixes {
        if bytes == 0
            || offset
                .checked_add(bytes)
                .is_none_or(|end| end > data.bytes.len())
        {
            return Err(ObjectError::InvalidModule(
                "regex-redux AArch64 report prefix layout",
            ));
        }
        maximum_report_bytes = maximum_report_bytes
            .checked_add(bytes)
            .and_then(|total| total.checked_add(21))
            .ok_or(ObjectError::ArithmeticOverflow(
                "regex-redux AArch64 report bound",
            ))?;
    }
    maximum_report_bytes =
        maximum_report_bytes
            .checked_add(3 * 21)
            .ok_or(ObjectError::ArithmeticOverflow(
                "regex-redux AArch64 terminal report bound",
            ))?;
    if maximum_report_bytes > crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES {
        return Err(ObjectError::InvalidModule(
            "regex-redux AArch64 report bound",
        ));
    }
    for &(offset, bytes) in &data.replacements {
        if offset
            .checked_add(bytes)
            .is_none_or(|end| end > data.bytes.len())
        {
            return Err(ObjectError::InvalidModule(
                "regex-redux AArch64 replacement layout",
            ));
        }
    }

    let mut assembler = Aarch64Assembler::new();
    let invalid_before_frame = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let mut call_offsets = Vec::new();
    call_offsets
        .try_reserve_exact(crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS)
        .map_err(|_| ObjectError::Allocation("regex-redux AArch64 calls"))?;

    assembler.branch_zero_x(0, invalid_before_frame)?;
    assembler.instruction(aarch64_and_low_x(9, 0, 3)?)?;
    assembler.branch_nonzero_x(9, invalid_before_frame)?;
    assembler.instruction(aarch64_adds_x_imm(
        9,
        0,
        u16::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REQUEST_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux request extent"))?,
    )?)?;
    assembler.branch_cond(AARCH64_HS, invalid_before_frame)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, AARCH64_REGEX_REDUX_FRAME_BYTES)?)?;
    assembler.instruction(aarch64_add_x_imm(9, 31, AARCH64_REGEX_REDUX_SAVED_OFFSET)?)?;
    for (first, second, offset) in [(19, 20, 0), (21, 22, 16), (23, 24, 32), (29, 30, 48)] {
        assembler.instruction(aarch64_store_pair_x(first, second, 9, offset)?)?;
    }
    aarch64_regex_redux_stack_store(&mut assembler, 0, X86_REGEX_REDUX_REQUEST_OFFSET)?;
    for (request_offset, stack_offset) in [
        (0, X86_REGEX_REDUX_HAYSTACK_OFFSET),
        (8, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET),
        (16, X86_REGEX_REDUX_SCRATCH_A_OFFSET),
        (24, X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET),
        (32, X86_REGEX_REDUX_SCRATCH_B_OFFSET),
        (40, X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET),
        (48, X86_REGEX_REDUX_REPORT_OFFSET),
        (56, X86_REGEX_REDUX_REPORT_CAP_OFFSET),
        (64, X86_REGEX_REDUX_RECEIPT_OFFSET),
    ] {
        assembler.instruction(aarch64_load_x_imm(9, 0, request_offset)?)?;
        aarch64_regex_redux_stack_store(&mut assembler, 9, stack_offset)?;
    }

    let data_page = assembler.instruction(0x9000_0015)?; // adrp x21, immutable data
    let data_page_offset = assembler.instruction(aarch64_add_x_imm(21, 21, 0)?)?;

    for pointer_offset in [
        X86_REGEX_REDUX_HAYSTACK_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_OFFSET,
        X86_REGEX_REDUX_REPORT_OFFSET,
        X86_REGEX_REDUX_RECEIPT_OFFSET,
    ] {
        aarch64_regex_redux_stack_load(&mut assembler, 9, pointer_offset)?;
        assembler.branch_zero_x(9, invalid)?;
    }
    aarch64_regex_redux_stack_load(&mut assembler, 9, X86_REGEX_REDUX_RECEIPT_OFFSET)?;
    assembler.instruction(aarch64_and_low_x(9, 9, 3)?)?;
    assembler.branch_nonzero_x(9, invalid)?;
    for length_offset in [
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
        X86_REGEX_REDUX_REPORT_CAP_OFFSET,
    ] {
        aarch64_regex_redux_stack_load(&mut assembler, 9, length_offset)?;
        assembler.branch_bit_set_x(9, 63, invalid)?;
    }
    aarch64_regex_redux_stack_load(&mut assembler, 9, X86_REGEX_REDUX_REPORT_CAP_OFFSET)?;
    assembler.instruction(aarch64_cmp_x_imm(
        9,
        u16::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report capacity"))?,
    )?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;

    aarch64_regex_redux_stack_load(&mut assembler, 9, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    assembler.instruction(aarch64_lsr_x_imm(10, 9, 1)?)?;
    assembler.instruction(aarch64_regex_redux_adds_x_reg(11, 9, 10)?)?;
    assembler.branch_cond(AARCH64_HS, invalid)?;
    assembler.branch_bit_set_x(11, 63, invalid)?;
    for capacity_offset in [
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
    ] {
        aarch64_regex_redux_stack_load(&mut assembler, 12, capacity_offset)?;
        assembler.instruction(aarch64_cmp_x(12, 11)?)?;
        assembler.branch_cond(AARCH64_LO, invalid)?;
    }

    aarch64_regex_redux_fixed_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_REQUEST_OFFSET,
        u16::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REQUEST_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux request extent"))?,
        X86_REGEX_REDUX_REQUEST_END_OFFSET,
        invalid,
    )?;
    aarch64_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_HAYSTACK_OFFSET,
        X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET,
        X86_REGEX_REDUX_HAYSTACK_END_OFFSET,
        invalid,
    )?;
    aarch64_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_END_OFFSET,
        invalid,
    )?;
    aarch64_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_SCRATCH_B_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET,
        X86_REGEX_REDUX_SCRATCH_B_END_OFFSET,
        invalid,
    )?;
    aarch64_regex_redux_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_REPORT_OFFSET,
        X86_REGEX_REDUX_REPORT_CAP_OFFSET,
        X86_REGEX_REDUX_REPORT_END_OFFSET,
        invalid,
    )?;
    aarch64_regex_redux_fixed_pointer_end(
        &mut assembler,
        X86_REGEX_REDUX_RECEIPT_OFFSET,
        u16::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_RECEIPT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux receipt extent"))?,
        X86_REGEX_REDUX_RECEIPT_END_OFFSET,
        invalid,
    )?;
    let ranges = [
        (
            X86_REGEX_REDUX_REQUEST_OFFSET,
            X86_REGEX_REDUX_REQUEST_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_HAYSTACK_OFFSET,
            X86_REGEX_REDUX_HAYSTACK_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_SCRATCH_A_OFFSET,
            X86_REGEX_REDUX_SCRATCH_A_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_SCRATCH_B_OFFSET,
            X86_REGEX_REDUX_SCRATCH_B_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_REPORT_OFFSET,
            X86_REGEX_REDUX_REPORT_END_OFFSET,
        ),
        (
            X86_REGEX_REDUX_RECEIPT_OFFSET,
            X86_REGEX_REDUX_RECEIPT_END_OFFSET,
        ),
    ];
    for first in 0..ranges.len() {
        for second in first + 1..ranges.len() {
            aarch64_regex_redux_disjoint(
                &mut assembler,
                ranges[first].0,
                ranges[first].1,
                ranges[second].0,
                ranges[second].1,
                invalid,
            )?;
        }
    }

    aarch64_regex_redux_stack_load(&mut assembler, 19, X86_REGEX_REDUX_HAYSTACK_OFFSET)?;
    aarch64_regex_redux_stack_load(&mut assembler, 20, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    aarch64_regex_redux_emit_replacement(
        &mut assembler,
        0,
        X86_REGEX_REDUX_SCRATCH_A_OFFSET,
        X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET,
        None,
        X86_REGEX_REDUX_CLEAN_LEN_OFFSET,
        runtime_failure,
        &mut call_offsets,
    )?;
    for variant in 0..data.variant_prefixes.len() {
        aarch64_regex_redux_emit_count(
            &mut assembler,
            variant + 1,
            X86_REGEX_REDUX_COUNTS_OFFSET + variant * 8,
            runtime_failure,
            &mut call_offsets,
        )?;
    }
    for substitution in 0..data.replacements.len() {
        let destination_is_b = substitution.is_multiple_of(2);
        aarch64_regex_redux_emit_replacement(
            &mut assembler,
            10 + substitution,
            if destination_is_b {
                X86_REGEX_REDUX_SCRATCH_B_OFFSET
            } else {
                X86_REGEX_REDUX_SCRATCH_A_OFFSET
            },
            if destination_is_b {
                X86_REGEX_REDUX_SCRATCH_B_CAP_OFFSET
            } else {
                X86_REGEX_REDUX_SCRATCH_A_CAP_OFFSET
            },
            Some(data.replacements[substitution]),
            X86_REGEX_REDUX_SUBSTITUTION_LENGTHS_OFFSET + substitution * 8,
            runtime_failure,
            &mut call_offsets,
        )?;
    }

    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(
        24,
        31,
        u16::try_from(X86_REGEX_REDUX_REPORT_TEMP_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report temporary"))?,
    )?)?;
    for (variant, &(offset, bytes)) in data.variant_prefixes.iter().enumerate() {
        aarch64_regex_redux_report_prefix(&mut assembler, offset, bytes)?;
        aarch64_regex_redux_stack_load(
            &mut assembler,
            9,
            X86_REGEX_REDUX_COUNTS_OFFSET + variant * 8,
        )?;
        aarch64_regex_redux_report_u64(&mut assembler)?;
        aarch64_regex_redux_report_byte(&mut assembler, b'\n')?;
    }
    aarch64_regex_redux_report_byte(&mut assembler, b'\n')?;
    aarch64_regex_redux_stack_load(&mut assembler, 9, X86_REGEX_REDUX_HAYSTACK_LEN_OFFSET)?;
    aarch64_regex_redux_report_u64(&mut assembler)?;
    aarch64_regex_redux_report_byte(&mut assembler, b'\n')?;
    aarch64_regex_redux_stack_load(&mut assembler, 9, X86_REGEX_REDUX_CLEAN_LEN_OFFSET)?;
    aarch64_regex_redux_report_u64(&mut assembler)?;
    aarch64_regex_redux_report_byte(&mut assembler, b'\n')?;
    assembler.instruction(aarch64_mov_x(9, 20)?)?;
    aarch64_regex_redux_report_u64(&mut assembler)?;
    aarch64_regex_redux_report_byte(&mut assembler, b'\n')?;
    assembler.instruction(aarch64_cmp_x_imm(
        23,
        u16::try_from(crate::NATIVE_REGEX_REDUX_AOT_V1_REPORT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("regex-redux report bound"))?,
    )?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;

    aarch64_regex_redux_stack_load(&mut assembler, 11, X86_REGEX_REDUX_REPORT_OFFSET)?;
    assembler.instruction(aarch64_movz_x(9, 0, 0)?)?;
    let report_copy = assembler.label()?;
    let report_copied = assembler.label()?;
    assembler.branch_zero_x(23, report_copied)?;
    assembler.bind(report_copy)?;
    assembler.instruction(aarch64_load_byte_reg(10, 24, 9)?)?;
    assembler.instruction(aarch64_regex_redux_store_byte_reg(10, 11, 9)?)?;
    assembler.instruction(aarch64_add_x_imm(9, 9, 1)?)?;
    assembler.instruction(aarch64_cmp_x(9, 23)?)?;
    assembler.branch_cond(AARCH64_LO, report_copy)?;
    assembler.bind(report_copied)?;
    aarch64_regex_redux_publish_receipt(&mut assembler)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    assembler.instruction(aarch64_add_x_imm(9, 31, AARCH64_REGEX_REDUX_SAVED_OFFSET)?)?;
    for (first, second, offset) in [(19, 20, 0), (21, 22, 16), (23, 24, 32), (29, 30, 48)] {
        assembler.instruction(aarch64_load_pair_x(first, second, 9, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, AARCH64_REGEX_REDUX_FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_before_frame)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    if call_offsets.len() != crate::NATIVE_REGEX_REDUX_AOT_V1_COMPONENTS
        || call_offsets
            .iter()
            .enumerate()
            .any(|(expected, &(component, _))| component != expected)
    {
        return Err(ObjectError::InvalidModule(
            "regex-redux AArch64 call closure",
        ));
    }
    let mut relocation_offsets = Vec::new();
    relocation_offsets
        .try_reserve_exact(2 + call_offsets.len())
        .map_err(|_| ObjectError::Allocation("regex-redux AArch64 relocation offsets"))?;
    relocation_offsets.extend([data_page, data_page_offset]);
    relocation_offsets.extend(call_offsets.iter().map(|&(_, offset)| offset));
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;

    let mut relocations = Vec::new();
    relocations
        .try_reserve_exact(relocation_offsets.len())
        .map_err(|_| ObjectError::Allocation("regex-redux AArch64 relocations"))?;
    relocations.push(ModuleRelocation {
        section: REGEX_REDUX_TEXT_SECTION,
        offset: offset_u64(relocation_offsets[0], "regex-redux AArch64 data page")?,
        kind: RelocationKind::Aarch64Page21,
        symbol: REGEX_REDUX_DATA_SYMBOL,
        addend: 0,
    });
    relocations.push(ModuleRelocation {
        section: REGEX_REDUX_TEXT_SECTION,
        offset: offset_u64(
            relocation_offsets[1],
            "regex-redux AArch64 data page offset",
        )?,
        kind: RelocationKind::Aarch64PageOff12,
        symbol: REGEX_REDUX_DATA_SYMBOL,
        addend: 0,
    });
    for (component, &(expected, _)) in call_offsets.iter().enumerate() {
        if component != expected {
            return Err(ObjectError::InvalidModule(
                "regex-redux AArch64 relocation closure",
            ));
        }
        relocations.push(ModuleRelocation {
            section: REGEX_REDUX_TEXT_SECTION,
            offset: offset_u64(
                relocation_offsets[component + 2],
                "regex-redux AArch64 component",
            )?,
            kind: RelocationKind::Aarch64Branch26,
            symbol: REGEX_REDUX_COMPONENT_SYMBOL_BASE + component,
            addend: 0,
        });
    }
    Ok((code, relocations))
}

/// Emit Intel-recommended NOP encodings into unreachable post-return space.
/// Nine-byte chunks keep the instruction audit explicit without bloating the
/// compiler, and the exact remainder covers every power-of-two alignment.
fn x86_emit_unreachable_nops(
    assembler: &mut X86Assembler,
    mut bytes: usize,
) -> Result<(), ObjectError> {
    const NOP9: &[u8] = &[0x66, 0x0f, 0x1f, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00];
    while bytes >= NOP9.len() {
        assembler.instruction(NOP9)?;
        bytes = bytes
            .checked_sub(NOP9.len())
            .ok_or(ObjectError::ArithmeticOverflow("x86 cold padding"))?;
    }
    let tail = match bytes {
        0 => &[][..],
        1 => &[0x90][..],
        2 => &[0x66, 0x90][..],
        3 => &[0x0f, 0x1f, 0x00][..],
        4 => &[0x0f, 0x1f, 0x40, 0x00][..],
        5 => &[0x0f, 0x1f, 0x44, 0x00, 0x00][..],
        6 => &[0x66, 0x0f, 0x1f, 0x44, 0x00, 0x00][..],
        7 => &[0x0f, 0x1f, 0x80, 0x00, 0x00, 0x00, 0x00][..],
        8 => &[0x0f, 0x1f, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00][..],
        _ => return Err(ObjectError::InvalidModule("x86 cold padding remainder")),
    };
    if !tail.is_empty() {
        assembler.instruction(tail)?;
    }
    Ok(())
}

fn x86_emit_default_exception_lookup(
    assembler: &mut X86Assembler,
    exception_capacity: u8,
    cells: NativeCellEncoding,
    keys: NativeDefaultExceptionKeys,
) -> Result<(), ObjectError> {
    if !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
        || exception_capacity == 0
        || usize::from(exception_capacity) > MAX_NATIVE_DEFAULT_EXCEPTIONS
    {
        return Err(ObjectError::InvalidModule(
            "x86 default-exception row shape",
        ));
    }
    let value_offset = native_default_exception_value_offset(exception_capacity, cells).ok_or(
        ObjectError::InvalidModule("x86 default-exception value offset"),
    )?;
    let mut exception_labels = Vec::new();
    exception_labels
        .try_reserve_exact(usize::from(exception_capacity))
        .map_err(|_| ObjectError::Allocation("x86 default-exception labels"))?;
    for ordinal in 0..usize::from(exception_capacity) {
        let slot = if keys == NativeDefaultExceptionKeys::Boundaries {
            usize::from(exception_capacity)
                .checked_sub(ordinal)
                .and_then(|slot| slot.checked_sub(1))
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 default-exception boundary slot",
                ))?
        } else {
            ordinal
        };
        let label = assembler.label()?;
        exception_labels.push((slot, label));
        let key_offset = cells
            .bytes()
            .checked_add(slot)
            .and_then(|offset| u8::try_from(offset).ok())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 default-exception key offset",
            ))?;
        assembler.instruction(&[0x41, 0x3a, 0x42, key_offset])?; // cmp al,[r10+key]
        let branch = if keys == NativeDefaultExceptionKeys::Boundaries {
            &[0x0f, 0x83][..] // jae: byte is in this constant run or a later one
        } else {
            &[0x0f, 0x84][..] // je: exact class/raw-byte exception
        };
        assembler.branch(branch, label)?;
    }
    let done = assembler.label()?;
    match cells {
        NativeCellEncoding::Compact16 => {
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x02])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x02])?;
        }
        _ => unreachable!("validated bounded sparse cell width"),
    }
    assembler.branch(&[0xe9], done)?;
    for (slot, label) in exception_labels {
        assembler.bind(label)?;
        let cell_offset = value_offset
            .checked_add(slot.checked_mul(cells.bytes()).ok_or(
                ObjectError::ArithmeticOverflow("x86 default-exception cell offset"),
            )?)
            .and_then(|offset| u8::try_from(offset).ok())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 default-exception cell offset",
            ))?;
        match cells {
            NativeCellEncoding::Compact16 => {
                assembler.instruction(&[0x41, 0x0f, 0xb7, 0x42, cell_offset])?;
            }
            NativeCellEncoding::Wide32 => {
                assembler.instruction(&[0x41, 0x8b, 0x42, cell_offset])?;
            }
            _ => unreachable!("validated bounded sparse cell width"),
        }
        assembler.branch(&[0xe9], done)?;
    }
    assembler.bind(done)?;
    Ok(())
}

fn x86_emit_sparse_row_key_compare(
    assembler: &mut X86Assembler,
    slot: usize,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    let offset = cells
        .bytes()
        .checked_add(slot)
        .and_then(|offset| u32::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 scalable-exception key offset",
        ))?;
    if let Ok(offset) = i8::try_from(offset) {
        assembler.instruction(&[0x41, 0x3a, 0x42, offset.to_le_bytes()[0]])?; // cmp al,[r10+disp8]
    } else {
        let mut instruction = vec![0x41, 0x3a, 0x82]; // cmp al,[r10+disp32]
        instruction.extend_from_slice(&offset.to_le_bytes());
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_emit_sparse_row_value_load(
    assembler: &mut X86Assembler,
    value_offset: usize,
    slot: usize,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    let offset = value_offset
        .checked_add(slot.checked_mul(cells.bytes()).ok_or(
            ObjectError::ArithmeticOverflow("x86 scalable-exception value slot"),
        )?)
        .and_then(|offset| u32::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 scalable-exception value offset",
        ))?;
    if let Ok(offset) = i8::try_from(offset) {
        match cells {
            NativeCellEncoding::Compact16 => {
                assembler.instruction(&[
                    0x41,
                    0x0f,
                    0xb7,
                    0x42,
                    offset.to_le_bytes()[0],
                ])?; // movzx eax,word [r10+disp8]
            }
            NativeCellEncoding::Wide32 => {
                assembler.instruction(&[0x41, 0x8b, 0x42, offset.to_le_bytes()[0]])?; // mov eax,[r10+disp8]
            }
            _ => {
                return Err(ObjectError::InvalidModule(
                    "x86 scalable-exception value width",
                ));
            }
        }
    } else {
        let mut instruction = match cells {
            NativeCellEncoding::Compact16 => vec![0x41, 0x0f, 0xb7, 0x82],
            NativeCellEncoding::Wide32 => vec![0x41, 0x8b, 0x82],
            _ => {
                return Err(ObjectError::InvalidModule(
                    "x86 scalable-exception value width",
                ));
            }
        };
        instruction.extend_from_slice(&offset.to_le_bytes());
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_emit_sparse_binary_range(
    assembler: &mut X86Assembler,
    start: usize,
    end: usize,
    value_offset: usize,
    cells: NativeCellEncoding,
    default: X86Label,
    done: X86Label,
) -> Result<(), ObjectError> {
    if start >= end {
        return Err(ObjectError::InvalidModule(
            "x86 scalable-exception binary range",
        ));
    }
    let width = end.checked_sub(start).ok_or(ObjectError::ArithmeticOverflow(
        "x86 scalable-exception range width",
    ))?;
    if width == 1 {
        x86_emit_sparse_row_key_compare(assembler, start, cells)?;
        assembler.branch(&[0x0f, 0x85], default)?; // jne
        x86_emit_sparse_row_value_load(assembler, value_offset, start, cells)?;
        assembler.branch(&[0xe9], done)?;
        return Ok(());
    }
    let midpoint = start
        .checked_add(width / 2)
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 scalable-exception midpoint",
        ))?;
    let higher_start = midpoint.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
        "x86 scalable-exception higher range",
    ))?;
    let lower = assembler.label()?;
    let higher = (higher_start < end)
        .then(|| assembler.label())
        .transpose()?;
    x86_emit_sparse_row_key_compare(assembler, midpoint, cells)?;
    assembler.branch(&[0x0f, 0x82], lower)?; // jb
    assembler.branch(&[0x0f, 0x87], higher.unwrap_or(default))?; // ja
    x86_emit_sparse_row_value_load(assembler, value_offset, midpoint, cells)?;
    assembler.branch(&[0xe9], done)?;
    assembler.bind(lower)?;
    x86_emit_sparse_binary_range(
        assembler,
        start,
        midpoint,
        value_offset,
        cells,
        default,
        done,
    )?;
    if let Some(higher) = higher {
        assembler.bind(higher)?;
        x86_emit_sparse_binary_range(
            assembler,
            higher_start,
            end,
            value_offset,
            cells,
            default,
            done,
        )?;
    }
    Ok(())
}

const MAX_NATIVE_SPARSE_SCALAR_TAIL: usize = MAX_NATIVE_DEFAULT_EXCEPTIONS;

/// Target-neutral code-size route for a fixed-width sparse-key probe.
///
/// A one-to-four-key remainder is cheaper as the already-established scalar
/// tree than as another vector load, mask extraction and exact tail mask. The
/// scalar tail is emitted before vector code while the lookup key is still
/// live. Scalable rows may repeat their final real key and its value through
/// logical padding, while uniform rows repeat the default. Thus a padded tail
/// hit is semantically identical to the earlier logical hit; key uniqueness
/// is neither required nor assumed. Physical padding exists only through
/// capacity 16, where the single-vector inline sentinel remains in charge.
/// Larger remainders use one final exact masked vector chunk.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct NativeSparseChunkPlan {
    vector_width: usize,
    vector_keys: usize,
    vector_chunks: usize,
    scalar_tail: usize,
}

impl NativeSparseChunkPlan {
    fn chunk_start(self, chunk: usize) -> Option<usize> {
        (chunk < self.vector_chunks)
            .then(|| chunk.checked_mul(self.vector_width))
            .flatten()
    }

    fn chunk_live_lanes(self, chunk: usize) -> Option<usize> {
        let start = self.chunk_start(chunk)?;
        self.vector_keys
            .checked_sub(start)
            .map(|remaining| remaining.min(self.vector_width))
    }

    fn scalar_tail_start(self) -> Option<usize> {
        (self.scalar_tail != 0).then_some(self.vector_keys)
    }
}

fn native_sparse_chunk_plan(
    capacity: usize,
    vector_width: usize,
    readable_key_bytes: usize,
) -> Option<NativeSparseChunkPlan> {
    if capacity == 0 || vector_width == 0 || !vector_width.is_power_of_two() {
        return None;
    }
    let remainder = capacity.checked_rem(vector_width)?;
    let scalar_tail = if remainder <= MAX_NATIVE_SPARSE_SCALAR_TAIL {
        remainder
    } else {
        0
    };
    let vector_keys = capacity.checked_sub(scalar_tail)?;
    if vector_keys == 0 {
        return None;
    }
    let vector_chunks = vector_keys
        .checked_add(vector_width.checked_sub(1)?)?
        .checked_div(vector_width)?;
    // This is the end of the final physical load, not merely the final live
    // key. It proves every full chunk and an overlapping masked tail stay in
    // the row. In particular, post-64 AVX-512 tails may safely read into the
    // value area, while a no-full-chunk compact 17..20 row cannot use ZMM.
    let final_load_end = vector_chunks.checked_mul(vector_width)?;
    (final_load_end <= readable_key_bytes).then_some(NativeSparseChunkPlan {
        vector_width,
        vector_keys,
        vector_chunks,
        scalar_tail,
    })
}

/// Minimum number of comparisons made by the emitted balanced scalar tree
/// for a key that is absent from a non-empty range. The hot profile counts
/// only modal-default bytes, which are proved absent from every exception
/// range, so this lower bound applies to every weighted query.
fn native_sparse_binary_miss_comparisons(width: usize) -> Option<usize> {
    if width == 0 {
        return Some(0);
    }
    if width == 1 {
        return Some(1);
    }
    let midpoint = width.checked_div(2)?;
    let lower = native_sparse_binary_miss_comparisons(midpoint)?.checked_add(1)?;
    let higher_width = width.checked_sub(midpoint)?.checked_sub(1)?;
    let higher = if higher_width == 0 {
        1
    } else {
        native_sparse_binary_miss_comparisons(higher_width)?.checked_add(1)?
    };
    Some(lower.min(higher))
}

/// Instruction-equivalent work on the common no-exception path for the exact
/// emitted plan. This deliberately uses the plan's vector chunk count and its
/// separate scalar tail instead of approximating work as `ceil(C / tier)`.
fn native_sparse_plan_miss_units(
    plan: NativeSparseChunkPlan,
    vector_chunk_units: u8,
    scalar_compare_units: u8,
) -> Option<u128> {
    native_sparse_plan_miss_units_with_scalar(
        plan,
        vector_chunk_units,
        scalar_compare_units,
        true,
    )
}

fn native_sparse_plan_miss_units_with_scalar(
    plan: NativeSparseChunkPlan,
    vector_chunk_units: u8,
    scalar_compare_units: u8,
    include_scalar_tail: bool,
) -> Option<u128> {
    if vector_chunk_units == 0 || scalar_compare_units == 0 {
        return None;
    }
    let vector = u128::try_from(plan.vector_chunks)
        .ok()?
        .checked_mul(u128::from(vector_chunk_units))?;
    let scalar = if include_scalar_tail {
        u128::try_from(native_sparse_binary_miss_comparisons(plan.scalar_tail)?)
            .ok()?
            .checked_mul(u128::from(scalar_compare_units))?
    } else {
        0
    };
    vector.checked_add(scalar)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct NativeSparseBoundaryCost {
    guard_units: u8,
    vector_chunk_units: u8,
    scalar_compare_units: u8,
    full_scalar_tail_is_shared: bool,
    short_path_units: u8,
}

/// Admit one target-native duplicate-boundary tier only when a deliberately
/// conservative static model clears a two-to-one margin. The guard is paid on
/// every byte in every semantic row, while short-path work is paid on every
/// byte in rows that can stop at the tier, including exception hits. Gross
/// savings count only graph-proven modal-default misses and the exact
/// difference between the backend's full and prefix plans. A backend can mark
/// its full scalar tail as shared before the guard. Checked `u128` arithmetic
/// makes an oversized graph decline the optional optimization instead of
/// wrapping its cost.
fn select_native_sparse_boundary_tier(
    profile: NativeSparseBoundaryProfile,
    exception_capacity: u8,
    threshold: u8,
    prefix_plan: NativeSparseChunkPlan,
    full_plan: NativeSparseChunkPlan,
    cost: NativeSparseBoundaryCost,
) -> Option<u8> {
    if !profile.is_valid()
        || !NATIVE_SPARSE_BOUNDARY_TIERS.contains(&threshold)
        || threshold == 0
        || exception_capacity <= threshold
        || cost.guard_units == 0
        || prefix_plan.vector_width != full_plan.vector_width
        || prefix_plan
            .vector_keys
            .checked_add(prefix_plan.scalar_tail)?
            != usize::from(threshold)
        || full_plan
            .vector_keys
            .checked_add(full_plan.scalar_tail)?
            != usize::from(exception_capacity)
    {
        return None;
    }
    let prefix_work = native_sparse_plan_miss_units(
        prefix_plan,
        cost.vector_chunk_units,
        cost.scalar_compare_units,
    )?;
    let full_work = native_sparse_plan_miss_units_with_scalar(
        full_plan,
        cost.vector_chunk_units,
        cost.scalar_compare_units,
        !cost.full_scalar_tail_is_shared,
    )?;
    let saved_per_stoppable_query = full_work.checked_sub(prefix_work)?;
    if saved_per_stoppable_query == 0 {
        return None;
    }
    let guard_paid = u128::from(profile.semantic_rows)
        .checked_mul(u128::try_from(CLASS_MAP_BYTES).ok()?)?
        .checked_mul(u128::from(cost.guard_units))?;
    let short_path_paid = u128::from(profile.stoppable_row_byte_units(threshold)?)
        .checked_mul(u128::from(cost.short_path_units))?;
    let paid = guard_paid.checked_add(short_path_paid)?;
    let saved = u128::from(profile.stoppable_default_miss_byte_units(threshold)?)
        .checked_mul(saved_per_stoppable_query)?;
    let required = paid.checked_mul(2)?;
    (saved > required).then_some(threshold)
}

const X86_SPARSE_BOUNDARY_COST: NativeSparseBoundaryCost = NativeSparseBoundaryCost {
    guard_units: 3,
    vector_chunk_units: 4,
    scalar_compare_units: 2,
    full_scalar_tail_is_shared: true,
    short_path_units: 0,
};
const AARCH64_SPARSE_BOUNDARY_COST: NativeSparseBoundaryCost = NativeSparseBoundaryCost {
    guard_units: 4,
    vector_chunk_units: 2,
    scalar_compare_units: 2,
    full_scalar_tail_is_shared: false,
    short_path_units: 1,
};

fn native_hybrid_sparse_work_is_profitable(
    profile: NativeSparseBoundaryProfile,
    short_work: u128,
    long_work: u128,
    guard_units: u8,
    short_path_units: u8,
) -> Option<bool> {
    if !profile.is_valid()
        || short_work >= long_work
        || guard_units == 0
    {
        return Some(false);
    }
    let threshold = NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY;
    let guard_paid = u128::from(profile.semantic_rows)
        .checked_mul(u128::try_from(CLASS_MAP_BYTES).ok()?)?
        .checked_mul(u128::from(guard_units))?;
    let short_paid = u128::from(profile.stoppable_row_byte_units(threshold)?)
        .checked_mul(u128::from(short_path_units))?;
    let paid = guard_paid.checked_add(short_paid)?;
    let saved = u128::from(profile.stoppable_default_miss_byte_units(threshold)?)
        .checked_mul(long_work.checked_sub(short_work)?)?;
    Some(saved > paid.checked_mul(2)?)
}

fn native_hybrid_sparse_guard_is_profitable(
    profile: NativeSparseBoundaryProfile,
    exception_capacity: u8,
    cells: NativeCellEncoding,
    target: Target,
) -> bool {
    if exception_capacity <= NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY {
        return false;
    }
    match target.architecture {
        Architecture::X86_64 => {
            let kind = x86_start_filter_kind(target.features);
            let Some(short) = x86_sparse_lookup_chunk_plan_for_row(
                NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
                NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
                cells,
                kind,
            ) else {
                return false;
            };
            let Some(long) = x86_sparse_lookup_chunk_plan_for_row(
                exception_capacity,
                exception_capacity,
                cells,
                kind,
            ) else {
                return false;
            };
            let Some(short_work) = native_sparse_plan_miss_units(short, 4, 2) else {
                return false;
            };
            let Some(long_work) = native_sparse_plan_miss_units(long, 4, 2) else {
                return false;
            };
            native_hybrid_sparse_work_is_profitable(
                profile,
                short_work,
                long_work,
                X86_SPARSE_BOUNDARY_COST.guard_units,
                1,
            ) == Some(true)
        }
        Architecture::Aarch64 => {
            match aarch64_primary_scanner_isa(
                target.operating_system,
                target.features,
                true,
            ) {
                Aarch64PrimaryScannerIsa::Scalar => {
                    let Some(short_work) = native_sparse_binary_miss_comparisons(
                        usize::from(NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY),
                    )
                    .and_then(|work| u128::try_from(work).ok())
                    .and_then(|work| work.checked_mul(2))
                    else {
                        return false;
                    };
                    let Some(long_work) = native_sparse_binary_miss_comparisons(
                        usize::from(exception_capacity),
                    )
                    .and_then(|work| u128::try_from(work).ok())
                    .and_then(|work| work.checked_mul(2))
                    else {
                        return false;
                    };
                    native_hybrid_sparse_work_is_profitable(
                        profile,
                        short_work,
                        long_work,
                        AARCH64_SPARSE_BOUNDARY_COST.guard_units,
                        AARCH64_SPARSE_BOUNDARY_COST.short_path_units,
                    ) == Some(true)
                }
                Aarch64PrimaryScannerIsa::Asimd => {
                    let Some(short) = aarch64_sparse_lookup_chunk_plan_for_row(
                        NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
                        NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
                        cells,
                    ) else {
                        return false;
                    };
                    let Some(long) = aarch64_sparse_lookup_chunk_plan_for_row(
                        exception_capacity,
                        exception_capacity,
                        cells,
                    ) else {
                        return false;
                    };
                    let Some(short_work) = native_sparse_plan_miss_units(short, 2, 2) else {
                        return false;
                    };
                    let Some(long_work) = native_sparse_plan_miss_units(long, 2, 2) else {
                        return false;
                    };
                    native_hybrid_sparse_work_is_profitable(
                        profile,
                        short_work,
                        long_work,
                        AARCH64_SPARSE_BOUNDARY_COST.guard_units,
                        AARCH64_SPARSE_BOUNDARY_COST.short_path_units,
                    ) == Some(true)
                }
                // Runtime SVE vector length can cover the complete 255-key
                // semantic maximum in one probe. With no guaranteed lookup
                // work reduction, a fixed table that fits must win. Resource
                // rescue remains available when only the compact image fits.
                Aarch64PrimaryScannerIsa::Sve
                | Aarch64PrimaryScannerIsa::SveWithAsimdVl16 => false,
            }
        }
    }
}

fn x86_sparse_lookup_lane_width(
    exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> usize {
    let capacity = usize::from(exception_capacity);
    match (kind, cells, capacity) {
        (X86StartFilterKind::Sse2, _, _)
        | (X86StartFilterKind::Avx2, _, 0..=16)
        | (X86StartFilterKind::Avx512Bw, NativeCellEncoding::Compact16, 0..=20) => 16,
        (X86StartFilterKind::Avx2, _, _) => 32,
        (X86StartFilterKind::Avx512Bw, _, _) => 64,
    }
}

fn x86_sparse_lookup_chunk_plan(
    exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> Option<NativeSparseChunkPlan> {
    x86_sparse_lookup_chunk_plan_for_row(
        exception_capacity,
        exception_capacity,
        cells,
        kind,
    )
}

fn x86_sparse_lookup_chunk_plan_for_row(
    row_exception_capacity: u8,
    probe_exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> Option<NativeSparseChunkPlan> {
    if probe_exception_capacity > row_exception_capacity {
        return None;
    }
    let row_bytes = native_default_exception_row_bytes(row_exception_capacity, cells)?;
    let readable_key_bytes = row_bytes.checked_sub(cells.bytes())?;
    native_sparse_chunk_plan(
        usize::from(probe_exception_capacity),
        x86_sparse_lookup_lane_width(probe_exception_capacity, cells, kind),
        readable_key_bytes,
    )
}

fn x86_sparse_lookup_needs_vzeroupper(
    exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> bool {
    x86_sparse_lookup_chunk_plan(exception_capacity, cells, kind).is_some_and(|plan| {
        matches!(kind, X86StartFilterKind::Avx2)
            || matches!(kind, X86StartFilterKind::Avx512Bw) && plan.vector_width == 64
    })
}

fn x86_sparse_boundary_tier(
    layout: &NativeDfaLayout,
    kind: X86StartFilterKind,
) -> Option<u8> {
    let exception_capacity = layout.transitions.scalable_exception_capacity()?;
    let threshold = match kind {
        X86StartFilterKind::Sse2 => 16,
        X86StartFilterKind::Avx2 => 32,
        X86StartFilterKind::Avx512Bw => 64,
    };
    let prefix_plan = x86_sparse_lookup_chunk_plan_for_row(
        exception_capacity,
        threshold,
        layout.cells,
        kind,
    )?;
    let full_plan = x86_sparse_lookup_chunk_plan(exception_capacity, layout.cells, kind)?;
    select_native_sparse_boundary_tier(
        layout.sparse_boundary_profile?,
        exception_capacity,
        threshold,
        prefix_plan,
        full_plan,
        X86_SPARSE_BOUNDARY_COST,
    )
}

fn x86_emit_sparse_duplicate_boundary_guard(
    assembler: &mut X86Assembler,
    row_exception_capacity: u8,
    threshold: u8,
    cells: NativeCellEncoding,
    full: X86Label,
) -> Result<(), ObjectError> {
    if threshold == 0
        || threshold >= row_exception_capacity
        || !NATIVE_SPARSE_BOUNDARY_TIERS.contains(&threshold)
        || !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
    {
        return Err(ObjectError::InvalidModule(
            "x86 scalable duplicate-boundary guard shape",
        ));
    }
    let displacement = cells
        .bytes()
        .checked_add(usize::from(threshold).checked_sub(1).ok_or(
            ObjectError::ArithmeticOverflow("x86 sparse boundary tier"),
        )?)
        .and_then(|offset| u32::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 sparse boundary key offset",
        ))?;
    let mut load = vec![0x41, 0x0f, 0xb7, 0x82]; // movzx eax,word [r10+disp32]
    load.extend_from_slice(&displacement.to_le_bytes());
    assembler.instruction(&load)?;
    assembler.instruction(&[0x38, 0xe0])?; // cmp al,ah
    assembler.branch(&[0x0f, 0x85], full)?; // distinct keys prove count > tier
    Ok(())
}

fn x86_emit_sparse_vector_broadcast(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
    vector_width: usize,
) -> Result<(), ObjectError> {
    match (kind, vector_width) {
        (X86StartFilterKind::Sse2, 16) => {
            assembler.instruction(&[0x69, 0xc0, 0x01, 0x01, 0x01, 0x01])?; // imul eax,0x01010101
            assembler.instruction(&[0x66, 0x0f, 0x6e, 0xc0])?; // movd xmm0,eax
            assembler.instruction(&[0x66, 0x0f, 0x70, 0xc0, 0x00])?; // pshufd xmm0,xmm0,0
        }
        (X86StartFilterKind::Avx512Bw, 16) => {
            // AVX-512F+BW does not imply AVX2 or AVX-512VL, but it does
            // provide the VEX.128 forms of these baseline operations. Keep
            // the narrow compact-row route VEX encoded so a ZMM scanner can
            // enter table lookup without an AVX-to-legacy-SSE transition.
            assembler.instruction(&[0x69, 0xc0, 0x01, 0x01, 0x01, 0x01])?; // imul eax,0x01010101
            assembler.instruction(&[0xc5, 0xf9, 0x6e, 0xc0])?; // vmovd xmm0,eax
            assembler.instruction(&[0xc5, 0xf9, 0x70, 0xc0, 0x00])?; // vpshufd xmm0,xmm0,0
        }
        (X86StartFilterKind::Avx2, 16) => {
            assembler.instruction(&[0xc5, 0xf9, 0x6e, 0xc0])?; // vmovd xmm0,eax
            assembler.instruction(&[0xc4, 0xe2, 0x79, 0x78, 0xc0])?; // vpbroadcastb xmm0,xmm0
        }
        (X86StartFilterKind::Avx2, 32) => {
            assembler.instruction(&[0xc5, 0xf9, 0x6e, 0xc0])?; // vmovd xmm0,eax
            assembler.instruction(&[0xc4, 0xe2, 0x7d, 0x78, 0xc0])?; // vpbroadcastb ymm0,xmm0
        }
        (X86StartFilterKind::Avx512Bw, 64) => {
            assembler.instruction(&[0x62, 0xf2, 0x7d, 0x48, 0x7a, 0xc0])?; // vpbroadcastb zmm0,eax
        }
        _ => {
            return Err(ObjectError::InvalidModule(
                "x86 scalable vector broadcast width",
            ));
        }
    }
    Ok(())
}

/// Produce one exact local-lane mask without destroying the broadcast.
///
/// XMM/YMM14 is caller-saved and disjoint from persistent scanner state:
/// graph-derived scanner constants occupy registers 1..9, retained candidates live in
/// R12/R13, and sparse-batch accumulation uses register 15. Prefix-relation
/// code uses register 14 only as a defined-and-consumed negation temporary
/// before it can branch to table lookup; every scanner reentry defines it
/// again. Keeping the broadcast in register zero is therefore safe across any
/// number of table chunks. AVX-512 writes K1 and likewise retains ZMM0.
fn x86_emit_sparse_vector_mask(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
    vector_width: usize,
    key_offset: u32,
    live_lanes: usize,
) -> Result<(), ObjectError> {
    if live_lanes == 0 || live_lanes > vector_width {
        return Err(ObjectError::InvalidModule(
            "x86 scalable vector live lanes",
        ));
    }
    match (kind, vector_width) {
        (X86StartFilterKind::Sse2, 16) => {
            let mut load = vec![0xf3, 0x45, 0x0f, 0x6f, 0xb2]; // movdqu xmm14,[r10+disp32]
            load.extend_from_slice(&key_offset.to_le_bytes());
            assembler.instruction(&load)?;
            assembler.instruction(&[0x66, 0x44, 0x0f, 0x74, 0xf0])?; // pcmpeqb xmm14,xmm0
            assembler.instruction(&[0x66, 0x41, 0x0f, 0xd7, 0xc6])?; // pmovmskb eax,xmm14
        }
        (X86StartFilterKind::Avx2, 16 | 32) | (X86StartFilterKind::Avx512Bw, 16) => {
            let vex_l = if vector_width == 16 { 0x79 } else { 0x7d };
            let mut compare = vec![0xc4, 0x41, vex_l, 0x74, 0xb2]; // vpcmpeqb xmm/ymm14,xmm/ymm0,[r10+disp32]
            compare.extend_from_slice(&key_offset.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.instruction(&[0xc4, 0xc1, vex_l, 0xd7, 0xc6])?; // vpmovmskb eax,xmm/ymm14
        }
        (X86StartFilterKind::Avx512Bw, 64) => {
            let mut compare = vec![0x62, 0xd1, 0x7d, 0x48, 0x74, 0x8a]; // vpcmpeqb k1,zmm0,[r10+disp32]
            compare.extend_from_slice(&key_offset.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.instruction(&[0xc4, 0xe1, 0xfb, 0x93, 0xc1])?; // kmovq rax,k1
        }
        _ => {
            return Err(ObjectError::InvalidModule(
                "x86 scalable vector mask width",
            ));
        }
    }
    if live_lanes == vector_width {
        return Ok(());
    }
    if vector_width == 64 {
        let shift = vector_width.checked_sub(live_lanes).ok_or(
            ObjectError::ArithmeticOverflow("x86 AVX-512 sparse live lanes"),
        )?;
        let shift = u8::try_from(shift).map_err(|_| {
            ObjectError::ArithmeticOverflow("x86 AVX-512 sparse live shift")
        })?;
        assembler.instruction(&[0x48, 0xc1, 0xe0, shift])?; // shl rax,64-live
        assembler.instruction(&[0x48, 0xc1, 0xe8, shift])?; // shr rax,64-live
    } else {
        let live_bits = u32::try_from(live_lanes)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 sparse live lanes"))?;
        let live_mask = 1_u32
            .checked_shl(live_bits)
            .and_then(|mask| mask.checked_sub(1))
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 sparse live mask",
            ))?;
        x86_emit_and_eax_mask(assembler, live_mask)?;
    }
    Ok(())
}

fn x86_emit_sparse_vector_value_load(
    assembler: &mut X86Assembler,
    value_offset: usize,
    chunk_start: usize,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    let displacement = chunk_start
        .checked_mul(cells.bytes())
        .and_then(|offset| value_offset.checked_add(offset))
        .and_then(|offset| u32::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 scalable vector value offset",
        ))?;
    let mut load = match cells {
        NativeCellEncoding::Compact16 => vec![0x41, 0x0f, 0xb7, 0x84, 0x42],
        NativeCellEncoding::Wide32 => vec![0x41, 0x8b, 0x84, 0x82],
        _ => {
            return Err(ObjectError::InvalidModule(
                "x86 scalable vector value width",
            ));
        }
    };
    load.extend_from_slice(&displacement.to_le_bytes());
    assembler.instruction(&load).map(|_| ())
}

/// Emit only the vector part of a sparse lookup after the byte key has
/// already been broadcast. The caller owns `done`, which lets a guarded
/// prefix and its full-row alternative share one broadcast and one join.
fn x86_emit_sparse_vector_lookup_from_broadcast(
    assembler: &mut X86Assembler,
    plan: NativeSparseChunkPlan,
    value_offset: usize,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
    default: X86Label,
    done: X86Label,
) -> Result<(), ObjectError> {
    let mut vector_hits = Vec::new();
    vector_hits
        .try_reserve_exact(plan.vector_chunks)
        .map_err(|_| ObjectError::Allocation("x86 scalable vector hit labels"))?;
    for chunk in 0..plan.vector_chunks {
        let chunk_start = plan.chunk_start(chunk).ok_or(ObjectError::InvalidModule(
            "x86 scalable vector chunk start",
        ))?;
        let live_lanes = plan
            .chunk_live_lanes(chunk)
            .ok_or(ObjectError::InvalidModule(
                "x86 scalable vector chunk lanes",
            ))?;
        let key_offset = cells
            .bytes()
            .checked_add(chunk_start)
            .and_then(|offset| u32::try_from(offset).ok())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 scalable vector key offset",
            ))?;
        x86_emit_sparse_vector_mask(
            assembler,
            kind,
            plan.vector_width,
            key_offset,
            live_lanes,
        )?;
        if plan.vector_width == 64 {
            assembler.instruction(&[0x48, 0x85, 0xc0])?; // test rax,rax
        } else {
            assembler.instruction(&[0x85, 0xc0])?; // test eax,eax
        }
        let hit = assembler.label()?;
        assembler.branch(&[0x0f, 0x85], hit)?; // rare nonzero mask
        vector_hits.push((chunk_start, hit));
    }
    // No-match is the common path: all zero masks fall through every chunk to
    // one default load. Rare hit stubs retain each local mask and fold the
    // chunk base into their indexed value displacement.
    assembler.bind(default)?;
    match cells {
        NativeCellEncoding::Compact16 => {
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x02])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x02])?;
        }
        _ => unreachable!("validated scalable sparse cell width"),
    }
    assembler.branch(&[0xe9], done)?;
    for (chunk_start, hit) in vector_hits {
        assembler.bind(hit)?;
        if plan.vector_width == 64 {
            assembler.instruction(&[0x48, 0x0f, 0xbc, 0xc0])?; // bsf rax,rax
        } else {
            assembler.instruction(&[0x0f, 0xbc, 0xc0])?; // bsf eax,eax
        }
        x86_emit_sparse_vector_value_load(assembler, value_offset, chunk_start, cells)?;
        assembler.branch(&[0xe9], done)?;
    }
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "scalar-tail cost routing, three vector widths, exact masks and one common default share one lookup contract"
)]
fn x86_emit_sparse_exception_lookup(
    assembler: &mut X86Assembler,
    exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    x86_emit_sparse_exception_lookup_prefix(
        assembler,
        exception_capacity,
        exception_capacity,
        cells,
        kind,
    )
}

#[allow(
    clippy::too_many_lines,
    reason = "scalar-tail cost routing, three vector widths, exact masks and one common default share one lookup contract"
)]
fn x86_emit_sparse_exception_lookup_prefix(
    assembler: &mut X86Assembler,
    row_exception_capacity: u8,
    probe_exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    let value_offset = native_default_exception_value_offset(row_exception_capacity, cells).ok_or(
        ObjectError::InvalidModule("x86 scalable-exception value offset"),
    )?;
    x86_emit_sparse_exception_lookup_prefix_with_value_offset(
        assembler,
        row_exception_capacity,
        probe_exception_capacity,
        cells,
        kind,
        value_offset,
    )
}

fn x86_emit_sparse_exception_lookup_prefix_with_value_offset(
    assembler: &mut X86Assembler,
    row_exception_capacity: u8,
    probe_exception_capacity: u8,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
    value_offset: usize,
) -> Result<(), ObjectError> {
    let capacity = usize::from(probe_exception_capacity);
    let row_capacity = usize::from(row_exception_capacity);
    if !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
        || capacity <= MAX_NATIVE_DEFAULT_EXCEPTIONS
        || capacity > row_capacity
        || row_capacity > MAX_NATIVE_SPARSE_EXCEPTIONS
    {
        return Err(ObjectError::InvalidModule(
            "x86 scalable-exception row shape",
        ));
    }
    if value_offset
        < cells
            .bytes()
            .checked_add(capacity)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 scalable-exception key extent",
            ))?
        || !value_offset.is_multiple_of(cells.bytes())
    {
        return Err(ObjectError::InvalidModule(
            "x86 scalable-exception explicit value offset",
        ));
    }
    let inline_default_slot = probe_exception_capacity == row_exception_capacity
        && row_capacity < native_default_exception_physical_slots(row_exception_capacity);
    let default = assembler.label()?;
    let done = assembler.label()?;
    let Some(plan) = x86_sparse_lookup_chunk_plan_for_row(
        row_exception_capacity,
        probe_exception_capacity,
        cells,
        kind,
    ) else {
        x86_emit_sparse_binary_range(
            assembler,
            0,
            capacity,
            value_offset,
            cells,
            default,
            done,
        )?;
        assembler.bind(default)?;
        match cells {
            NativeCellEncoding::Compact16 => {
                assembler.instruction(&[0x41, 0x0f, 0xb7, 0x02])?;
            }
            NativeCellEncoding::Wide32 => {
                assembler.instruction(&[0x41, 0x8b, 0x02])?;
            }
            _ => unreachable!("validated scalable sparse cell width"),
        }
        assembler.bind(done)?;
        return Ok(());
    };

    // PMOVMSKB/KMOV overwrite EAX and therefore AL. Compare a cheap scalar
    // tail first, then broadcast the still-live key exactly once. Any repeated
    // logical padding key carries the same packed value as its first copy.
    if let Some(tail_start) = plan.scalar_tail_start() {
        let vector_start = assembler.label()?;
        x86_emit_sparse_binary_range(
            assembler,
            tail_start,
            capacity,
            value_offset,
            cells,
            vector_start,
            done,
        )?;
        assembler.bind(vector_start)?;
    }
    x86_emit_sparse_vector_broadcast(assembler, kind, plan.vector_width)?;
    if inline_default_slot {
        if plan.vector_chunks != 1 || plan.scalar_tail != 0 {
            return Err(ObjectError::InvalidModule(
                "x86 scalable inline-default route",
            ));
        }
        let chunk_start = plan.chunk_start(0).ok_or(ObjectError::InvalidModule(
            "x86 scalable inline-default chunk",
        ))?;
        let live_lanes = plan.chunk_live_lanes(0).ok_or(ObjectError::InvalidModule(
            "x86 scalable inline-default lanes",
        ))?;
        let key_offset = cells
            .bytes()
            .checked_add(chunk_start)
            .and_then(|offset| u32::try_from(offset).ok())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 scalable vector key offset",
            ))?;
        x86_emit_sparse_vector_mask(
            assembler,
            kind,
            plan.vector_width,
            key_offset,
            live_lanes,
        )?;
        let default_bit = 1_u32
            .checked_shl(u32::from(probe_exception_capacity))
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 scalable inline-default lane",
            ))?;
        x86_emit_or_eax_mask(assembler, default_bit)?;
        if plan.vector_width == 64 {
            assembler.instruction(&[0x48, 0x0f, 0xbc, 0xc0])?; // bsf rax,rax
        } else {
            assembler.instruction(&[0x0f, 0xbc, 0xc0])?; // bsf eax,eax
        }
        x86_emit_sparse_vector_value_load(assembler, value_offset, chunk_start, cells)?;
        return Ok(());
    }
    x86_emit_sparse_vector_lookup_from_broadcast(
        assembler,
        plan,
        value_offset,
        cells,
        kind,
        default,
        done,
    )?;
    assembler.bind(done)?;
    Ok(())
}

fn x86_emit_ordinal_map_lookup(
    assembler: &mut X86Assembler,
    value_capacity: u8,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    if value_capacity == 0
        || !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
    {
        return Err(ObjectError::InvalidModule("x86 ordinal-map row shape"));
    }
    let map_offset = native_ordinal_map_value_bytes(value_capacity, cells)
        .and_then(|offset| u32::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow("x86 ordinal-map offset"))?;
    if let Ok(displacement) = i8::try_from(map_offset) {
        assembler.instruction(&[
            0x41,
            0x0f,
            0xb6,
            0x44,
            0x02,
            displacement.to_le_bytes()[0],
        ])?; // eax = row.ordinal_map[eax]
    } else {
        let mut load = vec![0x41, 0x0f, 0xb6, 0x84, 0x02];
        load.extend_from_slice(&map_offset.to_le_bytes());
        assembler.instruction(&load)?; // eax = row.ordinal_map[eax]
    }
    match cells {
        NativeCellEncoding::Compact16 => {
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x04, 0x42])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x04, 0x82])?;
        }
        _ => unreachable!("validated x86 ordinal cell width"),
    }
    Ok(())
}

fn x86_emit_ordinal_offset_map_lookup(
    assembler: &mut X86Assembler,
    value_capacity: u8,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    if value_capacity == 0
        || !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
    {
        return Err(ObjectError::InvalidModule("x86 ordinal offset-map row shape"));
    }
    assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x02])?; // eax = row.byte_offset[eax]
    match cells {
        NativeCellEncoding::Compact16 => {
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x04, 0x02])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x04, 0x02])?;
        }
        _ => unreachable!("validated x86 ordinal offset cell width"),
    }
    Ok(())
}

fn x86_emit_bit_slice_lookup(
    assembler: &mut X86Assembler,
    value_capacity: u8,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    if value_capacity != NATIVE_BIT_SLICE_VALUE_CAPACITY
        || !matches!(cells, NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32)
    {
        return Err(ObjectError::InvalidModule("x86 bit-slice row shape"));
    }
    let bitmap_offset = native_bit_slice_bitmap_offset(cells)
        .and_then(|offset| u8::try_from(offset).ok())
        .ok_or(ObjectError::ArithmeticOverflow("x86 bit-slice bitmap offset"))?;
    // RAX is a zero-extended class/raw-byte ordinal. BT treats the aligned
    // qwords beginning at this displacement as one bit string, so the row's
    // padded final word proves every possible register-indexed access.
    assembler.instruction(&[0x49, 0x0f, 0xa3, 0x42, bitmap_offset])?;
    assembler.instruction(&[0x0f, 0x92, 0xc0])?; // setc al
    match cells {
        NativeCellEncoding::Compact16 => {
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x04, 0x42])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x04, 0x82])?;
        }
        _ => unreachable!("validated x86 bit-slice cell width"),
    }
    Ok(())
}

fn x86_emit_table_lookup(
    assembler: &mut X86Assembler,
    transitions: TransitionLayout,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    x86_emit_table_lookup_with_sparse_boundary_tier(
        assembler,
        transitions,
        cells,
        kind,
        None,
    )
}

#[allow(
    clippy::too_many_lines,
    reason = "dense, bounded, scalable and guarded scalable rows share one table-lookup contract"
)]
fn x86_emit_table_lookup_with_sparse_boundary_tier(
    assembler: &mut X86Assembler,
    transitions: TransitionLayout,
    cells: NativeCellEncoding,
    kind: X86StartFilterKind,
    sparse_boundary_tier: Option<u8>,
) -> Result<(), ObjectError> {
    if transitions == TransitionLayout::DefaultExceptions(0) {
        // Every raw byte names the same packed cell. Load it directly without
        // touching either the haystack or the omitted class map, and without
        // branching around an empty exception list.
        match cells {
            NativeCellEncoding::Compact16 => {
                assembler.instruction(&[0x41, 0x0f, 0xb7, 0x02])?;
            }
            NativeCellEncoding::Wide32 => {
                assembler.instruction(&[0x41, 0x8b, 0x02])?;
            }
            _ => {
                return Err(ObjectError::InvalidModule(
                    "x86 uniform default row shape",
                ));
            }
        }
        return Ok(());
    }
    if let TransitionLayout::HybridSparseExceptions(exception_capacity)
    | TransitionLayout::HybridByteSparseExceptions(exception_capacity) = transitions
    {
        if sparse_boundary_tier.is_some()
            || exception_capacity <= NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY
        {
            return Err(ObjectError::InvalidModule(
                "x86 hybrid sparse dispatch shape",
            ));
        }
        let long = assembler.label()?;
        let done = assembler.label()?;
        // This discriminator intentionally precedes the input load: its two
        // key loads overwrite EAX. Short padding proves equality, while every
        // long row has real, ascending and therefore distinct keys 15/16.
        x86_emit_sparse_duplicate_boundary_guard(
            assembler,
            exception_capacity,
            NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
            cells,
            long,
        )?;
        assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
        if matches!(transitions, TransitionLayout::HybridSparseExceptions(_)) {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?;
        }
        let short_value_offset = native_hybrid_sparse_short_value_offset(cells).ok_or(
            ObjectError::InvalidModule("x86 hybrid sparse short value offset"),
        )?;
        x86_emit_sparse_exception_lookup_prefix_with_value_offset(
            assembler,
            NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
            NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
            cells,
            kind,
            short_value_offset,
        )?;
        assembler.branch(&[0xe9], done)?;
        assembler.bind(long)?;
        assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
        if matches!(transitions, TransitionLayout::HybridSparseExceptions(_)) {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?;
        }
        x86_emit_sparse_exception_lookup(assembler, exception_capacity, cells, kind)?;
        assembler.bind(done)?;
        return Ok(());
    }
    if let Some(threshold) = sparse_boundary_tier {
        let (exception_capacity, class_keyed) = match transitions {
            TransitionLayout::DefaultSparseExceptions(capacity) => (capacity, true),
            TransitionLayout::DefaultByteSparseExceptions(capacity) => (capacity, false),
            _ => {
                return Err(ObjectError::InvalidModule(
                    "x86 sparse boundary tier reached a dense table",
                ));
            }
        };
        let value_offset = native_default_exception_value_offset(exception_capacity, cells)
            .ok_or(ObjectError::InvalidModule(
                "x86 scalable-exception value offset",
            ))?;
        let prefix_plan = x86_sparse_lookup_chunk_plan_for_row(
            exception_capacity,
            threshold,
            cells,
            kind,
        )
        .ok_or(ObjectError::InvalidModule(
            "x86 sparse boundary prefix plan",
        ))?;
        let full_plan = x86_sparse_lookup_chunk_plan(exception_capacity, cells, kind).ok_or(
            ObjectError::InvalidModule("x86 sparse boundary full plan"),
        )?;
        if prefix_plan.scalar_tail != 0
            || prefix_plan.vector_width != full_plan.vector_width
        {
            return Err(ObjectError::InvalidModule(
                "x86 sparse boundary plan mismatch",
            ));
        }
        // Keep AL live through the complete full-row scalar tail. Only then
        // broadcast once; the duplicate-boundary probe may overwrite EAX,
        // but both vector alternatives retain the byte in register zero.
        assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?; // eax = haystack[position]
        if class_keyed {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
        }
        let full = assembler.label()?;
        let done = assembler.label()?;
        if let Some(tail_start) = full_plan.scalar_tail_start() {
            let vector_start = assembler.label()?;
            x86_emit_sparse_binary_range(
                assembler,
                tail_start,
                usize::from(exception_capacity),
                value_offset,
                cells,
                vector_start,
                done,
            )?;
            assembler.bind(vector_start)?;
        }
        x86_emit_sparse_vector_broadcast(assembler, kind, full_plan.vector_width)?;
        x86_emit_sparse_duplicate_boundary_guard(
            assembler,
            exception_capacity,
            threshold,
            cells,
            full,
        )?;
        let prefix_default = assembler.label()?;
        x86_emit_sparse_vector_lookup_from_broadcast(
            assembler,
            prefix_plan,
            value_offset,
            cells,
            kind,
            prefix_default,
            done,
        )?;
        assembler.bind(full)?;
        let full_default = assembler.label()?;
        x86_emit_sparse_vector_lookup_from_broadcast(
            assembler,
            full_plan,
            value_offset,
            cells,
            kind,
            full_default,
            done,
        )?;
        assembler.bind(done)?;
        return Ok(());
    }
    // eax = haystack[position]
    assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
    match transitions {
        TransitionLayout::ClassMapped => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
        }
        TransitionLayout::DirectByte => {}
        TransitionLayout::DefaultExceptions(exception_capacity) => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
            x86_emit_default_exception_lookup(
                assembler,
                exception_capacity,
                cells,
                NativeDefaultExceptionKeys::Classes,
            )?;
            return Ok(());
        }
        TransitionLayout::DefaultByteExceptions(exception_capacity) => {
            x86_emit_default_exception_lookup(
                assembler,
                exception_capacity,
                cells,
                NativeDefaultExceptionKeys::Bytes,
            )?;
            return Ok(());
        }
        TransitionLayout::DefaultByteBoundaries(exception_capacity) => {
            x86_emit_default_exception_lookup(
                assembler,
                exception_capacity,
                cells,
                NativeDefaultExceptionKeys::Boundaries,
            )?;
            return Ok(());
        }
        TransitionLayout::DefaultSparseExceptions(exception_capacity) => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
            x86_emit_sparse_exception_lookup(assembler, exception_capacity, cells, kind)?;
            return Ok(());
        }
        TransitionLayout::DefaultByteSparseExceptions(exception_capacity) => {
            x86_emit_sparse_exception_lookup(assembler, exception_capacity, cells, kind)?;
            return Ok(());
        }
        TransitionLayout::OrdinalMapClasses(value_capacity) => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
            x86_emit_ordinal_map_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::OrdinalMapBytes(value_capacity) => {
            x86_emit_ordinal_map_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::OrdinalOffsetClasses(value_capacity) => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
            x86_emit_ordinal_offset_map_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::OrdinalOffsetBytes(value_capacity) => {
            x86_emit_ordinal_offset_map_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::BitSliceClasses(value_capacity) => {
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // eax = class_map[eax]
            x86_emit_bit_slice_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::BitSliceBytes(value_capacity) => {
            x86_emit_bit_slice_lookup(assembler, value_capacity, cells)?;
            return Ok(());
        }
        TransitionLayout::HybridSparseExceptions(_)
        | TransitionLayout::HybridByteSparseExceptions(_) => {
            unreachable!("hybrid sparse lookup returned before the ordinary dispatch")
        }
    }
    match cells {
        NativeCellEncoding::Compact8Direct => {
            // eax = zero_extend(packed_row[byte])
            assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x02])?;
        }
        NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            // eax = zero_extend(packed_row[class_or_byte])
            assembler.instruction(&[0x41, 0x0f, 0xb7, 0x04, 0x42])?;
        }
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x41, 0x8b, 0x04, 0x82])?;
        }
    }
    Ok(())
}

fn x86_emit_test_eax_mask(assembler: &mut X86Assembler, mask: u32) -> Result<(), ObjectError> {
    let mut instruction = vec![0xa9]; // test eax, imm32
    instruction.extend_from_slice(&mask.to_le_bytes());
    assembler.instruction(&instruction).map(|_| ())
}

fn x86_emit_and_eax_mask(assembler: &mut X86Assembler, mask: u32) -> Result<(), ObjectError> {
    let mut instruction = vec![0x25];
    instruction.extend_from_slice(&mask.to_le_bytes());
    assembler.instruction(&instruction).map(|_| ())
}

fn x86_emit_or_eax_mask(assembler: &mut X86Assembler, mask: u32) -> Result<(), ObjectError> {
    let mut instruction = vec![0x0d];
    instruction.extend_from_slice(&mask.to_le_bytes());
    assembler.instruction(&instruction).map(|_| ())
}

fn x86_emit_clear_eax_bit(assembler: &mut X86Assembler, bit: u8) -> Result<(), ObjectError> {
    if bit >= 32 {
        return Err(ObjectError::InvalidModule("x86 packed-cell flag bit"));
    }
    assembler.instruction(&[0x0f, 0xba, 0xf0, bit])?; // btr eax, bit
    Ok(())
}

fn x86_emit_unsigned_cell_classifier(
    assembler: &mut X86Assembler,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    match cells {
        NativeCellEncoding::Compact8Direct => {
            let maximum = u8::try_from(cells.next_mask().saturating_sub(1))
                .map_err(|_| ObjectError::InvalidModule("byte-compact classifier overflowed"))?;
            assembler.instruction(&[0x3c, maximum])?; // cmp al, next_mask - 1
        }
        NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            let mut compare = vec![0x3d]; // cmp eax, next_mask - 1
            compare.extend_from_slice(&cells.next_mask().saturating_sub(1).to_le_bytes());
            assembler.instruction(&compare)?;
        }
        NativeCellEncoding::Wide32 => {
            let mut compare = vec![0x3d]; // cmp eax, next_mask
            compare.extend_from_slice(&cells.next_mask().to_le_bytes());
            assembler.instruction(&compare)?;
        }
    }
    Ok(())
}

/// Scale a zero-based compact row ordinal and add the table base.
///
/// The table prefix is an exact multiple of `row_bytes`, so the token already
/// includes every physical prefix row. Factor class counts of 3, 5, or 9 use
/// one LEA followed by the address LEA. All other counts use one immediate
/// IMUL followed by the same scaled address LEA. The 14-bit token and at-most
/// 256 graph classes prove the 32-bit product cannot wrap.
fn x86_emit_set_row_from_compact_ordinal(
    assembler: &mut X86Assembler,
    row_bytes: u16,
) -> Result<(), ObjectError> {
    let row_bytes = usize::from(row_bytes);
    if row_bytes == 0
        || row_bytes.is_power_of_two()
        || !row_bytes.is_multiple_of(core::mem::size_of::<u16>())
    {
        return Err(ObjectError::InvalidModule(
            "x86 compact ordinal row stride",
        ));
    }
    let class_count = row_bytes
        .checked_div(core::mem::size_of::<u16>())
        .filter(|&classes| (1..=CLASS_MAP_BYTES).contains(&classes))
        .ok_or(ObjectError::InvalidModule(
            "x86 compact ordinal class count",
        ))?;
    let power = class_count.trailing_zeros();
    let odd = class_count >> power;
    let address_shift = power
        .checked_add(1)
        .filter(|&shift| shift <= 3);
    let address_scale = if let Some(address_shift) = address_shift
        && matches!(odd, 3 | 5 | 9)
    {
        let first_scale = match odd {
            3 => 0x40,
            5 => 0x80,
            9 => 0xc0,
            _ => unreachable!("guarded compact ordinal LEA factor"),
        };
        assembler.instruction(&[0x8d, 0x04, first_scale])?; // eax *= 3, 5, or 9
        1_u8 << u8::try_from(address_shift).map_err(|_| {
            ObjectError::ArithmeticOverflow("x86 compact ordinal address shift")
        })?
    } else {
        if let Ok(immediate) = u8::try_from(class_count)
            && immediate <= i8::MAX.cast_unsigned()
        {
            assembler.instruction(&[0x6b, 0xc0, immediate])?; // imul eax,eax,imm8
        } else {
            let immediate = u32::try_from(class_count).map_err(|_| {
                ObjectError::ArithmeticOverflow("x86 compact ordinal class count")
            })?;
            let mut instruction = vec![0x69, 0xc0]; // imul eax,eax,imm32
            instruction.extend_from_slice(&immediate.to_le_bytes());
            assembler.instruction(&instruction)?;
        }
        2
    };
    let sib = match address_scale {
        1 => 0x01,
        2 => 0x41,
        4 => 0x81,
        8 => 0xc1,
        _ => {
            return Err(ObjectError::InvalidModule(
                "x86 compact ordinal address scale",
            ));
        }
    };
    assembler.instruction(&[0x4d, 0x8d, 0x14, sib])?; // r10 = table + scaled ordinal
    Ok(())
}

fn x86_emit_set_row_from_cell(
    assembler: &mut X86Assembler,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    match cells {
        // r10 = table + encoded - 1
        NativeCellEncoding::Wide32 => {
            assembler.instruction(&[0x4d, 0x8d, 0x54, 0x01, 0xff])?;
        }
        NativeCellEncoding::Compact8Direct
        | NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            return Err(ObjectError::InvalidModule(
                "zero-based compact cell entered biased x86 row addressing",
            ));
        }
    }
    Ok(())
}

fn x86_emit_set_row_from_compact_zero_based_cell(
    assembler: &mut X86Assembler,
    cells: NativeCellEncoding,
) -> Result<(), ObjectError> {
    match cells {
        NativeCellEncoding::Compact8Direct => {
            // r10 = table + zero_based_token * 256
            assembler.instruction(&[0xc1, 0xe0, 0x08])?; // shl eax, 8
            assembler.instruction(&[0x4d, 0x8d, 0x14, 0x01])?;
        }
        NativeCellEncoding::Compact16 => {
            // r10 = table + zero_based_token * 2
            assembler.instruction(&[0x4d, 0x8d, 0x14, 0x41])?;
        }
        NativeCellEncoding::Compact16Indexed(shift) => {
            // r10 = table + zero_based_token * row_bytes
            assembler.instruction(&[0xc1, 0xe0, shift])?; // shl eax, row shift
            assembler.instruction(&[0x4d, 0x8d, 0x14, 0x01])?;
        }
        NativeCellEncoding::Compact16Ordinal(row_bytes) => {
            x86_emit_set_row_from_compact_ordinal(assembler, row_bytes)?;
        }
        NativeCellEncoding::Wide32 => {
            return Err(ObjectError::InvalidModule(
                "wide cell entered compact row addressing",
            ));
        }
    }
    Ok(())
}

fn x86_set_row(assembler: &mut X86Assembler, table_offset: u32) -> Result<(), ObjectError> {
    let mut instruction = vec![0x4d, 0x8d, 0x91];
    instruction.extend_from_slice(&table_offset.to_le_bytes());
    assembler.instruction(&instruction)?;
    Ok(())
}

fn x86_emit_exact_span_start(assembler: &mut X86Assembler, width: u64) -> Result<(), ObjectError> {
    assembler.instruction(&[0x4c, 0x89, 0xd8])?; // start = selected end
    if let Ok(width) = u8::try_from(width)
        && width <= 0x7f
    {
        assembler.instruction(&[0x48, 0x83, 0xe8, width])?; // sub rax, imm8
    } else if let Ok(width) = i32::try_from(width) {
        let mut instruction = vec![0x48, 0x2d]; // sub rax, imm32
        instruction.extend_from_slice(&width.to_le_bytes());
        assembler.instruction(&instruction)?;
    } else {
        let mut load = vec![0x49, 0xba]; // movabs r10, width
        load.extend_from_slice(&width.to_le_bytes());
        assembler.instruction(&load)?;
        assembler.instruction(&[0x4c, 0x29, 0xd0])?; // sub rax, r10
    }
    Ok(())
}

fn x86_emit_exact_prefix_match(
    assembler: &mut X86Assembler,
    width: u8,
    output: OutputContract,
    register_outcome: bool,
    matched: X86Label,
) -> Result<(), ObjectError> {
    if width == 0 || usize::from(width) > MAX_ANCHORED_PREFIX_BYTES {
        return Err(ObjectError::InvalidModule(
            "invalid x86 exact-prefix match width",
        ));
    }
    if output != OutputContract::Exists {
        assembler.instruction(&[0x48, 0x8d, 0x42, width])?; // end = candidate + width
        if register_outcome {
            if output == OutputContract::Span {
                assembler.instruction(&[0x49, 0x89, 0xd2])?; // r10 = candidate
            }
            assembler.instruction(&[0x49, 0x89, 0xc3])?; // r11 = end
        } else if output == OutputContract::Span {
            assembler.instruction(&[0x49, 0x89, 0x10])?; // result.start = candidate
        } else {
            assembler.instruction(&[0x49, 0x89, 0x00])?; // result.start = end
            assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?; // result.end = end
        }
        if !register_outcome && output == OutputContract::Span {
            assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?; // result.end = end
        }
    }
    assembler.branch(&[0xe9], matched)?;
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum X86StartFilterKind {
    /// SSE2 is an architectural baseline capability of x86-64.
    Sse2,
    /// AVX2 is emitted only when explicitly present in [`Target::features`].
    Avx2,
    /// The 64-byte path needs AVX-512F and AVX-512BW, but not AVX-512VL.
    Avx512Bw,
}

/// Location of the exact lane mask produced by one x86 vector filter.
///
/// SSE2 and AVX2 materialize their masks in `eax`. AVX-512BW comparisons
/// produce 64 lane bits directly in an opmask register: exact membership uses
/// `k1`, range membership uses `k4`, and a graph-proven multi-column
/// intersection uses `k5`. Keeping that distinction explicit prevents a
/// 64-lane mask from accidentally taking a 32-bit `pmovmskb`/`bsf` path.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum X86CandidateMask {
    MovemaskEax,
    Avx512K1,
    Avx512K4,
    Avx512K5,
    /// Four-vector sparse-filter accumulator. K6 is outside the candidate and
    /// lazy-intersection bank and remains caller-saved on supported targets.
    Avx512K6,
}

impl X86CandidateMask {
    fn for_filter(filter: NativeStartFilter, kind: X86StartFilterKind) -> Self {
        match kind {
            X86StartFilterKind::Sse2 | X86StartFilterKind::Avx2 => Self::MovemaskEax,
            X86StartFilterKind::Avx512Bw if filter.is_exact() => Self::Avx512K1,
            X86StartFilterKind::Avx512Bw => Self::Avx512K4,
        }
    }

    const fn for_intersection(kind: X86StartFilterKind) -> Self {
        match kind {
            X86StartFilterKind::Sse2 | X86StartFilterKind::Avx2 => Self::MovemaskEax,
            X86StartFilterKind::Avx512Bw => Self::Avx512K5,
        }
    }

    const fn opmask_register(self) -> Option<u8> {
        match self {
            Self::MovemaskEax => None,
            Self::Avx512K1 => Some(1),
            Self::Avx512K4 => Some(4),
            Self::Avx512K5 => Some(5),
            Self::Avx512K6 => Some(6),
        }
    }
}

fn x86_emit_candidate_nonzero(
    assembler: &mut X86Assembler,
    mask: X86CandidateMask,
) -> Result<(), ObjectError> {
    if let Some(register) = mask.opmask_register() {
        // KORTESTQ kN, kN. The opmask is deliberately retained for the rare
        // taken branch, where KMOVQ+BSFQ selects one of all 64 lanes.
        assembler.instruction(&[0xc4, 0xe1, 0xf8, 0x98, 0xc0 | (register << 3) | register])?;
    } else {
        assembler.instruction(&[0x85, 0xc0])?; // test eax, eax
    }
    Ok(())
}

fn x86_emit_first_candidate_lane(
    assembler: &mut X86Assembler,
    mask: X86CandidateMask,
) -> Result<(), ObjectError> {
    if let Some(register) = mask.opmask_register() {
        // KMOVQ rax, kN followed by BSFQ preserves every AVX-512 lane,
        // including lanes 32..63. The caller has already proved nonzero.
        assembler.instruction(&[0xc4, 0xe1, 0xfb, 0x93, 0xc0 | register])?;
        assembler.instruction(&[0x48, 0x0f, 0xbc, 0xc0])?;
    } else {
        assembler.instruction(&[0x0f, 0xbc, 0xc0])?; // bsf eax, eax
    }
    Ok(())
}

fn x86_emit_retain_candidate_mask(
    assembler: &mut X86Assembler,
    mask: X86CandidateMask,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x49, 0x89, 0xd4])?; // r12 = vector block base
    if let Some(register) = mask.opmask_register() {
        // Preserve all 64 AVX-512 lanes before any scalar guard can clobber
        // RAX or the temporary opmask bank.
        assembler.instruction(&[0xc4, 0xe1, 0xfb, 0x93, 0xc0 | register])?; // rax = kN
        assembler.instruction(&[0x49, 0x89, 0xc5])?; // r13 = rax
    } else {
        assembler.instruction(&[0x41, 0x89, 0xc5])?; // r13d = eax
    }
    Ok(())
}

fn x86_emit_first_retained_candidate(assembler: &mut X86Assembler) -> Result<(), ObjectError> {
    assembler.instruction(&[0x49, 0x0f, 0xbc, 0xc5])?; // bsf rax, r13
    assembler.instruction(&[0x49, 0x8d, 0x14, 0x04])?; // position = r12 + rax
    Ok(())
}

fn x86_emit_clear_first_retained_candidate(
    assembler: &mut X86Assembler,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x49, 0x8d, 0x45, 0xff])?; // rax = r13 - 1
    assembler.instruction(&[0x49, 0x21, 0xc5])?; // r13 &= rax
    assembler.instruction(&[0x4d, 0x85, 0xed])?; // test r13, r13
    Ok(())
}

fn x86_emit_advance_retained_block(
    assembler: &mut X86Assembler,
    width: u8,
) -> Result<(), ObjectError> {
    if !matches!(width, 16 | 32 | 64) {
        return Err(ObjectError::InvalidModule("x86 retained-mask vector width"));
    }
    assembler.instruction(&[0x49, 0x8d, 0x54, 0x24, width])?; // position = base + width
    Ok(())
}

fn x86_emit_avx512_copy_mask_to_k5(
    assembler: &mut X86Assembler,
    source: X86CandidateMask,
) -> Result<(), ObjectError> {
    let register = source.opmask_register().ok_or(ObjectError::InvalidModule(
        "AVX-512 intersection primary is not an opmask",
    ))?;
    if !matches!(register, 1 | 4) {
        return Err(ObjectError::InvalidModule(
            "AVX-512 intersection primary opmask register",
        ));
    }
    // KORQ k5, kN, kN. VEX.vvvv selects the first source and ModRM.r/m the
    // second; both are the source mask, so this is an exact copy.
    let vex = 0xfc_u8 & !(register << 3);
    assembler.instruction(&[0xc4, 0xe1, vex, 0x45, 0xe8 | register])?;
    Ok(())
}

fn x86_emit_avx512_intersect_k5(
    assembler: &mut X86Assembler,
    source: X86CandidateMask,
) -> Result<(), ObjectError> {
    let register = source.opmask_register().ok_or(ObjectError::InvalidModule(
        "AVX-512 intersection secondary is not an opmask",
    ))?;
    if !matches!(register, 1 | 4) {
        return Err(ObjectError::InvalidModule(
            "AVX-512 intersection secondary opmask register",
        ));
    }
    // KANDQ k5, k5, kN.
    assembler.instruction(&[0xc4, 0xe1, 0xd4, 0x41, 0xe8 | register])?;
    Ok(())
}

fn x86_start_filter_kind(features: FeatureSet) -> X86StartFilterKind {
    if features.has(CpuFeature::X86Avx512F) && features.has(CpuFeature::X86Avx512Bw) {
        X86StartFilterKind::Avx512Bw
    } else if features.has(CpuFeature::X86Avx2) {
        X86StartFilterKind::Avx2
    } else {
        X86StartFilterKind::Sse2
    }
}

impl X86StartFilterKind {
    const fn width(self) -> u8 {
        match self {
            Self::Sse2 => 16,
            Self::Avx2 => 32,
            Self::Avx512Bw => 64,
        }
    }

    const fn needs_vzeroupper(self) -> bool {
        !matches!(self, Self::Sse2)
    }
}

fn x86_use_sparse_filter_mask_batch(filter: NativeStartFilter, kind: X86StartFilterKind) -> bool {
    filter_fits_expected_hit_budget(
        filter,
        u16::from(kind.width()).saturating_mul(X86_MASK_BATCH_VECTORS),
        MAX_SPARSE_RESCAN_EXPECTED_HITS,
    )
}

fn x86_filter_constant_register(
    first_register: u8,
    logical_index: usize,
) -> Result<u8, ObjectError> {
    let logical_index = u8::try_from(logical_index)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 filter constant register"))?;
    let register =
        first_register
            .checked_add(logical_index)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 filter constant register",
            ))?;
    if register == 0 || register > 8 {
        return Err(ObjectError::InvalidModule("x86 filter constant register"));
    }
    Ok(register)
}

fn x86_emit_start_filter_constants(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
    first_register: u8,
) -> Result<(), ObjectError> {
    for (index, range) in filter.ranges().iter().enumerate() {
        if filter.is_exact() {
            let register = x86_filter_constant_register(first_register, index)?;
            x86_emit_splat_byte(assembler, register, range.start, kind)?;
        } else {
            let logical_low = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
                "x86 range-filter low register",
            ))?;
            let low_register = x86_filter_constant_register(first_register, logical_low)?;
            let high_register = x86_filter_constant_register(
                first_register,
                logical_low
                    .checked_add(1)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 range-filter high register",
                    ))?,
            )?;
            x86_emit_splat_byte(assembler, low_register, range.start, kind)?;
            x86_emit_splat_byte(assembler, high_register, range.end, kind)?;
        }
    }
    Ok(())
}

fn x86_emit_prefix_relation_constants(
    assembler: &mut X86Assembler,
    plan: NativePrefixRelationVectorPlan,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    if plan.constant_count > MAX_X86_PREFIX_RELATION_CONSTANTS {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-relation constant budget",
        ));
    }
    for rectangle in plan.rectangles() {
        for predicate in [rectangle.first, rectangle.second] {
            if !predicate.any {
                x86_emit_start_filter_constants(
                    assembler,
                    predicate.filter,
                    kind,
                    predicate.first_constant,
                )?;
            }
        }
    }
    Ok(())
}

fn x86_emit_sse2_binary(
    assembler: &mut X86Assembler,
    opcode: u8,
    destination: u8,
    source: u8,
) -> Result<(), ObjectError> {
    if destination > 15 || source > 15 {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-relation SSE2 register",
        ));
    }
    let rex = 0x40 | u8::from(destination >= 8) << 2 | u8::from(source >= 8);
    let mut instruction = vec![0x66];
    if rex != 0x40 {
        instruction.push(rex);
    }
    instruction.extend_from_slice(&[0x0f, opcode, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
    assembler.instruction(&instruction)?;
    Ok(())
}

fn x86_emit_avx2_binary(
    assembler: &mut X86Assembler,
    opcode: u8,
    destination: u8,
    left: u8,
    right: u8,
) -> Result<(), ObjectError> {
    if [destination, left, right]
        .iter()
        .any(|register| *register > 15)
    {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-relation AVX2 binary register",
        ));
    }
    let mut vex2 = 0xe1_u8;
    if destination >= 8 {
        vex2 &= !0x80;
    }
    if right >= 8 {
        vex2 &= !0x20;
    }
    let vex3 = 0x7d_u8 & !(left << 3);
    assembler.instruction(&[
        0xc4,
        vex2,
        vex3,
        opcode,
        0xc0 | ((destination & 7) << 3) | (right & 7),
    ])?;
    Ok(())
}

fn x86_emit_avx2_map38_binary(
    assembler: &mut X86Assembler,
    opcode: u8,
    destination: u8,
    left: u8,
    right: u8,
) -> Result<(), ObjectError> {
    if [destination, left, right]
        .iter()
        .any(|register| *register > 15)
    {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy AVX2 map38 register",
        ));
    }
    let mut vex2 = 0xe2_u8; // 0F38 map
    if destination >= 8 {
        vex2 &= !0x80;
    }
    if right >= 8 {
        vex2 &= !0x20;
    }
    let vex3 = 0x7d_u8 & !(left << 3); // 256-bit, 66 prefix
    assembler.instruction(&[
        0xc4,
        vex2,
        vex3,
        opcode,
        0xc0 | ((destination & 7) << 3) | (right & 7),
    ])?;
    Ok(())
}

fn x86_emit_avx2_shift_right_words(
    assembler: &mut X86Assembler,
    destination: u8,
    source: u8,
    amount: u8,
) -> Result<(), ObjectError> {
    if destination > 15 || source > 15 || amount > 15 {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy AVX2 word shift",
        ));
    }
    let mut vex2 = 0xe1_u8;
    if source >= 8 {
        vex2 &= !0x20;
    }
    let vex3 = 0x7d_u8 & !(destination << 3);
    assembler.instruction(&[
        0xc4,
        vex2,
        vex3,
        0x71,
        0xd0 | (source & 7), // /2: VPSRLW
        amount,
    ])?;
    Ok(())
}

fn x86_emit_avx2_table_load(
    assembler: &mut X86Assembler,
    destination: u8,
    displacement: i32,
) -> Result<(), ObjectError> {
    if destination > 15 {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy table register",
        ));
    }
    let mut vex2 = 0xc1_u8; // map 0F, base R9 (inverted B = 0)
    if destination >= 8 {
        vex2 &= !0x80;
    }
    let mut load = vec![
        0xc4,
        vex2,
        0x7e,
        0x6f,
        0x81 | ((destination & 7) << 3),
    ];
    load.extend_from_slice(&displacement.to_le_bytes());
    assembler.instruction(&load)?; // vmovdqu ymmN, disp32[r9]
    Ok(())
}

fn x86_emit_avx2_move(
    assembler: &mut X86Assembler,
    destination: u8,
    source: u8,
) -> Result<(), ObjectError> {
    if destination > 15 || source > 15 {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-relation AVX2 move register",
        ));
    }
    let mut vex2 = 0xe1_u8;
    if destination >= 8 {
        vex2 &= !0x80;
    }
    if source >= 8 {
        vex2 &= !0x20;
    }
    assembler.instruction(&[
        0xc4,
        vex2,
        0x7d,
        0x6f,
        0xc0 | ((destination & 7) << 3) | (source & 7),
    ])?;
    Ok(())
}

fn x86_emit_k_binary(
    assembler: &mut X86Assembler,
    opcode: u8,
    destination: u8,
    left: u8,
    right: u8,
) -> Result<(), ObjectError> {
    if destination == 0 || left == 0 || right == 0 || destination > 7 || left > 7 || right > 7 {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-relation opmask register",
        ));
    }
    let vex = 0xfc_u8 & !(left << 3);
    assembler.instruction(&[0xc4, 0xe1, vex, opcode, 0xc0 | (destination << 3) | right])?;
    Ok(())
}

fn x86_emit_prefix_relation_predicate(
    assembler: &mut X86Assembler,
    predicate: NativePrefixRelationPredicate,
    kind: X86StartFilterKind,
    destination: u8,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => {
            if predicate.any {
                return x86_emit_sse2_binary(assembler, 0x74, destination, destination);
            }
            x86_emit_start_filter_vector_candidates(
                assembler,
                predicate.filter,
                kind,
                predicate.first_constant,
            )?;
            if predicate.negated {
                x86_emit_sse2_binary(assembler, 0x74, 14, 14)?;
                x86_emit_sse2_binary(assembler, 0xef, 12, 14)?;
            }
            x86_emit_sse2_binary(assembler, 0x6f, destination, 12)
        }
        X86StartFilterKind::Avx2 => {
            if predicate.any {
                return x86_emit_avx2_binary(
                    assembler,
                    0x74,
                    destination,
                    destination,
                    destination,
                );
            }
            x86_emit_start_filter_vector_candidates(
                assembler,
                predicate.filter,
                kind,
                predicate.first_constant,
            )?;
            if predicate.negated {
                x86_emit_avx2_binary(assembler, 0x74, 14, 14, 14)?;
                x86_emit_avx2_binary(assembler, 0xef, 12, 12, 14)?;
            }
            x86_emit_avx2_move(assembler, destination, 12)
        }
        X86StartFilterKind::Avx512Bw => {
            if predicate.any {
                return x86_emit_k_binary(assembler, 0x45, destination, 7, 7);
            }
            x86_emit_start_filter_vector_candidates(
                assembler,
                predicate.filter,
                kind,
                predicate.first_constant,
            )?;
            let source = X86CandidateMask::for_filter(predicate.filter, kind)
                .opmask_register()
                .ok_or(ObjectError::InvalidModule(
                    "AVX-512 prefix-relation predicate mask",
                ))?;
            x86_emit_k_binary(
                assembler,
                if predicate.negated { 0x47 } else { 0x45 },
                destination,
                source,
                if predicate.negated { 7 } else { source },
            )
        }
    }
}

/// Emit the exact graph-derived union of byte-set rectangles for one vector.
/// The result stays in EAX for SSE2/AVX2 and K5 for AVX-512BW, so the shared
/// first-lane extraction observes every lane, including AVX-512 lanes 32..63.
fn x86_emit_prefix_relation_vector_test(
    assembler: &mut X86Assembler,
    plan: NativePrefixRelationVectorPlan,
    kind: X86StartFilterKind,
) -> Result<X86CandidateMask, ObjectError> {
    if plan.rectangles().is_empty() {
        return Err(ObjectError::InvalidModule(
            "empty x86 prefix-relation vector plan",
        ));
    }
    if kind == X86StartFilterKind::Avx512Bw {
        x86_emit_k_binary(assembler, 0x46, 7, 7, 7)?; // k7 = all ones
    }
    for (index, rectangle) in plan.rectangles().iter().copied().enumerate() {
        let first_destination = if kind == X86StartFilterKind::Avx512Bw {
            6
        } else {
            13
        };
        x86_emit_prefix_relation_predicate(assembler, rectangle.first, kind, first_destination)?;
        if !rectangle.second.any {
            let second_destination = if kind == X86StartFilterKind::Avx512Bw {
                1
            } else {
                12
            };
            x86_emit_prefix_relation_predicate(
                assembler,
                rectangle.second,
                kind,
                second_destination,
            )?;
            match kind {
                X86StartFilterKind::Sse2 => {
                    x86_emit_sse2_binary(assembler, 0xdb, 13, 12)?;
                }
                X86StartFilterKind::Avx2 => {
                    x86_emit_avx2_binary(assembler, 0xdb, 13, 13, 12)?;
                }
                X86StartFilterKind::Avx512Bw => {
                    x86_emit_k_binary(assembler, 0x41, 6, 6, 1)?;
                }
            }
        }
        match kind {
            X86StartFilterKind::Sse2 => {
                x86_emit_sse2_binary(assembler, if index == 0 { 0x6f } else { 0xeb }, 15, 13)?
            }
            X86StartFilterKind::Avx2 => {
                if index == 0 {
                    x86_emit_avx2_move(assembler, 15, 13)?;
                } else {
                    x86_emit_avx2_binary(assembler, 0xeb, 15, 15, 13)?;
                }
            }
            X86StartFilterKind::Avx512Bw => {
                x86_emit_k_binary(assembler, 0x45, 5, if index == 0 { 6 } else { 5 }, 6)?;
            }
        }
    }
    let mask = match kind {
        X86StartFilterKind::Sse2 => {
            x86_emit_sse2_binary(assembler, 0x6f, 12, 15)?;
            assembler.instruction(&[0x66, 0x41, 0x0f, 0xd7, 0xc4])?;
            X86CandidateMask::MovemaskEax
        }
        X86StartFilterKind::Avx2 => {
            x86_emit_avx2_move(assembler, 12, 15)?;
            assembler.instruction(&[0xc4, 0xc1, 0x7d, 0xd7, 0xc4])?;
            X86CandidateMask::MovemaskEax
        }
        X86StartFilterKind::Avx512Bw => X86CandidateMask::Avx512K5,
    };
    x86_emit_candidate_nonzero(assembler, mask)?;
    Ok(mask)
}

fn x86_emit_splat_byte(
    assembler: &mut X86Assembler,
    register: u8,
    byte: u8,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    if register == 0 || register > 8 {
        return Err(ObjectError::InvalidModule(
            "x86 start-filter constant register",
        ));
    }
    // Seed all four scalar bytes at once. SSE2 can then fill the complete
    // register with one dword shuffle instead of a byte unpack followed by
    // word and dword shuffles. AVX2/AVX-512 keep their single broadcast and
    // observe the same low byte.
    let mut load_immediate = vec![0xb8];
    load_immediate.extend_from_slice(&u32::from_le_bytes([byte; 4]).to_le_bytes());
    assembler.instruction(&load_immediate)?;
    let low_register = register & 7;
    let self_modrm = 0xc0 | (low_register << 3) | low_register;
    match (kind, register < 8) {
        (X86StartFilterKind::Sse2, true) => {
            assembler.instruction(&[0x66, 0x0f, 0x6e, 0xc0 | (register << 3)])?;
        }
        (X86StartFilterKind::Sse2, false) => {
            assembler.instruction(&[0x66, 0x44, 0x0f, 0x6e, 0xc0])?;
        }
        // Keep AVX and AVX-512 setup entirely VEX/EVEX encoded. A legacy MOVD
        // after an earlier full-width broadcast can otherwise trigger an
        // AVX-to-SSE transition assist while initializing multi-range filters.
        (X86StartFilterKind::Avx2 | X86StartFilterKind::Avx512Bw, true) => {
            assembler.instruction(&[0xc5, 0xf9, 0x6e, 0xc0 | (register << 3)])?;
        }
        (X86StartFilterKind::Avx2 | X86StartFilterKind::Avx512Bw, false) => {
            assembler.instruction(&[0xc5, 0x79, 0x6e, 0xc0])?;
        }
    }
    match kind {
        X86StartFilterKind::Sse2 if register < 8 => {
            assembler.instruction(&[0x66, 0x0f, 0x70, self_modrm, 0])?;
        }
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x45, 0x0f, 0x70, self_modrm, 0])?;
        }
        X86StartFilterKind::Avx2 if register < 8 => {
            assembler.instruction(&[0xc4, 0xe2, 0x7d, 0x78, self_modrm])?;
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc4, 0x42, 0x7d, 0x78, self_modrm])?;
        }
        X86StartFilterKind::Avx512Bw if register < 8 => {
            assembler.instruction(&[0x62, 0xf2, 0x7d, 0x48, 0x78, self_modrm])?;
        }
        X86StartFilterKind::Avx512Bw => {
            assembler.instruction(&[0x62, 0x52, 0x7d, 0x48, 0x78, self_modrm])?;
        }
    }
    Ok(())
}

fn x86_emit_start_filter_vector_load(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    let mut instruction = match kind {
        X86StartFilterKind::Sse2 => vec![0xf3, 0x0f, 0x6f],
        X86StartFilterKind::Avx2 => vec![0xc5, 0xfe, 0x6f],
        X86StartFilterKind::Avx512Bw => vec![0x62, 0xf1, 0x7f, 0x48, 0x6f],
    };
    if scan_offset == 0 {
        instruction.extend_from_slice(&[0x04, 0x17]);
    } else if kind == X86StartFilterKind::Avx512Bw || scan_offset > 0x7f {
        // EVEX disp8 is compressed and scales by the 64-byte ZMM tuple size.
        // Prefix/suffix byte-column offsets are ordinary byte displacements;
        // SSE/AVX disp8 is also signed. Encode either case as an unscaled
        // disp32 when the byte offset cannot use a positive ordinary disp8.
        instruction.extend_from_slice(&[0x84, 0x17]);
        instruction.extend_from_slice(&i32::from(scan_offset).to_le_bytes());
    } else {
        instruction.extend_from_slice(&[0x44, 0x17, scan_offset]);
    }
    assembler.instruction(&instruction)?;
    Ok(())
}

fn x86_emit_start_filter_scalar_load(
    assembler: &mut X86Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
    } else {
        assembler.instruction(&[0x0f, 0xb6, 0x44, 0x17, scan_offset])?;
    }
    Ok(())
}

fn x86_emit_exact_byte_set_scalar_load(
    assembler: &mut X86Assembler,
    scan_offset: u16,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
    } else if let Ok(displacement) = u8::try_from(scan_offset)
        && displacement <= 0x7f
    {
        assembler.instruction(&[0x0f, 0xb6, 0x44, 0x17, displacement])?;
    } else {
        let mut instruction = vec![0x0f, 0xb6, 0x84, 0x17];
        instruction.extend_from_slice(&i32::from(scan_offset).to_le_bytes());
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_emit_exact_byte_set_scalar_bound(
    assembler: &mut X86Assembler,
    scan_offset: u8,
    exhausted: X86Label,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(&[0x48, 0x39, 0xca])?; // cmp position, end
    } else if scan_offset <= 0x7f {
        assembler.instruction(&[0x48, 0x8d, 0x42, scan_offset])?;
        assembler.instruction(&[0x48, 0x39, 0xc8])?;
    } else {
        let mut address = vec![0x48, 0x8d, 0x82]; // lea disp32(position), scratch
        address.extend_from_slice(&i32::from(scan_offset).to_le_bytes());
        assembler.instruction(&address)?;
        assembler.instruction(&[0x48, 0x39, 0xc8])?;
    }
    assembler.branch(&[0x0f, 0x83], exhausted)?;
    Ok(())
}

/// Test EAX's byte value against the canonical little-endian 256-bit bitmap.
/// `BT [r9 + bitmap], rax` treats the four words as one contiguous bit string.
fn x86_emit_exact_byte_set_test(
    assembler: &mut X86Assembler,
    storage: NativeExactByteSetStorage,
    member: X86Label,
) -> Result<(), ObjectError> {
    x86_emit_exact_byte_set_test_with_base(assembler, storage, 9, member)
}

/// Test EAX against an exact-set bitmap addressed by one extended caller-
/// saved base register. Complete DFA entries use R9; dynamic roots use R10 so
/// their authenticated class map can remain live in R9.
fn x86_emit_exact_byte_set_test_with_base(
    assembler: &mut X86Assembler,
    storage: NativeExactByteSetStorage,
    base: u8,
    member: X86Label,
) -> Result<(), ObjectError> {
    if storage.aarch64_lut_offset.is_some() {
        return Err(ObjectError::InvalidModule(
            "x86 exact-set scanner received an AArch64 LUT",
        ));
    }
    if !(8..=15).contains(&base) {
        return Err(ObjectError::InvalidModule(
            "x86 exact-set scanner received an unsupported bitmap base",
        ));
    }
    let displacement = x86_exact_bitmap_displacement(storage)?;
    let mut test = vec![0x49, 0x0f, 0xa3, 0x80 | (base & 7)];
    test.extend_from_slice(&displacement.to_le_bytes());
    assembler.instruction(&test)?;
    assembler.branch(&[0x0f, 0x82], member)?; // jc
    Ok(())
}

fn x86_exact_bitmap_displacement(
    storage: NativeExactByteSetStorage,
) -> Result<i32, ObjectError> {
    i32::try_from(storage.bitmap_offset).map_err(|_| {
        ObjectError::InvalidModule("x86 exact-set bitmap exceeds signed displacement")
    })
}

fn x86_exact_nibble_displacement(
    storage: NativeExactByteSetStorage,
    table_index: u8,
) -> Result<i32, ObjectError> {
    const X86_NIBBLE_TABLE_STRIDE: u32 = 32;
    if storage.aarch64_lut_offset.is_some()
        || !storage.nibble_base.is_multiple_of(X86_NIBBLE_TABLE_STRIDE)
        || table_index > 3
    {
        return Err(ObjectError::InvalidModule(
            "x86 exact-set nibble-table storage is malformed",
        ));
    }
    let table_delta = u32::from(table_index)
        .checked_mul(X86_NIBBLE_TABLE_STRIDE)
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 exact-set nibble-table displacement",
        ))?;
    let displacement = storage
        .nibble_base
        .checked_add(table_delta)
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 exact-set nibble-table displacement",
        ))?;
    i32::try_from(displacement).map_err(|_| {
        ObjectError::InvalidModule("x86 exact-set nibble table exceeds signed displacement")
    })
}

/// Load the three duplicated nibble tables and the fixed low-nibble mask into
/// caller-saved YMM registers. These constants remain live across scalar DFA
/// work and prefix guards; those paths reserve YMM1..YMM3/YMM7 when the exact
/// primary owns the scanner route.
fn x86_emit_exact_avx2_constants(
    assembler: &mut X86Assembler,
    storage: NativeExactByteSetStorage,
) -> Result<(), ObjectError> {
    for (table_index, destination) in [(0_u8, 1_u8), (1, 2), (2, 3), (3, 7)] {
        let displacement = x86_exact_nibble_displacement(storage, table_index)?;
        let mut load = vec![0xc4, 0xc1, 0x7e, 0x6f, 0x81 | (destination << 3)];
        load.extend_from_slice(&displacement.to_le_bytes());
        assembler.instruction(&load)?; // vmovdqu ymmN, disp32[r9]
    }
    Ok(())
}

/// Broadcast the four canonical 32-byte exact-set tables into caller-saved
/// ZMM registers. `VBROADCASTI32X4` replicates the canonical 128-bit table
/// across all four lanes without increasing the immutable table footprint.
/// The instruction needs AVX-512F, while the classifier below additionally
/// needs AVX-512BW.
fn x86_emit_exact_avx512_constants(
    assembler: &mut X86Assembler,
    storage: NativeExactByteSetStorage,
) -> Result<(), ObjectError> {
    for (table_index, destination) in [(0_u8, 1_u8), (1, 2), (2, 3), (3, 7)] {
        let displacement = x86_exact_nibble_displacement(storage, table_index)?;
        let modrm = 0x81_u8
            | destination
                .checked_mul(8)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 AVX-512 exact constant register",
                ))?;
        let mut load = vec![0x62, 0xd2, 0x7d, 0x48, 0x5a, modrm];
        load.extend_from_slice(&displacement.to_le_bytes());
        assembler.instruction(&load)?; // vbroadcasti32x4 zmmN, disp32[r9]
    }
    Ok(())
}

fn x86_emit_exact_vector_constants(
    assembler: &mut X86Assembler,
    storage: NativeExactByteSetStorage,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => Err(ObjectError::InvalidModule(
            "x86 exact-set vector constants selected SSE2",
        )),
        X86StartFilterKind::Avx2 => x86_emit_exact_avx2_constants(assembler, storage),
        X86StartFilterKind::Avx512Bw => x86_emit_exact_avx512_constants(assembler, storage),
    }
}

/// Produce the exact 32-lane membership mask in EAX for one AVX2 block.
///
/// YMM1/YMM2 are the low/high row banks, YMM3 maps high nibbles to bits, and
/// YMM7 is `0x0f` in every byte. The input byte's sign bit selects its row bank;
/// intersecting that row bitset with its exact high-nibble bit cannot create a
/// false-positive byte pair.
fn x86_emit_exact_avx2_candidates(
    assembler: &mut X86Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    x86_emit_start_filter_vector_load(assembler, X86StartFilterKind::Avx2, scan_offset)?;
    assembler.instruction(&[0xc5, 0xdd, 0x71, 0xd0, 0x04])?; // high nibbles in ymm4
    assembler.instruction(&[0xc5, 0xfd, 0xdb, 0xef])?; // low nibbles in ymm5
    assembler.instruction(&[0xc5, 0xdd, 0xdb, 0xe7])?; // mask high nibbles
    assembler.instruction(&[0xc4, 0xe2, 0x75, 0x00, 0xf5])?; // low rows in ymm6
    assembler.instruction(&[0xc4, 0xe2, 0x6d, 0x00, 0xed])?; // high rows in ymm5
    assembler.instruction(&[0xc4, 0xe3, 0x4d, 0x4c, 0xf5, 0x00])?; // select row bank
    assembler.instruction(&[0xc4, 0xe2, 0x65, 0x00, 0xe4])?; // exact high bits
    assembler.instruction(&[0xc5, 0xcd, 0xdb, 0xf4])?; // intersect in ymm6
    assembler.instruction(&[0xc5, 0xd5, 0xef, 0xed])?; // zero ymm5
    assembler.instruction(&[0xc5, 0xcd, 0x74, 0xf5])?; // zero lanes are 0xff
    assembler.instruction(&[0xc5, 0xfd, 0xd7, 0xc6])?; // vpmovmskb eax, ymm6
    assembler.instruction(&[0xf7, 0xd0])?; // invert: member lanes are one
    Ok(())
}

/// Produce the exact 64-lane membership mask in K1 for one AVX-512BW block.
///
/// ZMM1/ZMM2 are the low/high row banks, ZMM3 maps high nibbles to bits, and
/// ZMM7 is `0x0f` in every byte. K2 selects the high row bank from each input
/// byte's sign bit. `VPTESTMB` publishes exact nonzero membership directly as
/// a 64-bit opmask, preserving lanes 32..63 for the common first-hit helper.
fn x86_emit_exact_avx512_candidates(
    assembler: &mut X86Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    x86_emit_start_filter_vector_load(assembler, X86StartFilterKind::Avx512Bw, scan_offset)?;
    assembler.instruction(&[0x62, 0xf1, 0x5d, 0x48, 0x71, 0xd0, 0x04])?; // high nibbles zmm4
    assembler.instruction(&[0x62, 0xf1, 0x7d, 0x48, 0xdb, 0xef])?; // low nibbles zmm5
    assembler.instruction(&[0x62, 0xf1, 0x5d, 0x48, 0xdb, 0xe7])?; // mask high nibbles
    assembler.instruction(&[0x62, 0xf2, 0x75, 0x48, 0x00, 0xf5])?; // low rows zmm6
    assembler.instruction(&[0x62, 0xf2, 0x6d, 0x48, 0x00, 0xed])?; // high rows zmm5
    assembler.instruction(&[0x62, 0xf2, 0x7e, 0x48, 0x29, 0xd0])?; // sign mask k2
    assembler.instruction(&[0x62, 0xf1, 0x7f, 0x4a, 0x6f, 0xf5])?; // select high rows
    assembler.instruction(&[0x62, 0xf2, 0x65, 0x48, 0x00, 0xe4])?; // exact high bits
    assembler.instruction(&[0x62, 0xf1, 0x4d, 0x48, 0xdb, 0xf4])?; // intersect zmm6
    assembler.instruction(&[0x62, 0xf2, 0x4d, 0x48, 0x26, 0xce])?; // members in k1
    Ok(())
}

fn x86_emit_exact_vector_candidates(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
    scan_offset: u8,
) -> Result<X86CandidateMask, ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => Err(ObjectError::InvalidModule(
            "x86 exact-set vector candidates selected SSE2",
        )),
        X86StartFilterKind::Avx2 => {
            x86_emit_exact_avx2_candidates(assembler, scan_offset)?;
            Ok(X86CandidateMask::MovemaskEax)
        }
        X86StartFilterKind::Avx512Bw => {
            x86_emit_exact_avx512_candidates(assembler, scan_offset)?;
            Ok(X86CandidateMask::Avx512K1)
        }
    }
}

fn x86_emit_start_filter_scalar_bound(
    assembler: &mut X86Assembler,
    scan_offset: u8,
    exhausted: X86Label,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(&[0x48, 0x39, 0xca])?; // candidate >= end
    } else {
        assembler.instruction(&[0x48, 0x8d, 0x42, scan_offset])?;
        assembler.instruction(&[0x48, 0x39, 0xc8])?; // candidate + offset >= end
    }
    assembler.branch(&[0x0f, 0x83], exhausted)?;
    Ok(())
}

fn x86_emit_range_start_filter_vector_candidates(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
    first_register: u8,
) -> Result<(), ObjectError> {
    if filter.ranges().is_empty() || filter.is_exact() {
        return Err(ObjectError::InvalidModule(
            "non-range x86 filter reached range vector lowering",
        ));
    }
    x86_emit_start_filter_vector_load(assembler, kind, filter.scan_offset)?;
    if kind == X86StartFilterKind::Avx512Bw {
        assembler.instruction(&[0xc4, 0xe1, 0xdc, 0x47, 0xe4])?; // kxorq k4, k4, k4
    }
    for (index, _) in filter.ranges().iter().enumerate() {
        let logical_low = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
            "x86 range-filter low register",
        ))?;
        let low = x86_filter_constant_register(first_register, logical_low)?;
        let high = x86_filter_constant_register(
            first_register,
            logical_low
                .checked_add(1)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 range-filter high register",
                ))?,
        )?;
        match kind {
            X86StartFilterKind::Sse2 => {
                assembler.instruction(&[0x66, 0x44, 0x0f, 0x6f, 0xd0])?; // xmm10 = source
                assembler.instruction(&[
                    0x66,
                    if low < 8 { 0x44 } else { 0x45 },
                    0x0f,
                    0xde,
                    0xd0 | (low & 7),
                ])?;
                assembler.instruction(&[0x66, 0x44, 0x0f, 0x74, 0xd0])?;
                assembler.instruction(&[0x66, 0x44, 0x0f, 0x6f, 0xd8])?; // xmm11 = source
                assembler.instruction(&[
                    0x66,
                    if high < 8 { 0x44 } else { 0x45 },
                    0x0f,
                    0xda,
                    0xd8 | (high & 7),
                ])?;
                assembler.instruction(&[0x66, 0x44, 0x0f, 0x74, 0xd8])?;
                assembler.instruction(&[0x66, 0x45, 0x0f, 0xdb, 0xd3])?; // xmm10 &= xmm11
                if index == 0 {
                    assembler.instruction(&[0x66, 0x45, 0x0f, 0x6f, 0xca])?; // xmm9 = xmm10
                } else {
                    assembler.instruction(&[0x66, 0x45, 0x0f, 0xeb, 0xca])?; // xmm9 |= xmm10
                }
            }
            X86StartFilterKind::Avx2 => {
                if low < 8 {
                    assembler.instruction(&[0xc5, 0x7d, 0xde, 0xd0 | low])?;
                } else {
                    assembler.instruction(&[0xc5, 0x3d, 0xde, 0xd0 | (low & 7)])?;
                }
                assembler.instruction(&[0xc5, 0x2d, 0x74, 0xd0])?;
                if high < 8 {
                    assembler.instruction(&[0xc5, 0x7d, 0xda, 0xd8 | high])?;
                } else {
                    assembler.instruction(&[0xc5, 0x3d, 0xda, 0xd8 | (high & 7)])?;
                }
                assembler.instruction(&[0xc5, 0x25, 0x74, 0xd8])?;
                assembler.instruction(&[0xc4, 0x41, 0x2d, 0xdb, 0xd3])?;
                if index == 0 {
                    assembler.instruction(&[0xc4, 0x41, 0x2d, 0xeb, 0xca])?; // ymm9 = ymm10
                } else {
                    assembler.instruction(&[0xc4, 0x41, 0x2d, 0xeb, 0xc9])?; // ymm9 |= ymm10
                }
            }
            X86StartFilterKind::Avx512Bw => {
                let low_evex = if low < 8 { 0xf3 } else { 0xd3 };
                let high_evex = if high < 8 { 0xf3 } else { 0xd3 };
                assembler.instruction(&[0x62, low_evex, 0x7d, 0x48, 0x3e, 0xc8 | (low & 7), 5])?; // vpcmpnltub k1, zmm0, zmm(low)
                assembler.instruction(&[
                    0x62,
                    high_evex,
                    0x7d,
                    0x48,
                    0x3e,
                    0xd0 | (high & 7),
                    2,
                ])?; // vpcmpleub k2, zmm0, zmm(high)
                assembler.instruction(&[0xc4, 0xe1, 0xf4, 0x41, 0xda])?; // k3 = k1 & k2
                assembler.instruction(&[0xc4, 0xe1, 0xdc, 0x45, 0xe3])?; // k4 |= k3
            }
        }
    }
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x45, 0x0f, 0x6f, 0xe1])?; // xmm12 = xmm9
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc4, 0x41, 0x7d, 0x6f, 0xe1])?; // ymm12 = ymm9
        }
        X86StartFilterKind::Avx512Bw => {}
    }
    Ok(())
}

fn x86_emit_exact_start_filter_vector_candidates(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
    first_register: u8,
) -> Result<(), ObjectError> {
    if filter.ranges().is_empty() || !filter.is_exact() {
        return Err(ObjectError::InvalidModule(
            "non-exact x86 filter reached exact vector lowering",
        ));
    }
    let ranges = filter.ranges();
    match kind {
        X86StartFilterKind::Sse2 => {
            x86_emit_start_filter_vector_load(assembler, kind, filter.scan_offset)?;
            // XMM1..8 may all be constants for a fragmented exact set. Keep
            // masks in reserved XMM11/XMM12 so processing the fifth byte does
            // not overwrite a still-live constant.
            assembler.instruction(&[0x66, 0x44, 0x0f, 0x6f, 0xe0])?; // xmm12 = source
            assembler.instruction(&[
                0x66,
                if first_register < 8 { 0x44 } else { 0x45 },
                0x0f,
                0x74,
                0xe0 | (first_register & 7),
            ])?;
            for index in 1..ranges.len() {
                let register = x86_filter_constant_register(first_register, index)?;
                assembler.instruction(&[0x66, 0x44, 0x0f, 0x6f, 0xd8])?; // xmm11 = source
                assembler.instruction(&[
                    0x66,
                    if register < 8 { 0x44 } else { 0x45 },
                    0x0f,
                    0x74,
                    0xd8 | (register & 7),
                ])?;
                assembler.instruction(&[0x66, 0x45, 0x0f, 0xeb, 0xe3])?; // xmm12 |= xmm11
            }
        }
        X86StartFilterKind::Avx2 => {
            x86_emit_start_filter_vector_load(assembler, kind, filter.scan_offset)?;
            if first_register < 8 {
                assembler.instruction(&[0xc5, 0x7d, 0x74, 0xe0 | first_register])?;
            } else {
                // Equality is commutative: use YMM8 as VEX.vvvv and keep the
                // ModRM source at YMM0 for the compact high-register form.
                assembler.instruction(&[0xc5, 0x3d, 0x74, 0xe0])?;
            }
            for index in 1..ranges.len() {
                let register = x86_filter_constant_register(first_register, index)?;
                if register < 8 {
                    assembler.instruction(&[0xc5, 0x7d, 0x74, 0xd8 | register])?;
                } else {
                    assembler.instruction(&[0xc5, 0x3d, 0x74, 0xd8])?;
                }
                assembler.instruction(&[0xc4, 0x41, 0x1d, 0xeb, 0xe3])?; // ymm12 |= ymm11
            }
        }
        X86StartFilterKind::Avx512Bw => {
            x86_emit_start_filter_vector_load(assembler, kind, filter.scan_offset)?;
            let first_evex = if first_register < 8 { 0xf1 } else { 0xd1 };
            assembler.instruction(&[
                0x62,
                first_evex,
                0x7d,
                0x48,
                0x74,
                0xc8 | (first_register & 7),
            ])?;
            for index in 1..ranges.len() {
                let register = x86_filter_constant_register(first_register, index)?;
                let evex = if register < 8 { 0xf1 } else { 0xd1 };
                assembler.instruction(&[0x62, evex, 0x7d, 0x48, 0x74, 0xd0 | (register & 7)])?;
                assembler.instruction(&[0xc4, 0xe1, 0xf4, 0x45, 0xca])?;
            }
        }
    }
    // SSE2/AVX2 build the exact mask directly in XMM/YMM12. AVX-512 keeps it
    // in k1, as described by X86CandidateMask.
    Ok(())
}

fn x86_emit_start_filter_vector_candidates(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
    first_register: u8,
) -> Result<(), ObjectError> {
    if filter.is_exact() {
        x86_emit_exact_start_filter_vector_candidates(assembler, filter, kind, first_register)
    } else {
        x86_emit_range_start_filter_vector_candidates(assembler, filter, kind, first_register)
    }
}

fn x86_emit_start_filter_vector_test(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
) -> Result<X86CandidateMask, ObjectError> {
    if filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule(
            "empty x86 start filter reached vector lowering",
        ));
    }
    if !filter.is_exact() && kind == X86StartFilterKind::Avx512Bw {
        x86_emit_start_filter_range_vector_test(assembler, filter, kind)?;
        return Ok(X86CandidateMask::Avx512K4);
    }
    x86_emit_start_filter_vector_candidates(assembler, filter, kind, 1)?;
    let mask = X86CandidateMask::for_filter(filter, kind);
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x41, 0x0f, 0xd7, 0xc4])?;
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc4, 0xc1, 0x7d, 0xd7, 0xc4])?;
        }
        X86StartFilterKind::Avx512Bw => {
            x86_emit_candidate_nonzero(assembler, mask)?;
            return Ok(mask);
        }
    }
    x86_emit_candidate_nonzero(assembler, mask)?;
    Ok(mask)
}

/// Intersect the already-materialized primary candidates with every remaining
/// graph-required vector column. SSE2/AVX2 leave the exact lane set in
/// XMM/YMM7; AVX-512BW leaves all lane bits in K5.
fn x86_emit_vector_filter_secondary_candidates(
    assembler: &mut X86Assembler,
    vector_filter: NativeVectorFilter,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "unsupported x86 vector-filter intersection",
        ));
    }
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x41, 0x0f, 0x6f, 0xfc])?; // xmm7 = primary xmm12
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc4, 0xc1, 0x7d, 0x6f, 0xfc])?; // ymm7 = primary ymm12
        }
        X86StartFilterKind::Avx512Bw => x86_emit_avx512_copy_mask_to_k5(
            assembler,
            X86CandidateMask::for_filter(vector_filter.columns()[0], kind),
        )?,
    }
    let primary_constants = vector_filter.columns()[0].constant_count();
    let mut first_register = 1_u8
        .checked_add(
            u8::try_from(primary_constants)
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 vector-filter constants"))?,
        )
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 vector-filter constants",
        ))?;
    for &filter in &vector_filter.columns()[1..] {
        x86_emit_start_filter_vector_candidates(assembler, filter, kind, first_register)?;
        match kind {
            X86StartFilterKind::Sse2 => {
                assembler.instruction(&[0x66, 0x41, 0x0f, 0xdb, 0xfc])?; // xmm7 &= xmm12
            }
            X86StartFilterKind::Avx2 => {
                assembler.instruction(&[0xc4, 0xc1, 0x45, 0xdb, 0xfc])?; // ymm7 &= ymm12
            }
            X86StartFilterKind::Avx512Bw => {
                x86_emit_avx512_intersect_k5(
                    assembler,
                    X86CandidateMask::for_filter(filter, kind),
                )?;
            }
        }
        first_register = first_register
            .checked_add(
                u8::try_from(filter.constant_count())
                    .map_err(|_| ObjectError::ArithmeticOverflow("x86 vector-filter constants"))?,
            )
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 vector-filter constants",
            ))?;
    }
    Ok(())
}

fn x86_emit_vector_filter_intersection_test(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x0f, 0xd7, 0xc7])?;
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc5, 0xfd, 0xd7, 0xc7])?;
        }
        X86StartFilterKind::Avx512Bw => {
            x86_emit_candidate_nonzero(assembler, X86CandidateMask::for_intersection(kind))?;
        }
    }
    if kind != X86StartFilterKind::Avx512Bw {
        x86_emit_candidate_nonzero(assembler, X86CandidateMask::MovemaskEax)?;
    }
    Ok(())
}

fn x86_emit_vector_filter_secondary_test(
    assembler: &mut X86Assembler,
    vector_filter: NativeVectorFilter,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    x86_emit_vector_filter_secondary_candidates(assembler, vector_filter, kind)?;
    x86_emit_vector_filter_intersection_test(assembler, kind)
}

fn x86_emit_start_filter_vector_candidate(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
    vector_hit: X86Label,
) -> Result<(), ObjectError> {
    let _mask = x86_emit_start_filter_vector_test(assembler, filter, kind)?;
    // The no-hit case is the scanner's hot path, so leave it as fallthrough
    // and share one out-of-line first-lane stub across every unrolled vector.
    // `position` has not advanced when this rare branch is taken.
    assembler.branch(&[0x0f, 0x85], vector_hit)?;
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum X86SparseBatchCandidate {
    Primary(NativeStartFilter),
    Intersection,
}

impl X86SparseBatchCandidate {
    const fn vector_register(self) -> u8 {
        match self {
            Self::Primary(_) => 12,
            Self::Intersection => 7,
        }
    }

    fn mask(self, kind: X86StartFilterKind) -> X86CandidateMask {
        match self {
            Self::Primary(filter) => X86CandidateMask::for_filter(filter, kind),
            Self::Intersection => X86CandidateMask::for_intersection(kind),
        }
    }
}

/// XMM/YMM15 and K6 are caller-saved and disjoint from the vector-filter
/// constants and intersection banks. R10/R11 remain untouched.
fn x86_emit_sparse_batch_accumulator_clear(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => x86_emit_sse2_binary(assembler, 0xef, 15, 15)?,
        X86StartFilterKind::Avx2 => x86_emit_avx2_binary(assembler, 0xef, 15, 15, 15)?,
        X86StartFilterKind::Avx512Bw => {
            x86_emit_k_binary(assembler, 0x47, 6, 6, 6)?; // kxorq k6, k6, k6
        }
    }
    Ok(())
}

fn x86_emit_sparse_batch_accumulate(
    assembler: &mut X86Assembler,
    candidate: X86SparseBatchCandidate,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => {
            x86_emit_sse2_binary(assembler, 0xeb, 15, candidate.vector_register())?;
        }
        X86StartFilterKind::Avx2 => {
            x86_emit_avx2_binary(assembler, 0xeb, 15, 15, candidate.vector_register())?;
        }
        X86StartFilterKind::Avx512Bw => {
            let source =
                candidate
                    .mask(kind)
                    .opmask_register()
                    .ok_or(ObjectError::InvalidModule(
                        "AVX-512 sparse batch candidate has no opmask",
                    ))?;
            x86_emit_k_binary(assembler, 0x45, 6, 6, source)?; // k6 |= source
        }
    }
    Ok(())
}

fn x86_emit_sparse_batch_accumulator_test(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0x66, 0x41, 0x0f, 0xd7, 0xc7])?; // pmovmskb eax, xmm15
            x86_emit_candidate_nonzero(assembler, X86CandidateMask::MovemaskEax)?;
        }
        X86StartFilterKind::Avx2 => {
            assembler.instruction(&[0xc4, 0xc1, 0x7d, 0xd7, 0xc7])?; // vpmovmskb eax, ymm15
            x86_emit_candidate_nonzero(assembler, X86CandidateMask::MovemaskEax)?;
        }
        X86StartFilterKind::Avx512Bw => {
            x86_emit_candidate_nonzero(assembler, X86CandidateMask::Avx512K6)?;
        }
    }
    Ok(())
}

/// Test four adjacent vector blocks with one conditional branch. Primary
/// masks are ORed by lane; a hit rewinds the complete bounded group.
fn x86_emit_sparse_filter_mask_batch(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    x86_emit_sparse_batch_accumulator_clear(assembler, kind)?;
    for _ in 0..X86_MASK_BATCH_VECTORS {
        x86_emit_start_filter_vector_candidates(assembler, filter, kind, 1)?;
        x86_emit_sparse_batch_accumulate(
            assembler,
            X86SparseBatchCandidate::Primary(filter),
            kind,
        )?;
        assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
    }
    x86_emit_sparse_batch_accumulator_test(assembler, kind)
}

/// Test four adjacent vector blocks with the complete graph-required column
/// intersection. The caller starts at the group base; both outcomes leave RDX
/// just beyond the group, and a hit can rewind for exact scalar replay.
fn x86_emit_sparse_vector_filter_mask_batch(
    assembler: &mut X86Assembler,
    vector_filter: NativeVectorFilter,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "unsupported x86 sparse vector-filter intersection",
        ));
    }
    x86_emit_sparse_batch_accumulator_clear(assembler, kind)?;
    for _ in 0..X86_MASK_BATCH_VECTORS {
        x86_emit_start_filter_vector_candidates(assembler, vector_filter.columns()[0], kind, 1)?;
        x86_emit_vector_filter_secondary_candidates(assembler, vector_filter, kind)?;
        x86_emit_sparse_batch_accumulate(assembler, X86SparseBatchCandidate::Intersection, kind)?;
        assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
    }
    x86_emit_sparse_batch_accumulator_test(assembler, kind)
}

fn x86_emit_rewind_sparse_filter_mask_batch(
    assembler: &mut X86Assembler,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    let bytes = u16::from(kind.width())
        .checked_mul(X86_MASK_BATCH_VECTORS)
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 sparse-filter batch width",
        ))?;
    if bytes <= 0x7f {
        assembler.instruction(&[
            0x48,
            0x83,
            0xea,
            u8::try_from(bytes)
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 sparse-filter rewind"))?,
        ])?;
    } else {
        let mut instruction = vec![0x48, 0x81, 0xea]; // sub rdx, imm32
        instruction.extend_from_slice(&u32::from(bytes).to_le_bytes());
        assembler.instruction(&instruction)?;
    }
    Ok(())
}

fn x86_emit_suffix_lower_bound(
    assembler: &mut X86Assembler,
    backtrack: u64,
) -> Result<(), ObjectError> {
    if backtrack == 0 {
        return Ok(());
    }
    let clamp = assembler.label()?;
    let done = assembler.label()?;
    assembler.instruction(&[0x48, 0x89, 0xd0])?; // distance = suffix base
    assembler.instruction(&[0x48, 0x29, 0xf0])?; // distance -= window start
    if let Ok(immediate) = i32::try_from(backtrack) {
        let mut compare = vec![0x48, 0x3d]; // cmp distance, backtrack
        compare.extend_from_slice(&immediate.to_le_bytes());
        assembler.instruction(&compare)?;
        assembler.branch(&[0x0f, 0x86], clamp)?; // distance <= backtrack
        if let Ok(short) = u8::try_from(backtrack)
            && short <= 0x7f
        {
            assembler.instruction(&[0x48, 0x83, 0xea, short])?; // position -= backtrack
        } else {
            let mut subtract = vec![0x48, 0x81, 0xea];
            subtract.extend_from_slice(&immediate.to_le_bytes());
            assembler.instruction(&subtract)?;
        }
    } else {
        let mut load = vec![0x49, 0xba]; // movabs r10, backtrack
        load.extend_from_slice(&backtrack.to_le_bytes());
        assembler.instruction(&load)?;
        assembler.instruction(&[0x4c, 0x39, 0xd0])?; // cmp distance, r10
        assembler.branch(&[0x0f, 0x86], clamp)?;
        assembler.instruction(&[0x4c, 0x29, 0xd2])?; // position -= r10
    }
    assembler.branch(&[0xe9], done)?;
    assembler.bind(clamp)?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?; // position = window start
    assembler.bind(done)?;
    Ok(())
}

fn x86_emit_suffix_reset_restart(
    assembler: &mut X86Assembler,
    non_reset: NativeResetFilter,
) -> Result<(), ObjectError> {
    let scan = assembler.label()?;
    let non_reset_byte = assembler.label()?;
    let no_reset = assembler.label()?;
    let done = assembler.label()?;
    assembler.instruction(&[0x49, 0x89, 0xd2])?; // cursor = suffix base
    assembler.instruction(&[0x41, 0xbb, 64, 0, 0, 0])?; // remaining = 64
    assembler.bind(scan)?;
    assembler.instruction(&[0x49, 0x39, 0xf2])?; // cursor <= window start
    assembler.branch(&[0x0f, 0x86], no_reset)?;
    assembler.instruction(&[0x49, 0xff, 0xca])?; // --cursor
    assembler.instruction(&[0x42, 0x0f, 0xb6, 0x04, 0x17])?; // haystack[cursor]
    for range in non_reset.ranges() {
        assembler.instruction(&[0x3c, range.start])?;
        if range.start == range.end {
            assembler.branch(&[0x0f, 0x84], non_reset_byte)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next_range)?;
            assembler.instruction(&[0x3c, range.end])?;
            assembler.branch(&[0x0f, 0x86], non_reset_byte)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(&[0x49, 0x8d, 0x52, 1])?; // start = reset + 1
    assembler.branch(&[0xe9], done)?;

    assembler.bind(non_reset_byte)?;
    assembler.instruction(&[0x49, 0xff, 0xcb])?; // --remaining
    assembler.branch(&[0x0f, 0x85], scan)?;
    assembler.bind(no_reset)?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?; // restore original start
    assembler.bind(done)?;
    Ok(())
}

fn x86_emit_suffix_restart(
    assembler: &mut X86Assembler,
    restart: NativeSuffixRestart,
) -> Result<(), ObjectError> {
    match restart {
        NativeSuffixRestart::Bounded { backtrack } => {
            x86_emit_suffix_lower_bound(assembler, backtrack)
        }
        NativeSuffixRestart::Synchronizing { non_reset } => {
            x86_emit_suffix_reset_restart(assembler, non_reset)
        }
        NativeSuffixRestart::OriginalStart => {
            assembler.instruction(&[0x48, 0x89, 0xf2])?; // restore original start
            Ok(())
        }
    }
}

/// Scan every graph-required factor candidate and prove candidate starts with
/// an independently determinized reverse machine. Total reverse-table work is
/// capped by one byte transition per input byte; exhausting that fuel falls
/// back to the untouched ordinary forward DFA. Candidate scanning itself is
/// still the same SIMD/scalar mandatory-factor proof used by the established
/// suffix prepass.
#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the factor scanner and reverse-proof control flow form one auditable native loop"
)]
fn x86_emit_seeded_reverse_prepass(
    assembler: &mut X86Assembler,
    suffix: NativeSuffixFilter,
    reverse: NativeSeededReverseLayout,
    kind: X86StartFilterKind,
    layout: NativeDfaLayout,
    no_match: X86Label,
    matched: X86Label,
) -> Result<(), ObjectError> {
    let vector = assembler.label()?;
    let single_vector = assembler.label()?;
    let scalar = assembler.label()?;
    let scalar_columns = assembler.label()?;
    let scalar_reject = assembler.label()?;
    let primary_hit = assembler.label()?;
    let vector_hit = assembler.label()?;
    let sparse_batch_hit = assembler.label()?;
    let candidate = assembler.label()?;
    let reverse_loop = assembler.label()?;
    let record_start = assembler.label()?;
    let reverse_continue = assembler.label()?;
    let reverse_live = assembler.label()?;
    let reverse_done = assembler.label()?;
    let finalize = assembler.label()?;
    let global_minimum = assembler.label()?;
    let fallback = assembler.label()?;
    let done = assembler.label()?;
    let filter = suffix.filter;
    if suffix.minimum_width == 0 {
        return Err(ObjectError::InvalidModule(
            "x86 seeded reverse filter has zero minimum width",
        ));
    }
    if layout.seeded_reverse != Some(reverse) {
        return Err(ObjectError::InvalidModule(
            "x86 seeded reverse layout changed during lowering",
        ));
    }
    let malformed_certificate = reverse.first_endpoint_proves_no_earlier_match
        && (!reverse.proves_match
            || !matches!(suffix.reverse_seed, NativeSuffixReverseSeed::AcceptBoundary));
    let endpoint_without_certificate = layout.output != OutputContract::Exists
        && (!reverse.proves_match || !reverse.first_endpoint_proves_no_earlier_match);
    let malformed_seed = match suffix.reverse_seed {
        NativeSuffixReverseSeed::AcceptBoundary => {
            reverse.boundary_offset != suffix.minimum_width || !reverse.proves_match
        }
        NativeSuffixReverseSeed::RootState(_) => {
            reverse.boundary_offset != 0 || reverse.proves_match
        }
    };
    let unsupported_synchronizing_reverse =
        matches!(suffix.restart, NativeSuffixRestart::Synchronizing { .. })
            && !(layout.output == OutputContract::Exists
                && matches!(suffix.reverse_seed, NativeSuffixReverseSeed::AcceptBoundary)
                && reverse.proves_match
                && reverse.first_endpoint_proves_no_earlier_match);
    if malformed_certificate
        || endpoint_without_certificate
        || malformed_seed
        || suffix.retry.is_some()
        || unsupported_synchronizing_reverse
    {
        return Err(ObjectError::InvalidModule(
            "x86 seeded reverse escaped its graph admission gate",
        ));
    }

    let lazy_vector_filter = suffix.vector_filter;
    let scalar_filter = suffix.vector_filter.or(suffix.scalar_filter);
    let maximum_filter_offset =
        scalar_filter.map_or(filter.scan_offset, NativeVectorFilter::max_scan_offset);
    let maximum_scan_offset = maximum_filter_offset.max(reverse.boundary_offset.saturating_sub(1));
    let use_sparse_batch = x86_use_sparse_filter_mask_batch(filter, kind);
    let emit_constants = |assembler: &mut X86Assembler| -> Result<(), ObjectError> {
        if let Some(vector_filter) = lazy_vector_filter {
            let mut first_register = 1_u8;
            for &column in vector_filter.columns() {
                x86_emit_start_filter_constants(assembler, column, kind, first_register)?;
                first_register = first_register
                    .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                        ObjectError::ArithmeticOverflow("x86 seeded reverse constants")
                    })?)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 seeded reverse constants",
                    ))?;
            }
        } else {
            x86_emit_start_filter_constants(assembler, filter, kind, 1)?;
        }
        Ok(())
    };
    if !ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS {
        emit_constants(assembler)?;
    }

    // R12 is reverse fuel, R13 the minimum proved start, R14 the next factor
    // base, and R15 the reverse cursor. The outer lowering preserves all four.
    assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
    let mut minimum = vec![0x48, 0x3d];
    minimum.extend_from_slice(&u32::from(SUFFIX_PREFILTER_MIN_WINDOW_BYTES).to_le_bytes());
    assembler.instruction(&minimum)?;
    assembler.branch(&[0x0f, 0x82], done)?;
    assembler.instruction(&[0x49, 0x89, 0xc4])?; // fuel = window bytes
    assembler.instruction(&[0x49, 0xc7, 0xc5, 0xff, 0xff, 0xff, 0xff])?; // min = none
    if ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS {
        emit_constants(assembler)?;
    }

    assembler.bind(vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x29, 0xd0])?;
    let unrolled_bytes = u32::from(kind.width())
        .checked_mul(4)
        .and_then(|bytes| bytes.checked_add(u32::from(maximum_scan_offset)))
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 seeded reverse filter width",
        ))?;
    let mut compare_unrolled = vec![0x48, 0x3d];
    compare_unrolled.extend_from_slice(&unrolled_bytes.to_le_bytes());
    assembler.instruction(&compare_unrolled)?;
    assembler.branch(&[0x0f, 0x82], single_vector)?;
    let vector_candidate_hit = if lazy_vector_filter.is_some() {
        primary_hit
    } else {
        vector_hit
    };
    if use_sparse_batch {
        x86_emit_sparse_filter_mask_batch(assembler, filter, kind)?;
        assembler.branch(&[0x0f, 0x85], sparse_batch_hit)?;
    } else {
        for _ in 0..X86_MASK_BATCH_VECTORS {
            x86_emit_start_filter_vector_candidate(assembler, filter, kind, vector_candidate_hit)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
        }
    }
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(sparse_batch_hit)?;
    x86_emit_rewind_sparse_filter_mask_batch(assembler, kind)?;
    assembler.branch(&[0xe9], scalar)?;

    assembler.bind(single_vector)?;
    let single_vector_bytes =
        kind.width()
            .checked_add(maximum_scan_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 seeded reverse filter width",
            ))?;
    assembler.instruction(&[0x48, 0x83, 0xf8, single_vector_bytes])?;
    assembler.branch(&[0x0f, 0x82], scalar)?;
    x86_emit_start_filter_vector_candidate(assembler, filter, kind, vector_candidate_hit)?;
    assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(scalar)?;
    x86_emit_start_filter_scalar_bound(assembler, maximum_scan_offset, finalize)?;
    x86_emit_start_filter_scalar_load(assembler, filter.scan_offset)?;
    let scalar_candidate = if scalar_filter.is_some() {
        scalar_columns
    } else {
        candidate
    };
    for range in filter.ranges() {
        assembler.instruction(&[0x3c, range.start])?;
        if range.start == range.end {
            assembler.branch(&[0x0f, 0x84], scalar_candidate)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next_range)?;
            assembler.instruction(&[0x3c, range.end])?;
            assembler.branch(&[0x0f, 0x86], scalar_candidate)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    if let Some(vector_filter) = scalar_filter {
        assembler.bind(scalar_columns)?;
        for &column in &vector_filter.columns()[1..] {
            x86_emit_scalar_filter_membership(assembler, column, scalar_reject)?;
        }
        assembler.branch(&[0xe9], candidate)?;
        assembler.bind(scalar_reject)?;
        assembler.instruction(&[0x48, 0xff, 0xc2])?;
        assembler.branch(&[0xe9], vector)?;

        if let Some(lazy_filter) = lazy_vector_filter {
            assembler.bind(primary_hit)?;
            x86_emit_vector_filter_secondary_test(assembler, lazy_filter, kind)?;
            assembler.branch(&[0x0f, 0x85], vector_hit)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
            assembler.branch(&[0xe9], vector)?;
        } else {
            assembler.bind(primary_hit)?;
            assembler.branch(&[0xe9], scalar)?;
        }
    } else {
        assembler.bind(scalar_columns)?;
        assembler.branch(&[0xe9], candidate)?;
        assembler.bind(scalar_reject)?;
        assembler.branch(&[0xe9], scalar)?;
        assembler.bind(primary_hit)?;
        assembler.branch(&[0xe9], scalar)?;
    }

    assembler.bind(vector_hit)?;
    let vector_hit_mask = if lazy_vector_filter.is_some() {
        X86CandidateMask::for_intersection(kind)
    } else {
        X86CandidateMask::for_filter(filter, kind)
    };
    x86_emit_first_candidate_lane(assembler, vector_hit_mask)?;
    assembler.instruction(&[0x48, 0x01, 0xc2])?; // position += first lane

    assembler.bind(candidate)?;
    assembler.instruction(&[0x4c, 0x8d, 0x72, 0x01])?; // next base = candidate + 1
    if reverse.boundary_offset == 0 {
        assembler.instruction(&[0x49, 0x89, 0xd7])?; // cursor = candidate
    } else {
        assembler.instruction(&[0x4c, 0x8d, 0x7a, reverse.boundary_offset])?; // cursor = candidate + boundary
    }
    let mut class_map = vec![0x4d, 0x8d, 0x99]; // lea class-map(r9), r11
    class_map.extend_from_slice(&reverse.class_map_offset.to_le_bytes());
    assembler.instruction(&class_map)?;
    x86_set_row(assembler, reverse.initial_row_offset)?;

    // A start reachable without consuming a reverse byte is recorded before
    // entering the table loop. It must not flow through `reverse_continue`,
    // whose EAX cell exists only after a table load.
    if reverse.initial_reaches_start {
        if reverse.proves_match && layout.output == OutputContract::Exists {
            assembler.branch(&[0xe9], matched)?;
        } else {
            assembler.instruction(&[0x4d, 0x39, 0xef])?; // cursor >= minimum
            assembler.branch(&[0x0f, 0x83], reverse_loop)?;
            assembler.instruction(&[0x4d, 0x89, 0xfd])?; // minimum = cursor
            assembler.instruction(&[0x49, 0x39, 0xf5])?; // minimum == window start
            assembler.branch(&[0x0f, 0x84], global_minimum)?;
        }
    }

    assembler.bind(reverse_loop)?;
    assembler.instruction(&[0x49, 0x39, 0xf7])?; // cursor <= window start
    assembler.branch(&[0x0f, 0x86], reverse_done)?;
    assembler.instruction(&[0x4d, 0x85, 0xe4])?; // test fuel
    assembler.branch(&[0x0f, 0x84], fallback)?;
    assembler.instruction(&[0x49, 0xff, 0xcf])?; // --cursor
    assembler.instruction(&[0x49, 0xff, 0xcc])?; // --fuel
    assembler.instruction(&[0x42, 0x0f, 0xb6, 0x04, 0x3f])?; // byte [haystack+cursor]
    assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x03])?; // exact raw class
    assembler.instruction(&[0x41, 0x8b, 0x04, 0x82])?; // packed reverse cell
    assembler.instruction(&[0x85, 0xc0])?; // accept sign and dead zero
    assembler.branch(&[0x0f, 0x88], record_start)?;
    assembler.branch(&[0x0f, 0x84], reverse_done)?;
    assembler.bind(reverse_live)?;
    assembler.instruction(&[0x4d, 0x8d, 0x54, 0x01, 0xff])?;
    assembler.branch(&[0xe9], reverse_loop)?;

    assembler.bind(record_start)?;
    if reverse.proves_match && layout.output == OutputContract::Exists {
        assembler.branch(&[0xe9], matched)?;
    } else {
        // This sidecar is independently wide. Clear its sole metadata bit on
        // the cold accepting edge so the live rejoin carries a raw byte token.
        x86_emit_clear_eax_bit(assembler, 31)?;
        assembler.instruction(&[0x4d, 0x39, 0xef])?; // cursor >= minimum
        assembler.branch(&[0x0f, 0x83], reverse_continue)?;
        assembler.instruction(&[0x4d, 0x89, 0xfd])?; // minimum = cursor
        assembler.instruction(&[0x49, 0x39, 0xf5])?; // minimum == window start
        assembler.branch(&[0x0f, 0x84], global_minimum)?;
        assembler.branch(&[0xe9], reverse_continue)?;
    }

    assembler.bind(reverse_continue)?;
    assembler.instruction(&[0x85, 0xc0])?; // accepted dead transition?
    assembler.branch(&[0x0f, 0x84], reverse_done)?;
    assembler.branch(&[0xe9], reverse_live)?;

    assembler.bind(reverse_done)?;
    if reverse.first_endpoint_proves_no_earlier_match {
        // Only a completely consumed reverse trace may publish this minimum.
        // The terminal-barrier certificate makes the first such endpoint a
        // no-earlier-match proof, but ordered forward replay still selects
        // the authoritative endpoint and Span start.
        assembler.instruction(&[0x49, 0x83, 0xfd, 0xff])?; // minimum == none?
        assembler.branch(&[0x0f, 0x85], global_minimum)?;
    }
    assembler.instruction(&[0x4c, 0x89, 0xf2])?; // position = next base
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(finalize)?;
    assembler.instruction(&[0x49, 0x83, 0xfd, 0xff])?;
    assembler.branch(&[0x0f, 0x84], no_match)?;
    assembler.bind(global_minimum)?;
    assembler.instruction(&[0x4c, 0x89, 0xea])?; // position = minimum proved start
    assembler.branch(&[0xe9], done)?;

    assembler.bind(fallback)?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?; // untouched semantic start
    assembler.bind(done)?;
    Ok(())
}

fn validate_x86_mandatory_teddy_layout(
    suffix: NativeSuffixFilter,
    teddy: NativeMandatoryTeddyLayout,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    let isa_matches = matches!(
        (kind, teddy.isa),
        (X86StartFilterKind::Avx2, MandatoryTeddyIsa::X86Avx2)
            | (
                X86StartFilterKind::Avx512Bw,
                MandatoryTeddyIsa::X86Avx512Bw
            )
    );
    let columns = usize::from(teddy.plan.columns());
    let expected_mask = usize::try_from(teddy.table_base)
        .ok()
        .and_then(|base| {
            columns
                .checked_mul(X86_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN)
                .and_then(|bytes| base.checked_add(bytes))
        });
    let expected_end = expected_mask
        .and_then(|offset| offset.checked_add(X86_MANDATORY_TEDDY_NIBBLE_MASK_BYTES));
    let portfolio_owns_plan = suffix.teddy_portfolio.is_some_and(|portfolio| {
        portfolio.plans().any(|plan| *plan == teddy.plan)
    });
    if !isa_matches
        || teddy.plan.bank_count() != 1
        || teddy.vector_bytes != 32
        || !(3..=4).contains(&teddy.plan.columns())
        || teddy.plan.columns() > suffix.minimum_width
        || !usize::try_from(teddy.table_base)
            .is_ok_and(|offset| offset.is_multiple_of(X86_MANDATORY_TEDDY_ALIGNMENT))
        || expected_mask != usize::try_from(teddy.nibble_mask_offset).ok()
        || expected_end != usize::try_from(teddy.table_end).ok()
        || !portfolio_owns_plan
        || suffix.retry.is_none()
    {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy layout receipt is malformed",
        ));
    }
    Ok(())
}

fn x86_mandatory_teddy_table_displacement(
    teddy: NativeMandatoryTeddyLayout,
    column: usize,
    high: bool,
) -> Result<i32, ObjectError> {
    if column >= usize::from(teddy.plan.columns()) {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy column is out of range",
        ));
    }
    let offset = u32::try_from(column)
        .ok()
        .and_then(|column| {
            column.checked_mul(
                u32::try_from(X86_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN).ok()?,
            )
        })
        .and_then(|offset| teddy.table_base.checked_add(offset))
        .and_then(|offset| {
            if high {
                offset.checked_add(32)
            } else {
                Some(offset)
            }
        })
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 mandatory Teddy table displacement",
        ))?;
    i32::try_from(offset).map_err(|_| {
        ObjectError::InvalidModule("x86 mandatory Teddy table exceeds signed displacement")
    })
}

fn x86_emit_mandatory_teddy_constants(
    assembler: &mut X86Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let low_register = u8::try_from(
            column
                .checked_mul(2)
                .and_then(|index| index.checked_add(1))
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 mandatory Teddy low register",
                ))?,
        )
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 mandatory Teddy low register"))?;
        let high_register = low_register
            .checked_add(1)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 mandatory Teddy high register",
            ))?;
        x86_emit_avx2_table_load(
            assembler,
            low_register,
            x86_mandatory_teddy_table_displacement(teddy, column, false)?,
        )?;
        x86_emit_avx2_table_load(
            assembler,
            high_register,
            x86_mandatory_teddy_table_displacement(teddy, column, true)?,
        )?;
    }
    let nibble_mask = i32::try_from(teddy.nibble_mask_offset).map_err(|_| {
        ObjectError::InvalidModule("x86 mandatory Teddy nibble mask exceeds signed displacement")
    })?;
    x86_emit_avx2_table_load(assembler, 9, nibble_mask)
}

/// Produce a nonzero-byte candidate mask for 32 adjacent bases. YMM1..YMM8
/// are duplicated low/high tables, YMM9 is the low-nibble mask, and all
/// remaining registers are caller-saved temporaries. Every chronological
/// column loads from the same candidate-base vector plus its fixed offset.
fn x86_emit_mandatory_teddy_avx2_candidates(
    assembler: &mut X86Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let offset = u8::try_from(column)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 mandatory Teddy column"))?;
        x86_emit_start_filter_vector_load(assembler, X86StartFilterKind::Avx2, offset)?;
        x86_emit_avx2_shift_right_words(assembler, 10, 0, 4)?;
        x86_emit_avx2_binary(assembler, 0xdb, 11, 0, 9)?; // low indices
        x86_emit_avx2_binary(assembler, 0xdb, 10, 10, 9)?; // high indices
        let low_table = u8::try_from(column * 2 + 1)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 mandatory Teddy low table"))?;
        let high_table = low_table
            .checked_add(1)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 mandatory Teddy high table",
            ))?;
        x86_emit_avx2_map38_binary(assembler, 0x00, 12, low_table, 11)?; // VPSHUFB
        x86_emit_avx2_map38_binary(assembler, 0x00, 13, high_table, 10)?;
        x86_emit_avx2_binary(assembler, 0xdb, 12, 12, 13)?;
        if column == 0 {
            x86_emit_avx2_move(assembler, 14, 12)?;
        } else {
            x86_emit_avx2_binary(assembler, 0xdb, 14, 14, 12)?;
        }
    }
    x86_emit_avx2_binary(assembler, 0xef, 15, 15, 15)?; // zero
    x86_emit_avx2_binary(assembler, 0x74, 12, 14, 15)?; // zero lanes
    assembler.instruction(&[0xc4, 0xc1, 0x7d, 0xd7, 0xc4])?; // vpmovmskb eax,ymm12
    assembler.instruction(&[0xf7, 0xd0])?; // nonzero bucket masks are candidates
    Ok(())
}

fn x86_emit_mandatory_teddy_scalar_candidate(
    assembler: &mut X86Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let offset = u8::try_from(column)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 mandatory Teddy scalar column"))?;
        x86_emit_start_filter_scalar_load(assembler, offset)?;
        assembler.instruction(&[0x41, 0x89, 0xc2])?; // r10d = byte
        assembler.instruction(&[0x83, 0xe0, 0x0f])?; // low nibble
        assembler.instruction(&[0x41, 0xc1, 0xea, 0x04])?; // high nibble in r10d
        let low_displacement = x86_mandatory_teddy_table_displacement(teddy, column, false)?;
        let low = if let Ok(displacement) = u8::try_from(low_displacement)
            && displacement <= 0x7f
        {
            let mut instruction = vec![0x41, 0x0f, 0xb6, 0x44, 0x01];
            instruction.push(displacement);
            instruction
        } else {
            let mut instruction = vec![0x41, 0x0f, 0xb6, 0x84, 0x01];
            instruction.extend_from_slice(&low_displacement.to_le_bytes());
            instruction
        };
        assembler.instruction(&low)?; // eax = low_table[low]
        let high_displacement = x86_mandatory_teddy_table_displacement(teddy, column, true)?;
        let high = if let Ok(displacement) = u8::try_from(high_displacement)
            && displacement <= 0x7f
        {
            let mut instruction = vec![0x47, 0x0f, 0xb6, 0x54, 0x11];
            instruction.push(displacement);
            instruction
        } else {
            let mut instruction = vec![0x47, 0x0f, 0xb6, 0x94, 0x11];
            instruction.extend_from_slice(&high_displacement.to_le_bytes());
            instruction
        };
        assembler.instruction(&high)?; // r10d = high_table[r10]
        assembler.instruction(&[0x44, 0x21, 0xd0])?; // eax &= r10d
        if column == 0 {
            assembler.instruction(&[0x41, 0x89, 0xc3])?; // r11d = buckets
        } else {
            assembler.instruction(&[0x41, 0x21, 0xc3])?; // r11d &= buckets
        }
    }
    assembler.instruction(&[0x45, 0x85, 0xdb])?; // candidate buckets nonzero?
    Ok(())
}

/// Authenticate a root-first correlated-prefix cascade before any dynamic
/// compact selector can enter. The exact graph root scan either proves no
/// match or supplies a lower bound for the fingerprint scan; Teddy exhaustion
/// is then authoritative, while its first collision-prone hit can only move
/// the semantic bound earlier than a real match.
#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the lowering-only gate keeps one authenticated layout and its complete backend transaction together"
)]
fn x86_emit_dynamic_correlated_prefix_gate(
    assembler: &mut X86Assembler,
    gate: NativeDynamicCorrelatedPrefixLayout,
    root_setup: X86Label,
    root_representation_offset: u8,
    continue_selector: X86Label,
    no_match: X86Label,
) -> Result<X86Label, ObjectError> {
    let teddy = gate.teddy;
    let columns = usize::from(teddy.plan.columns());
    let expected_mask = usize::try_from(teddy.table_base)
        .ok()
        .and_then(|base| {
            columns
                .checked_mul(X86_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN)
                .and_then(|bytes| base.checked_add(bytes))
        });
    let expected_end = expected_mask
        .and_then(|offset| offset.checked_add(X86_MANDATORY_TEDDY_NIBBLE_MASK_BYTES));
    if gate.aarch64_lane_index_offset.is_some()
        || gate.payload_end != teddy.table_end
        || !matches!(
            teddy.isa,
            MandatoryTeddyIsa::X86Avx2 | MandatoryTeddyIsa::X86Avx512Bw
        )
        || teddy.plan.bank_count() != 1
        || !(3..=4).contains(&teddy.plan.columns())
        || teddy.vector_bytes != 32
        || expected_mask != usize::try_from(teddy.nibble_mask_offset).ok()
        || expected_end != usize::try_from(teddy.table_end).ok()
    {
        return Err(ObjectError::InvalidModule(
            "x86 dynamic correlated-prefix layout is malformed",
        ));
    }

    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let vector_candidate = assembler.label()?;
    let candidate = assembler.label()?;
    let exhausted = assembler.label()?;
    let restore_selector = assembler.label()?;
    let scan_from_root = assembler.label()?;

    // The framed public entry retained these exact values before any compact
    // authentication. Short windows bypass the gate without paying for a
    // duplicate identity check.
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x40])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x48])?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x29, 0xd0])?;
    let minimum = u32::try_from(PARTIAL_DFA_MIN_INPUT_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 correlated-prefix input floor"))?;
    let mut compare_minimum = vec![0x48, 0x3d];
    compare_minimum.extend_from_slice(&minimum.to_le_bytes());
    assembler.instruction(&compare_minimum)?;
    assembler.branch(&[0x0f, 0x82], restore_selector)?;

    // A whole-window negative or a narrowed semantic start carries authority
    // only for a live handle of this exact artifact. On any mismatch, restore
    // the untouched public arguments and let the incumbent selector preserve
    // its established validation/fallback behavior.
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x04, 0x24])?;
    let mut active_seal = vec![0x49, 0xba];
    active_seal.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL.to_le_bytes());
    assembler.instruction(&active_seal)?;
    assembler.instruction(&[0x4c, 0x3b, 0x17])?;
    assembler.branch(&[0x0f, 0x85], restore_selector)?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 correlated-prefix identity word",
            ))?;
        if word_offset == 0 {
            assembler.instruction(&[0x4c, 0x8b, 0x10])?;
        } else {
            assembler.instruction(&[
                0x4c,
                0x8b,
                0x50,
                u8::try_from(word_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "x86 correlated-prefix linked identity offset",
                    )
                })?,
            ])?;
        }
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 correlated-prefix header identity offset",
            ))?;
        assembler.instruction(&[
            0x4c,
            0x3b,
            0x57,
            u8::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "x86 correlated-prefix header identity displacement",
                )
            })?,
        ])?;
        assembler.branch(&[0x0f, 0x85], restore_selector)?;
    }

    // Run the exact graph root scanner before the correlated fingerprint.
    // Representation zero is reserved for this pre-selector pass; every real
    // compact tag and authenticated initial-row pointer is nonzero.
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x8b, 0x0c, 0x24])?;
    assembler.instruction(&[
        0x48,
        0xc7,
        0x44,
        0x24,
        root_representation_offset,
        0,
        0,
        0,
        0,
    ])?;
    assembler.branch(&[0xe9], root_setup)?;

    // The root scanner returns its exact first candidate base in RDX. Resume
    // Teddy there, reloading only the public haystack/end and identity anchor
    // that the root implementation is allowed to borrow.
    assembler.bind(scan_from_root)?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, 0x18])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x48])?;
    assembler.instruction(&[0x4c, 0x8b, 0x0c, 0x24])?;

    x86_emit_mandatory_teddy_constants(assembler, teddy)?;
    assembler.bind(vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x29, 0xd0])?;
    let vector_bytes = u32::from(teddy.plan.columns())
        .checked_sub(1)
        .and_then(|last| last.checked_add(u32::from(teddy.vector_bytes)))
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 correlated-prefix vector bound",
        ))?;
    let mut compare_vector = vec![0x48, 0x3d];
    compare_vector.extend_from_slice(&vector_bytes.to_le_bytes());
    assembler.instruction(&compare_vector)?;
    assembler.branch(&[0x0f, 0x82], scalar)?;
    x86_emit_mandatory_teddy_avx2_candidates(assembler, teddy)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], vector_candidate)?;
    assembler.instruction(&[0x48, 0x83, 0xc2, teddy.vector_bytes])?;
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(scalar)?;
    let maximum_offset = teddy.plan.columns().checked_sub(1).ok_or(
        ObjectError::InvalidModule("x86 correlated-prefix plan has no columns"),
    )?;
    x86_emit_start_filter_scalar_bound(assembler, maximum_offset, exhausted)?;
    x86_emit_mandatory_teddy_scalar_candidate(assembler, teddy)?;
    assembler.branch(&[0x0f, 0x85], candidate)?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    assembler.bind(vector_candidate)?;
    x86_emit_first_candidate_lane(assembler, X86CandidateMask::MovemaskEax)?;
    assembler.instruction(&[0x48, 0x01, 0xc2])?; // start += first candidate lane
    assembler.branch(&[0xe9], candidate)?;

    assembler.bind(exhausted)?;
    assembler.instruction(&[0xc5, 0xf8, 0x77])?;
    assembler.branch(&[0xe9], no_match)?;

    assembler.bind(candidate)?;
    assembler.instruction(&[0xc5, 0xf8, 0x77])?;
    // The exact-root/Teddy cascade proved that no match can start before RDX.
    // Narrow only the private semantic window; absolute result offsets and
    // the public haystack base remain unchanged.
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, 0x40])?;
    assembler.bind(restore_selector)?;
    // Restore the complete SysV public ABI before compact authentication. The
    // scan borrowed RDI/RDX/RCX/R9, while the candidate path deliberately
    // replaced only the frame-resident semantic start.
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, 0x18])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x20])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x40])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, 0x48])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x38])?;
    assembler.instruction(&[0x48, 0x8b, 0x04, 0x24])?;
    assembler.branch(&[0xe9], continue_selector)?;
    Ok(scan_from_root)
}

/// Correlated mandatory-factor scanner for one installed slim plan. A vector
/// miss advances exactly 32 bases. A scalar miss advances exactly one. The
/// unchanged bounded verifier records `candidate + 1` before verification.
/// R12/R13 retain later lanes from the current vector across rejection; once
/// exhausted, scanning resumes at the next block. Scalar rejection resumes at
/// the verifier's exact base+1, proving monotone progress on both routes.
fn x86_emit_mandatory_teddy_suffix_prepass(
    assembler: &mut X86Assembler,
    suffix: NativeSuffixFilter,
    teddy: NativeMandatoryTeddyLayout,
    kind: X86StartFilterKind,
    layout: NativeDfaLayout,
    no_match: X86Label,
    matched: X86Label,
) -> Result<(), ObjectError> {
    validate_x86_mandatory_teddy_layout(suffix, teddy, kind)?;
    if layout.seeded_reverse.is_some() {
        return Err(ObjectError::InvalidModule(
            "x86 mandatory Teddy overlaps seeded reverse",
        ));
    }
    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let vector_hit = assembler.label()?;
    let retained_hit = assembler.label()?;
    let retry_scan = assembler.label()?;
    let apply = assembler.label()?;
    x86_emit_mandatory_teddy_constants(assembler, teddy)?;
    assembler.instruction(&[0x49, 0xc7, 0xc4, 0xff, 0xff, 0xff, 0xff])?; // no retained block

    assembler.bind(vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= base
    let vector_bytes = u32::from(teddy.plan.columns())
        .checked_sub(1)
        .and_then(|last| last.checked_add(u32::from(teddy.vector_bytes)))
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 mandatory Teddy vector bound",
        ))?;
    let mut compare = vec![0x48, 0x3d];
    compare.extend_from_slice(&vector_bytes.to_le_bytes());
    assembler.instruction(&compare)?;
    assembler.branch(&[0x0f, 0x82], scalar)?;
    x86_emit_mandatory_teddy_avx2_candidates(assembler, teddy)?;
    x86_emit_candidate_nonzero(assembler, X86CandidateMask::MovemaskEax)?;
    assembler.branch(&[0x0f, 0x85], vector_hit)?;
    assembler.instruction(&[0x48, 0x83, 0xc2, teddy.vector_bytes])?;
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(scalar)?;
    // A short final window has no retained vector block. Mark it explicitly
    // so a false scalar candidate resumes at the verifier's saved base+1.
    assembler.instruction(&[0x49, 0xc7, 0xc4, 0xff, 0xff, 0xff, 0xff])?;
    let maximum_offset = teddy
        .plan
        .columns()
        .checked_sub(1)
        .ok_or(ObjectError::InvalidModule(
            "x86 mandatory Teddy has no columns",
        ))?;
    x86_emit_start_filter_scalar_bound(assembler, maximum_offset, no_match)?;
    x86_emit_mandatory_teddy_scalar_candidate(assembler, teddy)?;
    assembler.branch(&[0x0f, 0x85], apply)?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    assembler.bind(vector_hit)?;
    x86_emit_retain_candidate_mask(assembler, X86CandidateMask::MovemaskEax)?;
    assembler.bind(retained_hit)?;
    x86_emit_first_retained_candidate(assembler)?;
    // Remove the selected low bit before the verifier can clobber arithmetic
    // flags or RAX. Later rejection therefore sees only strictly later bases.
    assembler.instruction(&[0x49, 0x8d, 0x45, 0xff])?; // rax = r13 - 1
    assembler.instruction(&[0x49, 0x21, 0xc5])?; // r13 &= rax
    assembler.bind(apply)?;
    let retry = suffix.retry.ok_or(ObjectError::InvalidModule(
        "x86 mandatory Teddy has no exact retry verifier",
    ))?;
    module_suffix_retry::x86_emit_bounded_suffix_retry(
        assembler, layout, retry, kind, retry_scan, no_match, matched,
    )?;

    assembler.bind(retry_scan)?;
    assembler.instruction(&[0x49, 0x83, 0xfc, 0xff])?; // scalar/no retained block?
    assembler.branch(&[0x0f, 0x84], vector)?; // verifier supplied candidate + 1
    assembler.instruction(&[0x45, 0x85, 0xed])?; // retained lanes remain?
    assembler.branch(&[0x0f, 0x85], retained_hit)?;
    assembler.instruction(&[0x49, 0x8d, 0x54, 0x24, teddy.vector_bytes])?;
    assembler.instruction(&[0x49, 0xc7, 0xc4, 0xff, 0xff, 0xff, 0xff])?;
    assembler.branch(&[0xe9], vector)?;
    Ok(())
}

/// Scan aligned graph-proven suffix columns before entering the forward
/// machine. The terminal column is primary; other selective columns are
/// loaded only in primary-hit blocks. Absence of any aligned candidate proves
/// that no match exists. The first candidate either applies the bounded-width
/// lower bound or restarts after a nearby all-state synchronizing byte.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct X86AdaptiveSuffixColdPlan {
    joint_vector: X86Label,
    adaptive_scalar: X86Label,
    adaptive_scalar_columns: X86Label,
    adaptive_scalar_reject: X86Label,
    sparse_batch_hit: X86Label,
    single_vector: X86Label,
    apply: X86Label,
    no_match: X86Label,
    filter: NativeStartFilter,
    vector_filter: NativeVectorFilter,
    kind: X86StartFilterKind,
    maximum_scan_offset: u8,
    unrolled_bytes: u32,
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "aligned vector batches, lazy intersections and scalar tails form one suffix proof"
)]
fn x86_emit_suffix_prepass(
    assembler: &mut X86Assembler,
    suffix: NativeSuffixFilter,
    kind: X86StartFilterKind,
    layout: NativeDfaLayout,
    no_match: X86Label,
    matched: X86Label,
) -> Result<Option<X86AdaptiveSuffixColdPlan>, ObjectError> {
    if let Some(teddy) = layout.mandatory_teddy {
        x86_emit_mandatory_teddy_suffix_prepass(
            assembler, suffix, teddy, kind, layout, no_match, matched,
        )?;
        return Ok(None);
    }
    if let Some(reverse) = layout.seeded_reverse {
        x86_emit_seeded_reverse_prepass(
            assembler, suffix, reverse, kind, layout, no_match, matched,
        )?;
        return Ok(None);
    }
    let vector = assembler.label()?;
    let single_vector = assembler.label()?;
    let scalar = assembler.label()?;
    let scalar_columns = assembler.label()?;
    let scalar_reject = assembler.label()?;
    let primary_hit = assembler.label()?;
    let vector_hit = assembler.label()?;
    let sparse_batch_hit = assembler.label()?;
    let joint_vector = assembler.label()?;
    let adaptive_scalar = assembler.label()?;
    let adaptive_scalar_columns = assembler.label()?;
    let adaptive_scalar_reject = assembler.label()?;
    let apply = assembler.label()?;
    let done = assembler.label()?;
    let filter = suffix.filter;
    if suffix.minimum_width == 0 {
        return Err(ObjectError::InvalidModule(
            "x86 suffix filter has zero minimum width",
        ));
    }

    // Every retained column is a graph-required aligned predicate. AVX-512
    // keeps their 64-lane intersection in k5, so the same proof used by the
    // SSE2/AVX2 lazy-secondary path applies without scalar refinement.
    let lazy_vector_filter = suffix.vector_filter;
    let scalar_filter = suffix.vector_filter.or(suffix.scalar_filter);
    let maximum_scan_offset =
        scalar_filter.map_or(filter.scan_offset, NativeVectorFilter::max_scan_offset);
    let use_sparse_batch = x86_use_sparse_filter_mask_batch(filter, kind);
    // The initial suffix scan is exactly the baseline primary-only sparse
    // batch. Only a witnessed scalar secondary rejection after such a hit
    // changes CFG mode: subsequent complete groups use all retained columns.
    // No runtime mode flag or additional live register is required.
    let adaptive_joint_filter = (layout.declined_redundant_root_reverse && use_sparse_batch)
        .then_some(lazy_vector_filter)
        .flatten();
    let emit_constants = |assembler: &mut X86Assembler| -> Result<(), ObjectError> {
        if let Some(vector_filter) = lazy_vector_filter {
            let mut first_register = 1_u8;
            for &column in vector_filter.columns() {
                x86_emit_start_filter_constants(assembler, column, kind, first_register)?;
                first_register = first_register
                    .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                        ObjectError::ArithmeticOverflow("x86 suffix-filter constants")
                    })?)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 suffix-filter constants",
                    ))?;
            }
        } else {
            x86_emit_start_filter_constants(assembler, filter, kind, 1)?;
        }
        Ok(())
    };
    if !ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS {
        emit_constants(assembler)?;
    }
    assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
    let mut minimum = vec![0x48, 0x3d];
    minimum.extend_from_slice(&u32::from(SUFFIX_PREFILTER_MIN_WINDOW_BYTES).to_le_bytes());
    assembler.instruction(&minimum)?;
    assembler.branch(&[0x0f, 0x82], done)?;
    if ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS {
        emit_constants(assembler)?;
    }

    assembler.bind(vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x29, 0xd0])?;
    let unrolled_bytes = u32::from(kind.width())
        .checked_mul(4)
        .and_then(|bytes| bytes.checked_add(u32::from(maximum_scan_offset)))
        .ok_or(ObjectError::ArithmeticOverflow("x86 suffix-filter width"))?;
    let mut compare_unrolled = vec![0x48, 0x3d];
    compare_unrolled.extend_from_slice(&unrolled_bytes.to_le_bytes());
    assembler.instruction(&compare_unrolled)?;
    assembler.branch(&[0x0f, 0x82], single_vector)?;
    let vector_candidate_hit = if lazy_vector_filter.is_some() {
        primary_hit
    } else {
        vector_hit
    };
    if use_sparse_batch {
        x86_emit_sparse_filter_mask_batch(assembler, filter, kind)?;
        assembler.branch(&[0x0f, 0x85], sparse_batch_hit)?;
    } else {
        for _ in 0..X86_MASK_BATCH_VECTORS {
            x86_emit_start_filter_vector_candidate(assembler, filter, kind, vector_candidate_hit)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
        }
    }
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(sparse_batch_hit)?;
    x86_emit_rewind_sparse_filter_mask_batch(assembler, kind)?;
    assembler.branch(
        &[0xe9],
        if adaptive_joint_filter.is_some() {
            adaptive_scalar
        } else {
            scalar
        },
    )?;

    assembler.bind(single_vector)?;
    let single_vector_bytes = kind
        .width()
        .checked_add(maximum_scan_offset)
        .ok_or(ObjectError::ArithmeticOverflow("x86 suffix-filter width"))?;
    assembler.instruction(&[0x48, 0x83, 0xf8, single_vector_bytes])?;
    assembler.branch(&[0x0f, 0x82], scalar)?;
    x86_emit_start_filter_vector_candidate(assembler, filter, kind, vector_candidate_hit)?;
    assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(scalar)?;
    x86_emit_start_filter_scalar_bound(assembler, maximum_scan_offset, no_match)?;
    x86_emit_start_filter_scalar_load(assembler, filter.scan_offset)?;
    let scalar_candidate = if scalar_filter.is_some() {
        scalar_columns
    } else {
        apply
    };
    for range in filter.ranges() {
        assembler.instruction(&[0x3c, range.start])?;
        if range.start == range.end {
            assembler.branch(&[0x0f, 0x84], scalar_candidate)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next_range)?;
            assembler.instruction(&[0x3c, range.end])?;
            assembler.branch(&[0x0f, 0x86], scalar_candidate)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    if let Some(vector_filter) = scalar_filter {
        assembler.bind(scalar_columns)?;
        for &column in &vector_filter.columns()[1..] {
            x86_emit_scalar_filter_membership(assembler, column, scalar_reject)?;
        }
        assembler.branch(&[0xe9], apply)?;
        assembler.bind(scalar_reject)?;
        assembler.instruction(&[0x48, 0xff, 0xc2])?;
        assembler.branch(&[0xe9], vector)?;

        if let Some(lazy_filter) = lazy_vector_filter {
            assembler.bind(primary_hit)?;
            x86_emit_vector_filter_secondary_test(assembler, lazy_filter, kind)?;
            assembler.branch(&[0x0f, 0x85], vector_hit)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
            assembler.branch(&[0xe9], vector)?;
        } else {
            assembler.bind(primary_hit)?;
            assembler.branch(&[0xe9], scalar)?;
        }
    } else {
        assembler.bind(scalar_columns)?;
        assembler.branch(&[0xe9], apply)?;
        assembler.bind(scalar_reject)?;
        assembler.branch(&[0xe9], scalar)?;
        assembler.bind(primary_hit)?;
        assembler.branch(&[0xe9], scalar)?;
    }

    assembler.bind(vector_hit)?;
    let vector_hit_mask = if lazy_vector_filter.is_some() {
        X86CandidateMask::for_intersection(kind)
    } else {
        X86CandidateMask::for_filter(filter, kind)
    };
    x86_emit_first_candidate_lane(assembler, vector_hit_mask)?;
    assembler.instruction(&[0x48, 0x01, 0xc2])?;
    assembler.branch(&[0xe9], apply)?;

    assembler.bind(apply)?;
    if let Some(retry) = suffix.retry {
        module_suffix_retry::x86_emit_bounded_suffix_retry(
            assembler, layout, retry, kind, vector, no_match, matched,
        )?;
    } else {
        x86_emit_suffix_restart(assembler, suffix.restart)?;
    }
    assembler.bind(done)?;
    Ok(
        adaptive_joint_filter.map(|vector_filter| X86AdaptiveSuffixColdPlan {
            joint_vector,
            adaptive_scalar,
            adaptive_scalar_columns,
            adaptive_scalar_reject,
            sparse_batch_hit,
            single_vector,
            apply,
            no_match,
            filter,
            vector_filter,
            kind,
            maximum_scan_offset,
            unrolled_bytes,
        }),
    )
}

/// Emit the adaptive joint-group and exact-replay paths after the function's
/// ordinary return. They are reachable only through explicit branches from
/// the suffix prepass, so keeping them cold preserves every dormant scanner
/// byte and offset except the one rel32 edge that enters this region.
fn x86_emit_adaptive_suffix_cold(
    assembler: &mut X86Assembler,
    plan: X86AdaptiveSuffixColdPlan,
) -> Result<(), ObjectError> {
    assembler.bind(plan.joint_vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
    let mut compare_unrolled = vec![0x48, 0x3d];
    compare_unrolled.extend_from_slice(&plan.unrolled_bytes.to_le_bytes());
    assembler.instruction(&compare_unrolled)?;
    // Once fewer than four complete blocks remain there is no full group to
    // optimize; the baseline single-vector/tail handles the remainder.
    assembler.branch(&[0x0f, 0x82], plan.single_vector)?;
    x86_emit_sparse_vector_filter_mask_batch(assembler, plan.vector_filter, plan.kind)?;
    assembler.branch(&[0x0f, 0x85], plan.sparse_batch_hit)?;
    assembler.branch(&[0xe9], plan.joint_vector)?;

    // Exact scalar replay begins at the rewound group base. The first false
    // secondary advances exactly one byte, then permanently resumes the joint
    // group CFG without any runtime mode flag or extra live register.
    assembler.bind(plan.adaptive_scalar)?;
    x86_emit_start_filter_scalar_bound(assembler, plan.maximum_scan_offset, plan.no_match)?;
    x86_emit_start_filter_scalar_load(assembler, plan.filter.scan_offset)?;
    for range in plan.filter.ranges() {
        assembler.instruction(&[0x3c, range.start])?;
        if range.start == range.end {
            assembler.branch(&[0x0f, 0x84], plan.adaptive_scalar_columns)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next_range)?;
            assembler.instruction(&[0x3c, range.end])?;
            assembler.branch(&[0x0f, 0x86], plan.adaptive_scalar_columns)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], plan.adaptive_scalar)?;

    assembler.bind(plan.adaptive_scalar_columns)?;
    for &column in &plan.vector_filter.columns()[1..] {
        x86_emit_scalar_filter_membership(assembler, column, plan.adaptive_scalar_reject)?;
    }
    assembler.branch(&[0xe9], plan.apply)?;
    assembler.bind(plan.adaptive_scalar_reject)?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], plan.joint_vector)?;
    Ok(())
}

fn x86_emit_prefix_predicate(
    assembler: &mut X86Assembler,
    predicate: NativePrefixPredicate,
    failed: X86Label,
) -> Result<(), ObjectError> {
    match predicate.membership {
        ScalarPrefixMembership::RejectAll => assembler.branch(&[0xe9], failed)?,
        ScalarPrefixMembership::Bitmap256 => {
            // eax = haystack[position + anchored offset]
            assembler.instruction(&[0x0f, 0xb6, 0x44, 0x17, predicate.position])?;
            // CF = bitmap[eax]. `btq` treats memory as a bit string, so the
            // byte value directly selects one of the membership bits.
            let mut test = vec![0x49, 0x0f, 0xa3, 0x81];
            test.extend_from_slice(&predicate.bitmap_offset.to_le_bytes());
            assembler.instruction(&test)?;
            assembler.branch(&[0x0f, 0x83], failed)?; // jnc
        }
        ScalarPrefixMembership::Ranges(ranges) => {
            x86_emit_prefix_ranges(assembler, predicate.position, ranges, failed)?;
        }
    }
    Ok(())
}

fn x86_emit_prefix_relation(
    assembler: &mut X86Assembler,
    relation: NativePrefixRelationFilter,
    failed: X86Label,
) -> Result<(), ObjectError> {
    // A little-endian halfword is exactly the matrix bit index
    // `first | (second << 8)`. `btq` treats the table as one contiguous bit
    // string, avoiding per-group dispatch on the candidate path.
    assembler.instruction(&[0x0f, 0xb7, 0x04, 0x17])?; // movzx eax, word [rdi+rdx]
    let mut test = vec![0x49, 0x0f, 0xa3, 0x81]; // btq rax, disp32[r9]
    test.extend_from_slice(&relation.bitmap_offset.to_le_bytes());
    assembler.instruction(&test)?;
    assembler.branch(&[0x0f, 0x83], failed)?; // jnc
    Ok(())
}

fn x86_emit_prefix_block(
    assembler: &mut X86Assembler,
    block: NativePrefixBlockGuard,
    kind: X86StartFilterKind,
    failed: X86Label,
) -> Result<(), ObjectError> {
    if block.lane_mask == 0
        || block.byte_mask_offset
            != block
                .expected_offset
                .checked_add(
                    u32::try_from(prefix_block::PREFIX_BLOCK_BYTES).map_err(|_| {
                        ObjectError::ArithmeticOverflow("x86 prefix-block constant width")
                    })?,
                )
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 prefix-block mask offset",
                ))?
    {
        return Err(ObjectError::InvalidModule(
            "x86 prefix-block constants are malformed",
        ));
    }
    match kind {
        X86StartFilterKind::Sse2 => {
            assembler.instruction(&[0xf3, 0x0f, 0x6f, 0x04, 0x17])?; // movdqu xmm0, [rdi+rdx]
            let mut compare = vec![0x66, 0x41, 0x0f, 0x74, 0x81]; // pcmpeqb xmm0, [r9+disp32]
            compare.extend_from_slice(&block.expected_offset.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.instruction(&[0x66, 0x0f, 0xd7, 0xc0])?; // pmovmskb eax, xmm0
        }
        X86StartFilterKind::Avx2 | X86StartFilterKind::Avx512Bw => {
            // Keep the 128-bit block VEX-encoded when the surrounding scanner
            // uses wide registers, avoiding an AVX-to-legacy-SSE transition.
            assembler.instruction(&[0xc5, 0xfa, 0x6f, 0x04, 0x17])?; // vmovdqu xmm0, [rdi+rdx]
            let mut compare = vec![0xc4, 0xc1, 0x79, 0x74, 0x81]; // vpcmpeqb xmm0, xmm0, [r9+disp32]
            compare.extend_from_slice(&block.expected_offset.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.instruction(&[0xc5, 0xf9, 0xd7, 0xc0])?; // vpmovmskb eax, xmm0
        }
    }
    let lane_mask = u32::from(block.lane_mask);
    if block.lane_mask != u16::MAX {
        assembler.instruction(&[0x25, lane_mask as u8, (lane_mask >> 8) as u8, 0, 0])?; // and eax, lane mask
    }
    let mut compare_mask = vec![0x3d]; // cmp eax, lane mask
    compare_mask.extend_from_slice(&lane_mask.to_le_bytes());
    assembler.instruction(&compare_mask)?;
    assembler.branch(&[0x0f, 0x85], failed)?;
    Ok(())
}

fn x86_emit_prefix_guard_path(
    assembler: &mut X86Assembler,
    layout: NativeDfaLayout,
    kind: X86StartFilterKind,
    vector_coverage: Option<NativeVectorGuardCoverage>,
    predicate_failed: X86Label,
    terminal_bound_failed: X86Label,
    prefix_verified: X86Label,
) -> Result<(), ObjectError> {
    let guaranteed_bytes = layout.prefix_guaranteed_bytes()?;
    if vector_coverage.is_none_or(|coverage| coverage.guaranteed_bytes < guaranteed_bytes) {
        assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
        assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
        assembler.instruction(&[0x48, 0x83, 0xf8, guaranteed_bytes])?;
        assembler.branch(&[0x0f, 0x82], terminal_bound_failed)?;
    }
    if let Some(relation) = layout.prefix_relation
        && vector_coverage.is_none_or(|coverage| !coverage.relation)
    {
        x86_emit_prefix_relation(assembler, relation, predicate_failed)?;
    }
    let checked_block = layout.prefix_block.filter(|block| {
        vector_coverage.is_none_or(|coverage| block.lane_mask & !coverage.prefix_positions != 0)
    });
    if let Some(block) = checked_block {
        x86_emit_prefix_block(assembler, block, kind, predicate_failed)?;
    }
    if let Some(prefix) = layout.prefix_filter {
        for &predicate in prefix.predicates() {
            if checked_block.is_some_and(|block| block.covers_position(predicate.position)) {
                continue;
            }
            if vector_coverage.is_some_and(|coverage| coverage.covers_position(predicate.position))
            {
                continue;
            }
            x86_emit_prefix_predicate(assembler, predicate, predicate_failed)?;
        }
    }
    assembler.branch(&[0xe9], prefix_verified)?;
    Ok(())
}

fn x86_emit_prefix_ranges(
    assembler: &mut X86Assembler,
    position: u8,
    ranges: ScalarPrefixRangePlan,
    failed: X86Label,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x0f, 0xb6, 0x44, 0x17, position])?;
    let passed = assembler.label()?;
    for range in ranges.ranges() {
        assembler.instruction(&[0x3c, range.start()])?;
        if range.is_singleton() {
            assembler.branch(&[0x0f, 0x84], passed)?;
        } else {
            let next = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next)?;
            assembler.instruction(&[0x3c, range.end()])?;
            assembler.branch(&[0x0f, 0x86], passed)?;
            assembler.bind(next)?;
        }
    }
    assembler.branch(&[0xe9], failed)?;
    assembler.bind(passed)?;
    Ok(())
}

fn x86_emit_scalar_filter_membership(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    failed: X86Label,
) -> Result<(), ObjectError> {
    if filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule(
            "x86 scalar membership has no candidates",
        ));
    }
    x86_emit_start_filter_scalar_load(assembler, filter.scan_offset)?;
    let passed = assembler.label()?;
    for range in filter.ranges() {
        assembler.instruction(&[0x3c, range.start])?;
        if range.start == range.end {
            assembler.branch(&[0x0f, 0x84], passed)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch(&[0x0f, 0x82], next_range)?;
            assembler.instruction(&[0x3c, range.end])?;
            assembler.branch(&[0x0f, 0x86], passed)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.branch(&[0xe9], failed)?;
    assembler.bind(passed)?;
    Ok(())
}

/// Return an exact anchored-product match at the original window start before
/// a large-window suffix prepass. The normal prefix guard omits the column
/// already validated by the moving start scanner; this entry probe has not run
/// that scanner, so it must test that primary column explicitly.
#[allow(
    clippy::large_types_passed_by_value,
    reason = "the probe consumes the same copyable layout value as the surrounding lowering"
)]
fn x86_emit_exact_start_probe(
    assembler: &mut X86Assembler,
    layout: NativeDfaLayout,
    kind: X86StartFilterKind,
    require_large_window: bool,
    register_outcome: bool,
    failed: X86Label,
    matched: X86Label,
) -> Result<(), ObjectError> {
    let width = layout
        .exact_prefix_match_width
        .ok_or(ObjectError::InvalidModule(
            "x86 exact-start width is absent",
        ))?;
    let primary_offset = layout.start_scanner_offset().ok_or(ObjectError::InvalidModule(
        "x86 exact-start probe has no primary",
    ))?;
    if primary_offset >= width {
        return Err(ObjectError::InvalidModule(
            "x86 exact-start primary is outside its product",
        ));
    }
    if layout
        .prefix_filter
        .is_some_and(|prefix| prefix.guaranteed_bytes != width)
    {
        return Err(ObjectError::InvalidModule(
            "x86 exact-start width disagrees with prefix guard",
        ));
    }

    assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= original start
    if require_large_window {
        let mut large_window = vec![0x48, 0x3d];
        large_window
            .extend_from_slice(&u32::from(SUFFIX_PREFILTER_MIN_WINDOW_BYTES).to_le_bytes());
        assembler.instruction(&large_window)?;
        assembler.branch(&[0x0f, 0x82], failed)?;
    }
    assembler.instruction(&[0x48, 0x83, 0xf8, width])?;
    assembler.branch(&[0x0f, 0x82], failed)?;
    if let Some(block) = layout.prefix_block {
        x86_emit_prefix_block(assembler, block, kind, failed)?;
    }
    if layout
        .prefix_block
        .is_none_or(|block| !block.covers_position(primary_offset))
    {
        if let Some(primary) = layout.start_filter {
            x86_emit_scalar_filter_membership(assembler, primary, failed)?;
        } else {
            let exact = layout.exact_start_byte_set.ok_or(ObjectError::InvalidModule(
                "x86 exact-start probe lost its exact primary",
            ))?;
            let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
                "x86 exact-start probe has no canonical storage",
            ))?;
            x86_emit_exact_byte_set_scalar_load(assembler, u16::from(exact.scan_offset))?;
            let member = assembler.label()?;
            x86_emit_exact_byte_set_test(assembler, storage, member)?;
            assembler.branch(&[0xe9], failed)?;
            assembler.bind(member)?;
        }
    }
    if let Some(prefix) = layout.prefix_filter {
        for &predicate in prefix.predicates() {
            if layout
                .prefix_block
                .is_some_and(|block| block.covers_position(predicate.position))
            {
                continue;
            }
            x86_emit_prefix_predicate(assembler, predicate, failed)?;
        }
    }
    x86_emit_exact_prefix_match(
        assembler,
        width,
        layout.output,
        register_outcome,
        matched,
    )
}

/// Validate and narrow the untouched public x86 search window to the only
/// candidate admitted by an exact-width absolute-boundary proof. `rsi`
/// remains the original haystack length until this helper returns.
fn x86_emit_exact_absolute_anchored_bounds(
    assembler: &mut X86Assembler,
    bounds: AbsoluteAnchoredBounds,
    width: u64,
    no_match: X86Label,
) -> Result<(), ObjectError> {
    if bounds.requires_start {
        assembler.instruction(&[0x48, 0x85, 0xd2])?; // test window start
        assembler.branch(&[0x0f, 0x85], no_match)?;
    }
    if bounds.requires_end {
        assembler.instruction(&[0x48, 0x39, 0xf1])?; // end vs length
        assembler.branch(&[0x0f, 0x85], no_match)?;
    }
    if !bounds.requires_start && !bounds.requires_end {
        return Err(ObjectError::InvalidModule(
            "x86 absolute-anchor entry has no bound",
        ));
    }

    assembler.instruction(&[0x48, 0xb8])?; // movabs rax, width
    push_bytes(&mut assembler.code, &width.to_le_bytes())?;
    match (bounds.requires_start, bounds.requires_end) {
        (true, true) => {
            assembler.instruction(&[0x48, 0x39, 0xc6])?; // len vs width
            assembler.branch(&[0x0f, 0x85], no_match)?;
        }
        (true, false) => {
            assembler.instruction(&[0x48, 0x39, 0xc1])?; // end vs width
            assembler.branch(&[0x0f, 0x82], no_match)?;
            assembler.instruction(&[0x48, 0x89, 0xc1])?; // end = width
        }
        (false, true) => {
            assembler.instruction(&[0x48, 0x39, 0xc6])?; // len vs width
            assembler.branch(&[0x0f, 0x82], no_match)?;
            assembler.instruction(&[0x49, 0x89, 0xf3])?; // start = len
            assembler.instruction(&[0x49, 0x29, 0xc3])?; // start -= width
            assembler.instruction(&[0x4c, 0x39, 0xda])?; // old start vs candidate
            assembler.branch(&[0x0f, 0x87], no_match)?;
            assembler.instruction(&[0x4c, 0x89, 0xda])?; // start = candidate
        }
        (false, false) => unreachable!("absolute-anchor entry has no bound"),
    }
    Ok(())
}

fn x86_emit_start_filter_range_vector_test(
    assembler: &mut X86Assembler,
    filter: NativeStartFilter,
    kind: X86StartFilterKind,
) -> Result<(), ObjectError> {
    if kind != X86StartFilterKind::Avx512Bw {
        return Err(ObjectError::InvalidModule(
            "non-AVX-512 filter reached opmask range test",
        ));
    }
    x86_emit_range_start_filter_vector_candidates(assembler, filter, kind, 1)?;
    x86_emit_candidate_nonzero(assembler, X86CandidateMask::Avx512K4)
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
fn lower_x86_64_dfa_with_emission(
    layout: NativeDfaLayout,
    features: FeatureSet,
) -> Result<NativeDfaEmission, ObjectError> {
    lower_x86_64_dfa_with_entry_contract(
        layout,
        features,
        NativeDfaEntryContract::Public,
    )
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
fn lower_x86_64_dfa_with_entry_contract(
    layout: NativeDfaLayout,
    features: FeatureSet,
    entry_contract: NativeDfaEntryContract,
) -> Result<NativeDfaEmission, ObjectError> {
    if !native_default_exception_layout_is_valid(&layout) {
        return Err(ObjectError::InvalidModule(
            "x86 default-exception layout shape",
        ));
    }
    if layout.start_filter.is_some() && layout.exact_start_byte_set.is_some()
        || layout.exact_start_byte_set.is_some() != layout.exact_start_storage.is_some()
    {
        return Err(ObjectError::InvalidModule(
            "x86 primary scanner layout is inconsistent",
        ));
    }
    if !layout.pending_preserving_scanner_shape_is_valid() {
        return Err(ObjectError::InvalidModule(
            "x86 pending-preserving scanner layout is inconsistent",
        ));
    }
    if entry_contract.fixed_candidate() && layout.mandatory_teddy.is_some() {
        return Err(ObjectError::InvalidModule(
            "x86 fixed candidate retained a moving Teddy scanner",
        ));
    }
    let mut assembler = X86Assembler::new();
    let register_outcome = entry_contract.register_outcome();
    let fixed_candidate = entry_contract.fixed_candidate();
    let scan = assembler.label()?;
    let scalar_scan = assembler.label()?;
    let scalar_transition = assembler.label()?;
    let scalar_body = assembler.label()?;
    let scalar_backedge = assembler.label()?;
    let accelerated_transition = assembler.label()?;
    let partial_resume = assembler.label()?;
    let forward_exception = assembler.label()?;
    let prefix_check = assembler.label()?;
    let prefix_vector_check = assembler.label()?;
    let prefix_verified = assembler.label()?;
    let prefix_apply = assembler.label()?;
    let prefix_fail = assembler.label()?;
    let prefix_retained_fail = assembler.label()?;
    let prefix_terminal = assembler.label()?;
    let filter_vector = assembler.label()?;
    let filter_single_vector = assembler.label()?;
    let filter_scalar = assembler.label()?;
    let filter_scalar_columns = assembler.label()?;
    let filter_scalar_reject = assembler.label()?;
    let filter_vector_primary_hit = assembler.label()?;
    let filter_vector_hit = assembler.label()?;
    let filter_sparse_batch_hit = assembler.label()?;
    let filter_retained_exhausted = assembler.label()?;
    let accept = assembler.label()?;
    let finish = assembler.label()?;
    let no_match = assembler.label()?;
    let matched = assembler.label()?;
    let selected_end = assembler.label()?;
    let invalid = assembler.label()?;
    let done = assembler.label()?;
    let reverse_loop = assembler.label()?;
    let reverse_exception = assembler.label()?;
    let record_reverse_start = assembler.label()?;
    let reverse_continue = assembler.label()?;
    let reverse_finish = assembler.label()?;
    let exact_start_probe_failed = assembler.label()?;

    let instruction_filter = layout
        .start_filter
        .filter(|filter| !filter.ranges().is_empty())
        .or_else(|| {
            layout
                .suffix_filter
                .map(|suffix| suffix.filter)
                .filter(|filter| !filter.ranges().is_empty())
        })
        .or_else(|| layout.loop_skip.map(|skip| skip.filter));
    let table_lookup_kind = x86_start_filter_kind(features);
    let sparse_boundary_tier = x86_sparse_boundary_tier(&layout, table_lookup_kind);
    let filter_kind = (layout.exact_start_byte_set.is_some() || instruction_filter.is_some())
        .then_some(table_lookup_kind);
    let table_lookup_needs_vzeroupper = match layout.transitions {
        TransitionLayout::HybridSparseExceptions(capacity)
        | TransitionLayout::HybridByteSparseExceptions(capacity) => {
            x86_sparse_lookup_needs_vzeroupper(
                NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY,
                layout.cells,
                table_lookup_kind,
            ) || x86_sparse_lookup_needs_vzeroupper(
                capacity,
                layout.cells,
                table_lookup_kind,
            )
        }
        transitions => transitions
            .scalable_exception_capacity()
            .is_some_and(|capacity| {
                x86_sparse_lookup_needs_vzeroupper(
                    capacity,
                    layout.cells,
                    table_lookup_kind,
                )
            }),
    };
    let exact_vector_kind = if layout.exact_start_byte_set.is_some() {
        filter_kind.filter(|kind| !matches!(kind, X86StartFilterKind::Sse2))
    } else {
        None
    };
    let mut scanner_emission = None;
    let prefix_relation_vector = layout
        .prefix_relation
        .and_then(|relation| relation.vector_plan);
    // This exact mask subsumes independent columns zero and one. Keeping their
    // Cartesian SIMD conjunction would recreate precisely the false lanes the
    // relation proves impossible.
    let vector_filter = if prefix_relation_vector.is_some() {
        None
    } else {
        filter_kind.and(layout.vector_filter)
    };
    let candidate = if layout.has_prefix_guard() {
        prefix_check
    } else if layout.prefix_fast_forward.is_some() {
        prefix_apply
    } else {
        scalar_scan
    };
    let vector_coverage = derive_native_vector_guard_coverage(
        layout,
        prefix_relation_vector.is_some(),
        vector_filter,
    );
    let retain_vector_candidates = vector_coverage
        .map(|coverage| coverage.has_rejectable_residual(layout))
        .transpose()?
        .unwrap_or(false);
    // Exact products may replay a rare hit from the bounded group base because
    // every rejected lane resumes the same complete scanner at the next byte.
    // Intersect every selected graph column before that replay. This removes
    // the former dependence on a small scalar residual while retaining the
    // ordinary one-vector mask for tails and non-sparse primaries.
    let use_exact_product_multicolumn_batch = layout.exact_prefix_match_width.is_some()
        && prefix_relation_vector.is_none()
        && vector_filter.is_some()
        && vector_coverage.is_some()
        && layout.start_filter.is_some_and(|filter| {
            filter_kind.is_some_and(|kind| x86_use_sparse_filter_mask_batch(filter, kind))
        });
    let use_sparse_start_batch = (!retain_vector_candidates
        && prefix_relation_vector.is_none()
        && layout.start_filter.is_some_and(|filter| {
            filter_kind.is_some_and(|kind| x86_use_sparse_filter_mask_batch(filter, kind))
        })) || use_exact_product_multicolumn_batch;

    let uses_seeded_reverse = layout.seeded_reverse.is_some();
    let retains_teddy_candidates = layout.mandatory_teddy.is_some();
    if retain_vector_candidates || uses_seeded_reverse || retains_teddy_candidates {
        // R12/R13 are callee-saved under both supported x86-64 ABIs. Every
        // status exit converges on `done`, which restores them in reverse.
        assembler.instruction(&[0x41, 0x54])?; // push r12
        assembler.instruction(&[0x41, 0x55])?; // push r13
    }
    if uses_seeded_reverse {
        assembler.instruction(&[0x41, 0x56])?; // push r14
        assembler.instruction(&[0x41, 0x57])?; // push r15
    }

    if entry_contract.validates_public_args() {
        // Validate start <= end <= length before touching public result
        // memory. The prepared partial core receives the same facts from its
        // sole validated caller and authenticated exact-window preflight.
        assembler.instruction(&[0x48, 0x85, 0xf6])?; // test length sign bit
        assembler.branch(&[0x0f, 0x88], invalid)?;
        assembler.instruction(&[0x48, 0x39, 0xf1])?; // cmp rcx, rsi
        assembler.branch(&[0x0f, 0x87], invalid)?; // ja
        assembler.instruction(&[0x48, 0x39, 0xca])?; // cmp rdx, rcx
        assembler.branch(&[0x0f, 0x87], invalid)?;
        assembler.instruction(&[0x4d, 0x85, 0xc0])?; // test r8, r8
        assembler.branch(&[0x0f, 0x84], invalid)?;
        assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?; // test result alignment
        assembler.branch(&[0x0f, 0x85], invalid)?;
        assembler.instruction(&[0x48, 0x85, 0xff])?; // test rdi, rdi
        assembler.branch(&[0x0f, 0x84], invalid)?;
    }
    if entry_contract.validates_public_args() {
        assembler.instruction(&[0x31, 0xc0])?;
        assembler.instruction(&[0x49, 0x89, 0x00])?;
        assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?;
    }
    if let Some((bounds, width)) = entry_contract.exact_absolute_anchored() {
        x86_emit_exact_absolute_anchored_bounds(&mut assembler, bounds, width, no_match)?;
    }
    assembler.instruction(&[0x48, 0x89, 0xd6])?; // mov rsi, rdx (window start)

    // lea table(%rip), r9
    assembler.instruction(&[0x4c, 0x8d, 0x0d])?;
    let table_displacement_label = assembler.label()?;
    assembler.bind(table_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    let probe_exact_product = layout.exact_prefix_match_width.is_some()
        && (fixed_candidate
            || layout.suffix_filter.is_some()
            || use_exact_product_multicolumn_batch);
    if probe_exact_product {
        let kind = filter_kind.ok_or(ObjectError::InvalidModule(
            "x86 exact-start prefix block has no instruction selection",
        ))?;
        let probe_failed = exact_start_probe_failure_target(
            fixed_candidate,
            exact_start_probe_failed,
            no_match,
        );
        x86_emit_exact_start_probe(
            &mut assembler,
            layout,
            kind,
            !fixed_candidate,
            register_outcome,
            probe_failed,
            matched,
        )?;
        if !fixed_candidate {
            assembler.bind(exact_start_probe_failed)?;
        }
    }
    let adaptive_suffix_cold = if !fixed_candidate
        && let Some(suffix) = layout.suffix_filter
    {
        let kind = filter_kind.ok_or(ObjectError::InvalidModule(
            "x86 suffix filter has no instruction selection",
        ))?;
        x86_emit_suffix_prepass(&mut assembler, suffix, kind, layout, no_match, matched)?
    } else {
        None
    };
    if layout.output != OutputContract::Exists {
        assembler.instruction(&[0x49, 0xc7, 0xc3, 0xff, 0xff, 0xff, 0xff])?; // r11 = none
    }
    x86_set_row(&mut assembler, layout.forward_offset)?;
    if !fixed_candidate
        && let (Some(filter), Some(kind)) = (layout.start_filter, filter_kind)
    {
        if let Some(plan) = prefix_relation_vector {
            x86_emit_prefix_relation_constants(&mut assembler, plan, kind)?;
        } else if let Some(vector_filter) = vector_filter {
            let mut first_register = 1_u8;
            for &column in vector_filter.columns() {
                x86_emit_start_filter_constants(&mut assembler, column, kind, first_register)?;
                first_register = first_register
                    .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                        ObjectError::ArithmeticOverflow("x86 vector-filter constants")
                    })?)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 vector-filter constants",
                    ))?;
            }
        } else {
            x86_emit_start_filter_constants(&mut assembler, filter, kind, 1)?;
        }
    } else if !fixed_candidate && let Some(exact_vector_kind) = exact_vector_kind {
        let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
            "x86 vector exact scanner has no canonical storage",
        ))?;
        x86_emit_exact_vector_constants(&mut assembler, storage, exact_vector_kind)?;
    }

    if layout.initial_pending {
        if layout.output == OutputContract::Exists {
            assembler.branch(&[0xe9], matched)?;
        } else {
            assembler.instruction(&[0x49, 0x89, 0xd3])?;
            if layout.initial_terminal {
                assembler.branch(&[0xe9], finish)?;
            }
        }
    }

    if fixed_candidate {
        // The public proof and exact-width narrowing admitted exactly this
        // start. Enter the initial row directly; moving root/suffix scanners
        // can only rediscover the same candidate and add setup overhead.
        assembler.branch(&[0xe9], scalar_transition)?;
    }

    assembler.bind(scan)?;
    if let Some(filter) = layout.start_filter {
        // The row must be initial. Endpoint contracts ordinarily also require
        // no pending accept, except when the graph receipt proves that every
        // skipped byte is a non-accepting initial self-loop; in that case the
        // existing endpoint survives the skip unchanged.
        if layout.output != OutputContract::Exists && !layout.start_scanner_preserves_pending {
            assembler.instruction(&[0x49, 0x83, 0xfb, 0xff])?; // cmp r11, -1
            assembler.branch(&[0x0f, 0x85], scalar_scan)?;
        }
        let mut initial_row = vec![0x49, 0x8d, 0x81]; // lea offset(r9), rax
        initial_row.extend_from_slice(&layout.forward_offset.to_le_bytes());
        assembler.instruction(&initial_row)?;
        assembler.instruction(&[0x49, 0x39, 0xc2])?; // cmp r10, rax
        assembler.branch(&[0x0f, 0x85], scalar_scan)?;

        if filter.ranges().is_empty() {
            scanner_emission = Some(NativeScannerEmission {
                scan_offset: filter.scan_offset,
                membership: start_filter_membership(filter)?,
                isa: NativeScannerIsa::ScalarEmpty,
                vectorized: false,
            });
            assembler.instruction(&[0x48, 0x89, 0xca])?; // position = end
            assembler.branch(&[0xe9], finish)?;
        } else {
            let kind = filter_kind.ok_or(ObjectError::InvalidModule(
                "x86 start filter has no instruction selection",
            ))?;
            scanner_emission = Some(x86_range_scanner_emission(filter, kind)?);
            let maximum_scan_offset = prefix_relation_vector.map_or_else(
                || vector_filter.map_or(filter.scan_offset, NativeVectorFilter::max_scan_offset),
                |_| 1,
            );
            let vector_candidate_hit = if vector_filter.is_some() {
                filter_vector_primary_hit
            } else {
                filter_vector_hit
            };
            assembler.bind(filter_vector)?;
            assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
            assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
            let unrolled_bytes = u32::from(kind.width())
                .checked_mul(4)
                .and_then(|bytes| bytes.checked_add(u32::from(maximum_scan_offset)))
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 unrolled start-filter width",
                ))?;
            let mut compare_unrolled = vec![0x48, 0x3d]; // cmp rax, imm32
            compare_unrolled.extend_from_slice(&unrolled_bytes.to_le_bytes());
            assembler.instruction(&compare_unrolled)?;
            assembler.branch(&[0x0f, 0x82], filter_single_vector)?;
            if use_sparse_start_batch {
                if use_exact_product_multicolumn_batch {
                    x86_emit_sparse_vector_filter_mask_batch(
                        &mut assembler,
                        vector_filter.ok_or(ObjectError::InvalidModule(
                            "x86 exact-product conjunction has no vector filter",
                        ))?,
                        kind,
                    )?;
                } else {
                    x86_emit_sparse_filter_mask_batch(&mut assembler, filter, kind)?;
                }
                assembler.branch(&[0x0f, 0x85], filter_sparse_batch_hit)?;
            } else {
                for _ in 0..X86_MASK_BATCH_VECTORS {
                    if let Some(plan) = prefix_relation_vector {
                        x86_emit_prefix_relation_vector_test(&mut assembler, plan, kind)?;
                        assembler.branch(&[0x0f, 0x85], vector_candidate_hit)?;
                    } else {
                        x86_emit_start_filter_vector_candidate(
                            &mut assembler,
                            filter,
                            kind,
                            vector_candidate_hit,
                        )?;
                    }
                    assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
                }
            }
            assembler.branch(&[0xe9], filter_vector)?;

            assembler.bind(filter_sparse_batch_hit)?;
            x86_emit_rewind_sparse_filter_mask_batch(&mut assembler, kind)?;
            assembler.branch(&[0xe9], filter_scalar)?;

            assembler.bind(filter_single_vector)?;
            let single_vector_bytes = kind.width().checked_add(maximum_scan_offset).ok_or(
                ObjectError::ArithmeticOverflow("x86 start-filter vector width"),
            )?;
            assembler.instruction(&[0x48, 0x83, 0xf8, single_vector_bytes])?;
            assembler.branch(&[0x0f, 0x82], filter_scalar)?; // remaining < width
            if let Some(plan) = prefix_relation_vector {
                x86_emit_prefix_relation_vector_test(&mut assembler, plan, kind)?;
                assembler.branch(&[0x0f, 0x85], vector_candidate_hit)?;
            } else {
                x86_emit_start_filter_vector_candidate(
                    &mut assembler,
                    filter,
                    kind,
                    vector_candidate_hit,
                )?;
            }
            assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
            assembler.branch(&[0xe9], filter_vector)?;

            // Every instruction selection uses the scalar loop only for the
            // sub-vector tail; full AVX-512 blocks retain their exact mask.
            assembler.bind(filter_scalar)?;
            x86_emit_start_filter_scalar_bound(&mut assembler, maximum_scan_offset, finish)?;
            x86_emit_start_filter_scalar_load(&mut assembler, filter.scan_offset)?;
            let scalar_candidate = if vector_filter.is_some() {
                filter_scalar_columns
            } else {
                candidate
            };
            for range in filter.ranges() {
                assembler.instruction(&[0x3c, range.start])?;
                if range.start == range.end {
                    assembler.branch(&[0x0f, 0x84], scalar_candidate)?;
                } else {
                    let next_range = assembler.label()?;
                    assembler.branch(&[0x0f, 0x82], next_range)?;
                    assembler.instruction(&[0x3c, range.end])?;
                    assembler.branch(&[0x0f, 0x86], scalar_candidate)?;
                    assembler.bind(next_range)?;
                }
            }
            assembler.instruction(&[0x48, 0xff, 0xc2])?;
            assembler.branch(&[0xe9], filter_scalar)?;

            if let Some(vector_filter) = vector_filter {
                assembler.bind(filter_scalar_columns)?;
                for &column in &vector_filter.columns()[1..] {
                    x86_emit_scalar_filter_membership(
                        &mut assembler,
                        column,
                        filter_scalar_reject,
                    )?;
                }
                assembler.branch(&[0xe9], candidate)?;
                assembler.bind(filter_scalar_reject)?;
                assembler.instruction(&[0x48, 0xff, 0xc2])?;
                assembler.branch(&[0xe9], filter_scalar)?;

                assembler.bind(filter_vector_primary_hit)?;
                // Preserve the primary candidate vector across the hot-path
                // branch and pay for secondary loads only after that primary
                // vector actually hits. A false intersection skips the whole
                // block, avoiding repeated scalar/prefix refinement.
                x86_emit_vector_filter_secondary_test(&mut assembler, vector_filter, kind)?;
                assembler.branch(&[0x0f, 0x85], filter_vector_hit)?;
                assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
                assembler.branch(&[0xe9], filter_vector)?;
            }

            assembler.bind(filter_vector_hit)?;
            // The vector branch preserved the exact lane mask and base
            // position for this block. Select its first lane without scalar
            // rescanning, including AVX-512 lanes 32..63.
            let vector_hit_mask = if prefix_relation_vector.is_some() || vector_filter.is_some() {
                X86CandidateMask::for_intersection(kind)
            } else {
                X86CandidateMask::for_filter(filter, kind)
            };
            if retain_vector_candidates {
                x86_emit_retain_candidate_mask(&mut assembler, vector_hit_mask)?;
                x86_emit_first_retained_candidate(&mut assembler)?;
            } else {
                x86_emit_first_candidate_lane(&mut assembler, vector_hit_mask)?;
                assembler.instruction(&[0x48, 0x01, 0xc2])?; // position += first lane
            }
            assembler.branch(
                &[0xe9],
                if vector_coverage.is_some() {
                    prefix_vector_check
                } else {
                    candidate
                },
            )?;
        }
    } else if let Some(exact) = layout.exact_start_byte_set {
        let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
            "x86 exact scanner has no canonical storage",
        ))?;
        if storage.aarch64_lut_offset.is_some()
            || !storage.bitmap_offset.is_multiple_of(8)
            || !exact.is_valid()
        {
            return Err(ObjectError::InvalidModule(
                "x86 exact scanner storage is malformed",
            ));
        }
        scanner_emission = Some(NativeScannerEmission {
            scan_offset: exact.scan_offset,
            membership: exact.membership,
            isa: match exact_vector_kind {
                Some(X86StartFilterKind::Avx2) => NativeScannerIsa::X86Avx2,
                Some(X86StartFilterKind::Avx512Bw) => NativeScannerIsa::X86Avx512Bw,
                Some(X86StartFilterKind::Sse2) => {
                    return Err(ObjectError::InvalidModule(
                        "x86 exact scanner selected an unsupported SSE2 vector route",
                    ));
                }
                None => NativeScannerIsa::X86ScalarBitmap,
            },
            vectorized: exact_vector_kind.is_some(),
        });
        if layout.output != OutputContract::Exists && !layout.start_scanner_preserves_pending {
            assembler.instruction(&[0x49, 0x83, 0xfb, 0xff])?; // cmp r11, -1
            assembler.branch(&[0x0f, 0x85], scalar_scan)?;
        }
        let mut initial_row = vec![0x49, 0x8d, 0x81];
        initial_row.extend_from_slice(&layout.forward_offset.to_le_bytes());
        assembler.instruction(&initial_row)?;
        assembler.instruction(&[0x49, 0x39, 0xc2])?;
        assembler.branch(&[0x0f, 0x85], scalar_scan)?;

        let scalar = assembler.label()?;
        if let Some(exact_vector_kind) = exact_vector_kind {
            let vector = assembler.label()?;
            let vector_hit = assembler.label()?;
            assembler.bind(vector)?;
            assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
            assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
            let required = u32::from(exact.scan_offset)
                .checked_add(u32::from(exact_vector_kind.width()))
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 exact vector scanner bound",
                ))?;
            let mut compare = vec![0x48, 0x3d];
            compare.extend_from_slice(&required.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.branch(&[0x0f, 0x82], scalar)?;
            let candidate_mask = x86_emit_exact_vector_candidates(
                &mut assembler,
                exact_vector_kind,
                exact.scan_offset,
            )?;
            x86_emit_candidate_nonzero(&mut assembler, candidate_mask)?;
            assembler.branch(&[0x0f, 0x85], vector_hit)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, exact_vector_kind.width()])?;
            assembler.branch(&[0xe9], vector)?;
            assembler.bind(vector_hit)?;
            x86_emit_first_candidate_lane(&mut assembler, candidate_mask)?;
            assembler.instruction(&[0x48, 0x01, 0xc2])?;
            assembler.branch(&[0xe9], candidate)?;
        } else {
            let unrolled = assembler.label()?;
            let lane_one = assembler.label()?;
            let lane_two = assembler.label()?;
            let lane_three = assembler.label()?;
            assembler.bind(unrolled)?;
            assembler.instruction(&[0x48, 0x89, 0xc8])?; // remaining = end
            assembler.instruction(&[0x48, 0x29, 0xd0])?; // remaining -= position
            let required = u32::from(exact.scan_offset).checked_add(4).ok_or(
                ObjectError::ArithmeticOverflow("x86 exact scanner unrolled bound"),
            )?;
            let mut compare = vec![0x48, 0x3d];
            compare.extend_from_slice(&required.to_le_bytes());
            assembler.instruction(&compare)?;
            assembler.branch(&[0x0f, 0x82], scalar)?;
            x86_emit_exact_byte_set_scalar_load(&mut assembler, u16::from(exact.scan_offset))?;
            x86_emit_exact_byte_set_test(&mut assembler, storage, candidate)?;
            x86_emit_exact_byte_set_scalar_load(
                &mut assembler,
                u16::from(exact.scan_offset) + 1,
            )?;
            x86_emit_exact_byte_set_test(&mut assembler, storage, lane_one)?;
            x86_emit_exact_byte_set_scalar_load(
                &mut assembler,
                u16::from(exact.scan_offset) + 2,
            )?;
            x86_emit_exact_byte_set_test(&mut assembler, storage, lane_two)?;
            x86_emit_exact_byte_set_scalar_load(
                &mut assembler,
                u16::from(exact.scan_offset) + 3,
            )?;
            x86_emit_exact_byte_set_test(&mut assembler, storage, lane_three)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 4])?;
            assembler.branch(&[0xe9], unrolled)?;

            assembler.bind(lane_three)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 3])?;
            assembler.branch(&[0xe9], candidate)?;
            assembler.bind(lane_two)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 2])?;
            assembler.branch(&[0xe9], candidate)?;
            assembler.bind(lane_one)?;
            assembler.instruction(&[0x48, 0xff, 0xc2])?;
            assembler.branch(&[0xe9], candidate)?;
        }

        assembler.bind(scalar)?;
        x86_emit_exact_byte_set_scalar_bound(&mut assembler, exact.scan_offset, finish)?;
        x86_emit_exact_byte_set_scalar_load(&mut assembler, u16::from(exact.scan_offset))?;
        x86_emit_exact_byte_set_test(&mut assembler, storage, candidate)?;
        assembler.instruction(&[0x48, 0xff, 0xc2])?;
        assembler.branch(&[0xe9], scalar)?;
    }

    if layout.has_prefix_guard() {
        let kind = filter_kind.ok_or(ObjectError::InvalidModule(
            "x86 prefix guard has no instruction selection",
        ))?;
        assembler.bind(prefix_check)?;
        x86_emit_prefix_guard_path(
            &mut assembler,
            layout,
            kind,
            None,
            prefix_fail,
            prefix_terminal,
            prefix_verified,
        )?;
        assembler.bind(prefix_fail)?;
        // A rejected anchored start says nothing about the immediately
        // following start. Advance exactly one byte and rescan from the
        // untouched initial DFA state.
        assembler.instruction(&[0x48, 0xff, 0xc2])?;
        x86_set_row(&mut assembler, layout.forward_offset)?;
        assembler.branch(&[0xe9], scan)?;

        if let Some(coverage) = vector_coverage {
            assembler.bind(prefix_vector_check)?;
            x86_emit_prefix_guard_path(
                &mut assembler,
                layout,
                kind,
                Some(coverage),
                if retain_vector_candidates {
                    prefix_retained_fail
                } else {
                    prefix_fail
                },
                prefix_terminal,
                prefix_verified,
            )?;
        }
        if retain_vector_candidates {
            assembler.bind(prefix_retained_fail)?;
            x86_emit_clear_first_retained_candidate(&mut assembler)?;
            assembler.branch(&[0x0f, 0x84], filter_retained_exhausted)?;
            x86_emit_first_retained_candidate(&mut assembler)?;
            x86_set_row(&mut assembler, layout.forward_offset)?;
            assembler.branch(&[0xe9], prefix_vector_check)?;

            assembler.bind(filter_retained_exhausted)?;
            let kind = filter_kind.ok_or(ObjectError::InvalidModule(
                "x86 retained mask has no instruction selection",
            ))?;
            x86_emit_advance_retained_block(&mut assembler, kind.width())?;
            x86_set_row(&mut assembler, layout.forward_offset)?;
            assembler.branch(&[0xe9], filter_vector)?;
        }

        assembler.bind(prefix_terminal)?;
        assembler.branch(&[0xe9], finish)?;

        assembler.bind(prefix_verified)?;
        if let Some(width) = layout.exact_prefix_match_width {
            x86_emit_exact_prefix_match(
                &mut assembler,
                width,
                layout.output,
                register_outcome,
                matched,
            )?;
        } else {
            assembler.branch(&[0xe9], prefix_apply)?;
        }
    }

    assembler.bind(prefix_apply)?;
    x86_set_row(&mut assembler, layout.forward_offset)?;
    if let Some(plan) = layout.prefix_fast_forward {
        assembler.instruction(&[0x48, 0x83, 0xc2, plan.consumed_bytes])?;
        x86_set_row(&mut assembler, plan.target_row_offset)?;
    }
    assembler.bind(scalar_scan)?;
    if let Some(plan) = layout.loop_skip {
        let kind = filter_kind.ok_or(ObjectError::InvalidModule(
            "x86 loop skip has no instruction selection",
        ))?;
        let secondary_dispatch = layout
            .loop_skip_secondary
            .map(|_| assembler.label())
            .transpose()?
            .unwrap_or(scalar_transition);
        module_dfa_loop_skip::x86_emit_dfa_loop_skip(
            &mut assembler,
            plan,
            &layout,
            vector_filter,
            kind,
            exact_vector_kind,
            module_dfa_loop_skip::NativeDfaLoopSkipRole::Primary,
            secondary_dispatch,
            scalar_transition,
            scalar_transition,
            finish,
        )?;
        if let Some(secondary) = layout.loop_skip_secondary {
            assembler.bind(secondary_dispatch)?;
            module_dfa_loop_skip::x86_emit_dfa_loop_skip(
                &mut assembler,
                secondary,
                &layout,
                vector_filter,
                kind,
                exact_vector_kind,
                module_dfa_loop_skip::NativeDfaLoopSkipRole::Secondary,
                scalar_transition,
                scalar_transition,
                scalar_body,
                finish,
            )?;
        }
    }
    assembler.bind(scalar_transition)?;
    assembler.instruction(&[0x48, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x83], finish)?; // position >= end
    assembler.bind(scalar_body)?;
    x86_emit_table_lookup_with_sparse_boundary_tier(
        &mut assembler,
        layout.transitions,
        layout.cells,
        x86_start_filter_kind(features),
        sparse_boundary_tier,
    )?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?; // position += 1
    // Every ordinary live token is at most this encoding's authenticated
    // maximum. Either metadata bit, including the bit carried by every
    // forward dead sentinel, moves the unsigned value above that range.
    x86_emit_unsigned_cell_classifier(&mut assembler, layout.cells)?;
    assembler.branch(&[0x0f, 0x87], forward_exception)?; // ja
    match layout.cells {
        NativeCellEncoding::Compact8Direct
        | NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            x86_emit_set_row_from_compact_zero_based_cell(&mut assembler, layout.cells)?;
        }
        NativeCellEncoding::Wide32 => {
            // The authenticated forward packer tags dead zero, so every
            // ordinary wide value here is a nonzero one-based token.
            x86_emit_set_row_from_cell(&mut assembler, layout.cells)?;
        }
    }
    assembler.branch(&[0xe9], scalar_backedge)?;
    assembler.bind(scalar_backedge)?;
    // Rotate the steady-state loop around its bounds check. Scanner and
    // accelerator entries still use `scalar_transition`, while ordinary live
    // cells consume one fused compare/backedge instead of a guard plus an
    // unconditional backedge on every byte.
    assembler.instruction(&[0x48, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x82], scalar_body)?; // position < end
    assembler.branch(&[0xe9], finish)?;

    assembler.bind(accelerated_transition)?;
    x86_emit_and_eax_mask(&mut assembler, layout.cells.next_mask())?;
    if layout.cells == NativeCellEncoding::Wide32 {
        // Wide dead cells have a zero payload after stripping metadata. Consume
        // AND's zero flag before the optional partial-hole comparison overwrites
        // it; row addressing must never consume zero as a one-based wide token.
        assembler.branch(&[0x0f, 0x84], finish)?;
    }
    if layout.cells.is_compact() {
        let mut compare_dead = vec![0x3d]; // cmp eax, compact dead payload
        compare_dead.extend_from_slice(&layout.cells.dead_token().to_le_bytes());
        assembler.instruction(&compare_dead)?;
        assembler.branch(&[0x0f, 0x84], finish)?;
    }
    if let Some(partial) = layout.partial {
        let mut compare_hole = vec![0x3d]; // cmp eax, hole_token_base
        compare_hole.extend_from_slice(&partial.hole_token_base.to_le_bytes());
        assembler.instruction(&compare_hole)?;
        assembler.branch(&[0x0f, 0x83], partial_resume)?; // jae
    }
    if layout.cells.is_compact() {
        x86_emit_set_row_from_compact_zero_based_cell(&mut assembler, layout.cells)?;
    } else {
        x86_emit_set_row_from_cell(&mut assembler, layout.cells)?;
    }
    // An exact absolute entry admits only one candidate and deliberately
    // omits the moving root scanner's setup. A moving entry without a root
    // scanner must also preserve this live accelerated row: its `scan` label
    // falls through the root-only prefix-apply row reset. Only an installed
    // scanner can distinguish an accelerated initial row (which may scan for
    // a later candidate) from an accelerated interior loop row (which enters
    // `scalar_scan` without changing X10).
    assembler.branch(
        &[0xe9],
        if fixed_candidate || !layout.has_start_scanner() {
            scalar_scan
        } else {
            scan
        },
    )?;

    assembler.bind(partial_resume)?;
    if let Some(partial) = layout.partial {
        // Entering an incomplete state after the final consumed byte is a
        // complete decision and must not invoke K0.
        assembler.instruction(&[0x48, 0x39, 0xca])?; // cmp position, end
        assembler.branch(&[0x0f, 0x84], finish)?;
        let mut subtract_base = vec![0x2d]; // sub eax, hole_token_base
        subtract_base.extend_from_slice(&partial.hole_token_base.to_le_bytes());
        assembler.instruction(&subtract_base)?;
        if register_outcome {
            assembler.instruction(&[0x49, 0x89, 0xc2])?; // r10 = resume state
        } else {
            assembler.instruction(&[0x49, 0x89, 0x40, 0x10])?; // resume_state
            assembler.instruction(&[0x49, 0x89, 0x50, 0x18])?; // resume_position
            if layout.output == OutputContract::Exists {
                assembler.instruction(&[
                    0x49, 0xc7, 0x40, 0x20, 0xff, 0xff, 0xff, 0xff,
                ])?;
            } else {
                assembler.instruction(&[0x4d, 0x89, 0x58, 0x20])?; // pending_end
            }
        }
        let mut status = vec![0xb8];
        status.extend_from_slice(&NATIVE_PARTIAL_STATUS_RESUME.to_le_bytes());
        assembler.instruction(&status)?;
        assembler.branch(&[0xe9], done)?;
    }

    assembler.bind(forward_exception)?;
    x86_emit_test_eax_mask(&mut assembler, layout.cells.accepts())?;
    assembler.branch(&[0x0f, 0x85], accept)?;
    // Every non-accepting forward exception is accelerator-tagged: a graph
    // accelerator, partial hole, or the explicit dead sentinel.
    assembler.branch(&[0xe9], accelerated_transition)?;

    assembler.bind(accept)?;
    if layout.output == OutputContract::Exists {
        assembler.branch(&[0xe9], matched)?;
    } else {
        assembler.instruction(&[0x49, 0x89, 0xd3])?;
        // Normalize only the cold accepting edge. This makes an accepted-live
        // cell identical to an ordinary token while accepted-dead retains its
        // explicit accelerator sentinel at every cell width.
        x86_emit_clear_eax_bit(&mut assembler, layout.cells.accepts_bit())?;
        x86_emit_test_eax_mask(&mut assembler, layout.cells.accelerated())?;
        assembler.branch(&[0x0f, 0x85], accelerated_transition)?;
        match layout.cells {
            NativeCellEncoding::Compact8Direct
            | NativeCellEncoding::Compact16
            | NativeCellEncoding::Compact16Indexed(_)
            | NativeCellEncoding::Compact16Ordinal(_) => {
                // With both metadata bits disproved, EAX is already the
                // zero-based scaled row token, including valid row zero.
                x86_emit_set_row_from_compact_zero_based_cell(&mut assembler, layout.cells)?;
            }
            NativeCellEncoding::Wide32 => {
                // Accepted dead is tagged, so an ordinary accepted wide cell
                // is necessarily a nonzero one-based row token.
                x86_emit_set_row_from_cell(&mut assembler, layout.cells)?;
            }
        }
        assembler.branch(&[0xe9], scalar_backedge)?;
    }

    assembler.bind(finish)?;
    if layout.output == OutputContract::Exists {
        // All accepting paths have already returned directly through
        // `matched`; reaching the ordinary exit proves no match.
        assembler.branch(&[0xe9], no_match)?;
    } else {
        assembler.instruction(&[0x49, 0x83, 0xfb, 0xff])?;
        assembler.branch(&[0x0f, 0x84], no_match)?;
    }
    if layout.output == OutputContract::Span && !layout.initial_pending {
        if layout.exact_span_width.is_none() && !layout.has_reverse && layout.partial.is_none() {
            return Err(ObjectError::InvalidModule(
                "native span lowering has no reverse table",
            ));
        }
    } else {
        if layout.output == OutputContract::Span {
            if register_outcome {
                assembler.instruction(&[0x49, 0x89, 0xf2])?; // r10 = window start
            } else {
                assembler.instruction(&[0x49, 0x89, 0x30])?; // result.start = window_start
                assembler.instruction(&[0x4d, 0x89, 0x58, 0x08])?;
            }
        } else if layout.output == OutputContract::SelectedEnd && !register_outcome {
            assembler.instruction(&[0x4d, 0x89, 0x18])?; // result.start = selected end
            assembler.instruction(&[0x4d, 0x89, 0x58, 0x08])?;
        }
        assembler.branch(&[0xe9], matched)?;
    }

    if layout.output == OutputContract::Span && !layout.initial_pending {
        if !register_outcome {
            assembler.instruction(&[0x4d, 0x89, 0x58, 0x08])?; // preserve selected end
        }
        if let Some(width) = layout.exact_span_width {
            if layout.has_reverse {
                return Err(ObjectError::InvalidModule(
                    "fixed-width native span unexpectedly retained a reverse table",
                ));
            }
            x86_emit_exact_span_start(&mut assembler, width)?;
            if register_outcome {
                assembler.instruction(&[0x49, 0x89, 0xc2])?; // r10 = selected end - width
            } else {
                assembler.instruction(&[0x49, 0x89, 0x00])?; // result.start = selected end - width
            }
            assembler.branch(&[0xe9], matched)?;
        } else if layout.partial.is_some() {
            if entry_contract.propagates_partial_span_window_start() {
                if register_outcome {
                    assembler.instruction(&[0x49, 0x89, 0xf2])?; // r10 = admitted window start
                } else {
                    assembler.instruction(&[0x49, 0x89, 0x30])?;
                }
                assembler.branch(&[0xe9], matched)?;
            } else {
                assembler.branch(&[0xe9], selected_end)?;
            }
        } else {
            assembler.instruction(&[0x4c, 0x89, 0xda])?; // cursor = selected end
            assembler.instruction(&[0x48, 0xc7, 0xc1, 0xff, 0xff, 0xff, 0xff])?; // no candidate
            x86_set_row(&mut assembler, layout.reverse_offset)?;
            assembler.bind(reverse_loop)?;
            assembler.instruction(&[0x48, 0x39, 0xf2])?;
            assembler.branch(&[0x0f, 0x86], reverse_finish)?; // cursor <= window_start
            assembler.instruction(&[0x48, 0xff, 0xca])?;
            x86_emit_table_lookup_with_sparse_boundary_tier(
                &mut assembler,
                layout.transitions,
                layout.cells,
                x86_start_filter_kind(features),
                sparse_boundary_tier,
            )?;
            match layout.cells {
                NativeCellEncoding::Compact8Direct
                | NativeCellEncoding::Compact16
                | NativeCellEncoding::Compact16Indexed(_)
                | NativeCellEncoding::Compact16Ordinal(_) => {
                    x86_emit_unsigned_cell_classifier(&mut assembler, layout.cells)?;
                    assembler.branch(&[0x0f, 0x87], reverse_exception)?;
                    x86_emit_set_row_from_compact_zero_based_cell(
                        &mut assembler,
                        layout.cells,
                    )?;
                    assembler.branch(&[0xe9], reverse_loop)?;
                }
                NativeCellEncoding::Wide32 => {
                    assembler.instruction(&[0x85, 0xc0])?;
                    assembler.branch(&[0x0f, 0x88], record_reverse_start)?;
                    assembler.branch(&[0x0f, 0x84], reverse_finish)?;
                }
            }
            assembler.bind(reverse_continue)?;
            if layout.cells == NativeCellEncoding::Wide32 {
                x86_emit_set_row_from_cell(&mut assembler, layout.cells)?;
                assembler.branch(&[0xe9], reverse_loop)?;
            }

            assembler.bind(reverse_exception)?;
            if layout.cells.is_compact() {
                x86_emit_test_eax_mask(&mut assembler, layout.cells.accepts())?;
                assembler.branch(&[0x0f, 0x85], record_reverse_start)?;
                // The only non-accepting compact exception is dead.
                assembler.branch(&[0xe9], reverse_finish)?;
            }

            assembler.bind(record_reverse_start)?;
            assembler.instruction(&[0x48, 0x89, 0xd1])?;
            x86_emit_clear_eax_bit(&mut assembler, layout.cells.accepts_bit())?;
            if layout.cells.is_compact() {
                x86_emit_test_eax_mask(&mut assembler, layout.cells.accelerated())?;
                assembler.branch(&[0x0f, 0x85], reverse_finish)?;
                x86_emit_set_row_from_compact_zero_based_cell(&mut assembler, layout.cells)?;
                assembler.branch(&[0xe9], reverse_loop)?;
            } else {
                assembler.instruction(&[0x85, 0xc0])?;
                assembler.branch(&[0x0f, 0x84], reverse_finish)?;
                assembler.branch(&[0xe9], reverse_continue)?;
            }

            assembler.bind(reverse_finish)?;
            assembler.instruction(&[0x48, 0x83, 0xf9, 0xff])?;
            assembler.branch(&[0x0f, 0x84], invalid)?;
            assembler.instruction(&[0x49, 0x89, 0x08])?;
            assembler.branch(&[0xe9], matched)?;
        }
    }

    assembler.bind(no_match)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], done)?;
    assembler.bind(matched)?;
    assembler.instruction(&[0xb8, 0x01, 0x00, 0x00, 0x00])?;
    assembler.branch(&[0xe9], done)?;
    assembler.bind(selected_end)?;
    if layout.partial.is_some() {
        let mut status = vec![0xb8];
        status.extend_from_slice(&NATIVE_PARTIAL_STATUS_SELECTED_END.to_le_bytes());
        assembler.instruction(&status)?;
        assembler.branch(&[0xe9], done)?;
    }
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0x00, 0x00, 0x00])?;
    assembler.bind(done)?;
    if uses_seeded_reverse {
        assembler.instruction(&[0x41, 0x5f])?; // pop r15
        assembler.instruction(&[0x41, 0x5e])?; // pop r14
    }
    if retain_vector_candidates || uses_seeded_reverse || retains_teddy_candidates {
        assembler.instruction(&[0x41, 0x5d])?; // pop r13
        assembler.instruction(&[0x41, 0x5c])?; // pop r12
    }
    if (filter_kind.is_some_and(X86StartFilterKind::needs_vzeroupper)
        && (!fixed_candidate || probe_exact_product && layout.prefix_block.is_some()))
        || table_lookup_needs_vzeroupper
    {
        assembler.instruction(&[0xc5, 0xf8, 0x77])?;
    }
    assembler.instruction(&[0xc3])?;
    let adaptive_cold_start = if let Some(plan) = adaptive_suffix_cold {
        let cold_start = assembler.label()?;
        assembler.bind(cold_start)?;
        x86_emit_adaptive_suffix_cold(&mut assembler, plan)?;
        Some(cold_start)
    } else {
        None
    };

    let mut finished = assembler.finish_with_label_offsets()?;
    let table_displacement = finished.label_offset(table_displacement_label)?;
    if let Some(cold_start_label) = adaptive_cold_start {
        let cold_start = finished.label_offset(cold_start_label)?;
        let cold_bytes =
            finished
                .code
                .len()
                .checked_sub(cold_start)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 adaptive suffix cold size",
                ))?;
        let aligned_cold_bytes = cold_bytes
            .checked_add(X86_COLD_LINK_ALIGNMENT_BYTES - 1)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 adaptive suffix cold alignment",
            ))?
            & !(X86_COLD_LINK_ALIGNMENT_BYTES - 1);
        let padding =
            aligned_cold_bytes
                .checked_sub(cold_bytes)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 adaptive suffix cold padding",
                ))?;
        let mut padding_assembler = X86Assembler::new();
        x86_emit_unreachable_nops(&mut padding_assembler, padding)?;
        let padding = padding_assembler.finish_with_label_offsets()?.code;
        push_bytes(&mut finished.code, &padding)?;
    }

    let code = finished.code;
    let relocations = vec![ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(table_displacement, "x86 DFA table relocation offset")?,
            kind: RelocationKind::X86PcRelative32,
            symbol: PROGRAM_SYMBOL,
            addend: -4,
        }];
    let conjunction_batch_vectors = if use_exact_product_multicolumn_batch {
        u8::try_from(X86_MASK_BATCH_VECTORS)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 conjunction batch vectors"))?
    } else {
        1
    };
    let conjunction = vector_filter
        .zip(vector_coverage)
        .map(|(filter, coverage)| NativeVectorConjunctionEmission {
            filter,
            coverage,
            batch_vectors: conjunction_batch_vectors,
        });
    // A correlated Teddy receipt cannot be represented as one independent
    // byte-membership receipt. Its exact plan/ISA/offset receipt lives in the
    // layout itself; accelerator accounting reads that receipt directly.
    // Retained fallback publication authenticates that correlated receipt
    // separately instead of fabricating a one-column scanner emission.
    let suffix_scanner = if layout.mandatory_teddy.is_some() {
        None
    } else {
        layout
            .suffix_filter
            .map(|suffix| {
                let kind = filter_kind.ok_or(ObjectError::InvalidModule(
                    "x86 suffix scanner has no instruction selection",
                ))?;
                x86_range_scanner_emission(suffix.filter, kind)
            })
            .transpose()?
    };
    Ok(NativeDfaEmission {
        code,
        relocations,
        scanner: scanner_emission,
        suffix_scanner,
        conjunction,
    })
}

#[cfg(test)]
#[allow(
    clippy::large_types_passed_by_value,
    reason = "the test-only compatibility wrapper consumes the same copyable layout as the receipt-returning backend"
)]
fn lower_x86_64_dfa(
    layout: NativeDfaLayout,
    features: FeatureSet,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let emission = lower_x86_64_dfa_with_emission(layout, features)?;
    Ok((emission.code, emission.relocations))
}

fn x86_emit_public_search_abi_validation(
    assembler: &mut X86Assembler,
    invalid: X86Label,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xf1])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    Ok(())
}

fn x86_finish_native_finite_exists_leaf(
    assembler: &mut X86Assembler,
    matched: X86Label,
    no_match: X86Label,
    invalid: X86Label,
    uses_wide_vectors: bool,
) -> Result<(), ObjectError> {
    let returned = assembler.label()?;
    assembler.bind(matched)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(no_match)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.bind(returned)?;
    if uses_wide_vectors {
        assembler.instruction(&[0xc5, 0xf8, 0x77])?; // vzeroupper
    }
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    Ok(())
}

fn lower_x86_64_native_finite_exists_universal(
    membership: [u64; 4],
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    let mut assembler = X86Assembler::new();
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x49, 0x89, 0x00])?;
    assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?;
    assembler.instruction(&[0x48, 0x39, 0xca])?; // start == end?
    assembler.branch(&[0x0f, 0x82], matched)?;
    assembler.branch(&[0xe9], no_match)?;
    x86_finish_native_finite_exists_leaf(
        &mut assembler,
        matched,
        no_match,
        invalid,
        false,
    )?;
    Ok(NativeFiniteExistsByteSetEmission {
        code: assembler.finish_with_label_offsets()?.code,
        relocations: Vec::new(),
        scanner: NativeScannerEmission {
            scan_offset: 0,
            membership,
            isa: NativeScannerIsa::ScalarEmpty,
            vectorized: false,
        },
    })
}

fn lower_x86_64_native_finite_exists_filter(
    filter: NativeStartFilter,
    features: FeatureSet,
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    if filter.scan_offset != 0 || filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule(
            "x86 finite Exists filter has invalid geometry",
        ));
    }
    let kind = x86_start_filter_kind(features);
    let mut assembler = X86Assembler::new();
    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let scalar_miss = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x49, 0x89, 0x00])?;
    assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?;
    x86_emit_start_filter_constants(&mut assembler, filter, kind, 1)?;

    assembler.bind(vector)?;
    assembler.instruction(&[0x48, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x29, 0xd0])?;
    assembler.instruction(&[0x48, 0x83, 0xf8, kind.width()])?;
    assembler.branch(&[0x0f, 0x82], scalar)?;
    let _mask = x86_emit_start_filter_vector_test(&mut assembler, filter, kind)?;
    assembler.branch(&[0x0f, 0x85], matched)?;
    assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
    assembler.branch(&[0xe9], vector)?;

    assembler.bind(scalar)?;
    x86_emit_start_filter_scalar_bound(&mut assembler, 0, no_match)?;
    x86_emit_scalar_filter_membership(&mut assembler, filter, scalar_miss)?;
    assembler.branch(&[0xe9], matched)?;
    assembler.bind(scalar_miss)?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    x86_finish_native_finite_exists_leaf(
        &mut assembler,
        matched,
        no_match,
        invalid,
        kind.needs_vzeroupper(),
    )?;
    Ok(NativeFiniteExistsByteSetEmission {
        code: assembler.finish_with_label_offsets()?.code,
        relocations: Vec::new(),
        scanner: x86_range_scanner_emission(filter, kind)?,
    })
}

fn lower_x86_64_native_finite_exists_exact(
    set: NativeExactByteSet,
    storage: NativeExactByteSetStorage,
    features: FeatureSet,
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    if set.scan_offset != 0 || !set.is_valid() || storage.aarch64_lut_offset.is_some() {
        return Err(ObjectError::InvalidModule(
            "x86 finite Exists exact-set storage is malformed",
        ));
    }
    let vector_kind = if features.has(CpuFeature::X86Avx2)
        || (features.has(CpuFeature::X86Avx512F)
            && features.has(CpuFeature::X86Avx512Bw))
    {
        Some(x86_start_filter_kind(features))
    } else {
        None
    };
    let mut assembler = X86Assembler::new();
    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x49, 0x89, 0x00])?;
    assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?;
    assembler.instruction(&[0x4c, 0x8d, 0x0d])?;
    let program_displacement = assembler.label()?;
    assembler.bind(program_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    if let Some(kind) = vector_kind {
        x86_emit_exact_vector_constants(&mut assembler, storage, kind)?;
        assembler.bind(vector)?;
        assembler.instruction(&[0x48, 0x89, 0xc8])?;
        assembler.instruction(&[0x48, 0x29, 0xd0])?;
        assembler.instruction(&[0x48, 0x83, 0xf8, kind.width()])?;
        assembler.branch(&[0x0f, 0x82], scalar)?;
        let mask = x86_emit_exact_vector_candidates(&mut assembler, kind, 0)?;
        x86_emit_candidate_nonzero(&mut assembler, mask)?;
        assembler.branch(&[0x0f, 0x85], matched)?;
        assembler.instruction(&[0x48, 0x83, 0xc2, kind.width()])?;
        assembler.branch(&[0xe9], vector)?;
    }

    assembler.bind(scalar)?;
    x86_emit_exact_byte_set_scalar_bound(&mut assembler, 0, no_match)?;
    x86_emit_exact_byte_set_scalar_load(&mut assembler, 0)?;
    x86_emit_exact_byte_set_test(&mut assembler, storage, matched)?;
    assembler.instruction(&[0x48, 0xff, 0xc2])?;
    assembler.branch(&[0xe9], scalar)?;

    x86_finish_native_finite_exists_leaf(
        &mut assembler,
        matched,
        no_match,
        invalid,
        vector_kind.is_some(),
    )?;
    let finished = assembler.finish_with_label_offsets()?;
    let program_displacement = finished.label_offset(program_displacement)?;
    let isa = match vector_kind {
        Some(X86StartFilterKind::Avx2) => NativeScannerIsa::X86Avx2,
        Some(X86StartFilterKind::Avx512Bw) => NativeScannerIsa::X86Avx512Bw,
        Some(X86StartFilterKind::Sse2) => {
            return Err(ObjectError::InvalidModule(
                "x86 arbitrary exact set selected SSE2",
            ));
        }
        None => NativeScannerIsa::X86ScalarBitmap,
    };
    Ok(NativeFiniteExistsByteSetEmission {
        code: finished.code,
        relocations: vec![ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                program_displacement,
                "x86 finite Exists exact-set relocation offset",
            )?,
            kind: RelocationKind::X86PcRelative32,
            symbol: PROGRAM_SYMBOL,
            addend: -4,
        }],
        scanner: NativeScannerEmission {
            scan_offset: 0,
            membership: set.membership,
            isa,
            vectorized: vector_kind.is_some(),
        },
    })
}

/// Scalar System-V leaf for the authenticated ordered finite-language graph.
/// It is intentionally call-free and uses only the baseline x86-64 ISA; AVX2
/// and AVX-512 start scanning can be added after this exact leaf is proven.
fn lower_x86_64_native_finite_language(
    output: OutputContract,
    layout: NativeFiniteLanguageLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    match layout.representation {
        NativeFiniteLanguageRepresentation::Dense
        | NativeFiniteLanguageRepresentation::SparseFailure => {
            lower_x86_64_native_finite_language_impl(output, layout)
        }
    }
}

fn lower_x86_64_native_finite_language_impl(
    output: OutputContract,
    layout: NativeFiniteLanguageLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let row_offset = i32::try_from(layout.row_offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 finite row offset"))?;
    let output_in_row_offset = i32::try_from(layout.output_in_row_offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 finite row output offset"))?;
    let ordinal_in_row_offset = output_in_row_offset
        .checked_add(4)
        .ok_or(ObjectError::ArithmeticOverflow("x86 finite ordinal offset"))?;

    let mut assembler = X86Assembler::new();
    let scan = assembler.label()?;
    let replace = assembler.label()?;
    let horizon = assembler.label()?;
    let finish = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;
    let sparse_labels = if layout.representation
        == NativeFiniteLanguageRepresentation::SparseFailure
    {
        Some((
            assembler.label()?, // root-only loop while no match is pending
            assembler.label()?, // retry the current byte after failure
            assembler.label()?, // direct root table
            assembler.label()?, // root miss from the generic retry path
            assembler.label()?, // specialized one-edge row
            assembler.label()?, // straight-line two-to-four-edge row
            assembler.label()?, // explicit-edge loop
            assembler.label()?, // explicit edge found
            assembler.label()?, // follow failure
            assembler.label()?, // transition selected
        ))
    } else {
        None
    };
    let root_batch = native_finite_root_batch_is_admitted(layout);
    let root_scalar_only = if root_batch {
        Some(assembler.label()?)
    } else {
        None
    };

    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(&[0x31, 0xc0])?; // xor eax, eax
    assembler.instruction(&[0x49, 0x89, 0x00])?; // result[0] = 0
    assembler.instruction(&[0x49, 0x89, 0x40, 0x08])?; // result[1] = 0

    // Preserve the five callee-saved registers owned by this call-free leaf.
    assembler.instruction(&[0x53])?; // push rbx
    assembler.instruction(&[0x41, 0x54])?; // push r12
    assembler.instruction(&[0x41, 0x55])?; // push r13
    assembler.instruction(&[0x41, 0x56])?; // push r14
    assembler.instruction(&[0x41, 0x57])?; // push r15
    if root_batch {
        // A zero stack word means batching is still enabled. The first batch
        // containing a root transition flips it permanently for this search.
        assembler.instruction(&[0x50])?; // push zeroed rax
    }

    // lea program(%rip), r9. The class map begins at program+0.
    assembler.instruction(&[0x4c, 0x8d, 0x0d])?;
    let program_displacement = assembler.label()?;
    assembler.bind(program_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    let mut rows_base = vec![0x4d, 0x8d, 0x91]; // lea rows(%r9), %r10
    rows_base.extend_from_slice(&row_offset.to_le_bytes());
    assembler.instruction(&rows_base)?;
    assembler.instruction(&[0x4c, 0x89, 0xd3])?; // current row = rows base
    assembler.instruction(&[0x49, 0x89, 0xcc])?; // pending start = window end sentinel
    assembler.instruction(&[0x41, 0xbe, 0xff, 0xff, 0xff, 0xff])?; // pending ordinal
    let mut maximum_width = vec![0x41, 0xbf]; // mov maximum width, r15d
    maximum_width.extend_from_slice(&layout.maximum_width.to_le_bytes());
    assembler.instruction(&maximum_width)?;

    if let Some((root_scan, _, _, _, _, _, _, _, _, transitioned)) = sparse_labels {
        if let Some(root_scalar_only) = root_scalar_only {
            // Root table zero is the root-row token. Join four independent
            // probes before the common miss backedge. Once a batch observes
            // any root transition, keep the remainder of this search scalar:
            // this retains the sparse-miss win while bounding adversarial
            // dense-candidate overhead to one speculative batch.
            let root_scalar_tail = assembler.label()?;
            assembler.bind(root_scan)?;
            assembler.instruction(&[0x48, 0x89, 0xce])?; // remaining = end
            assembler.instruction(&[0x48, 0x29, 0xd6])?; // remaining -= position
            assembler.instruction(&[0x48, 0x83, 0xfe, 0x04])?;
            assembler.branch(&[0x0f, 0x82], root_scalar_tail)?;
            assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x41, 0x0f, 0xb7, 0x04, 0x41])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x41, 0x8b, 0x04, 0x81])?;
                }
            }
            assembler.instruction(&[0x0f, 0xb6, 0x74, 0x17, 0x01])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x41, 0x0f, 0xb7, 0x34, 0x71])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x41, 0x8b, 0x34, 0xb1])?;
                }
            }
            assembler.instruction(&[0x44, 0x0f, 0xb6, 0x5c, 0x17, 0x02])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x47, 0x0f, 0xb7, 0x1c, 0x59])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x47, 0x8b, 0x1c, 0x99])?;
                }
            }
            assembler.instruction(&[0x44, 0x0f, 0xb6, 0x6c, 0x17, 0x03])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x47, 0x0f, 0xb7, 0x2c, 0x69])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x47, 0x8b, 0x2c, 0xa9])?;
                }
            }
            assembler.instruction(&[0x09, 0xf0])?;
            assembler.instruction(&[0x44, 0x09, 0xd8])?;
            assembler.instruction(&[0x44, 0x09, 0xe8])?;
            let root_batch_miss = assembler.label()?;
            assembler.branch(&[0x0f, 0x84], root_batch_miss)?;
            assembler.instruction(&[0xc6, 0x04, 0x24, 0x01])?; // disable batching
            assembler.branch(&[0xe9], root_scalar_only)?;
            assembler.bind(root_batch_miss)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 0x04])?;
            assembler.branch(&[0xe9], root_scan)?;

            assembler.bind(root_scalar_tail)?;
            assembler.instruction(&[0x48, 0x39, 0xca])?;
            assembler.branch(&[0x0f, 0x83], finish)?;
            assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x41, 0x0f, 0xb7, 0x34, 0x41])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x41, 0x8b, 0x34, 0x81])?;
                }
            }
            assembler.instruction(&[0x85, 0xf6])?;
            assembler.branch(&[0x0f, 0x85], transitioned)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 0x01])?;
            assembler.branch(&[0xe9], root_scan)?;

            assembler.bind(root_scalar_only)?;
            assembler.instruction(&[0x48, 0x39, 0xca])?;
            assembler.branch(&[0x0f, 0x83], finish)?;
            assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x41, 0x0f, 0xb7, 0x34, 0x41])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x41, 0x8b, 0x34, 0x81])?;
                }
            }
            assembler.instruction(&[0x85, 0xf6])?;
            assembler.branch(&[0x0f, 0x85], transitioned)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 0x01])?;
            assembler.branch(&[0xe9], root_scalar_only)?;
        } else {
            assembler.bind(root_scan)?;
            assembler.instruction(&[0x48, 0x39, 0xca])?;
            assembler.branch(&[0x0f, 0x83], finish)?;
            assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(&[0x41, 0x0f, 0xb7, 0x34, 0x41])?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(&[0x41, 0x8b, 0x34, 0x81])?;
                }
            }
            assembler.instruction(&[0x85, 0xf6])?;
            assembler.branch(&[0x0f, 0x85], transitioned)?;
            assembler.instruction(&[0x48, 0x83, 0xc2, 0x01])?;
            assembler.branch(&[0xe9], root_scan)?;
        }
    }
    assembler.bind(scan)?;
    assembler.instruction(&[0x48, 0x39, 0xca])?; // cmp end, position
    assembler.branch(&[0x0f, 0x83], finish)?; // position >= end
    assembler.instruction(&[0x0f, 0xb6, 0x04, 0x17])?; // byte = haystack[position]
    if let Some((
        _,
        retry,
        root,
        root_miss,
        one_edge,
        small_sparse,
        edge_loop,
        edge_found,
        failure,
        transitioned,
    )) = sparse_labels
    {
        let edge_offset = i32::try_from(layout.sparse_edges_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 finite sparse edge offset"))?;

        assembler.bind(retry)?;
        assembler.instruction(&[0x4c, 0x39, 0xd3])?; // current row == root row?
        assembler.branch(&[0x0f, 0x84], root)?;
        assembler.instruction(&[0x44, 0x8b, 0x5b, 0x04])?; // packed edge metadata
        assembler.instruction(&[0x44, 0x89, 0xde])?; // edge start -> esi
        let mut mask_start = vec![0x81, 0xe6]; // and start mask, esi
        mask_start.extend_from_slice(&NATIVE_FINITE_SPARSE_EDGE_START_MASK.to_le_bytes());
        assembler.instruction(&mask_start)?;
        let mut edge_address = match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => vec![0x49, 0x8d, 0xb4, 0xb1],
            NativeFiniteLanguageCellWidth::U32 => vec![0x49, 0x8d, 0xb4, 0xf1],
        }; // lea edges(program, index * stride), rsi
        edge_address.extend_from_slice(&edge_offset.to_le_bytes());
        assembler.instruction(&edge_address)?;
        assembler.instruction(&[0x41, 0xc1, 0xeb, 0x14])?; // edge count -> r11d
        assembler.instruction(&[0x41, 0x83, 0xfb, 0x01])?; // one explicit edge?
        assembler.branch(&[0x0f, 0x84], one_edge)?;
        assembler.branch(&[0x0f, 0x82], failure)?; // zero-edge state
        assembler.instruction(&[0x41, 0x83, 0xfb, 0x04])?;
        assembler.branch(&[0x0f, 0x86], small_sparse)?; // two through four

        assembler.bind(edge_loop)?;
        assembler.instruction(&[0x45, 0x85, 0xdb])?;
        assembler.branch(&[0x0f, 0x84], failure)?;
        assembler.instruction(&[0x38, 0x06])?; // edge byte == input byte?
        assembler.branch(&[0x0f, 0x84], edge_found)?;
        assembler.branch(&[0x0f, 0x87], failure)?; // sorted edge passed input
        assembler.instruction(match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => &[0x48, 0x83, 0xc6, 0x04],
            NativeFiniteLanguageCellWidth::U32 => &[0x48, 0x83, 0xc6, 0x08],
        })?;
        assembler.instruction(&[0x41, 0x83, 0xeb, 0x01])?;
        assembler.branch(&[0xe9], edge_loop)?;

        assembler.bind(one_edge)?;
        assembler.instruction(&[0x38, 0x06])?;
        assembler.branch(&[0x0f, 0x84], edge_found)?;
        assembler.branch(&[0xe9], failure)?;

        assembler.bind(small_sparse)?;
        for index in 0_u8..4 {
            assembler.instruction(&[0x38, 0x06])?;
            assembler.branch(&[0x0f, 0x84], edge_found)?;
            if index == 3 {
                assembler.branch(&[0xe9], failure)?;
                break;
            }
            assembler.branch(&[0x0f, 0x87], failure)?; // sorted edge passed input
            if index != 0 {
                assembler.instruction(&[0x41, 0x83, 0xfb, index + 1])?;
                assembler.branch(&[0x0f, 0x84], failure)?;
            }
            assembler.instruction(match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => &[0x48, 0x83, 0xc6, 0x04],
                NativeFiniteLanguageCellWidth::U32 => &[0x48, 0x83, 0xc6, 0x08],
            })?;
        }

        assembler.bind(failure)?;
        assembler.instruction(&[0x8b, 0x1b])?; // failure row token
        assembler.instruction(&[0x49, 0x8d, 0x1c, 0x1a])?; // rows base + failure
        assembler.branch(&[0xe9], retry)?;

        assembler.bind(root)?;
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(&[0x41, 0x0f, 0xb7, 0x34, 0x41])?;
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(&[0x41, 0x8b, 0x34, 0x81])?;
            }
        }
        assembler.instruction(&[0x85, 0xf6])?; // root row token is zero
        assembler.branch(&[0x0f, 0x84], root_miss)?;
        assembler.branch(&[0xe9], transitioned)?;

        assembler.bind(root_miss)?;
        assembler.instruction(&[0x48, 0x83, 0xc2, 0x01])?; // ++position
        assembler.branch(&[0xe9], horizon)?;

        assembler.bind(edge_found)?;
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(&[0x0f, 0xb7, 0x76, 0x02])?;
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(&[0x8b, 0x76, 0x04])?;
            }
        }
        assembler.bind(transitioned)?;
        assembler.instruction(&[0x49, 0x8d, 0x1c, 0x32])?; // row = rows base + token
    } else {
        assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x01])?; // class = map[byte]
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(&[0x0f, 0xb7, 0x34, 0x43])?; // token = row[class*2]
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(&[0x8b, 0x34, 0x83])?; // token = row[class*4]
            }
        }
        assembler.instruction(&[0x49, 0x8d, 0x1c, 0x32])?; // row = rows base + token
    }
    assembler.instruction(&[0x48, 0x83, 0xc2, 0x01])?; // ++position
    let mut width_load = vec![0x8b, 0x83];
    width_load.extend_from_slice(&output_in_row_offset.to_le_bytes());
    assembler.instruction(&width_load)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], horizon)?;

    if output == OutputContract::Exists {
        assembler.branch(&[0xe9], matched)?;
    } else {
        let mut ordinal_load = vec![0x8b, 0xb3];
        ordinal_load.extend_from_slice(&ordinal_in_row_offset.to_le_bytes());
        assembler.instruction(&ordinal_load)?;
        assembler.instruction(&[0x49, 0x89, 0xd3])?; // candidate start = position
        assembler.instruction(&[0x49, 0x29, 0xc3])?; // candidate start -= width
        assembler.instruction(&[0x4d, 0x39, 0xe3])?; // cmp pending start, candidate start
        assembler.branch(&[0x0f, 0x82], replace)?;
        assembler.branch(&[0x0f, 0x87], horizon)?;
        assembler.instruction(&[0x44, 0x39, 0xf6])?; // cmp pending ordinal, candidate ordinal
        assembler.branch(&[0x0f, 0x83], horizon)?;

        assembler.bind(replace)?;
        assembler.instruction(&[0x4d, 0x89, 0xdc])?; // pending start = candidate start
        assembler.instruction(&[0x49, 0x89, 0xd5])?; // pending end = position
        assembler.instruction(&[0x41, 0x89, 0xf6])?; // pending ordinal = candidate ordinal
    }

    assembler.bind(horizon)?;
    assembler.instruction(&[0x49, 0x39, 0xcc])?; // pending sentinel?
    if let Some((root_scan, ..)) = sparse_labels {
        let pending = assembler.label()?;
        assembler.branch(&[0x0f, 0x85], pending)?;
        assembler.instruction(&[0x4c, 0x39, 0xd3])?; // current row == root row?
        assembler.branch(&[0x0f, 0x85], scan)?;
        if let Some(root_scalar_only) = root_scalar_only {
            assembler.instruction(&[0x80, 0x3c, 0x24, 0x00])?;
            assembler.branch(&[0x0f, 0x85], root_scalar_only)?;
        }
        assembler.branch(&[0xe9], root_scan)?;
        assembler.bind(pending)?;
    } else {
        assembler.branch(&[0x0f, 0x84], scan)?;
    }
    assembler.instruction(&[0x4d, 0x89, 0xe3])?; // horizon = pending start
    assembler.instruction(&[0x4d, 0x01, 0xfb])?; // horizon += maximum width
    assembler.instruction(&[0x4c, 0x39, 0xda])?; // cmp horizon, position
    assembler.branch(&[0x0f, 0x83], finish)?;
    assembler.branch(&[0xe9], scan)?;

    assembler.bind(finish)?;
    if output == OutputContract::Exists {
        assembler.branch(&[0xe9], no_match)?;
    } else {
        assembler.instruction(&[0x49, 0x39, 0xcc])?;
        assembler.branch(&[0x0f, 0x84], no_match)?;
        match output {
            OutputContract::SelectedEnd => {
                assembler.instruction(&[0x4d, 0x89, 0x28])?;
                assembler.instruction(&[0x4d, 0x89, 0x68, 0x08])?;
            }
            OutputContract::Span => {
                assembler.instruction(&[0x4d, 0x89, 0x20])?;
                assembler.instruction(&[0x4d, 0x89, 0x68, 0x08])?;
            }
            OutputContract::Exists => unreachable!("handled above"),
        }
        assembler.branch(&[0xe9], matched)?;
    }

    assembler.bind(matched)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(no_match)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.bind(returned)?;
    if root_batch {
        assembler.instruction(&[0x48, 0x83, 0xc4, 0x08])?;
    }
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let program_displacement = finished.label_offset(program_displacement)?;
    Ok((
        finished.code,
        vec![ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(program_displacement, "x86 finite program relocation offset")?,
            kind: RelocationKind::X86PcRelative32,
            symbol: PROGRAM_SYMBOL,
            addend: -4,
        }],
    ))
}

fn lower_x86_64_runtime_adapter() -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let mut assembler = X86Assembler::new();
    let invalid = assembler.label()?;

    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;

    // Shift five public arguments right by one register:
    // r8 -> r9, rcx -> r8, rdx -> rcx, rsi -> rdx, rdi -> rsi.
    assembler.instruction(&[0x4d, 0x89, 0xc1])?;
    assembler.instruction(&[0x49, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x89, 0xd1])?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?;
    assembler.instruction(&[0x48, 0x89, 0xfe])?;

    // lea program(%rip), %rdi
    assembler.instruction(&[0x48, 0x8d, 0x3d])?;
    let program_displacement_label = assembler.label()?;
    assembler.bind(program_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    // jmp runtime@PLT -- a tail call preserves the caller's return address.
    assembler.instruction(&[0xe9])?;
    let runtime_displacement_label = assembler.label()?;
    assembler.bind(runtime_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    let finished = assembler.finish_with_label_offsets()?;
    let program_displacement = finished.label_offset(program_displacement_label)?;
    let runtime_displacement = finished.label_offset(runtime_displacement_label)?;
    let code = finished.code;

    Ok((
        code,
        vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(program_displacement, "x86 program relocation offset")?,
                kind: RelocationKind::X86PcRelative32,
                symbol: PROGRAM_SYMBOL,
                // ELF PC32 defines P as the relocation field address, while
                // the ISA displacement is relative to the end of that field.
                addend: -4,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(runtime_displacement, "x86 runtime relocation offset")?,
                kind: RelocationKind::X86PltRelative32,
                symbol: RUNTIME_SYMBOL,
                addend: -4,
            },
        ],
    ))
}

fn lower_x86_64_endpoint_oracle_wrapper(
    mode: NativeEndpointOracleMode,
) -> Result<NativeEndpointOracleWrapper, ObjectError> {
    match mode {
        NativeEndpointOracleMode::NegativeOnly => {
            lower_x86_64_negative_endpoint_oracle_wrapper()
        }
        NativeEndpointOracleMode::Exact { output, width } => {
            lower_x86_64_exact_endpoint_oracle_wrapper(output, width)
        }
    }
}

/// The exact wrapper's local leaf returns the first accepting end in RDX when
/// EAX is one. The eight-byte frame both aligns the private call and preserves
/// only the public result pointer; no haystack/window arguments need replay.
fn lower_x86_64_exact_endpoint_oracle_wrapper(
    output: NativeExactEndpointOutput,
    width: u64,
) -> Result<NativeEndpointOracleWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 8;
    let mut assembler = X86Assembler::new();
    let matched = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x4c, 0x89, 0x04, 0x24])?; // result -> [rsp]
    assembler.instruction(&[0xe8])?;
    let core_call_displacement = assembler.label()?;
    assembler.bind(core_call_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], returned)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.instruction(&[0x83, 0xf8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], returned)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4c, 0x8b, 0x04, 0x24])?; // result -> r8
    match output {
        NativeExactEndpointOutput::SelectedEnd => {
            assembler.instruction(&[0x49, 0x89, 0x10])?; // end -> result.start
            assembler.instruction(&[0x49, 0x89, 0x50, 0x08])?; // end -> result.end
        }
        NativeExactEndpointOutput::Span => {
            assembler.instruction(&[0x48, 0x89, 0xd0])?; // end -> start scratch
            if width != 0 {
                let mut load_width = vec![0x49, 0xb9]; // movabs width, r9
                load_width.extend_from_slice(&width.to_le_bytes());
                assembler.instruction(&load_width)?;
                assembler.instruction(&[0x4c, 0x29, 0xc8])?; // start = end - width
            }
            assembler.instruction(&[0x49, 0x89, 0x00])?; // start -> result.start
            assembler.instruction(&[0x49, 0x89, 0x50, 0x08])?; // end -> result.end
        }
    }
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativeEndpointOracleWrapper {
        core_call_offset: finished.label_offset(core_call_displacement)?,
        code: finished.code,
        relocations: Vec::new(),
    })
}

fn lower_x86_64_negative_endpoint_oracle_wrapper()
-> Result<NativeEndpointOracleWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 40;
    let mut assembler = X86Assembler::new();
    let no_match = assembler.label()?;
    let replay = assembler.label()?;
    let runtime_fallback = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    // Preserve the public runtime adapter's fail-closed ABI boundary. In
    // particular, the result pointer is not touched before every scalar has
    // been authenticated.
    x86_emit_public_search_abi_validation(&mut assembler, invalid)?;

    // Portable endpoint probing starts at this same whole-window floor.
    // Short inputs tail directly to the semantic runtime with all five public
    // arguments still live and unchanged.
    assembler.instruction(&[0x48, 0x89, 0xc8])?; // rax = end
    assembler.instruction(&[0x48, 0x29, 0xd0])?; // rax -= start
    let mut compare_minimum = vec![0x48, 0x3d];
    compare_minimum.extend_from_slice(
        &u32::try_from(NATIVE_ENDPOINT_ORACLE_MIN_INPUT_BYTES)
            .map_err(|_| ObjectError::ArithmeticOverflow("x86 endpoint-oracle input floor"))?
            .to_le_bytes(),
    );
    assembler.instruction(&compare_minimum)?;
    assembler.branch(&[0x0f, 0x82], runtime_fallback)?;

    // Entry RSP is 8 modulo 16. Saving all five public arguments in a 40-byte
    // frame aligns the local leaf call and leaves a positive result able to
    // restart the exact original window through the semantic runtime.
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x89, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0xe8])?;
    let core_call_displacement = assembler.label()?;
    assembler.bind(core_call_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], no_match)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], replay)?;
    assembler.instruction(&[0x83, 0xf8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], returned)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(no_match)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(replay)?;
    assembler.instruction(&[0x48, 0x8b, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.bind(runtime_fallback)?;
    // Shift the restored public arguments right for runtime(program, ...).
    assembler.instruction(&[0x4d, 0x89, 0xc1])?;
    assembler.instruction(&[0x49, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x89, 0xd1])?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?;
    assembler.instruction(&[0x48, 0x89, 0xfe])?;
    assembler.instruction(&[0x48, 0x8d, 0x3d])?;
    let program_displacement = assembler.label()?;
    assembler.bind(program_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0xe9])?;
    let runtime_displacement = assembler.label()?;
    assembler.bind(runtime_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let core_call_offset = finished.label_offset(core_call_displacement)?;
    let program_offset = finished.label_offset(program_displacement)?;
    let runtime_offset = finished.label_offset(runtime_displacement)?;
    Ok(NativeEndpointOracleWrapper {
        code: finished.code,
        relocations: vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(program_offset, "x86 endpoint-oracle program relocation")?,
                kind: RelocationKind::X86PcRelative32,
                symbol: PROGRAM_SYMBOL,
                addend: -4,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(runtime_offset, "x86 endpoint-oracle runtime relocation")?,
                kind: RelocationKind::X86PltRelative32,
                symbol: RUNTIME_SYMBOL,
                addend: -4,
            },
        ],
        core_call_offset,
    })
}

fn lower_x86_64_prepared_runtime_adapter() -> (Vec<u8>, Vec<ModuleRelocation>) {
    // The exclusive helper has exactly the prepared entry's six-argument
    // SysV ABI. A tail jump needs no shuffle, frame, or target feature.
    (
        vec![0xe9, 0, 0, 0, 0],
        vec![ModuleRelocation {
            section: TEXT_SECTION,
            offset: 1,
            kind: RelocationKind::X86PltRelative32,
            symbol: RUNTIME_ADAPTER_PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: -4,
        }],
    )
}

/// Terminal consumer for the one shared non-overlapping Span iterator.
/// `Fill` deliberately retains its established lowering byte-for-byte; the
/// scalar sinks keep the same progress machine in one private generated frame.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PreparedSpanSink {
    Fill {
        large_window_runtime_bulk: bool,
    },
    Count,
    SpanSum,
}

/// Emit a one-shot SysV operation gate after the enclosing wrapper has
/// completed all read-only raw/state validation. The classifier accepts only
/// the handle in RDI. All six register arguments and the entry stack (which
/// may carry additional ABI arguments) are restored before either successor.
fn x86_emit_ordered_nfa_operation_gate(
    assembler: &mut X86Assembler,
    compatibility_identity: bool,
) -> Result<(usize, usize, Option<usize>), ObjectError> {
    let native = assembler.label()?;
    let legacy = assembler.label()?;
    assembler.instruction(&[0x48, 0x83, 0xec, 0x38])?; // align call frame
    assembler.instruction(&[0x48, 0x89, 0x3c, 0x24])?; // rdi
    assembler.instruction(&[0x48, 0x89, 0x74, 0x24, 0x08])?; // rsi
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, 0x10])?; // rdx
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x18])?; // rcx
    assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, 0x20])?; // r8
    assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, 0x28])?; // r9
    assembler.instruction(&[0xe8])?;
    let gate_call = assembler.label()?;
    assembler.bind(gate_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x48, 0x8b, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x28])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, 0x38])?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], native)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], legacy)?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(legacy)?;
    let identity_relocation = if compatibility_identity {
        assembler.instruction(&[0x4c, 0x8d, 0x05])?; // lea identity(%rip),r8
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        Some(displacement)
    } else {
        None
    };
    assembler.instruction(&[0xe9])?;
    let runtime_fallback = assembler.label()?;
    assembler.bind(runtime_fallback)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.bind(native)?;
    Ok((gate_call, runtime_fallback, identity_relocation))
}

/// Admit only the exact capability-bearing Ordered-NFA owner. Unlike the
/// compatibility gate above, a legacy handle fails closed instead of taking a
/// semantic runtime reducer edge. This is the boundary used by reducers that
/// claim the complete operation is compiler-generated native code.
fn x86_emit_required_ordered_nfa_operation_gate(
    assembler: &mut X86Assembler,
) -> Result<usize, ObjectError> {
    let native = assembler.label()?;
    let failed = assembler.label()?;
    assembler.instruction(&[0x48, 0x83, 0xec, 0x38])?;
    assembler.instruction(&[0x48, 0x89, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x89, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, 0x28])?;
    assembler.instruction(&[0xe8])?;
    let gate_call = assembler.label()?;
    assembler.bind(gate_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x41, 0x89, 0xc3])?; // preserve classifier status
    assembler.instruction(&[0x48, 0x8b, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x28])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, 0x38])?;
    assembler.instruction(&[0x41, 0x83, 0xfb, 0x01])?;
    assembler.branch(&[0x0f, 0x84], native)?;
    assembler.instruction(&[0x45, 0x85, 0xdb])?;
    assembler.branch(&[0x0f, 0x85], failed)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?; // legacy is not admitted
    assembler.instruction(&[0xc3])?;
    assembler.bind(failed)?;
    assembler.instruction(&[0x44, 0x89, 0xd8])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(native)?;
    Ok(gate_call)
}

fn lower_x86_64_prepared_span(
    sink: PreparedSpanSink,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    match sink {
        PreparedSpanSink::Fill {
            large_window_runtime_bulk,
        } => lower_x86_64_prepared_span_fill_impl(large_window_runtime_bulk, false),
        PreparedSpanSink::Count | PreparedSpanSink::SpanSum => {
            lower_x86_64_prepared_span_reduce(
                sink,
                NativeSpanReducerCallKind::PreparedPrivate,
                false,
            )
        }
    }
}

fn lower_x86_64_prepared_span_fill(
    large_window_runtime_bulk: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_x86_64_prepared_span(PreparedSpanSink::Fill {
        large_window_runtime_bulk,
    })
}

fn lower_x86_64_ordered_nfa_span_fill() -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_x86_64_prepared_span_fill_impl(false, true)
}

/// Emit the compiler-owned stateful Span refill loop.
///
/// The call placeholder targets the already composed prepared entry in this
/// same text section. Keeping iteration and empty-match progress in this leaf
/// removes one Rust/indirect-ABI round trip per match without duplicating any
/// regex-specific search code.
#[allow(
    clippy::too_many_lines,
    reason = "raw ABI validation, iterator progress, and transactional output publication are one generated leaf"
)]
fn lower_x86_64_prepared_span_fill_impl(
    large_window_runtime_bulk: bool,
    ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    if large_window_runtime_bulk && ordered_nfa_gate {
        return Err(ObjectError::InvalidModule(
            "Ordered-NFA Span fill retained a dynamic large-window edge",
        ));
    }
    const FRAME_BYTES: u8 = 48;
    let mut assembler = X86Assembler::new();
    let validate_state = assembler.label()?;
    let no_pending = assembler.label()?;
    let has_last = assembler.label()?;
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted = assembler.label()?;
    let full = assembler.label()?;
    let finished = assembler.label()?;
    let terminal_error = assembler.label()?;
    let invalid_result = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_bulk = large_window_runtime_bulk
        .then(|| assembler.label())
        .transpose()?;

    // Validate the complete raw boundary before publishing either output.
    assembler.instruction(&[0x48, 0x85, 0xff])?; // handle != null
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // haystack != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?; // length <= isize::MAX
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?; // state != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?; // state alignment
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x08])?; // written
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut maximum_capacity = vec![0x49, 0xba]; // movabs max/16, r10
    maximum_capacity.extend_from_slice(&(isize::MAX as u64 / 16).to_le_bytes());
    assembler.instruction(&maximum_capacity)?;
    assembler.instruction(&[0x4d, 0x39, 0xd1])?; // cmp capacity, max/16
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], validate_state)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?; // output != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;

    assembler.bind(validate_state)?;
    assembler.instruction(&[0x83, 0x79, 0x14, 0x00])?; // reserved == 0
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x8b, 0x41, 0x10])?; // flags
    assembler.instruction(&[0x41, 0x89, 0xc2])?;
    assembler.instruction(&[0x41, 0x83, 0xe2, 0x07])?;
    assembler.instruction(&[0x44, 0x39, 0xd0])?; // no unknown flags
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4c, 0x8b, 0x11])?; // next_start
    assembler.instruction(&[0x49, 0x39, 0xd2])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4c, 0x8b, 0x59, 0x08])?; // last_match_end
    assembler.instruction(&[0x49, 0x39, 0xd3])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0xa8, 0x02])?; // pending implies last and equality
    assembler.branch(&[0x0f, 0x84], no_pending)?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x4d, 0x39, 0xda])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.bind(no_pending)?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x85], has_last)?;
    assembler.instruction(&[0x4d, 0x85, 0xdb])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.branch(&[0xe9], validated)?;
    assembler.bind(has_last)?;
    assembler.instruction(&[0x4d, 0x39, 0xda])?; // next >= last
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.instruction(&[0xa8, 0x04])?;
    assembler.branch(&[0x0f, 0x84], validated)?;
    assembler.instruction(&[0xa8, 0x02])?; // finished cannot be pending
    assembler.branch(&[0x0f, 0x85], invalid)?;

    assembler.bind(validated)?;
    let ordered_gate_sites = ordered_nfa_gate
        .then(|| x86_emit_ordered_nfa_operation_gate(&mut assembler, false))
        .transpose()?;
    if let Some(runtime_bulk) = runtime_bulk {
        // The validated iterator start is authoritative. Hand the complete
        // refill to the runtime bulk helper before publishing `written` when
        // scanner-free V6 would reject the initial remaining window.
        assembler.instruction(&[0x48, 0x8b, 0x01])?;
        assembler.instruction(&[0x49, 0x89, 0xd2])?;
        assembler.instruction(&[0x49, 0x29, 0xc2])?;
        let mut maximum = vec![0x49, 0x81, 0xfa];
        maximum.extend_from_slice(
            &u32::try_from(FROZEN_SCANNER_FREE_DYNAMIC_ROWS_MAX_INPUT_BYTES)
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 bulk window ceiling"))?
                .to_le_bytes(),
        );
        assembler.instruction(&maximum)?;
        assembler.branch(&[0x0f, 0x87], runtime_bulk)?;
    }
    // Preserve the live arguments in callee-saved registers. Five pushes and
    // the 32-byte local frame leave RSP 16-byte aligned for every local call.
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // handle
    assembler.instruction(&[0x49, 0x89, 0xf4])?; // haystack
    assembler.instruction(&[0x49, 0x89, 0xd5])?; // length
    assembler.instruction(&[0x49, 0x89, 0xce])?; // state
    assembler.instruction(&[0x4d, 0x89, 0xc7])?; // output cursor
    assembler.instruction(&[0x4c, 0x89, 0x0c, 0x24])?; // capacity
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x60])?; // written
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x10, 0, 0, 0, 0])?;
    // Private two-word session: mode (uninitialized/frozen/fallback), tail.
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x20, 0, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x28, 0, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xc7, 0x00, 0, 0, 0, 0])?;
    assembler.instruction(&[0x4d, 0x85, 0xc9])?; // capacity != 0
    assembler.branch(&[0x0f, 0x85], loop_head)?;
    assembler.instruction(&[0x41, 0xf6, 0x46, 0x10, 0x04])?;
    assembler.branch(&[0x0f, 0x85], finished)?;
    assembler.branch(&[0xe9], full)?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x41, 0x8b, 0x46, 0x10])?;
    assembler.instruction(&[0xa8, 0x04])?;
    assembler.branch(&[0x0f, 0x85], finished)?;
    assembler.instruction(&[0xa8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], search)?;
    assembler.instruction(&[0x83, 0xe0, 0xfd])?; // clear pending
    assembler.instruction(&[0x41, 0x89, 0x46, 0x10])?;
    assembler.instruction(&[0x49, 0x8b, 0x0e])?;
    assembler.instruction(&[0x4c, 0x39, 0xe9])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x49, 0x83, 0x06, 0x01])?;

    assembler.bind(search)?;
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x4c, 0x89, 0xe6])?;
    assembler.instruction(&[0x4c, 0x89, 0xea])?;
    assembler.instruction(&[0x49, 0x8b, 0x0e])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4d, 0x89, 0xe8])?;
    assembler.instruction(&[0x4d, 0x89, 0xf9])?;
    assembler.instruction(&[0x4c, 0x8d, 0x54, 0x24, 0x20])?; // private session
    assembler.instruction(&[0xe8])?;
    let prepared_call = assembler.label()?;
    assembler.bind(prepared_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], terminal_error)?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4d, 0x8b, 0x17])?;
    assembler.instruction(&[0x4d, 0x8b, 0x5f, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x49, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x82], invalid_result)?;
    assembler.instruction(&[0x4d, 0x39, 0xd3])?;
    assembler.branch(&[0x0f, 0x82], invalid_result)?;
    assembler.instruction(&[0x4d, 0x39, 0xeb])?;
    assembler.branch(&[0x0f, 0x87], invalid_result)?;
    assembler.instruction(&[0x4d, 0x39, 0xda])?;
    assembler.branch(&[0x0f, 0x85], nonempty)?;
    assembler.instruction(&[0x41, 0x8b, 0x46, 0x10])?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], accepted)?;
    assembler.instruction(&[0x49, 0x8b, 0x4e, 0x08])?;
    assembler.instruction(&[0x4c, 0x39, 0xd9])?;
    assembler.branch(&[0x0f, 0x85], accepted)?;
    assembler.instruction(&[0x49, 0x8b, 0x0e])?;
    assembler.instruction(&[0x4c, 0x39, 0xe9])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x49, 0x83, 0x06, 0x01])?;
    assembler.branch(&[0xe9], search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    let publish = assembler.label()?;
    assembler.branch(&[0xe9], publish)?;
    assembler.bind(accepted)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(publish)?;
    assembler.instruction(&[0x4d, 0x89, 0x1e])?;
    assembler.instruction(&[0x4d, 0x89, 0x5e, 0x08])?;
    assembler.instruction(&[0x41, 0x89, 0x46, 0x10])?;
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x49, 0x83, 0xc2, 0x01])?;
    assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x08])?;
    assembler.instruction(&[0x4c, 0x89, 0x10])?;
    assembler.instruction(&[0x49, 0x83, 0xc7, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x04, 0x24])?;
    assembler.instruction(&[0x49, 0x39, 0xc2])?;
    assembler.branch(&[0x0f, 0x84], full)?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(full)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(finished)?;
    assembler.instruction(&[0x41, 0x8b, 0x46, 0x10])?;
    assembler.instruction(&[0x83, 0xe0, 0x01])?;
    assembler.instruction(&[0x83, 0xc8, 0x04])?;
    assembler.instruction(&[0x41, 0x89, 0x46, 0x10])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(invalid_result)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(terminal_error)?;
    assembler.instruction(&[0x41, 0x89, 0xc2])?;
    assembler.instruction(&[0x41, 0x8b, 0x46, 0x10])?;
    assembler.instruction(&[0x83, 0xe0, 0x01])?;
    assembler.instruction(&[0x83, 0xc8, 0x04])?;
    assembler.instruction(&[0x41, 0x89, 0x46, 0x10])?;
    assembler.instruction(&[0x44, 0x89, 0xd0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let mut bulk_runtime_fallback = None;
    if let Some(runtime_bulk) = runtime_bulk {
        assembler.bind(runtime_bulk)?;
        assembler.instruction(&[0xe9])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        bulk_runtime_fallback = Some(displacement);
    }

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativePreparedBulkWrapper {
        prepared_call_offset: finished.label_offset(prepared_call)?,
        ordered_nfa_gate_call_offset: ordered_gate_sites
            .map(|(call, _, _)| finished.label_offset(call))
            .transpose()?,
        bulk_runtime_fallback_offset: ordered_gate_sites
            .map(|(_, fallback, _)| finished.label_offset(fallback))
            .transpose()?
            .or(
                bulk_runtime_fallback
                    .map(|label| finished.label_offset(label))
                    .transpose()?,
            ),
        compatibility_identity_relocation: ordered_gate_sites
            .and_then(|(_, _, identity)| identity)
            .map(|offset| {
                finished
                    .label_offset(offset)
                    .map(NativePreparedIdentityRelocation::X86PcRelative32)
            })
            .transpose()?,
        identity_relocation: None,
        code: finished.code,
    })
}

/// Emit one transactional full-haystack Count or matched-byte SpanSum.
///
/// The generated leaf intentionally owns the iterator state, result slot, and,
/// when needed, a private prepared session for the complete reduction. Its only
/// call is an artifact-specific prepared target or self-contained ordinary Span
/// entry. The outer wrapper authenticates the complete immutable artifact
/// identity before that target can inspect source bytes.
#[allow(
    clippy::too_many_lines,
    reason = "raw ABI validation, exact nullable progress, and transactional scalar publication form one generated leaf"
)]
fn lower_x86_64_prepared_span_reduce(
    sink: PreparedSpanSink,
    call_kind: NativeSpanReducerCallKind,
    ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_x86_64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        call_kind,
        ordered_nfa_gate,
        None,
        false,
    )
}

#[allow(
    clippy::too_many_lines,
    reason = "authenticated one-shot terminal trim and exact nullable iteration form one generated leaf"
)]
fn lower_x86_64_prepared_span_reduce_with_terminal_exact_set(
    sink: PreparedSpanSink,
    call_kind: NativeSpanReducerCallKind,
    ordered_nfa_gate: bool,
    terminal_exact_set: Option<[u64; 4]>,
    required_ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 64;
    const OUTPUT_OFFSET: u8 = 16;
    const ACCUMULATOR_OFFSET: u8 = 24;
    const FLAGS_OFFSET: u8 = 32;
    const TERMINAL_END_OFFSET: u8 = 40;
    const SESSION_OFFSET: u8 = 48;

    if required_ordered_nfa_gate && !ordered_nfa_gate {
        return Err(ObjectError::InvalidModule(
            "required Ordered-NFA reducer gate was not selected",
        ));
    }
    if ordered_nfa_gate && call_kind != NativeSpanReducerCallKind::PreparedPrivate {
        return Err(ObjectError::InvalidModule(
            "Ordered-NFA reducer has no private prepared target",
        ));
    }
    if terminal_exact_set.is_some()
        && (!ordered_nfa_gate || call_kind != NativeSpanReducerCallKind::PreparedPrivate)
    {
        return Err(ObjectError::InvalidModule(
            "terminal exact-set aggregate trim has no Ordered-NFA private target",
        ));
    }
    if matches!(sink, PreparedSpanSink::Fill { .. }) {
        return Err(ObjectError::InvalidModule(
            "x86 prepared scalar reducer received the Fill sink",
        ));
    }
    let mut assembler = X86Assembler::new();
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted = assembler.label()?;
    let publish = assembler.label()?;
    let finished = assembler.label()?;
    let invalid_result = assembler.label()?;
    let terminal_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let wrong_identity = assembler.label()?;
    let terminal_scan = assembler.label()?;
    let terminal_word0 = assembler.label()?;
    let terminal_word1 = assembler.label()?;
    let terminal_word2 = assembler.label()?;
    let terminal_word3 = assembler.label()?;
    let terminal_member = assembler.label()?;

    // Validate the complete public boundary before entering generated code
    // that can authenticate and then access source bytes.
    assembler.instruction(&[0x48, 0x85, 0xff])?; // handle != null
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // haystack != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?; // length <= isize::MAX
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?; // output != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?; // output alignment
    assembler.branch(&[0x0f, 0x85], invalid)?;

    let ordered_gate_sites = (ordered_nfa_gate && !required_ordered_nfa_gate)
        .then(|| x86_emit_ordered_nfa_operation_gate(&mut assembler, true))
        .transpose()?;
    let required_gate_call = required_ordered_nfa_gate
        .then(|| x86_emit_required_ordered_nfa_operation_gate(&mut assembler))
        .transpose()?;

    // A private prepared target and a self-contained ordinary entry both rely
    // on this aggregate wrapper as their handle-authentication boundary.
    // Compare the immutable live header identity before any source access or
    // local call.
    assembler.instruction(&[0x48, 0x8d, 0x05])?; // lea identity(%rip), rax
    let identity_displacement = assembler.label()?;
    assembler.bind(identity_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 prepared aggregate identity word",
            ))?;
        if word_offset == 0 {
            assembler.instruction(&[0x4c, 0x8b, 0x10])?; // mov [rax], r10
        } else {
            assembler.instruction(&[
                0x4c,
                0x8b,
                0x50,
                u8::try_from(word_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "x86 prepared aggregate linked identity offset",
                    )
                })?,
            ])?;
        }
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 prepared aggregate header identity offset",
            ))?;
        assembler.instruction(&[
            0x4c,
            0x3b,
            0x57,
            u8::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "x86 prepared aggregate header identity displacement",
                )
            })?,
        ])?;
        assembler.branch(&[0x0f, 0x85], wrong_identity)?;
    }

    // Five pushes plus a 64-byte frame preserve 16-byte call alignment.
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // handle
    assembler.instruction(&[0x49, 0x89, 0xf4])?; // haystack
    assembler.instruction(&[0x49, 0x89, 0xd5])?; // length
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, OUTPUT_OFFSET])?;
    assembler.instruction(&[0x4d, 0x31, 0xf6])?; // next_start = 0
    assembler.instruction(&[0x4d, 0x31, 0xff])?; // last_match_end = 0
    assembler.instruction(&[
        0x48,
        0xc7,
        0x44,
        0x24,
        ACCUMULATOR_OFFSET,
        0,
        0,
        0,
        0,
    ])?;
    assembler.instruction(&[0xc7, 0x44, 0x24, FLAGS_OFFSET, 0, 0, 0, 0])?;
    if call_kind == NativeSpanReducerCallKind::PreparedPrivate {
        assembler.instruction(&[
            0x48,
            0xc7,
            0x44,
            0x24,
            SESSION_OFFSET,
            0,
            0,
            0,
            0,
        ])?;
        assembler.instruction(&[
            0x48,
            0xc7,
            0x44,
            0x24,
            SESSION_OFFSET + 8,
            0,
            0,
            0,
            0,
        ])?;
    }

    if let Some(bitmap_words) = terminal_exact_set {
        // The exhaustive reducer pays for one full reverse scan, once. The
        // ordinary/private search keeps the original full length in R13 for
        // assertion context while every iterator window ends at this E.
        assembler.instruction(&[0x4c, 0x89, 0x6c, 0x24, TERMINAL_END_OFFSET])?; // E = H
        assembler.instruction(&[0x4c, 0x89, 0xe9])?; // scan cursor = H
        assembler.bind(terminal_scan)?;
        assembler.instruction(&[0x48, 0x85, 0xc9])?;
        assembler.branch(&[0x0f, 0x84], finished)?;
        assembler.instruction(&[0x48, 0x83, 0xe9, 0x01])?;
        assembler.instruction(&[0x41, 0x0f, 0xb6, 0x04, 0x0c])?; // haystack[cursor]
        assembler.instruction(&[0x83, 0xf8, 0x40])?;
        assembler.branch(&[0x0f, 0x82], terminal_word0)?;
        assembler.instruction(&[0x3d, 0x80, 0, 0, 0])?;
        assembler.branch(&[0x0f, 0x82], terminal_word1)?;
        assembler.instruction(&[0x3d, 0xc0, 0, 0, 0])?;
        assembler.branch(&[0x0f, 0x82], terminal_word2)?;
        assembler.branch(&[0xe9], terminal_word3)?;
        for (label, word) in [
            terminal_word0,
            terminal_word1,
            terminal_word2,
            terminal_word3,
        ]
        .into_iter()
        .zip(bitmap_words)
        {
            assembler.bind(label)?;
            let mut load_word = vec![0x49, 0xba]; // movabs word, r10
            load_word.extend_from_slice(&word.to_le_bytes());
            assembler.instruction(&load_word)?;
            assembler.branch(&[0xe9], terminal_member)?;
        }
        assembler.bind(terminal_member)?;
        assembler.instruction(&[0x49, 0x0f, 0xa3, 0xc2])?; // bt rax, r10
        assembler.branch(&[0x0f, 0x83], terminal_scan)?; // member bit clear
        assembler.instruction(&[0x48, 0x83, 0xc1, 0x01])?;
        assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, TERMINAL_END_OFFSET])?; // E = last member + 1
    }

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, FLAGS_OFFSET])?;
    assembler.instruction(&[0xa8, 0x02])?; // pending empty progress
    assembler.branch(&[0x0f, 0x84], search)?;
    assembler.instruction(&[0x83, 0xe0, 0xfd])?;
    assembler.instruction(&[0x89, 0x44, 0x24, FLAGS_OFFSET])?;
    if terminal_exact_set.is_some() {
        assembler.instruction(&[0x4c, 0x3b, 0x74, 0x24, TERMINAL_END_OFFSET])?; // next_start == E
    } else {
        assembler.instruction(&[0x4d, 0x39, 0xee])?; // next_start == length
    }
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;

    assembler.bind(search)?;
    match call_kind {
        NativeSpanReducerCallKind::PreparedPrivate => {
            assembler.instruction(&[0x48, 0x89, 0xdf])?;
            assembler.instruction(&[0x4c, 0x89, 0xe6])?;
            assembler.instruction(&[0x4c, 0x89, 0xea])?;
            assembler.instruction(&[0x4c, 0x89, 0xf1])?;
            if terminal_exact_set.is_some() {
                assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, TERMINAL_END_OFFSET])?; // window end = E
            } else {
                assembler.instruction(&[0x4d, 0x89, 0xe8])?;
            }
            assembler.instruction(&[0x4c, 0x8d, 0x0c, 0x24])?; // private result
            assembler.instruction(&[0x4c, 0x8d, 0x54, 0x24, SESSION_OFFSET])?;
        }
        NativeSpanReducerCallKind::DirectOrdinary => {
            assembler.instruction(&[0x4c, 0x89, 0xe7])?; // haystack
            assembler.instruction(&[0x4c, 0x89, 0xee])?; // length
            assembler.instruction(&[0x4c, 0x89, 0xf2])?; // window start
            assembler.instruction(&[0x4c, 0x89, 0xe9])?; // window end
            assembler.instruction(&[0x4c, 0x8d, 0x04, 0x24])?; // private result
        }
    }
    assembler.instruction(&[0xe8])?;
    let prepared_call = assembler.label()?;
    assembler.bind(prepared_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], terminal_error)?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4c, 0x8b, 0x04, 0x24])?; // start
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x08])?; // end
    assembler.instruction(&[0x4d, 0x39, 0xf0])?; // start >= requested start
    assembler.branch(&[0x0f, 0x82], invalid_result)?;
    assembler.instruction(&[0x4d, 0x39, 0xc1])?; // end >= start
    assembler.branch(&[0x0f, 0x82], invalid_result)?;
    if terminal_exact_set.is_some() {
        assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, TERMINAL_END_OFFSET])?;
        assembler.instruction(&[0x4d, 0x39, 0xd1])?; // end <= E
    } else {
        assembler.instruction(&[0x4d, 0x39, 0xe9])?; // end <= length
    }
    assembler.branch(&[0x0f, 0x87], invalid_result)?;
    assembler.instruction(&[0x4d, 0x39, 0xc8])?;
    assembler.branch(&[0x0f, 0x85], nonempty)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, FLAGS_OFFSET])?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], accepted)?;
    assembler.instruction(&[0x4d, 0x39, 0xcf])?; // last end != end
    assembler.branch(&[0x0f, 0x85], accepted)?;
    if terminal_exact_set.is_some() {
        assembler.instruction(&[0x4c, 0x3b, 0x74, 0x24, TERMINAL_END_OFFSET])?;
    } else {
        assembler.instruction(&[0x4d, 0x39, 0xee])?;
    }
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;
    assembler.branch(&[0xe9], search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.branch(&[0xe9], publish)?;
    assembler.bind(accepted)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(publish)?;
    assembler.instruction(&[0x4d, 0x89, 0xce])?; // next_start = end
    assembler.instruction(&[0x4d, 0x89, 0xcf])?; // last_match_end = end
    assembler.instruction(&[0x89, 0x44, 0x24, FLAGS_OFFSET])?;
    match sink {
        PreparedSpanSink::Count => {
            assembler.instruction(&[
                0x48,
                0x83,
                0x44,
                0x24,
                ACCUMULATOR_OFFSET,
                0x01,
            ])?;
        }
        PreparedSpanSink::SpanSum => {
            assembler.instruction(&[0x4d, 0x89, 0xca])?; // width = end
            assembler.instruction(&[0x4d, 0x29, 0xc2])?; // width -= start
            assembler.instruction(&[
                0x4c,
                0x01,
                0x54,
                0x24,
                ACCUMULATOR_OFFSET,
            ])?;
        }
        PreparedSpanSink::Fill { .. } => unreachable!(),
    }
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, ACCUMULATOR_OFFSET])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, OUTPUT_OFFSET])?;
    assembler.instruction(&[0x48, 0x89, 0x01])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(invalid_result)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(terminal_error)?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(wrong_identity)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativePreparedBulkWrapper {
        prepared_call_offset: finished.label_offset(prepared_call)?,
        ordered_nfa_gate_call_offset: ordered_gate_sites
            .map(|(call, _, _)| finished.label_offset(call))
            .transpose()?
            .or(required_gate_call
                .map(|call| finished.label_offset(call))
                .transpose()?),
        bulk_runtime_fallback_offset: ordered_gate_sites
            .map(|(_, fallback, _)| finished.label_offset(fallback))
            .transpose()?,
        compatibility_identity_relocation: ordered_gate_sites
            .and_then(|(_, _, identity)| identity)
            .map(|offset| {
                finished
                    .label_offset(offset)
                    .map(NativePreparedIdentityRelocation::X86PcRelative32)
            })
            .transpose()?,
        identity_relocation: Some(NativePreparedIdentityRelocation::X86PcRelative32(
            finished.label_offset(identity_displacement)?,
        )),
        code: finished.code,
    })
}

fn lower_x86_64_ordered_nfa_span_reduce(
    sink: PreparedSpanSink,
    terminal_exact_set: Option<[u64; 4]>,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_x86_64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        NativeSpanReducerCallKind::PreparedPrivate,
        true,
        terminal_exact_set,
        false,
    )
}

fn lower_x86_64_required_ordered_nfa_span_reduce(
    sink: PreparedSpanSink,
    terminal_exact_set: Option<[u64; 4]>,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_x86_64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        NativeSpanReducerCallKind::PreparedPrivate,
        true,
        terminal_exact_set,
        true,
    )
}

/// Emit one transactional LF/CRLF line-domain Count. Each logical line is
/// presented to the local search as an independent 0..line_len haystack so
/// anchors and empty matches have exactly `ByteSlice::lines` semantics. The
/// private V15 session is cleared for every distinct line owner.
#[allow(
    clippy::too_many_lines,
    reason = "raw validation, line splitting, local calls, and scalar publication are one native leaf"
)]
fn lower_x86_64_prepared_grep_count(
    call_kind: NativeSpanReducerCallKind,
    required_ordered_nfa: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 48;
    const SESSION_OFFSET: u8 = 16;
    const COUNT_OFFSET: u8 = 32;
    const LINE_START_OFFSET: u8 = 40;

    if required_ordered_nfa && call_kind != NativeSpanReducerCallKind::PreparedPrivate {
        return Err(ObjectError::InvalidModule(
            "required Ordered-NFA GrepCount has no private prepared target",
        ));
    }
    let mut assembler = X86Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let completed_line = assembler.label()?;
    let matched_line = assembler.label()?;
    let finished = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let wrong_identity = assembler.label()?;

    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;

    let ordered_gate_call = required_ordered_nfa
        .then(|| x86_emit_required_ordered_nfa_operation_gate(&mut assembler))
        .transpose()?;

    assembler.instruction(&[0x48, 0x8d, 0x05])?;
    let identity_displacement = assembler.label()?;
    assembler.bind(identity_displacement)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 native GrepCount identity word",
            ))?;
        if word_offset == 0 {
            assembler.instruction(&[0x4c, 0x8b, 0x10])?;
        } else {
            assembler.instruction(&[
                0x4c,
                0x8b,
                0x50,
                u8::try_from(word_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "x86 native GrepCount linked identity offset",
                    )
                })?,
            ])?;
        }
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "x86 native GrepCount header identity offset",
            ))?;
        assembler.instruction(&[
            0x4c,
            0x3b,
            0x57,
            u8::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "x86 native GrepCount header identity displacement",
                )
            })?,
        ])?;
        assembler.branch(&[0x0f, 0x85], wrong_identity)?;
    }

    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // handle
    assembler.instruction(&[0x49, 0x89, 0xf4])?; // base
    assembler.instruction(&[0x49, 0x89, 0xd5])?; // length
    assembler.instruction(&[0x49, 0x89, 0xcf])?; // output
    assembler.instruction(&[0x4d, 0x31, 0xf6])?; // cursor
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, COUNT_OFFSET, 0, 0, 0, 0])?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.branch(&[0x0f, 0x84], finished)?;

    assembler.bind(line_loop)?;
    assembler.instruction(&[0x4c, 0x89, 0x74, 0x24, LINE_START_OFFSET])?;
    assembler.bind(scan)?;
    assembler.instruction(&[0x4d, 0x39, 0xee])?;
    assembler.branch(&[0x0f, 0x84], final_line)?;
    assembler.instruction(&[0x43, 0x80, 0x3c, 0x34, 0x0a])?;
    assembler.branch(&[0x0f, 0x84], found_lf)?;
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;
    assembler.branch(&[0xe9], scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(&[0x4d, 0x89, 0xf2])?; // line end before LF
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?; // next line start
    assembler.instruction(&[0x4c, 0x8b, 0x5c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x4d, 0x39, 0xda])?;
    assembler.branch(&[0x0f, 0x84], line_ready)?;
    assembler.instruction(&[0x43, 0x80, 0x7c, 0x14, 0xff, 0x0d])?;
    assembler.branch(&[0x0f, 0x85], line_ready)?;
    assembler.instruction(&[0x49, 0x83, 0xea, 0x01])?; // strip CR before LF
    assembler.branch(&[0xe9], line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(&[0x4d, 0x89, 0xf2])?;

    assembler.bind(line_ready)?;
    assembler.instruction(&[0x4c, 0x8b, 0x5c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x4d, 0x29, 0xda])?; // line length

    if call_kind == NativeSpanReducerCallKind::PreparedPrivate {
        assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, SESSION_OFFSET, 0, 0, 0, 0])?;
        assembler.instruction(&[
            0x48,
            0xc7,
            0x44,
            0x24,
            SESSION_OFFSET + 8,
            0,
            0,
            0,
            0,
        ])?;
        assembler.instruction(&[0x48, 0x89, 0xdf])?;
        assembler.instruction(&[0x4b, 0x8d, 0x34, 0x1c])?;
        assembler.instruction(&[0x4c, 0x89, 0xd2])?;
        assembler.instruction(&[0x31, 0xc9])?;
        assembler.instruction(&[0x4d, 0x89, 0xd0])?;
        assembler.instruction(&[0x4c, 0x8d, 0x0c, 0x24])?;
        assembler.instruction(&[0x4c, 0x8d, 0x54, 0x24, SESSION_OFFSET])?;
    } else {
        assembler.instruction(&[0x4b, 0x8d, 0x3c, 0x1c])?;
        assembler.instruction(&[0x4c, 0x89, 0xd6])?;
        assembler.instruction(&[0x31, 0xd2])?;
        assembler.instruction(&[0x4c, 0x89, 0xd1])?;
        assembler.instruction(&[0x4c, 0x8d, 0x04, 0x24])?;
    }
    assembler.instruction(&[0xe8])?;
    let prepared_call = assembler.label()?;
    assembler.bind(prepared_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], matched_line)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], completed_line)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(matched_line)?;
    assembler.instruction(&[0x48, 0x83, 0x44, 0x24, COUNT_OFFSET, 0x01])?;
    assembler.branch(&[0x0f, 0x82], overflow)?;
    assembler.bind(completed_line)?;
    assembler.instruction(&[0x4d, 0x39, 0xee])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.branch(&[0xe9], line_loop)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, COUNT_OFFSET])?;
    assembler.instruction(&[0x49, 0x89, 0x07])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(wrong_identity)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let prepared_call_offset = finished.label_offset(prepared_call)?;
    let ordered_nfa_gate_call_offset = ordered_gate_call
        .map(|call| finished.label_offset(call))
        .transpose()?;
    let identity_relocation = NativePreparedIdentityRelocation::X86PcRelative32(
        finished.label_offset(identity_displacement)?,
    );
    Ok(NativePreparedBulkWrapper {
        code: finished.code,
        prepared_call_offset,
        ordered_nfa_gate_call_offset,
        bulk_runtime_fallback_offset: None,
        compatibility_identity_relocation: None,
        identity_relocation: Some(identity_relocation),
    })
}

fn x86_native_capture_reducer_boundary(
    assembler: &mut X86Assembler,
    caller_scratch_bytes: usize,
    invalid: X86Label,
) -> Result<(), ObjectError> {
    assembler.instruction(&[0x48, 0x85, 0xff])?; // haystack
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // signed-domain length
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x89, 0xf8])?;
    assembler.instruction(&[0x48, 0x01, 0xf0])?; // complete haystack extent
    assembler.branch(&[0x0f, 0x82], invalid)?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(&[0x48, 0x85, 0xd2])?; // scalar output
        assembler.branch(&[0x0f, 0x84], invalid)?;
        assembler.instruction(&[0xf6, 0xc2, 0x07])?;
        assembler.branch(&[0x0f, 0x85], invalid)?;
        assembler.instruction(&[0x48, 0x89, 0xd0])?;
        assembler.instruction(&[0x48, 0x83, 0xc0, 8])?; // complete output extent
        assembler.branch(&[0x0f, 0x82], invalid)?;
        return Ok(());
    }

    assembler.instruction(&[0x49, 0x89, 0xc1])?; // retained haystack end
    assembler.instruction(&[0x48, 0x85, 0xd2])?; // caller scratch
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc2, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut exact_scratch = vec![0x48, 0xb8];
    exact_scratch.extend_from_slice(
        &u64::try_from(caller_scratch_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("capture reducer scratch"))?
            .to_le_bytes(),
    );
    assembler.instruction(&exact_scratch)?;
    assembler.instruction(&[0x48, 0x39, 0xc1])?; // exact scratch extent
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x89, 0xd0])?;
    assembler.instruction(&[0x48, 0x01, 0xc8])?; // complete scratch extent
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.instruction(&[0x49, 0x89, 0xc2])?; // retained scratch end
    let scratch_haystack_disjoint = assembler.label()?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x84], scratch_haystack_disjoint)?;
    assembler.instruction(&[0x4c, 0x39, 0xca])?;
    assembler.branch(&[0x0f, 0x83], scratch_haystack_disjoint)?;
    assembler.instruction(&[0x4c, 0x39, 0xd7])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_haystack_disjoint)?;
    let scratch_output_disjoint = assembler.label()?;
    assembler.instruction(&[0x4d, 0x8d, 0x58, 8])?;
    assembler.instruction(&[0x4c, 0x39, 0xda])?;
    assembler.branch(&[0x0f, 0x83], scratch_output_disjoint)?;
    assembler.instruction(&[0x4d, 0x39, 0xd0])?;
    assembler.branch(&[0x0f, 0x82], invalid)?;
    assembler.bind(scratch_output_disjoint)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?; // scalar output
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x4c, 0x89, 0xc0])?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 8])?; // complete output extent
    assembler.branch(&[0x0f, 0x82], invalid)?;
    Ok(())
}

fn x86_native_capture_reducer_epilogue(
    assembler: &mut X86Assembler,
    frame_bytes: u32,
) -> Result<(), ObjectError> {
    let mut release = vec![0x48, 0x81, 0xc4];
    release.extend_from_slice(&frame_bytes.to_le_bytes());
    assembler.instruction(&release)?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0x5d])?;
    assembler.instruction(&[0xc3])?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "exact selector progress, private replay request, and transactional reduction form one auditable native closure"
)]
fn lower_x86_64_native_participation_reducer_domain_v1(
    group_count: usize,
    participation_scratch_bytes: usize,
    caller_scratch_bytes: usize,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    const FRAME_BYTES: u32 = 120;
    const SPAN_OFFSET: u8 = 0;
    const REQUEST_OFFSET: u8 = 16;
    const SCRATCH_OFFSET: u8 = 80;
    const COUNT_OFFSET: u8 = 96;
    const FLAGS_OFFSET: u8 = 112;
    if !(1..=64).contains(&group_count)
        || participation_scratch_bytes == 0
        || (caller_scratch_bytes == 0
            && participation_scratch_bytes
                != crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
        || (caller_scratch_bytes != 0
            && caller_scratch_bytes != participation_scratch_bytes)
    {
        return Err(ObjectError::InvalidModule(
            "participation reducer group cardinality",
        ));
    }
    let group_count = u32::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("participation reducer groups"))?;
    let mut assembler = X86Assembler::new();
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted_empty = assembler.label()?;
    let accepted = assembler.label()?;
    let participation_matched = assembler.label()?;
    let finished = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    x86_native_capture_reducer_boundary(&mut assembler, caller_scratch_bytes, invalid)?;
    assembler.instruction(&[0x55])?;
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    let mut reserve = vec![0x48, 0x81, 0xec];
    reserve.extend_from_slice(&FRAME_BYTES.to_le_bytes());
    assembler.instruction(&reserve)?;
    assembler.instruction(&[0x49, 0x89, 0xfc])?; // haystack
    assembler.instruction(&[0x49, 0x89, 0xf5])?; // length
    if caller_scratch_bytes == 0 {
        assembler.instruction(&[0x49, 0x89, 0xd6])?; // output
    } else {
        assembler.instruction(&[0x4d, 0x89, 0xc6])?; // output
        assembler.instruction(&[0x48, 0x89, 0x54, 0x24, SCRATCH_OFFSET])?;
        assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, SCRATCH_OFFSET + 8])?;
    }
    assembler.instruction(&[0x4d, 0x31, 0xff])?; // total
    assembler.instruction(&[0x48, 0x31, 0xdb])?; // next start
    assembler.instruction(&[0x48, 0x31, 0xed])?; // last end
    assembler.instruction(&[0xc7, 0x44, 0x24, FLAGS_OFFSET, 0, 0, 0, 0])?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, FLAGS_OFFSET])?;
    assembler.instruction(&[0xa8, 0x02])?;
    assembler.branch(&[0x0f, 0x84], search)?;
    assembler.instruction(&[0x83, 0xe0, 0xfd])?;
    assembler.instruction(&[0x89, 0x44, 0x24, FLAGS_OFFSET])?;
    assembler.instruction(&[0x4c, 0x39, 0xeb])?; // next == length
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x48, 0x83, 0xc3, 1])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;

    assembler.bind(search)?;
    assembler.instruction(&[0x4c, 0x89, 0xe7])?;
    assembler.instruction(&[0x4c, 0x89, 0xee])?;
    assembler.instruction(&[0x48, 0x89, 0xda])?;
    assembler.instruction(&[0x4c, 0x89, 0xe9])?;
    assembler.instruction(&[0x4c, 0x8d, 0x44, 0x24, SPAN_OFFSET])?;
    assembler.instruction(&[0xe8])?;
    let selector_call = assembler.label()?;
    assembler.bind(selector_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 1])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, SPAN_OFFSET])?; // start
    assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, SPAN_OFFSET + 8])?; // end
    assembler.instruction(&[0x49, 0x39, 0xd9])?; // start >= next
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.instruction(&[0x4d, 0x39, 0xca])?; // end >= start
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.instruction(&[0x4d, 0x39, 0xea])?; // end <= length
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x4d, 0x39, 0xd1])?;
    assembler.branch(&[0x0f, 0x85], nonempty)?;
    assembler.instruction(&[0x8b, 0x44, 0x24, FLAGS_OFFSET])?;
    assembler.instruction(&[0xa8, 0x01])?;
    assembler.branch(&[0x0f, 0x84], accepted_empty)?;
    assembler.instruction(&[0x49, 0x39, 0xea])?; // end != last
    assembler.branch(&[0x0f, 0x85], accepted_empty)?;
    assembler.instruction(&[0x4c, 0x39, 0xeb])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x48, 0x83, 0xc3, 1])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.branch(&[0xe9], search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(&[0xb8, 1, 0, 0, 0])?;
    assembler.branch(&[0xe9], accepted)?;
    assembler.bind(accepted_empty)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(accepted)?;
    assembler.instruction(&[0x4c, 0x89, 0xd3])?; // next = end
    assembler.instruction(&[0x4c, 0x89, 0xd5])?; // last = end
    assembler.instruction(&[0x89, 0x44, 0x24, FLAGS_OFFSET])?;

    assembler.instruction(&[0x48, 0x8d, 0x05])?; // bundle(%rip)
    let bundle_relocation = assembler.label()?;
    assembler.bind(bundle_relocation)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, REQUEST_OFFSET])?;
    assembler.instruction(&[0x4c, 0x89, 0x64, 0x24, REQUEST_OFFSET + 8])?;
    assembler.instruction(&[0x4c, 0x89, 0x6c, 0x24, REQUEST_OFFSET + 16])?;
    assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, REQUEST_OFFSET + 24])?;
    assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, REQUEST_OFFSET + 32])?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(&[0x48, 0x8d, 0x44, 0x24, SCRATCH_OFFSET])?;
        assembler.instruction(&[0x48, 0x89, 0x44, 0x24, REQUEST_OFFSET + 40])?;
        let mut exact_scratch = vec![
            0x48,
            0xc7,
            0x44,
            0x24,
            REQUEST_OFFSET + 48,
        ];
        exact_scratch.extend_from_slice(
            &u32::try_from(participation_scratch_bytes)
                .map_err(|_| {
                    ObjectError::ArithmeticOverflow("participation reducer scratch")
                })?
                .to_le_bytes(),
        );
        assembler.instruction(&exact_scratch)?;
    } else {
        assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, SCRATCH_OFFSET])?;
        assembler.instruction(&[0x48, 0x89, 0x44, 0x24, REQUEST_OFFSET + 40])?;
        assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, SCRATCH_OFFSET + 8])?;
        assembler.instruction(&[0x48, 0x89, 0x44, 0x24, REQUEST_OFFSET + 48])?;
    }
    assembler.instruction(&[0x48, 0x8d, 0x44, 0x24, COUNT_OFFSET])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, REQUEST_OFFSET + 56])?;
    assembler.instruction(&[0x48, 0x8d, 0x7c, 0x24, REQUEST_OFFSET])?;
    assembler.instruction(&[0xe8])?;
    let participation_call = assembler.label()?;
    assembler.bind(participation_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x83, 0xf8, 1])?;
    assembler.branch(&[0x0f, 0x84], participation_matched)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(participation_matched)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, COUNT_OFFSET])?;
    assembler.instruction(&[0x48, 0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    let mut group_bound = vec![0x48, 0x3d];
    group_bound.extend_from_slice(&group_count.to_le_bytes());
    assembler.instruction(&group_bound)?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x49, 0x01, 0xc7])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x4d, 0x89, 0x3e])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(returned)?;
    x86_native_capture_reducer_epilogue(&mut assembler, FRAME_BYTES)?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let selector_call = finished.label_offset(selector_call)?;
    let participation_call = finished.label_offset(participation_call)?;
    let bundle_relocation = finished.label_offset(bundle_relocation)?;
    Ok(NativeCaptureReducerLoweringV1 {
        code: finished.code,
        local_calls: vec![
            (
                selector_call,
                NativeCaptureReducerCallTargetV1::Selector,
            ),
            (
                participation_call,
                NativeCaptureReducerCallTargetV1::Participation,
            ),
        ]
        .into_boxed_slice(),
        bundle_relocations: vec![(
            bundle_relocation,
            RelocationKind::X86PcRelative32,
            -4,
        )]
        .into_boxed_slice(),
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "private iterator state, exact capture schema validation, and transactional reduction form one generated native closure"
)]
fn lower_x86_64_native_capture_next_reducer_domain_v1(
    group_count: usize,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    const STATE_BYTES: usize = 24;
    if !(1..=16).contains(&group_count) {
        return Err(ObjectError::InvalidModule(
            "capture-next reducer group cardinality",
        ));
    }
    let slots_bytes = group_count
        .checked_mul(16)
        .ok_or(ObjectError::ArithmeticOverflow("capture reducer slots"))?;
    let frame_bytes = STATE_BYTES
        .checked_add(slots_bytes)
        .and_then(|bytes| u32::try_from(bytes).ok())
        .filter(|bytes| bytes % 16 == 8)
        .ok_or(ObjectError::ArithmeticOverflow("capture reducer frame"))?;
    let group_count_u32 = u32::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("capture reducer groups"))?;
    let mut assembler = X86Assembler::new();
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let finished = assembler.label()?;
    let invalid = assembler.label()?;

    x86_native_capture_reducer_boundary(&mut assembler, 0, invalid)?;
    assembler.instruction(&[0x55])?;
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    let mut reserve = vec![0x48, 0x81, 0xec];
    reserve.extend_from_slice(&frame_bytes.to_le_bytes());
    assembler.instruction(&reserve)?;
    assembler.instruction(&[0x49, 0x89, 0xfc])?;
    assembler.instruction(&[0x49, 0x89, 0xf5])?;
    assembler.instruction(&[0x49, 0x89, 0xd6])?;
    assembler.instruction(&[0x4d, 0x31, 0xff])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x48, 0x89, 0x04, 0x24])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 8])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 16])?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x4c, 0x89, 0xe7])?;
    assembler.instruction(&[0x4c, 0x89, 0xee])?;
    assembler.instruction(&[0x48, 0x89, 0xe2])?;
    assembler.instruction(&[0x48, 0x8d, 0x4c, 0x24, STATE_BYTES as u8])?;
    let mut exact_count = vec![0x41, 0xb8];
    exact_count.extend_from_slice(&group_count_u32.to_le_bytes());
    assembler.instruction(&exact_count)?;
    assembler.instruction(&[0xe8])?;
    let capture_next_call = assembler.label()?;
    assembler.bind(capture_next_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.instruction(&[0x83, 0xf8, 1])?;
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(matched)?;
    x86_capture_load_rsp_rax(&mut assembler, STATE_BYTES)?;
    x86_capture_load_rsp_rdi(&mut assembler, STATE_BYTES + 8)?;
    assembler.instruction(&[0x48, 0x83, 0xf8, 0xff])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.instruction(&[0x48, 0x83, 0xff, 0xff])?;
    assembler.branch(&[0x0f, 0x84], runtime_failure)?;
    assembler.instruction(&[0x48, 0x39, 0xf8])?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0x4c, 0x39, 0xef])?;
    assembler.branch(&[0x0f, 0x87], runtime_failure)?;
    assembler.instruction(&[0xbb, 1, 0, 0, 0])?;
    for group in 1..group_count {
        let valid = assembler.label()?;
        let unset = assembler.label()?;
        x86_capture_load_rsp_rax(&mut assembler, STATE_BYTES + group * 16)?;
        x86_capture_load_rsp_rdi(&mut assembler, STATE_BYTES + group * 16 + 8)?;
        assembler.instruction(&[0x48, 0x83, 0xf8, 0xff])?;
        assembler.branch(&[0x0f, 0x84], unset)?;
        assembler.instruction(&[0x48, 0x83, 0xff, 0xff])?;
        assembler.branch(&[0x0f, 0x84], runtime_failure)?;
        assembler.instruction(&[0x48, 0x39, 0xf8])?;
        assembler.branch(&[0x0f, 0x87], runtime_failure)?;
        assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, STATE_BYTES as u8])?;
        assembler.instruction(&[0x4c, 0x39, 0xc0])?;
        assembler.branch(&[0x0f, 0x82], runtime_failure)?;
        assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, (STATE_BYTES + 8) as u8])?;
        assembler.instruction(&[0x4c, 0x39, 0xc7])?;
        assembler.branch(&[0x0f, 0x87], runtime_failure)?;
        assembler.instruction(&[0x48, 0x83, 0xc3, 1])?;
        assembler.branch(&[0x0f, 0x82], runtime_failure)?;
        assembler.branch(&[0xe9], valid)?;
        assembler.bind(unset)?;
        assembler.instruction(&[0x48, 0x83, 0xff, 0xff])?;
        assembler.branch(&[0x0f, 0x85], runtime_failure)?;
        assembler.bind(valid)?;
    }
    assembler.instruction(&[0x49, 0x01, 0xdf])?;
    assembler.branch(&[0x0f, 0x82], runtime_failure)?;
    assembler.branch(&[0xe9], loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x4d, 0x89, 0x3e])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(returned)?;
    x86_native_capture_reducer_epilogue(&mut assembler, frame_bytes)?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let capture_next_call = finished.label_offset(capture_next_call)?;
    Ok(NativeCaptureReducerLoweringV1 {
        code: finished.code,
        local_calls: vec![(
            capture_next_call,
            NativeCaptureReducerCallTargetV1::CaptureNext,
        )]
        .into_boxed_slice(),
        bundle_relocations: Box::new([]),
    })
}

fn lower_x86_64_native_capture_grep_wrapper_v1(
    caller_scratch_bytes: usize,
) -> Result<(Vec<u8>, usize), ObjectError> {
    const LINE_START_OFFSET: u8 = 8;
    const SCRATCH_OFFSET: u8 = 16;
    let frame_bytes = if caller_scratch_bytes == 0 { 16 } else { 32 };
    let mut assembler = X86Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let finished = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    x86_native_capture_reducer_boundary(&mut assembler, caller_scratch_bytes, invalid)?;
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, frame_bytes])?;
    assembler.instruction(&[0x49, 0x89, 0xfc])?;
    assembler.instruction(&[0x49, 0x89, 0xf5])?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(&[0x49, 0x89, 0xd6])?;
    } else {
        assembler.instruction(&[0x4d, 0x89, 0xc6])?;
        assembler.instruction(&[0x48, 0x89, 0x54, 0x24, SCRATCH_OFFSET])?;
        assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, SCRATCH_OFFSET + 8])?;
    }
    assembler.instruction(&[0x4d, 0x31, 0xff])?;
    assembler.instruction(&[0x48, 0x31, 0xdb])?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.branch(&[0x0f, 0x84], finished)?;

    assembler.bind(line_loop)?;
    assembler.instruction(&[0x48, 0x89, 0x5c, 0x24, LINE_START_OFFSET])?;
    assembler.bind(scan)?;
    assembler.instruction(&[0x4c, 0x39, 0xeb])?;
    assembler.branch(&[0x0f, 0x84], final_line)?;
    assembler.instruction(&[0x43, 0x80, 0x3c, 0x1c, 0x0a])?;
    assembler.branch(&[0x0f, 0x84], found_lf)?;
    assembler.instruction(&[0x48, 0x83, 0xc3, 1])?;
    assembler.branch(&[0x0f, 0x82], overflow)?;
    assembler.branch(&[0xe9], scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(&[0x49, 0x89, 0xdb])?; // line end
    assembler.instruction(&[0x48, 0x83, 0xc3, 1])?;
    assembler.branch(&[0x0f, 0x82], overflow)?;
    assembler.instruction(&[0x48, 0x8b, 0x6c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x49, 0x39, 0xeb])?;
    assembler.branch(&[0x0f, 0x84], line_ready)?;
    assembler.instruction(&[0x43, 0x80, 0x7c, 0x1c, 0xff, 0x0d])?;
    assembler.branch(&[0x0f, 0x85], line_ready)?;
    assembler.instruction(&[0x49, 0x83, 0xeb, 1])?;
    assembler.branch(&[0xe9], line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(&[0x49, 0x89, 0xdb])?;
    assembler.bind(line_ready)?;
    assembler.instruction(&[0x48, 0x8b, 0x6c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x49, 0x29, 0xeb])?; // line length
    assembler.instruction(&[0x49, 0x8d, 0x3c, 0x2c])?;
    assembler.instruction(&[0x4c, 0x89, 0xde])?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(&[0x48, 0x8d, 0x14, 0x24])?;
    } else {
        assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, SCRATCH_OFFSET])?;
        assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, SCRATCH_OFFSET + 8])?;
        assembler.instruction(&[0x4c, 0x8d, 0x04, 0x24])?;
    }
    assembler.instruction(&[0xe8])?;
    let private_call = assembler.label()?;
    assembler.bind(private_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], returned)?;
    assembler.instruction(&[0x4c, 0x03, 0x3c, 0x24])?;
    assembler.branch(&[0x0f, 0x82], overflow)?;
    assembler.instruction(&[0x4c, 0x39, 0xeb])?;
    assembler.branch(&[0x0f, 0x84], finished)?;
    assembler.branch(&[0xe9], line_loop)?;

    assembler.bind(finished)?;
    assembler.instruction(&[0x4d, 0x89, 0x3e])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(&[0xb8, 3, 0, 0, 0])?;
    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 2, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let private_call = finished.label_offset(private_call)?;
    Ok((finished.code, private_call))
}

fn lower_x86_64_native_capture_reducer_v1(
    domain: NativeCaptureReducerDomainV1,
    source: NativeCaptureReducerSourceV1<'_>,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    let caller_scratch_bytes = source.caller_scratch_bytes();
    let lowered = match source {
        NativeCaptureReducerSourceV1::ExactSpanParticipation {
            group_count,
            participation_scratch_bytes,
            caller_scratch_bytes,
            ..
        } => lower_x86_64_native_participation_reducer_domain_v1(
            group_count,
            participation_scratch_bytes,
            caller_scratch_bytes,
        )?,
        NativeCaptureReducerSourceV1::CaptureNext { group_count, .. } => {
            lower_x86_64_native_capture_next_reducer_domain_v1(group_count)?
        }
    };
    if domain == NativeCaptureReducerDomainV1::WholeHaystack {
        return Ok(lowered);
    }
    let (mut code, private_call) =
        lower_x86_64_native_capture_grep_wrapper_v1(caller_scratch_bytes)?;
    let private_offset = code
        .len()
        .checked_add(15)
        .ok_or(ObjectError::ArithmeticOverflow("capture reducer private alignment"))?
        & !15;
    code.try_reserve_exact(
        private_offset
            .checked_sub(code.len())
            .and_then(|padding| padding.checked_add(lowered.code.len()))
            .ok_or(ObjectError::ArithmeticOverflow("capture reducer private extent"))?,
    )
    .map_err(|_| ObjectError::Allocation("capture reducer private code"))?;
    code.resize(private_offset, 0x90);
    push_bytes(&mut code, &lowered.code)?;
    let mut local_calls = Vec::new();
    local_calls
        .try_reserve_exact(
            1_usize
                .checked_add(lowered.local_calls.len())
                .ok_or(ObjectError::ArithmeticOverflow("capture reducer calls"))?,
        )
        .map_err(|_| ObjectError::Allocation("capture reducer calls"))?;
    local_calls.push((
        private_call,
        NativeCaptureReducerCallTargetV1::PrivateDomain(private_offset),
    ));
    for &(offset, target) in lowered.local_calls.iter() {
        local_calls.push((
            private_offset
                .checked_add(offset)
                .ok_or(ObjectError::ArithmeticOverflow("capture reducer child call"))?,
            target,
        ));
    }
    let mut bundle_relocations = Vec::new();
    bundle_relocations
        .try_reserve_exact(lowered.bundle_relocations.len())
        .map_err(|_| ObjectError::Allocation("capture reducer bundle relocations"))?;
    for &(offset, kind, addend) in lowered.bundle_relocations.iter() {
        bundle_relocations.push((
            private_offset.checked_add(offset).ok_or(
                ObjectError::ArithmeticOverflow("capture reducer bundle relocation"),
            )?,
            kind,
            addend,
        ));
    }
    Ok(NativeCaptureReducerLoweringV1 {
        code,
        local_calls: local_calls.into_boxed_slice(),
        bundle_relocations: bundle_relocations.into_boxed_slice(),
    })
}

/// Scale one transactional native Count result by a compiler-proved uniform
/// participating-group count. The local Count entry remains authoritative for
/// handle identity, source-domain validation, and exhaustive empty progress.
fn lower_x86_64_uniform_capture_count(
    multiplier: u64,
) -> Result<NativeUniformCaptureReducerWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 24;
    if multiplier == 0 {
        return Err(ObjectError::InvalidModule(
            "uniform capture multiplier is zero",
        ));
    }
    let mut assembler = X86Assembler::new();
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.instruction(&[0x48, 0x85, 0xff])?; // handle
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // haystack
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?; // signed-domain length
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?; // output
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?; // output alignment
    assembler.branch(&[0x0f, 0x85], invalid)?;

    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x08])?; // caller output
    assembler.instruction(&[0x48, 0x8d, 0x0c, 0x24])?; // private Count output
    assembler.instruction(&[0xe8])?;
    let count_call = assembler.label()?;
    assembler.bind(count_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], returned)?;

    assembler.instruction(&[0x48, 0x8b, 0x04, 0x24])?;
    let mut load_multiplier = vec![0x49, 0xba]; // movabs multiplier, r10
    load_multiplier.extend_from_slice(&multiplier.to_le_bytes());
    assembler.instruction(&load_multiplier)?;
    assembler.instruction(&[0x49, 0xf7, 0xe2])?; // mul r10 -> rdx:rax
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], overflow)?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x89, 0x01])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(overflow)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativeUniformCaptureReducerWrapper {
        count_call_offsets: vec![finished.label_offset(count_call)?].into_boxed_slice(),
        code: finished.code,
    })
}

/// Own exact `ByteSlice::lines` splitting and run exhaustive native Count in
/// each LF/CRLF line domain. The empty-window preflight authenticates the
/// handle before this wrapper inspects even one source byte.
#[allow(
    clippy::too_many_lines,
    reason = "preflight, line splitting, checked scaling, and publication form one native leaf"
)]
fn lower_x86_64_uniform_capture_grep(
    multiplier: u64,
) -> Result<NativeUniformCaptureReducerWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 32;
    const TOTAL_OFFSET: u8 = 8;
    const LINE_START_OFFSET: u8 = 16;
    if multiplier == 0 {
        return Err(ObjectError::InvalidModule(
            "uniform capture multiplier is zero",
        ));
    }
    let mut assembler = X86Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let finished_lines = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.instruction(&[0x48, 0x85, 0xff])?;
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?;
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc1, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;

    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?; // handle
    assembler.instruction(&[0x49, 0x89, 0xf4])?; // haystack base
    assembler.instruction(&[0x49, 0x89, 0xd5])?; // length
    assembler.instruction(&[0x49, 0x89, 0xcf])?; // caller output
    assembler.instruction(&[0x4d, 0x31, 0xf6])?; // cursor
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, TOTAL_OFFSET, 0, 0, 0, 0])?;

    // Authenticate through the exact Count operation before source access.
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x4c, 0x89, 0xe6])?;
    assembler.instruction(&[0x31, 0xd2])?;
    assembler.instruction(&[0x48, 0x8d, 0x0c, 0x24])?;
    assembler.instruction(&[0xe8])?;
    let preflight_call = assembler.label()?;
    assembler.bind(preflight_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], returned)?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.branch(&[0x0f, 0x84], finished_lines)?;

    assembler.bind(line_loop)?;
    assembler.instruction(&[0x4c, 0x89, 0x74, 0x24, LINE_START_OFFSET])?;
    assembler.bind(scan)?;
    assembler.instruction(&[0x4d, 0x39, 0xee])?;
    assembler.branch(&[0x0f, 0x84], final_line)?;
    assembler.instruction(&[0x43, 0x80, 0x3c, 0x34, 0x0a])?;
    assembler.branch(&[0x0f, 0x84], found_lf)?;
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;
    assembler.branch(&[0xe9], scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(&[0x4d, 0x89, 0xf2])?; // line end before LF
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;
    assembler.instruction(&[0x4c, 0x8b, 0x5c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x4d, 0x39, 0xda])?;
    assembler.branch(&[0x0f, 0x84], line_ready)?;
    assembler.instruction(&[0x43, 0x80, 0x7c, 0x14, 0xff, 0x0d])?;
    assembler.branch(&[0x0f, 0x85], line_ready)?;
    assembler.instruction(&[0x49, 0x83, 0xea, 0x01])?;
    assembler.branch(&[0xe9], line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(&[0x4d, 0x89, 0xf2])?;
    assembler.bind(line_ready)?;
    assembler.instruction(&[0x4c, 0x8b, 0x5c, 0x24, LINE_START_OFFSET])?;
    assembler.instruction(&[0x4d, 0x29, 0xda])?; // line length
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x4b, 0x8d, 0x34, 0x1c])?; // line pointer
    assembler.instruction(&[0x4c, 0x89, 0xd2])?;
    assembler.instruction(&[0x48, 0x8d, 0x0c, 0x24])?;
    assembler.instruction(&[0xe8])?;
    let line_count_call = assembler.label()?;
    assembler.bind(line_count_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x85], returned)?;

    assembler.instruction(&[0x48, 0x8b, 0x04, 0x24])?;
    let mut load_multiplier = vec![0x49, 0xba];
    load_multiplier.extend_from_slice(&multiplier.to_le_bytes());
    assembler.instruction(&load_multiplier)?;
    assembler.instruction(&[0x49, 0xf7, 0xe2])?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x85], overflow)?;
    assembler.instruction(&[0x48, 0x01, 0x44, 0x24, TOTAL_OFFSET])?;
    assembler.branch(&[0x0f, 0x82], overflow)?;
    assembler.instruction(&[0x4d, 0x39, 0xee])?;
    assembler.branch(&[0x0f, 0x84], finished_lines)?;
    assembler.branch(&[0xe9], line_loop)?;

    assembler.bind(finished_lines)?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, TOTAL_OFFSET])?;
    assembler.instruction(&[0x49, 0x89, 0x07])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(&[0xb8, 0x03, 0, 0, 0])?;
    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativeUniformCaptureReducerWrapper {
        count_call_offsets: vec![
            finished.label_offset(preflight_call)?,
            finished.label_offset(line_count_call)?,
        ]
        .into_boxed_slice(),
        code: finished.code,
    })
}

fn lower_x86_64_prepared_exists_batch() -> Result<NativePreparedBulkWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 48;
    let mut assembler = X86Assembler::new();
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let completed_item = assembler.label()?;
    let complete = assembler.label()?;
    let late_invalid = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.instruction(&[0x48, 0x85, 0xff])?; // handle
    assembler.branch(&[0x0f, 0x84], invalid_handle)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?; // processed
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    let mut maximum_count = vec![0x49, 0xba];
    maximum_count.extend_from_slice(&(isize::MAX as u64 / 16).to_le_bytes());
    assembler.instruction(&maximum_count)?;
    assembler.instruction(&[0x4c, 0x39, 0xd2])?;
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x84], validated)?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // descriptors
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0xf6, 0xc6, 0x07])?;
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xc9])?; // matched bytes
    assembler.branch(&[0x0f, 0x84], invalid)?;

    assembler.bind(validated)?;
    assembler.instruction(&[0x53])?;
    assembler.instruction(&[0x41, 0x54])?;
    assembler.instruction(&[0x41, 0x55])?;
    assembler.instruction(&[0x41, 0x56])?;
    assembler.instruction(&[0x41, 0x57])?;
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0xfb])?;
    assembler.instruction(&[0x49, 0x89, 0xf4])?;
    assembler.instruction(&[0x49, 0x89, 0xd5])?;
    assembler.instruction(&[0x49, 0x89, 0xce])?;
    assembler.instruction(&[0x4d, 0x89, 0xc7])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x10, 0, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x20, 0, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0xc7, 0x44, 0x24, 0x28, 0, 0, 0, 0])?;
    assembler.instruction(&[0x49, 0xc7, 0x07, 0, 0, 0, 0])?;

    assembler.bind(loop_head)?;
    assembler.instruction(&[0x4d, 0x85, 0xed])?;
    assembler.branch(&[0x0f, 0x84], complete)?;
    assembler.instruction(&[0x49, 0x8b, 0x34, 0x24])?;
    assembler.instruction(&[0x49, 0x8b, 0x54, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x85, 0xf6])?;
    assembler.branch(&[0x0f, 0x84], late_invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xd2])?;
    assembler.branch(&[0x0f, 0x88], late_invalid)?;
    assembler.instruction(&[0x48, 0x89, 0xdf])?;
    assembler.instruction(&[0x31, 0xc9])?;
    assembler.instruction(&[0x49, 0x89, 0xd0])?;
    assembler.instruction(&[0x49, 0x89, 0xe1])?;
    assembler.instruction(&[0x4c, 0x8d, 0x54, 0x24, 0x20])?; // private session
    assembler.instruction(&[0xe8])?;
    let prepared_call = assembler.label()?;
    assembler.bind(prepared_call)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?;
    assembler.branch(&[0x0f, 0x86], completed_item)?;
    assembler.branch(&[0xe9], returned)?;

    assembler.bind(completed_item)?;
    assembler.instruction(&[0x41, 0x88, 0x06])?;
    assembler.instruction(&[0x49, 0x83, 0xc4, 0x10])?;
    assembler.instruction(&[0x49, 0x83, 0xc6, 0x01])?;
    assembler.instruction(&[0x49, 0x83, 0xed, 0x01])?;
    assembler.instruction(&[0x48, 0x8b, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 0x01])?;
    assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x10])?;
    assembler.instruction(&[0x49, 0x89, 0x07])?;
    assembler.branch(&[0xe9], loop_head)?;
    assembler.bind(complete)?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.branch(&[0xe9], returned)?;
    assembler.bind(late_invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;

    assembler.bind(returned)?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0x41, 0x5f])?;
    assembler.instruction(&[0x41, 0x5e])?;
    assembler.instruction(&[0x41, 0x5d])?;
    assembler.instruction(&[0x41, 0x5c])?;
    assembler.instruction(&[0x5b])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(&[0xb8, 0x05, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;
    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    Ok(NativePreparedBulkWrapper {
        prepared_call_offset: finished.label_offset(prepared_call)?,
        ordered_nfa_gate_call_offset: None,
        bulk_runtime_fallback_offset: None,
        compatibility_identity_relocation: None,
        identity_relocation: None,
        code: finished.code,
    })
}

/// Emit the AAPCS64 one-shot operation gate after complete read-only wrapper
/// validation. X0..X7 and LR are restored before either successor; X18 is
/// untouched and SP remains 16-byte aligned across the classifier BL.
fn aarch64_emit_ordered_nfa_operation_gate(
    assembler: &mut Aarch64Assembler,
    compatibility_identity: bool,
) -> Result<(usize, usize, Option<[usize; 2]>), ObjectError> {
    let native = assembler.label()?;
    let legacy = assembler.label()?;
    assembler.instruction(aarch64_sub_x_imm(31, 31, 80)?)?;
    for (left, right, offset) in [
        (0, 1, 0),
        (2, 3, 16),
        (4, 5, 32),
        (6, 7, 48),
    ] {
        assembler.instruction(aarch64_store_pair_x(left, right, 31, offset)?)?;
    }
    assembler.instruction(aarch64_store_x(30, 31, 64)?)?;
    let gate_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_mov_x(9, 0)?)?; // preserve classifier status
    for (left, right, offset) in [
        (0, 1, 0),
        (2, 3, 16),
        (4, 5, 32),
        (6, 7, 48),
    ] {
        assembler.instruction(aarch64_load_pair_x(left, right, 31, offset)?)?;
    }
    assembler.instruction(aarch64_load_x_imm(30, 31, 64)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, 80)?)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, native)?;
    assembler.branch_zero_w(9, legacy)?;
    assembler.instruction(aarch64_mov_x(0, 9)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(legacy)?;
    let identity_relocation = if compatibility_identity {
        Some([
            assembler.instruction(0x9000_0004)?,
            assembler.instruction(aarch64_add_x_imm(4, 4, 0)?)?,
        ])
    } else {
        None
    };
    let runtime_fallback = assembler.instruction(0x1400_0000)?;
    assembler.bind(native)?;
    Ok((gate_call, runtime_fallback, identity_relocation))
}

/// AAPCS64 counterpart to
/// [`x86_emit_required_ordered_nfa_operation_gate`]. A capability mismatch is
/// terminal and never enters the target-neutral semantic reducer.
fn aarch64_emit_required_ordered_nfa_operation_gate(
    assembler: &mut Aarch64Assembler,
) -> Result<usize, ObjectError> {
    let native = assembler.label()?;
    let failed = assembler.label()?;
    assembler.instruction(aarch64_sub_x_imm(31, 31, 80)?)?;
    for (left, right, offset) in [
        (0, 1, 0),
        (2, 3, 16),
        (4, 5, 32),
        (6, 7, 48),
    ] {
        assembler.instruction(aarch64_store_pair_x(left, right, 31, offset)?)?;
    }
    assembler.instruction(aarch64_store_x(30, 31, 64)?)?;
    let gate_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_mov_x(9, 0)?)?;
    for (left, right, offset) in [
        (0, 1, 0),
        (2, 3, 16),
        (4, 5, 32),
        (6, 7, 48),
    ] {
        assembler.instruction(aarch64_load_pair_x(left, right, 31, offset)?)?;
    }
    assembler.instruction(aarch64_load_x_imm(30, 31, 64)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, 80)?)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, native)?;
    assembler.branch_nonzero_w(9, failed)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(failed)?;
    assembler.instruction(aarch64_mov_x(0, 9)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(native)?;
    Ok(gate_call)
}

#[allow(
    clippy::too_many_lines,
    reason = "raw ABI validation, iterator progress, and transactional output publication are one generated leaf"
)]
fn lower_aarch64_prepared_span(
    sink: PreparedSpanSink,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    match sink {
        PreparedSpanSink::Fill {
            large_window_runtime_bulk,
        } => lower_aarch64_prepared_span_fill_impl(large_window_runtime_bulk, false),
        PreparedSpanSink::Count | PreparedSpanSink::SpanSum => {
            lower_aarch64_prepared_span_reduce(
                sink,
                NativeSpanReducerCallKind::PreparedPrivate,
                false,
            )
        }
    }
}

fn lower_aarch64_prepared_span_fill(
    large_window_runtime_bulk: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_aarch64_prepared_span(PreparedSpanSink::Fill {
        large_window_runtime_bulk,
    })
}

fn lower_aarch64_ordered_nfa_span_fill() -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_aarch64_prepared_span_fill_impl(false, true)
}

fn lower_aarch64_prepared_span_fill_impl(
    large_window_runtime_bulk: bool,
    ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    if large_window_runtime_bulk && ordered_nfa_gate {
        return Err(ObjectError::InvalidModule(
            "Ordered-NFA Span fill retained a dynamic large-window edge",
        ));
    }
    const FRAME_BYTES: u16 = 112;
    let mut assembler = Aarch64Assembler::new();
    let validate_state = assembler.label()?;
    let no_pending = assembler.label()?;
    let has_last = assembler.label()?;
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted = assembler.label()?;
    let publish = assembler.label()?;
    let full = assembler.label()?;
    let finished = assembler.label()?;
    let terminal_error = assembler.label()?;
    let invalid_result = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let runtime_bulk = large_window_runtime_bulk
        .then(|| assembler.label())
        .transpose()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(2, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 3, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    assembler.branch_zero_x(6, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 6, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;
    aarch64_load_u64_constant(&mut assembler, 7, isize::MAX as u64 / 16)?;
    assembler.instruction(aarch64_cmp_x(5, 7)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_zero_x(5, validate_state)?;
    assembler.branch_zero_x(4, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 4, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    assembler.bind(validate_state)?;
    assembler.instruction(aarch64_load_w_imm(7, 3, 20)?)?;
    assembler.branch_nonzero_w(7, invalid)?;
    assembler.instruction(aarch64_load_w_imm(7, 3, 16)?)?;
    assembler.instruction(aarch64_and_low_w(8, 7, 3)?)?;
    assembler.instruction(aarch64_cmp_w(7, 8)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_load_x_imm(8, 3, 0)?)?;
    assembler.instruction(aarch64_cmp_x(8, 2)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_load_x_imm(9, 3, 8)?)?;
    assembler.instruction(aarch64_cmp_x(9, 2)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_bit_clear_w(7, 1, no_pending)?;
    assembler.branch_bit_clear_w(7, 0, invalid)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.bind(no_pending)?;
    assembler.branch_bit_set_w(7, 0, has_last)?;
    assembler.branch_nonzero_x(8, invalid)?;
    assembler.branch_nonzero_x(9, invalid)?;
    assembler.branch(validated)?;
    assembler.bind(has_last)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.branch_bit_clear_w(7, 2, validated)?;
    assembler.branch_bit_set_w(7, 1, invalid)?;

    assembler.bind(validated)?;
    let ordered_gate_sites = ordered_nfa_gate
        .then(|| aarch64_emit_ordered_nfa_operation_gate(&mut assembler, false))
        .transpose()?;
    if let Some(runtime_bulk) = runtime_bulk {
        assembler.instruction(aarch64_load_x_imm(7, 3, 0)?)?;
        assembler.instruction(aarch64_sub_x_reg(7, 2, 7)?)?;
        assembler.instruction(aarch64_cmp_x_imm(
            7,
            u16::try_from(FROZEN_SCANNER_FREE_DYNAMIC_ROWS_MAX_INPUT_BYTES)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 bulk window ceiling"))?,
        )?)?;
        assembler.branch_cond(AARCH64_HI, runtime_bulk)?;
    }
    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(19, 20, 31, 0)?)?;
    assembler.instruction(aarch64_store_pair_x(21, 22, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(23, 24, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(25, 26, 31, 48)?)?;
    assembler.instruction(aarch64_store_pair_x(27, 28, 31, 64)?)?;
    assembler.instruction(aarch64_store_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_store_pair_x(31, 31, 31, 96)?)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_mov_x(23, 4)?)?;
    assembler.instruction(aarch64_mov_x(24, 5)?)?;
    assembler.instruction(aarch64_mov_x(25, 6)?)?;
    assembler.instruction(aarch64_movz_x(26, 0, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 25, 0)?)?;
    assembler.branch_nonzero_x(24, loop_head)?;
    assembler.instruction(aarch64_load_w_imm(9, 22, 16)?)?;
    assembler.branch_bit_set_w(9, 2, finished)?;
    assembler.branch(full)?;

    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_load_w_imm(9, 22, 16)?)?;
    assembler.branch_bit_set_w(9, 2, finished)?;
    assembler.branch_bit_clear_w(9, 1, search)?;
    assembler.instruction(aarch64_and_low_w(9, 9, 1)?)?;
    assembler.instruction(aarch64_store_w(9, 22, 16)?)?;
    assembler.instruction(aarch64_load_x_imm(8, 22, 0)?)?;
    assembler.instruction(aarch64_cmp_x(8, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(8, 8, 1)?)?;
    assembler.instruction(aarch64_store_x(8, 22, 0)?)?;

    assembler.bind(search)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_mov_x(2, 21)?)?;
    assembler.instruction(aarch64_load_x_imm(27, 22, 0)?)?;
    assembler.instruction(aarch64_mov_x(3, 27)?)?;
    assembler.instruction(aarch64_mov_x(4, 21)?)?;
    assembler.instruction(aarch64_mov_x(5, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(6, 31, 96)?)?;
    let prepared_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(terminal_error)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_x_imm(8, 23, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(9, 23, 8)?)?;
    assembler.instruction(aarch64_cmp_x(8, 27)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_result)?;
    assembler.instruction(aarch64_cmp_x(9, 8)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_result)?;
    assembler.instruction(aarch64_cmp_x(9, 21)?)?;
    assembler.branch_cond(AARCH64_HI, invalid_result)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, nonempty)?;
    assembler.instruction(aarch64_load_w_imm(10, 22, 16)?)?;
    assembler.branch_bit_clear_w(10, 0, accepted)?;
    assembler.instruction(aarch64_load_x_imm(11, 22, 8)?)?;
    assembler.instruction(aarch64_cmp_x(11, 9)?)?;
    assembler.branch_cond(AARCH64_NE, accepted)?;
    assembler.instruction(aarch64_load_x_imm(11, 22, 0)?)?;
    assembler.instruction(aarch64_cmp_x(11, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(11, 11, 1)?)?;
    assembler.instruction(aarch64_store_x(11, 22, 0)?)?;
    assembler.branch(search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(aarch64_movz_w(10, 1)?)?;
    assembler.branch(publish)?;
    assembler.bind(accepted)?;
    assembler.instruction(aarch64_movz_w(10, 3)?)?;
    assembler.bind(publish)?;
    assembler.instruction(aarch64_store_x(9, 22, 0)?)?;
    assembler.instruction(aarch64_store_x(9, 22, 8)?)?;
    assembler.instruction(aarch64_store_w(10, 22, 16)?)?;
    assembler.instruction(aarch64_add_x_imm(26, 26, 1)?)?;
    assembler.instruction(aarch64_store_x(26, 25, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 16)?)?;
    assembler.instruction(aarch64_cmp_x(26, 24)?)?;
    assembler.branch_cond(AARCH64_EQ, full)?;
    assembler.branch(loop_head)?;

    assembler.bind(full)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;
    assembler.bind(finished)?;
    assembler.instruction(aarch64_load_w_imm(9, 22, 16)?)?;
    assembler.instruction(aarch64_and_low_w(9, 9, 1)?)?;
    assembler.instruction(aarch64_movz_w(10, 4)?)?;
    assembler.instruction(aarch64_orr_w(9, 9, 10)?)?;
    assembler.instruction(aarch64_store_w(9, 22, 16)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(invalid_result)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(terminal_error)?;
    assembler.instruction(aarch64_mov_x(28, 0)?)?;
    assembler.instruction(aarch64_load_w_imm(9, 22, 16)?)?;
    assembler.instruction(aarch64_and_low_w(9, 9, 1)?)?;
    assembler.instruction(aarch64_movz_w(10, 4)?)?;
    assembler.instruction(aarch64_orr_w(9, 9, 10)?)?;
    assembler.instruction(aarch64_store_w(9, 22, 16)?)?;
    assembler.instruction(aarch64_mov_x(0, 28)?)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 20, 31, 0)?)?;
    assembler.instruction(aarch64_load_pair_x(21, 22, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(23, 24, 31, 32)?)?;
    assembler.instruction(aarch64_load_pair_x(25, 26, 31, 48)?)?;
    assembler.instruction(aarch64_load_pair_x(27, 28, 31, 64)?)?;
    assembler.instruction(aarch64_load_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let bulk_runtime_fallback = if let Some(runtime_bulk) = runtime_bulk {
        assembler.bind(runtime_bulk)?;
        Some(assembler.instruction(0x1400_0000)?)
    } else {
        None
    };

    let mut offsets = vec![prepared_call];
    let ordered_gate_indices = ordered_gate_sites.map(|(call, fallback, identity)| {
        let call_index = offsets.len();
        offsets.push(call);
        let fallback_index = offsets.len();
        offsets.push(fallback);
        let identity_indices = identity.map(|[page, page_offset]| {
            let page_index = offsets.len();
            offsets.push(page);
            let page_offset_index = offsets.len();
            offsets.push(page_offset);
            [page_index, page_offset_index]
        });
        (call_index, fallback_index, identity_indices)
    });
    let bulk_runtime_fallback_index = bulk_runtime_fallback.map(|instruction| {
        let index = offsets.len();
        offsets.push(instruction);
        index
    });
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativePreparedBulkWrapper {
        code,
        prepared_call_offset: offsets[0],
        ordered_nfa_gate_call_offset: ordered_gate_indices
            .map(|(call, _, _)| offsets[call]),
        bulk_runtime_fallback_offset: ordered_gate_indices
            .map(|(_, fallback, _)| offsets[fallback])
            .or_else(|| bulk_runtime_fallback_index.map(|index| offsets[index])),
        compatibility_identity_relocation: ordered_gate_indices
            .and_then(|(_, _, identity)| identity)
            .map(|[page, page_offset]| {
                NativePreparedIdentityRelocation::Aarch64Page21PageOff12 {
                    page: offsets[page],
                    page_offset: offsets[page_offset],
                }
            }),
        identity_relocation: None,
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "raw ABI validation, exact nullable progress, and transactional scalar publication form one generated leaf"
)]
fn lower_aarch64_prepared_span_reduce(
    sink: PreparedSpanSink,
    call_kind: NativeSpanReducerCallKind,
    ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_aarch64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        call_kind,
        ordered_nfa_gate,
        None,
        false,
    )
}

#[allow(
    clippy::too_many_lines,
    reason = "authenticated one-shot terminal trim and exact nullable iteration form one generated leaf"
)]
fn lower_aarch64_prepared_span_reduce_with_terminal_exact_set(
    sink: PreparedSpanSink,
    call_kind: NativeSpanReducerCallKind,
    ordered_nfa_gate: bool,
    terminal_exact_set: Option<[u64; 4]>,
    required_ordered_nfa_gate: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    const LEGACY_FRAME_BYTES: u16 = 112;
    const TERMINAL_FRAME_BYTES: u16 = 128;
    const SAVED_REGISTERS_OFFSET: i16 = 16;
    const SESSION_OFFSET: u16 = 96;
    const SESSION_PAIR_OFFSET: i16 = 96;
    const TERMINAL_END_OFFSET: u16 = 112;

    if required_ordered_nfa_gate && !ordered_nfa_gate {
        return Err(ObjectError::InvalidModule(
            "required AArch64 Ordered-NFA reducer gate was not selected",
        ));
    }
    if ordered_nfa_gate && call_kind != NativeSpanReducerCallKind::PreparedPrivate {
        return Err(ObjectError::InvalidModule(
            "Ordered-NFA reducer has no private prepared target",
        ));
    }
    if terminal_exact_set.is_some()
        && (!ordered_nfa_gate || call_kind != NativeSpanReducerCallKind::PreparedPrivate)
    {
        return Err(ObjectError::InvalidModule(
            "terminal exact-set aggregate trim has no Ordered-NFA private target",
        ));
    }
    if matches!(sink, PreparedSpanSink::Fill { .. }) {
        return Err(ObjectError::InvalidModule(
            "AArch64 prepared scalar reducer received the Fill sink",
        ));
    }
    let frame_bytes = if terminal_exact_set.is_some() {
        TERMINAL_FRAME_BYTES
    } else {
        LEGACY_FRAME_BYTES
    };

    let mut assembler = Aarch64Assembler::new();
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted = assembler.label()?;
    let publish = assembler.label()?;
    let finished = assembler.label()?;
    let invalid_result = assembler.label()?;
    let terminal_error = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let wrong_identity = assembler.label()?;
    let terminal_scan = assembler.label()?;
    let terminal_word0 = assembler.label()?;
    let terminal_word1 = assembler.label()?;
    let terminal_word2 = assembler.label()?;
    let terminal_word3 = assembler.label()?;
    let terminal_member = assembler.label()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(2, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 3, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    let ordered_gate_sites = (ordered_nfa_gate && !required_ordered_nfa_gate)
        .then(|| aarch64_emit_ordered_nfa_operation_gate(&mut assembler, true))
        .transpose()?;
    let required_gate_call = required_ordered_nfa_gate
        .then(|| aarch64_emit_required_ordered_nfa_operation_gate(&mut assembler))
        .transpose()?;

    // Authenticate the exact linked artifact before either local call shape
    // can inspect source bytes.
    let identity_page = assembler.instruction(0x9000_0007)?;
    let identity_page_offset = assembler.instruction(aarch64_add_x_imm(7, 7, 0)?)?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 prepared aggregate identity word",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            8,
            7,
            u16::try_from(word_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 prepared aggregate linked identity offset",
                )
            })?,
        )?)?;
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 prepared aggregate header identity offset",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            9,
            0,
            u16::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 prepared aggregate header identity displacement",
                )
            })?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(9, 8)?)?;
        assembler.branch_cond(AARCH64_NE, wrong_identity)?;
    }

    assembler.instruction(aarch64_sub_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(aarch64_store_pair_x(
        19,
        20,
        31,
        SAVED_REGISTERS_OFFSET,
    )?)?;
    assembler.instruction(aarch64_store_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_store_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_store_pair_x(29, 30, 31, 80)?)?;
    if call_kind == NativeSpanReducerCallKind::PreparedPrivate {
        assembler.instruction(aarch64_store_pair_x(
            31,
            31,
            31,
            SESSION_PAIR_OFFSET,
        )?)?;
    }
    assembler.instruction(aarch64_mov_x(19, 0)?)?; // handle
    assembler.instruction(aarch64_mov_x(20, 1)?)?; // haystack
    assembler.instruction(aarch64_mov_x(21, 2)?)?; // length
    assembler.instruction(aarch64_mov_x(22, 3)?)?; // output
    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?; // next_start
    assembler.instruction(aarch64_movz_x(24, 0, 0)?)?; // last_match_end
    assembler.instruction(aarch64_movz_x(25, 0, 0)?)?; // accumulator
    assembler.instruction(aarch64_movz_w(26, 0)?)?; // iterator flags

    if let Some(bitmap_words) = terminal_exact_set {
        // Keep H in X21 for assertions. This one exhaustive aggregate scan
        // computes a smaller semantic E in its own slot, disjoint from the
        // two-word private prepared session at +96.
        assembler.instruction(aarch64_store_x(21, 31, TERMINAL_END_OFFSET)?)?;
        assembler.instruction(aarch64_mov_x(8, 21)?)?; // scan cursor = H
        assembler.bind(terminal_scan)?;
        assembler.branch_zero_x(8, finished)?;
        assembler.instruction(aarch64_sub_x_imm(8, 8, 1)?)?;
        assembler.instruction(aarch64_load_byte_reg(9, 20, 8)?)?;
        assembler.instruction(aarch64_cmp_w_imm(9, 64)?)?;
        assembler.branch_cond(AARCH64_LO, terminal_word0)?;
        assembler.instruction(aarch64_cmp_w_imm(9, 128)?)?;
        assembler.branch_cond(AARCH64_LO, terminal_word1)?;
        assembler.instruction(aarch64_cmp_w_imm(9, 192)?)?;
        assembler.branch_cond(AARCH64_LO, terminal_word2)?;
        assembler.branch(terminal_word3)?;
        for (label, word) in [
            terminal_word0,
            terminal_word1,
            terminal_word2,
            terminal_word3,
        ]
        .into_iter()
        .zip(bitmap_words)
        {
            assembler.bind(label)?;
            aarch64_load_u64_constant(&mut assembler, 10, word)?;
            assembler.branch(terminal_member)?;
        }
        assembler.bind(terminal_member)?;
        assembler.instruction(aarch64_lsrv_x(10, 10, 9)?)?;
        assembler.branch_bit_clear_w(10, 0, terminal_scan)?;
        assembler.instruction(aarch64_add_x_imm(8, 8, 1)?)?;
        assembler.instruction(aarch64_store_x(8, 31, TERMINAL_END_OFFSET)?)?;
    }

    assembler.bind(loop_head)?;
    assembler.branch_bit_clear_w(26, 1, search)?;
    assembler.instruction(aarch64_and_low_w(26, 26, 1)?)?;
    if terminal_exact_set.is_some() {
        assembler.instruction(aarch64_load_x_imm(8, 31, TERMINAL_END_OFFSET)?)?;
        assembler.instruction(aarch64_cmp_x(23, 8)?)?;
    } else {
        assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    }
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;

    assembler.bind(search)?;
    match call_kind {
        NativeSpanReducerCallKind::PreparedPrivate => {
            assembler.instruction(aarch64_mov_x(0, 19)?)?;
            assembler.instruction(aarch64_mov_x(1, 20)?)?;
            assembler.instruction(aarch64_mov_x(2, 21)?)?;
            assembler.instruction(aarch64_mov_x(3, 23)?)?;
            if terminal_exact_set.is_some() {
                assembler.instruction(aarch64_load_x_imm(4, 31, TERMINAL_END_OFFSET)?)?;
            } else {
                assembler.instruction(aarch64_mov_x(4, 21)?)?;
            }
            // ADD (immediate) names SP for register 31, unlike MOV's XZR alias.
            assembler.instruction(aarch64_add_x_imm(5, 31, 0)?)?;
            assembler.instruction(aarch64_add_x_imm(6, 31, SESSION_OFFSET)?)?;
        }
        NativeSpanReducerCallKind::DirectOrdinary => {
            assembler.instruction(aarch64_mov_x(0, 20)?)?; // haystack
            assembler.instruction(aarch64_mov_x(1, 21)?)?; // length
            assembler.instruction(aarch64_mov_x(2, 23)?)?; // window start
            assembler.instruction(aarch64_mov_x(3, 21)?)?; // window end
            assembler.instruction(aarch64_add_x_imm(4, 31, 0)?)?; // private result
        }
    }
    let prepared_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(terminal_error)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_x_imm(8, 31, 0)?)?; // start
    assembler.instruction(aarch64_load_x_imm(9, 31, 8)?)?; // end
    assembler.instruction(aarch64_cmp_x(8, 23)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_result)?;
    assembler.instruction(aarch64_cmp_x(9, 8)?)?;
    assembler.branch_cond(AARCH64_LO, invalid_result)?;
    if terminal_exact_set.is_some() {
        assembler.instruction(aarch64_load_x_imm(10, 31, TERMINAL_END_OFFSET)?)?;
        assembler.instruction(aarch64_cmp_x(9, 10)?)?;
    } else {
        assembler.instruction(aarch64_cmp_x(9, 21)?)?;
    }
    assembler.branch_cond(AARCH64_HI, invalid_result)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, nonempty)?;
    assembler.branch_bit_clear_w(26, 0, accepted)?;
    assembler.instruction(aarch64_cmp_x(24, 9)?)?;
    assembler.branch_cond(AARCH64_NE, accepted)?;
    if terminal_exact_set.is_some() {
        assembler.instruction(aarch64_load_x_imm(10, 31, TERMINAL_END_OFFSET)?)?;
        assembler.instruction(aarch64_cmp_x(23, 10)?)?;
    } else {
        assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    }
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.branch(search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(aarch64_movz_w(26, 1)?)?;
    assembler.branch(publish)?;
    assembler.bind(accepted)?;
    assembler.instruction(aarch64_movz_w(26, 3)?)?;
    assembler.bind(publish)?;
    assembler.instruction(aarch64_mov_x(23, 9)?)?;
    assembler.instruction(aarch64_mov_x(24, 9)?)?;
    match sink {
        PreparedSpanSink::Count => {
            assembler.instruction(aarch64_add_x_imm(25, 25, 1)?)?;
        }
        PreparedSpanSink::SpanSum => {
            assembler.instruction(aarch64_sub_x_reg(10, 9, 8)?)?;
            assembler.instruction(aarch64_add_x_reg(25, 25, 10)?)?;
        }
        PreparedSpanSink::Fill { .. } => unreachable!(),
    }
    assembler.branch(loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(25, 22, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(invalid_result)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(terminal_error)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_load_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_load_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_load_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(wrong_identity)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = vec![prepared_call, identity_page, identity_page_offset];
    let ordered_gate_indices = ordered_gate_sites.map(|(call, fallback, identity)| {
        let call_index = offsets.len();
        offsets.push(call);
        let fallback_index = offsets.len();
        offsets.push(fallback);
        let identity_indices = identity.map(|[page, page_offset]| {
            let page_index = offsets.len();
            offsets.push(page);
            let page_offset_index = offsets.len();
            offsets.push(page_offset);
            [page_index, page_offset_index]
        });
        (call_index, fallback_index, identity_indices)
    });
    let required_gate_index = required_gate_call.map(|call| {
        let index = offsets.len();
        offsets.push(call);
        index
    });
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativePreparedBulkWrapper {
        code,
        prepared_call_offset: offsets[0],
        ordered_nfa_gate_call_offset: ordered_gate_indices
            .map(|(call, _, _)| offsets[call])
            .or(required_gate_index.map(|index| offsets[index])),
        bulk_runtime_fallback_offset: ordered_gate_indices
            .map(|(_, fallback, _)| offsets[fallback]),
        compatibility_identity_relocation: ordered_gate_indices
            .and_then(|(_, _, identity)| identity)
            .map(|[page, page_offset]| {
                NativePreparedIdentityRelocation::Aarch64Page21PageOff12 {
                    page: offsets[page],
                    page_offset: offsets[page_offset],
                }
            }),
        identity_relocation: Some(
            NativePreparedIdentityRelocation::Aarch64Page21PageOff12 {
                page: offsets[1],
                page_offset: offsets[2],
            },
        ),
    })
}

fn lower_aarch64_ordered_nfa_span_reduce(
    sink: PreparedSpanSink,
    terminal_exact_set: Option<[u64; 4]>,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_aarch64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        NativeSpanReducerCallKind::PreparedPrivate,
        true,
        terminal_exact_set,
        false,
    )
}

fn lower_aarch64_required_ordered_nfa_span_reduce(
    sink: PreparedSpanSink,
    terminal_exact_set: Option<[u64; 4]>,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    lower_aarch64_prepared_span_reduce_with_terminal_exact_set(
        sink,
        NativeSpanReducerCallKind::PreparedPrivate,
        true,
        terminal_exact_set,
        true,
    )
}

/// AAPCS64 lowering of the transactional native line-domain reducer.
#[allow(
    clippy::too_many_lines,
    reason = "raw validation, line splitting, local calls, and scalar publication are one native leaf"
)]
fn lower_aarch64_prepared_grep_count(
    call_kind: NativeSpanReducerCallKind,
    required_ordered_nfa: bool,
) -> Result<NativePreparedBulkWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 112;
    const SESSION_OFFSET: u16 = 96;
    if required_ordered_nfa && call_kind != NativeSpanReducerCallKind::PreparedPrivate {
        return Err(ObjectError::InvalidModule(
            "required Ordered-NFA GrepCount has no private prepared target",
        ));
    }

    let mut assembler = Aarch64Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let completed_line = assembler.label()?;
    let matched_line = assembler.label()?;
    let finished = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;
    let wrong_identity = assembler.label()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(2, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 3, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    let ordered_gate_call = required_ordered_nfa
        .then(|| aarch64_emit_required_ordered_nfa_operation_gate(&mut assembler))
        .transpose()?;

    let identity_page = assembler.instruction(0x9000_0007)?;
    let identity_page_offset = assembler.instruction(aarch64_add_x_imm(7, 7, 0)?)?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 native GrepCount identity word",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            8,
            7,
            u16::try_from(word_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 native GrepCount linked identity offset",
                )
            })?,
        )?)?;
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 native GrepCount header identity offset",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            9,
            0,
            u16::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 native GrepCount header identity displacement",
                )
            })?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(9, 8)?)?;
        assembler.branch_cond(AARCH64_NE, wrong_identity)?;
    }

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_store_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_store_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(24, 0, 0)?)?;
    assembler.branch_zero_x(21, finished)?;

    assembler.bind(line_loop)?;
    assembler.instruction(aarch64_mov_x(25, 23)?)?;
    assembler.bind(scan)?;
    assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, final_line)?;
    assembler.instruction(aarch64_load_byte_reg(8, 20, 23)?)?;
    assembler.instruction(aarch64_cmp_w_imm(8, 10)?)?;
    assembler.branch_cond(AARCH64_EQ, found_lf)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.branch(scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(aarch64_mov_x(26, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.instruction(aarch64_cmp_x(26, 25)?)?;
    assembler.branch_cond(AARCH64_EQ, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(8, 26, 1)?)?;
    assembler.instruction(aarch64_load_byte_reg(9, 20, 8)?)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 13)?)?;
    assembler.branch_cond(AARCH64_NE, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(26, 26, 1)?)?;
    assembler.branch(line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(aarch64_mov_x(26, 23)?)?;
    assembler.bind(line_ready)?;
    assembler.instruction(aarch64_sub_x_reg(26, 26, 25)?)?;
    assembler.instruction(aarch64_add_x_reg(8, 20, 25)?)?;
    match call_kind {
        NativeSpanReducerCallKind::PreparedPrivate => {
            assembler.instruction(aarch64_store_pair_x(31, 31, 31, 96)?)?;
            assembler.instruction(aarch64_mov_x(0, 19)?)?;
            assembler.instruction(aarch64_mov_x(1, 8)?)?;
            assembler.instruction(aarch64_mov_x(2, 26)?)?;
            assembler.instruction(aarch64_movz_x(3, 0, 0)?)?;
            assembler.instruction(aarch64_mov_x(4, 26)?)?;
            assembler.instruction(aarch64_add_x_imm(5, 31, 0)?)?;
            assembler.instruction(aarch64_add_x_imm(6, 31, SESSION_OFFSET)?)?;
        }
        NativeSpanReducerCallKind::DirectOrdinary => {
            assembler.instruction(aarch64_mov_x(0, 8)?)?;
            assembler.instruction(aarch64_mov_x(1, 26)?)?;
            assembler.instruction(aarch64_movz_x(2, 0, 0)?)?;
            assembler.instruction(aarch64_mov_x(3, 26)?)?;
            assembler.instruction(aarch64_add_x_imm(4, 31, 0)?)?;
        }
    }
    let prepared_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched_line)?;
    assembler.branch_zero_w(0, completed_line)?;
    assembler.branch(returned)?;

    assembler.bind(matched_line)?;
    assembler.instruction(aarch64_adds_x_imm(24, 24, 1)?)?;
    assembler.branch_cond(AARCH64_HS, overflow)?;
    assembler.bind(completed_line)?;
    assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.branch(line_loop)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(24, 22, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_load_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_load_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_load_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(wrong_identity)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = vec![prepared_call, identity_page, identity_page_offset];
    let gate_index = ordered_gate_call.map(|call| {
        let index = offsets.len();
        offsets.push(call);
        index
    });
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativePreparedBulkWrapper {
        code,
        prepared_call_offset: offsets[0],
        ordered_nfa_gate_call_offset: gate_index.map(|index| offsets[index]),
        bulk_runtime_fallback_offset: None,
        compatibility_identity_relocation: None,
        identity_relocation: Some(
            NativePreparedIdentityRelocation::Aarch64Page21PageOff12 {
                page: offsets[1],
                page_offset: offsets[2],
            },
        ),
    })
}

fn aarch64_native_capture_reducer_boundary(
    assembler: &mut Aarch64Assembler,
    caller_scratch_bytes: usize,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.branch_zero_x(0, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(1, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.instruction(aarch64_add_x_reg(5, 0, 1)?)?;
    assembler.instruction(aarch64_cmp_x(5, 0)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    if caller_scratch_bytes == 0 {
        assembler.branch_zero_x(2, invalid)?;
        assembler.instruction(aarch64_and_low_x(5, 2, 3)?)?;
        assembler.branch_nonzero_x(5, invalid)?;
        assembler.instruction(aarch64_add_x_imm(5, 2, 8)?)?;
        assembler.instruction(aarch64_cmp_x(5, 2)?)?;
        assembler.branch_cond(AARCH64_LO, invalid)?;
        return Ok(());
    }

    assembler.instruction(aarch64_mov_x(6, 5)?)?;
    assembler.branch_zero_x(2, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 2, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    aarch64_load_u64_constant(
        assembler,
        5,
        u64::try_from(caller_scratch_bytes)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 reducer scratch"))?,
    )?;
    assembler.instruction(aarch64_cmp_x(3, 5)?)?;
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(aarch64_add_x_reg(5, 2, 3)?)?;
    assembler.instruction(aarch64_cmp_x(5, 2)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.instruction(aarch64_mov_x(7, 5)?)?;
    let scratch_haystack_disjoint = assembler.label()?;
    assembler.branch_zero_x(1, scratch_haystack_disjoint)?;
    assembler.instruction(aarch64_cmp_x(2, 6)?)?;
    assembler.branch_cond(AARCH64_HS, scratch_haystack_disjoint)?;
    assembler.instruction(aarch64_cmp_x(0, 7)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_haystack_disjoint)?;
    let scratch_output_disjoint = assembler.label()?;
    assembler.instruction(aarch64_add_x_imm(8, 4, 8)?)?;
    assembler.instruction(aarch64_cmp_x(2, 8)?)?;
    assembler.branch_cond(AARCH64_HS, scratch_output_disjoint)?;
    assembler.instruction(aarch64_cmp_x(4, 7)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    assembler.bind(scratch_output_disjoint)?;
    assembler.branch_zero_x(4, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 4, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    assembler.instruction(aarch64_add_x_imm(5, 4, 8)?)?;
    assembler.instruction(aarch64_cmp_x(5, 4)?)?;
    assembler.branch_cond(AARCH64_LO, invalid)?;
    Ok(())
}

fn aarch64_native_capture_reducer_save(
    assembler: &mut Aarch64Assembler,
    frame_bytes: u16,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_sub_x_imm(31, 31, frame_bytes)?)?;
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_store_pair_x(first, second, 31, offset)?)?;
    }
    Ok(())
}

fn aarch64_native_capture_reducer_epilogue(
    assembler: &mut Aarch64Assembler,
    frame_bytes: u16,
) -> Result<(), ObjectError> {
    for (first, second, offset) in [
        (19, 20, 0),
        (21, 22, 16),
        (23, 24, 32),
        (25, 26, 48),
        (27, 28, 64),
        (29, 30, 80),
    ] {
        assembler.instruction(aarch64_load_pair_x(first, second, 31, offset)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "exact selector progress, private replay request, and transactional reduction form one AAPCS64 closure"
)]
fn lower_aarch64_native_participation_reducer_domain_v1(
    group_count: usize,
    participation_scratch_bytes: usize,
    caller_scratch_bytes: usize,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    const FRAME_BYTES: u16 = 208;
    const SPAN_OFFSET: u16 = 96;
    const REQUEST_OFFSET: u16 = 112;
    const SCRATCH_OFFSET: u16 = 176;
    const COUNT_OFFSET: u16 = 192;
    if !(1..=64).contains(&group_count)
        || participation_scratch_bytes == 0
        || (caller_scratch_bytes == 0
            && participation_scratch_bytes
                != crate::NATIVE_PARTICIPATION_AOT_V1_SCRATCH_BYTES)
        || (caller_scratch_bytes != 0
            && caller_scratch_bytes != participation_scratch_bytes)
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 participation reducer group cardinality",
        ));
    }
    let group_count = u16::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 participation groups"))?;
    let mut assembler = Aarch64Assembler::new();
    let loop_head = assembler.label()?;
    let search = assembler.label()?;
    let matched = assembler.label()?;
    let nonempty = assembler.label()?;
    let accepted_empty = assembler.label()?;
    let accepted = assembler.label()?;
    let participation_matched = assembler.label()?;
    let finished = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    aarch64_native_capture_reducer_boundary(
        &mut assembler,
        caller_scratch_bytes,
        invalid,
    )?;
    aarch64_native_capture_reducer_save(&mut assembler, FRAME_BYTES)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(aarch64_mov_x(21, 2)?)?;
    } else {
        assembler.instruction(aarch64_mov_x(21, 4)?)?;
        assembler.instruction(aarch64_store_x(2, 31, SCRATCH_OFFSET)?)?;
        assembler.instruction(aarch64_store_x(3, 31, SCRATCH_OFFSET + 8)?)?;
    }
    assembler.instruction(aarch64_movz_x(22, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(24, 0, 0)?)?;
    assembler.instruction(aarch64_movz_w(25, 0)?)?;

    assembler.bind(loop_head)?;
    assembler.branch_bit_clear_w(25, 1, search)?;
    assembler.instruction(aarch64_movz_w(5, 2)?)?;
    assembler.instruction(aarch64_eor_w(25, 25, 5)?)?;
    assembler.instruction(aarch64_cmp_x(23, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_adds_x_imm(23, 23, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;

    assembler.bind(search)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_mov_x(2, 23)?)?;
    assembler.instruction(aarch64_mov_x(3, 20)?)?;
    assembler.instruction(aarch64_add_x_imm(4, 31, SPAN_OFFSET)?)?;
    let selector_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(returned)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_pair_x(
        5,
        6,
        31,
        i16::try_from(SPAN_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 reducer span"))?,
    )?)?;
    assembler.instruction(aarch64_cmp_x(5, 23)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(6, 5)?)?;
    assembler.branch_cond(AARCH64_LO, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(6, 20)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_NE, nonempty)?;
    assembler.branch_bit_clear_w(25, 0, accepted_empty)?;
    assembler.instruction(aarch64_cmp_x(6, 24)?)?;
    assembler.branch_cond(AARCH64_NE, accepted_empty)?;
    assembler.instruction(aarch64_cmp_x(23, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.instruction(aarch64_adds_x_imm(23, 23, 1)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(search)?;

    assembler.bind(nonempty)?;
    assembler.instruction(aarch64_movz_w(25, 1)?)?;
    assembler.branch(accepted)?;
    assembler.bind(accepted_empty)?;
    assembler.instruction(aarch64_movz_w(25, 3)?)?;
    assembler.bind(accepted)?;
    assembler.instruction(aarch64_mov_x(23, 6)?)?;
    assembler.instruction(aarch64_mov_x(24, 6)?)?;

    let bundle_page = assembler.instruction(0x9000_0007)?; // adrp x7, bundle
    let bundle_page_offset = assembler.instruction(aarch64_add_x_imm(7, 7, 0)?)?;
    assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET)?)?;
    assembler.instruction(aarch64_store_x(19, 31, REQUEST_OFFSET + 8)?)?;
    assembler.instruction(aarch64_store_x(20, 31, REQUEST_OFFSET + 16)?)?;
    assembler.instruction(aarch64_store_x(5, 31, REQUEST_OFFSET + 24)?)?;
    assembler.instruction(aarch64_store_x(6, 31, REQUEST_OFFSET + 32)?)?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(aarch64_add_x_imm(7, 31, SCRATCH_OFFSET)?)?;
        assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET + 40)?)?;
        assembler.instruction(aarch64_movz_x(
            7,
            u16::try_from(participation_scratch_bytes).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 participation reducer scratch")
            })?,
            0,
        )?)?;
        assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET + 48)?)?;
    } else {
        assembler.instruction(aarch64_load_x_imm(7, 31, SCRATCH_OFFSET)?)?;
        assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET + 40)?)?;
        assembler.instruction(aarch64_load_x_imm(7, 31, SCRATCH_OFFSET + 8)?)?;
        assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET + 48)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(7, 31, COUNT_OFFSET)?)?;
    assembler.instruction(aarch64_store_x(7, 31, REQUEST_OFFSET + 56)?)?;
    assembler.instruction(aarch64_add_x_imm(0, 31, REQUEST_OFFSET)?)?;
    let participation_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, participation_matched)?;
    assembler.branch_zero_w(0, runtime_failure)?;
    assembler.branch(returned)?;

    assembler.bind(participation_matched)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, COUNT_OFFSET)?)?;
    assembler.branch_zero_x(5, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x_imm(5, group_count)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_adds_x_reg(22, 22, 5)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(22, 21, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    aarch64_native_capture_reducer_epilogue(&mut assembler, FRAME_BYTES)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [
        selector_call,
        participation_call,
        bundle_page,
        bundle_page_offset,
    ];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeCaptureReducerLoweringV1 {
        code,
        local_calls: vec![
            (offsets[0], NativeCaptureReducerCallTargetV1::Selector),
            (
                offsets[1],
                NativeCaptureReducerCallTargetV1::Participation,
            ),
        ]
        .into_boxed_slice(),
        bundle_relocations: vec![
            (offsets[2], RelocationKind::Aarch64Page21, 0),
            (offsets[3], RelocationKind::Aarch64PageOff12, 0),
        ]
        .into_boxed_slice(),
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "private iterator state, exact capture schema validation, and transactional reduction form one generated AAPCS64 closure"
)]
fn lower_aarch64_native_capture_next_reducer_domain_v1(
    group_count: usize,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    const STATE_OFFSET: u16 = 96;
    const SLOT_OFFSET: u16 = 120;
    if !(1..=16).contains(&group_count) {
        return Err(ObjectError::InvalidModule(
            "AArch64 capture-next reducer group cardinality",
        ));
    }
    let frame_bytes = group_count
        .checked_mul(16)
        .and_then(|bytes| bytes.checked_add(128))
        .and_then(|bytes| u16::try_from(bytes).ok())
        .filter(|bytes| bytes.is_multiple_of(16))
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture reducer frame"))?;
    let group_count_u64 = u64::try_from(group_count)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture reducer groups"))?;
    let mut assembler = Aarch64Assembler::new();
    let loop_head = assembler.label()?;
    let matched = assembler.label()?;
    let finished = assembler.label()?;
    let runtime_failure = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    aarch64_native_capture_reducer_boundary(&mut assembler, 0, invalid)?;
    aarch64_native_capture_reducer_save(&mut assembler, frame_bytes)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_movz_x(22, 0, 0)?)?;
    assembler.instruction(aarch64_store_pair_x(
        31,
        31,
        31,
        i16::try_from(STATE_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture state"))?,
    )?)?;
    assembler.instruction(aarch64_store_x(31, 31, STATE_OFFSET + 16)?)?;

    assembler.bind(loop_head)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_add_x_imm(2, 31, STATE_OFFSET)?)?;
    assembler.instruction(aarch64_add_x_imm(3, 31, SLOT_OFFSET)?)?;
    aarch64_load_u64_constant(&mut assembler, 4, group_count_u64)?;
    let capture_next_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_zero_w(0, finished)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(returned)?;

    assembler.bind(matched)?;
    aarch64_load_u64_constant(&mut assembler, 7, u64::MAX)?;
    assembler.instruction(aarch64_load_pair_x(
        5,
        6,
        31,
        i16::try_from(SLOT_OFFSET)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 group zero"))?,
    )?)?;
    assembler.instruction(aarch64_cmp_x(5, 7)?)?;
    assembler.branch_cond(AARCH64_EQ, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(6, 7)?)?;
    assembler.branch_cond(AARCH64_EQ, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(5, 6)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_cmp_x(6, 20)?)?;
    assembler.branch_cond(AARCH64_HI, runtime_failure)?;
    assembler.instruction(aarch64_movz_x(23, 1, 0)?)?;
    for group in 1..group_count {
        let valid = assembler.label()?;
        let unset = assembler.label()?;
        let offset = SLOT_OFFSET
            .checked_add(
                u16::try_from(group * 16)
                    .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture slot"))?,
            )
            .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture slot"))?;
        assembler.instruction(aarch64_load_pair_x(
            5,
            6,
            31,
            i16::try_from(offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 capture slot"))?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(5, 7)?)?;
        assembler.branch_cond(AARCH64_EQ, unset)?;
        assembler.instruction(aarch64_cmp_x(6, 7)?)?;
        assembler.branch_cond(AARCH64_EQ, runtime_failure)?;
        assembler.instruction(aarch64_cmp_x(5, 6)?)?;
        assembler.branch_cond(AARCH64_HI, runtime_failure)?;
        assembler.instruction(aarch64_load_pair_x(
            8,
            9,
            31,
            i16::try_from(SLOT_OFFSET)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 group zero"))?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(5, 8)?)?;
        assembler.branch_cond(AARCH64_LO, runtime_failure)?;
        assembler.instruction(aarch64_cmp_x(6, 9)?)?;
        assembler.branch_cond(AARCH64_HI, runtime_failure)?;
        assembler.instruction(aarch64_adds_x_imm(23, 23, 1)?)?;
        assembler.branch_cond(AARCH64_HS, runtime_failure)?;
        assembler.branch(valid)?;
        assembler.bind(unset)?;
        assembler.instruction(aarch64_cmp_x(6, 7)?)?;
        assembler.branch_cond(AARCH64_NE, runtime_failure)?;
        assembler.bind(valid)?;
    }
    assembler.instruction(aarch64_adds_x_reg(22, 22, 23)?)?;
    assembler.branch_cond(AARCH64_HS, runtime_failure)?;
    assembler.branch(loop_head)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(22, 21, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(runtime_failure)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    aarch64_native_capture_reducer_epilogue(&mut assembler, frame_bytes)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [capture_next_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeCaptureReducerLoweringV1 {
        code,
        local_calls: vec![(
            offsets[0],
            NativeCaptureReducerCallTargetV1::CaptureNext,
        )]
        .into_boxed_slice(),
        bundle_relocations: Box::new([]),
    })
}

fn lower_aarch64_native_capture_grep_wrapper_v1(
    caller_scratch_bytes: usize,
) -> Result<(Vec<u8>, usize), ObjectError> {
    const COUNT_OFFSET: u16 = 96;
    const SCRATCH_OFFSET: u16 = 104;
    let frame_bytes = if caller_scratch_bytes == 0 { 112 } else { 128 };
    let mut assembler = Aarch64Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let finished = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    aarch64_native_capture_reducer_boundary(
        &mut assembler,
        caller_scratch_bytes,
        invalid,
    )?;
    aarch64_native_capture_reducer_save(&mut assembler, frame_bytes)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(aarch64_mov_x(21, 2)?)?;
    } else {
        assembler.instruction(aarch64_mov_x(21, 4)?)?;
        assembler.instruction(aarch64_store_x(2, 31, SCRATCH_OFFSET)?)?;
        assembler.instruction(aarch64_store_x(3, 31, SCRATCH_OFFSET + 8)?)?;
    }
    assembler.instruction(aarch64_movz_x(22, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?;
    assembler.branch_zero_x(20, finished)?;

    assembler.bind(line_loop)?;
    assembler.instruction(aarch64_mov_x(24, 23)?)?;
    assembler.bind(scan)?;
    assembler.instruction(aarch64_cmp_x(23, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, final_line)?;
    assembler.instruction(aarch64_load_byte_reg(5, 19, 23)?)?;
    assembler.instruction(aarch64_cmp_w_imm(5, 10)?)?;
    assembler.branch_cond(AARCH64_EQ, found_lf)?;
    assembler.instruction(aarch64_adds_x_imm(23, 23, 1)?)?;
    assembler.branch_cond(AARCH64_HS, overflow)?;
    assembler.branch(scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(aarch64_mov_x(25, 23)?)?;
    assembler.instruction(aarch64_adds_x_imm(23, 23, 1)?)?;
    assembler.branch_cond(AARCH64_HS, overflow)?;
    assembler.instruction(aarch64_cmp_x(25, 24)?)?;
    assembler.branch_cond(AARCH64_EQ, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(5, 25, 1)?)?;
    assembler.instruction(aarch64_load_byte_reg(6, 19, 5)?)?;
    assembler.instruction(aarch64_cmp_w_imm(6, 13)?)?;
    assembler.branch_cond(AARCH64_NE, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(25, 25, 1)?)?;
    assembler.branch(line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(aarch64_mov_x(25, 23)?)?;
    assembler.bind(line_ready)?;
    assembler.instruction(aarch64_add_x_reg(0, 19, 24)?)?;
    assembler.instruction(aarch64_sub_x_reg(1, 25, 24)?)?;
    if caller_scratch_bytes == 0 {
        assembler.instruction(aarch64_add_x_imm(2, 31, COUNT_OFFSET)?)?;
    } else {
        assembler.instruction(aarch64_load_x_imm(2, 31, SCRATCH_OFFSET)?)?;
        assembler.instruction(aarch64_load_x_imm(3, 31, SCRATCH_OFFSET + 8)?)?;
        assembler.instruction(aarch64_add_x_imm(4, 31, COUNT_OFFSET)?)?;
    }
    let private_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_nonzero_w(0, returned)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, COUNT_OFFSET)?)?;
    assembler.instruction(aarch64_adds_x_reg(22, 22, 5)?)?;
    assembler.branch_cond(AARCH64_HS, overflow)?;
    assembler.instruction(aarch64_cmp_x(23, 20)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.branch(line_loop)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(22, 21, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    aarch64_native_capture_reducer_epilogue(&mut assembler, frame_bytes)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [private_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok((code, offsets[0]))
}

fn lower_aarch64_native_capture_reducer_v1(
    domain: NativeCaptureReducerDomainV1,
    source: NativeCaptureReducerSourceV1<'_>,
) -> Result<NativeCaptureReducerLoweringV1, ObjectError> {
    let caller_scratch_bytes = source.caller_scratch_bytes();
    let lowered = match source {
        NativeCaptureReducerSourceV1::ExactSpanParticipation {
            group_count,
            participation_scratch_bytes,
            caller_scratch_bytes,
            ..
        } => lower_aarch64_native_participation_reducer_domain_v1(
            group_count,
            participation_scratch_bytes,
            caller_scratch_bytes,
        )?,
        NativeCaptureReducerSourceV1::CaptureNext { group_count, .. } => {
            lower_aarch64_native_capture_next_reducer_domain_v1(group_count)?
        }
    };
    if domain == NativeCaptureReducerDomainV1::WholeHaystack {
        return Ok(lowered);
    }
    let (mut code, private_call) =
        lower_aarch64_native_capture_grep_wrapper_v1(caller_scratch_bytes)?;
    if !code.len().is_multiple_of(4) || !lowered.code.len().is_multiple_of(4) {
        return Err(ObjectError::InvalidModule(
            "AArch64 capture reducer instruction alignment",
        ));
    }
    let private_offset = code.len();
    push_bytes(&mut code, &lowered.code)?;
    let mut local_calls = Vec::new();
    local_calls
        .try_reserve_exact(
            1_usize
                .checked_add(lowered.local_calls.len())
                .ok_or(ObjectError::ArithmeticOverflow("AArch64 capture reducer calls"))?,
        )
        .map_err(|_| ObjectError::Allocation("AArch64 capture reducer calls"))?;
    local_calls.push((
        private_call,
        NativeCaptureReducerCallTargetV1::PrivateDomain(private_offset),
    ));
    for &(offset, target) in lowered.local_calls.iter() {
        local_calls.push((
            private_offset.checked_add(offset).ok_or(
                ObjectError::ArithmeticOverflow("AArch64 capture reducer child call"),
            )?,
            target,
        ));
    }
    let mut bundle_relocations = Vec::new();
    bundle_relocations
        .try_reserve_exact(lowered.bundle_relocations.len())
        .map_err(|_| ObjectError::Allocation("AArch64 capture reducer relocations"))?;
    for &(offset, kind, addend) in lowered.bundle_relocations.iter() {
        bundle_relocations.push((
            private_offset.checked_add(offset).ok_or(
                ObjectError::ArithmeticOverflow("AArch64 capture reducer relocation"),
            )?,
            kind,
            addend,
        ));
    }
    Ok(NativeCaptureReducerLoweringV1 {
        code,
        local_calls: local_calls.into_boxed_slice(),
        bundle_relocations: bundle_relocations.into_boxed_slice(),
    })
}

fn lower_aarch64_uniform_capture_count(
    multiplier: u64,
) -> Result<NativeUniformCaptureReducerWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 32;
    if multiplier == 0 {
        return Err(ObjectError::InvalidModule(
            "uniform capture multiplier is zero",
        ));
    }
    let mut assembler = Aarch64Assembler::new();
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(2, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 3, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(19, 30, 31, 16)?)?;
    assembler.instruction(aarch64_mov_x(19, 3)?)?;
    assembler.instruction(aarch64_add_x_imm(3, 31, 0)?)?;
    let count_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_nonzero_w(0, returned)?;
    assembler.instruction(aarch64_load_x_imm(8, 31, 0)?)?;
    aarch64_load_u64_constant(&mut assembler, 9, multiplier)?;
    assembler.instruction(aarch64_umulh_x(10, 8, 9)?)?;
    assembler.branch_nonzero_x(10, overflow)?;
    assembler.instruction(aarch64_mul_x(8, 8, 9)?)?;
    assembler.instruction(aarch64_store_x(8, 19, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 30, 31, 16)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [count_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeUniformCaptureReducerWrapper {
        code,
        count_call_offsets: offsets.into(),
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "preflight, line splitting, checked scaling, and publication form one native leaf"
)]
fn lower_aarch64_uniform_capture_grep(
    multiplier: u64,
) -> Result<NativeUniformCaptureReducerWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 96;
    if multiplier == 0 {
        return Err(ObjectError::InvalidModule(
            "uniform capture multiplier is zero",
        ));
    }
    let mut assembler = Aarch64Assembler::new();
    let line_loop = assembler.label()?;
    let scan = assembler.label()?;
    let found_lf = assembler.label()?;
    let final_line = assembler.label()?;
    let line_ready = assembler.label()?;
    let finished = assembler.label()?;
    let overflow = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(2, 0)?)?;
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.branch_zero_x(3, invalid)?;
    assembler.instruction(aarch64_and_low_x(7, 3, 3)?)?;
    assembler.branch_nonzero_x(7, invalid)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_store_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_store_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_movz_x(23, 0, 0)?)?;
    assembler.instruction(aarch64_movz_x(25, 0, 0)?)?;

    // Authenticate the Count closure before reading the source line scanner.
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 20)?)?;
    assembler.instruction(aarch64_movz_x(2, 0, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(3, 31, 0)?)?;
    let preflight_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_nonzero_w(0, returned)?;
    assembler.branch_zero_x(21, finished)?;

    assembler.bind(line_loop)?;
    assembler.instruction(aarch64_mov_x(24, 23)?)?;
    assembler.bind(scan)?;
    assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, final_line)?;
    assembler.instruction(aarch64_load_byte_reg(8, 20, 23)?)?;
    assembler.instruction(aarch64_cmp_w_imm(8, 10)?)?;
    assembler.branch_cond(AARCH64_EQ, found_lf)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.branch(scan)?;

    assembler.bind(found_lf)?;
    assembler.instruction(aarch64_mov_x(26, 23)?)?;
    assembler.instruction(aarch64_add_x_imm(23, 23, 1)?)?;
    assembler.instruction(aarch64_cmp_x(26, 24)?)?;
    assembler.branch_cond(AARCH64_EQ, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(8, 26, 1)?)?;
    assembler.instruction(aarch64_load_byte_reg(9, 20, 8)?)?;
    assembler.instruction(aarch64_cmp_w_imm(9, 13)?)?;
    assembler.branch_cond(AARCH64_NE, line_ready)?;
    assembler.instruction(aarch64_sub_x_imm(26, 26, 1)?)?;
    assembler.branch(line_ready)?;

    assembler.bind(final_line)?;
    assembler.instruction(aarch64_mov_x(26, 23)?)?;
    assembler.bind(line_ready)?;
    assembler.instruction(aarch64_sub_x_reg(26, 26, 24)?)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_add_x_reg(1, 20, 24)?)?;
    assembler.instruction(aarch64_mov_x(2, 26)?)?;
    assembler.instruction(aarch64_add_x_imm(3, 31, 0)?)?;
    let line_count_call = assembler.instruction(0x9400_0000)?;
    assembler.branch_nonzero_w(0, returned)?;
    assembler.instruction(aarch64_load_x_imm(8, 31, 0)?)?;
    aarch64_load_u64_constant(&mut assembler, 9, multiplier)?;
    assembler.instruction(aarch64_umulh_x(10, 8, 9)?)?;
    assembler.branch_nonzero_x(10, overflow)?;
    assembler.instruction(aarch64_mul_x(8, 8, 9)?)?;
    assembler.instruction(aarch64_adds_x_reg(25, 25, 8)?)?;
    assembler.branch_cond(AARCH64_HS, overflow)?;
    assembler.instruction(aarch64_cmp_x(23, 21)?)?;
    assembler.branch_cond(AARCH64_EQ, finished)?;
    assembler.branch(line_loop)?;

    assembler.bind(finished)?;
    assembler.instruction(aarch64_store_x(25, 22, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(overflow)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_load_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_load_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_load_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [preflight_call, line_count_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeUniformCaptureReducerWrapper {
        code,
        count_call_offsets: offsets.into(),
    })
}

fn lower_aarch64_prepared_exists_batch() -> Result<NativePreparedBulkWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 112;
    let mut assembler = Aarch64Assembler::new();
    let validated = assembler.label()?;
    let loop_head = assembler.label()?;
    let completed_item = assembler.label()?;
    let complete = assembler.label()?;
    let late_invalid = assembler.label()?;
    let returned = assembler.label()?;
    let invalid_handle = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.branch_zero_x(0, invalid_handle)?;
    assembler.branch_zero_x(4, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 4, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    aarch64_load_u64_constant(&mut assembler, 5, isize::MAX as u64 / 16)?;
    assembler.instruction(aarch64_cmp_x(2, 5)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.branch_zero_x(2, validated)?;
    assembler.branch_zero_x(1, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 1, 3)?)?;
    assembler.branch_nonzero_x(5, invalid)?;
    assembler.branch_zero_x(3, invalid)?;

    assembler.bind(validated)?;
    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_store_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_store_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_store_pair_x(31, 31, 31, 96)?)?;
    assembler.instruction(aarch64_mov_x(19, 0)?)?;
    assembler.instruction(aarch64_mov_x(20, 1)?)?;
    assembler.instruction(aarch64_mov_x(21, 2)?)?;
    assembler.instruction(aarch64_mov_x(22, 3)?)?;
    assembler.instruction(aarch64_mov_x(23, 4)?)?;
    assembler.instruction(aarch64_movz_x(24, 0, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 23, 0)?)?;

    assembler.bind(loop_head)?;
    assembler.branch_zero_x(21, complete)?;
    assembler.instruction(aarch64_load_x_imm(25, 20, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(26, 20, 8)?)?;
    assembler.branch_zero_x(25, late_invalid)?;
    assembler.instruction(aarch64_cmp_x_imm(26, 0)?)?;
    assembler.branch_cond(AARCH64_MI, late_invalid)?;
    assembler.instruction(aarch64_mov_x(0, 19)?)?;
    assembler.instruction(aarch64_mov_x(1, 25)?)?;
    assembler.instruction(aarch64_mov_x(2, 26)?)?;
    assembler.instruction(aarch64_movz_x(3, 0, 0)?)?;
    assembler.instruction(aarch64_mov_x(4, 26)?)?;
    // ADD (immediate) names SP for register 31; the MOV-register alias would
    // name XZR and pass a null result pointer to the prepared search.
    assembler.instruction(aarch64_add_x_imm(5, 31, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(6, 31, 96)?)?;
    let prepared_call = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_LS, completed_item)?;
    assembler.branch(returned)?;

    assembler.bind(completed_item)?;
    assembler.instruction(aarch64_store_byte(0, 22, 0)?)?;
    assembler.instruction(aarch64_add_x_imm(20, 20, 16)?)?;
    assembler.instruction(aarch64_add_x_imm(22, 22, 1)?)?;
    assembler.instruction(aarch64_sub_x_imm(21, 21, 1)?)?;
    assembler.instruction(aarch64_add_x_imm(24, 24, 1)?)?;
    assembler.instruction(aarch64_store_x(24, 23, 0)?)?;
    assembler.branch(loop_head)?;
    assembler.bind(complete)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(returned)?;
    assembler.bind(late_invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(19, 20, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(21, 22, 31, 32)?)?;
    assembler.instruction(aarch64_load_pair_x(23, 24, 31, 48)?)?;
    assembler.instruction(aarch64_load_pair_x(25, 26, 31, 64)?)?;
    assembler.instruction(aarch64_load_pair_x(29, 30, 31, 80)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid_handle)?;
    assembler.instruction(aarch64_movz_w(0, 5)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [prepared_call];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativePreparedBulkWrapper {
        code,
        prepared_call_offset: offsets[0],
        ordered_nfa_gate_call_offset: None,
        bulk_runtime_fallback_offset: None,
        compatibility_identity_relocation: None,
        identity_relocation: None,
    })
}

#[allow(
    dead_code,
    reason = "used by the retained legacy slow-partial compatibility emitter"
)]
fn patch_x86_64_local_call(
    code: &mut [u8],
    displacement_offset: usize,
    target: usize,
) -> Result<(), ObjectError> {
    let instruction_end_offset = displacement_offset
        .checked_add(4)
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 local call instruction end",
        ))?;
    if displacement_offset
        .checked_sub(1)
        .and_then(|opcode| code.get(opcode))
        != Some(&0xe8)
        || code.get(displacement_offset..instruction_end_offset) != Some(&[0, 0, 0, 0])
    {
        return Err(ObjectError::InvalidModule(
            "x86 local call placeholder is malformed",
        ));
    }
    let target = i64::try_from(target)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 local call target"))?;
    let instruction_end = i64::try_from(instruction_end_offset)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 local call source"))?;
    let displacement = target
        .checked_sub(instruction_end)
        .and_then(|displacement| i32::try_from(displacement).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "x86 local call displacement",
        ))?;
    code.get_mut(displacement_offset..instruction_end_offset)
        .ok_or(ObjectError::InvalidModule(
            "x86 local call displacement is outside code",
        ))?
        .copy_from_slice(&displacement.to_le_bytes());
    Ok(())
}

fn x86_emit_static_prefix_epoch_increment_rax(
    assembler: &mut X86Assembler,
    overflow: X86Label,
) -> Result<(), ObjectError> {
    let displacement = u32::try_from(STATIC_PREFIX_INVOCATION_EPOCH_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 static-prefix epoch offset"))?
        .to_le_bytes();
    let mut load = vec![0x48, 0x8b, 0x87]; // mov rax, [rdi + disp32]
    load.extend_from_slice(&displacement);
    assembler.instruction(&load)?;
    assembler.instruction(&[0x48, 0x83, 0xc0, 0x01])?; // add rax, 1
    assembler.branch(&[0x0f, 0x84], overflow)?;
    let mut store = vec![0x48, 0x89, 0x87]; // mov [rdi + disp32], rax
    store.extend_from_slice(&displacement);
    assembler.instruction(&store)?;
    Ok(())
}

fn x86_emit_static_prefix_epoch_increment_r10(
    assembler: &mut X86Assembler,
    overflow: X86Label,
) -> Result<(), ObjectError> {
    let displacement = u32::try_from(STATIC_PREFIX_INVOCATION_EPOCH_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 static-prefix epoch offset"))?
        .to_le_bytes();
    let mut load = vec![0x4c, 0x8b, 0x97]; // mov r10, [rdi + disp32]
    load.extend_from_slice(&displacement);
    assembler.instruction(&load)?;
    assembler.instruction(&[0x49, 0x83, 0xc2, 0x01])?; // add r10, 1
    assembler.branch(&[0x0f, 0x84], overflow)?;
    let mut store = vec![0x4c, 0x89, 0x97]; // mov [rdi + disp32], r10
    store.extend_from_slice(&displacement);
    assembler.instruction(&store)?;
    Ok(())
}

#[allow(
    dead_code,
    clippy::too_many_lines,
    reason = "legacy public ABI checks, local outcomes, and whole-search tail deopt stay contiguous"
)]
fn lower_x86_64_slow_partial_wrapper(
    output: OutputContract,
) -> Result<NativeSlowPartialWrapper, ObjectError> {
    const FRAME_BYTES: u8 = 40;
    let mut assembler = X86Assembler::new();
    let no_match = assembler.label()?;
    let matched = assembler.label()?;
    let deopt = assembler.label()?;
    let invalid = assembler.label()?;

    // Validate the complete public SysV boundary before saving or calling.
    assembler.instruction(&[0x48, 0x85, 0xf6])?; // test length sign bit
    assembler.branch(&[0x0f, 0x88], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xf1])?; // cmp end, length
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x48, 0x39, 0xca])?; // cmp start, end
    assembler.branch(&[0x0f, 0x87], invalid)?;
    assembler.instruction(&[0x4d, 0x85, 0xc0])?; // result != null
    assembler.branch(&[0x0f, 0x84], invalid)?;
    assembler.instruction(&[0x41, 0xf6, 0xc0, 0x07])?; // result alignment
    assembler.branch(&[0x0f, 0x85], invalid)?;
    assembler.instruction(&[0x48, 0x85, 0xff])?; // haystack != null
    assembler.branch(&[0x0f, 0x84], invalid)?;

    // Entry RSP is 8 mod 16; 40 bytes aligns the local core call and saves
    // every original public argument for an exact whole-search restart.
    assembler.instruction(&[0x48, 0x83, 0xec, FRAME_BYTES])?;
    assembler.instruction(&[0x48, 0x89, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x89, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, 0x20])?;

    assembler.instruction(&[0xe8])?;
    let core_call_displacement_label = assembler.label()?;
    assembler.bind(core_call_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x85, 0xc0])?; // status == no match
    assembler.branch(&[0x0f, 0x84], no_match)?;
    assembler.instruction(&[0x83, 0xf8, 0x01])?; // status == local match
    assembler.branch(&[0x0f, 0x84], matched)?;
    assembler.branch(&[0xe9], deopt)?;

    assembler.bind(no_match)?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x20])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x49, 0x89, 0x01])?;
    assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(matched)?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, 0x20])?;
    match output {
        OutputContract::Exists => {
            assembler.instruction(&[0x31, 0xc0])?;
            assembler.instruction(&[0x49, 0x89, 0x01])?;
            assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
        }
        OutputContract::SelectedEnd => {
            assembler.instruction(&[0x4d, 0x89, 0x19])?;
            assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
        }
        OutputContract::Span => {
            assembler.instruction(&[0x4d, 0x89, 0x11])?;
            assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
        }
    }
    assembler.instruction(&[0xb8, 0x01, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(deopt)?;
    assembler.instruction(&[0x48, 0x8b, 0x3c, 0x24])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, 0x08])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, 0x10])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, 0x18])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, 0x20])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, FRAME_BYTES])?;
    // Shift the original public arguments right for runtime(program, ...).
    assembler.instruction(&[0x4d, 0x89, 0xc1])?;
    assembler.instruction(&[0x49, 0x89, 0xc8])?;
    assembler.instruction(&[0x48, 0x89, 0xd1])?;
    assembler.instruction(&[0x48, 0x89, 0xf2])?;
    assembler.instruction(&[0x48, 0x89, 0xfe])?;
    assembler.instruction(&[0x48, 0x8d, 0x3d])?;
    let program_displacement_label = assembler.label()?;
    assembler.bind(program_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0xe9])?;
    let runtime_displacement_label = assembler.label()?;
    assembler.bind(runtime_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;

    assembler.bind(invalid)?;
    assembler.instruction(&[0xb8, 0x02, 0, 0, 0])?;
    assembler.instruction(&[0xc3])?;

    let finished = assembler.finish_with_label_offsets()?;
    let core_call_offset = finished.label_offset(core_call_displacement_label)?;
    let program_displacement = finished.label_offset(program_displacement_label)?;
    let runtime_displacement = finished.label_offset(runtime_displacement_label)?;
    Ok(NativeSlowPartialWrapper {
        code: finished.code,
        relocations: vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    program_displacement,
                    "x86 slow partial program relocation",
                )?,
                kind: RelocationKind::X86PcRelative32,
                symbol: PROGRAM_SYMBOL,
                addend: -4,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    runtime_displacement,
                    "x86 slow partial runtime relocation",
                )?,
                kind: RelocationKind::X86PltRelative32,
                symbol: RUNTIME_SYMBOL,
                addend: -4,
            },
        ],
        core_call_offset,
        ticketless_core_call_offset: None,
        resume_tail_call_offset: None,
        continuation_resume_tail_call_offset: None,
    })
}

/// Lower the prepared half of a transient static-prefix hybrid. Successful
/// native completion returns directly; every retained hole continues through
/// the same prepared handle from its exact frontier and first unconsumed byte.
/// A complete-forward late reverse decline has no descriptor or continuation.
fn lower_x86_64_static_prefix_prepared_wrapper(
    output: OutputContract,
    span_recovery: bool,
    resume_table_addend: Option<i64>,
    defer_preflight: bool,
    input_admission: StaticPrefixInputAdmission,
) -> Result<NativeSlowPartialWrapper, ObjectError> {
    if input_admission.short_native_max.is_some() && resume_table_addend.is_none() {
        return Err(ObjectError::InvalidModule(
            "x86 short static-prefix admission has no resume descriptor",
        ));
    }
    if input_admission.short_native_max.is_some_and(|maximum| {
        maximum == 0 || usize::from(maximum) >= PARTIAL_DFA_MIN_INPUT_BYTES
    }) {
        return Err(ObjectError::InvalidModule(
            "x86 short static-prefix admission is outside the fallback window",
        ));
    }
    let frame_bytes = if defer_preflight { 104 } else { 72 };
    // Deferred holes use their first five frame words as the SysV outgoing
    // identity, descriptor, state, position, and pending arguments for the
    // fused eleven-argument boundary. Eager objects keep their established
    // smaller layout and register-heavy compact continuation call.
    let saved_handle_offset = if defer_preflight { 0x28 } else { 0x10 };
    let saved_haystack_offset = if defer_preflight { 0x30 } else { 0x18 };
    let saved_length_offset = if defer_preflight { 0x38 } else { 0x20 };
    let saved_start_offset = if defer_preflight { 0x40 } else { 0x28 };
    let saved_end_offset = if defer_preflight { 0x48 } else { 0x30 };
    let saved_result_offset = if defer_preflight { 0x50 } else { 0x38 };
    let deferred_state_offset = 0x10;
    let resume_position_offset = if defer_preflight { 0x18 } else { 0x40 };
    let deferred_pending_offset = 0x20;
    let eager_ticketless = !defer_preflight && input_admission.short_native_max.is_some();
    let inline_authenticated_entry = defer_preflight || eager_ticketless;
    let mut assembler = X86Assembler::new();
    let preflight_enter = assembler.label()?;
    let native_match = assembler.label()?;
    let native_no_match = assembler.label()?;
    let native_resume = resume_table_addend.map(|_| assembler.label()).transpose()?;
    let native_span_recovery = span_recovery.then(|| assembler.label()).transpose()?;
    let native_deopt = assembler.label()?;
    let fallback_runtime = assembler.label()?;
    let deferred_short_native_max = defer_preflight
        .then_some(input_admission.short_native_max)
        .flatten();
    let short_window_check = deferred_short_native_max
        .map(|_| assembler.label())
        .transpose()?;
    let short_native_entry = deferred_short_native_max
        .map(|_| assembler.label())
        .transpose()?;
    let ticketless_entry = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_match = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_no_match = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_deopt = eager_ticketless.then(|| assembler.label()).transpose()?;
    let invalid_handle = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let invalid_argument = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let wrong_identity = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let entry_epoch_overflow = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let guard_retire = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let direct_epoch_overflow = (!defer_preflight).then(|| assembler.label()).transpose()?;
    let resume_epoch_overflow = resume_table_addend
        .map(|_| assembler.label())
        .transpose()?;
    let mut retire_displacement_labels = Vec::new();

    if defer_preflight {
        let (Some(invalid_handle), Some(invalid_argument)) =
            (invalid_handle, invalid_argument)
        else {
            return Err(ObjectError::InvalidModule(
                "x86 deferred static-prefix guards are absent",
            ));
        };
        // The deferred route assumes exactly the same unsafe live-allocation
        // contract as the runtime ABI, but validates every raw scalar before
        // its first header or haystack load. Keep handle failure distinct from
        // the remaining argument failures, matching V1/V2 runtime statuses.
        assembler.instruction(&[0x48, 0x85, 0xff])?; // handle != null
        assembler.branch(&[0x0f, 0x84], invalid_handle)?;
        assembler.instruction(&[0x48, 0x85, 0xf6])?; // haystack != null
        assembler.branch(&[0x0f, 0x84], invalid_argument)?;
        assembler.instruction(&[0x48, 0x85, 0xd2])?; // length <= isize::MAX
        assembler.branch(&[0x0f, 0x88], invalid_argument)?;
        assembler.instruction(&[0x49, 0x39, 0xd0])?; // end <= length
        assembler.branch(&[0x0f, 0x87], invalid_argument)?;
        assembler.instruction(&[0x4c, 0x39, 0xc1])?; // start <= end
        assembler.branch(&[0x0f, 0x87], invalid_argument)?;
        assembler.instruction(&[0x4d, 0x85, 0xc9])?; // result != null
        assembler.branch(&[0x0f, 0x84], invalid_argument)?;
        assembler.instruction(&[0x41, 0xf6, 0xc1, 0x07])?; // result alignment
        assembler.branch(&[0x0f, 0x85], invalid_argument)?;
    }

    let deferred_identity_displacement_label = if defer_preflight {
        let wrong_identity = wrong_identity.ok_or(ObjectError::InvalidModule(
            "x86 deferred static-prefix identity guard is absent",
        ))?;
        // PreparedAotRegex is repr(C) and its immutable V6 header is asserted
        // at offset zero. Artifact identity remains stable after the active
        // compact seal is revoked, so this deliberately does not test that
        // seal: retained prefixes remain reusable after earlier side exits.
        assembler.instruction(&[0x48, 0x8d, 0x05])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        for identity_word in 0_usize..4 {
            let word_offset = identity_word
                .checked_mul(core::mem::size_of::<u64>())
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 deferred static-prefix identity word",
                ))?;
            if word_offset == 0 {
                assembler.instruction(&[0x4c, 0x8b, 0x10])?;
            } else {
                assembler.instruction(&[
                    0x4c,
                    0x8b,
                    0x50,
                    u8::try_from(word_offset).map_err(|_| {
                        ObjectError::ArithmeticOverflow(
                            "x86 deferred static-prefix linked identity offset",
                        )
                    })?,
                ])?;
            }
            let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(word_offset)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 deferred static-prefix header identity offset",
                ))?;
            assembler.instruction(&[
                0x4c,
                0x3b,
                0x57,
                u8::try_from(header_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "x86 deferred static-prefix header identity displacement",
                    )
                })?,
            ])?;
            assembler.branch(&[0x0f, 0x85], wrong_identity)?;
        }
        Some(displacement)
    } else {
        None
    };

    if defer_preflight {
        // The immutable identity authenticates this allocation before the
        // first mutable access. Advancing the per-owner generation makes any
        // capability left by an earlier invocation stale without adding a
        // helper call to the ordinary native path.
        x86_emit_static_prefix_epoch_increment_r10(
            &mut assembler,
            entry_epoch_overflow.ok_or(ObjectError::InvalidModule(
                "x86 deferred static-prefix epoch guard is absent",
            ))?,
        )?;
    }

    // Unproved short windows retain the ordinary prepared path, but only
    // after the deferred entry has authenticated the exact artifact and
    // invalidated capabilities from prior invocations. A proved window jumps
    // back to the unchanged native entry from a cold check below the fallback
    // tail. All public argument registers remain intact on either route.
    let minimum = u32::try_from(PARTIAL_DFA_MIN_INPUT_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("static-prefix input admission floor"))?;
    let mut compare_minimum = if defer_preflight {
        assembler.instruction(&[0x4d, 0x89, 0xc2])?; // mov r10, r8
        assembler.instruction(&[0x49, 0x29, 0xca])?; // sub r10, rcx
        vec![0x49, 0x81, 0xfa] // cmp r10, imm32
    } else {
        assembler.instruction(&[0x4c, 0x89, 0xc0])?; // mov rax, r8
        assembler.instruction(&[0x48, 0x29, 0xc8])?; // sub rax, rcx
        vec![0x48, 0x3d] // cmp rax, imm32
    };
    compare_minimum.extend_from_slice(&minimum.to_le_bytes());
    assembler.instruction(&compare_minimum)?;
    assembler.branch(
        &[0x0f, 0x82],
        if defer_preflight {
            short_window_check.unwrap_or(fallback_runtime)
        } else {
            ticketless_entry.unwrap_or(fallback_runtime)
        },
    )?;
    if let Some(short_native_entry) = short_native_entry {
        assembler.bind(short_native_entry)?;
    }

    // Entry RSP is 8 modulo 16. Both frame sizes align helper calls and keep
    // all six prepared arguments plus the two outgoing identity/descriptor
    // slots. The deferred frame adds three private words so a hole can retain
    // its frontier across lazy admission.
    assembler.instruction(&[0x48, 0x83, 0xec, frame_bytes])?;
    assembler.instruction(&[0x48, 0x89, 0x7c, 0x24, saved_handle_offset])?;
    assembler.instruction(&[0x48, 0x89, 0x74, 0x24, saved_haystack_offset])?;
    assembler.instruction(&[0x48, 0x89, 0x54, 0x24, saved_length_offset])?;
    assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, saved_start_offset])?;
    assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, saved_end_offset])?;
    assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, saved_result_offset])?;
    let identity_displacement_label = if let Some(displacement) =
        deferred_identity_displacement_label
    {
        displacement
    } else {
        assembler.instruction(&[0x48, 0x8d, 0x05])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        displacement
    };
    assembler.instruction(&[0x48, 0x89, 0x04, 0x24])?;
    let resume_descriptor_displacement_label = if resume_table_addend.is_some() {
        assembler.instruction(&[0x48, 0x8d, 0x05])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x08])?;
        Some(displacement)
    } else {
        None
    };
    let eager_preflight_displacement_label = if defer_preflight {
        None
    } else {
        assembler.instruction(&[0xe8])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        assembler.instruction(&[0x83, 0xf8, PARTIAL_PREFLIGHT_ENTER_STATUS])?;
        assembler.branch(&[0x0f, 0x84], preflight_enter)?;
        assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
        assembler.instruction(&[0xc3])?;
        Some(displacement)
    };

    assembler.bind(preflight_enter)?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_haystack_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_length_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_start_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_end_offset])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_result_offset])?;
    assembler.instruction(&[0xe8])?;
    let core_call_displacement_label = assembler.label()?;
    assembler.bind(core_call_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x83, 0xf8, 1])?;
    assembler.branch(&[0x0f, 0x84], native_match)?;
    assembler.instruction(&[0x85, 0xc0])?;
    assembler.branch(&[0x0f, 0x84], native_no_match)?;
    if let Some(native_resume) = native_resume {
        assembler.instruction(&[
            0x83,
            0xf8,
            u8::try_from(NATIVE_PARTIAL_STATUS_RESUME)
                .map_err(|_| ObjectError::ArithmeticOverflow("static-prefix resume status"))?,
        ])?;
        assembler.branch(&[0x0f, 0x84], native_resume)?;
    }
    if let Some(native_span_recovery) = native_span_recovery {
        assembler.instruction(&[
            0x83,
            0xf8,
            u8::try_from(NATIVE_PARTIAL_STATUS_SELECTED_END).map_err(|_| {
                ObjectError::ArithmeticOverflow("static-prefix Span recovery status")
            })?,
        ])?;
        assembler.branch(&[0x0f, 0x84], native_span_recovery)?;
    }
    assembler.branch(&[0xe9], native_deopt)?;

    assembler.bind(native_no_match)?;
    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        // Eager V2 admission minted a capability at the current generation.
        // Retire it by generation before publishing a direct result.
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        x86_emit_static_prefix_epoch_increment_rax(&mut assembler, direct_epoch_overflow)?;
    }
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
    assembler.instruction(&[0x31, 0xc0])?;
    assembler.instruction(&[0x49, 0x89, 0x01])?;
    assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
    assembler.instruction(&[0xc3])?;

    assembler.bind(native_match)?;
    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        // RAX is scratch here; R10/R11 retain the selected native endpoints.
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        x86_emit_static_prefix_epoch_increment_rax(&mut assembler, direct_epoch_overflow)?;
    }
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
    match output {
        OutputContract::Exists => {
            assembler.instruction(&[0x31, 0xc0])?;
            assembler.instruction(&[0x49, 0x89, 0x01])?;
            assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
        }
        OutputContract::SelectedEnd => {
            assembler.instruction(&[0x4d, 0x89, 0x19])?;
            assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
        }
        OutputContract::Span => {
            assembler.instruction(&[0x4d, 0x89, 0x11])?;
            assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
        }
    }
    assembler.instruction(&[0xb8, 1, 0, 0, 0])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
    assembler.instruction(&[0xc3])?;

    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        assembler.bind(direct_epoch_overflow)?;
        assembler.instruction(&[
            0xbe,
            PREPARED_RUNTIME_FAILURE_STATUS,
            0,
            0,
            0,
        ])?; // mov esi, runtime failure
        assembler.instruction(&[0xe8])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        retire_displacement_labels.push(displacement);
        assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
        assembler.instruction(&[0xc3])?;
    }

    let span_recovery_displacement_label = if let Some(native_span_recovery) = native_span_recovery {
        assembler.bind(native_span_recovery)?;
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
        assembler.instruction(&[0x4c, 0x89, 0x5c, 0x24, 0x08])?;
        if defer_preflight {
            assembler.instruction(&[0x48, 0x8b, 0x87])?;
            push_bytes(
                &mut assembler.code,
                &u32::try_from(STATIC_PREFIX_INVOCATION_EPOCH_OFFSET)
                    .map_err(|_| {
                        ObjectError::ArithmeticOverflow(
                            "x86 lazy static-prefix Span epoch offset",
                        )
                    })?
                    .to_le_bytes(),
            )?;
            assembler.instruction(&[0x48, 0x89, 0x44, 0x24, 0x10])?;
        }
        assembler.instruction(&[0xe8])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
        assembler.instruction(&[0xc3])?;
        Some(displacement)
    } else {
        None
    };

    let mut resume_tail_call_displacement_label = None;
    let mut continuation_resume_tail_call_displacement_label = None;
    let resume_runtime_displacement_label = if let Some(native_resume) = native_resume {
        assembler.bind(native_resume)?;
        // The native core returns resume state in r10, first unconsumed
        // position in rdx, and the pending endpoint word in r11. The canonical
        // descriptor determines whether that last word is meaningful.
        assembler.instruction(&[
            0x48,
            0x89,
            0x54,
            0x24,
            resume_position_offset,
        ])?;
        let resume_return = assembler.label()?;
        if defer_preflight {
            // The first five frame words are the outgoing stack arguments for
            // identity, descriptor, state, position, and pending endpoint.
            // One helper call now authenticates and consumes the hole.
            assembler.instruction(&[
                0x4c,
                0x89,
                0x54,
                0x24,
                deferred_state_offset,
            ])?;
            assembler.instruction(&[
                0x4c,
                0x89,
                0x5c,
                0x24,
                deferred_pending_offset,
            ])?;
            assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
            assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
            assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
        } else {
            assembler.instruction(&[0x4c, 0x89, 0x1c, 0x24])?;
            assembler.instruction(&[0x49, 0x89, 0xd1])?;
            assembler.instruction(&[0x4d, 0x89, 0xd0])?;
            assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_result_offset])?;
        }
        assembler.instruction(&[0xe8])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        let continuation_resume = assembler.label()?;
        assembler.instruction(&[
            0x83,
            0xf8,
            STATIC_PREFIX_NATIVE_CONTINUATION_RESUME_STATUS,
        ])?;
        assembler.branch(&[0x0f, 0x84], continuation_resume)?;
        assembler.instruction(&[0x83, 0xf8, STATIC_PREFIX_NATIVE_RESUME_STATUS])?;
        assembler.branch(&[0x0f, 0x85], resume_return)?;
        // Reconstitute the ordinary prepared arguments and pass the three
        // private continuation words in R10 (cursor), R11 (canonical state),
        // and RAX (zero-or-pending endpoint) to the appended local tail.
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, resume_position_offset])?;
        assembler.instruction(&[0x4d, 0x8b, 0x19])?;
        assembler.instruction(&[0x49, 0x8b, 0x41, 0x08])?;
        assembler.instruction(&[0xe8])?;
        let tail_call = assembler.label()?;
        assembler.bind(tail_call)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        resume_tail_call_displacement_label = Some(tail_call);
        assembler.branch(&[0xe9], resume_return)?;

        assembler.bind(continuation_resume)?;
        // Status 8 keeps the public owner base in RDI. The distinct local
        // side entry selects its fixed +664 header after saving that base for
        // fallback and variable-Span recovery helpers.
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
        assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
        assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, resume_position_offset])?;
        assembler.instruction(&[0x4d, 0x8b, 0x19])?;
        assembler.instruction(&[0x49, 0x8b, 0x41, 0x08])?;
        assembler.instruction(&[0xe8])?;
        let continuation_tail_call = assembler.label()?;
        assembler.bind(continuation_tail_call)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        continuation_resume_tail_call_displacement_label = Some(continuation_tail_call);
        assembler.bind(resume_return)?;
        assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
        x86_emit_static_prefix_epoch_increment_r10(
            &mut assembler,
            resume_epoch_overflow.ok_or(ObjectError::InvalidModule(
                "x86 static-prefix resume epoch overflow label is absent",
            ))?,
        )?;
        assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
        assembler.instruction(&[0xc3])?;
        assembler.bind(resume_epoch_overflow.ok_or(ObjectError::InvalidModule(
            "x86 static-prefix resume epoch overflow label is absent",
        ))?)?;
        assembler.instruction(&[0x89, 0xc6])?; // mov esi, eax
        assembler.instruction(&[0xe8])?;
        let retire_displacement = assembler.label()?;
        assembler.bind(retire_displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        retire_displacement_labels.push(retire_displacement);
        assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
        assembler.instruction(&[0xc3])?;
        Some(displacement)
    } else {
        None
    };

    assembler.bind(native_deopt)?;
    assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
    assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
    assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
    assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
    assembler.instruction(&[0xe8])?;
    let deopt_displacement_label = assembler.label()?;
    assembler.bind(deopt_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
    assembler.instruction(&[0xc3])?;

    if let Some(invalid_handle) = invalid_handle {
        assembler.bind(invalid_handle)?;
        assembler.instruction(&[0xb8, PREPARED_INVALID_HANDLE_STATUS, 0, 0, 0])?;
        assembler.instruction(&[0xc3])?;
    }
    if let Some(invalid_argument) = invalid_argument {
        assembler.bind(invalid_argument)?;
        assembler.instruction(&[
            0xbe,
            PREPARED_INVALID_ARGUMENT_STATUS,
            0,
            0,
            0,
        ])?; // mov esi, invalid argument
        assembler.branch(
            &[0xe9],
            guard_retire.ok_or(ObjectError::InvalidModule(
                "x86 static-prefix guard retirement label is absent",
            ))?,
        )?;
    }
    if let Some(wrong_identity) = wrong_identity {
        assembler.bind(wrong_identity)?;
        assembler.instruction(&[
            0xbe,
            PREPARED_RUNTIME_FAILURE_STATUS,
            0,
            0,
            0,
        ])?; // mov esi, runtime failure
        assembler.branch(
            &[0xe9],
            guard_retire.ok_or(ObjectError::InvalidModule(
                "x86 static-prefix guard retirement label is absent",
            ))?,
        )?;
    }
    if let Some(entry_epoch_overflow) = entry_epoch_overflow {
        assembler.bind(entry_epoch_overflow)?;
        assembler.instruction(&[
            0xbe,
            PREPARED_RUNTIME_FAILURE_STATUS,
            0,
            0,
            0,
        ])?; // mov esi, runtime failure
        assembler.branch(
            &[0xe9],
            guard_retire.ok_or(ObjectError::InvalidModule(
                "x86 static-prefix guard retirement label is absent",
            ))?,
        )?;
    }
    if let Some(guard_retire) = guard_retire {
        assembler.bind(guard_retire)?;
        assembler.instruction(&[0xe9])?;
        let displacement = assembler.label()?;
        assembler.bind(displacement)?;
        push_bytes(&mut assembler.code, &[0; 4])?;
        retire_displacement_labels.push(displacement);
    }

    assembler.bind(fallback_runtime)?;
    assembler.instruction(&[0xe9])?;
    let fallback_displacement_label = assembler.label()?;
    assembler.bind(fallback_displacement_label)?;
    push_bytes(&mut assembler.code, &[0; 4])?;
    if let (Some(short_window_check), Some(short_native_entry), Some(short_native_max)) = (
        short_window_check,
        short_native_entry,
        deferred_short_native_max,
    ) {
        assembler.bind(short_window_check)?;
        let mut compare_short = vec![0x49, 0x81, 0xfa]; // cmp r10, imm32
        compare_short.extend_from_slice(&u32::from(short_native_max).to_le_bytes());
        assembler.instruction(&compare_short)?;
        assembler.branch(&[0x0f, 0x86], short_native_entry)?; // len <= h
        assembler.branch(&[0xe9], fallback_runtime)?;
    }

    let (ticketless_identity_displacement_label, ticketless_core_call_displacement_label) =
        if let (
            Some(ticketless_entry),
            Some(ticketless_match),
            Some(ticketless_no_match),
            Some(ticketless_deopt),
            Some(short_native_max),
            Some(invalid_handle),
            Some(invalid_argument),
            Some(wrong_identity),
            Some(entry_epoch_overflow),
        ) = (
            ticketless_entry,
            ticketless_match,
            ticketless_no_match,
            ticketless_deopt,
            input_admission.short_native_max,
            invalid_handle,
            invalid_argument,
            wrong_identity,
            entry_epoch_overflow,
        ) {
            assembler.bind(ticketless_entry)?;
            // This cold edge is reached only by an eager window below the
            // ordinary crossover. Validate every public scalar before the
            // first owner or haystack load, then authenticate the exact linked
            // object just as the proof-free entry does.
            assembler.instruction(&[0x48, 0x85, 0xff])?; // handle != null
            assembler.branch(&[0x0f, 0x84], invalid_handle)?;
            assembler.instruction(&[0x48, 0x85, 0xf6])?; // haystack != null
            assembler.branch(&[0x0f, 0x84], invalid_argument)?;
            assembler.instruction(&[0x48, 0x85, 0xd2])?; // length <= isize::MAX
            assembler.branch(&[0x0f, 0x88], invalid_argument)?;
            assembler.instruction(&[0x49, 0x39, 0xd0])?; // end <= length
            assembler.branch(&[0x0f, 0x87], invalid_argument)?;
            assembler.instruction(&[0x4c, 0x39, 0xc1])?; // start <= end
            assembler.branch(&[0x0f, 0x87], invalid_argument)?;
            assembler.instruction(&[0x4d, 0x85, 0xc9])?; // result != null
            assembler.branch(&[0x0f, 0x84], invalid_argument)?;
            assembler.instruction(&[0x41, 0xf6, 0xc1, 0x07])?; // result alignment
            assembler.branch(&[0x0f, 0x85], invalid_argument)?;

            assembler.instruction(&[0x48, 0x8d, 0x05])?;
            let identity_displacement = assembler.label()?;
            assembler.bind(identity_displacement)?;
            push_bytes(&mut assembler.code, &[0; 4])?;
            for identity_word in 0_usize..4 {
                let word_offset = identity_word
                    .checked_mul(core::mem::size_of::<u64>())
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 ticketless static-prefix identity word",
                    ))?;
                if word_offset == 0 {
                    assembler.instruction(&[0x4c, 0x8b, 0x10])?;
                } else {
                    assembler.instruction(&[
                        0x4c,
                        0x8b,
                        0x50,
                        u8::try_from(word_offset).map_err(|_| {
                            ObjectError::ArithmeticOverflow(
                                "x86 ticketless static-prefix linked identity offset",
                            )
                        })?,
                    ])?;
                }
                let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                    .checked_add(word_offset)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "x86 ticketless static-prefix header identity offset",
                    ))?;
                assembler.instruction(&[
                    0x4c,
                    0x3b,
                    0x57,
                    u8::try_from(header_offset).map_err(|_| {
                        ObjectError::ArithmeticOverflow(
                            "x86 ticketless static-prefix header identity displacement",
                        )
                    })?,
                ])?;
                assembler.branch(&[0x0f, 0x85], wrong_identity)?;
            }
            x86_emit_static_prefix_epoch_increment_r10(
                &mut assembler,
                entry_epoch_overflow,
            )?;
            assembler.instruction(&[0x4d, 0x89, 0xc2])?; // mov r10, r8
            assembler.instruction(&[0x49, 0x29, 0xca])?; // sub r10, rcx
            let mut compare_short = vec![0x49, 0x81, 0xfa]; // cmp r10, h
            compare_short.extend_from_slice(&u32::from(short_native_max).to_le_bytes());
            assembler.instruction(&compare_short)?;
            assembler.branch(&[0x0f, 0x87], fallback_runtime)?; // len > h

            // No ticket is minted. Save the ordinary eager frame solely for
            // direct result publication or a semantic whole-window side exit.
            assembler.instruction(&[0x48, 0x83, 0xec, frame_bytes])?;
            assembler.instruction(&[0x48, 0x89, 0x7c, 0x24, saved_handle_offset])?;
            assembler.instruction(&[0x48, 0x89, 0x74, 0x24, saved_haystack_offset])?;
            assembler.instruction(&[0x48, 0x89, 0x54, 0x24, saved_length_offset])?;
            assembler.instruction(&[0x48, 0x89, 0x4c, 0x24, saved_start_offset])?;
            assembler.instruction(&[0x4c, 0x89, 0x44, 0x24, saved_end_offset])?;
            assembler.instruction(&[0x4c, 0x89, 0x4c, 0x24, saved_result_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_haystack_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_length_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_start_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_end_offset])?;
            assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_result_offset])?;
            assembler.instruction(&[0xe8])?;
            let core_call = assembler.label()?;
            assembler.bind(core_call)?;
            push_bytes(&mut assembler.code, &[0; 4])?;
            assembler.instruction(&[0x83, 0xf8, 1])?;
            assembler.branch(&[0x0f, 0x84], ticketless_match)?;
            assembler.instruction(&[0x85, 0xc0])?;
            assembler.branch(&[0x0f, 0x84], ticketless_no_match)?;
            // Resume, selected-end recovery, and every unknown private status
            // are impossible inside the first-hole proof and fail over to the
            // whole-window semantic engine without consuming a capability.
            assembler.branch(&[0xe9], ticketless_deopt)?;

            assembler.bind(ticketless_no_match)?;
            assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
            assembler.instruction(&[0x31, 0xc0])?;
            assembler.instruction(&[0x49, 0x89, 0x01])?;
            assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
            assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
            assembler.instruction(&[0xc3])?;

            assembler.bind(ticketless_match)?;
            assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
            match output {
                OutputContract::Exists => {
                    assembler.instruction(&[0x31, 0xc0])?;
                    assembler.instruction(&[0x49, 0x89, 0x01])?;
                    assembler.instruction(&[0x49, 0x89, 0x41, 0x08])?;
                }
                OutputContract::SelectedEnd => {
                    assembler.instruction(&[0x4d, 0x89, 0x19])?;
                    assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
                }
                OutputContract::Span => {
                    assembler.instruction(&[0x4d, 0x89, 0x11])?;
                    assembler.instruction(&[0x4d, 0x89, 0x59, 0x08])?;
                }
            }
            assembler.instruction(&[0xb8, 1, 0, 0, 0])?;
            assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
            assembler.instruction(&[0xc3])?;

            assembler.bind(ticketless_deopt)?;
            assembler.instruction(&[0x48, 0x8b, 0x7c, 0x24, saved_handle_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x74, 0x24, saved_haystack_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x54, 0x24, saved_length_offset])?;
            assembler.instruction(&[0x48, 0x8b, 0x4c, 0x24, saved_start_offset])?;
            assembler.instruction(&[0x4c, 0x8b, 0x44, 0x24, saved_end_offset])?;
            assembler.instruction(&[0x4c, 0x8b, 0x4c, 0x24, saved_result_offset])?;
            assembler.instruction(&[0x48, 0x83, 0xc4, frame_bytes])?;
            assembler.branch(&[0xe9], fallback_runtime)?;
            (Some(identity_displacement), Some(core_call))
        } else {
            (None, None)
        };

    let finished = assembler.finish_with_label_offsets()?;
    let identity_displacement = finished.label_offset(identity_displacement_label)?;
    let resume_descriptor_displacement = resume_descriptor_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let preflight_displacement = eager_preflight_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let core_call_offset = finished.label_offset(core_call_displacement_label)?;
    let ticketless_core_call_offset = ticketless_core_call_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let ticketless_identity_displacement = ticketless_identity_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let deopt_displacement = finished.label_offset(deopt_displacement_label)?;
    let fallback_displacement = finished.label_offset(fallback_displacement_label)?;
    let resume_runtime_displacement = resume_runtime_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let span_recovery_displacement = span_recovery_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let resume_tail_call_offset = resume_tail_call_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let continuation_resume_tail_call_offset = continuation_resume_tail_call_displacement_label
        .map(|label| finished.label_offset(label))
        .transpose()?;
    let retire_displacements = retire_displacement_labels
        .into_iter()
        .map(|label| finished.label_offset(label))
        .collect::<Result<Vec<_>, _>>()?;
    let mut relocations = vec![ModuleRelocation {
        section: TEXT_SECTION,
        offset: offset_u64(identity_displacement, "x86 static-prefix identity relocation")?,
        kind: RelocationKind::X86PcRelative32,
        symbol: PARTIAL_IDENTITY_SYMBOL,
        addend: -4,
    }];
    if let Some(ticketless_identity_displacement) = ticketless_identity_displacement {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                ticketless_identity_displacement,
                "x86 ticketless static-prefix identity relocation",
            )?,
            kind: RelocationKind::X86PcRelative32,
            symbol: PARTIAL_IDENTITY_SYMBOL,
            addend: -4,
        });
    }
    if let Some(preflight_displacement) = preflight_displacement {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(preflight_displacement, "x86 static-prefix preflight relocation")?,
            kind: RelocationKind::X86PltRelative32,
            symbol: PREPARED_PREFLIGHT_RUNTIME_SYMBOL,
            addend: -4,
        });
    }
    relocations.extend([
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(deopt_displacement, "x86 static-prefix deopt relocation")?,
            kind: RelocationKind::X86PltRelative32,
            symbol: PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: -4,
        },
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(fallback_displacement, "x86 static-prefix fallback relocation")?,
            kind: RelocationKind::X86PltRelative32,
            symbol: PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: -4,
        },
    ]);
    if let (Some(descriptor_displacement), Some(runtime_displacement), Some(table_addend)) = (
        resume_descriptor_displacement,
        resume_runtime_displacement,
        resume_table_addend,
    ) {
        relocations.extend([
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    descriptor_displacement,
                    "x86 static-prefix resume descriptor relocation",
                )?,
                kind: RelocationKind::X86PcRelative32,
                symbol: PARTIAL_TABLE_SYMBOL,
                addend: table_addend.checked_sub(4).ok_or(
                    ObjectError::ArithmeticOverflow(
                        "x86 static-prefix resume descriptor relocation addend",
                    ),
                )?,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    runtime_displacement,
                    "x86 static-prefix continuation relocation",
                )?,
                kind: RelocationKind::X86PltRelative32,
                symbol: PARTIAL_RUNTIME_SYMBOL,
                addend: -4,
            },
        ]);
    } else if resume_descriptor_displacement.is_some()
        || resume_runtime_displacement.is_some()
        || resume_table_addend.is_some()
    {
        return Err(ObjectError::InvalidModule(
            "x86 static-prefix resume lowering is incomplete",
        ));
    }
    if let Some(span_recovery_displacement) = span_recovery_displacement {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                span_recovery_displacement,
                "x86 static-prefix Span recovery relocation",
            )?,
            kind: RelocationKind::X86PltRelative32,
            symbol: if defer_preflight {
                STATIC_PREFIX_LAZY_SPAN_RECOVERY_RUNTIME_SYMBOL
            } else {
                PARTIAL_SPAN_RECOVERY_RUNTIME_SYMBOL
            },
            addend: -4,
        });
    }
    for retire_displacement in retire_displacements {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                retire_displacement,
                "x86 static-prefix retirement relocation",
            )?,
            kind: RelocationKind::X86PltRelative32,
            symbol: STATIC_PREFIX_RETIRE_RUNTIME_SYMBOL,
            addend: -4,
        });
    }
    Ok(NativeSlowPartialWrapper {
        code: finished.code,
        relocations,
        core_call_offset,
        ticketless_core_call_offset,
        resume_tail_call_offset,
        continuation_resume_tail_call_offset,
    })
}

/// Per-call authentication policy for one already-published compact
/// V3 through V14 compact projection selected by its exact generation tag.
///
/// Production exclusive handles use an active-capability mode: construction
/// fully validates the private immutable owner before publishing both seals,
/// and every route that can mutate capability-owned state clears the active
/// seal first. Reverse-only variable-Span postflight reads only the separately
/// authenticated live reverse projection (and fallback mutates disjoint K0
/// scratch), so it retains the immutable owner on success.
/// Fixed-width SIMD modes preserve that proof while comparing the exact
/// artifact identity with one branch. Portable AArch64 targets retain the
/// scalar capability because ASIMD is an explicit target feature in this
/// crate; x86-64 always has the SSE2 baseline.
/// `FullVerifier` remains available to audit the complete descriptor geometry
/// and to preserve fail-closed codegen coverage independently of that
/// lifecycle proof.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(
    dead_code,
    reason = "the full verifier remains an explicit non-production audit and test path"
)]
enum FrozenCompactGuardMode {
    ActiveCapability,
    ActiveCapabilitySimdIdentity,
    ActiveCapabilityAvx2Identity,
    ActiveCapabilityReverseSupertransition,
    ActiveCapabilitySimdIdentityReverseSupertransition,
    ActiveCapabilityAvx2IdentityReverseSupertransition,
    FullVerifier,
    FullVerifierVariableSpan(u16),
}

impl FrozenCompactGuardMode {
    const fn is_full_verifier(self) -> bool {
        matches!(self, Self::FullVerifier | Self::FullVerifierVariableSpan(_))
    }

    const fn variable_span_source_class_count(self) -> Option<u16> {
        match self {
            Self::FullVerifierVariableSpan(source_class_count) => Some(source_class_count),
            Self::ActiveCapability
            | Self::ActiveCapabilitySimdIdentity
            | Self::ActiveCapabilityAvx2Identity
            | Self::ActiveCapabilityReverseSupertransition
            | Self::ActiveCapabilitySimdIdentityReverseSupertransition
            | Self::ActiveCapabilityAvx2IdentityReverseSupertransition
            | Self::FullVerifier => None,
        }
    }

    const fn uses_simd_identity(self) -> bool {
        matches!(
            self,
            Self::ActiveCapabilitySimdIdentity
                | Self::ActiveCapabilityAvx2Identity
                | Self::ActiveCapabilitySimdIdentityReverseSupertransition
                | Self::ActiveCapabilityAvx2IdentityReverseSupertransition
        )
    }

    const fn uses_x86_avx2_identity(self) -> bool {
        matches!(
            self,
            Self::ActiveCapabilityAvx2Identity
                | Self::ActiveCapabilityAvx2IdentityReverseSupertransition
        )
    }

    const fn expects_reverse_supertransition(self) -> bool {
        matches!(
            self,
            Self::ActiveCapabilityReverseSupertransition
                | Self::ActiveCapabilitySimdIdentityReverseSupertransition
                | Self::ActiveCapabilityAvx2IdentityReverseSupertransition
        )
    }
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FrozenCompactNativeFormat {
    StateOrdinalV3,
    CellOffsetV4,
    UnaryExistsV5,
    StateOrdinalV6,
    CellOffsetV7,
    StateOrdinalDirectV8,
    #[allow(
        dead_code,
        reason = "V9 remains a standalone compatibility-verifier format without a production entry"
    )]
    CellOffsetDirectV9,
    StateOrdinalDirectU8V10,
    PairSupertransitionV11,
    StateOrdinalMappedU8V12,
    DensePairSupertransitionV13,
    DenseQuadSupertransitionV14,
}

fn x86_emit_movq_xmm_from_gpr(
    assembler: &mut X86Assembler,
    xmm: u8,
    gpr: u8,
) -> Result<(), ObjectError> {
    if xmm >= 16 || gpr >= 16 {
        return Err(ObjectError::InvalidModule(
            "x86 MOVQ register is outside the baseline register bank",
        ));
    }
    let rex = 0x48 | ((xmm >> 3) << 2) | (gpr >> 3);
    let modrm = 0xc0 | ((xmm & 7) << 3) | (gpr & 7);
    assembler.instruction(&[0x66, rex, 0x0f, 0x6e, modrm])?;
    Ok(())
}

fn x86_emit_movq_gpr_from_xmm(
    assembler: &mut X86Assembler,
    gpr: u8,
    xmm: u8,
) -> Result<(), ObjectError> {
    if xmm >= 16 || gpr >= 16 {
        return Err(ObjectError::InvalidModule(
            "x86 MOVQ register is outside the baseline register bank",
        ));
    }
    let rex = 0x48 | ((xmm >> 3) << 2) | (gpr >> 3);
    let modrm = 0xc0 | ((xmm & 7) << 3) | (gpr & 7);
    assembler.instruction(&[0x66, rex, 0x0f, 0x7e, modrm])?;
    Ok(())
}

impl FrozenCompactNativeFormat {
    const fn flag(self) -> u32 {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4,
            Self::UnaryExistsV5 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5,
            Self::StateOrdinalV6 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V6,
            Self::CellOffsetV7 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V7,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9,
            Self::StateOrdinalDirectU8V10 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10,
            Self::PairSupertransitionV11 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11
            }
            Self::StateOrdinalMappedU8V12 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12,
            Self::DensePairSupertransitionV13 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13
            }
            Self::DenseQuadSupertransitionV14 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14
            }
        }
    }

    const fn header_bytes(self) -> usize {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V3_BYTES,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V4_BYTES,
            Self::UnaryExistsV5 => FROZEN_PREPARED_HEADER_V5_BYTES,
            Self::StateOrdinalV6 => FROZEN_PREPARED_HEADER_V6_BYTES,
            Self::CellOffsetV7 => FROZEN_PREPARED_HEADER_V7_BYTES,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V8_BYTES,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V9_BYTES,
            Self::StateOrdinalDirectU8V10 => FROZEN_PREPARED_HEADER_V10_BYTES,
            Self::PairSupertransitionV11 => FROZEN_PREPARED_HEADER_V11_BYTES,
            Self::StateOrdinalMappedU8V12 => FROZEN_PREPARED_HEADER_V12_BYTES,
            Self::DensePairSupertransitionV13 => FROZEN_PREPARED_HEADER_V13_BYTES,
            Self::DenseQuadSupertransitionV14 => FROZEN_PREPARED_HEADER_V14_BYTES,
        }
    }

    const fn tail_offset(self) -> usize {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V3_DYNAMIC_ROWS_OFFSET,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V4_DYNAMIC_ROWS_OFFSET,
            Self::UnaryExistsV5 => FROZEN_PREPARED_HEADER_V5_DYNAMIC_ROWS_OFFSET,
            Self::StateOrdinalV6 => FROZEN_PREPARED_HEADER_V6_DYNAMIC_ROWS_OFFSET,
            Self::CellOffsetV7 => FROZEN_PREPARED_HEADER_V7_DYNAMIC_ROWS_OFFSET,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V8_DYNAMIC_ROWS_OFFSET,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V9_DYNAMIC_ROWS_OFFSET,
            Self::StateOrdinalDirectU8V10 => FROZEN_PREPARED_HEADER_V10_DYNAMIC_ROWS_OFFSET,
            Self::PairSupertransitionV11 => FROZEN_PREPARED_HEADER_V11_DYNAMIC_ROWS_OFFSET,
            Self::StateOrdinalMappedU8V12 => FROZEN_PREPARED_HEADER_V12_DYNAMIC_ROWS_OFFSET,
            Self::DensePairSupertransitionV13 => FROZEN_PREPARED_HEADER_V13_DYNAMIC_ROWS_OFFSET,
            Self::DenseQuadSupertransitionV14 => FROZEN_PREPARED_HEADER_V14_DYNAMIC_ROWS_OFFSET,
        }
    }

    const fn ready_seal(self) -> u64 {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V3_READY_SEAL,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V4_READY_SEAL,
            Self::UnaryExistsV5 => FROZEN_PREPARED_HEADER_V5_READY_SEAL,
            Self::StateOrdinalV6 => FROZEN_PREPARED_HEADER_V6_READY_SEAL,
            Self::CellOffsetV7 => FROZEN_PREPARED_HEADER_V7_READY_SEAL,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V8_READY_SEAL,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V9_READY_SEAL,
            Self::StateOrdinalDirectU8V10 => FROZEN_PREPARED_HEADER_V10_READY_SEAL,
            Self::PairSupertransitionV11 => FROZEN_PREPARED_HEADER_V11_READY_SEAL,
            Self::StateOrdinalMappedU8V12 => FROZEN_PREPARED_HEADER_V12_READY_SEAL,
            Self::DensePairSupertransitionV13 => FROZEN_PREPARED_HEADER_V13_READY_SEAL,
            Self::DenseQuadSupertransitionV14 => FROZEN_PREPARED_HEADER_V14_READY_SEAL,
        }
    }

    const fn format_version(self) -> u32 {
        match self {
            Self::StateOrdinalV3 => FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION,
            Self::CellOffsetV4 => FROZEN_DYNAMIC_ROWS_V4_FORMAT_VERSION,
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_FORMAT_VERSION,
            Self::StateOrdinalV6 => FROZEN_DYNAMIC_ROWS_V6_FORMAT_VERSION,
            Self::CellOffsetV7 => FROZEN_DYNAMIC_ROWS_V7_FORMAT_VERSION,
            Self::StateOrdinalDirectV8 => FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION,
            Self::CellOffsetDirectV9 => FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION,
            Self::StateOrdinalDirectU8V10 => FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION,
            Self::PairSupertransitionV11 => FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION,
            Self::StateOrdinalMappedU8V12 => FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION,
            Self::DensePairSupertransitionV13 => FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION,
            Self::DenseQuadSupertransitionV14 => FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION,
        }
    }

    const fn is_state_ordinal(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalV3
                | Self::StateOrdinalV6
                | Self::StateOrdinalDirectV8
                | Self::StateOrdinalDirectU8V10
                | Self::StateOrdinalMappedU8V12
        )
    }

    const fn is_cell_offset(self) -> bool {
        matches!(
            self,
            Self::CellOffsetV4
                | Self::UnaryExistsV5
                | Self::CellOffsetV7
                | Self::CellOffsetDirectV9
        )
    }

    const fn is_direct_byte(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalDirectV8
                | Self::CellOffsetDirectV9
                | Self::StateOrdinalDirectU8V10
        )
    }

    const fn is_u8(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalDirectU8V10 | Self::StateOrdinalMappedU8V12
        )
    }

    const fn is_pair_supertransition(self) -> bool {
        matches!(
            self,
            Self::PairSupertransitionV11 | Self::DensePairSupertransitionV13
        )
    }

    const fn is_dense_pair_supertransition(self) -> bool {
        matches!(self, Self::DensePairSupertransitionV13)
    }

    const fn is_quad_supertransition(self) -> bool {
        matches!(self, Self::DenseQuadSupertransitionV14)
    }

    const fn has_loop_plans(self) -> bool {
        matches!(self, Self::StateOrdinalV6 | Self::CellOffsetV7)
    }

    const fn ready_seal_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_READY_SEAL_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_READY_SEAL_OFFSET,
        }
    }

    const fn rows_address_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_ROWS_ADDRESS_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_ROWS_ADDRESS_OFFSET,
        }
    }

    const fn cache_identity_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_CACHE_IDENTITY_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_CACHE_IDENTITY_OFFSET,
        }
    }

    const fn state_count_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_STATE_COUNT_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_STATE_COUNT_OFFSET,
        }
    }

    const fn class_count_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_CLASS_COUNT_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_CLASS_COUNT_OFFSET,
        }
    }

    const fn row_shift_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_ROW_SHIFT_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET,
        }
    }

    const fn initial_state_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_INITIAL_STATE_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_INITIAL_STATE_OFFSET,
        }
    }

    const fn loop_count_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_LOOP_COUNT_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_LOOP_COUNT_OFFSET,
        }
    }

    const fn loop_states_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_LOOP_STATES_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_LOOP_STATES_OFFSET,
        }
    }

    const fn format_version_offset(self) -> usize {
        match self {
            Self::UnaryExistsV5 => FROZEN_DYNAMIC_ROWS_V5_FORMAT_VERSION_OFFSET,
            _ => FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET,
        }
    }
}

#[allow(
    clippy::too_many_lines,
    reason = "compact capabilities and full verifiers share one explicit fail-closed target lowering"
)]
fn x86_emit_frozen_compact_entry(
    assembler: &mut X86Assembler,
    format: FrozenCompactNativeFormat,
    try_older: X86Label,
    call_preflight: X86Label,
    compact_enter: X86Label,
    guard_mode: FrozenCompactGuardMode,
) -> Result<(), ObjectError> {
    let branch_failed = |assembler: &mut X86Assembler| {
        assembler.branch(&[0x0f, 0x85], call_preflight)
    };
    let header_disp = |offset: usize, context| {
        u8::try_from(offset).map_err(|_| ObjectError::ArithmeticOverflow(context))
    };
    let tail_disp = |offset: usize, context| {
        u8::try_from(offset).map_err(|_| ObjectError::ArithmeticOverflow(context))
    };
    if guard_mode
        .variable_span_source_class_count()
        .is_some_and(|count| !(1..=256).contains(&count))
    {
        return Err(ObjectError::InvalidModule(
            "x86 compact reverse verifier has an invalid source class count",
        ));
    }

    // Select the overlapping tail exclusively through its distinct V1 flag.
    // A different-generation header reaches the older validator without
    // consuming this format's extent or tail fields.
    let mut compare_flags = vec![
        0x81,
        0x7f,
        header_disp(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET, "x86 V3 flags")?,
    ];
    let primary_flags = if guard_mode.expects_reverse_supertransition() {
        format.flag() | FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION
    } else {
        format.flag()
    };
    compare_flags.extend_from_slice(&primary_flags.to_le_bytes());
    assembler.instruction(&compare_flags)?;
    if guard_mode.expects_reverse_supertransition() {
        let accepted_flags = assembler.label()?;
        assembler.branch(&[0x0f, 0x84], accepted_flags)?;
        let mut compare_base_flags = vec![
            0x81,
            0x7f,
            header_disp(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET, "x86 V3 base flags")?,
        ];
        compare_base_flags.extend_from_slice(&format.flag().to_le_bytes());
        assembler.instruction(&compare_base_flags)?;
        assembler.branch(&[0x0f, 0x85], try_older)?;
        assembler.bind(accepted_flags)?;
    } else {
        assembler.branch(&[0x0f, 0x85], try_older)?;
    }

    // Every live exclusive handle owns the maximum V6 envelope. The active
    // seal authenticates its immutable setup proof; only the audit path needs
    // to re-read the smaller format's logical extent and descriptor mirrors.
    if guard_mode.is_full_verifier() {
        let mut compare_extent = vec![
            0x48,
            0x81,
            0x7f,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET,
                "x86 V3 header extent offset",
            )?,
        ];
        compare_extent.extend_from_slice(
            &u32::try_from(format.header_bytes())
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 compact header extent"))?
                .to_le_bytes(),
        );
        assembler.instruction(&compare_extent)?;
        branch_failed(assembler)?;
    }

    let mut load_seal = vec![0x49, 0xba];
    load_seal.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL.to_le_bytes());
    assembler.instruction(&load_seal)?;
    assembler.instruction(&[0x4c, 0x3b, 0x17])?;
    branch_failed(assembler)?;
    if guard_mode.is_full_verifier() {
        let mut load_magic = vec![0x49, 0xba];
        load_magic.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_MAGIC.to_le_bytes());
        assembler.instruction(&load_magic)?;
        assembler.instruction(&[
            0x4c,
            0x3b,
            0x57,
            header_disp(FROZEN_PREPARED_HEADER_V1_MAGIC_OFFSET, "x86 V3 magic")?,
        ])?;
        branch_failed(assembler)?;
        let mut compare_abi = vec![
            0x81,
            0x7f,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_ABI_VERSION_OFFSET,
                "x86 V3 ABI version",
            )?,
        ];
        compare_abi.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_ABI_VERSION.to_le_bytes());
        assembler.instruction(&compare_abi)?;
        branch_failed(assembler)?;
    }

    // The scalar verifier remains an independent correctness baseline. An
    // AVX2 target XORs the complete unaligned 256-bit identities and uses
    // VPTEST's exact all-zero ZF result. VZEROUPPER deliberately sits between
    // VPTEST and the mismatch branch: it preserves EFLAGS while making both
    // the equal path and the legacy-SSE/runtime failure path transition-clean.
    // Baseline x86-64 compares both 128-bit halves, folds their byte-equality
    // masks, and branches once on the same exact 256-bit result. The linked
    // identity address is already frame-resident, so either proof may consume
    // vector scratch and EAX without weakening later preflight or table setup.
    if guard_mode.uses_x86_avx2_identity() {
        let header = header_disp(
            FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET,
            "x86 compact AVX2 identity offset",
        )?;
        assembler.instruction(&[0xc5, 0xfe, 0x6f, 0x00])?; // vmovdqu ymm0, [rax]
        assembler.instruction(&[0xc5, 0xfd, 0xef, 0x47, header])?; // vpxor ymm0, ymm0, identity[rdi]
        assembler.instruction(&[0xc4, 0xe2, 0x7d, 0x17, 0xc0])?; // vptest ymm0, ymm0
        assembler.instruction(&[0xc5, 0xf8, 0x77])?; // vzeroupper (preserves EFLAGS)
        branch_failed(assembler)?;
    } else if guard_mode.uses_simd_identity() {
        let first_header = header_disp(
            FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET,
            "x86 compact SSE2 identity offset",
        )?;
        let second_header = header_disp(
            FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(16)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "x86 compact SSE2 identity extent",
                ))?,
            "x86 compact SSE2 identity second half",
        )?;
        assembler.instruction(&[0xf3, 0x0f, 0x6f, 0x00])?; // movdqu xmm0, [rax]
        assembler.instruction(&[0xf3, 0x0f, 0x6f, 0x48, 0x10])?; // movdqu xmm1, 16[rax]
        assembler.instruction(&[0xf3, 0x0f, 0x6f, 0x57, first_header])?; // movdqu xmm2, identity[rdi]
        assembler.instruction(&[0xf3, 0x0f, 0x6f, 0x5f, second_header])?; // movdqu xmm3, identity+16[rdi]
        assembler.instruction(&[0x66, 0x0f, 0x74, 0xc2])?; // pcmpeqb xmm0, xmm2
        assembler.instruction(&[0x66, 0x0f, 0x74, 0xcb])?; // pcmpeqb xmm1, xmm3
        assembler.instruction(&[0x66, 0x0f, 0xdb, 0xc1])?; // pand xmm0, xmm1
        assembler.instruction(&[0x66, 0x0f, 0xd7, 0xc0])?; // pmovmskb eax, xmm0
        assembler.instruction(&[0x66, 0x3d, 0xff, 0xff])?; // cmp ax, 0xffff
        branch_failed(assembler)?;
    } else {
        for identity_word in 0_usize..4 {
            let word_offset = identity_word
                .checked_mul(core::mem::size_of::<u64>())
                .ok_or(ObjectError::ArithmeticOverflow("x86 V3 identity word"))?;
            if word_offset == 0 {
                assembler.instruction(&[0x4c, 0x8b, 0x10])?;
            } else {
                assembler.instruction(&[
                    0x4c,
                    0x8b,
                    0x50,
                    header_disp(word_offset, "x86 V3 linked identity word")?,
                ])?;
            }
            let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(word_offset)
                .ok_or(ObjectError::ArithmeticOverflow("x86 V3 header identity"))?;
            assembler.instruction(&[
                0x4c,
                0x3b,
                0x57,
                header_disp(header_offset, "x86 V3 header identity word")?,
            ])?;
            branch_failed(assembler)?;
        }
    }

    if let Some(source_class_count) = guard_mode.variable_span_source_class_count() {
        let source_class_count_u32 = u32::from(source_class_count);
        let reverse_failed = assembler.label()?;
        let reverse_valid = assembler.label()?;

        // Preserve the SysV window arguments while DIV consumes RDX:RCX.
        // This path exists only for the independent audit verifier; active
        // prepared handles use their setup-authenticated capability instead.
        assembler.instruction(&[0x52])?; // push rdx
        assembler.instruction(&[0x51])?; // push rcx
        assembler.instruction(&[
            0x4c,
            0x8b,
            0x57,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET,
                "x86 V3 reverse rows",
            )?,
        ])?;
        assembler.instruction(&[0x4d, 0x85, 0xd2])?;
        assembler.branch(&[0x0f, 0x84], reverse_failed)?;
        assembler.instruction(&[0x41, 0xf6, 0xc2, 0x03])?;
        assembler.branch(&[0x0f, 0x85], reverse_failed)?;

        assembler.instruction(&[
            0x4c,
            0x8b,
            0x57,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET,
                "x86 V3 reverse live cells",
            )?,
        ])?;
        let mut compare_minimum = vec![0x49, 0x81, 0xfa];
        compare_minimum.extend_from_slice(&source_class_count_u32.to_le_bytes());
        assembler.instruction(&compare_minimum)?;
        assembler.branch(&[0x0f, 0x82], reverse_failed)?;
        let mut compare_maximum = vec![0x49, 0x81, 0xfa];
        compare_maximum
            .extend_from_slice(&DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK.to_le_bytes());
        assembler.instruction(&compare_maximum)?;
        assembler.branch(&[0x0f, 0x87], reverse_failed)?;

        // Exact divisibility by the original, pre-coalescing K0 stride.
        assembler.instruction(&[0x4c, 0x89, 0xd0])?;
        assembler.instruction(&[0x31, 0xd2])?;
        let mut load_stride = vec![0xb9];
        load_stride.extend_from_slice(&source_class_count_u32.to_le_bytes());
        assembler.instruction(&load_stride)?;
        assembler.instruction(&[0x48, 0xf7, 0xf1])?;
        assembler.instruction(&[0x48, 0x85, 0xd2])?;
        assembler.branch(&[0x0f, 0x85], reverse_failed)?;

        assembler.instruction(&[
            0x44,
            0x8b,
            0x5f,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_REVERSE_INITIAL_ROW_OFFSET,
                "x86 V3 reverse initial row",
            )?,
        ])?;
        let mut compare_no_reverse = vec![0x41, 0x81, 0xfb];
        compare_no_reverse
            .extend_from_slice(&FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW.to_le_bytes());
        assembler.instruction(&compare_no_reverse)?;
        assembler.branch(&[0x0f, 0x84], reverse_failed)?;
        assembler.instruction(&[0x44, 0x89, 0xd8])?;
        assembler.instruction(&[0x31, 0xd2])?;
        assembler.instruction(&[0x48, 0xf7, 0xf1])?;
        assembler.instruction(&[0x48, 0x85, 0xd2])?;
        assembler.branch(&[0x0f, 0x85], reverse_failed)?;
        let mut add_stride = vec![0x49, 0x81, 0xc3];
        add_stride.extend_from_slice(&source_class_count_u32.to_le_bytes());
        assembler.instruction(&add_stride)?;
        assembler.instruction(&[0x4d, 0x39, 0xd3])?;
        assembler.branch(&[0x0f, 0x87], reverse_failed)?;

        assembler.instruction(&[0x59])?; // pop rcx
        assembler.instruction(&[0x5a])?; // pop rdx
        assembler.branch(&[0xe9], reverse_valid)?;
        assembler.bind(reverse_failed)?;
        assembler.instruction(&[0x59])?;
        assembler.instruction(&[0x5a])?;
        assembler.branch(&[0xe9], call_preflight)?;
        assembler.bind(reverse_valid)?;
    } else if guard_mode.is_full_verifier() {
        for (field, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET,
                "x86 V3 reverse rows",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET,
                "x86 V3 reverse cells",
            ),
        ] {
            assembler.instruction(&[0x48, 0x83, 0x7f, header_disp(field, context)?, 0])?;
            branch_failed(assembler)?;
        }
        let mut compare_no_reverse = vec![
            0x81,
            0x7f,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_REVERSE_INITIAL_ROW_OFFSET,
                "x86 V3 reverse initial row",
            )?,
        ];
        compare_no_reverse
            .extend_from_slice(&FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW.to_le_bytes());
        assembler.instruction(&compare_no_reverse)?;
        branch_failed(assembler)?;
    }

    let tail_offset = i32::try_from(format.tail_offset())
        .map_err(|_| ObjectError::ArithmeticOverflow("x86 compact tail offset"))?;
    let mut tail_address = vec![0x4c, 0x8d, 0x9f];
    tail_address.extend_from_slice(&tail_offset.to_le_bytes());
    assembler.instruction(&tail_address)?;

    if guard_mode.is_full_verifier() {
        let mut load_ready = vec![0x49, 0xba];
        load_ready.extend_from_slice(&format.ready_seal().to_le_bytes());
        assembler.instruction(&load_ready)?;
        assembler.instruction(&[
            0x4d,
            0x3b,
            0x53,
            tail_disp(
                format.ready_seal_offset(),
                "x86 V3 ready seal",
            )?,
        ])?;
        branch_failed(assembler)?;
        let mut compare_format = vec![
            0x41,
            0x81,
            0x7b,
            tail_disp(
                format.format_version_offset(),
                "x86 V3 format version",
            )?,
        ];
        compare_format.extend_from_slice(&format.format_version().to_le_bytes());
        assembler.instruction(&compare_format)?;
        branch_failed(assembler)?;
    }

    if guard_mode.is_full_verifier() {
        // These mirrors, pointer constraints, and the complete geometry below
        // were proved when the private owner was built. Production entries may
        // rely on the still-active capability; the full verifier remains an
        // independently emitted corruption-detection path for audits/tests.
        for (header_field, tail_field, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_FORWARD_ROWS_ADDRESS_OFFSET,
                format.rows_address_offset(),
                "x86 V3 rows mirror",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_CACHE_IDENTITY_OFFSET,
                format.cache_identity_offset(),
                "x86 V3 cache identity mirror",
            ),
        ] {
            assembler.instruction(&[
                0x4c,
                0x8b,
                0x57,
                header_disp(header_field, context)?,
            ])?;
            assembler.instruction(&[
                0x4d,
                0x3b,
                0x53,
                tail_disp(tail_field, context)?,
            ])?;
            branch_failed(assembler)?;
        }

        assembler.instruction(&[
            0x4d,
            0x8b,
            0x53,
            tail_disp(
                format.rows_address_offset(),
                "x86 V3 rows address",
            )?,
        ])?;
        assembler.instruction(&[0x4d, 0x85, 0xd2])?;
        assembler.branch(&[0x0f, 0x84], call_preflight)?;
        if !format.is_u8() {
            assembler.instruction(&[
                0x41,
                0xf6,
                0xc2,
                if format == FrozenCompactNativeFormat::PairSupertransitionV11 {
                    0x03
                } else {
                    0x01
                },
            ])?;
            branch_failed(assembler)?;
        }
    }

    if guard_mode.is_full_verifier() {
        assembler.instruction(&[
            0x4d,
            0x8b,
            0x53,
            tail_disp(
                format.cache_identity_offset(),
                "x86 V3 cache identity",
            )?,
        ])?;
        assembler.instruction(&[0x4d, 0x85, 0xd2])?;
        assembler.branch(&[0x0f, 0x84], call_preflight)?;
    }

    if guard_mode.is_full_verifier() {
        assembler.instruction(&[
            0x41,
            0x8b,
            0x43,
            tail_disp(format.state_count_offset(), "x86 V3 states")?,
        ])?;
        assembler.instruction(&[0x85, 0xc0])?;
        assembler.branch(&[0x0f, 0x84], call_preflight)?;
        if format.is_u8() {
            assembler.instruction(&[0x83, 0xf8, 0x7f])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_state_ordinal() {
            assembler.instruction(&[0x3d, 0xff, 0x7f, 0x00, 0x00])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_quad_supertransition() {
            assembler.instruction(&[0x3d, 0xff, 0x1f, 0x00, 0x00])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        }
        assembler.instruction(&[
            0x45,
            0x8b,
            0x43,
            tail_disp(format.class_count_offset(), "x86 V3 classes")?,
        ])?;
        assembler.instruction(&[0x45, 0x85, 0xc0])?;
        assembler.branch(&[0x0f, 0x84], call_preflight)?;
        assembler.instruction(&[0x41, 0x81, 0xf8, 0x00, 0x01, 0x00, 0x00])?;
        assembler.branch(&[0x0f, 0x87], call_preflight)?;
        if format.is_pair_supertransition() {
            assembler.instruction(&[0x41, 0x83, 0xf8, 0x02])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[
                0x41,
                0x83,
                0xf8,
                if format.is_dense_pair_supertransition() {
                    0x08
                } else {
                    0x04
                },
            ])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_quad_supertransition() {
            assembler.instruction(&[0x41, 0x83, 0xf8, 0x02])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x41, 0x83, 0xf8, 0x04])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        }
        if format.is_direct_byte() {
            assembler.instruction(&[0x41, 0x81, 0xf8, 0x00, 0x01, 0x00, 0x00])?;
            branch_failed(assembler)?;
        }
        if format.is_quad_supertransition() {
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET,
                    "x86 V14 reserved shift",
                )?,
                0,
            ])?;
            branch_failed(assembler)?;
            // Exact block cells are C^4+C^3+C^2+C, without cache-expanding
            // power-of-two padding.
            assembler.instruction(&[0x44, 0x89, 0xc2])?;
            assembler.instruction(&[0x41, 0x0f, 0xaf, 0xd0])?;
            assembler.instruction(&[0x89, 0xd1])?;
            assembler.instruction(&[0x41, 0x0f, 0xaf, 0xc8])?;
            assembler.instruction(&[0x01, 0xca])?;
            assembler.instruction(&[0x41, 0x0f, 0xaf, 0xc8])?;
            assembler.instruction(&[0x01, 0xca])?;
            assembler.instruction(&[0x44, 0x01, 0xc2])?;
        } else if format.is_dense_pair_supertransition() {
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET,
                    "x86 V13 reserved shift",
                )?,
                0,
            ])?;
            branch_failed(assembler)?;
            // V13 stores exactly C*C pair cells plus one odd-tail bitmap.
            assembler.instruction(&[0x44, 0x89, 0xc2])?;
            assembler.instruction(&[0x41, 0x0f, 0xaf, 0xd0])?;
            assembler.instruction(&[0xff, 0xc2])?;
        } else if format.is_pair_supertransition() {
            assembler.instruction(&[
                0x41,
                0x8b,
                0x4b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET,
                    "x86 V11 class shift",
                )?,
            ])?;
            assembler.instruction(&[0x83, 0xf9, 0x01])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x83, 0xf9, 0x02])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
            assembler.instruction(&[0xba, 0x01, 0x00, 0x00, 0x00])?;
            assembler.instruction(&[0x48, 0xd3, 0xe2])?;
            assembler.instruction(&[0x44, 0x39, 0xc2])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x41, 0x89, 0xd2])?;
            assembler.instruction(&[0x41, 0xd1, 0xea])?;
            assembler.instruction(&[0x45, 0x39, 0xd0])?;
            assembler.branch(&[0x0f, 0x86], call_preflight)?;
            assembler.instruction(&[0x0f, 0xaf, 0xd2])?;
            assembler.instruction(&[0xff, 0xc2])?;
        } else if format.is_u8() {
            assembler.instruction(&[
                0x41,
                0x8b,
                0x4b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET,
                    "x86 compact-u8 row shift",
                )?,
            ])?;
            assembler.instruction(&[0x83, 0xf9, 0x08])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
            assembler.instruction(&[0xba, 0x01, 0x00, 0x00, 0x00])?;
            assembler.instruction(&[0x48, 0xd3, 0xe2])?;
            assembler.instruction(&[0x44, 0x39, 0xc2])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x41, 0x89, 0xd2])?;
            assembler.instruction(&[0x41, 0xd1, 0xea])?;
            assembler.instruction(&[0x45, 0x39, 0xd0])?;
            assembler.branch(&[0x0f, 0x86], call_preflight)?;
        } else if format.is_state_ordinal() {
            assembler.instruction(&[
                0x41,
                0x8b,
                0x4b,
                tail_disp(FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET, "x86 V3 row shift")?,
            ])?;
            assembler.instruction(&[0x83, 0xf9, 0x01])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x83, 0xf9, 0x09])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;

            // Reconstruct the exact physical geometry: cells=2^(byte_shift-1),
            // cells>=classes>cells/2. This is precisely next_power_of_two(classes).
            assembler.instruction(&[0xba, 0x01, 0x00, 0x00, 0x00])?;
            assembler.instruction(&[0xff, 0xc9])?;
            assembler.instruction(&[0x48, 0xd3, 0xe2])?;
            assembler.instruction(&[0x44, 0x39, 0xc2])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[0x41, 0x89, 0xd2])?;
            assembler.instruction(&[0x41, 0xd1, 0xea])?;
            assembler.instruction(&[0x45, 0x39, 0xd0])?;
            assembler.branch(&[0x0f, 0x86], call_preflight)?;
        } else {
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET, "x86 V4 row shift")?,
                0,
            ])?;
            branch_failed(assembler)?;
            // V4/V9 are deliberately unpadded. EDX becomes the physical/logical
            // class count for the common live-cell and initial-row proofs.
            assembler.instruction(&[0x44, 0x89, 0xc2])?;
        }
        assembler.instruction(&[
            0x39,
            0x57,
            header_disp(FROZEN_PREPARED_HEADER_V1_ROW_STRIDE_OFFSET, "x86 V3 row stride")?,
        ])?;
        branch_failed(assembler)?;

        assembler.instruction(&[0x41, 0x89, 0xc2])?;
        assembler.instruction(&[0x48, 0x0f, 0xaf, 0xc2])?;
        if format.is_quad_supertransition() {
            // V14 tokens address block starts rather than the full owned
            // extent. Prove `(states - 1) * block_cells + 1 <= 8191`
            // exactly; the independent live-cell mirror below authenticates
            // the complete final block as well.
            assembler.instruction(&[0x49, 0x89, 0xc2])?;
            assembler.instruction(&[0x49, 0x29, 0xd2])?;
            assembler.instruction(&[0x49, 0xff, 0xc2])?;
            assembler.instruction(&[0x49, 0x81, 0xfa, 0xff, 0x1f, 0x00, 0x00])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_dense_pair_supertransition() {
            // As for V14, only block starts are encoded as destinations. The
            // final block may extend past the token mask, so authenticate
            // `(states - 1) * block_cells + 1` while retaining RAX as the
            // complete live-cell extent for the mirror below.
            assembler.instruction(&[0x49, 0x89, 0xc2])?;
            assembler.instruction(&[0x49, 0x29, 0xd2])?;
            assembler.instruction(&[0x49, 0xff, 0xc2])?;
            assembler.instruction(&[0x49, 0x81, 0xfa, 0xff, 0x3f, 0x00, 0x00])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_pair_supertransition() {
            assembler.instruction(&[0x48, 0x3d, 0xff, 0xff, 0xff, 0x1f])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        } else if format.is_cell_offset() {
            assembler.instruction(&[0x48, 0x3d, 0xff, 0x7f, 0x00, 0x00])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        }
        assembler.instruction(&[
            0x48,
            0x39,
            0x47,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_FORWARD_LIVE_CELLS_OFFSET,
                "x86 V3 live cells",
            )?,
        ])?;
        branch_failed(assembler)?;
        // Setup canonicalizes every compact encoding before format selection.
        // The full verifier authenticates both mirrors exactly; the
        // production active-capability guard relies on the same immutable
        // owner proof without redoing this geometry on every invocation.
        assembler.instruction(&[
            0x41,
            0x83,
            0x7b,
            tail_disp(
                format.initial_state_offset(),
                "x86 compact initial state",
            )?,
            0,
        ])?;
        branch_failed(assembler)?;
        assembler.instruction(&[
            0x83,
            0x7f,
            header_disp(
                FROZEN_PREPARED_HEADER_V1_FORWARD_INITIAL_ROW_OFFSET,
                "x86 compact initial row",
            )?,
            0,
        ])?;
        branch_failed(assembler)?;

        let (dead_cell, accept_mask, next_state_mask) = match format {
            FrozenCompactNativeFormat::DenseQuadSupertransitionV14 => (
                0,
                u32::from(DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::PairSupertransitionV11 => (
                0,
                DYNAMIC_NATIVE_ROWS_V11_ANY_ACCEPT_MASK,
                DYNAMIC_NATIVE_ROWS_V11_NEXT_BLOCK_TOKEN_MASK,
            ),
            FrozenCompactNativeFormat::DensePairSupertransitionV13 => (
                0,
                u32::from(DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::StateOrdinalDirectU8V10 => (
                u32::from(DYNAMIC_NATIVE_ROWS_V10_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V10_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V10_NEXT_STATE_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::StateOrdinalMappedU8V12 => (
                u32::from(DYNAMIC_NATIVE_ROWS_V12_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V12_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V12_NEXT_STATE_TOKEN_MASK),
            ),
            _ => (
                u32::from(DYNAMIC_NATIVE_ROWS_V3_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK),
            ),
        };
        for (field, expected, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_UNFILLED_CELL_OFFSET,
                dead_cell,
                "x86 compact dead cell",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_ACCEPT_MASK_OFFSET,
                accept_mask,
                "x86 compact accept mask",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_NEXT_ROW_TOKEN_MASK_OFFSET,
                next_state_mask,
                "x86 compact next-state mask",
            ),
        ] {
            let mut compare = vec![0x81, 0x7f, header_disp(field, context)?];
            compare.extend_from_slice(&expected.to_le_bytes());
            assembler.instruction(&compare)?;
            branch_failed(assembler)?;
        }
    }

    if guard_mode.is_full_verifier() {
        // Compact non-loop formats, including V11/V13/V14 supertransitions,
        // normalize complete immutable rows by suppressing mutable-K0
        // learned-loop ownership. The full verifier authenticates that
        // normalization independently of the active capability.
        assembler.instruction(&[
            0x41,
            0x83,
            0x7b,
            tail_disp(format.loop_count_offset(), "x86 V3 loop count")?,
            0,
        ])?;
        branch_failed(assembler)?;
        for loop_index in 0..NATIVE_ROWS_LOOP_ROW_CAPACITY {
            let offset = format.loop_states_offset()
                .checked_add(
                    loop_index
                        .checked_mul(core::mem::size_of::<u32>())
                        .ok_or(ObjectError::ArithmeticOverflow("x86 V3 loop state"))?,
                )
                .ok_or(ObjectError::ArithmeticOverflow("x86 V3 loop state"))?;
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(offset, "x86 V3 inactive loop state")?,
                0xff,
            ])?;
            branch_failed(assembler)?;
        }

        if format == FrozenCompactNativeFormat::UnaryExistsV5 {
            assembler.instruction(&[
                0x45,
                0x8b,
                0x53,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET,
                    "x86 V5 first accept step",
                )?,
            ])?;
            assembler.instruction(&[0x44, 0x89, 0xd0])?;
            assembler.instruction(&[
                0x41,
                0x33,
                0x43,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_COMPLEMENT_OFFSET,
                    "x86 V5 first accept complement",
                )?,
            ])?;
            assembler.instruction(&[0x83, 0xf8, 0xff])?;
            branch_failed(assembler)?;
            assembler.instruction(&[
                0x45,
                0x3b,
                0x53,
                tail_disp(format.state_count_offset(), "x86 V5 state bound")?,
            ])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
        }

        if format.has_loop_plans() {
            let loop_plan_capacity = u8::try_from(NATIVE_ROWS_LOOP_ROW_CAPACITY)
                .map_err(|_| ObjectError::ArithmeticOverflow("x86 V6 loop capacity"))?;
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_PLAN_COUNT_OFFSET,
                    "x86 V6 loop plan count",
                )?,
                1,
            ])?;
            assembler.branch(&[0x0f, 0x82], call_preflight)?;
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_PLAN_COUNT_OFFSET,
                    "x86 V6 loop plan count",
                )?,
                loop_plan_capacity,
            ])?;
            assembler.branch(&[0x0f, 0x87], call_preflight)?;
            assembler.instruction(&[
                0x41,
                0x83,
                0x7b,
                tail_disp(FROZEN_DYNAMIC_ROWS_V6_RESERVED_OFFSET, "x86 V6 reserved")?,
                0,
            ])?;
            branch_failed(assembler)?;
            for (field, context) in [
                (
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_ADDRESS_OFFSET,
                    "x86 V6 loop index address",
                ),
                (
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_LENGTH_OFFSET,
                    "x86 V6 loop index length",
                ),
            ] {
                assembler.instruction(&[0x49, 0x83, 0x7b, tail_disp(field, context)?, 0])?;
                assembler.branch(&[0x0f, 0x84], call_preflight)?;
            }
        }
    }

    // Preserve the standalone full verifier byte contract. Production
    // lowering saves these public bounds once before its selector lattice,
    // avoiding the historical four-instruction copy in every format guard.
    if guard_mode.is_full_verifier() {
        assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x28])?;
        assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, 0x40])?;
        assembler.instruction(&[0x4c, 0x8b, 0x54, 0x24, 0x30])?;
        assembler.instruction(&[0x4c, 0x89, 0x54, 0x24, 0x48])?;
    }

    if format == FrozenCompactNativeFormat::UnaryExistsV5 {
        assembler.instruction(&[
            0x45,
            0x8b,
            0x53,
            tail_disp(
                FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET,
                "x86 V5 retained first accept step",
            )?,
        ])?;
    }
    assembler.branch(&[0xe9], compact_enter)?;
    Ok(())
}

fn x86_emit_frozen_compact_v3_entry(
    assembler: &mut X86Assembler,
    try_v2: X86Label,
    call_preflight: X86Label,
    v3_enter: X86Label,
    guard_mode: FrozenCompactGuardMode,
) -> Result<(), ObjectError> {
    x86_emit_frozen_compact_entry(
        assembler,
        FrozenCompactNativeFormat::StateOrdinalV3,
        try_v2,
        call_preflight,
        v3_enter,
        guard_mode,
    )
}

