fn aarch64_csel_x(
    destination: u8,
    when_true: u8,
    when_false: u8,
    condition: u8,
) -> Result<u32, ObjectError> {
    if condition > 15 {
        return Err(ObjectError::InvalidModule("AArch64 CSEL condition"));
    }
    Ok(0x9a80_0000
        | aarch64_reg(when_false, 16)?
        | (u32::from(condition) << 12)
        | aarch64_reg(when_true, 5)?
        | aarch64_reg(destination, 0)?)
}

