fn aarch64_sve_and_z(
    destination: u8,
    left: u8,
    right: u8,
) -> Result<u32, ObjectError> {
    // SVE spells the unpredicated bitwise form with D elements; the operation
    // is bitwise and therefore preserves the byte-lane classifier exactly.
    Ok(0x0420_3000
        | aarch64_reg(right, 16)?
        | aarch64_reg(left, 5)?
        | aarch64_reg(destination, 0)?)
}

fn aarch64_sve_orr_z(
    destination: u8,
    left: u8,
    right: u8,
) -> Result<u32, ObjectError> {
    // As with AND, SVE's unpredicated logical spelling uses D elements while
    // applying the operation bitwise across the complete scalable register.
    Ok(0x0460_3000
        | aarch64_reg(right, 16)?
        | aarch64_reg(left, 5)?
        | aarch64_reg(destination, 0)?)
}

