const AARCH64_EXACT_FILTER_SCRATCH: u8 = 28;
const AARCH64_VECTOR_FILTER_FIRST_CONSTANT: u8 = 1;
const AARCH64_STANDALONE_FILTER_FIRST_CONSTANT: u8 = 16;

const fn aarch64_caller_saved_simd(register: u8) -> bool {
    register <= 7 || register >= 16
}

/// Translate one bounded filter-constant slot to a caller-saved SIMD register.
///
/// Retained multi-column filters have a four-constant global cap and occupy
/// V1..V4. Standalone exact and range filters occupy V16..V23. The two banks
/// match their callers' complementary source/candidate allocations, avoid the
/// ABI-preserved V8..V15 bank, and leave V7 exclusively available for the
/// persistent loop's horizontal candidate reduction.
fn aarch64_filter_constant_register(first_register: u8, index: usize) -> Result<u8, ObjectError> {
    let logical = index
        .checked_add(usize::from(first_register))
        .and_then(|value| u8::try_from(value).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "ASIMD filter constant register",
        ))?;
    let register = match logical {
        1..=4 | 16..=23 => logical,
        _ => {
            return Err(ObjectError::InvalidModule(
                "ASIMD filter constant escaped caller-saved register banks",
            ));
        }
    };
    Ok(register)
}

fn aarch64_prefix_relation_constant_register(
    first_register: u8,
    index: usize,
) -> Result<u8, ObjectError> {
    let register = index
        .checked_add(usize::from(first_register))
        .and_then(|value| u8::try_from(value).ok())
        .ok_or(ObjectError::ArithmeticOverflow(
            "ASIMD prefix-relation constant register",
        ))?;
    if !(1..=MAX_AARCH64_PREFIX_RELATION_CONSTANTS).contains(&register) {
        return Err(ObjectError::InvalidModule(
            "ASIMD prefix-relation constant escaped V1..V6",
        ));
    }
    Ok(register)
}

fn aarch64_emit_first_lane_constants(
    assembler: &mut Aarch64Assembler,
    table_offset: u32,
) -> Result<(), ObjectError> {
    if table_offset == 0 {
        assembler.instruction(aarch64_load_q(29, 5)?)?;
    } else {
        aarch64_set_table_address(assembler, 12, table_offset)?;
        assembler.instruction(aarch64_load_q(29, 12)?)?;
    }
    // Candidate comparisons produce exact 0xff/0x00 bytes. v29 is the lane
    // ramp, v30 advances it between 16-byte blocks, and v31 is a sentinel
    // larger than every lane in a four-vector batch.
    assembler.instruction(aarch64_movi_16b(30, 16)?)?;
    assembler.instruction(aarch64_movi_16b(31, 64)?)?;
    Ok(())
}

fn aarch64_emit_candidate_any(
    assembler: &mut Aarch64Assembler,
    candidates: u8,
) -> Result<(), ObjectError> {
    // Keep the exact mask intact for the rare hit edge. Caller-saved v7 is
    // outside every bounded filter-constant and candidate allocation;
    // v29-v31 remain the persistent first-lane constants.
    assembler.instruction(aarch64_umaxv_16b(7, candidates)?)?;
    assembler.instruction(aarch64_umov_b0(12, 7)?)?;
    assembler.instruction(aarch64_cmp_w_zero(12)?)?;
    Ok(())
}

fn aarch64_emit_candidate_batch_any(
    assembler: &mut Aarch64Assembler,
    first_candidates: u8,
) -> Result<(), ObjectError> {
    let second = first_candidates
        .checked_add(1)
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 batch candidates"))?;
    let third = first_candidates
        .checked_add(2)
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 batch candidates"))?;
    let fourth = first_candidates
        .checked_add(3)
        .ok_or(ObjectError::ArithmeticOverflow("AArch64 batch candidates"))?;
    // Pairwise reduction preserves all four exact lane masks for a rare hit
    // while shortening the overwhelmingly hot miss path by one ORR.
    assembler.instruction(aarch64_orr_16b(28, first_candidates, second)?)?;
    assembler.instruction(aarch64_orr_16b(7, third, fourth)?)?;
    assembler.instruction(aarch64_orr_16b(28, 28, 7)?)?;
    aarch64_emit_candidate_any(assembler, 28)
}

fn aarch64_emit_first_candidate_lane(
    assembler: &mut Aarch64Assembler,
    candidates: u8,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_bsl_16b(candidates, 29, 31)?)?;
    assembler.instruction(aarch64_uminv_16b(candidates, candidates)?)?;
    assembler.instruction(aarch64_umov_b0(12, candidates)?)?;
    assembler.instruction(aarch64_add_x_reg(2, 2, 12)?)?;
    Ok(())
}

fn aarch64_emit_first_retained_candidate_lane(
    assembler: &mut Aarch64Assembler,
    candidates: u8,
    block_base: u8,
) -> Result<(), ObjectError> {
    // The retained mask must survive scalar checks. Refine a caller-saved
    // copy in V28 and address the selected lane from the supplied block base.
    assembler.instruction(aarch64_orr_16b(28, candidates, candidates)?)?;
    assembler.instruction(aarch64_bsl_16b(28, 29, 31)?)?;
    assembler.instruction(aarch64_uminv_16b(28, 28)?)?;
    assembler.instruction(aarch64_umov_b0(12, 28)?)?;
    assembler.instruction(aarch64_add_x_reg(2, block_base, 12)?)?;
    Ok(())
}

#[allow(
    clippy::arithmetic_side_effects,
    reason = "the preceding checked register bound proves all fixed offsets remain in range"
)]
fn aarch64_emit_first_candidate_in_batch(
    assembler: &mut Aarch64Assembler,
    first_candidates: u8,
) -> Result<(), ObjectError> {
    let last_candidates =
        first_candidates
            .checked_add(3)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 batch candidate register",
            ))?;
    if last_candidates >= 28 {
        return Err(ObjectError::InvalidModule(
            "AArch64 batch candidates overlap first-lane temporaries",
        ));
    }

    // Convert each exact mask into its absolute lane number, using 64 for
    // absent lanes. Pairwise unsigned minima then select the first candidate
    // over the complete 64-byte batch without a scalar rescan or a chain of
    // unpredictable per-block branches.
    assembler.instruction(aarch64_orr_16b(28, 29, 29)?)?;
    for block in 0_u8..4 {
        let candidates =
            first_candidates
                .checked_add(block)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 batch candidate register",
                ))?;
        assembler.instruction(aarch64_bsl_16b(candidates, 28, 31)?)?;
        if block < 3 {
            assembler.instruction(aarch64_add_16b(28, 28, 30)?)?;
        }
    }
    assembler.instruction(aarch64_umin_16b(
        first_candidates,
        first_candidates,
        first_candidates + 1,
    )?)?;
    assembler.instruction(aarch64_umin_16b(
        first_candidates + 2,
        first_candidates + 2,
        first_candidates + 3,
    )?)?;
    assembler.instruction(aarch64_umin_16b(
        first_candidates,
        first_candidates,
        first_candidates + 2,
    )?)?;
    assembler.instruction(aarch64_uminv_16b(first_candidates, first_candidates)?)?;
    assembler.instruction(aarch64_umov_b0(12, first_candidates)?)?;
    assembler.instruction(aarch64_add_x_reg(2, 2, 12)?)?;
    Ok(())
}

fn aarch64_emit_start_filter_constants(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    first_register: u8,
) -> Result<(), ObjectError> {
    for (index, range) in filter.ranges().iter().enumerate() {
        if filter.is_exact() {
            let register = aarch64_filter_constant_register(first_register, index)?;
            assembler.instruction(aarch64_movi_16b(register, range.start)?)?;
        } else {
            let logical_low = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
                "ASIMD range-filter low register",
            ))?;
            let logical_high =
                logical_low
                    .checked_add(1)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "ASIMD range-filter high register",
                    ))?;
            let low_register = aarch64_filter_constant_register(first_register, logical_low)?;
            let high_register = aarch64_filter_constant_register(first_register, logical_high)?;
            assembler.instruction(aarch64_movi_16b(low_register, range.start)?)?;
            assembler.instruction(aarch64_movi_16b(high_register, range.end)?)?;
        }
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Aarch64SveFilterKind {
    Sve,
    Sve2 { match_table_offset: u32 },
}

/// Per-column lowering selected for one scalable multicolumn scanner.
///
/// Keeping this distinct from [`NativeVectorFilterCostModel`] makes the
/// planning/lowering contract explicit: the former predicts resources, while
/// this receipt records the concrete table-backed implementation of every
/// selected column. A future direct-DFA multicolumn scanner can consume the
/// same plan without changing graph selection again.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Aarch64SveFilterPlan {
    kinds: [Aarch64SveFilterKind; MAX_VECTOR_FILTER_COLUMNS],
    column_count: u8,
}

impl Aarch64SveFilterPlan {
    fn primary(self) -> Aarch64SveFilterKind {
        self.kinds[0]
    }

    fn kind(self, column: usize) -> Result<Aarch64SveFilterKind, ObjectError> {
        self.kinds
            .get(column)
            .copied()
            .filter(|_| column < usize::from(self.column_count))
            .ok_or(ObjectError::InvalidModule(
                "SVE filter plan column is absent",
            ))
    }

    fn validate_for(
        self,
        primary: NativeStartFilter,
        vector_filter: Option<NativeVectorFilter>,
    ) -> Result<(), ObjectError> {
        if vector_filter.is_some_and(|vector_filter| {
            vector_filter.columns().first().copied() != Some(primary)
        }) {
            return Err(ObjectError::InvalidModule(
                "SVE vector-filter primary mismatch",
            ));
        }
        let expected_columns = vector_filter.map_or(1, |filter| filter.columns().len());
        if usize::from(self.column_count) != expected_columns {
            return Err(ObjectError::InvalidModule(
                "SVE filter plan column count mismatch",
            ));
        }
        Ok(())
    }

    fn uses_sve2(self) -> bool {
        self.kinds
            .iter()
            .take(usize::from(self.column_count))
            .any(|kind| matches!(kind, Aarch64SveFilterKind::Sve2 { .. }))
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Aarch64SvePrimaryHitCharge {
    debt: u16,
    initial_credit: u16,
    fallback: Aarch64Label,
}

/// Largest runtime SVE vector length admitted to the four-vector scanner.
///
/// The graph-derived byte frequency uses 256 denominator units. A replay is
/// admitted only while its expected hits across four runtime vectors fit the
/// same conservative budget as the sparse x86 mask batch. Architectural SVE
/// lengths are multiples of 16 bytes in [16, 256], so rounding down preserves
/// the inequality for every supported process vector length. Base SVE also
/// pays the ordinary membership-instruction cap; SVE2 MATCH forms any exact
/// membership with one hot vector instruction.
fn aarch64_sve_batch_max_vector_bytes(
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
) -> Option<u16> {
    if filter.ranges().is_empty() {
        return None;
    }
    let instruction_units = match kind {
        Aarch64SveFilterKind::Sve => vector_filter_instruction_units(filter),
        Aarch64SveFilterKind::Sve2 { .. } => 1,
    };
    if instruction_units > MAX_VECTOR_FILTER_INSTRUCTION_UNITS {
        return None;
    }
    let frequency_units = estimated_filter_frequency_units(filter);
    if frequency_units == 0 {
        return None;
    }
    let budget = u32::from(MAX_SPARSE_RESCAN_EXPECTED_HITS)
        .checked_mul(u32::from(BYTE_FREQUENCY_DENOMINATOR))?;
    let expected_hits_per_vl = u32::from(AARCH64_SVE_BATCH_VECTORS)
        .checked_mul(u32::from(frequency_units))?;
    let raw_maximum = budget.checked_div(expected_hits_per_vl)?;
    let minimum = u32::from(AARCH64_SVE_MIN_VECTOR_BYTES);
    let rounded = raw_maximum.checked_div(minimum)?.checked_mul(minimum)?;
    if rounded < minimum {
        return None;
    }
    u16::try_from(rounded.min(u32::from(AARCH64_SVE_MAX_VECTOR_BYTES))).ok()
}

fn aarch64_sve_filter_constant_register(index: usize) -> Result<u8, ObjectError> {
    // These exported matchers have the ordinary C AAPCS64 interface: every
    // argument and result is a scalar, never a scalable vector or predicate.
    // AAPCS64 6.1.3 therefore makes Z16..Z31 caller-saved (only low 64-bit
    // V8..V15 state is preserved), so Z16..Z23 are scratch without a scalable
    // save frame and cannot disturb the callee-saved V8..V15 bank.
    let register = index
        .checked_add(16)
        .and_then(|value| u8::try_from(value).ok())
        .filter(|&value| value <= 23)
        .ok_or(ObjectError::InvalidModule(
            "SVE filter constant escaped Z16..Z23",
        ))?;
    Ok(register)
}

fn aarch64_sve_filter_constant_register_from(
    first_constant: usize,
    index: usize,
) -> Result<u8, ObjectError> {
    let logical = first_constant
        .checked_add(index)
        .ok_or(ObjectError::ArithmeticOverflow("SVE filter constant"))?;
    aarch64_sve_filter_constant_register(logical)
}

fn aarch64_sve_filter_constant_count(
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
) -> usize {
    match kind {
        Aarch64SveFilterKind::Sve => filter.constant_count(),
        Aarch64SveFilterKind::Sve2 { .. } => 1,
    }
}

/// Materialize the per-column lowering contract after optional SVE2 tables
/// have been installed. A missing table conservatively prices that exact set
/// as base SVE. If a widened graph plan can no longer fit the audited
/// Z16..Z23/hot-operation budgets, the caller must use a scalar (or another
/// independently valid) route instead of partially lowering the plan.
fn aarch64_sve_filter_plan(
    primary: NativeStartFilter,
    vector_filter: Option<NativeVectorFilter>,
    match_table_offsets: [Option<u32>; MAX_VECTOR_FILTER_COLUMNS],
) -> Result<Option<Aarch64SveFilterPlan>, ObjectError> {
    if vector_filter.is_some_and(|vector_filter| {
        vector_filter.columns().first().copied() != Some(primary)
    }) {
        return Err(ObjectError::InvalidModule(
            "SVE vector-filter primary mismatch",
        ));
    }
    let mut columns = [primary; MAX_VECTOR_FILTER_COLUMNS];
    let column_count = if let Some(vector_filter) = vector_filter {
        let selected = vector_filter.columns();
        columns[..selected.len()].copy_from_slice(selected);
        selected.len()
    } else {
        1
    };
    if match_table_offsets[column_count..]
        .iter()
        .any(Option::is_some)
    {
        return Err(ObjectError::InvalidModule(
            "SVE match table has no filter column",
        ));
    }

    let mut kinds = [Aarch64SveFilterKind::Sve; MAX_VECTOR_FILTER_COLUMNS];
    let mut constants = 0_usize;
    let mut instruction_units = 0_u16;
    for (column, (&filter, match_table_offset)) in columns[..column_count]
        .iter()
        .zip(match_table_offsets)
        .enumerate()
    {
        if match_table_offset.is_some() && !filter.is_exact() {
            return Err(ObjectError::InvalidModule(
                "SVE2 match table belongs to a range filter",
            ));
        }
        let kind = match match_table_offset {
            Some(match_table_offset) => Aarch64SveFilterKind::Sve2 { match_table_offset },
            None => Aarch64SveFilterKind::Sve,
        };
        kinds[column] = kind;
        constants = constants
            .checked_add(aarch64_sve_filter_constant_count(filter, kind))
            .ok_or(ObjectError::ArithmeticOverflow(
                "SVE vector-filter constants",
            ))?;
        instruction_units = instruction_units
            .checked_add(match kind {
                Aarch64SveFilterKind::Sve => vector_filter_instruction_units(filter),
                Aarch64SveFilterKind::Sve2 { .. } => 1,
            })
            .ok_or(ObjectError::ArithmeticOverflow(
                "SVE vector-filter instruction units",
            ))?;
    }
    if constants > 8
        || (vector_filter.is_some()
            && instruction_units > MAX_VECTOR_FILTER_INSTRUCTION_UNITS)
    {
        return Ok(None);
    }
    Ok(Some(Aarch64SveFilterPlan {
        kinds,
        column_count: u8::try_from(column_count)
            .map_err(|_| ObjectError::ArithmeticOverflow("SVE filter-plan columns"))?,
    }))
}

fn aarch64_emit_sve_filter_setup(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
    first_constant: usize,
) -> Result<(), ObjectError> {
    if filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule("empty SVE start filter"));
    }
    // AAPCS64 makes every predicate register caller-saved under the ordinary
    // base PCS used by this scalar interface. The scalable-vector PCS instead
    // preserves P4..P15, but these exported entries never use that PCS.
    match kind {
        Aarch64SveFilterKind::Sve => {
            for (index, range) in filter.ranges().iter().enumerate() {
                if filter.is_exact() {
                    let register =
                        aarch64_sve_filter_constant_register_from(first_constant, index)?;
                    assembler.instruction(aarch64_sve_dup_b_imm(register, range.start)?)?;
                } else {
                    let low_index = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
                        "SVE range-filter low constant",
                    ))?;
                    let high_index =
                        low_index
                            .checked_add(1)
                            .ok_or(ObjectError::ArithmeticOverflow(
                                "SVE range-filter high constant",
                            ))?;
                    let low =
                        aarch64_sve_filter_constant_register_from(first_constant, low_index)?;
                    let high =
                        aarch64_sve_filter_constant_register_from(first_constant, high_index)?;
                    assembler.instruction(aarch64_sve_dup_b_imm(low, range.start)?)?;
                    assembler.instruction(aarch64_sve_dup_b_imm(high, range.end)?)?;
                }
            }
        }
        Aarch64SveFilterKind::Sve2 { match_table_offset } => {
            if !filter.is_exact() || filter.ranges().len() > 16 {
                return Err(ObjectError::InvalidModule("invalid SVE2 MATCH filter"));
            }
            // LD1RQB is predicated; the public scanner entry establishes P0
            // after setup, so this one setup-only PTRUE is required here.
            assembler.instruction(aarch64_sve_ptrue_b())?;
            aarch64_set_table_address(assembler, 12, match_table_offset)?;
            let table = aarch64_sve_filter_constant_register(first_constant)?;
            assembler.instruction(aarch64_sve_ld1rqb(table, 12)?)?;
        }
    }
    Ok(())
}

fn aarch64_emit_sve_filter_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
    first_constant: usize,
    source: u8,
    destination: u8,
    scratch: u8,
    range_scratch: u8,
) -> Result<(), ObjectError> {
    match kind {
        Aarch64SveFilterKind::Sve2 { .. } => {
            let table = aarch64_sve_filter_constant_register(first_constant)?;
            assembler.instruction(aarch64_sve2_match_b(destination, source, table)?)?;
        }
        Aarch64SveFilterKind::Sve if filter.is_exact() => {
            for (index, _) in filter.ranges().iter().enumerate() {
                let constant =
                    aarch64_sve_filter_constant_register_from(first_constant, index)?;
                let comparison = if index == 0 { destination } else { scratch };
                assembler.instruction(aarch64_sve_cmpeq_b(comparison, source, constant)?)?;
                if index != 0 {
                    assembler.instruction(aarch64_sve_orr_b(
                        destination,
                        destination,
                        scratch,
                    )?)?;
                }
            }
        }
        Aarch64SveFilterKind::Sve => {
            for (index, _) in filter.ranges().iter().enumerate() {
                let low_index = index.checked_mul(2).ok_or(
                    ObjectError::ArithmeticOverflow("SVE range-filter candidate low"),
                )?;
                let high_index = low_index.checked_add(1).ok_or(
                    ObjectError::ArithmeticOverflow("SVE range-filter candidate high"),
                )?;
                let low =
                    aarch64_sve_filter_constant_register_from(first_constant, low_index)?;
                let high =
                    aarch64_sve_filter_constant_register_from(first_constant, high_index)?;
                let comparison = if index == 0 { destination } else { scratch };
                assembler.instruction(aarch64_sve_cmphs_b(comparison, source, low)?)?;
                // CMPLS(data, high) is the CMPhs(high, data) alias.
                assembler.instruction(aarch64_sve_cmphs_b(range_scratch, high, source)?)?;
                assembler.instruction(aarch64_sve_and_b(
                    comparison,
                    comparison,
                    range_scratch,
                )?)?;
                if index != 0 {
                    assembler.instruction(aarch64_sve_orr_b(
                        destination,
                        destination,
                        scratch,
                    )?)?;
                }
            }
        }
    }
    Ok(())
}

fn aarch64_emit_sve_filter_setups(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    vector_filter: Option<NativeVectorFilter>,
    plan: Aarch64SveFilterPlan,
) -> Result<(), ObjectError> {
    plan.validate_for(filter, vector_filter)?;
    let primary_kind = plan.kind(0)?;
    aarch64_emit_sve_filter_setup(assembler, filter, primary_kind, 0)?;
    let mut first_constant = aarch64_sve_filter_constant_count(filter, primary_kind);
    if let Some(vector_filter) = vector_filter {
        for (index, &column) in vector_filter.columns()[1..].iter().enumerate() {
            let plan_index = index
                .checked_add(1)
                .ok_or(ObjectError::ArithmeticOverflow("SVE filter-plan column"))?;
            let kind = plan.kind(plan_index)?;
            aarch64_emit_sve_filter_setup(assembler, column, kind, first_constant)?;
            first_constant = first_constant
                .checked_add(aarch64_sve_filter_constant_count(column, kind))
                .ok_or(ObjectError::ArithmeticOverflow(
                    "SVE vector-filter constants",
                ))?;
        }
    }
    Ok(())
}

fn aarch64_emit_sve_filter_load_primary_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
    vector_offset: u8,
) -> Result<(), ObjectError> {
    aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
    assembler.instruction(aarch64_sve_ld1b_vl(0, 12, vector_offset)?)?;
    aarch64_emit_sve_filter_candidates(assembler, filter, kind, 0, 0, 1, 2, 3)
}

fn aarch64_emit_sve_filter_load_secondary_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    vector_filter: NativeVectorFilter,
    plan: Aarch64SveFilterPlan,
    vector_offset: u8,
) -> Result<(), ObjectError> {
    plan.validate_for(filter, Some(vector_filter))?;
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "SVE vector-filter has no secondary columns",
        ));
    }
    let mut first_constant =
        aarch64_sve_filter_constant_count(filter, plan.kind(0)?);
    for (index, &column) in vector_filter.columns()[1..].iter().enumerate() {
        let plan_index = index
            .checked_add(1)
            .ok_or(ObjectError::ArithmeticOverflow("SVE filter-plan column"))?;
        let kind = plan.kind(plan_index)?;
        aarch64_emit_start_filter_address(assembler, column.scan_offset)?;
        assembler.instruction(aarch64_sve_ld1b_vl(0, 12, vector_offset)?)?;
        aarch64_emit_sve_filter_candidates(
            assembler,
            column,
            kind,
            first_constant,
            0,
            2,
            3,
            4,
        )?;
        assembler.instruction(aarch64_sve_and_b(1, 1, 2)?)?;
        first_constant = first_constant
            .checked_add(aarch64_sve_filter_constant_count(column, kind))
            .ok_or(ObjectError::ArithmeticOverflow(
                "SVE vector-filter constants",
            ))?;
    }
    Ok(())
}

fn aarch64_emit_sve_filter_batch_primary_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
) -> Result<(), ObjectError> {
    let batch_vectors = u8::try_from(AARCH64_SVE_BATCH_VECTORS)
        .map_err(|_| ObjectError::ArithmeticOverflow("SVE batch vectors"))?;
    aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
    for block in 0_u8..batch_vectors {
        let source = 24_u8
            .checked_add(block)
            .ok_or(ObjectError::ArithmeticOverflow("SVE batch source"))?;
        assembler.instruction(aarch64_sve_ld1b_vl(source, 12, block)?)?;
    }
    for block in 0_u8..batch_vectors {
        let source = 24_u8
            .checked_add(block)
            .ok_or(ObjectError::ArithmeticOverflow("SVE batch source"))?;
        let destination = 1_u8.checked_add(block).ok_or(
            ObjectError::ArithmeticOverflow("SVE batch candidate predicate"),
        )?;
        aarch64_emit_sve_filter_candidates(
            assembler,
            filter,
            kind,
            0,
            source,
            destination,
            5,
            6,
        )?;
    }
    Ok(())
}

fn aarch64_emit_sve_filter_batch_secondary_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    vector_filter: NativeVectorFilter,
    plan: Aarch64SveFilterPlan,
) -> Result<(), ObjectError> {
    plan.validate_for(filter, Some(vector_filter))?;
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "SVE vector-filter has no secondary columns",
        ));
    }
    let batch_vectors = u8::try_from(AARCH64_SVE_BATCH_VECTORS)
        .map_err(|_| ObjectError::ArithmeticOverflow("SVE batch vectors"))?;
    let mut first_constant =
        aarch64_sve_filter_constant_count(filter, plan.kind(0)?);
    for (index, &column) in vector_filter.columns()[1..].iter().enumerate() {
        let plan_index = index
            .checked_add(1)
            .ok_or(ObjectError::ArithmeticOverflow("SVE filter-plan column"))?;
        let kind = plan.kind(plan_index)?;
        aarch64_emit_start_filter_address(assembler, column.scan_offset)?;
        for block in 0_u8..batch_vectors {
            let source = 24_u8
                .checked_add(block)
                .ok_or(ObjectError::ArithmeticOverflow("SVE batch source"))?;
            assembler.instruction(aarch64_sve_ld1b_vl(source, 12, block)?)?;
        }
        for block in 0_u8..batch_vectors {
            let source = 24_u8
                .checked_add(block)
                .ok_or(ObjectError::ArithmeticOverflow("SVE batch source"))?;
            let primary = 1_u8.checked_add(block).ok_or(
                ObjectError::ArithmeticOverflow("SVE batch candidate predicate"),
            )?;
            aarch64_emit_sve_filter_candidates(
                assembler,
                column,
                kind,
                first_constant,
                source,
                5,
                6,
                7,
            )?;
            assembler.instruction(aarch64_sve_and_b(primary, primary, 5)?)?;
        }
        first_constant = first_constant
            .checked_add(aarch64_sve_filter_constant_count(column, kind))
            .ok_or(ObjectError::ArithmeticOverflow(
                "SVE vector-filter constants",
            ))?;
    }
    Ok(())
}

fn aarch64_emit_sve_first_candidate(
    assembler: &mut Aarch64Assembler,
    candidates: u8,
    candidate: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_sve_brkb_p0(2, candidates)?)?;
    // BRKB clears every inactive P0 lane, so INCP's ungoverned count of P2
    // exactly matches the former CNTP(P0, P2) followed by ADD.
    assembler.instruction(aarch64_sve_incp_b(2, 2)?)?;
    assembler.branch(candidate)?;
    Ok(())
}

fn aarch64_emit_sve_primary_hit_charge(
    assembler: &mut Aarch64Assembler,
    charge: Aarch64SvePrimaryHitCharge,
) -> Result<(), ObjectError> {
    // Context anchored-forward search keeps fixed-point work debt in x17.
    // Charge a primary-hit block before any graph-secondary refinement and
    // resume the one-shot fallback from that block's semantic base on excess.
    assembler.instruction(aarch64_add_x_imm(17, 17, charge.debt)?)?;
    assembler.instruction(aarch64_add_x_imm(12, 2, charge.initial_credit)?)?;
    assembler.instruction(aarch64_cmp_x(17, 12)?)?;
    let admitted = assembler.label()?;
    assembler.branch_cond(AARCH64_LS, admitted)?;
    assembler.instruction(aarch64_store_x(2, 4, 0)?)?;
    assembler.branch(charge.fallback)?;
    assembler.bind(admitted)?;
    Ok(())
}

fn aarch64_emit_sve_legacy_filter_load_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    kind: Aarch64SveFilterKind,
    vector_offset: u8,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_sve_ld1b_vl(0, 12, vector_offset)?)?;
    aarch64_emit_sve_filter_candidates(assembler, filter, kind, 0, 0, 1, 2, 3)
}

/// Emit the direct-DFA SVE scanner for a single graph-derived byte column.
/// Multicolumn plans use the shared lazy-intersection scanner below, while
/// retaining this smaller lowering avoids secondary-column machinery when the
/// graph selector chose only one column.
#[allow(
    clippy::too_many_arguments,
    reason = "setup lifetime and the three CFG exits are explicit lowering invariants"
)]
fn aarch64_emit_sve_start_filter_scanner(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    maximum_scan_offset: u8,
    kind: Aarch64SveFilterKind,
    rematerialize_filter_setup: bool,
    vector_length_is_precomputed: bool,
    vector: Aarch64Label,
    scalar: Aarch64Label,
    candidate: Aarch64Label,
) -> Result<(), ObjectError> {
    let single = assembler.label()?;
    let partial = assembler.label()?;
    let single_hit = assembler.label()?;
    let batch_plan = if let Some(maximum_vector_bytes) =
        aarch64_sve_batch_max_vector_bytes(filter, kind)
    {
        Some((
            maximum_vector_bytes,
            assembler.label()?,
            assembler.label()?,
            [
                assembler.label()?,
                assembler.label()?,
                assembler.label()?,
                assembler.label()?,
            ],
        ))
    } else {
        None
    };
    assembler.bind(vector)?;
    // Mixed-capability entries rematerialize because intervening ASIMD work
    // may alias V16..V23 with the SVE Z16..Z23 constant bank. Pure-SVE
    // callers instead establish the immutable constants before this retry
    // label and retain them across scalar candidate validation.
    if rematerialize_filter_setup {
        aarch64_emit_sve_filter_setup(assembler, filter, kind, 0)?;
    }
    assembler.instruction(aarch64_sve_ptrue_b())?;
    if !vector_length_is_precomputed {
        assembler.instruction(aarch64_sve_cntb(6)?)?;
    }

    if let Some((maximum_vector_bytes, batch, batch_hit, batch_hits)) = batch_plan {
        let batch_vectors = u8::try_from(AARCH64_SVE_BATCH_VECTORS)
            .map_err(|_| ObjectError::ArithmeticOverflow("SVE batch vectors"))?;
        assembler.instruction(aarch64_cmp_x_imm(6, maximum_vector_bytes)?)?;
        assembler.branch_cond(AARCH64_HI, single)?;
        assembler.bind(batch)?;
        assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
        if maximum_scan_offset != 0 {
            assembler.instruction(aarch64_cmp_x_imm(12, u16::from(maximum_scan_offset))?)?;
            assembler.branch_cond(AARCH64_LS, scalar)?;
            assembler.instruction(aarch64_sub_x_imm(12, 12, u16::from(maximum_scan_offset))?)?;
        }
        assembler.instruction(aarch64_cmp_x_lsl(12, 6, 2)?)?;
        assembler.branch_cond(AARCH64_LO, single)?;
        // Keep each block's primary predicate live. This saves the complete
        // load-and-compare replay on a hit and replaces the rolling union with
        // a balanced reduction.
        aarch64_emit_sve_filter_batch_primary_candidates(assembler, filter, kind)?;
        assembler.instruction(aarch64_sve_orr_b(8, 1, 2)?)?;
        assembler.instruction(aarch64_sve_orr_b(9, 3, 4)?)?;
        assembler.instruction(aarch64_sve_orrs_p0_b(8, 8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, batch_hit)?;
        assembler.instruction(aarch64_sve_addvl(2, 2, batch_vectors)?)?;
        assembler.branch(batch)?;

        // Ordered probes over the retained masks keep the leftmost candidate
        // exact without reloading or recomputing the hit batch.
        assembler.bind(batch_hit)?;
        for (block, &hit) in batch_hits.iter().enumerate() {
            let predicate = u8::try_from(block)
                .ok()
                .and_then(|block| block.checked_add(1))
                .ok_or(ObjectError::ArithmeticOverflow("SVE hit predicate"))?;
            assembler.instruction(aarch64_sve_ptest_p0(predicate)?)?;
            assembler.branch_cond(AARCH64_NE, hit)?;
        }
        assembler.branch(scalar)?;
        for (block, &hit) in batch_hits.iter().enumerate() {
            assembler.bind(hit)?;
            if block != 0 {
                assembler.instruction(aarch64_sve_addvl(
                    2,
                    2,
                    u8::try_from(block)
                        .map_err(|_| ObjectError::ArithmeticOverflow("SVE hit block"))?,
                )?)?;
            }
            let predicate = u8::try_from(block)
                .ok()
                .and_then(|block| block.checked_add(1))
                .ok_or(ObjectError::ArithmeticOverflow("SVE hit predicate"))?;
            if predicate != 1 {
                assembler.instruction(aarch64_sve_orr_b(1, predicate, predicate)?)?;
            }
            aarch64_emit_sve_first_candidate(assembler, 1, candidate)?;
        }
    }

    assembler.bind(single)?;
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    if maximum_scan_offset != 0 {
        assembler.instruction(aarch64_cmp_x_imm(12, u16::from(maximum_scan_offset))?)?;
        assembler.branch_cond(AARCH64_LS, scalar)?;
        assembler.instruction(aarch64_sub_x_imm(12, 12, u16::from(maximum_scan_offset))?)?;
    }
    assembler.instruction(aarch64_cmp_x(12, 6)?)?;
    assembler.branch_cond(AARCH64_LO, partial)?;
    aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
    aarch64_emit_sve_legacy_filter_load_candidates(assembler, filter, kind, 0)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    assembler.branch_cond(AARCH64_NE, single_hit)?;
    assembler.instruction(aarch64_sve_addvl(2, 2, 1)?)?;
    assembler.branch(single)?;

    assembler.bind(partial)?;
    let partial_end = if maximum_scan_offset == 0 {
        3
    } else {
        assembler.instruction(aarch64_sub_x_imm(12, 3, u16::from(maximum_scan_offset))?)?;
        12
    };
    assembler.instruction(aarch64_sve_whilelo_b(0, 2, partial_end)?)?;
    aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
    aarch64_emit_sve_legacy_filter_load_candidates(assembler, filter, kind, 0)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    assembler.branch_cond(AARCH64_NE, single_hit)?;
    if maximum_scan_offset == 0 {
        assembler.instruction(aarch64_mov_x(2, 3)?)?;
    } else {
        assembler.instruction(aarch64_sub_x_imm(2, 3, u16::from(maximum_scan_offset))?)?;
    }
    assembler.branch(scalar)?;

    assembler.bind(single_hit)?;
    aarch64_emit_sve_first_candidate(assembler, 1, candidate)?;
    Ok(())
}

/// Emit one vector-length-agnostic scanner over a graph-derived byte filter.
///
/// `CNTB` is loop invariant. A stable graph/frequency gate admits the
/// four-vector path only for runtime vector lengths whose expected replay
/// budget is sparse; other filters and wider process VLs enter the direct
/// one-vector loop. The batch retains four independent lane masks, intersects
/// every graph-derived column in place, and probes a rare hit in source order.
/// One-vector and predicated partial tails preserve the same exact first-lane
/// rule without reading past the window.
fn aarch64_emit_sve_multicol_start_filter_scanner(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    vector_filter: Option<NativeVectorFilter>,
    primary_hit_charge: Option<Aarch64SvePrimaryHitCharge>,
    maximum_scan_offset: u8,
    plan: Aarch64SveFilterPlan,
    rematerialize_filter_setup: bool,
    vector_length_is_precomputed: bool,
    vector: Aarch64Label,
    scalar: Aarch64Label,
    candidate: Aarch64Label,
) -> Result<(), ObjectError> {
    plan.validate_for(filter, vector_filter)?;
    if primary_hit_charge.is_some() && vector_filter.is_none() {
        return Err(ObjectError::InvalidModule(
            "SVE primary-hit charge has no secondary columns",
        ));
    }
    let single = assembler.label()?;
    let single_advance = assembler.label()?;
    let partial = assembler.label()?;
    let partial_exhausted = assembler.label()?;
    let single_hit = assembler.label()?;
    let primary_kind = plan.primary();
    let batch_plan = if let Some(maximum_vector_bytes) =
        aarch64_sve_batch_max_vector_bytes(filter, primary_kind)
    {
        Some((
            maximum_vector_bytes,
            assembler.label()?,
            assembler.label()?,
            assembler.label()?,
            [
                assembler.label()?,
                assembler.label()?,
                assembler.label()?,
                assembler.label()?,
            ],
        ))
    } else {
        None
    };
    assembler.bind(vector)?;
    // Mixed-capability entries rematerialize because intervening ASIMD work
    // may alias V16..V23 with the SVE Z16..Z23 constant bank. Pure-SVE
    // callers establish the complete immutable bank before this retry label.
    if rematerialize_filter_setup {
        aarch64_emit_sve_filter_setups(assembler, filter, vector_filter, plan)?;
    }
    // A rejected candidate may also re-enter after a predicated tail probe.
    // Restore the all-lanes predicate before any full-vector load.
    assembler.instruction(aarch64_sve_ptrue_b())?;
    if !vector_length_is_precomputed {
        assembler.instruction(aarch64_sve_cntb(6)?)?;
    }

    if let Some((maximum_vector_bytes, batch, batch_advance, batch_hit, batch_hits)) = batch_plan {
        let batch_vectors = u8::try_from(AARCH64_SVE_BATCH_VECTORS)
            .map_err(|_| ObjectError::ArithmeticOverflow("SVE batch vectors"))?;
        assembler.instruction(aarch64_cmp_x_imm(6, maximum_vector_bytes)?)?;
        assembler.branch_cond(AARCH64_HI, single)?;
        assembler.bind(batch)?;
        assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
        if maximum_scan_offset != 0 {
            assembler.instruction(aarch64_cmp_x_imm(12, u16::from(maximum_scan_offset))?)?;
            assembler.branch_cond(AARCH64_LS, scalar)?;
            assembler.instruction(aarch64_sub_x_imm(12, 12, u16::from(maximum_scan_offset))?)?;
        }
        // Four runtime vectors are 4 * CNTB, encoded as the checked LSL #2.
        assembler.instruction(aarch64_cmp_x_lsl(12, 6, 2)?)?;
        assembler.branch_cond(AARCH64_LO, single)?;
        aarch64_emit_sve_filter_batch_primary_candidates(assembler, filter, primary_kind)?;
        assembler.instruction(aarch64_sve_orr_b(8, 1, 2)?)?;
        assembler.instruction(aarch64_sve_orr_b(9, 3, 4)?)?;
        assembler.instruction(aarch64_sve_orrs_p0_b(8, 8, 9)?)?;
        if let Some(vector_filter) = vector_filter {
            // The graph selector prices secondary columns as lazy work. Do
            // not touch them until this four-vector batch contains a primary
            // lane, then intersect every retained lane before hit ordering.
            assembler.branch_cond(AARCH64_EQ, batch_advance)?;
            if let Some(charge) = primary_hit_charge {
                aarch64_emit_sve_primary_hit_charge(assembler, charge)?;
            }
            aarch64_emit_sve_filter_batch_secondary_candidates(
                assembler,
                filter,
                vector_filter,
                plan,
            )?;
            assembler.instruction(aarch64_sve_orr_b(8, 1, 2)?)?;
            assembler.instruction(aarch64_sve_orr_b(9, 3, 4)?)?;
            assembler.instruction(aarch64_sve_orrs_p0_b(8, 8, 9)?)?;
        }
        assembler.branch_cond(AARCH64_NE, batch_hit)?;
        assembler.bind(batch_advance)?;
        assembler.instruction(aarch64_sve_addvl(2, 2, batch_vectors)?)?;
        assembler.branch(batch)?;

        // The column-outer schedule retains all four intersected masks.
        // Ordered probes keep the leftmost candidate exact without reloading
        // either primary or secondary columns on the hit path.
        assembler.bind(batch_hit)?;
        for (block, &hit) in batch_hits.iter().enumerate() {
            let predicate = u8::try_from(block)
                .ok()
                .and_then(|block| block.checked_add(1))
                .ok_or(ObjectError::ArithmeticOverflow("SVE hit predicate"))?;
            assembler.instruction(aarch64_sve_ptest_p0(predicate)?)?;
            assembler.branch_cond(AARCH64_NE, hit)?;
        }
        // The batch union proved that one ordered probe must succeed. Preserve
        // a correct scalar fallback if future selection violates the invariant.
        assembler.branch(scalar)?;
        for (block, &hit) in batch_hits.iter().enumerate() {
            assembler.bind(hit)?;
            if block != 0 {
                assembler.instruction(aarch64_sve_addvl(
                    2,
                    2,
                    u8::try_from(block)
                        .map_err(|_| ObjectError::ArithmeticOverflow("SVE hit block"))?,
                )?)?;
            }
            let predicate = u8::try_from(block)
                .ok()
                .and_then(|block| block.checked_add(1))
                .ok_or(ObjectError::ArithmeticOverflow("SVE hit predicate"))?;
            if predicate != 1 {
                assembler.instruction(aarch64_sve_orr_b(1, predicate, predicate)?)?;
            }
            aarch64_emit_sve_first_candidate(assembler, 1, candidate)?;
        }
    }

    assembler.bind(single)?;
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    if maximum_scan_offset != 0 {
        assembler.instruction(aarch64_cmp_x_imm(12, u16::from(maximum_scan_offset))?)?;
        assembler.branch_cond(AARCH64_LS, scalar)?;
        assembler.instruction(aarch64_sub_x_imm(12, 12, u16::from(maximum_scan_offset))?)?;
    }
    assembler.instruction(aarch64_cmp_x(12, 6)?)?;
    assembler.branch_cond(AARCH64_LO, partial)?;
    aarch64_emit_sve_filter_load_primary_candidates(assembler, filter, primary_kind, 0)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    if let Some(vector_filter) = vector_filter {
        assembler.branch_cond(AARCH64_EQ, single_advance)?;
        if let Some(charge) = primary_hit_charge {
            aarch64_emit_sve_primary_hit_charge(assembler, charge)?;
        }
        aarch64_emit_sve_filter_load_secondary_candidates(
            assembler,
            filter,
            vector_filter,
            plan,
            0,
        )?;
        assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    }
    assembler.branch_cond(AARCH64_NE, single_hit)?;
    assembler.bind(single_advance)?;
    assembler.instruction(aarch64_sve_addvl(2, 2, 1)?)?;
    assembler.branch(single)?;

    assembler.bind(partial)?;
    let partial_end = if maximum_scan_offset == 0 {
        3
    } else {
        assembler.instruction(aarch64_sub_x_imm(12, 3, u16::from(maximum_scan_offset))?)?;
        12
    };
    assembler.instruction(aarch64_sve_whilelo_b(0, 2, partial_end)?)?;
    aarch64_emit_sve_filter_load_primary_candidates(assembler, filter, primary_kind, 0)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    if let Some(vector_filter) = vector_filter {
        assembler.branch_cond(AARCH64_EQ, partial_exhausted)?;
        if let Some(charge) = primary_hit_charge {
            aarch64_emit_sve_primary_hit_charge(assembler, charge)?;
        }
        aarch64_emit_sve_filter_load_secondary_candidates(
            assembler,
            filter,
            vector_filter,
            plan,
            0,
        )?;
        assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    }
    assembler.branch_cond(AARCH64_NE, single_hit)?;
    assembler.bind(partial_exhausted)?;
    if maximum_scan_offset == 0 {
        assembler.instruction(aarch64_mov_x(2, 3)?)?;
    } else {
        assembler.instruction(aarch64_sub_x_imm(2, 3, u16::from(maximum_scan_offset))?)?;
    }
    assembler.branch(scalar)?;

    assembler.bind(single_hit)?;
    aarch64_emit_sve_first_candidate(assembler, 1, candidate)?;
    Ok(())
}

fn aarch64_emit_prefix_relation_constants(
    assembler: &mut Aarch64Assembler,
    plan: NativePrefixRelationVectorPlan,
) -> Result<(), ObjectError> {
    if plan.constant_count > MAX_AARCH64_PREFIX_RELATION_CONSTANTS {
        return Err(ObjectError::InvalidModule(
            "AArch64 prefix-relation constant budget",
        ));
    }
    for rectangle in plan.rectangles() {
        for predicate in [rectangle.first, rectangle.second] {
            if predicate.any {
                continue;
            }
            for (index, range) in predicate.filter.ranges().iter().enumerate() {
                if predicate.filter.is_exact() {
                    let register =
                        aarch64_prefix_relation_constant_register(predicate.first_constant, index)?;
                    assembler.instruction(aarch64_movi_16b(register, range.start)?)?;
                } else {
                    let logical_low = index.checked_mul(2).ok_or(
                        ObjectError::ArithmeticOverflow("AArch64 prefix-relation range constant"),
                    )?;
                    let low = aarch64_prefix_relation_constant_register(
                        predicate.first_constant,
                        logical_low,
                    )?;
                    let high = aarch64_prefix_relation_constant_register(
                        predicate.first_constant,
                        logical_low
                            .checked_add(1)
                            .ok_or(ObjectError::ArithmeticOverflow(
                                "AArch64 prefix-relation range constant",
                            ))?,
                    )?;
                    assembler.instruction(aarch64_movi_16b(low, range.start)?)?;
                    assembler.instruction(aarch64_movi_16b(high, range.end)?)?;
                }
            }
        }
    }
    Ok(())
}

fn aarch64_emit_prefix_relation_predicate(
    assembler: &mut Aarch64Assembler,
    predicate: NativePrefixRelationPredicate,
    source: u8,
    destination: u8,
) -> Result<(), ObjectError> {
    if predicate.any {
        assembler.instruction(aarch64_cmeq_16b(destination, source, source)?)?;
        return Ok(());
    }
    if predicate.filter.is_exact() {
        let first = aarch64_prefix_relation_constant_register(predicate.first_constant, 0)?;
        assembler.instruction(aarch64_cmeq_16b(destination, source, first)?)?;
        for index in 1..predicate.filter.ranges().len() {
            let constant =
                aarch64_prefix_relation_constant_register(predicate.first_constant, index)?;
            assembler.instruction(aarch64_cmeq_16b(19, source, constant)?)?;
            assembler.instruction(aarch64_orr_16b(destination, destination, 19)?)?;
        }
    } else {
        for (index, _) in predicate.filter.ranges().iter().enumerate() {
            let logical_low = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 prefix-relation range constant",
            ))?;
            let low =
                aarch64_prefix_relation_constant_register(predicate.first_constant, logical_low)?;
            let high = aarch64_prefix_relation_constant_register(
                predicate.first_constant,
                logical_low
                    .checked_add(1)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 prefix-relation range constant",
                    ))?,
            )?;
            assembler.instruction(aarch64_cmhs_16b(18, source, low)?)?;
            assembler.instruction(aarch64_cmhs_16b(19, high, source)?)?;
            assembler.instruction(aarch64_and_16b(18, 18, 19)?)?;
            if index == 0 {
                assembler.instruction(aarch64_orr_16b(destination, 18, 18)?)?;
            } else {
                assembler.instruction(aarch64_orr_16b(destination, destination, 18)?)?;
            }
        }
    }
    if predicate.negated {
        assembler.instruction(aarch64_cmeq_16b(17, source, source)?)?;
        assembler.instruction(aarch64_eor_16b(destination, destination, 17)?)?;
    }
    Ok(())
}

/// Produce one exact rectangle-union mask without reducing it. V17..V21 are
/// caller-saved temporaries and V1..V6 are bounded constants; the
/// ABI-preserved V8..V15 bank is never touched.
fn aarch64_emit_prefix_relation_mask(
    assembler: &mut Aarch64Assembler,
    plan: NativePrefixRelationVectorPlan,
    first_source: u8,
    second_source: u8,
    destination: u8,
) -> Result<(), ObjectError> {
    if plan.rectangles().is_empty() {
        return Err(ObjectError::InvalidModule(
            "empty AArch64 prefix-relation vector plan",
        ));
    }
    for (index, rectangle) in plan.rectangles().iter().copied().enumerate() {
        aarch64_emit_prefix_relation_predicate(assembler, rectangle.first, first_source, 20)?;
        if !rectangle.second.any {
            aarch64_emit_prefix_relation_predicate(assembler, rectangle.second, second_source, 21)?;
            assembler.instruction(aarch64_and_16b(20, 20, 21)?)?;
        }
        if index == 0 {
            assembler.instruction(aarch64_orr_16b(destination, 20, 20)?)?;
        } else {
            assembler.instruction(aarch64_orr_16b(destination, destination, 20)?)?;
        }
    }
    Ok(())
}

/// Produce the exact 16-lane rectangle-union mask in V24 and leave condition
/// flags ready for the shared hit edge.
fn aarch64_emit_prefix_relation_vector_test(
    assembler: &mut Aarch64Assembler,
    plan: NativePrefixRelationVectorPlan,
) -> Result<(), ObjectError> {
    aarch64_emit_start_filter_address(assembler, 0)?;
    assembler.instruction(aarch64_load_q(0, 12)?)?;
    aarch64_emit_start_filter_address(assembler, 1)?;
    assembler.instruction(aarch64_load_q(16, 12)?)?;
    aarch64_emit_prefix_relation_mask(assembler, plan, 0, 16, 24)?;
    aarch64_emit_candidate_any(assembler, 24)
}

/// Produce four exact adjacent relation masks in V24..V27. The first byte
/// column is loaded once; EXT forms the overlapping second column for the
/// first three blocks, and one final load supplies byte 64 for the last.
fn aarch64_emit_prefix_relation_batch_candidates(
    assembler: &mut Aarch64Assembler,
    plan: NativePrefixRelationVectorPlan,
) -> Result<u8, ObjectError> {
    const FIRST_CANDIDATES: u8 = 24;
    aarch64_emit_start_filter_address(assembler, 0)?;
    assembler.instruction(aarch64_ld1_four_16b(FIRST_CANDIDATES, 12)?)?;
    for block in 0_u8..4 {
        let candidates =
            FIRST_CANDIDATES
                .checked_add(block)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 relation batch candidates",
                ))?;
        assembler.instruction(aarch64_orr_16b(0, candidates, candidates)?)?;
        if block < 3 {
            assembler.instruction(aarch64_ext_16b(16, candidates, candidates + 1, 1)?)?;
        } else {
            aarch64_emit_start_filter_address(assembler, 49)?;
            assembler.instruction(aarch64_load_q(16, 12)?)?;
        }
        aarch64_emit_prefix_relation_mask(assembler, plan, 0, 16, candidates)?;
    }
    Ok(FIRST_CANDIDATES)
}

fn aarch64_emit_start_filter_vector_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    source: u8,
    destination: u8,
    first_register: u8,
) -> Result<(), ObjectError> {
    if filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule(
            "empty AArch64 start filter reached vector lowering",
        ));
    }
    if !aarch64_caller_saved_simd(source)
        || !aarch64_caller_saved_simd(destination)
        || source == AARCH64_EXACT_FILTER_SCRATCH
        || destination == AARCH64_EXACT_FILTER_SCRATCH
    {
        return Err(ObjectError::InvalidModule(
            "ASIMD filter operands overlap an ABI-preserved or reserved register",
        ));
    }
    if filter.is_exact() {
        let first_constant = aarch64_filter_constant_register(first_register, 0)?;
        assembler.instruction(aarch64_cmeq_16b(destination, source, first_constant)?)?;
        for index in 1..filter.ranges().len() {
            let register = aarch64_filter_constant_register(first_register, index)?;
            // V28 is dead until the caller reduces the completed candidate
            // masks. Keeping the union scratch there avoids ABI-preserved
            // V8..V15 without consuming another persistent constant register.
            assembler.instruction(aarch64_cmeq_16b(
                AARCH64_EXACT_FILTER_SCRATCH,
                source,
                register,
            )?)?;
            assembler.instruction(aarch64_orr_16b(
                destination,
                destination,
                AARCH64_EXACT_FILTER_SCRATCH,
            )?)?;
        }
    } else {
        for (index, _) in filter.ranges().iter().enumerate() {
            let logical_low = index.checked_mul(2).ok_or(ObjectError::ArithmeticOverflow(
                "ASIMD range-filter low register",
            ))?;
            let logical_high =
                logical_low
                    .checked_add(1)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "ASIMD range-filter high register",
                    ))?;
            let low_register = aarch64_filter_constant_register(first_register, logical_low)?;
            let high_register = aarch64_filter_constant_register(first_register, logical_high)?;
            assembler.instruction(aarch64_cmhs_16b(5, source, low_register)?)?;
            assembler.instruction(aarch64_cmhs_16b(6, high_register, source)?)?;
            assembler.instruction(aarch64_and_16b(5, 5, 6)?)?;
            if index == 0 {
                assembler.instruction(aarch64_orr_16b(destination, 5, 5)?)?;
            } else {
                assembler.instruction(aarch64_orr_16b(destination, destination, 5)?)?;
            }
        }
    }
    Ok(())
}

fn aarch64_emit_start_filter_vector_test(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    source: u8,
    candidates: u8,
) -> Result<(), ObjectError> {
    let first_register = AARCH64_STANDALONE_FILTER_FIRST_CONSTANT;
    aarch64_emit_start_filter_vector_candidates(
        assembler,
        filter,
        source,
        candidates,
        first_register,
    )?;
    assembler.instruction(aarch64_umaxv_16b(candidates, candidates)?)?;
    assembler.instruction(aarch64_umov_b0(12, candidates)?)?;
    assembler.instruction(aarch64_cmp_w_zero(12)?)?;
    Ok(())
}

fn aarch64_emit_start_filter_address(
    assembler: &mut Aarch64Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_add_x_reg(12, 0, 2)?)?;
    if scan_offset != 0 {
        assembler.instruction(aarch64_add_x_imm(12, 12, u16::from(scan_offset))?)?;
    }
    Ok(())
}

fn aarch64_emit_vector_filter_secondary_candidates_at(
    assembler: &mut Aarch64Assembler,
    vector_filter: NativeVectorFilter,
    block_offset: u8,
    primary_candidates: u8,
) -> Result<(), ObjectError> {
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "AArch64 vector-filter intersection has one column",
        ));
    }
    let mut first_register = AARCH64_VECTOR_FILTER_FIRST_CONSTANT
        .checked_add(
            u8::try_from(vector_filter.columns()[0].constant_count())
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 vector-filter constants"))?,
        )
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 vector-filter constants",
        ))?;
    for &column in &vector_filter.columns()[1..] {
        let load_offset =
            block_offset
                .checked_add(column.scan_offset)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 vector-filter load offset",
                ))?;
        aarch64_emit_start_filter_address(assembler, load_offset)?;
        assembler.instruction(aarch64_load_q(0, 12)?)?;
        aarch64_emit_start_filter_vector_candidates(assembler, column, 0, 25, first_register)?;
        assembler.instruction(aarch64_and_16b(primary_candidates, primary_candidates, 25)?)?;
        first_register =
            first_register
                .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                    ObjectError::ArithmeticOverflow("AArch64 vector-filter constants")
                })?)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 vector-filter constants",
                ))?;
    }
    Ok(())
}

fn aarch64_emit_vector_filter_secondary_batch(
    assembler: &mut Aarch64Assembler,
    vector_filter: NativeVectorFilter,
) -> Result<(), ObjectError> {
    if vector_filter.columns().len() < 2 {
        return Err(ObjectError::InvalidModule(
            "AArch64 vector-filter intersection has one column",
        ));
    }
    let mut first_register = AARCH64_VECTOR_FILTER_FIRST_CONSTANT
        .checked_add(
            u8::try_from(vector_filter.columns()[0].constant_count())
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 vector-filter constants"))?,
        )
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 vector-filter constants",
        ))?;
    for &column in &vector_filter.columns()[1..] {
        aarch64_emit_start_filter_address(assembler, column.scan_offset)?;
        assembler.instruction(aarch64_ld1_four_16b(16, 12)?)?;
        for lane in 0_u8..4 {
            let source = 16_u8
                .checked_add(lane)
                .ok_or(ObjectError::ArithmeticOverflow("AArch64 LD1 source"))?;
            let secondary_candidates =
                20_u8
                    .checked_add(lane)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 secondary candidates",
                    ))?;
            let primary_candidates =
                24_u8
                    .checked_add(lane)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 primary candidates",
                    ))?;
            aarch64_emit_start_filter_vector_candidates(
                assembler,
                column,
                source,
                secondary_candidates,
                first_register,
            )?;
            assembler.instruction(aarch64_and_16b(
                primary_candidates,
                primary_candidates,
                secondary_candidates,
            )?)?;
        }
        first_register =
            first_register
                .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                    ObjectError::ArithmeticOverflow("AArch64 vector-filter constants")
                })?)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 vector-filter constants",
                ))?;
    }
    Ok(())
}

fn aarch64_emit_start_filter_batch_candidates(
    assembler: &mut Aarch64Assembler,
    filter: NativeStartFilter,
    first_register: u8,
) -> Result<u8, ObjectError> {
    let (first_source, first_candidates) = match first_register {
        AARCH64_VECTOR_FILTER_FIRST_CONSTANT..=4 => (16_u8, 24_u8),
        AARCH64_STANDALONE_FILTER_FIRST_CONSTANT => (24_u8, 0_u8),
        _ => {
            return Err(ObjectError::InvalidModule(
                "ASIMD batch filter has an invalid constant allocation",
            ));
        }
    };
    aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
    assembler.instruction(aarch64_ld1_four_16b(first_source, 12)?)?;
    for lane in 0_u8..4 {
        let source = first_source
            .checked_add(lane)
            .ok_or(ObjectError::ArithmeticOverflow("AArch64 LD1 source"))?;
        let candidates = first_candidates
            .checked_add(lane)
            .ok_or(ObjectError::ArithmeticOverflow("AArch64 batch candidates"))?;
        aarch64_emit_start_filter_vector_candidates(
            assembler,
            filter,
            source,
            candidates,
            first_register,
        )?;
    }
    Ok(first_candidates)
}

fn aarch64_emit_start_filter_scalar_bound(
    assembler: &mut Aarch64Assembler,
    scan_offset: u8,
    exhausted: Aarch64Label,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    } else {
        assembler.instruction(aarch64_add_x_imm(12, 2, u16::from(scan_offset))?)?;
        assembler.instruction(aarch64_cmp_x(12, 3)?)?;
    }
    assembler.branch_cond(AARCH64_HS, exhausted)?;
    Ok(())
}

fn aarch64_emit_start_filter_scalar_load(
    assembler: &mut Aarch64Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    if scan_offset == 0 {
        assembler.instruction(aarch64_load_byte_reg(8, 0, 2)?)?;
    } else {
        assembler.instruction(aarch64_add_x_reg(12, 0, 2)?)?;
        assembler.instruction(aarch64_load_byte_imm(8, 12, u16::from(scan_offset))?)?;
    }
    Ok(())
}

/// Test the byte already loaded in W8 through the canonical 0/1 LUT.
fn aarch64_emit_exact_byte_set_test(
    assembler: &mut Aarch64Assembler,
    storage: NativeExactByteSetStorage,
    member: Aarch64Label,
) -> Result<(), ObjectError> {
    let lut_offset = storage
        .aarch64_lut_offset
        .ok_or(ObjectError::InvalidModule(
            "AArch64 exact-set scanner has no LUT",
        ))?;
    aarch64_set_table_address(assembler, 12, lut_offset)?;
    aarch64_emit_exact_byte_set_lut_test(assembler, 12, member)
}

fn aarch64_emit_exact_byte_set_lut_test(
    assembler: &mut Aarch64Assembler,
    lut_base: u8,
    member: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_load_byte_reg(8, lut_base, 8)?)?;
    assembler.instruction(aarch64_cmp_w_imm(8, 0)?)?;
    assembler.branch_cond(AARCH64_NE, member)?;
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Aarch64ExactSveKind {
    Nibble,
    Sve2Match(NativeExactSve2MatchStorage),
}

impl Aarch64ExactSveKind {
    const fn scanner_isa(self) -> NativeScannerIsa {
        match self {
            Self::Nibble => NativeScannerIsa::Aarch64Sve,
            Self::Sve2Match(_) => NativeScannerIsa::Aarch64Sve2,
        }
    }
}

fn selected_aarch64_exact_sve_kind(
    operating_system: OperatingSystem,
    features: FeatureSet,
    storage: NativeExactByteSetStorage,
) -> Option<Aarch64ExactSveKind> {
    if !aarch64_primary_scanner_uses_sve(aarch64_primary_scanner_isa(
        operating_system,
        features,
        true,
    )) {
        return None;
    }
    if features.has(CpuFeature::Aarch64Sve2)
        && let Some(match_storage) = storage.sve2_match
    {
        Some(Aarch64ExactSveKind::Sve2Match(match_storage))
    } else {
        Some(Aarch64ExactSveKind::Nibble)
    }
}

fn aarch64_validate_exact_nibble_storage(
    storage: NativeExactByteSetStorage,
) -> Result<(), ObjectError> {
    let lut_end = storage
        .aarch64_lut_offset
        .and_then(|offset| offset.checked_add(256))
        .ok_or(ObjectError::InvalidModule(
            "AArch64 exact-set scanner has no bounded LUT",
        ))?;
    if !storage.nibble_base.is_multiple_of(16) || storage.nibble_base < lut_end {
        return Err(ObjectError::InvalidModule(
            "AArch64 exact-set nibble-table storage is malformed",
        ));
    }
    Ok(())
}

fn aarch64_emit_exact_sve_constants(
    assembler: &mut Aarch64Assembler,
    storage: NativeExactByteSetStorage,
    kind: Aarch64ExactSveKind,
) -> Result<(), ObjectError> {
    aarch64_validate_exact_nibble_storage(storage)?;
    assembler.instruction(aarch64_sve_ptrue_b())?;
    match kind {
        Aarch64ExactSveKind::Nibble => {
            aarch64_set_table_address(assembler, 12, storage.nibble_base)?;
            for register in 16_u8..=18 {
                assembler.instruction(aarch64_sve_ld1rqb(register, 12)?)?;
                if register != 18 {
                    assembler.instruction(aarch64_add_x_imm(12, 12, 16)?)?;
                }
            }
            assembler.instruction(aarch64_sve_dup_b_imm(19, 0x0f)?)?;
        }
        Aarch64ExactSveKind::Sve2Match(match_storage) => {
            if !(1..=MAX_AARCH64_EXACT_SVE2_MATCH_TABLES)
                .contains(&match_storage.table_count)
                || !match_storage.table_base.is_multiple_of(16)
                || match_storage.table_base
                    != storage.nibble_base.checked_add(48).ok_or(
                        ObjectError::ArithmeticOverflow("AArch64 exact SVE2 table base"),
                    )?
            {
                return Err(ObjectError::InvalidModule(
                    "AArch64 exact SVE2 table storage is malformed",
                ));
            }
            aarch64_set_table_address(assembler, 12, match_storage.table_base)?;
            for table in 0..match_storage.table_count {
                let register = 16_u8
                    .checked_add(table)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 exact SVE2 table register",
                    ))?;
                assembler.instruction(aarch64_sve_ld1rqb(register, 12)?)?;
                if table.checked_add(1) != Some(match_storage.table_count) {
                    assembler.instruction(aarch64_add_x_imm(12, 12, 16)?)?;
                }
            }
        }
    }
    Ok(())
}

/// Produce one exact scalable candidate predicate in P1.
///
/// The base-SVE route is the same exact three-table nibble classifier as the
/// fixed-width backends. SVE2 MATCH is selected only when at most four
/// minority-side tables were installed; dense sets invert that exact union
/// under P0, so inactive tail lanes always remain clear.
fn aarch64_emit_exact_sve_candidates(
    assembler: &mut Aarch64Assembler,
    kind: Aarch64ExactSveKind,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    aarch64_emit_start_filter_address(assembler, scan_offset)?;
    assembler.instruction(aarch64_sve_ld1b_vl(0, 12, 0)?)?;
    match kind {
        Aarch64ExactSveKind::Nibble => {
            assembler.instruction(aarch64_sve_lsr_b_by_4(4, 0)?)?;
            assembler.instruction(aarch64_sve_and_z(5, 0, 19)?)?;
            assembler.instruction(aarch64_sve_tbl_b(6, 16, 5)?)?;
            assembler.instruction(aarch64_sve_tbl_b(7, 17, 5)?)?;
            assembler.instruction(aarch64_sve_cmplt_zero_b(2, 0)?)?;
            assembler.instruction(aarch64_sve_sel_b(6, 2, 7, 6)?)?;
            assembler.instruction(aarch64_sve_tbl_b(4, 18, 4)?)?;
            assembler.instruction(aarch64_sve_and_z(6, 6, 4)?)?;
            assembler.instruction(aarch64_sve_cmpne_zero_b(1, 6)?)?;
        }
        Aarch64ExactSveKind::Sve2Match(match_storage) => {
            for table in 0..match_storage.table_count {
                let table_register = 16_u8
                    .checked_add(table)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 exact SVE2 table register",
                    ))?;
                let destination = if table == 0 { 1 } else { 2 };
                assembler.instruction(aarch64_sve2_match_b(
                    destination,
                    0,
                    table_register,
                )?)?;
                if table != 0 {
                    assembler.instruction(aarch64_sve_orr_b(1, 1, 2)?)?;
                }
            }
            if match_storage.complement {
                assembler.instruction(aarch64_sve_not_b(1, 1)?)?;
            }
        }
    }
    Ok(())
}

fn aarch64_emit_exact_sve_scanner(
    assembler: &mut Aarch64Assembler,
    exact: NativeExactByteSet,
    kind: Aarch64ExactSveKind,
    retained_vector_length: Option<u8>,
    vector: Aarch64Label,
    scalar: Aarch64Label,
    candidate: Aarch64Label,
) -> Result<(), ObjectError> {
    let single = assembler.label()?;
    let partial = assembler.label()?;
    let hit = assembler.label()?;

    assembler.bind(vector)?;
    assembler.instruction(aarch64_sve_ptrue_b())?;
    // Mixed-capability roots sampled their runtime VL after every prepass and
    // retain it in a leaf-scratch GPR across retries. Pure-SVE roots have no
    // dispatch sample and materialize the same byte count here.
    let vector_length = if let Some(vector_length) = retained_vector_length {
        vector_length
    } else {
        assembler.instruction(aarch64_sve_cntb(6)?)?;
        6
    };
    assembler.bind(single)?;
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    if exact.scan_offset != 0 {
        assembler.instruction(aarch64_cmp_x_imm(12, u16::from(exact.scan_offset))?)?;
        assembler.branch_cond(AARCH64_LS, scalar)?;
        assembler.instruction(aarch64_sub_x_imm(
            12,
            12,
            u16::from(exact.scan_offset),
        )?)?;
    }
    assembler.instruction(aarch64_cmp_x(12, vector_length)?)?;
    assembler.branch_cond(AARCH64_LO, partial)?;
    aarch64_emit_exact_sve_candidates(assembler, kind, exact.scan_offset)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    assembler.branch_cond(AARCH64_NE, hit)?;
    assembler.instruction(aarch64_sve_addvl(2, 2, 1)?)?;
    assembler.branch(single)?;

    assembler.bind(partial)?;
    let partial_end = if exact.scan_offset == 0 {
        3
    } else {
        assembler.instruction(aarch64_sub_x_imm(
            12,
            3,
            u16::from(exact.scan_offset),
        )?)?;
        12
    };
    assembler.instruction(aarch64_sve_whilelo_b(0, 2, partial_end)?)?;
    aarch64_emit_exact_sve_candidates(assembler, kind, exact.scan_offset)?;
    assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
    assembler.branch_cond(AARCH64_NE, hit)?;
    if exact.scan_offset == 0 {
        assembler.instruction(aarch64_mov_x(2, 3)?)?;
    } else {
        assembler.instruction(aarch64_sub_x_imm(
            2,
            3,
            u16::from(exact.scan_offset),
        )?)?;
    }
    assembler.branch(scalar)?;

    assembler.bind(hit)?;
    aarch64_emit_sve_first_candidate(assembler, 1, candidate)
}

fn aarch64_emit_exact_asimd_constants(
    assembler: &mut Aarch64Assembler,
    storage: NativeExactByteSetStorage,
) -> Result<(), ObjectError> {
    aarch64_validate_exact_nibble_storage(storage)?;
    aarch64_set_table_address(assembler, 6, storage.nibble_base)?;
    assembler.instruction(aarch64_ld1_three_16b(16, 6)?)?;
    assembler.instruction(aarch64_movi_16b(19, 0x0f)?)?;
    Ok(())
}

/// Produce one exact 16-lane arbitrary-byte-set mask in V24.
///
/// V16/V17 hold low/high row banks, V18 maps high nibbles to their row bit,
/// and V19 is the fixed low-nibble mask. The input byte's sign selects its row
/// bank, so every set bit in the result proves exact membership.
fn aarch64_emit_exact_asimd_candidates(
    assembler: &mut Aarch64Assembler,
    scan_offset: u8,
) -> Result<(), ObjectError> {
    aarch64_emit_start_filter_address(assembler, scan_offset)?;
    assembler.instruction(aarch64_load_q(0, 12)?)?;
    assembler.instruction(aarch64_ushr_16b_by_4(20, 0)?)?;
    assembler.instruction(aarch64_and_16b(21, 0, 19)?)?;
    assembler.instruction(aarch64_tbl1_16b(22, 16, 21)?)?;
    assembler.instruction(aarch64_tbl1_16b(23, 17, 21)?)?;
    assembler.instruction(aarch64_cmlt_zero_16b(24, 0)?)?;
    assembler.instruction(aarch64_bsl_16b(24, 23, 22)?)?;
    assembler.instruction(aarch64_and_16b(20, 20, 19)?)?;
    assembler.instruction(aarch64_tbl1_16b(20, 18, 20)?)?;
    assembler.instruction(aarch64_and_16b(24, 24, 20)?)?;
    assembler.instruction(aarch64_cmtst_16b(24, 24, 24)?)?;
    aarch64_emit_candidate_any(assembler, 24)
}

fn aarch64_emit_exact_asimd_scanner(
    assembler: &mut Aarch64Assembler,
    exact: NativeExactByteSet,
    vector: Aarch64Label,
    scalar: Aarch64Label,
    candidate: Aarch64Label,
    use_exact_lane: bool,
) -> Result<(), ObjectError> {
    let vector_hit = use_exact_lane.then(|| assembler.label()).transpose()?;
    assembler.bind(vector)?;
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    let required = u16::from(exact.scan_offset).checked_add(16).ok_or(
        ObjectError::ArithmeticOverflow("AArch64 exact ASIMD scanner bound"),
    )?;
    assembler.instruction(aarch64_cmp_x_imm(12, required)?)?;
    assembler.branch_cond(AARCH64_LO, scalar)?;
    aarch64_emit_exact_asimd_candidates(assembler, exact.scan_offset)?;
    assembler.branch_cond(AARCH64_NE, vector_hit.unwrap_or(scalar))?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
    assembler.branch(vector)?;
    if let Some(vector_hit) = vector_hit {
        assembler.bind(vector_hit)?;
        aarch64_emit_first_candidate_lane(assembler, 24)?;
        assembler.branch(candidate)?;
    }
    Ok(())
}

fn aarch64_emit_suffix_lower_bound(
    assembler: &mut Aarch64Assembler,
    backtrack: u64,
) -> Result<(), ObjectError> {
    if backtrack == 0 {
        return Ok(());
    }
    let clamp = assembler.label()?;
    let done = assembler.label()?;
    assembler.instruction(aarch64_sub_x_reg(12, 2, 9)?)?; // suffix base - window start
    if let Ok(immediate) = u16::try_from(backtrack)
        && immediate <= 0x0fff
    {
        assembler.instruction(aarch64_cmp_x_imm(12, immediate)?)?;
        assembler.branch_cond(AARCH64_LS, clamp)?;
        assembler.instruction(aarch64_sub_x_imm(2, 2, immediate)?)?;
    } else {
        aarch64_load_u64_constant(assembler, 6, backtrack)?;
        assembler.instruction(aarch64_cmp_x(12, 6)?)?;
        assembler.branch_cond(AARCH64_LS, clamp)?;
        assembler.instruction(aarch64_sub_x_reg(2, 2, 6)?)?;
    }
    assembler.branch(done)?;
    assembler.bind(clamp)?;
    assembler.instruction(aarch64_mov_x(2, 9)?)?;
    assembler.bind(done)?;
    Ok(())
}

fn aarch64_emit_suffix_reset_restart(
    assembler: &mut Aarch64Assembler,
    non_reset: NativeResetFilter,
) -> Result<(), ObjectError> {
    let scan = assembler.label()?;
    let non_reset_byte = assembler.label()?;
    let no_reset = assembler.label()?;
    let done = assembler.label()?;
    assembler.instruction(aarch64_mov_x(10, 2)?)?; // cursor = suffix base
    assembler.instruction(aarch64_movz_w(6, 64)?)?;
    assembler.bind(scan)?;
    assembler.instruction(aarch64_cmp_x(10, 9)?)?;
    assembler.branch_cond(AARCH64_LS, no_reset)?;
    assembler.instruction(aarch64_sub_x_imm(10, 10, 1)?)?;
    assembler.instruction(aarch64_load_byte_reg(8, 0, 10)?)?;
    for range in non_reset.ranges() {
        assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.start))?)?;
        if range.start == range.end {
            assembler.branch_cond(AARCH64_EQ, non_reset_byte)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch_cond(AARCH64_LO, next_range)?;
            assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.end))?)?;
            assembler.branch_cond(AARCH64_LS, non_reset_byte)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(aarch64_add_x_imm(2, 10, 1)?)?; // start = reset + 1
    assembler.branch(done)?;

    assembler.bind(non_reset_byte)?;
    assembler.instruction(aarch64_sub_w_imm(6, 6, 1)?)?;
    assembler.instruction(aarch64_cmp_w_zero(6)?)?;
    assembler.branch_cond(AARCH64_NE, scan)?;
    assembler.bind(no_reset)?;
    assembler.instruction(aarch64_mov_x(2, 9)?)?;
    assembler.bind(done)?;
    Ok(())
}

fn aarch64_emit_suffix_restart(
    assembler: &mut Aarch64Assembler,
    restart: NativeSuffixRestart,
) -> Result<(), ObjectError> {
    match restart {
        NativeSuffixRestart::Bounded { backtrack } => {
            aarch64_emit_suffix_lower_bound(assembler, backtrack)
        }
        NativeSuffixRestart::Synchronizing { non_reset } => {
            aarch64_emit_suffix_reset_restart(assembler, non_reset)
        }
        NativeSuffixRestart::OriginalStart => {
            assembler.instruction(aarch64_mov_x(2, 9)?)?;
            Ok(())
        }
    }
}

fn validate_aarch64_mandatory_teddy_layout(
    suffix: NativeSuffixFilter,
    teddy: NativeMandatoryTeddyLayout,
    features: FeatureSet,
    operating_system: OperatingSystem,
) -> Result<(), ObjectError> {
    if teddy.plan.bank_count() != 1
        || !(3..=4).contains(&teddy.plan.columns())
        || teddy.plan.columns() > suffix.minimum_width
        || suffix.retry.is_none()
        || teddy.vector_bytes != 16
        || !teddy
            .table_base
            .is_multiple_of(u32::try_from(AARCH64_MANDATORY_TEDDY_ALIGNMENT).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 mandatory Teddy alignment")
            })?)
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy layout shape",
        ));
    }
    let table_bytes = u32::from(teddy.plan.columns())
        .checked_mul(u32::try_from(AARCH64_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN).map_err(
            |_| ObjectError::ArithmeticOverflow("AArch64 mandatory Teddy table bytes"),
        )?)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 mandatory Teddy table extent",
        ))?;
    let expected_end = teddy
        .table_base
        .checked_add(table_bytes)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 mandatory Teddy table extent",
        ))?;
    let portfolio_owns_plan = suffix.teddy_portfolio.is_some_and(|portfolio| {
        portfolio.plans().any(|plan| *plan == teddy.plan)
    });
    if teddy.table_end != expected_end
        || teddy.nibble_mask_offset != expected_end
        || !portfolio_owns_plan
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy table receipt",
        ));
    }
    let supported = match teddy.isa {
        MandatoryTeddyIsa::Aarch64Asimd => features.has(CpuFeature::Aarch64Asimd),
        MandatoryTeddyIsa::Aarch64Sve => {
            operating_system == OperatingSystem::Linux
                && features.has(CpuFeature::Aarch64Sve)
        }
        MandatoryTeddyIsa::Aarch64Sve2 => {
            operating_system == OperatingSystem::Linux
                && features.has(CpuFeature::Aarch64Sve)
                && features.has(CpuFeature::Aarch64Sve2)
        }
        MandatoryTeddyIsa::X86Avx2 | MandatoryTeddyIsa::X86Avx512Bw => false,
    };
    if !supported {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy ISA receipt",
        ));
    }
    Ok(())
}

fn aarch64_mandatory_teddy_table_offset(
    teddy: NativeMandatoryTeddyLayout,
    column: usize,
    high: bool,
) -> Result<u32, ObjectError> {
    if column >= usize::from(teddy.plan.columns()) {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy table column",
        ));
    }
    let bank_offset = if high { 16 } else { 0 };
    let offset = column
        .checked_mul(AARCH64_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN)
        .and_then(|offset| offset.checked_add(bank_offset))
        .and_then(|offset| u32::try_from(offset).ok())
        .and_then(|offset| teddy.table_base.checked_add(offset))
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 mandatory Teddy table offset",
        ))?;
    let end = offset
        .checked_add(16)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 mandatory Teddy table offset",
        ))?;
    if end > teddy.table_end {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy table offset escaped receipt",
        ));
    }
    Ok(offset)
}

fn aarch64_emit_mandatory_teddy_asimd_constants(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    aarch64_set_table_address(assembler, 12, teddy.table_base)?;
    for column in 0..usize::from(teddy.plan.columns()) {
        let first = u8::try_from(
            16_usize
                .checked_add(column.checked_mul(2).ok_or(
                    ObjectError::ArithmeticOverflow("AArch64 Teddy constant register"),
                )?)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 Teddy constant register",
                ))?,
        )
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 Teddy constant register"))?;
        let second = first
            .checked_add(1)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 Teddy constant register",
            ))?;
        let byte_offset = u16::try_from(
            column
                .checked_mul(AARCH64_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 Teddy constant offset",
                ))?,
        )
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 Teddy constant offset"))?;
        assembler.instruction(aarch64_load_pair_q(first, second, 12, byte_offset)?)?;
    }
    Ok(())
}

fn aarch64_emit_mandatory_teddy_sve_constants(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_sve_ptrue_b())?;
    aarch64_set_table_address(assembler, 12, teddy.table_base)?;
    let table_count = teddy
        .plan
        .columns()
        .checked_mul(2)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy table count",
        ))?;
    for table in 0..table_count {
        let register = 16_u8
            .checked_add(table)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 SVE Teddy constant register",
            ))?;
        assembler.instruction(aarch64_sve_ld1rqb(register, 12)?)?;
        if table.checked_add(1) != Some(table_count) {
            assembler.instruction(aarch64_add_x_imm(12, 12, 16)?)?;
        }
    }
    Ok(())
}

/// Produce one exact 16-lane correlated candidate mask in V24.
fn aarch64_emit_mandatory_teddy_asimd_candidates(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let scan_offset = u8::try_from(column).map_err(|_| {
            ObjectError::ArithmeticOverflow("AArch64 mandatory Teddy scan offset")
        })?;
        aarch64_emit_start_filter_address(assembler, scan_offset)?;
        assembler.instruction(aarch64_load_q(0, 12)?)?;
        assembler.instruction(aarch64_ushr_16b_by_4(25, 0)?)?;
        assembler.instruction(aarch64_and_16b(27, 0, 26)?)?;
        let low = 16_u8
            .checked_add(scan_offset.checked_mul(2).ok_or(
                ObjectError::ArithmeticOverflow("AArch64 Teddy table register"),
            )?)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 Teddy table register",
            ))?;
        let high = low.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 Teddy table register",
        ))?;
        assembler.instruction(aarch64_tbl1_16b(28, low, 27)?)?;
        assembler.instruction(aarch64_tbl1_16b(7, high, 25)?)?;
        assembler.instruction(aarch64_and_16b(28, 28, 7)?)?;
        if column == 0 {
            assembler.instruction(aarch64_orr_16b(24, 28, 28)?)?;
        } else {
            assembler.instruction(aarch64_and_16b(24, 24, 28)?)?;
        }
    }
    // Table bytes are bucket identities, not boolean bytes. Convert every
    // nonzero identity to the exact ff/00 mask required by first-lane BSL.
    assembler.instruction(aarch64_cmtst_16b(24, 24, 24)?)?;
    aarch64_emit_candidate_any(assembler, 24)
}

/// Produce one exact scalable correlated candidate predicate for one runtime
/// vector. Base SVE TBL is used for both SVE and SVE2 targets; MATCH cannot
/// retain bucket IDs.
fn aarch64_emit_mandatory_teddy_sve_candidates_at(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
    vector_offset: u8,
    candidates: u8,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let scan_offset = u8::try_from(column).map_err(|_| {
            ObjectError::ArithmeticOverflow("AArch64 SVE Teddy scan offset")
        })?;
        aarch64_emit_start_filter_address(assembler, scan_offset)?;
        assembler.instruction(aarch64_sve_ld1b_vl(0, 12, vector_offset)?)?;
        assembler.instruction(aarch64_sve_lsr_b_by_4(4, 0)?)?;
        assembler.instruction(aarch64_sve_and_z(5, 0, 26)?)?;
        let low = 16_u8
            .checked_add(scan_offset.checked_mul(2).ok_or(
                ObjectError::ArithmeticOverflow("AArch64 SVE Teddy table register"),
            )?)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 SVE Teddy table register",
            ))?;
        let high = low.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy table register",
        ))?;
        assembler.instruction(aarch64_sve_tbl_b(7, low, 5)?)?;
        assembler.instruction(aarch64_sve_tbl_b(0, high, 4)?)?;
        assembler.instruction(aarch64_sve_and_z(7, 7, 0)?)?;
        if column == 0 {
            assembler.instruction(aarch64_sve_and_z(6, 7, 7)?)?;
        } else {
            assembler.instruction(aarch64_sve_and_z(6, 6, 7)?)?;
        }
    }
    assembler.instruction(aarch64_sve_cmpne_zero_b(candidates, 6)?)?;
    Ok(())
}

/// Produce four exact scalable correlated candidate predicates while keeping
/// each block's bucket bytes live in caller-saved scalable registers.
///
/// The previous four-vector composition called the one-vector emitter in
/// block-outer order and reused its small scratch bank. A four-vector miss
/// batch has no such dependency: make it column-outer, compute each column
/// address once, and give the four lookup chains independent Z registers.
/// Besides removing three address formations per column, this exposes the
/// independent load/TBL latency to the core. The retained bucket vectors let
/// the exact wrapper recover a hit's bucket byte directly instead of replaying
/// the scalar nibble tables at that lane.
const AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS: [u8; 4] = [24, 25, 27, 28];

/// Admit the single-column batch check only while the stable model predicts
/// at most one first-column survivor across all four runtime vectors. This is
/// deliberately stricter than instruction-count break-even: at the admitted
/// boundary the independent-byte model predicts an all-zero batch about 37%
/// of the time, leaving a material margin for the extra survivor-side test.
/// Automatic exact-Teddy selection normally prefers the incumbent accelerator
/// for such a sparse column; this primarily benefits the explicit
/// forced-structural policy used to compare the composite scanner with stock.
const AARCH64_MANDATORY_TEDDY_SVE_SINGLE_PREFIX_EXPECTED_HITS: u16 = 1;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Aarch64MandatoryTeddySveBatchPlan {
    column_order: [u8; 4],
    single_prefix_max_vector_bytes: Option<u16>,
}

fn aarch64_mandatory_teddy_sve_column_union_frequency(
    plan: &MandatoryTeddyPlan,
    column: usize,
) -> Result<u16, ObjectError> {
    let bank = plan.bank(0).ok_or(ObjectError::InvalidModule(
        "AArch64 SVE Teddy batch has no mask bank",
    ))?;
    let low = bank.low(column).ok_or(ObjectError::InvalidModule(
        "AArch64 SVE Teddy batch has no low table",
    ))?;
    let high = bank.high(column).ok_or(ObjectError::InvalidModule(
        "AArch64 SVE Teddy batch has no high table",
    ))?;
    let mut frequency = 0_u16;
    for byte in u8::MIN..=u8::MAX {
        if low[usize::from(byte & 0x0f)] & high[usize::from(byte >> 4)] != 0 {
            frequency = frequency
                .saturating_add(estimated_byte_frequency_units(byte))
                .min(BYTE_FREQUENCY_DENOMINATOR);
        }
    }
    Ok(frequency)
}

/// Order the four possible fingerprint columns so the first two form the
/// smallest stable-frequency product estimate. An empty intersection after
/// those two columns proves that every deeper intersection is empty too.
/// Within the selected pair, put the smaller exact bucket-union frequency
/// first so a sufficiently sparse singleton can reject a complete batch.
/// Remaining columns retain chronological order because their order cannot
/// affect the exact bucket result.
#[allow(
    clippy::too_many_lines,
    reason = "one bounded planner keeps pair scoring, orientation, and VL admission auditable together"
)]
fn aarch64_mandatory_teddy_sve_batch_plan(
    plan: &MandatoryTeddyPlan,
) -> Result<Aarch64MandatoryTeddySveBatchPlan, ObjectError> {
    let columns = usize::from(plan.columns());
    if plan.bank_count() != 1
        || !(3..=4).contains(&columns)
        || !(1..=8).contains(&plan.bucket_count())
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 SVE Teddy batch does not have a slim 3/4-column plan",
        ));
    }
    let bank = plan.bank(0).ok_or(ObjectError::InvalidModule(
        "AArch64 SVE Teddy batch has no mask bank",
    ))?;
    let mut frequency = [[0_u16; 8]; 4];
    let mut union_frequency = [0_u16; 4];
    for (column, frequencies) in frequency[..columns].iter_mut().enumerate() {
        let low = bank.low(column).ok_or(ObjectError::InvalidModule(
            "AArch64 SVE Teddy batch has no low table",
        ))?;
        let high = bank.high(column).ok_or(ObjectError::InvalidModule(
            "AArch64 SVE Teddy batch has no high table",
        ))?;
        union_frequency[column] =
            aarch64_mandatory_teddy_sve_column_union_frequency(plan, column)?;
        for byte in u8::MIN..=u8::MAX {
            let buckets = low[usize::from(byte & 0x0f)] & high[usize::from(byte >> 4)];
            for (bucket, units) in frequencies
                [..usize::from(plan.bucket_count())]
                .iter_mut()
                .enumerate()
            {
                let bit = 1_u8.checked_shl(u32::try_from(bucket).map_err(|_| {
                    ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch bucket")
                })?)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 SVE Teddy batch bucket bit",
                ))?;
                if buckets & bit != 0 {
                    *units = units
                        .saturating_add(estimated_byte_frequency_units(byte))
                        .min(BYTE_FREQUENCY_DENOMINATOR);
                }
            }
        }
    }

    // The sum is a bucket-union estimate under the stable independent-byte
    // model. It is only a profitability estimate; semantic safety comes
    // solely from checking an intermediate AND for zero. Stable
    // (score, left, right) ordering gives deterministic output when pairs tie.
    let mut best = (u64::MAX, 0_usize, 1_usize);
    for left in 0..columns {
        let first_right = left.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy pair column",
        ))?;
        for right in first_right..columns {
            let score = (0..usize::from(plan.bucket_count())).fold(0_u64, |sum, bucket| {
                sum.saturating_add(
                    u64::from(frequency[left][bucket])
                        .saturating_mul(u64::from(frequency[right][bucket])),
                )
            });
            best = best.min((score, left, right));
        }
    }
    let (first, second) = if (union_frequency[best.1], best.1)
        <= (union_frequency[best.2], best.2)
    {
        (best.1, best.2)
    } else {
        (best.2, best.1)
    };
    let mut order = [0_u8; 4];
    order[0] = u8::try_from(first)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy first column"))?;
    order[1] = u8::try_from(second)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy second column"))?;
    let mut next = 2_usize;
    for column in 0..columns {
        if column != first && column != second {
            order[next] = u8::try_from(column).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 SVE Teddy remaining column")
            })?;
            next = next.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 SVE Teddy column order",
            ))?;
        }
    }
    let first_frequency = union_frequency[first];
    if first_frequency == 0 {
        return Err(ObjectError::InvalidModule(
            "AArch64 SVE Teddy batch has an empty first column",
        ));
    }
    let expected_hits_per_vector_byte = u32::try_from(
        AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS.len(),
    )
    .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch vectors"))?
    .checked_mul(u32::from(first_frequency))
    .ok_or(ObjectError::ArithmeticOverflow(
        "AArch64 SVE Teddy singleton expected hits",
    ))?;
    let hit_budget = u32::from(AARCH64_MANDATORY_TEDDY_SVE_SINGLE_PREFIX_EXPECTED_HITS)
        .checked_mul(u32::from(BYTE_FREQUENCY_DENOMINATOR))
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy singleton hit budget",
        ))?;
    let raw_maximum = hit_budget.checked_div(expected_hits_per_vector_byte).ok_or(
        ObjectError::ArithmeticOverflow("AArch64 SVE Teddy singleton hit divisor"),
    )?;
    let minimum = u32::from(AARCH64_SVE_MIN_VECTOR_BYTES);
    let rounded = raw_maximum
        .checked_div(minimum)
        .and_then(|vectors| vectors.checked_mul(minimum))
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy singleton vector rounding",
        ))?;
    let single_prefix_max_vector_bytes = (rounded >= minimum)
        .then(|| u16::try_from(rounded.min(u32::from(AARCH64_SVE_MAX_VECTOR_BYTES))))
        .transpose()
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy singleton vector bound"))?;
    Ok(Aarch64MandatoryTeddySveBatchPlan {
        column_order: order,
        single_prefix_max_vector_bytes,
    })
}

#[allow(
    clippy::arithmetic_side_effects,
    reason = "the four-entry register map proves every fixed u8 offset remains in range"
)]
fn aarch64_emit_mandatory_teddy_sve_batch4_column(
    assembler: &mut Aarch64Assembler,
    teddy: &NativeMandatoryTeddyLayout,
    column: u8,
    initialize: bool,
) -> Result<(), ObjectError> {
    let batch_vectors = u8::try_from(AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS.len())
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch vectors"))?;
    if column >= teddy.plan.columns() {
        return Err(ObjectError::InvalidModule(
            "AArch64 SVE Teddy batch column is out of range",
        ));
    }
    aarch64_emit_start_filter_address(assembler, column)?;

    // Z0..Z3 hold the four input/low-table chains and Z4..Z7 the
    // corresponding high-table chains. All are caller-saved under the
    // ordinary scalar PCS used by the exported matcher.
    for block in 0_u8..batch_vectors {
        assembler.instruction(aarch64_sve_ld1b_vl(block, 12, block)?)?;
    }
    for block in 0_u8..batch_vectors {
        assembler.instruction(aarch64_sve_lsr_b_by_4(4 + block, block)?)?;
    }
    for block in 0_u8..batch_vectors {
        assembler.instruction(aarch64_sve_and_z(block, block, 26)?)?;
    }

    let low = 16_u8
        .checked_add(column.checked_mul(2).ok_or(
            ObjectError::ArithmeticOverflow("AArch64 SVE Teddy table register"),
        )?)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 SVE Teddy table register",
        ))?;
    let high = low.checked_add(1).ok_or(ObjectError::ArithmeticOverflow(
        "AArch64 SVE Teddy table register",
    ))?;
    for block in 0_u8..batch_vectors {
        // TBL permits its destination to alias its index vector.
        assembler.instruction(aarch64_sve_tbl_b(block, low, block)?)?;
    }
    for block in 0_u8..batch_vectors {
        assembler.instruction(aarch64_sve_tbl_b(4 + block, high, 4 + block)?)?;
    }
    if initialize {
        // The first column has no prior bucket state. Intersect its low/high
        // table results directly into the retained registers instead of
        // materializing four temporary intersections and then copying them.
        for (block, &buckets) in AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS
            .iter()
            .enumerate()
        {
            let source = u8::try_from(block)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch source"))?;
            assembler.instruction(aarch64_sve_and_z(buckets, source, 4 + source)?)?;
        }
    } else {
        for block in 0_u8..batch_vectors {
            assembler.instruction(aarch64_sve_and_z(block, block, 4 + block)?)?;
        }
        for (block, &buckets) in AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS
            .iter()
            .enumerate()
        {
            let source = u8::try_from(block)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch source"))?;
            assembler.instruction(aarch64_sve_and_z(buckets, buckets, source)?)?;
        }
    }
    Ok(())
}

fn aarch64_emit_mandatory_teddy_sve_batch4_predicates(
    assembler: &mut Aarch64Assembler,
) -> Result<(), ObjectError> {
    for (block, &buckets) in AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS
        .iter()
        .enumerate()
    {
        let candidates = u8::try_from(block)
            .ok()
            .and_then(|block| block.checked_add(1))
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 SVE Teddy batch predicate",
            ))?;
        assembler.instruction(aarch64_sve_cmpne_zero_b(candidates, buckets)?)?;
    }
    Ok(())
}

/// Publish NZCV for the existential union of all four retained bucket
/// vectors without materializing their four durable hit predicates. P8 and
/// caller-saved Z4/Z5 are scratch; the exact Z24/Z25/Z27/Z28 bucket
/// identities survive without touching callee-saved V8..V15 state.
fn aarch64_emit_mandatory_teddy_sve_batch4_any(
    assembler: &mut Aarch64Assembler,
) -> Result<(), ObjectError> {
    assembler.instruction(aarch64_sve_orr_z(4, 24, 25)?)?;
    assembler.instruction(aarch64_sve_orr_z(5, 27, 28)?)?;
    assembler.instruction(aarch64_sve_orr_z(4, 4, 5)?)?;
    assembler.instruction(aarch64_sve_cmpne_zero_b(8, 4)?)?;
    assembler.instruction(aarch64_sve_ptest_p0(8)?)?;
    Ok(())
}

fn aarch64_emit_mandatory_teddy_sve_batch4_candidates(
    assembler: &mut Aarch64Assembler,
    teddy: &NativeMandatoryTeddyLayout,
    vector: Aarch64Label,
    single_prefix: bool,
) -> Result<(), ObjectError> {
    let batch_vectors = u8::try_from(AARCH64_MANDATORY_TEDDY_SVE_BATCH_BUCKET_REGISTERS.len())
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 SVE Teddy batch vectors"))?;
    let batch_suffix = assembler.label()?;
    let batch_plan = aarch64_mandatory_teddy_sve_batch_plan(&teddy.plan)?;
    if single_prefix && batch_plan.single_prefix_max_vector_bytes.is_none() {
        return Err(ObjectError::InvalidModule(
            "AArch64 SVE Teddy singleton prefix was not admitted",
        ));
    }
    for (index, &column) in batch_plan.column_order[..usize::from(teddy.plan.columns())]
        .iter()
        .enumerate()
    {
        aarch64_emit_mandatory_teddy_sve_batch4_column(
            assembler,
            teddy,
            column,
            index == 0,
        )?;
        if index == 0 && single_prefix {
            let second_column = assembler.label()?;
            aarch64_emit_mandatory_teddy_sve_batch4_any(assembler)?;
            assembler.branch_cond(AARCH64_NE, second_column)?;
            assembler.instruction(aarch64_sve_addvl(2, 2, batch_vectors)?)?;
            assembler.branch(vector)?;
            assembler.bind(second_column)?;
        }
        if index == 1 {
            aarch64_emit_mandatory_teddy_sve_batch4_any(assembler)?;
            // Make the expected prefix miss the fall-through path. The
            // omitted suffix is branch-only and runs only when at least one
            // prefix bucket survives the whole batch.
            assembler.branch_cond(AARCH64_NE, batch_suffix)?;
            assembler.instruction(aarch64_sve_addvl(2, 2, batch_vectors)?)?;
            assembler.branch(vector)?;
            assembler.bind(batch_suffix)?;
        }
    }
    Ok(())
}

/// Produce one exact scalable correlated candidate predicate in P1.
fn aarch64_emit_mandatory_teddy_sve_candidates(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    aarch64_emit_mandatory_teddy_sve_candidates_at(assembler, teddy, 0, 1)
}

fn aarch64_emit_mandatory_teddy_scalar_candidate(
    assembler: &mut Aarch64Assembler,
    teddy: NativeMandatoryTeddyLayout,
) -> Result<(), ObjectError> {
    for column in 0..usize::from(teddy.plan.columns()) {
        let scan_offset = u8::try_from(column).map_err(|_| {
            ObjectError::ArithmeticOverflow("AArch64 scalar Teddy scan offset")
        })?;
        aarch64_emit_start_filter_scalar_load(assembler, scan_offset)?;
        assembler.instruction(aarch64_and_low_w(6, 8, 4)?)?;
        aarch64_set_table_address(
            assembler,
            12,
            aarch64_mandatory_teddy_table_offset(teddy, column, false)?,
        )?;
        assembler.instruction(aarch64_load_byte_reg(6, 12, 6)?)?;
        assembler.instruction(aarch64_lsr_w_imm(8, 8, 4)?)?;
        aarch64_set_table_address(
            assembler,
            12,
            aarch64_mandatory_teddy_table_offset(teddy, column, true)?,
        )?;
        assembler.instruction(aarch64_load_byte_reg(8, 12, 8)?)?;
        assembler.instruction(aarch64_and_w(6, 6, 8)?)?;
        if column == 0 {
            assembler.instruction(aarch64_and_w(10, 6, 6)?)?;
        } else {
            assembler.instruction(aarch64_and_w(10, 10, 6)?)?;
        }
    }
    assembler.instruction(aarch64_cmp_w_zero(10)?)?;
    Ok(())
}

/// Fixed-width ASIMD half of the root-first correlated-prefix cascade. The
/// exact root scanner supplies the earliest possible match base; exhaustion
/// here is an exact negative, while the first fingerprint collision is still
/// a safe lower bound on match start.
#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the lowering-only gate keeps one authenticated layout and its complete backend transaction together"
)]
fn aarch64_emit_dynamic_correlated_prefix_gate(
    assembler: &mut Aarch64Assembler,
    gate: NativeDynamicCorrelatedPrefixLayout,
    root_plan: Aarch64DynamicScannerPlan,
    root_dispatch: Aarch64Label,
    root_representation_offset: u16,
    continue_selector: Aarch64Label,
    no_match: Aarch64Label,
) -> Result<Aarch64Label, ObjectError> {
    let teddy = gate.teddy;
    let columns = usize::from(teddy.plan.columns());
    let expected_end = usize::try_from(teddy.table_base)
        .ok()
        .and_then(|base| {
            columns
                .checked_mul(AARCH64_MANDATORY_TEDDY_TABLE_BYTES_PER_COLUMN)
                .and_then(|bytes| base.checked_add(bytes))
        });
    let expected_lane_end = gate.aarch64_lane_index_offset.and_then(|offset| {
        offset.checked_add(u32::try_from(AARCH64_FIRST_LANE_INDEX.len()).ok()?)
    });
    if teddy.isa != MandatoryTeddyIsa::Aarch64Asimd
        || teddy.plan.bank_count() != 1
        || !(3..=4).contains(&teddy.plan.columns())
        || teddy.vector_bytes != 16
        || expected_end != usize::try_from(teddy.table_end).ok()
        || teddy.nibble_mask_offset != teddy.table_end
        || expected_lane_end != Some(gate.payload_end)
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 dynamic correlated-prefix layout is malformed",
        ));
    }

    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let vector_candidate = assembler.label()?;
    let candidate = assembler.label()?;
    let exhausted = assembler.label()?;
    let restore_selector = assembler.label()?;
    let scan_from_root = assembler.label()?;

    assembler.instruction(aarch64_load_x_imm(2, 31, 48)?)?;
    assembler.instruction(aarch64_load_x_imm(3, 31, 56)?)?;
    assembler.instruction(aarch64_sub_x_reg(8, 3, 2)?)?;
    let minimum = u16::try_from(PARTIAL_DFA_MIN_INPUT_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 correlated-prefix input floor"))?;
    assembler.instruction(aarch64_cmp_x_imm(8, minimum)?)?;
    assembler.branch_cond(AARCH64_LO, restore_selector)?;

    // The prefix gate may answer before any compact-format selector. First
    // authenticate that its handle is live and belongs to the graph whose
    // correlated literals were compiled into these tables. A mismatch skips
    // the gate and retains the incumbent selector's full fallback contract.
    assembler.instruction(aarch64_load_x_imm(0, 31, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, 80)?)?;
    assembler.instruction(aarch64_load_x_imm(
        8,
        0,
        u16::try_from(FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL_OFFSET).map_err(|_| {
            ObjectError::ArithmeticOverflow(
                "AArch64 correlated-prefix active-seal offset",
            )
        })?,
    )?)?;
    aarch64_load_u64_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, restore_selector)?;
    for identity_word in 0_usize..4 {
        let word_offset = identity_word
            .checked_mul(core::mem::size_of::<u64>())
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 correlated-prefix identity word",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            8,
            6,
            u16::try_from(word_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 correlated-prefix linked identity offset",
                )
            })?,
        )?)?;
        let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
            .checked_add(word_offset)
            .ok_or(ObjectError::ArithmeticOverflow(
                "AArch64 correlated-prefix header identity offset",
            ))?;
        assembler.instruction(aarch64_load_x_imm(
            9,
            0,
            u16::try_from(header_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow(
                    "AArch64 correlated-prefix header identity displacement",
                )
            })?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, restore_selector)?;
    }

    // Representation zero reserves one pre-selector pass through the exact
    // graph root scanner. Install its constants here instead of using the
    // shared post-selector setup, whose endpoint path may reuse SP+80 after
    // the active identity has already served its purpose.
    assembler.instruction(aarch64_load_x_imm(0, 31, 8)?)?;
    assembler.instruction(aarch64_store_x(
        31,
        31,
        root_representation_offset,
    )?)?;
    aarch64_emit_dynamic_root_setup(assembler, root_plan)?;
    assembler.branch(root_dispatch)?;

    // X2 is the exact first root base. The root scanner may borrow the other
    // public scan registers and vector constants, so restore the end and
    // identity anchor before installing Teddy's independent constants.
    assembler.bind(scan_from_root)?;
    assembler.instruction(aarch64_load_x_imm(0, 31, 8)?)?;
    assembler.instruction(aarch64_load_x_imm(3, 31, 56)?)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, 80)?)?;

    aarch64_emit_mandatory_teddy_asimd_constants(assembler, teddy)?;
    aarch64_emit_first_lane_constants(
        assembler,
        gate.aarch64_lane_index_offset.ok_or(
            ObjectError::InvalidModule(
                "AArch64 dynamic correlated-prefix lane ramp is absent",
            ),
        )?,
    )?;
    assembler.instruction(aarch64_movi_16b(26, 0x0f)?)?;
    assembler.bind(vector)?;
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    let required = u16::from(
        teddy
            .plan
            .columns()
            .checked_sub(1)
            .ok_or(ObjectError::InvalidModule(
                "AArch64 correlated-prefix plan has no columns",
            ))?,
    )
    .checked_add(16)
    .ok_or(ObjectError::ArithmeticOverflow(
        "AArch64 correlated-prefix vector bound",
    ))?;
    assembler.instruction(aarch64_cmp_x_imm(12, required)?)?;
    assembler.branch_cond(AARCH64_LO, scalar)?;
    aarch64_emit_mandatory_teddy_asimd_candidates(assembler, teddy)?;
    assembler.branch_cond(AARCH64_NE, vector_candidate)?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
    assembler.branch(vector)?;

    assembler.bind(scalar)?;
    let maximum_offset = teddy.plan.columns().checked_sub(1).ok_or(
        ObjectError::InvalidModule("AArch64 correlated-prefix plan has no columns"),
    )?;
    aarch64_emit_start_filter_scalar_bound(assembler, maximum_offset, exhausted)?;
    aarch64_emit_mandatory_teddy_scalar_candidate(assembler, teddy)?;
    assembler.branch_cond(AARCH64_NE, candidate)?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    assembler.branch(scalar)?;

    assembler.bind(vector_candidate)?;
    aarch64_emit_first_candidate_lane(assembler, 24)?;
    assembler.branch(candidate)?;

    assembler.bind(exhausted)?;
    assembler.branch(no_match)?;

    assembler.bind(candidate)?;
    // Preserve the candidate-derived lower bound in the private semantic
    // window. The restored public base still keeps result offsets absolute.
    assembler.instruction(aarch64_store_x(2, 31, 48)?)?;
    assembler.branch(restore_selector)?;
    assembler.bind(restore_selector)?;
    // Scalar classification borrows W6, so restore the identity together with
    // every public argument before compact authentication resumes.
    assembler.instruction(aarch64_load_pair_x(0, 1, 31, 0)?)?;
    assembler.instruction(aarch64_load_pair_x(2, 5, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(3, 4, 31, 48)?)?;
    assembler.instruction(aarch64_load_x_imm(6, 31, 80)?)?;
    assembler.branch(continue_selector)?;
    Ok(scan_from_root)
}

/// Correlated mandatory suffix scanner. Every false candidate re-enters at
/// the verifier's exact `candidate + 1`; unlike x86, AArch64 simply rebuilds
/// the next vector mask. This is valid for every transition representation,
/// including ASIMD/SVE resource-fallback row lookups that clobber V24/P1.
fn aarch64_emit_mandatory_teddy_suffix_prepass(
    assembler: &mut Aarch64Assembler,
    suffix: NativeSuffixFilter,
    teddy: NativeMandatoryTeddyLayout,
    features: FeatureSet,
    operating_system: OperatingSystem,
    layout: NativeDfaLayout,
    no_match: Aarch64Label,
    matched: Aarch64Label,
) -> Result<(), ObjectError> {
    validate_aarch64_mandatory_teddy_layout(suffix, teddy, features, operating_system)?;
    if layout.seeded_reverse.is_some() {
        return Err(ObjectError::InvalidModule(
            "AArch64 mandatory Teddy overlaps seeded reverse",
        ));
    }
    let retry_scan = assembler.label()?;
    let vector = assembler.label()?;
    let scalar = assembler.label()?;
    let vector_hit = assembler.label()?;
    let apply = assembler.label()?;
    let maximum_offset = teddy.plan.columns().checked_sub(1).ok_or(
        ObjectError::InvalidModule("AArch64 mandatory Teddy has no columns"),
    )?;

    match teddy.isa {
        MandatoryTeddyIsa::Aarch64Asimd => {
            aarch64_emit_mandatory_teddy_asimd_constants(assembler, teddy)?;
            assembler.bind(retry_scan)?;
            // V26 is intentionally rematerialized after exact verification:
            // scalable resource-row lookup may use the same caller-saved bank.
            assembler.instruction(aarch64_movi_16b(26, 0x0f)?)?;
            assembler.bind(vector)?;
            assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
            let required = u16::from(maximum_offset)
                .checked_add(16)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 mandatory Teddy vector bound",
                ))?;
            assembler.instruction(aarch64_cmp_x_imm(12, required)?)?;
            assembler.branch_cond(AARCH64_LO, scalar)?;
            aarch64_emit_mandatory_teddy_asimd_candidates(assembler, teddy)?;
            assembler.branch_cond(AARCH64_NE, vector_hit)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
            assembler.branch(vector)?;

            assembler.bind(vector_hit)?;
            aarch64_emit_first_candidate_lane(assembler, 24)?;
            assembler.branch(apply)?;

            assembler.bind(scalar)?;
            aarch64_emit_start_filter_scalar_bound(assembler, maximum_offset, no_match)?;
            aarch64_emit_mandatory_teddy_scalar_candidate(assembler, teddy)?;
            assembler.branch_cond(AARCH64_NE, apply)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
            assembler.branch(scalar)?;
        }
        MandatoryTeddyIsa::Aarch64Sve | MandatoryTeddyIsa::Aarch64Sve2 => {
            let partial = assembler.label()?;
            aarch64_emit_mandatory_teddy_sve_constants(assembler, teddy)?;
            assembler.bind(retry_scan)?;
            // P0 and Z26 are caller-saved scratch for resource-row lookup, so
            // reconstruct both after every exact rejection.
            assembler.instruction(aarch64_sve_ptrue_b())?;
            assembler.instruction(aarch64_sve_dup_b_imm(26, 0x0f)?)?;
            assembler.instruction(aarch64_sve_cntb(6)?)?;
            assembler.bind(vector)?;
            assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
            assembler.instruction(aarch64_cmp_x_imm(
                12,
                u16::from(teddy.plan.columns()),
            )?)?;
            assembler.branch_cond(AARCH64_LO, no_match)?;
            // X10 is the exclusive end of valid candidate bases. It is live
            // only until one candidate is chosen and may then be clobbered by
            // the exact verifier.
            assembler.instruction(aarch64_sub_x_imm(
                10,
                3,
                u16::from(maximum_offset),
            )?)?;
            assembler.instruction(aarch64_sub_x_reg(12, 10, 2)?)?;
            assembler.instruction(aarch64_cmp_x(12, 6)?)?;
            assembler.branch_cond(AARCH64_LO, partial)?;
            aarch64_emit_mandatory_teddy_sve_candidates(assembler, teddy)?;
            assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
            assembler.branch_cond(AARCH64_NE, vector_hit)?;
            assembler.instruction(aarch64_sve_addvl(2, 2, 1)?)?;
            assembler.branch(vector)?;

            assembler.bind(partial)?;
            assembler.instruction(aarch64_sve_whilelo_b(0, 2, 10)?)?;
            aarch64_emit_mandatory_teddy_sve_candidates(assembler, teddy)?;
            assembler.instruction(aarch64_sve_ptest_p0(1)?)?;
            assembler.branch_cond(AARCH64_EQ, no_match)?;

            assembler.bind(vector_hit)?;
            aarch64_emit_sve_first_candidate(assembler, 1, apply)?;

            // Keep otherwise shared labels bound for control-flow auditing.
            assembler.bind(scalar)?;
            assembler.branch(no_match)?;
        }
        MandatoryTeddyIsa::X86Avx2 | MandatoryTeddyIsa::X86Avx512Bw => {
            return Err(ObjectError::InvalidModule(
                "x86 mandatory Teddy reached AArch64 lowering",
            ));
        }
    }

    assembler.bind(apply)?;
    let retry = suffix.retry.ok_or(ObjectError::InvalidModule(
        "AArch64 mandatory Teddy has no exact retry verifier",
    ))?;
    module_suffix_retry::aarch64_emit_bounded_suffix_retry(
        assembler,
        layout,
        retry,
        features,
        operating_system,
        retry_scan,
        no_match,
        matched,
    )?;
    Ok(())
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_arguments,
    clippy::too_many_lines,
    reason = "aligned vector batches, lazy intersections and scalar tails form one suffix proof"
)]
fn aarch64_emit_suffix_prepass(
    assembler: &mut Aarch64Assembler,
    suffix: NativeSuffixFilter,
    sve_kind: Option<Aarch64SveFilterKind>,
    use_asimd: bool,
    use_asimd_batch: bool,
    use_exact_asimd_lane: bool,
    features: FeatureSet,
    operating_system: OperatingSystem,
    layout: NativeDfaLayout,
    no_match: Aarch64Label,
    matched: Aarch64Label,
) -> Result<(), ObjectError> {
    if let Some(teddy) = layout.mandatory_teddy {
        return aarch64_emit_mandatory_teddy_suffix_prepass(
            assembler,
            suffix,
            teddy,
            features,
            operating_system,
            layout,
            no_match,
            matched,
        );
    }
    let use_sve = sve_kind.is_some();
    let use_runtime_vl_dispatch = use_sve && use_asimd;
    if let Some(reverse) = layout.seeded_reverse {
        return module_seeded_reverse_aarch64::aarch64_emit_seeded_reverse_prepass(
            assembler,
            suffix,
            reverse,
            use_asimd,
            use_asimd_batch,
            use_exact_asimd_lane,
            layout,
            no_match,
            matched,
        );
    }
    let vector = assembler.label()?;
    let single_vector = assembler.label()?;
    let scalar = assembler.label()?;
    let scalar_columns = assembler.label()?;
    let scalar_reject = assembler.label()?;
    let batch_primary_hit = assembler.label()?;
    let single_primary_hit = assembler.label()?;
    let batch_hit = assembler.label()?;
    let single_hit = assembler.label()?;
    let apply = assembler.label()?;
    let done = assembler.label()?;
    let sve_vector = if use_sve {
        Some(assembler.label()?)
    } else {
        None
    };
    let mixed_asimd_setup = if use_runtime_vl_dispatch {
        Some(assembler.label()?)
    } else {
        None
    };
    let mixed_sve_setup = if use_runtime_vl_dispatch {
        Some(assembler.label()?)
    } else {
        None
    };
    let mixed_retry = if use_runtime_vl_dispatch {
        Some(assembler.label()?)
    } else {
        None
    };
    let retry_scan = mixed_retry.unwrap_or_else(|| sve_vector.unwrap_or(vector));
    let filter = suffix.filter;
    let scalar_filter = suffix.vector_filter.or(suffix.scalar_filter);
    let maximum_scan_offset =
        scalar_filter.map_or(filter.scan_offset, NativeVectorFilter::max_scan_offset);
    if suffix.minimum_width == 0 {
        return Err(ObjectError::InvalidModule(
            "AArch64 suffix filter has zero minimum width",
        ));
    }
    let mut batch_first_candidates = None;
    let emit_constants = |assembler: &mut Aarch64Assembler| -> Result<(), ObjectError> {
        if use_asimd {
            if let Some(vector_filter) = suffix.vector_filter {
                let mut first_register = AARCH64_VECTOR_FILTER_FIRST_CONSTANT;
                for &column in vector_filter.columns() {
                    aarch64_emit_start_filter_constants(assembler, column, first_register)?;
                    first_register = first_register
                        .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                            ObjectError::ArithmeticOverflow("AArch64 suffix-filter constants")
                        })?)
                        .ok_or(ObjectError::ArithmeticOverflow(
                            "AArch64 suffix-filter constants",
                        ))?;
                }
            } else {
                let first_register = AARCH64_STANDALONE_FILTER_FIRST_CONSTANT;
                aarch64_emit_start_filter_constants(assembler, filter, first_register)?;
            }
        }
        Ok(())
    };
    if !ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS && !use_runtime_vl_dispatch {
        emit_constants(assembler)?;
    }
    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
    assembler.instruction(aarch64_cmp_x_imm(12, SUFFIX_PREFILTER_MIN_WINDOW_BYTES)?)?;
    assembler.branch_cond(AARCH64_LO, done)?;
    if ENABLE_DEFERRED_SUFFIX_FILTER_CONSTANTS && !use_runtime_vl_dispatch {
        emit_constants(assembler)?;
    }

    if use_runtime_vl_dispatch {
        // X16 is caller-saved, untouched by the suffix scalar verifier and
        // bounded retry, and live only until this prepass returns. Retaining
        // CNTB here lets every retry choose the same ISA without repeating a
        // candidate scan or rematerializing either aliased V/Z constant bank.
        assembler.instruction(aarch64_sve_cntb(16)?)?;
        assembler.instruction(aarch64_cmp_x_imm(16, 16)?)?;
        assembler.branch_cond(
            AARCH64_LS,
            mixed_asimd_setup.ok_or(ObjectError::InvalidModule(
                "mixed suffix ASIMD setup is absent",
            ))?,
        )?;
        if mixed_sve_setup.is_none() {
            return Err(ObjectError::InvalidModule(
                "mixed suffix SVE setup is absent",
            ));
        }
    }

    if let Some(sve_vector) = sve_vector {
        let sve_candidate = assembler.label()?;
        let sve_reject = assembler.label()?;
        let sve_kind = sve_kind.ok_or(ObjectError::InvalidModule(
            "AArch64 SVE suffix scanner has no filter kind",
        ))?;
        if let Some(mixed_sve_setup) = mixed_sve_setup {
            assembler.bind(mixed_sve_setup)?;
        }
        // Each runtime route materializes only its own constants. The scalar
        // verifier cannot clobber Z16..Z23, so retry edges skip this setup.
        aarch64_emit_sve_filter_setup(assembler, filter, sve_kind, 0)?;
        if use_runtime_vl_dispatch {
            assembler.instruction(aarch64_mov_x(6, 16)?)?;
        }
        aarch64_emit_sve_start_filter_scanner(
            assembler,
            filter,
            maximum_scan_offset,
            sve_kind,
            false,
            use_runtime_vl_dispatch,
            sve_vector,
            scalar,
            sve_candidate,
        )?;
        assembler.bind(sve_candidate)?;
        if let Some(vector_filter) = scalar_filter {
            for &column in &vector_filter.columns()[1..] {
                aarch64_emit_scalar_filter_membership(assembler, column, sve_reject)?;
            }
        }
        assembler.branch(apply)?;
        assembler.bind(sve_reject)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
        assembler.branch(retry_scan)?;
    }

    if use_asimd {
        if let Some(mixed_asimd_setup) = mixed_asimd_setup {
            assembler.bind(mixed_asimd_setup)?;
            emit_constants(assembler)?;
        }
        assembler.bind(vector)?;
        assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
        if use_asimd_batch {
            let batch_bytes = u16::from(maximum_scan_offset)
                .checked_add(AARCH64_BATCH_BYTES)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 suffix-filter width",
                ))?;
            assembler.instruction(aarch64_cmp_x_imm(12, batch_bytes)?)?;
            assembler.branch_cond(AARCH64_LO, single_vector)?;
            let first_register = if suffix.vector_filter.is_some() {
                AARCH64_VECTOR_FILTER_FIRST_CONSTANT
            } else {
                AARCH64_STANDALONE_FILTER_FIRST_CONSTANT
            };
            let first_candidates =
                aarch64_emit_start_filter_batch_candidates(assembler, filter, first_register)?;
            batch_first_candidates = Some(first_candidates);
            aarch64_emit_candidate_batch_any(assembler, first_candidates)?;
            assembler.branch_cond(
                AARCH64_NE,
                if suffix.vector_filter.is_some() {
                    batch_primary_hit
                } else if use_exact_asimd_lane {
                    batch_hit
                } else {
                    scalar
                },
            )?;
            assembler.instruction(aarch64_add_x_imm(2, 2, AARCH64_BATCH_BYTES)?)?;
            assembler.branch(vector)?;
        }

        assembler.bind(single_vector)?;
        let vector_bytes = u16::from(maximum_scan_offset).checked_add(16).ok_or(
            ObjectError::ArithmeticOverflow("AArch64 suffix-filter width"),
        )?;
        assembler.instruction(aarch64_cmp_x_imm(12, vector_bytes)?)?;
        assembler.branch_cond(AARCH64_LO, scalar)?;
        aarch64_emit_start_filter_address(assembler, filter.scan_offset)?;
        assembler.instruction(aarch64_load_q(0, 12)?)?;
        if suffix.vector_filter.is_some() {
            aarch64_emit_start_filter_vector_candidates(
                assembler,
                filter,
                0,
                24,
                AARCH64_VECTOR_FILTER_FIRST_CONSTANT,
            )?;
            aarch64_emit_candidate_any(assembler, 24)?;
            assembler.branch_cond(AARCH64_NE, single_primary_hit)?;
        } else {
            let first_register = AARCH64_STANDALONE_FILTER_FIRST_CONSTANT;
            aarch64_emit_start_filter_vector_candidates(assembler, filter, 0, 24, first_register)?;
            aarch64_emit_candidate_any(assembler, 24)?;
            assembler.branch_cond(
                AARCH64_NE,
                if use_exact_asimd_lane {
                    single_hit
                } else {
                    scalar
                },
            )?;
        }
        assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
        assembler.branch(vector)?;

        if let Some(vector_filter) = suffix.vector_filter {
            assembler.bind(batch_primary_hit)?;
            if use_asimd_batch {
                aarch64_emit_vector_filter_secondary_batch(assembler, vector_filter)?;
                aarch64_emit_candidate_batch_any(assembler, 24)?;
                assembler.branch_cond(
                    AARCH64_NE,
                    if use_exact_asimd_lane {
                        batch_hit
                    } else {
                        scalar
                    },
                )?;
                assembler.instruction(aarch64_add_x_imm(2, 2, AARCH64_BATCH_BYTES)?)?;
                assembler.branch(vector)?;
            } else {
                assembler.branch(scalar)?;
            }

            assembler.bind(single_primary_hit)?;
            aarch64_emit_vector_filter_secondary_candidates_at(assembler, vector_filter, 0, 24)?;
            aarch64_emit_candidate_any(assembler, 24)?;
            assembler.branch_cond(
                AARCH64_NE,
                if use_exact_asimd_lane {
                    single_hit
                } else {
                    scalar
                },
            )?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
            assembler.branch(vector)?;
        } else {
            assembler.bind(batch_primary_hit)?;
            assembler.branch(scalar)?;
            assembler.bind(single_primary_hit)?;
            assembler.branch(scalar)?;
        }

        let selected = if suffix.vector_filter.is_some() || suffix.scalar_filter.is_none() {
            apply
        } else {
            scalar_columns
        };
        assembler.bind(batch_hit)?;
        if use_exact_asimd_lane && let Some(first_candidates) = batch_first_candidates {
            aarch64_emit_first_candidate_in_batch(assembler, first_candidates)?;
            assembler.branch(selected)?;
        } else {
            assembler.branch(scalar)?;
        }
        assembler.bind(single_hit)?;
        if use_exact_asimd_lane {
            aarch64_emit_first_candidate_lane(assembler, 24)?;
            assembler.branch(selected)?;
        } else {
            assembler.branch(scalar)?;
        }
    } else {
        // Keep the labels complete even when the target deliberately omits
        // ASIMD and uses the scalar acceptance-boundary scan.
        assembler.bind(vector)?;
        assembler.branch(scalar)?;
        assembler.bind(single_vector)?;
        assembler.branch(scalar)?;
        assembler.bind(batch_primary_hit)?;
        assembler.branch(scalar)?;
        assembler.bind(single_primary_hit)?;
        assembler.branch(scalar)?;
        assembler.bind(batch_hit)?;
        assembler.branch(scalar)?;
        assembler.bind(single_hit)?;
        assembler.branch(scalar)?;
    }

    if let Some(mixed_retry) = mixed_retry {
        assembler.bind(mixed_retry)?;
        assembler.instruction(aarch64_cmp_x_imm(16, 16)?)?;
        assembler.branch_cond(AARCH64_LS, vector)?;
        // Bounded DFA verification uses W6 for row tokens. Restore the
        // retained VL before re-entering the scalable scanner.
        assembler.instruction(aarch64_mov_x(6, 16)?)?;
        assembler.branch(sve_vector.ok_or(ObjectError::InvalidModule(
            "mixed suffix retry has no SVE scanner",
        ))?)?;
    }

    assembler.bind(scalar)?;
    aarch64_emit_start_filter_scalar_bound(assembler, maximum_scan_offset, no_match)?;
    aarch64_emit_start_filter_scalar_load(assembler, filter.scan_offset)?;
    let scalar_candidate = if scalar_filter.is_some() {
        scalar_columns
    } else {
        apply
    };
    for range in filter.ranges() {
        assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.start))?)?;
        if range.start == range.end {
            assembler.branch_cond(AARCH64_EQ, scalar_candidate)?;
        } else {
            let next_range = assembler.label()?;
            assembler.branch_cond(AARCH64_LO, next_range)?;
            assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.end))?)?;
            assembler.branch_cond(AARCH64_LS, scalar_candidate)?;
            assembler.bind(next_range)?;
        }
    }
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    assembler.branch(scalar)?;

    if let Some(vector_filter) = scalar_filter {
        assembler.bind(scalar_columns)?;
        for &column in &vector_filter.columns()[1..] {
            aarch64_emit_scalar_filter_membership(assembler, column, scalar_reject)?;
        }
        assembler.branch(apply)?;
        assembler.bind(scalar_reject)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
        assembler.branch(retry_scan)?;
    } else {
        assembler.bind(scalar_columns)?;
        assembler.branch(apply)?;
        assembler.bind(scalar_reject)?;
        assembler.branch(scalar)?;
    }

    assembler.bind(apply)?;
    if let Some(retry) = suffix.retry {
        module_suffix_retry::aarch64_emit_bounded_suffix_retry(
            assembler,
            layout,
            retry,
            features,
            operating_system,
            retry_scan,
            no_match,
            matched,
        )?;
    } else {
        aarch64_emit_suffix_restart(assembler, suffix.restart)?;
    }
    assembler.bind(done)?;
    Ok(())
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
#[cfg(test)]
fn lower_aarch64_dfa(
    layout: NativeDfaLayout,
    features: FeatureSet,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    lower_aarch64_dfa_for_operating_system(layout, features, OperatingSystem::Linux, None)
}

const fn aarch64_use_exact_first_lane(_operating_system: OperatingSystem) -> bool {
    true
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
#[cfg(test)]
fn lower_aarch64_dfa_for_operating_system(
    layout: NativeDfaLayout,
    features: FeatureSet,
    operating_system: OperatingSystem,
    sve_filter_plan: Option<Aarch64SveFilterPlan>,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let emission = lower_aarch64_dfa_for_operating_system_with_emission(
        layout,
        features,
        operating_system,
        sve_filter_plan,
    )?;
    Ok((emission.code, emission.relocations))
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
#[cfg(test)]
fn lower_aarch64_dfa_for_operating_system_with_emission(
    layout: NativeDfaLayout,
    features: FeatureSet,
    operating_system: OperatingSystem,
    sve_filter_plan: Option<Aarch64SveFilterPlan>,
) -> Result<NativeDfaEmission, ObjectError> {
    let sve_suffix_kind =
        selected_aarch64_sve_suffix_kind(layout, features, operating_system);
    lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
        layout,
        features,
        operating_system,
        sve_filter_plan,
        sve_suffix_kind,
        NativeDfaEntryContract::Public,
    )
}

#[allow(
    clippy::large_types_passed_by_value,
    clippy::too_many_lines,
    reason = "the specialized forward/reverse control-flow graph is kept contiguous for auditing"
)]
fn lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
    layout: NativeDfaLayout,
    features: FeatureSet,
    operating_system: OperatingSystem,
    sve_filter_plan: Option<Aarch64SveFilterPlan>,
    sve_suffix_kind: Option<Aarch64SveFilterKind>,
    entry_contract: NativeDfaEntryContract,
) -> Result<NativeDfaEmission, ObjectError> {
    if !native_default_exception_layout_is_valid(&layout) {
        return Err(ObjectError::InvalidModule(
            "AArch64 default-exception layout shape",
        ));
    }
    if layout.start_filter.is_some() && layout.exact_start_byte_set.is_some()
        || layout.exact_start_byte_set.is_some() != layout.exact_start_storage.is_some()
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 primary scanner layout is inconsistent",
        ));
    }
    if !layout.pending_preserving_scanner_shape_is_valid() {
        return Err(ObjectError::InvalidModule(
            "AArch64 pending-preserving scanner layout is inconsistent",
        ));
    }
    if entry_contract.fixed_candidate() && layout.mandatory_teddy.is_some() {
        return Err(ObjectError::InvalidModule(
            "AArch64 fixed candidate retained a moving Teddy scanner",
        ));
    }
    let mut assembler = Aarch64Assembler::new();
    let register_outcome = entry_contract.register_outcome();
    let fixed_candidate = entry_contract.fixed_candidate();
    let scan = assembler.label()?;
    let scalar_scan = assembler.label()?;
    let scalar_transition = assembler.label()?;
    let scalar_body = assembler.label()?;
    let scalar_backedge = assembler.label()?;
    let accelerated_transition = assembler.label()?;
    let partial_resume = assembler.label()?;
    let forward_exception = assembler.label()?;
    let prefix_check = assembler.label()?;
    let prefix_vector_check = assembler.label()?;
    let prefix_verified = assembler.label()?;
    let prefix_apply = assembler.label()?;
    let prefix_fail = assembler.label()?;
    let prefix_retained_fail = assembler.label()?;
    let prefix_terminal = assembler.label()?;
    let filter_sve = assembler.label()?;
    let filter_sve_candidate = assembler.label()?;
    let filter_sve_reject = assembler.label()?;
    let filter_vector = assembler.label()?;
    let filter_single_vector = assembler.label()?;
    let filter_batch_primary_hit = assembler.label()?;
    let filter_single_primary_hit = assembler.label()?;
    let filter_batch_hit = assembler.label()?;
    let filter_single_hit = assembler.label()?;
    let filter_retained_exhausted = assembler.label()?;
    let filter_scalar = assembler.label()?;
    let filter_scalar_columns = assembler.label()?;
    let filter_scalar_reject = assembler.label()?;
    let accept = assembler.label()?;
    let finish = assembler.label()?;
    let no_match = assembler.label()?;
    let matched = assembler.label()?;
    let selected_end = assembler.label()?;
    let invalid = assembler.label()?;
    let done = assembler.label()?;
    let reverse_scan = assembler.label()?;
    let reverse_exception = assembler.label()?;
    let record_reverse_start = assembler.label()?;
    let reverse_continue = assembler.label()?;
    let reverse_finish = assembler.label()?;
    let exact_start_probe_failed = assembler.label()?;

    if entry_contract.validates_public_args() {
        assembler.instruction(0xf100_003f)?; // cmp length, #0
        assembler.branch_cond(AARCH64_MI, invalid)?;
        assembler.instruction(aarch64_cmp_x(3, 1)?)?;
        assembler.branch_cond(AARCH64_HI, invalid)?;
        assembler.instruction(aarch64_cmp_x(2, 3)?)?;
        assembler.branch_cond(AARCH64_HI, invalid)?;
        assembler.instruction(0xf100_009f)?; // cmp x4, #0
        assembler.branch_cond(AARCH64_EQ, invalid)?;
        assembler.instruction(aarch64_and_low_x(5, 4, 3)?)?;
        assembler.instruction(0xf100_00bf)?; // cmp alignment scratch, #0
        assembler.branch_cond(AARCH64_NE, invalid)?;
        assembler.instruction(0xf100_001f)?; // cmp x0, #0
        assembler.branch_cond(AARCH64_EQ, invalid)?;
    }
    if entry_contract.validates_public_args() {
        assembler.instruction(aarch64_store_x(31, 4, 0)?)?;
        assembler.instruction(aarch64_store_x(31, 4, 8)?)?;
    }
    if let Some((bounds, width)) = entry_contract.exact_absolute_anchored() {
        aarch64_emit_exact_absolute_anchored_bounds(&mut assembler, bounds, width, no_match)?;
    }
    assembler.instruction(aarch64_mov_x(9, 2)?)?;

    let table_page = assembler.instruction(0x9000_0005)?;
    let table_page_offset = assembler.instruction(aarch64_add_x_imm(5, 5, 0)?)?;
    let primary_scanner_isa =
        aarch64_primary_scanner_isa(operating_system, features, true);
    let use_sve_filter = sve_filter_plan.is_some()
        && layout
            .start_filter
            .is_some_and(|filter| !filter.ranges().is_empty());
    let use_runtime_vl_dispatch = use_sve_filter
        && aarch64_primary_scanner_uses_runtime_vl_dispatch(primary_scanner_isa);
    let use_asimd_filter = (!use_sve_filter || use_runtime_vl_dispatch)
        && features.has(CpuFeature::Aarch64Asimd)
        && layout
            .start_filter
            .is_some_and(|filter| !filter.ranges().is_empty());
    let exact_sve_kind = layout
        .exact_start_storage
        .filter(|_| layout.exact_start_byte_set.is_some())
        .and_then(|storage| {
            selected_aarch64_exact_sve_kind(operating_system, features, storage)
        });
    let exact_use_runtime_vl_dispatch = exact_sve_kind.is_some()
        && aarch64_primary_scanner_uses_runtime_vl_dispatch(primary_scanner_isa);
    let use_exact_asimd = features.has(CpuFeature::Aarch64Asimd)
        && layout.exact_start_byte_set.is_some()
        && (exact_sve_kind.is_none() || exact_use_runtime_vl_dispatch);
    let mut scanner_emission = None;
    if sve_suffix_kind.is_some()
        && selected_aarch64_sve_suffix_kind(layout, features, operating_system).is_none()
    {
        return Err(ObjectError::InvalidModule(
            "installed AArch64 SVE suffix plan is unsupported",
        ));
    }
    let use_asimd_suffix = features.has(CpuFeature::Aarch64Asimd)
        && layout
            .suffix_filter
            .is_some_and(|suffix| !suffix.filter.ranges().is_empty())
        && layout.mandatory_teddy.is_none_or(|teddy| {
            teddy.isa == MandatoryTeddyIsa::Aarch64Asimd
        });
    let use_asimd_suffix_batch = use_asimd_suffix
        && layout
            .suffix_filter
            .is_some_and(|suffix| use_aarch64_filter_batch(suffix.filter));
    let sve_loop_kind = selected_aarch64_sve_loop_kind(&layout, features, operating_system);
    let loop_use_runtime_vl_dispatch = sve_loop_kind.is_some()
        && features.has(CpuFeature::Aarch64Asimd)
        && layout
            .loop_skip
            .is_some_and(module_dfa_loop_skip::aarch64_uses_asimd_batch);
    let use_asimd_loop = (sve_loop_kind.is_none() || loop_use_runtime_vl_dispatch)
        && features.has(CpuFeature::Aarch64Asimd)
        && layout.loop_skip.is_some();
    let secondary_sve_loop_kind = layout.loop_skip_secondary.and_then(|plan| {
        selected_aarch64_sve_loop_kind_for_plan(plan, features, operating_system)
    });
    let secondary_loop_use_runtime_vl_dispatch = secondary_sve_loop_kind.is_some()
        && features.has(CpuFeature::Aarch64Asimd)
        && layout
            .loop_skip_secondary
            .is_some_and(module_dfa_loop_skip::aarch64_uses_asimd_batch);
    let use_asimd_secondary_loop = (secondary_sve_loop_kind.is_none()
        || secondary_loop_use_runtime_vl_dispatch)
        && features.has(CpuFeature::Aarch64Asimd)
        && layout.loop_skip_secondary.is_some();
    let sparse_lookup_isa = if layout.transitions.uses_vector_sparse_lookup() {
        aarch64_primary_scanner_isa(operating_system, features, true)
    } else {
        Aarch64PrimaryScannerIsa::Scalar
    };
    let sparse_boundary_tier =
        aarch64_sparse_boundary_tier(&layout, features, operating_system);
    let sparse_sve_fused_boundary =
        aarch64_sparse_sve_fused_boundary(&layout, features, operating_system);
    let scalar_body_preloaded = (layout.loop_skip_secondary.is_some()
        && aarch64_table_lookup_has_common_raw_load(layout.transitions, sparse_boundary_tier))
    .then(|| assembler.label())
    .transpose()?;
    let use_asimd_sparse_lookup = matches!(
        sparse_lookup_isa,
        Aarch64PrimaryScannerIsa::Asimd | Aarch64PrimaryScannerIsa::SveWithAsimdVl16
    );
    let sparse_use_runtime_vl_dispatch =
        aarch64_primary_scanner_uses_runtime_vl_dispatch(sparse_lookup_isa);
    let pure_sve_filter = use_sve_filter && !features.has(CpuFeature::Aarch64Asimd);
    let prefix_relation_vector = layout
        .prefix_relation
        .and_then(|relation| relation.vector_plan)
        // The exact relation vector has an ASIMD lowering but no SVE
        // lowering. In the pure-SVE tier its mere layout presence must not
        // suppress the graph-derived Cartesian columns: those columns remain
        // a necessary filter, and the unchanged scalar pair bitmap verifies
        // every selected candidate exactly.
        .filter(|_| !pure_sve_filter);
    // Exact lane extraction wins on Apple Silicon, while generic Linux
    // AArch64 retains SIMD block rejection and refines a hit scalarly. This
    // target cost policy applies to every graph-derived filter uniformly.
    let use_exact_asimd_lane = aarch64_use_exact_first_lane(operating_system);
    let vector_filter = if prefix_relation_vector.is_some() {
        None
    } else {
        layout.vector_filter
    };
    if let Some(plan) = sve_filter_plan {
        let primary = layout.start_filter.ok_or(ObjectError::InvalidModule(
            "direct SVE filter plan has no graph primary",
        ))?;
        plan.validate_for(primary, vector_filter)?;
    }
    let vector_coverage = use_asimd_filter
        .then(|| {
            derive_native_vector_guard_coverage(
                layout,
                prefix_relation_vector.is_some(),
                vector_filter,
            )
        })
        .flatten();
    let retain_vector_candidates = vector_coverage
        .map(|coverage| coverage.has_rejectable_residual(layout))
        .transpose()?
        .unwrap_or(false);
    // A 64-byte reduction pays when the graph-derived initial candidate set
    // is sparse. Ordinary residual guards retain the exact 16-lane mask so a
    // rejected candidate can continue inside that block. A complete exact
    // product has a stronger retry proof. Its multicolumn route intersects
    // every graph-selected SIMD column before choosing the first lane; the
    // ordinary prefix guard then validates any remaining scalar columns and
    // either returns the match or resumes this scanner at `candidate + 1`.
    // The primary-only route retains its small scalar-retry ceiling.
    // Correlated relation filters keep their established all-or-nothing batch
    // gate because the exact-product proof does not cover their language.
    let use_asimd_exact_product_multicolumn_batch = use_asimd_filter
        && retain_vector_candidates
        && layout.exact_prefix_match_width.is_some()
        && prefix_relation_vector.is_none()
        && vector_filter.is_some()
        && layout.start_filter.is_some_and(use_aarch64_filter_batch);
    let use_asimd_exact_product_scalar_residual_batch = use_asimd_filter
        && retain_vector_candidates
        && layout.exact_prefix_match_width.is_some()
        && prefix_relation_vector.is_none()
        && vector_filter.is_none()
        && layout.prefix_filter.is_some_and(|prefix| {
            prefix.predicates().len()
                <= MAX_ASIMD_EXACT_PRODUCT_SCALAR_RESIDUAL_BATCH_PREDICATES
        })
        && layout.start_filter.is_some_and(use_aarch64_filter_batch);
    let use_asimd_exact_product_residual_batch =
        use_asimd_exact_product_multicolumn_batch
            || use_asimd_exact_product_scalar_residual_batch;
    let use_asimd_relation_batch = use_asimd_filter
        && !retain_vector_candidates
        && prefix_relation_vector.is_some()
        && vector_coverage.is_some()
        && layout.start_filter.is_some_and(use_aarch64_filter_batch);
    let use_asimd_batch = use_asimd_filter
        && (!retain_vector_candidates || use_asimd_exact_product_residual_batch)
        && (prefix_relation_vector.is_none() || use_asimd_relation_batch)
        && layout.start_filter.is_some_and(use_aarch64_filter_batch);
    let use_asimd_multicolumn_batch = use_asimd_batch && vector_filter.is_some();
    let filter_single_vector_loop = use_asimd_exact_product_residual_batch
        .then(|| assembler.label())
        .transpose()?;
    if use_asimd_sparse_lookup
        || !fixed_candidate
            && use_exact_asimd_lane
            && (use_asimd_filter
                || use_exact_asimd
                || use_asimd_suffix
                || use_asimd_loop
                || use_asimd_secondary_loop)
    {
        let lane_index_offset =
            layout
                .asimd_lane_index_offset
                .ok_or(ObjectError::InvalidModule(
                    "ASIMD candidate lowering has no lane-index table",
                ))?;
        aarch64_emit_first_lane_constants(&mut assembler, lane_index_offset)?;
    }
    let candidate = if layout.has_prefix_guard() {
        prefix_check
    } else if layout.prefix_fast_forward.is_some() {
        prefix_apply
    } else {
        scalar_scan
    };
    let use_prefix_block = features.has(CpuFeature::Aarch64Asimd) && layout.prefix_block.is_some();
    let probe_exact_product = layout.exact_prefix_match_width.is_some()
        && (fixed_candidate
            || layout.suffix_filter.is_some()
            || use_asimd_exact_product_residual_batch);
    if probe_exact_product {
        // A sparse four-vector scanner wins on long misses but should not pay
        // four loads and a horizontal reduction for a match at the original
        // window start. The same complete-product guard used ahead of a
        // suffix prepass proves that start once on large windows. A moving
        // entry retries from its untouched X2; a fixed entry has no second
        // candidate and rejects immediately.
        let probe_failed = exact_start_probe_failure_target(
            fixed_candidate,
            exact_start_probe_failed,
            no_match,
        );
        aarch64_emit_exact_start_probe(
            &mut assembler,
            layout,
            use_prefix_block,
            !fixed_candidate,
            register_outcome,
            probe_failed,
            matched,
        )?;
        if !fixed_candidate {
            assembler.bind(exact_start_probe_failed)?;
        }
    }
    if !fixed_candidate && let Some(suffix) = layout.suffix_filter {
        aarch64_emit_suffix_prepass(
            &mut assembler,
            suffix,
            sve_suffix_kind,
            use_asimd_suffix,
            use_asimd_suffix_batch,
            use_exact_asimd_lane,
            features,
            operating_system,
            layout,
            no_match,
            matched,
        )?;
    }
    aarch64_set_row_base(&mut assembler, layout.forward_offset)?;
    if layout.output != OutputContract::Exists {
        assembler.instruction(0x9280_000d)?; // movn x13, #0
        assembler.instruction(aarch64_mov_x(7, 13)?)?;
    }
    if !fixed_candidate && use_asimd_filter {
        let filter = layout.start_filter.ok_or(ObjectError::InvalidModule(
            "ASIMD start filter has no graph filter",
        ))?;
        if let Some(plan) = prefix_relation_vector {
            aarch64_emit_prefix_relation_constants(&mut assembler, plan)?;
        } else if let Some(vector_filter) = vector_filter {
            let mut first_register = AARCH64_VECTOR_FILTER_FIRST_CONSTANT;
            for &column in vector_filter.columns() {
                aarch64_emit_start_filter_constants(&mut assembler, column, first_register)?;
                first_register = first_register
                    .checked_add(u8::try_from(column.constant_count()).map_err(|_| {
                        ObjectError::ArithmeticOverflow("AArch64 vector-filter constants")
                    })?)
                    .ok_or(ObjectError::ArithmeticOverflow(
                        "AArch64 vector-filter constants",
                    ))?;
            }
        } else {
            let first_register = AARCH64_STANDALONE_FILTER_FIRST_CONSTANT;
            aarch64_emit_start_filter_constants(&mut assembler, filter, first_register)?;
        }
    } else if !fixed_candidate && let Some(kind) = exact_sve_kind {
        let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
            "AArch64 SVE exact scanner has no canonical storage",
        ))?;
        aarch64_emit_exact_sve_constants(&mut assembler, storage, kind)?;
    } else if !fixed_candidate && use_exact_asimd {
        let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
            "AArch64 ASIMD exact scanner has no canonical storage",
        ))?;
        aarch64_emit_exact_asimd_constants(&mut assembler, storage)?;
    }
    let mut filter_batch_first_candidates = None;

    if layout.initial_pending {
        if layout.output == OutputContract::Exists {
            assembler.branch(matched)?;
        } else {
            assembler.instruction(aarch64_mov_x(7, 2)?)?;
            if layout.initial_terminal {
                assembler.branch(finish)?;
            }
        }
    }

    let retain_sve_filter_setup = pure_sve_filter;
    if !fixed_candidate && retain_sve_filter_setup {
        let filter = layout.start_filter.ok_or(ObjectError::InvalidModule(
            "pure-SVE start filter has no graph filter",
        ))?;
        let sve_filter_plan = sve_filter_plan.ok_or(ObjectError::InvalidModule(
            "pure-SVE start filter has no lowering plan",
        ))?;
        // No ASIMD instruction is emitted in this capability tier. Candidate
        // validation is scalar, so the caller-saved Z16..Z23 constant bank is
        // immutable until return and need not be rebuilt on each retry.
        aarch64_emit_sve_filter_setups(&mut assembler, filter, vector_filter, sve_filter_plan)?;
    }

    if sparse_use_runtime_vl_dispatch
        || loop_use_runtime_vl_dispatch
        || secondary_loop_use_runtime_vl_dispatch
        || !fixed_candidate && (use_runtime_vl_dispatch || exact_use_runtime_vl_dispatch)
    {
        // The suffix prepass cannot provide this value: its short-window
        // bypass reaches the root without executing its optional CNTB, and
        // the seeded-reverse prepass also owns X16. Sample only after every
        // prepass and initial-pending early exit. Sparse rows, including a
        // fixed-candidate entry, and profitable interior loop dispatches use
        // the same retained mode. Since `scan` is bound after these
        // instructions, every DFA transition and root retry preserves both
        // caller-saved registers instead of querying VL again.
        assembler.instruction(aarch64_sve_cntb(AARCH64_MIXED_ROOT_VL_REGISTER)?)?;
        assembler.instruction(aarch64_sub_x_imm(
            AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER,
            AARCH64_MIXED_ROOT_VL_REGISTER,
            AARCH64_SVE_MIN_VECTOR_BYTES,
        )?)?;
    }
    if let NativeCellEncoding::Compact16Ordinal(row_bytes) = layout.cells {
        // X15 is caller-saved and otherwise unused by the ordinary DFA
        // lowering. Retain the authenticated stride across scanner retries so
        // every scalar transition forms its next row with one MADD.
        assembler.instruction(aarch64_movz_x(15, row_bytes, 0)?)?;
    }

    if fixed_candidate {
        // The public proof admitted one start and X2/X3 now delimit exactly
        // its width. Avoid every moving SIMD/scalar root scanner and consume
        // that candidate through the ordinary ordered DFA directly.
        assembler.branch(scalar_transition)?;
    }

    assembler.bind(scan)?;
    if let Some(filter) = layout.start_filter {
        if layout.output != OutputContract::Exists && !layout.start_scanner_preserves_pending {
            assembler.instruction(aarch64_cmp_x(7, 13)?)?;
            assembler.branch_cond(AARCH64_NE, scalar_scan)?;
        }
        aarch64_set_table_address(&mut assembler, 12, layout.forward_offset)?;
        assembler.instruction(aarch64_cmp_x(11, 12)?)?;
        assembler.branch_cond(AARCH64_NE, scalar_scan)?;

        if filter.ranges().is_empty() {
            scanner_emission = Some(NativeScannerEmission {
                scan_offset: filter.scan_offset,
                membership: start_filter_membership(filter)?,
                isa: NativeScannerIsa::ScalarEmpty,
                vectorized: false,
            });
            assembler.instruction(aarch64_mov_x(2, 3)?)?;
            assembler.branch(finish)?;
        } else {
            scanner_emission = Some(aarch64_range_scanner_emission(
                filter,
                use_sve_filter,
                use_asimd_filter,
                sve_filter_plan,
            )?);
            let maximum_scan_offset = prefix_relation_vector.map_or_else(
                || vector_filter.map_or(filter.scan_offset, NativeVectorFilter::max_scan_offset),
                |_| 1,
            );
            if let Some(sve_filter_plan) = sve_filter_plan.filter(|_| use_sve_filter) {
                if use_runtime_vl_dispatch {
                    // ASIMD's four-vector scanner is the lower-cost VL16
                    // implementation. The process VL is stable, so a retained
                    // zero/nonzero mode makes every root retry one predictable
                    // compare-and-branch. Wider VLs copy the retained byte
                    // count into the SVE scanner's established X6 input.
                    assembler
                        .branch_zero_w(AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER, filter_vector)?;
                    assembler.instruction(aarch64_mov_x(6, AARCH64_MIXED_ROOT_VL_REGISTER)?)?;
                }
                if let Some(vector_filter) = vector_filter {
                    // Intersect the complete graph filter before selecting a
                    // lane. Scalar tails retain the common scalar-column path.
                    aarch64_emit_sve_multicol_start_filter_scanner(
                        &mut assembler,
                        filter,
                        Some(vector_filter),
                        None,
                        maximum_scan_offset,
                        sve_filter_plan,
                        !retain_sve_filter_setup,
                        use_runtime_vl_dispatch,
                        filter_sve,
                        filter_scalar,
                        filter_sve_candidate,
                    )?;
                } else {
                    aarch64_emit_sve_start_filter_scanner(
                        &mut assembler,
                        filter,
                        maximum_scan_offset,
                        sve_filter_plan.primary(),
                        !retain_sve_filter_setup,
                        use_runtime_vl_dispatch,
                        filter_sve,
                        filter_scalar,
                        filter_sve_candidate,
                    )?;
                }
                assembler.bind(filter_sve_candidate)?;
                assembler.branch(candidate)?;
                if vector_filter.is_none() {
                    // Preserve byte-identical single-column artifacts. This
                    // legacy reject block is unreachable without secondaries.
                    assembler.bind(filter_sve_reject)?;
                    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
                    assembler.branch(filter_sve)?;
                }
            }
            if use_asimd_filter {
                assembler.bind(filter_vector)?;
                assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
                if use_asimd_batch {
                    let batch_bytes = u16::from(maximum_scan_offset)
                        .checked_add(AARCH64_BATCH_BYTES)
                        .ok_or(ObjectError::ArithmeticOverflow(
                            "ASIMD batch start-filter width",
                        ))?;
                    assembler.instruction(aarch64_cmp_x_imm(12, batch_bytes)?)?;
                    assembler.branch_cond(AARCH64_LO, filter_single_vector)?;
                    let first_candidates = if let Some(plan) = prefix_relation_vector {
                        if !use_asimd_relation_batch {
                            return Err(ObjectError::InvalidModule(
                                "ASIMD relation batch escaped its proof gate",
                            ));
                        }
                        aarch64_emit_prefix_relation_batch_candidates(&mut assembler, plan)?
                    } else {
                        let first_register = if vector_filter.is_some() {
                            AARCH64_VECTOR_FILTER_FIRST_CONSTANT
                        } else {
                            AARCH64_STANDALONE_FILTER_FIRST_CONSTANT
                        };
                        aarch64_emit_start_filter_batch_candidates(
                            &mut assembler,
                            filter,
                            first_register,
                        )?
                    };
                    filter_batch_first_candidates = Some(first_candidates);
                    aarch64_emit_candidate_batch_any(&mut assembler, first_candidates)?;
                    assembler.branch_cond(
                        AARCH64_NE,
                        if vector_filter.is_some() {
                            filter_batch_primary_hit
                        } else if use_exact_asimd_lane {
                            filter_batch_hit
                        } else {
                            filter_scalar
                        },
                    )?;
                    assembler.instruction(aarch64_add_x_imm(2, 2, AARCH64_BATCH_BYTES)?)?;
                    assembler.branch(filter_vector)?;
                }
                if let Some(filter_single_vector_loop) = filter_single_vector_loop {
                    assembler.bind(filter_single_vector_loop)?;
                    assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
                }
                assembler.bind(filter_single_vector)?;
                let vector_bytes = u16::from(maximum_scan_offset).checked_add(16).ok_or(
                    ObjectError::ArithmeticOverflow("ASIMD start-filter vector width"),
                )?;
                assembler.instruction(aarch64_cmp_x_imm(12, vector_bytes)?)?;
                assembler.branch_cond(AARCH64_LO, filter_scalar)?;
                if let Some(plan) = prefix_relation_vector {
                    aarch64_emit_prefix_relation_vector_test(&mut assembler, plan)?;
                } else {
                    aarch64_emit_start_filter_address(&mut assembler, filter.scan_offset)?;
                    assembler.instruction(aarch64_load_q(0, 12)?)?;
                }
                if prefix_relation_vector.is_some() {
                    // The exact relation helper already reduced V24 and left
                    // condition flags ready for the shared hit branch.
                } else if vector_filter.is_some() {
                    aarch64_emit_start_filter_vector_candidates(
                        &mut assembler,
                        filter,
                        0,
                        24,
                        AARCH64_VECTOR_FILTER_FIRST_CONSTANT,
                    )?;
                    aarch64_emit_candidate_any(&mut assembler, 24)?;
                } else {
                    let first_register = AARCH64_STANDALONE_FILTER_FIRST_CONSTANT;
                    aarch64_emit_start_filter_vector_candidates(
                        &mut assembler,
                        filter,
                        0,
                        24,
                        first_register,
                    )?;
                    aarch64_emit_candidate_any(&mut assembler, 24)?;
                }
                assembler.branch_cond(
                    AARCH64_NE,
                    if vector_filter.is_some() {
                        filter_single_primary_hit
                    } else if use_exact_asimd_lane {
                        filter_single_hit
                    } else {
                        filter_scalar
                    },
                )?;
                assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
                assembler.branch(filter_single_vector_loop.unwrap_or(filter_vector))?;

                if let Some(vector_filter) = vector_filter {
                    if use_asimd_batch {
                        assembler.bind(filter_batch_primary_hit)?;
                        aarch64_emit_vector_filter_secondary_batch(&mut assembler, vector_filter)?;
                        aarch64_emit_candidate_batch_any(&mut assembler, 24)?;
                        assembler.branch_cond(
                            AARCH64_NE,
                            if use_exact_asimd_lane {
                                filter_batch_hit
                            } else {
                                filter_scalar
                            },
                        )?;
                        assembler.instruction(aarch64_add_x_imm(2, 2, AARCH64_BATCH_BYTES)?)?;
                        assembler.branch(filter_vector)?;
                    }

                    assembler.bind(filter_single_primary_hit)?;
                    aarch64_emit_vector_filter_secondary_candidates_at(
                        &mut assembler,
                        vector_filter,
                        0,
                        24,
                    )?;
                    aarch64_emit_candidate_any(&mut assembler, 24)?;
                    assembler.branch_cond(
                        AARCH64_NE,
                        if use_exact_asimd_lane {
                            filter_single_hit
                        } else {
                            filter_scalar
                        },
                    )?;
                    assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
                    assembler.branch(filter_vector)?;
                }

                assembler.bind(filter_batch_hit)?;
                if use_exact_asimd_lane
                    && let Some(first_candidates) = filter_batch_first_candidates
                {
                    aarch64_emit_first_candidate_in_batch(&mut assembler, first_candidates)?;
                    assembler.branch(if use_asimd_exact_product_residual_batch {
                        // The four masks are caller-saved temporaries. The
                        // multicolumn route already intersected every selected
                        // SIMD column; the ordinary exact prefix guard rechecks
                        // them and any scalar residual, and its failure edge
                        // restarts scanning at the next possible start.
                        candidate
                    } else if vector_coverage.is_some() {
                        prefix_vector_check
                    } else {
                        candidate
                    })?;
                } else {
                    assembler.branch(filter_scalar)?;
                }
                assembler.bind(filter_single_hit)?;
                if use_exact_asimd_lane {
                    if retain_vector_candidates {
                        assembler.instruction(aarch64_mov_x(14, 2)?)?;
                        aarch64_emit_first_retained_candidate_lane(&mut assembler, 24, 14)?;
                    } else {
                        aarch64_emit_first_candidate_lane(&mut assembler, 24)?;
                    }
                    assembler.branch(if vector_coverage.is_some() {
                        prefix_vector_check
                    } else {
                        candidate
                    })?;
                } else {
                    assembler.branch(filter_scalar)?;
                }
            }

            assembler.bind(filter_scalar)?;
            aarch64_emit_start_filter_scalar_bound(&mut assembler, maximum_scan_offset, finish)?;
            aarch64_emit_start_filter_scalar_load(&mut assembler, filter.scan_offset)?;
            let scalar_candidate = if vector_filter.is_some() {
                filter_scalar_columns
            } else {
                candidate
            };
            for range in filter.ranges() {
                assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.start))?)?;
                if range.start == range.end {
                    assembler.branch_cond(AARCH64_EQ, scalar_candidate)?;
                } else {
                    let next_range = assembler.label()?;
                    assembler.branch_cond(AARCH64_LO, next_range)?;
                    assembler.instruction(aarch64_cmp_w_imm(8, u16::from(range.end))?)?;
                    assembler.branch_cond(AARCH64_LS, scalar_candidate)?;
                    assembler.bind(next_range)?;
                }
            }
            assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
            assembler.branch(filter_scalar)?;

            if let Some(vector_filter) = vector_filter {
                assembler.bind(filter_scalar_columns)?;
                for &column in &vector_filter.columns()[1..] {
                    aarch64_emit_scalar_filter_membership(
                        &mut assembler,
                        column,
                        filter_scalar_reject,
                    )?;
                }
                assembler.branch(candidate)?;
                assembler.bind(filter_scalar_reject)?;
                assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
                assembler.branch(filter_scalar)?;
            }
        }
    } else if let Some(exact) = layout.exact_start_byte_set {
        let storage = layout.exact_start_storage.ok_or(ObjectError::InvalidModule(
            "AArch64 exact scanner has no canonical storage",
        ))?;
        if !storage.bitmap_offset.is_multiple_of(8)
            || storage.aarch64_lut_offset
                != storage.bitmap_offset.checked_add(32)
            || !exact.is_valid()
        {
            return Err(ObjectError::InvalidModule(
                "AArch64 exact scanner storage is malformed",
            ));
        }
        scanner_emission = Some(NativeScannerEmission {
            scan_offset: exact.scan_offset,
            membership: exact.membership,
            isa: exact_sve_kind.map_or_else(
                || {
                    if use_exact_asimd {
                        NativeScannerIsa::Aarch64Asimd
                    } else {
                        NativeScannerIsa::Aarch64ScalarLut
                    }
                },
                Aarch64ExactSveKind::scanner_isa,
            ),
            vectorized: use_exact_asimd || exact_sve_kind.is_some(),
        });
        if layout.output != OutputContract::Exists && !layout.start_scanner_preserves_pending {
            assembler.instruction(aarch64_cmp_x(7, 13)?)?;
            assembler.branch_cond(AARCH64_NE, scalar_scan)?;
        }
        aarch64_set_table_address(&mut assembler, 12, layout.forward_offset)?;
        assembler.instruction(aarch64_cmp_x(11, 12)?)?;
        assembler.branch_cond(AARCH64_NE, scalar_scan)?;
        let exact_scalar = assembler.label()?;
        let exact_scalar_loop = assembler.label()?;
        if let Some(kind) = exact_sve_kind {
            let exact_vector = assembler.label()?;
            let exact_asimd_vector = exact_use_runtime_vl_dispatch
                .then(|| assembler.label())
                .transpose()?;
            if let Some(exact_asimd_vector) = exact_asimd_vector {
                assembler.branch_zero_w(
                    AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER,
                    exact_asimd_vector,
                )?;
            }
            aarch64_emit_exact_sve_scanner(
                &mut assembler,
                exact,
                kind,
                exact_use_runtime_vl_dispatch
                    .then_some(AARCH64_MIXED_ROOT_VL_REGISTER),
                exact_vector,
                exact_scalar,
                candidate,
            )?;
            if let Some(exact_asimd_vector) = exact_asimd_vector {
                // SVE2 MATCH tables are not the nibble classifier consumed by
                // ASIMD. Reload the canonical fixed-width constants only on
                // the process-wide VL16 arm; a wider process never executes
                // this block and retains the scalable constants above.
                assembler.bind(exact_asimd_vector)?;
                aarch64_emit_exact_asimd_constants(&mut assembler, storage)?;
                let exact_asimd_scan = assembler.label()?;
                aarch64_emit_exact_asimd_scanner(
                    &mut assembler,
                    exact,
                    exact_asimd_scan,
                    exact_scalar,
                    candidate,
                    use_exact_asimd_lane,
                )?;
            }
        } else if use_exact_asimd {
            let exact_vector = assembler.label()?;
            aarch64_emit_exact_asimd_scanner(
                &mut assembler,
                exact,
                exact_vector,
                exact_scalar,
                candidate,
                use_exact_asimd_lane,
            )?;
        }

        assembler.bind(exact_scalar)?;
        aarch64_set_table_address(
            &mut assembler,
            6,
            storage
                .aarch64_lut_offset
                .ok_or(ObjectError::InvalidModule(
                    "AArch64 exact scanner has no LUT",
                ))?,
        )?;
        assembler.bind(exact_scalar_loop)?;
        aarch64_emit_start_filter_scalar_bound(&mut assembler, exact.scan_offset, finish)?;
        aarch64_emit_start_filter_scalar_load(&mut assembler, exact.scan_offset)?;
        aarch64_emit_exact_byte_set_lut_test(&mut assembler, 6, candidate)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
        assembler.branch(exact_scalar_loop)?;
    }

    if layout.has_prefix_guard() {
        assembler.bind(prefix_check)?;
        aarch64_emit_prefix_guard_path(
            &mut assembler,
            layout,
            use_prefix_block,
            None,
            prefix_fail,
            prefix_terminal,
            prefix_verified,
        )?;
        assembler.bind(prefix_fail)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
        aarch64_set_row_base(&mut assembler, layout.forward_offset)?;
        assembler.branch(scan)?;

        if let Some(coverage) = vector_coverage {
            assembler.bind(prefix_vector_check)?;
            aarch64_emit_prefix_guard_path(
                &mut assembler,
                layout,
                use_prefix_block,
                Some(coverage),
                if retain_vector_candidates {
                    prefix_retained_fail
                } else {
                    prefix_fail
                },
                prefix_terminal,
                prefix_verified,
            )?;
        }
        if retain_vector_candidates {
            assembler.bind(prefix_retained_fail)?;
            // Keep V24 intact. Form an exact `lane >= rejected + 1` mask in
            // V28, intersect it with the retained candidates, and select the
            // next lane relative to caller-saved X14.
            assembler.instruction(aarch64_add_x_imm(12, 2, 1)?)?;
            assembler.instruction(aarch64_sub_x_reg(12, 12, 14)?)?;
            assembler.instruction(aarch64_dup_16b_from_w(28, 12)?)?;
            assembler.instruction(aarch64_cmhs_16b(28, 29, 28)?)?;
            assembler.instruction(aarch64_and_16b(28, 28, 24)?)?;
            aarch64_emit_candidate_any(&mut assembler, 28)?;
            assembler.branch_cond(AARCH64_EQ, filter_retained_exhausted)?;
            aarch64_emit_first_retained_candidate_lane(&mut assembler, 28, 14)?;
            aarch64_set_row_base(&mut assembler, layout.forward_offset)?;
            assembler.branch(prefix_vector_check)?;

            assembler.bind(filter_retained_exhausted)?;
            assembler.instruction(aarch64_add_x_imm(2, 14, 16)?)?;
            aarch64_set_row_base(&mut assembler, layout.forward_offset)?;
            assembler.branch(filter_vector)?;
        }

        assembler.bind(prefix_terminal)?;
        assembler.branch(finish)?;

        assembler.bind(prefix_verified)?;
        if let Some(width) = layout.exact_prefix_match_width {
            aarch64_emit_exact_prefix_match(
                &mut assembler,
                width,
                layout.output,
                register_outcome,
                matched,
            )?;
        } else {
            assembler.branch(prefix_apply)?;
        }
    }

    assembler.bind(prefix_apply)?;
    aarch64_set_row_base(&mut assembler, layout.forward_offset)?;
    if let Some(plan) = layout.prefix_fast_forward {
        assembler.instruction(aarch64_add_x_imm(2, 2, u16::from(plan.consumed_bytes))?)?;
        aarch64_set_row_base(&mut assembler, plan.target_row_offset)?;
    }
    assembler.bind(scalar_scan)?;
    if let Some(plan) = layout.loop_skip {
        let secondary_dispatch = layout
            .loop_skip_secondary
            .map(|_| assembler.label())
            .transpose()?
            .unwrap_or(scalar_transition);
        module_dfa_loop_skip::aarch64_emit_dfa_loop_skip(
            &mut assembler,
            plan,
            &layout,
            vector_filter,
            sve_loop_kind,
            use_asimd_loop,
            loop_use_runtime_vl_dispatch.then_some((
                AARCH64_MIXED_ROOT_VL_REGISTER,
                AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER,
            )),
            use_exact_asimd_lane,
            exact_sve_kind,
            module_dfa_loop_skip::NativeDfaLoopSkipRole::Primary,
            secondary_dispatch,
            scalar_transition,
            scalar_transition,
            finish,
        )?;
        if let Some(secondary) = layout.loop_skip_secondary {
            assembler.bind(secondary_dispatch)?;
            module_dfa_loop_skip::aarch64_emit_dfa_loop_skip(
                &mut assembler,
                secondary,
                &layout,
                vector_filter,
                secondary_sve_loop_kind,
                use_asimd_secondary_loop,
                secondary_loop_use_runtime_vl_dispatch.then_some((
                    AARCH64_MIXED_ROOT_VL_REGISTER,
                    AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER,
                )),
                use_exact_asimd_lane,
                exact_sve_kind,
                module_dfa_loop_skip::NativeDfaLoopSkipRole::Secondary,
                scalar_transition,
                scalar_transition,
                scalar_body_preloaded.unwrap_or(scalar_body),
                finish,
            )?;
        }
    }
    assembler.bind(scalar_transition)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_HS, finish)?;
    assembler.bind(scalar_body)?;
    aarch64_emit_table_lookup_with_sparse_boundary_tier(
        &mut assembler,
        layout.transitions,
        layout.cells,
        layout.bit_slice_domain_count,
        features,
        operating_system,
        sparse_boundary_tier,
        sparse_sve_fused_boundary,
        scalar_body_preloaded,
    )?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    // Bits at and above the accelerator flag are zero exactly for ordinary
    // live forward cells. Every dead sentinel is tagged under the forward
    // packing policy, so one shift and one branch classify every exception.
    assembler.instruction(aarch64_lsr_w_imm(
        12,
        8,
        layout.cells.accelerated_bit(),
    )?)?;
    assembler.branch_nonzero_w(12, forward_exception)?;
    match layout.cells {
        NativeCellEncoding::Compact8Direct
        | NativeCellEncoding::Compact16
        | NativeCellEncoding::Compact16Indexed(_)
        | NativeCellEncoding::Compact16Ordinal(_) => {
            aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 8)?;
        }
        NativeCellEncoding::Wide32 => {
            // The forward packing invariant makes every ordinary wide token
            // nonzero and one-based.
            assembler.instruction(aarch64_sub_w_imm(6, 8, 1)?)?;
            aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 6)?;
        }
    }
    assembler.branch(scalar_backedge)?;
    assembler.bind(scalar_backedge)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_LO, scalar_body)?;
    assembler.branch(finish)?;

    assembler.bind(accelerated_transition)?;
    assembler.instruction(aarch64_and_low_w(6, 8, layout.cells.next_bits())?)?;
    if layout.cells.is_compact() {
        aarch64_load_u32_constant(&mut assembler, 12, layout.cells.dead_token())?;
        assembler.instruction(aarch64_cmp_w(6, 12)?)?;
        assembler.branch_cond(AARCH64_EQ, finish)?;
    }
    if let Some(partial) = layout.partial {
        aarch64_load_u32_constant(&mut assembler, 12, partial.hole_token_base)?;
        assembler.instruction(aarch64_cmp_x(6, 12)?)?;
        assembler.branch_cond(AARCH64_HS, partial_resume)?;
    }
    if !layout.cells.is_compact() {
        assembler.branch_zero_w(6, finish)?;
        assembler.instruction(aarch64_sub_w_imm(6, 6, 1)?)?;
    }
    aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 6)?;
    // Fixed exact-absolute entries omit all moving-scanner constants and the
    // mixed SVE runtime-VL sample. A moving entry without a root scanner must
    // likewise preserve this live accelerated row: its `scan` label falls
    // through the root-only prefix-apply row reset. Only an installed scanner
    // can discriminate an accelerated initial row from an interior loop row.
    assembler.branch(if fixed_candidate || !layout.has_start_scanner() {
        scalar_scan
    } else {
        scan
    })?;

    assembler.bind(partial_resume)?;
    if layout.partial.is_some() {
        assembler.instruction(aarch64_cmp_x(2, 3)?)?;
        assembler.branch_cond(AARCH64_EQ, finish)?;
        // The sole incoming edge loaded this exact hole base into X12 for its
        // unsigned range test. Keep that value live across the cold branch
        // instead of rematerializing one or two constant instructions.
        assembler.instruction(aarch64_sub_x_reg(6, 6, 12)?)?;
        if !register_outcome {
            assembler.instruction(aarch64_store_x(6, 4, 16)?)?;
            assembler.instruction(aarch64_store_x(2, 4, 24)?)?;
            if layout.output == OutputContract::Exists {
                aarch64_load_u64_constant(&mut assembler, 12, u64::MAX)?;
                assembler.instruction(aarch64_store_x(12, 4, 32)?)?;
            } else {
                assembler.instruction(aarch64_store_x(7, 4, 32)?)?;
            }
        }
        assembler.instruction(aarch64_movz_w(
            0,
            u16::try_from(NATIVE_PARTIAL_STATUS_RESUME)
                .map_err(|_| ObjectError::InvalidModule("native partial resume status"))?,
        )?)?;
        assembler.branch(done)?;
    }

    assembler.bind(forward_exception)?;
    assembler.branch_bit_set_w(8, layout.cells.accepts_bit(), accept)?;
    // Every non-accepting forward exception is accelerator-tagged: a graph
    // accelerator, partial hole, or the explicit dead sentinel.
    assembler.branch(accelerated_transition)?;

    assembler.bind(accept)?;
    if layout.output == OutputContract::Exists {
        assembler.branch(matched)?;
    } else {
        assembler.instruction(aarch64_mov_x(7, 2)?)?;
        // Clear only the layout-specific accept bit on this cold edge. Any
        // accelerator bit, including accepted-dead at every width, remains
        // available to the shared classifier.
        assembler.instruction(aarch64_and_low_w(8, 8, layout.cells.accepts_bit())?)?;
        assembler.branch_bit_set_w(8, layout.cells.accelerated_bit(), accelerated_transition)?;
        match layout.cells {
            NativeCellEncoding::Compact8Direct
            | NativeCellEncoding::Compact16
            | NativeCellEncoding::Compact16Indexed(_)
            | NativeCellEncoding::Compact16Ordinal(_) => {
                aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 8)?;
            }
            NativeCellEncoding::Wide32 => {
                // Accepted dead is tagged, so an ordinary accepted wide cell
                // is necessarily a nonzero one-based row token.
                assembler.instruction(aarch64_sub_w_imm(6, 8, 1)?)?;
                aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 6)?;
            }
        }
        assembler.branch(scalar_backedge)?;
    }

    assembler.bind(finish)?;
    if layout.output == OutputContract::Exists {
        assembler.branch(no_match)?;
    } else {
        assembler.instruction(aarch64_cmp_x(7, 13)?)?;
        assembler.branch_cond(AARCH64_EQ, no_match)?;
    }
    if layout.output == OutputContract::Span && !layout.initial_pending {
        if layout.exact_span_width.is_none() && !layout.has_reverse && layout.partial.is_none() {
            return Err(ObjectError::InvalidModule(
                "AArch64 span lowering has no reverse table",
            ));
        }
    } else {
        if layout.output == OutputContract::Span {
            if register_outcome {
                assembler.instruction(aarch64_mov_x(6, 9)?)?;
            } else {
                assembler.instruction(aarch64_store_x(9, 4, 0)?)?;
                assembler.instruction(aarch64_store_x(7, 4, 8)?)?;
            }
        } else if layout.output == OutputContract::SelectedEnd && !register_outcome {
            assembler.instruction(aarch64_store_x(7, 4, 0)?)?;
            assembler.instruction(aarch64_store_x(7, 4, 8)?)?;
        }
        assembler.branch(matched)?;
    }

    if layout.output == OutputContract::Span && !layout.initial_pending {
        if !register_outcome {
            assembler.instruction(aarch64_store_x(7, 4, 8)?)?;
        }
        if let Some(width) = layout.exact_span_width {
            if layout.has_reverse {
                return Err(ObjectError::InvalidModule(
                    "fixed-width AArch64 span unexpectedly retained a reverse table",
                ));
            }
            aarch64_emit_exact_span_start(&mut assembler, width)?;
            if !register_outcome {
                assembler.instruction(aarch64_store_x(6, 4, 0)?)?;
            }
            assembler.branch(matched)?;
        } else if layout.partial.is_some() {
            if entry_contract.propagates_partial_span_window_start() {
                if register_outcome {
                    assembler.instruction(aarch64_mov_x(6, 9)?)?;
                } else {
                    assembler.instruction(aarch64_store_x(9, 4, 0)?)?;
                }
                assembler.branch(matched)?;
            } else {
                assembler.branch(selected_end)?;
            }
        } else {
            assembler.instruction(aarch64_mov_x(2, 7)?)?;
            assembler.instruction(aarch64_mov_x(10, 13)?)?;
            aarch64_set_row_base(&mut assembler, layout.reverse_offset)?;
            assembler.bind(reverse_scan)?;
            assembler.instruction(aarch64_cmp_x(2, 9)?)?;
            assembler.branch_cond(AARCH64_LS, reverse_finish)?;
            assembler.instruction(aarch64_sub_x_imm(2, 2, 1)?)?;
            aarch64_emit_table_lookup_with_sparse_boundary_tier(
                &mut assembler,
                layout.transitions,
                layout.cells,
                layout.bit_slice_domain_count,
                features,
                operating_system,
                sparse_boundary_tier,
                sparse_sve_fused_boundary,
                None,
            )?;
            match layout.cells {
                NativeCellEncoding::Compact8Direct
                | NativeCellEncoding::Compact16
                | NativeCellEncoding::Compact16Indexed(_)
                | NativeCellEncoding::Compact16Ordinal(_) => {
                    assembler.instruction(aarch64_lsr_w_imm(
                        12,
                        8,
                        layout.cells.accelerated_bit(),
                    )?)?;
                    assembler.branch_nonzero_w(12, reverse_exception)?;
                    aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 8)?;
                    assembler.branch(reverse_scan)?;
                }
                NativeCellEncoding::Wide32 => {
                    assembler.branch_bit_set_w(
                        8,
                        layout.cells.accepts_bit(),
                        record_reverse_start,
                    )?;
                    // Reverse cells never carry accelerator metadata. A
                    // non-accepting wide cell is zero or a raw token.
                    assembler.branch_zero_w(8, reverse_finish)?;
                }
            }
            assembler.bind(reverse_continue)?;
            if layout.cells == NativeCellEncoding::Wide32 {
                assembler.instruction(aarch64_sub_w_imm(6, 8, 1)?)?;
                aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 6)?;
                assembler.branch(reverse_scan)?;
            }

            assembler.bind(reverse_exception)?;
            if layout.cells.is_compact() {
                assembler.branch_bit_set_w(8, layout.cells.accepts_bit(), record_reverse_start)?;
                // The only non-accepting compact exception is dead.
                assembler.branch(reverse_finish)?;
            }

            assembler.bind(record_reverse_start)?;
            assembler.instruction(aarch64_mov_x(10, 2)?)?;
            assembler.instruction(aarch64_and_low_w(8, 8, layout.cells.accepts_bit())?)?;
            if layout.cells.is_compact() {
                assembler.branch_bit_set_w(8, layout.cells.accelerated_bit(), reverse_finish)?;
                aarch64_set_row_from_zero_based_cell(&mut assembler, layout.cells, 8)?;
                assembler.branch(reverse_scan)?;
            } else {
                assembler.branch_zero_w(8, reverse_finish)?;
                assembler.branch(reverse_continue)?;
            }

            assembler.bind(reverse_finish)?;
            assembler.instruction(aarch64_cmp_x(10, 13)?)?;
            assembler.branch_cond(AARCH64_EQ, invalid)?;
            assembler.instruction(aarch64_store_x(10, 4, 0)?)?;
            assembler.branch(matched)?;
        }
    }

    assembler.bind(no_match)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.branch(done)?;
    assembler.bind(matched)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(done)?;
    assembler.bind(selected_end)?;
    if layout.partial.is_some() {
        assembler.instruction(aarch64_movz_w(
            0,
            u16::try_from(NATIVE_PARTIAL_STATUS_SELECTED_END)
                .map_err(|_| ObjectError::InvalidModule("native selected-end status"))?,
        )?)?;
        assembler.branch(done)?;
    }
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.bind(done)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut relocation_offsets = [table_page, table_page_offset];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    let relocations = vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(relocation_offsets[0], "AArch64 DFA ADRP relocation offset")?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(relocation_offsets[1], "AArch64 DFA ADD relocation offset")?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
        ];
    let conjunction = if (use_asimd_filter || use_sve_filter)
        && let Some(filter) = vector_filter
        && let Some(coverage) =
            derive_native_vector_guard_coverage(layout, false, Some(filter))
    {
        let sve_batch = use_sve_filter
            && sve_filter_plan.is_some_and(|plan| {
                aarch64_sve_batch_max_vector_bytes(
                    layout.start_filter.unwrap_or(EMPTY_NATIVE_START_FILTER),
                    plan.primary(),
                )
                .is_some()
            });
        let batch_vectors = if use_asimd_multicolumn_batch || sve_batch {
            u8::try_from(AARCH64_SVE_BATCH_VECTORS).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 conjunction batch vectors")
            })?
        } else {
            1
        };
        Some(NativeVectorConjunctionEmission {
            filter,
            coverage,
            batch_vectors,
        })
    } else {
        None
    };
    // Correlated Teddy is authenticated separately against the exact suffix
    // portfolio. Its split-nibble projection may contain false-positive bytes
    // and therefore must not masquerade as an exact one-column receipt.
    let suffix_scanner = if layout.mandatory_teddy.is_some() {
        None
    } else {
        layout
            .suffix_filter
            .map(|suffix| {
                aarch64_suffix_scanner_emission(
                    suffix.filter,
                    sve_suffix_kind,
                    use_asimd_suffix,
                )
            })
            .transpose()?
    };
    Ok(NativeDfaEmission {
        code,
        relocations,
        scanner: scanner_emission,
        suffix_scanner,
        conjunction,
    })
}

fn aarch64_instruction(code: &mut Vec<u8>, instruction: u32) -> Result<(), ObjectError> {
    push_bytes(code, &instruction.to_le_bytes())
}

fn aarch64_mov(destination: u8, source: u8) -> u32 {
    // MOV Xd, Xm aliases ORR Xd, XZR, Xm.
    0xaa00_03e0 | (u32::from(source) << 16) | u32::from(destination)
}

fn aarch64_emit_public_search_abi_validation(
    assembler: &mut Aarch64Assembler,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.instruction(0xf100_003f)?; // cmp length, #0
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.instruction(aarch64_cmp_x(3, 1)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(0xf100_009f)?; // cmp x4, #0
    assembler.branch_cond(AARCH64_EQ, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 4, 3)?)?;
    assembler.instruction(0xf100_00bf)?; // cmp alignment scratch, #0
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(0xf100_001f)?; // cmp x0, #0
    assembler.branch_cond(AARCH64_EQ, invalid)?;
    Ok(())
}

fn aarch64_finish_native_finite_exists_leaf(
    assembler: &mut Aarch64Assembler,
    matched: Aarch64Label,
    no_match: Aarch64Label,
    invalid: Aarch64Label,
) -> Result<(), ObjectError> {
    assembler.bind(matched)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(no_match)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.instruction(0xd65f_03c0)?;
    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;
    Ok(())
}

fn aarch64_finish_native_finite_exists_with_optional_program_relocation(
    assembler: Aarch64Assembler,
    program_relocation: Option<(usize, usize)>,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let Some((program_page, program_page_offset)) = program_relocation else {
        return Ok((assembler.finish_with_offsets(&mut [])?, Vec::new()));
    };
    let mut relocation_offsets = [program_page, program_page_offset];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    Ok((
        code,
        vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[0],
                    "AArch64 finite Exists ADRP relocation offset",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[1],
                    "AArch64 finite Exists ADD relocation offset",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
        ],
    ))
}

fn aarch64_emit_native_finite_exists_program_base(
    assembler: &mut Aarch64Assembler,
) -> Result<(usize, usize), ObjectError> {
    let program_page = assembler.instruction(0x9000_0005)?; // adrp x5, program@PAGE
    let program_page_offset = assembler.instruction(aarch64_add_x_imm(5, 5, 0)?)?;
    Ok((program_page, program_page_offset))
}

fn lower_aarch64_native_finite_exists_universal(
    membership: [u64; 4],
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    let mut assembler = Aarch64Assembler::new();
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(aarch64_store_x(31, 4, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 4, 8)?)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_LO, matched)?;
    assembler.branch(no_match)?;
    aarch64_finish_native_finite_exists_leaf(&mut assembler, matched, no_match, invalid)?;
    Ok(NativeFiniteExistsByteSetEmission {
        code: assembler.finish_with_offsets(&mut [])?,
        relocations: Vec::new(),
        scanner: NativeScannerEmission {
            scan_offset: 0,
            membership,
            isa: NativeScannerIsa::ScalarEmpty,
            vectorized: false,
        },
    })
}

fn lower_aarch64_native_finite_exists_filter(
    plan: Aarch64FiniteExistsFilterPlan,
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    if plan.filter.scan_offset != 0 || plan.filter.ranges().is_empty() {
        return Err(ObjectError::InvalidModule(
            "AArch64 finite Exists filter has invalid geometry",
        ));
    }
    let mut assembler = Aarch64Assembler::new();
    let sve_vector = plan.sve_kind.map(|_| assembler.label()).transpose()?;
    let asimd_vector = plan.use_asimd.then(|| assembler.label()).transpose()?;
    let scalar = assembler.label()?;
    let scalar_miss = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    let asimd_setup = plan
        .use_runtime_vl_dispatch
        .then(|| assembler.label())
        .transpose()?;
    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(aarch64_store_x(31, 4, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 4, 8)?)?;
    let program_relocation = if matches!(plan.sve_kind, Some(Aarch64SveFilterKind::Sve2 { .. })) {
        Some(aarch64_emit_native_finite_exists_program_base(
            &mut assembler,
        )?)
    } else {
        None
    };

    if plan.use_runtime_vl_dispatch {
        assembler.instruction(aarch64_sve_cntb(6)?)?;
        assembler.instruction(aarch64_cmp_x_imm(6, 16)?)?;
        assembler.branch_cond(
            AARCH64_LS,
            asimd_setup.ok_or(ObjectError::InvalidModule(
                "mixed finite Exists ASIMD setup is absent",
            ))?,
        )?;
    }
    if let Some(sve_kind) = plan.sve_kind {
        aarch64_emit_sve_filter_setup(&mut assembler, plan.filter, sve_kind, 0)?;
        aarch64_emit_sve_start_filter_scanner(
            &mut assembler,
            plan.filter,
            0,
            sve_kind,
            false,
            plan.use_runtime_vl_dispatch,
            sve_vector.ok_or(ObjectError::InvalidModule(
                "finite Exists SVE vector label is absent",
            ))?,
            scalar,
            matched,
        )?;
    }
    if plan.use_asimd {
        if let Some(asimd_setup) = asimd_setup {
            assembler.bind(asimd_setup)?;
        }
        aarch64_emit_start_filter_constants(
            &mut assembler,
            plan.filter,
            AARCH64_STANDALONE_FILTER_FIRST_CONSTANT,
        )?;
        let asimd_vector = asimd_vector.ok_or(ObjectError::InvalidModule(
            "finite Exists ASIMD vector label is absent",
        ))?;
        assembler.bind(asimd_vector)?;
        assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
        assembler.instruction(aarch64_cmp_x_imm(12, 16)?)?;
        assembler.branch_cond(AARCH64_LO, scalar)?;
        aarch64_emit_start_filter_address(&mut assembler, 0)?;
        assembler.instruction(aarch64_load_q(0, 12)?)?;
        aarch64_emit_start_filter_vector_test(&mut assembler, plan.filter, 0, 24)?;
        assembler.branch_cond(AARCH64_NE, matched)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
        assembler.branch(asimd_vector)?;
    }

    assembler.bind(scalar)?;
    aarch64_emit_start_filter_scalar_bound(&mut assembler, 0, no_match)?;
    aarch64_emit_scalar_filter_membership(&mut assembler, plan.filter, scalar_miss)?;
    assembler.branch(matched)?;
    assembler.bind(scalar_miss)?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    assembler.branch(scalar)?;
    aarch64_finish_native_finite_exists_leaf(&mut assembler, matched, no_match, invalid)?;
    let (code, relocations) =
        aarch64_finish_native_finite_exists_with_optional_program_relocation(
            assembler,
            program_relocation,
        )?;
    Ok(NativeFiniteExistsByteSetEmission {
        code,
        relocations,
        scanner: plan.scanner,
    })
}

fn lower_aarch64_native_finite_exists_exact(
    plan: Aarch64FiniteExistsExactPlan,
) -> Result<NativeFiniteExistsByteSetEmission, ObjectError> {
    if plan.set.scan_offset != 0
        || !plan.set.is_valid()
        || plan.storage.aarch64_lut_offset.is_none()
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 finite Exists exact-set storage is malformed",
        ));
    }
    let mut assembler = Aarch64Assembler::new();
    let sve_vector = plan.sve_kind.map(|_| assembler.label()).transpose()?;
    let asimd_vector = plan.use_asimd.then(|| assembler.label()).transpose()?;
    let scalar = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let invalid = assembler.label()?;
    let asimd_setup = plan
        .use_runtime_vl_dispatch
        .then(|| assembler.label())
        .transpose()?;
    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(aarch64_store_x(31, 4, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 4, 8)?)?;
    let program_relocation =
        aarch64_emit_native_finite_exists_program_base(&mut assembler)?;

    if plan.use_runtime_vl_dispatch {
        assembler.instruction(aarch64_sve_cntb(6)?)?;
        assembler.instruction(aarch64_cmp_x_imm(6, 16)?)?;
        assembler.branch_cond(
            AARCH64_LS,
            asimd_setup.ok_or(ObjectError::InvalidModule(
                "mixed finite Exists exact ASIMD setup is absent",
            ))?,
        )?;
    }
    if let Some(sve_kind) = plan.sve_kind {
        aarch64_emit_exact_sve_constants(&mut assembler, plan.storage, sve_kind)?;
        aarch64_emit_exact_sve_scanner(
            &mut assembler,
            plan.set,
            sve_kind,
            plan.use_runtime_vl_dispatch.then_some(6),
            sve_vector.ok_or(ObjectError::InvalidModule(
                "finite Exists exact SVE vector label is absent",
            ))?,
            scalar,
            matched,
        )?;
    }
    if plan.use_asimd {
        if let Some(asimd_setup) = asimd_setup {
            assembler.bind(asimd_setup)?;
        }
        aarch64_emit_exact_asimd_constants(&mut assembler, plan.storage)?;
        let asimd_vector = asimd_vector.ok_or(ObjectError::InvalidModule(
            "finite Exists exact ASIMD vector label is absent",
        ))?;
        assembler.bind(asimd_vector)?;
        assembler.instruction(aarch64_sub_x_reg(12, 3, 2)?)?;
        assembler.instruction(aarch64_cmp_x_imm(12, 16)?)?;
        assembler.branch_cond(AARCH64_LO, scalar)?;
        aarch64_emit_exact_asimd_candidates(&mut assembler, 0)?;
        assembler.branch_cond(AARCH64_NE, matched)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 16)?)?;
        assembler.branch(asimd_vector)?;
    }

    assembler.bind(scalar)?;
    aarch64_set_table_address(
        &mut assembler,
        6,
        plan.storage
            .aarch64_lut_offset
            .ok_or(ObjectError::InvalidModule(
                "AArch64 finite Exists exact-set LUT is absent",
            ))?,
    )?;
    let scalar_loop = assembler.label()?;
    assembler.bind(scalar_loop)?;
    aarch64_emit_start_filter_scalar_bound(&mut assembler, 0, no_match)?;
    aarch64_emit_start_filter_scalar_load(&mut assembler, 0)?;
    aarch64_emit_exact_byte_set_lut_test(&mut assembler, 6, matched)?;
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    assembler.branch(scalar_loop)?;
    aarch64_finish_native_finite_exists_leaf(&mut assembler, matched, no_match, invalid)?;
    let (code, relocations) =
        aarch64_finish_native_finite_exists_with_optional_program_relocation(
            assembler,
            Some(program_relocation),
        )?;
    Ok(NativeFiniteExistsByteSetEmission {
        code,
        relocations,
        scanner: plan.scanner,
    })
}

/// Scalar AAPCS64 leaf for the authenticated ordered finite-language graph.
/// It avoids x18 (reserved by Apple platforms), uses no callee-saved register,
/// and is call-free. ASIMD/SVE/SVE2 scanning remains a later additive layer on
/// top of this equivalence baseline.
fn lower_aarch64_native_finite_language(
    output: OutputContract,
    layout: NativeFiniteLanguageLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    match layout.representation {
        NativeFiniteLanguageRepresentation::Dense
        | NativeFiniteLanguageRepresentation::SparseFailure => {
            lower_aarch64_native_finite_language_impl(output, layout)
        }
    }
}

fn lower_aarch64_native_finite_language_impl(
    output: OutputContract,
    layout: NativeFiniteLanguageLayout,
) -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let mut assembler = Aarch64Assembler::new();
    let scan = assembler.label()?;
    let replace = assembler.label()?;
    let horizon = assembler.label()?;
    let finish = assembler.label()?;
    let matched = assembler.label()?;
    let no_match = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;
    let sparse_labels = if layout.representation
        == NativeFiniteLanguageRepresentation::SparseFailure
    {
        Some((
            assembler.label()?, // root-only loop while no match is pending
            assembler.label()?, // retry current byte
            assembler.label()?, // direct root table
            assembler.label()?, // root miss from the generic retry path
            assembler.label()?, // specialized one-edge row
            assembler.label()?, // straight-line two-to-four-edge row
            assembler.label()?, // explicit-edge loop
            assembler.label()?, // explicit edge found
            assembler.label()?, // follow failure
            assembler.label()?, // transition selected
        ))
    } else {
        None
    };
    let root_batch = native_finite_root_batch_is_admitted(layout);
    let root_scalar_only = if root_batch {
        Some(assembler.label()?)
    } else {
        None
    };

    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(aarch64_store_x(31, 4, 0)?)?;
    assembler.instruction(aarch64_store_x(31, 4, 8)?)?;
    if root_batch {
        assembler.instruction(aarch64_sub_x_imm(31, 31, 16)?)?;
        assembler.instruction(aarch64_store_x(31, 31, 0)?)?;
    }

    // Load the class-map base from the native program symbol.
    let program_page = assembler.instruction(0x9000_0005)?; // adrp x5, program@PAGE
    let program_page_offset =
        assembler.instruction(aarch64_add_x_imm(5, 5, 0)?)?; // program@PAGEOFF
    assembler.instruction(aarch64_mov_x(16, 5)?)?;
    aarch64_set_table_address(&mut assembler, 17, layout.row_offset)?;
    if layout.representation == NativeFiniteLanguageRepresentation::SparseFailure {
        aarch64_set_table_address(&mut assembler, 13, layout.sparse_edges_offset)?;
    }
    aarch64_load_u32_constant(&mut assembler, 15, layout.maximum_width)?;
    assembler.instruction(aarch64_mov_x(6, 17)?)?; // current row = rows base
    assembler.instruction(aarch64_mov_x(9, 3)?)?; // pending start sentinel
    aarch64_load_u32_constant(&mut assembler, 11, u32::MAX)?;

    if let Some((root_scan, _, _, _, _, _, _, _, _, transitioned)) = sparse_labels {
        if let Some(root_scalar_only) = root_scalar_only {
            let root_scalar_tail = assembler.label()?;
            assembler.bind(root_scan)?;
            assembler.instruction(aarch64_sub_x_reg(1, 3, 2)?)?;
            assembler.instruction(aarch64_cmp_x_imm(1, 4)?)?;
            assembler.branch_cond(AARCH64_LO, root_scalar_tail)?;
            assembler.instruction(aarch64_add_x_reg(1, 0, 2)?)?;
            for (register, offset) in [(7, 0), (8, 1), (12, 2), (14, 3)] {
                assembler.instruction(aarch64_load_byte_imm(register, 1, offset)?)?;
                match layout.cells {
                    NativeFiniteLanguageCellWidth::U16 => {
                        assembler.instruction(aarch64_load_h_uxtw(register, 5, register)?)?;
                    }
                    NativeFiniteLanguageCellWidth::U32 => {
                        assembler.instruction(aarch64_load_w_uxtw(register, 5, register)?)?;
                    }
                }
            }
            assembler.instruction(aarch64_orr_w(7, 7, 8)?)?;
            assembler.instruction(aarch64_orr_w(7, 7, 12)?)?;
            assembler.instruction(aarch64_orr_w(7, 7, 14)?)?;
            let root_batch_miss = assembler.label()?;
            assembler.branch_zero_w(7, root_batch_miss)?;
            assembler.instruction(aarch64_movz_w(1, 1)?)?;
            assembler.instruction(aarch64_store_x(1, 31, 0)?)?;
            assembler.branch(root_scalar_only)?;
            assembler.bind(root_batch_miss)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 4)?)?;
            assembler.branch(root_scan)?;

            assembler.bind(root_scalar_tail)?;
            assembler.instruction(aarch64_cmp_x(2, 3)?)?;
            assembler.branch_cond(AARCH64_HS, finish)?;
            assembler.instruction(aarch64_load_byte_reg(7, 0, 2)?)?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(aarch64_load_h_uxtw(14, 5, 7)?)?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(aarch64_load_w_uxtw(14, 5, 7)?)?;
                }
            }
            assembler.branch_nonzero_w(14, transitioned)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
            assembler.branch(root_scan)?;

            assembler.bind(root_scalar_only)?;
            assembler.instruction(aarch64_cmp_x(2, 3)?)?;
            assembler.branch_cond(AARCH64_HS, finish)?;
            assembler.instruction(aarch64_load_byte_reg(7, 0, 2)?)?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(aarch64_load_h_uxtw(14, 5, 7)?)?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(aarch64_load_w_uxtw(14, 5, 7)?)?;
                }
            }
            assembler.branch_nonzero_w(14, transitioned)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
            assembler.branch(root_scalar_only)?;
        } else {
            assembler.bind(root_scan)?;
            assembler.instruction(aarch64_cmp_x(2, 3)?)?;
            assembler.branch_cond(AARCH64_HS, finish)?;
            assembler.instruction(aarch64_load_byte_reg(7, 0, 2)?)?;
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => {
                    assembler.instruction(aarch64_load_h_uxtw(14, 5, 7)?)?;
                }
                NativeFiniteLanguageCellWidth::U32 => {
                    assembler.instruction(aarch64_load_w_uxtw(14, 5, 7)?)?;
                }
            }
            assembler.branch_nonzero_w(14, transitioned)?;
            assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
            assembler.branch(root_scan)?;
        }
    }
    assembler.bind(scan)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_HS, finish)?;
    assembler.instruction(aarch64_load_byte_reg(7, 0, 2)?)?;
    if let Some((
        _,
        retry,
        root,
        root_miss,
        one_edge,
        small_sparse,
        edge_loop,
        edge_found,
        failure,
        transitioned,
    )) = sparse_labels
    {
        assembler.bind(retry)?;
        assembler.instruction(aarch64_cmp_x(6, 17)?)?;
        assembler.branch_cond(AARCH64_EQ, root)?;
        assembler.instruction(aarch64_load_w_imm(12, 6, 4)?)?;
        assembler.instruction(aarch64_and_low_w(
            14,
            12,
            u8::try_from(NATIVE_FINITE_SPARSE_EDGE_START_BITS).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 finite sparse edge bits")
            })?,
        )?)?;
        assembler.instruction(aarch64_add_x_uxtw(
            1,
            13,
            14,
            match layout.cells {
                NativeFiniteLanguageCellWidth::U16 => 2,
                NativeFiniteLanguageCellWidth::U32 => 3,
            },
        )?)?;
        assembler.instruction(aarch64_lsr_w_imm(
            12,
            12,
            u8::try_from(NATIVE_FINITE_SPARSE_EDGE_COUNT_SHIFT).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 finite sparse count shift")
            })?,
        )?)?;
        assembler.instruction(aarch64_cmp_w_imm(12, 1)?)?;
        assembler.branch_cond(AARCH64_EQ, one_edge)?;
        assembler.branch_cond(AARCH64_LO, failure)?;
        assembler.instruction(aarch64_cmp_w_imm(12, 4)?)?;
        assembler.branch_cond(AARCH64_LS, small_sparse)?;

        assembler.bind(edge_loop)?;
        assembler.branch_zero_w(12, failure)?;
        assembler.instruction(aarch64_load_byte_imm(14, 1, 0)?)?;
        assembler.instruction(aarch64_cmp_w(7, 14)?)?;
        assembler.branch_cond(AARCH64_EQ, edge_found)?;
        assembler.branch_cond(AARCH64_LO, failure)?;
        assembler.instruction(aarch64_add_x_imm(
            1,
            1,
            u16::try_from(native_finite_sparse_edge_stride(layout.cells)).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 finite sparse edge stride")
            })?,
        )?)?;
        assembler.instruction(aarch64_sub_w_imm(12, 12, 1)?)?;
        assembler.branch(edge_loop)?;

        assembler.bind(one_edge)?;
        assembler.instruction(aarch64_load_byte_imm(14, 1, 0)?)?;
        assembler.instruction(aarch64_cmp_w(7, 14)?)?;
        assembler.branch_cond(AARCH64_EQ, edge_found)?;
        assembler.branch(failure)?;

        assembler.bind(small_sparse)?;
        for index in 0_u16..4 {
            assembler.instruction(aarch64_load_byte_imm(14, 1, 0)?)?;
            assembler.instruction(aarch64_cmp_w(7, 14)?)?;
            assembler.branch_cond(AARCH64_EQ, edge_found)?;
            if index == 3 {
                assembler.branch(failure)?;
                break;
            }
            assembler.branch_cond(AARCH64_LO, failure)?;
            if index != 0 {
                assembler.instruction(aarch64_cmp_w_imm(12, index + 1)?)?;
                assembler.branch_cond(AARCH64_EQ, failure)?;
            }
            assembler.instruction(aarch64_add_x_imm(
                1,
                1,
                u16::try_from(native_finite_sparse_edge_stride(layout.cells)).map_err(|_| {
                    ObjectError::ArithmeticOverflow("AArch64 finite sparse edge stride")
                })?,
            )?)?;
        }

        assembler.bind(failure)?;
        assembler.instruction(aarch64_load_w_imm(14, 6, 0)?)?;
        assembler.instruction(aarch64_add_x_uxtw(6, 17, 14, 0)?)?;
        assembler.branch(retry)?;

        assembler.bind(root)?;
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(aarch64_load_h_uxtw(14, 5, 7)?)?;
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(aarch64_load_w_uxtw(14, 5, 7)?)?;
            }
        }
        assembler.branch_zero_w(14, root_miss)?;
        assembler.branch(transitioned)?;

        assembler.bind(root_miss)?;
        assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
        assembler.branch(horizon)?;

        assembler.bind(edge_found)?;
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(aarch64_load_halfword_imm(14, 1, 2)?)?;
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(aarch64_load_w_imm(14, 1, 4)?)?;
            }
        }
        assembler.bind(transitioned)?;
        assembler.instruction(aarch64_add_x_uxtw(6, 17, 14, 0)?)?;
    } else {
        assembler.instruction(aarch64_load_byte_reg(7, 16, 7)?)?;
        match layout.cells {
            NativeFiniteLanguageCellWidth::U16 => {
                assembler.instruction(aarch64_load_h_uxtw(6, 6, 7)?)?;
            }
            NativeFiniteLanguageCellWidth::U32 => {
                assembler.instruction(aarch64_load_w_uxtw(6, 6, 7)?)?;
            }
        }
        assembler.instruction(aarch64_add_x_uxtw(6, 17, 6, 0)?)?;
    }
    assembler.instruction(aarch64_add_x_imm(2, 2, 1)?)?;
    assembler.instruction(aarch64_load_w_imm(
        7,
        6,
        u16::try_from(layout.output_in_row_offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 finite row output offset"))?,
    )?)?;
    assembler.branch_zero_w(7, horizon)?;

    if output == OutputContract::Exists {
        assembler.branch(matched)?;
    } else {
        let ordinal_offset = layout
            .output_in_row_offset
            .checked_add(4)
            .ok_or(ObjectError::ArithmeticOverflow("AArch64 finite ordinal offset"))?;
        assembler.instruction(aarch64_load_w_imm(
            8,
            6,
            u16::try_from(ordinal_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 finite ordinal offset"))?,
        )?)?;
        assembler.instruction(aarch64_sub_x_reg(14, 2, 7)?)?;
        assembler.instruction(aarch64_cmp_x(14, 9)?)?;
        assembler.branch_cond(AARCH64_LO, replace)?;
        assembler.branch_cond(AARCH64_HI, horizon)?;
        assembler.instruction(aarch64_cmp_w(8, 11)?)?;
        assembler.branch_cond(AARCH64_HS, horizon)?;

        assembler.bind(replace)?;
        assembler.instruction(aarch64_mov_x(9, 14)?)?;
        assembler.instruction(aarch64_mov_x(10, 2)?)?;
        assembler.instruction(aarch64_mov_x(11, 8)?)?;
    }

    assembler.bind(horizon)?;
    assembler.instruction(aarch64_cmp_x(9, 3)?)?;
    if let Some((root_scan, ..)) = sparse_labels {
        let pending = assembler.label()?;
        assembler.branch_cond(AARCH64_NE, pending)?;
        assembler.instruction(aarch64_cmp_x(6, 17)?)?;
        assembler.branch_cond(AARCH64_NE, scan)?;
        if let Some(root_scalar_only) = root_scalar_only {
            assembler.instruction(aarch64_load_w_imm(1, 31, 0)?)?;
            assembler.branch_nonzero_w(1, root_scalar_only)?;
        }
        assembler.branch(root_scan)?;
        assembler.bind(pending)?;
    } else {
        assembler.branch_cond(AARCH64_EQ, scan)?;
    }
    assembler.instruction(aarch64_add_x_reg(14, 9, 15)?)?;
    assembler.instruction(aarch64_cmp_x(2, 14)?)?;
    assembler.branch_cond(AARCH64_HS, finish)?;
    assembler.branch(scan)?;

    assembler.bind(finish)?;
    if output == OutputContract::Exists {
        assembler.branch(no_match)?;
    } else {
        assembler.instruction(aarch64_cmp_x(9, 3)?)?;
        assembler.branch_cond(AARCH64_EQ, no_match)?;
        match output {
            OutputContract::SelectedEnd => {
                assembler.instruction(aarch64_store_x(10, 4, 0)?)?;
                assembler.instruction(aarch64_store_x(10, 4, 8)?)?;
            }
            OutputContract::Span => {
                assembler.instruction(aarch64_store_x(9, 4, 0)?)?;
                assembler.instruction(aarch64_store_x(10, 4, 8)?)?;
            }
            OutputContract::Exists => unreachable!("handled above"),
        }
        assembler.branch(matched)?;
    }

    assembler.bind(matched)?;
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.branch(returned)?;
    assembler.bind(no_match)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.bind(returned)?;
    if root_batch {
        assembler.instruction(aarch64_add_x_imm(31, 31, 16)?)?;
    }
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut relocation_offsets = [program_page, program_page_offset];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    Ok((
        code,
        vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[0],
                    "AArch64 finite ADRP relocation offset",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[1],
                    "AArch64 finite ADD relocation offset",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
        ],
    ))
}

fn lower_aarch64_runtime_adapter() -> Result<(Vec<u8>, Vec<ModuleRelocation>), ObjectError> {
    let mut assembler = Aarch64Assembler::new();
    let invalid = assembler.label()?;

    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;

    // Shift x0..x4 to x1..x5, from high to low to avoid clobbering.
    assembler.instruction(aarch64_mov(5, 4))?;
    assembler.instruction(aarch64_mov(4, 3))?;
    assembler.instruction(aarch64_mov(3, 2))?;
    assembler.instruction(aarch64_mov(2, 1))?;
    assembler.instruction(aarch64_mov(1, 0))?;

    // adrp x0, program@PAGE
    let program_page = assembler.instruction(0x9000_0000)?;
    // add x0, x0, program@PAGEOFF
    let program_page_offset = assembler.instruction(0x9100_0000)?;
    // b runtime -- tail branch; no link register update.
    let runtime_branch = assembler.instruction(0x1400_0000)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;
    let mut relocation_offsets = [program_page, program_page_offset, runtime_branch];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;

    Ok((
        code,
        vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(relocation_offsets[0], "AArch64 ADRP relocation offset")?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(relocation_offsets[1], "AArch64 ADD relocation offset")?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(relocation_offsets[2], "AArch64 branch relocation offset")?,
                kind: RelocationKind::Aarch64Branch26,
                symbol: RUNTIME_SYMBOL,
                addend: 0,
            },
        ],
    ))
}

fn lower_aarch64_endpoint_oracle_wrapper(
    mode: NativeEndpointOracleMode,
) -> Result<NativeEndpointOracleWrapper, ObjectError> {
    match mode {
        NativeEndpointOracleMode::NegativeOnly => {
            lower_aarch64_negative_endpoint_oracle_wrapper()
        }
        NativeEndpointOracleMode::Exact { output, width } => {
            lower_aarch64_exact_endpoint_oracle_wrapper(output, width)
        }
    }
}

/// The exact wrapper consumes the private first-end cursor in X2. Its one
/// 16-byte AAPCS64 frame preserves only the public result pointer and LR; a
/// positive never restores the haystack/window arguments or enters runtime.
fn lower_aarch64_exact_endpoint_oracle_wrapper(
    output: NativeExactEndpointOutput,
    width: u64,
) -> Result<NativeEndpointOracleWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 16;
    let mut assembler = Aarch64Assembler::new();
    let matched = assembler.label()?;
    let returned = assembler.label()?;
    let unwind = assembler.label()?;
    let invalid = assembler.label()?;

    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;
    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(4, 30, 31, 0)?)?;
    let core_call_offset = assembler.instruction(0x9400_0000)?;

    assembler.instruction(aarch64_cmp_w_imm(0, 0)?)?;
    assembler.branch_cond(AARCH64_EQ, returned)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 2)?)?;
    assembler.branch_cond(AARCH64_EQ, returned)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;
    assembler.branch(returned)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_pair_x(4, 30, 31, 0)?)?;
    assembler.branch(unwind)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_pair_x(4, 30, 31, 0)?)?;
    match output {
        NativeExactEndpointOutput::SelectedEnd => {
            assembler.instruction(aarch64_store_x(2, 4, 0)?)?;
            assembler.instruction(aarch64_store_x(2, 4, 8)?)?;
        }
        NativeExactEndpointOutput::Span => {
            assembler.instruction(aarch64_mov_x(7, 2)?)?;
            aarch64_emit_exact_span_start(&mut assembler, width)?;
            assembler.instruction(aarch64_store_x(6, 4, 0)?)?;
            assembler.instruction(aarch64_store_x(2, 4, 8)?)?;
        }
    }
    assembler.instruction(aarch64_movz_w(0, 1)?)?;

    assembler.bind(unwind)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [core_call_offset];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeEndpointOracleWrapper {
        code,
        relocations: Vec::new(),
        core_call_offset: offsets[0],
    })
}

fn lower_aarch64_negative_endpoint_oracle_wrapper()
-> Result<NativeEndpointOracleWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 48;
    let mut assembler = Aarch64Assembler::new();
    let no_match = assembler.label()?;
    let replay = assembler.label()?;
    let runtime_fallback = assembler.label()?;
    let returned = assembler.label()?;
    let invalid = assembler.label()?;

    aarch64_emit_public_search_abi_validation(&mut assembler, invalid)?;

    assembler.instruction(aarch64_sub_x_reg(5, 3, 2)?)?;
    assembler.instruction(aarch64_cmp_x_imm(
        5,
        u16::try_from(NATIVE_ENDPOINT_ORACLE_MIN_INPUT_BYTES).map_err(|_| {
            ObjectError::ArithmeticOverflow("AArch64 endpoint-oracle input floor")
        })?,
    )?)?;
    assembler.branch_cond(AARCH64_LO, runtime_fallback)?;

    // The 48-byte AAPCS64 frame preserves x0..x4 and LR and remains 16-byte
    // aligned across the local existence-leaf call.
    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(0, 1, 31, 0)?)?;
    assembler.instruction(aarch64_store_pair_x(2, 3, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(4, 30, 31, 32)?)?;
    let core_call_offset = assembler.instruction(0x9400_0000)?;

    assembler.instruction(aarch64_cmp_w_imm(0, 0)?)?;
    assembler.branch_cond(AARCH64_EQ, no_match)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, replay)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 2)?)?;
    assembler.branch_cond(AARCH64_EQ, returned)?;
    assembler.instruction(aarch64_movz_w(0, 3)?)?;

    assembler.bind(returned)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, 40)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(no_match)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, 40)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(replay)?;
    assembler.instruction(aarch64_load_pair_x(0, 1, 31, 0)?)?;
    assembler.instruction(aarch64_load_pair_x(2, 3, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(4, 30, 31, 32)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.bind(runtime_fallback)?;
    assembler.instruction(aarch64_mov_x(5, 4)?)?;
    assembler.instruction(aarch64_mov_x(4, 3)?)?;
    assembler.instruction(aarch64_mov_x(3, 2)?)?;
    assembler.instruction(aarch64_mov_x(2, 1)?)?;
    assembler.instruction(aarch64_mov_x(1, 0)?)?;
    let program_page = assembler.instruction(0x9000_0000)?;
    let program_page_offset = assembler.instruction(0x9100_0000)?;
    let runtime_branch = assembler.instruction(0x1400_0000)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut offsets = [
        core_call_offset,
        program_page,
        program_page_offset,
        runtime_branch,
    ];
    let code = assembler.finish_with_offsets(&mut offsets)?;
    Ok(NativeEndpointOracleWrapper {
        code,
        relocations: vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(offsets[1], "AArch64 endpoint-oracle program ADRP")?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(offsets[2], "AArch64 endpoint-oracle program ADD")?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(offsets[3], "AArch64 endpoint-oracle runtime branch")?,
                kind: RelocationKind::Aarch64Branch26,
                symbol: RUNTIME_SYMBOL,
                addend: 0,
            },
        ],
        core_call_offset: offsets[0],
    })
}

fn lower_aarch64_prepared_runtime_adapter() -> (Vec<u8>, Vec<ModuleRelocation>) {
    // The exclusive helper has exactly the prepared entry's six-argument
    // AAPCS64 ABI. A tail branch preserves LR and all arguments.
    (
        0x1400_0000_u32.to_le_bytes().to_vec(),
        vec![ModuleRelocation {
            section: TEXT_SECTION,
            offset: 0,
            kind: RelocationKind::Aarch64Branch26,
            symbol: RUNTIME_ADAPTER_PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: 0,
        }],
    )
}

#[allow(
    dead_code,
    reason = "used by the retained legacy slow-partial compatibility emitter"
)]
fn patch_aarch64_local_call(
    code: &mut [u8],
    instruction_offset: usize,
    target: usize,
) -> Result<(), ObjectError> {
    let end = instruction_offset
        .checked_add(4)
        .ok_or(ObjectError::ArithmeticOverflow(
            "AArch64 local call instruction end",
        ))?;
    let slot = code
        .get_mut(instruction_offset..end)
        .ok_or(ObjectError::InvalidModule(
            "AArch64 local call is outside code",
        ))?;
    let instruction = u32::from_le_bytes([slot[0], slot[1], slot[2], slot[3]]);
    if instruction != 0x9400_0000 {
        return Err(ObjectError::InvalidModule(
            "AArch64 local call placeholder is malformed",
        ));
    }
    let words = Aarch64Assembler::fixup_words(instruction_offset, target)?;
    if !Aarch64Assembler::fixup_words_fit(words, 26)? {
        return Err(ObjectError::InvalidModule(
            "AArch64 local call is out of range",
        ));
    }
    let modulus = 1_i64 << 26;
    let immediate = u32::try_from(words.rem_euclid(modulus))
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 local call immediate"))?;
    slot.copy_from_slice(&(0x9400_0000 | immediate).to_le_bytes());
    Ok(())
}

#[allow(
    dead_code,
    clippy::too_many_lines,
    reason = "legacy public ABI checks, local outcomes, and whole-search tail deopt stay contiguous"
)]
fn lower_aarch64_slow_partial_wrapper(
    output: OutputContract,
) -> Result<NativeSlowPartialWrapper, ObjectError> {
    const FRAME_BYTES: u16 = 48;
    let mut assembler = Aarch64Assembler::new();
    let no_match = assembler.label()?;
    let matched = assembler.label()?;
    let deopt = assembler.label()?;
    let invalid = assembler.label()?;

    assembler.instruction(0xf100_003f)?; // cmp length, #0
    assembler.branch_cond(AARCH64_MI, invalid)?;
    assembler.instruction(aarch64_cmp_x(3, 1)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(aarch64_cmp_x(2, 3)?)?;
    assembler.branch_cond(AARCH64_HI, invalid)?;
    assembler.instruction(0xf100_009f)?; // result != null
    assembler.branch_cond(AARCH64_EQ, invalid)?;
    assembler.instruction(aarch64_and_low_x(5, 4, 3)?)?;
    assembler.instruction(0xf100_00bf)?; // result alignment
    assembler.branch_cond(AARCH64_NE, invalid)?;
    assembler.instruction(0xf100_001f)?; // haystack != null
    assembler.branch_cond(AARCH64_EQ, invalid)?;

    assembler.instruction(aarch64_sub_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_store_pair_x(0, 1, 31, 0)?)?;
    assembler.instruction(aarch64_store_pair_x(2, 3, 31, 16)?)?;
    assembler.instruction(aarch64_store_pair_x(4, 30, 31, 32)?)?;

    let core_call_offset = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 0)?)?;
    assembler.branch_cond(AARCH64_EQ, no_match)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, matched)?;
    assembler.branch(deopt)?;

    assembler.bind(no_match)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, 32)?)?;
    assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, 40)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(matched)?;
    assembler.instruction(aarch64_load_x_imm(5, 31, 32)?)?;
    match output {
        OutputContract::Exists => {
            assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
        }
        OutputContract::SelectedEnd => {
            assembler.instruction(aarch64_store_pair_x(7, 7, 5, 0)?)?;
        }
        OutputContract::Span => {
            assembler.instruction(aarch64_store_pair_x(6, 7, 5, 0)?)?;
        }
    }
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, 40)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(deopt)?;
    assembler.instruction(aarch64_load_pair_x(0, 1, 31, 0)?)?;
    assembler.instruction(aarch64_load_pair_x(2, 3, 31, 16)?)?;
    assembler.instruction(aarch64_load_pair_x(4, 30, 31, 32)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, FRAME_BYTES)?)?;
    assembler.instruction(aarch64_mov_x(5, 4)?)?;
    assembler.instruction(aarch64_mov_x(4, 3)?)?;
    assembler.instruction(aarch64_mov_x(3, 2)?)?;
    assembler.instruction(aarch64_mov_x(2, 1)?)?;
    assembler.instruction(aarch64_mov_x(1, 0)?)?;
    let program_page = assembler.instruction(0x9000_0000)?;
    let program_page_offset = assembler.instruction(0x9100_0000)?;
    let runtime_branch = assembler.instruction(0x1400_0000)?;

    assembler.bind(invalid)?;
    assembler.instruction(aarch64_movz_w(0, 2)?)?;
    assembler.instruction(0xd65f_03c0)?;

    let mut relocation_offsets = [
        program_page,
        program_page_offset,
        runtime_branch,
        core_call_offset,
    ];
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    Ok(NativeSlowPartialWrapper {
        code,
        relocations: vec![
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[0],
                    "AArch64 slow partial program ADRP",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[1],
                    "AArch64 slow partial program ADD",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PROGRAM_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[2],
                    "AArch64 slow partial runtime branch",
                )?,
                kind: RelocationKind::Aarch64Branch26,
                symbol: RUNTIME_SYMBOL,
                addend: 0,
            },
        ],
        core_call_offset: relocation_offsets[3],
        ticketless_core_call_offset: None,
        resume_tail_call_offset: None,
        continuation_resume_tail_call_offset: None,
    })
}

fn aarch64_emit_static_prefix_epoch_increment(
    assembler: &mut Aarch64Assembler,
    handle: u8,
    scratch: u8,
    overflow: Aarch64Label,
) -> Result<(), ObjectError> {
    let epoch_offset = u16::try_from(STATIC_PREFIX_INVOCATION_EPOCH_OFFSET)
        .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 static-prefix epoch offset"))?;
    assembler.instruction(aarch64_load_x_imm(scratch, handle, epoch_offset)?)?;
    assembler.instruction(aarch64_add_x_imm(scratch, scratch, 1)?)?;
    assembler.branch_zero_x(scratch, overflow)?;
    assembler.instruction(aarch64_store_x(scratch, handle, epoch_offset)?)?;
    Ok(())
}

fn lower_aarch64_static_prefix_prepared_wrapper(
    output: OutputContract,
    span_recovery: bool,
    resume_table_addend: Option<i64>,
    defer_preflight: bool,
    input_admission: StaticPrefixInputAdmission,
) -> Result<NativeSlowPartialWrapper, ObjectError> {
    if input_admission.short_native_max.is_some() && resume_table_addend.is_none() {
        return Err(ObjectError::InvalidModule(
            "AArch64 short static-prefix admission has no resume descriptor",
        ));
    }
    if input_admission.short_native_max.is_some_and(|maximum| {
        maximum == 0 || usize::from(maximum) >= PARTIAL_DFA_MIN_INPUT_BYTES
    }) {
        return Err(ObjectError::InvalidModule(
            "AArch64 short static-prefix admission is outside the fallback window",
        ));
    }
    // Enforce the architecture-local profitability policy at the emitter
    // boundary as well as at candidate selection, so a future caller cannot
    // accidentally restore the rejected tiny-window ARM dispatch.
    if input_admission
        .short_native_max
        .is_some_and(|maximum| usize::from(maximum) < DYNAMIC_NATIVE_ROWS_MIN_INPUT_BYTES)
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 short static-prefix admission is below the native-row floor",
        ));
    }
    let frame_bytes = if defer_preflight { 96 } else { 64 };
    let return_address_offset = if defer_preflight { 88 } else { 56 };
    // AAPCS64 supplies the first eight fused-boundary arguments in X0--X7;
    // deferred frames reserve their first three words for state, position,
    // and pending endpoint. Eager entries retain their established layout.
    let saved_handle_offset = if defer_preflight { 24 } else { 0 };
    let saved_haystack_offset = if defer_preflight { 32 } else { 8 };
    let saved_length_offset = if defer_preflight { 40 } else { 16 };
    let saved_start_offset = if defer_preflight { 48 } else { 24 };
    let saved_end_offset = if defer_preflight { 56 } else { 32 };
    let saved_result_offset = if defer_preflight { 64 } else { 40 };
    let deferred_state_offset = 0;
    let resume_position_offset = if defer_preflight { 8 } else { 48 };
    let deferred_pending_offset = 16;
    let eager_ticketless = !defer_preflight && input_admission.short_native_max.is_some();
    let inline_authenticated_entry = defer_preflight || eager_ticketless;
    let load_offset = |offset: i16| {
        u16::try_from(offset)
            .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 static-prefix frame offset"))
    };
    let mut assembler = Aarch64Assembler::new();
    let preflight_enter = assembler.label()?;
    let native_match = assembler.label()?;
    let native_no_match = assembler.label()?;
    let native_resume = resume_table_addend.map(|_| assembler.label()).transpose()?;
    let native_span_recovery = span_recovery.then(|| assembler.label()).transpose()?;
    let native_deopt = assembler.label()?;
    let fallback_runtime = assembler.label()?;
    let deferred_short_native_max = defer_preflight
        .then_some(input_admission.short_native_max)
        .flatten();
    let short_window_check = deferred_short_native_max
        .map(|_| assembler.label())
        .transpose()?;
    let short_native_entry = deferred_short_native_max
        .map(|_| assembler.label())
        .transpose()?;
    let ticketless_entry = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_match = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_no_match = eager_ticketless.then(|| assembler.label()).transpose()?;
    let ticketless_deopt = eager_ticketless.then(|| assembler.label()).transpose()?;
    let invalid_handle = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let invalid_argument = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let wrong_identity = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let entry_epoch_overflow = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let guard_retire = inline_authenticated_entry
        .then(|| assembler.label())
        .transpose()?;
    let direct_epoch_overflow = (!defer_preflight).then(|| assembler.label()).transpose()?;
    let resume_epoch_overflow = resume_table_addend
        .map(|_| assembler.label())
        .transpose()?;
    let mut retire_branches = Vec::new();

    if defer_preflight {
        let (Some(invalid_handle), Some(invalid_argument)) =
            (invalid_handle, invalid_argument)
        else {
            return Err(ObjectError::InvalidModule(
                "AArch64 deferred static-prefix guards are absent",
            ));
        };
        // Check every raw scalar before the first header or haystack load.
        // The non-null handle retains the private ABI's documented live-owner
        // premise; null has its distinct stable status.
        assembler.branch_zero_x(0, invalid_handle)?;
        assembler.branch_zero_x(1, invalid_argument)?;
        assembler.branch_bit_set_x(2, 63, invalid_argument)?;
        assembler.instruction(aarch64_cmp_x(4, 2)?)?;
        assembler.branch_cond(AARCH64_HI, invalid_argument)?;
        assembler.instruction(aarch64_cmp_x(3, 4)?)?;
        assembler.branch_cond(AARCH64_HI, invalid_argument)?;
        assembler.branch_zero_x(5, invalid_argument)?;
        assembler.instruction(aarch64_and_low_x(6, 5, 3)?)?;
        assembler.branch_nonzero_x(6, invalid_argument)?;
    }

    let deferred_identity_relocations = if defer_preflight {
        let wrong_identity = wrong_identity.ok_or(ObjectError::InvalidModule(
            "AArch64 deferred static-prefix identity guard is absent",
        ))?;
        // The offset-zero V6 identity remains immutable when mutable runtime
        // work revokes the compact active seal. Do not couple retained-prefix
        // reuse to that unrelated seal lifecycle.
        let page = assembler.instruction(0x9000_0006)?;
        let page_offset = assembler.instruction(aarch64_add_x_imm(6, 6, 0)?)?;
        for identity_word in 0_usize..4 {
            let word_offset = identity_word
                .checked_mul(core::mem::size_of::<u64>())
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 deferred static-prefix identity word",
                ))?;
            assembler.instruction(aarch64_load_x_imm(
                8,
                6,
                u16::try_from(word_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "AArch64 deferred static-prefix linked identity offset",
                    )
                })?,
            )?)?;
            let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(word_offset)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 deferred static-prefix header identity offset",
                ))?;
            assembler.instruction(aarch64_load_x_imm(
                9,
                0,
                u16::try_from(header_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "AArch64 deferred static-prefix header identity displacement",
                    )
                })?,
            )?)?;
            assembler.instruction(aarch64_cmp_x(9, 8)?)?;
            assembler.branch_cond(AARCH64_NE, wrong_identity)?;
        }
        Some((page, page_offset))
    } else {
        None
    };

    if defer_preflight {
        // Authenticate the immutable owner before the first mutable access,
        // then invalidate every capability minted by an older invocation.
        aarch64_emit_static_prefix_epoch_increment(
            &mut assembler,
            0,
            8,
            entry_epoch_overflow.ok_or(ObjectError::InvalidModule(
                "AArch64 deferred static-prefix epoch guard is absent",
            ))?,
        )?;
    }

    // X6 is caller-saved and all six public arguments remain untouched for an
    // unproved short-window tail fallback. A proved short window returns from
    // the cold check to the unchanged native entry. Authentication and
    // generation retirement deliberately precede both paths.
    let window_register = if defer_preflight { 10 } else { 6 };
    assembler.instruction(aarch64_sub_x_reg(window_register, 4, 3)?)?;
    let minimum = u16::try_from(PARTIAL_DFA_MIN_INPUT_BYTES)
        .map_err(|_| ObjectError::ArithmeticOverflow("static-prefix input admission floor"))?;
    assembler.instruction(aarch64_cmp_x_imm(window_register, minimum)?)?;
    assembler.branch_cond(
        AARCH64_LO,
        if defer_preflight {
            short_window_check.unwrap_or(fallback_runtime)
        } else {
            ticketless_entry.unwrap_or(fallback_runtime)
        },
    )?;
    if let Some(short_native_entry) = short_native_entry {
        assembler.bind(short_native_entry)?;
    }

    assembler.instruction(aarch64_sub_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(aarch64_store_pair_x(
        0,
        1,
        31,
        saved_handle_offset,
    )?)?;
    assembler.instruction(aarch64_store_pair_x(
        2,
        3,
        31,
        saved_length_offset,
    )?)?;
    assembler.instruction(aarch64_store_pair_x(
        4,
        5,
        31,
        saved_end_offset,
    )?)?;
    assembler.instruction(aarch64_store_x(30, 31, return_address_offset)?)?;
    let (identity_page, identity_page_offset) = if let Some(relocations) =
        deferred_identity_relocations
    {
        assembler.instruction(aarch64_store_x(6, 31, 72)?)?;
        relocations
    } else {
        (
            assembler.instruction(0x9000_0006)?,
            assembler.instruction(aarch64_add_x_imm(6, 6, 0)?)?,
        )
    };
    let resume_descriptor_relocations = if resume_table_addend.is_some() {
        let relocations = (
            assembler.instruction(0x9000_0007)?,
            assembler.instruction(aarch64_add_x_imm(7, 7, 0)?)?,
        );
        if defer_preflight {
            assembler.instruction(aarch64_store_x(7, 31, 80)?)?;
        }
        Some(relocations)
    } else {
        None
    };
    let eager_preflight_branch = if defer_preflight {
        None
    } else {
        let branch = assembler.instruction(0x9400_0000)?;
        assembler.instruction(aarch64_cmp_w_imm(
            0,
            u16::from(PARTIAL_PREFLIGHT_ENTER_STATUS),
        )?)?;
        assembler.branch_cond(AARCH64_EQ, preflight_enter)?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;
        Some(branch)
    };

    assembler.bind(preflight_enter)?;
    assembler.instruction(aarch64_load_pair_x(
        0,
        1,
        31,
        saved_haystack_offset,
    )?)?;
    assembler.instruction(aarch64_load_pair_x(
        2,
        3,
        31,
        saved_start_offset,
    )?)?;
    let core_call_offset = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
    assembler.branch_cond(AARCH64_EQ, native_match)?;
    assembler.instruction(aarch64_cmp_w_imm(0, 0)?)?;
    assembler.branch_cond(AARCH64_EQ, native_no_match)?;
    if let Some(native_resume) = native_resume {
        assembler.instruction(aarch64_cmp_w_imm(
            0,
            u16::try_from(NATIVE_PARTIAL_STATUS_RESUME).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 static-prefix resume status")
            })?,
        )?)?;
        assembler.branch_cond(AARCH64_EQ, native_resume)?;
    }
    if let Some(native_span_recovery) = native_span_recovery {
        assembler.instruction(aarch64_cmp_w_imm(
            0,
            u16::try_from(NATIVE_PARTIAL_STATUS_SELECTED_END).map_err(|_| {
                ObjectError::ArithmeticOverflow("AArch64 static-prefix Span recovery status")
            })?,
        )?)?;
        assembler.branch_cond(AARCH64_EQ, native_span_recovery)?;
    }
    assembler.branch(native_deopt)?;

    assembler.bind(native_no_match)?;
    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        // Eager V2 admission minted a capability. Invalidate it before any
        // caller result store; X6/X7 remain available for match endpoints.
        assembler.instruction(aarch64_load_x_imm(
            0,
            31,
            load_offset(saved_handle_offset)?,
        )?)?;
        aarch64_emit_static_prefix_epoch_increment(
            &mut assembler,
            0,
            8,
            direct_epoch_overflow,
        )?;
    }
    assembler.instruction(aarch64_load_x_imm(5, 31, saved_result_offset)?)?;
    assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
    assembler.instruction(aarch64_movz_w(0, 0)?)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;

    assembler.bind(native_match)?;
    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        assembler.instruction(aarch64_load_x_imm(
            0,
            31,
            load_offset(saved_handle_offset)?,
        )?)?;
        aarch64_emit_static_prefix_epoch_increment(
            &mut assembler,
            0,
            8,
            direct_epoch_overflow,
        )?;
    }
    assembler.instruction(aarch64_load_x_imm(5, 31, saved_result_offset)?)?;
    match output {
        OutputContract::Exists => {
            assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
        }
        OutputContract::SelectedEnd => {
            assembler.instruction(aarch64_store_pair_x(7, 7, 5, 0)?)?;
        }
        OutputContract::Span => {
            assembler.instruction(aarch64_store_pair_x(6, 7, 5, 0)?)?;
        }
    }
    assembler.instruction(aarch64_movz_w(0, 1)?)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;

    if let Some(direct_epoch_overflow) = direct_epoch_overflow {
        assembler.bind(direct_epoch_overflow)?;
        assembler.instruction(aarch64_movz_w(
            1,
            u16::from(PREPARED_RUNTIME_FAILURE_STATUS),
        )?)?;
        retire_branches.push(assembler.instruction(0x9400_0000)?);
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;
    }

    let span_recovery_relocations = if let Some(native_span_recovery) = native_span_recovery {
        assembler.bind(native_span_recovery)?;
        assembler.instruction(aarch64_load_pair_x(0, 1, 31, saved_handle_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(2, 3, 31, saved_length_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(4, 5, 31, saved_end_offset)?)?;
        let identity_page = assembler.instruction(0x9000_0006)?;
        let identity_page_offset = assembler.instruction(aarch64_add_x_imm(6, 6, 0)?)?;
        if defer_preflight {
            assembler.instruction(aarch64_load_x_imm(
                8,
                0,
                u16::try_from(STATIC_PREFIX_INVOCATION_EPOCH_OFFSET).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "AArch64 lazy static-prefix Span epoch offset",
                    )
                })?,
            )?)?;
            assembler.instruction(aarch64_store_x(8, 31, 0)?)?;
        }
        let runtime_branch = assembler.instruction(0x9400_0000)?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;
        Some((identity_page, identity_page_offset, runtime_branch))
    } else {
        None
    };

    let mut resume_tail_call = None;
    let mut continuation_resume_tail_call = None;
    let resume_runtime_branch = if let Some(native_resume) = native_resume {
        assembler.bind(native_resume)?;
        let resume_return = assembler.label()?;
        if defer_preflight {
            // X0--X7 carry handle, haystack, length, window, result,
            // identity, and descriptor. The three native frontier words are
            // the aligned stack arguments consumed by fused V2 continuation.
            assembler.instruction(aarch64_store_x(
                6,
                31,
                deferred_state_offset,
            )?)?;
            assembler.instruction(aarch64_store_x(
                2,
                31,
                resume_position_offset,
            )?)?;
            assembler.instruction(aarch64_store_x(
                7,
                31,
                deferred_pending_offset,
            )?)?;
            assembler.instruction(aarch64_load_pair_x(
                0,
                1,
                31,
                saved_handle_offset,
            )?)?;
            assembler.instruction(aarch64_load_pair_x(
                2,
                3,
                31,
                saved_length_offset,
            )?)?;
            assembler.instruction(aarch64_load_pair_x(
                4,
                5,
                31,
                saved_end_offset,
            )?)?;
            assembler.instruction(aarch64_load_pair_x(6, 7, 31, 72)?)?;
        } else {
            assembler.instruction(aarch64_mov_x(5, 2)?)?;
            assembler.instruction(aarch64_store_x(5, 31, resume_position_offset)?)?;
            assembler.instruction(aarch64_mov_x(4, 6)?)?;
            assembler.instruction(aarch64_mov_x(6, 7)?)?;
            assembler.instruction(aarch64_load_pair_x(
                0,
                1,
                31,
                saved_handle_offset,
            )?)?;
            assembler.instruction(aarch64_load_x_imm(
                2,
                31,
                load_offset(saved_length_offset)?,
            )?)?;
            assembler.instruction(aarch64_load_x_imm(3, 31, saved_result_offset)?)?;
        }
        let branch = assembler.instruction(0x9400_0000)?;
        let continuation_resume = assembler.label()?;
        assembler.instruction(aarch64_cmp_w_imm(
            0,
            u16::from(STATIC_PREFIX_NATIVE_CONTINUATION_RESUME_STATUS),
        )?)?;
        assembler.branch_cond(AARCH64_EQ, continuation_resume)?;
        assembler.instruction(aarch64_cmp_w_imm(
            0,
            u16::from(STATIC_PREFIX_NATIVE_RESUME_STATUS),
        )?)?;
        assembler.branch_cond(AARCH64_NE, resume_return)?;
        // Rebuild the prepared ABI and carry the authenticated continuation
        // in X8 (cursor), X6 (canonical state), and X7 (pending endpoint).
        assembler.instruction(aarch64_load_pair_x(0, 1, 31, saved_handle_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(2, 3, 31, saved_length_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(4, 5, 31, saved_end_offset)?)?;
        assembler.instruction(aarch64_load_x_imm(8, 31, resume_position_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(6, 7, 5, 0)?)?;
        resume_tail_call = Some(assembler.instruction(0x9400_0000)?);
        assembler.branch(resume_return)?;

        assembler.bind(continuation_resume)?;
        // Status 8 enters with the original allocation base in X0. The continuation
        // side entry saves it before selecting the fixed +664 header.
        assembler.instruction(aarch64_load_pair_x(0, 1, 31, saved_handle_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(2, 3, 31, saved_length_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(4, 5, 31, saved_end_offset)?)?;
        assembler.instruction(aarch64_load_x_imm(8, 31, resume_position_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(6, 7, 5, 0)?)?;
        continuation_resume_tail_call = Some(assembler.instruction(0x9400_0000)?);
        assembler.bind(resume_return)?;
        assembler.instruction(aarch64_load_x_imm(
            9,
            31,
            load_offset(saved_handle_offset)?,
        )?)?;
        aarch64_emit_static_prefix_epoch_increment(
            &mut assembler,
            9,
            8,
            resume_epoch_overflow.ok_or(ObjectError::InvalidModule(
                "AArch64 static-prefix resume epoch overflow label is absent",
            ))?,
        )?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;
        assembler.bind(resume_epoch_overflow.ok_or(ObjectError::InvalidModule(
            "AArch64 static-prefix resume epoch overflow label is absent",
        ))?)?;
        assembler.instruction(aarch64_mov_x(1, 0)?)?;
        assembler.instruction(aarch64_mov_x(0, 9)?)?;
        retire_branches.push(assembler.instruction(0x9400_0000)?);
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;
        Some(branch)
    } else {
        None
    };

    assembler.bind(native_deopt)?;
    assembler.instruction(aarch64_load_pair_x(0, 1, 31, saved_handle_offset)?)?;
    assembler.instruction(aarch64_load_pair_x(2, 3, 31, saved_length_offset)?)?;
    assembler.instruction(aarch64_load_pair_x(4, 5, 31, saved_end_offset)?)?;
    let deopt_branch = assembler.instruction(0x9400_0000)?;
    assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
    assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
    assembler.instruction(0xd65f_03c0)?;

    if let Some(invalid_handle) = invalid_handle {
        assembler.bind(invalid_handle)?;
        assembler.instruction(aarch64_movz_w(
            0,
            u16::from(PREPARED_INVALID_HANDLE_STATUS),
        )?)?;
        assembler.instruction(0xd65f_03c0)?;
    }
    if let Some(invalid_argument) = invalid_argument {
        assembler.bind(invalid_argument)?;
        assembler.instruction(aarch64_movz_w(
            1,
            u16::from(PREPARED_INVALID_ARGUMENT_STATUS),
        )?)?;
        assembler.branch(guard_retire.ok_or(ObjectError::InvalidModule(
            "AArch64 static-prefix guard retirement label is absent",
        ))?)?;
    }
    if let Some(wrong_identity) = wrong_identity {
        assembler.bind(wrong_identity)?;
        assembler.instruction(aarch64_movz_w(
            1,
            u16::from(PREPARED_RUNTIME_FAILURE_STATUS),
        )?)?;
        assembler.branch(guard_retire.ok_or(ObjectError::InvalidModule(
            "AArch64 static-prefix guard retirement label is absent",
        ))?)?;
    }
    if let Some(entry_epoch_overflow) = entry_epoch_overflow {
        assembler.bind(entry_epoch_overflow)?;
        assembler.instruction(aarch64_movz_w(
            1,
            u16::from(PREPARED_RUNTIME_FAILURE_STATUS),
        )?)?;
        assembler.branch(guard_retire.ok_or(ObjectError::InvalidModule(
            "AArch64 static-prefix guard retirement label is absent",
        ))?)?;
    }
    if let Some(guard_retire) = guard_retire {
        assembler.bind(guard_retire)?;
        retire_branches.push(assembler.instruction(0x1400_0000)?);
    }

    assembler.bind(fallback_runtime)?;
    let fallback_branch = assembler.instruction(0x1400_0000)?;
    if let (Some(short_window_check), Some(short_native_entry), Some(short_native_max)) = (
        short_window_check,
        short_native_entry,
        deferred_short_native_max,
    ) {
        assembler.bind(short_window_check)?;
        assembler.instruction(aarch64_cmp_x_imm(window_register, short_native_max)?)?;
        assembler.branch_cond(AARCH64_LS, short_native_entry)?; // len <= h
        assembler.branch(fallback_runtime)?;
    }

    let (ticketless_identity_relocations, ticketless_core_call) = if let (
        Some(ticketless_entry),
        Some(ticketless_match),
        Some(ticketless_no_match),
        Some(ticketless_deopt),
        Some(short_native_max),
        Some(invalid_handle),
        Some(invalid_argument),
        Some(wrong_identity),
        Some(entry_epoch_overflow),
    ) = (
        ticketless_entry,
        ticketless_match,
        ticketless_no_match,
        ticketless_deopt,
        input_admission.short_native_max,
        invalid_handle,
        invalid_argument,
        wrong_identity,
        entry_epoch_overflow,
    ) {
        assembler.bind(ticketless_entry)?;
        // The eager long route above remains the established preflight path.
        // Only its cold sub-crossover edge validates and authenticates inline.
        assembler.branch_zero_x(0, invalid_handle)?;
        assembler.branch_zero_x(1, invalid_argument)?;
        assembler.branch_bit_set_x(2, 63, invalid_argument)?;
        assembler.instruction(aarch64_cmp_x(4, 2)?)?;
        assembler.branch_cond(AARCH64_HI, invalid_argument)?;
        assembler.instruction(aarch64_cmp_x(3, 4)?)?;
        assembler.branch_cond(AARCH64_HI, invalid_argument)?;
        assembler.branch_zero_x(5, invalid_argument)?;
        assembler.instruction(aarch64_and_low_x(6, 5, 3)?)?;
        assembler.branch_nonzero_x(6, invalid_argument)?;

        let identity_page = assembler.instruction(0x9000_0006)?;
        let identity_page_offset = assembler.instruction(aarch64_add_x_imm(6, 6, 0)?)?;
        for identity_word in 0_usize..4 {
            let word_offset = identity_word
                .checked_mul(core::mem::size_of::<u64>())
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 ticketless static-prefix identity word",
                ))?;
            assembler.instruction(aarch64_load_x_imm(
                8,
                6,
                u16::try_from(word_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "AArch64 ticketless static-prefix linked identity offset",
                    )
                })?,
            )?)?;
            let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(word_offset)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 ticketless static-prefix header identity offset",
                ))?;
            assembler.instruction(aarch64_load_x_imm(
                9,
                0,
                u16::try_from(header_offset).map_err(|_| {
                    ObjectError::ArithmeticOverflow(
                        "AArch64 ticketless static-prefix header identity displacement",
                    )
                })?,
            )?)?;
            assembler.instruction(aarch64_cmp_x(9, 8)?)?;
            assembler.branch_cond(AARCH64_NE, wrong_identity)?;
        }
        aarch64_emit_static_prefix_epoch_increment(
            &mut assembler,
            0,
            8,
            entry_epoch_overflow,
        )?;
        assembler.instruction(aarch64_sub_x_reg(10, 4, 3)?)?;
        assembler.instruction(aarch64_cmp_x_imm(10, short_native_max)?)?;
        assembler.branch_cond(AARCH64_HI, fallback_runtime)?;

        // This lane mints no descriptor ticket. Its frame exists only across
        // the selected target-native core call and direct result publication.
        assembler.instruction(aarch64_sub_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(aarch64_store_pair_x(
            0,
            1,
            31,
            saved_handle_offset,
        )?)?;
        assembler.instruction(aarch64_store_pair_x(
            2,
            3,
            31,
            saved_length_offset,
        )?)?;
        assembler.instruction(aarch64_store_pair_x(4, 5, 31, saved_end_offset)?)?;
        assembler.instruction(aarch64_store_x(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(
            0,
            1,
            31,
            saved_haystack_offset,
        )?)?;
        assembler.instruction(aarch64_load_pair_x(
            2,
            3,
            31,
            saved_start_offset,
        )?)?;
        let core_call = assembler.instruction(0x9400_0000)?;
        assembler.instruction(aarch64_cmp_w_imm(0, 1)?)?;
        assembler.branch_cond(AARCH64_EQ, ticketless_match)?;
        assembler.instruction(aarch64_cmp_w_imm(0, 0)?)?;
        assembler.branch_cond(AARCH64_EQ, ticketless_no_match)?;
        // Status 3, status 4, and every unknown status side-exit without ever
        // entering continuation or variable-Span recovery.
        assembler.branch(ticketless_deopt)?;

        assembler.bind(ticketless_no_match)?;
        assembler.instruction(aarch64_load_x_imm(5, 31, saved_result_offset)?)?;
        assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
        assembler.instruction(aarch64_movz_w(0, 0)?)?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;

        assembler.bind(ticketless_match)?;
        assembler.instruction(aarch64_load_x_imm(5, 31, saved_result_offset)?)?;
        match output {
            OutputContract::Exists => {
                assembler.instruction(aarch64_store_pair_x(31, 31, 5, 0)?)?;
            }
            OutputContract::SelectedEnd => {
                assembler.instruction(aarch64_store_pair_x(7, 7, 5, 0)?)?;
            }
            OutputContract::Span => {
                assembler.instruction(aarch64_store_pair_x(6, 7, 5, 0)?)?;
            }
        }
        assembler.instruction(aarch64_movz_w(0, 1)?)?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.instruction(0xd65f_03c0)?;

        assembler.bind(ticketless_deopt)?;
        assembler.instruction(aarch64_load_pair_x(0, 1, 31, saved_handle_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(2, 3, 31, saved_length_offset)?)?;
        assembler.instruction(aarch64_load_pair_x(4, 5, 31, saved_end_offset)?)?;
        assembler.instruction(aarch64_load_x_imm(30, 31, return_address_offset)?)?;
        assembler.instruction(aarch64_add_x_imm(31, 31, frame_bytes)?)?;
        assembler.branch(fallback_runtime)?;
        (Some((identity_page, identity_page_offset)), Some(core_call))
    } else {
        (None, None)
    };

    let mut relocation_offsets = vec![
        identity_page,
        identity_page_offset,
        core_call_offset,
        deopt_branch,
        fallback_branch,
    ];
    let ticketless_core_index = ticketless_core_call.map(|core_call| {
        let index = relocation_offsets.len();
        relocation_offsets.push(core_call);
        index
    });
    let ticketless_identity_indices =
        ticketless_identity_relocations.map(|(identity_page, identity_page_offset)| {
            let first = relocation_offsets.len();
            relocation_offsets.extend([identity_page, identity_page_offset]);
            (first, first + 1)
        });
    let preflight_index = eager_preflight_branch.map(|branch| {
            let index = relocation_offsets.len();
            relocation_offsets.push(branch);
            index
        });
    let resume_indices = match (
        resume_descriptor_relocations,
        resume_runtime_branch,
        resume_table_addend,
    ) {
        (Some((descriptor_page, descriptor_page_offset)), Some(runtime_branch), Some(_)) => {
            let first = relocation_offsets.len();
            relocation_offsets.extend([descriptor_page, descriptor_page_offset, runtime_branch]);
            Some((first, first + 1, first + 2))
        }
        (None, None, None) => None,
        _ => {
            return Err(ObjectError::InvalidModule(
                "AArch64 static-prefix resume lowering is incomplete",
            ));
        }
    };
    let span_recovery_indices = span_recovery_relocations.map(
        |(identity_page, identity_page_offset, runtime_branch)| {
            let first = relocation_offsets.len();
            relocation_offsets.extend([identity_page, identity_page_offset, runtime_branch]);
            (first, first + 1, first + 2)
        },
    );
    let resume_tail_index = resume_tail_call.map(|tail_call| {
        let index = relocation_offsets.len();
        relocation_offsets.push(tail_call);
        index
    });
    let continuation_resume_tail_index = continuation_resume_tail_call.map(|tail_call| {
        let index = relocation_offsets.len();
        relocation_offsets.push(tail_call);
        index
    });
    let retire_indices = retire_branches
        .into_iter()
        .map(|branch| {
            let index = relocation_offsets.len();
            relocation_offsets.push(branch);
            index
        })
        .collect::<Vec<_>>();
    let code = assembler.finish_with_offsets(&mut relocation_offsets)?;
    let mut relocations = vec![
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(relocation_offsets[0], "AArch64 static-prefix identity ADRP")?,
            kind: RelocationKind::Aarch64Page21,
            symbol: PARTIAL_IDENTITY_SYMBOL,
            addend: 0,
        },
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(relocation_offsets[1], "AArch64 static-prefix identity ADD")?,
            kind: RelocationKind::Aarch64PageOff12,
            symbol: PARTIAL_IDENTITY_SYMBOL,
            addend: 0,
        },
    ];
    if let Some((identity_page, identity_page_offset)) = ticketless_identity_indices {
        relocations.extend([
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[identity_page],
                    "AArch64 ticketless static-prefix identity ADRP",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PARTIAL_IDENTITY_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[identity_page_offset],
                    "AArch64 ticketless static-prefix identity ADD",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PARTIAL_IDENTITY_SYMBOL,
                addend: 0,
            },
        ]);
    }
    if let Some(preflight_index) = preflight_index {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                relocation_offsets[preflight_index],
                "AArch64 static-prefix preflight branch",
            )?,
            kind: RelocationKind::Aarch64Branch26,
            symbol: PREPARED_PREFLIGHT_RUNTIME_SYMBOL,
            addend: 0,
        });
    }
    relocations.extend([
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(relocation_offsets[3], "AArch64 static-prefix deopt branch")?,
            kind: RelocationKind::Aarch64Branch26,
            symbol: PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: 0,
        },
        ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(relocation_offsets[4], "AArch64 static-prefix fallback branch")?,
            kind: RelocationKind::Aarch64Branch26,
            symbol: PREPARED_FALLBACK_RUNTIME_SYMBOL,
            addend: 0,
        },
    ]);
    if let (Some((descriptor_page, descriptor_page_offset, runtime_branch)), Some(table_addend)) =
        (resume_indices, resume_table_addend)
    {
        relocations.extend([
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[descriptor_page],
                    "AArch64 static-prefix resume descriptor ADRP",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PARTIAL_TABLE_SYMBOL,
                addend: table_addend,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[descriptor_page_offset],
                    "AArch64 static-prefix resume descriptor ADD",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PARTIAL_TABLE_SYMBOL,
                addend: table_addend,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[runtime_branch],
                    "AArch64 static-prefix continuation branch",
                )?,
                kind: RelocationKind::Aarch64Branch26,
                symbol: PARTIAL_RUNTIME_SYMBOL,
                addend: 0,
            },
        ]);
    }
    if let Some((identity_page, identity_page_offset, runtime_branch)) = span_recovery_indices {
        relocations.extend([
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[identity_page],
                    "AArch64 static-prefix Span identity ADRP",
                )?,
                kind: RelocationKind::Aarch64Page21,
                symbol: PARTIAL_IDENTITY_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[identity_page_offset],
                    "AArch64 static-prefix Span identity ADD",
                )?,
                kind: RelocationKind::Aarch64PageOff12,
                symbol: PARTIAL_IDENTITY_SYMBOL,
                addend: 0,
            },
            ModuleRelocation {
                section: TEXT_SECTION,
                offset: offset_u64(
                    relocation_offsets[runtime_branch],
                    "AArch64 static-prefix Span recovery branch",
                )?,
                kind: RelocationKind::Aarch64Branch26,
                symbol: if defer_preflight {
                    STATIC_PREFIX_LAZY_SPAN_RECOVERY_RUNTIME_SYMBOL
                } else {
                    PARTIAL_SPAN_RECOVERY_RUNTIME_SYMBOL
                },
                addend: 0,
            },
        ]);
    }
    for retire_index in retire_indices {
        relocations.push(ModuleRelocation {
            section: TEXT_SECTION,
            offset: offset_u64(
                relocation_offsets[retire_index],
                "AArch64 static-prefix retirement branch",
            )?,
            kind: RelocationKind::Aarch64Branch26,
            symbol: STATIC_PREFIX_RETIRE_RUNTIME_SYMBOL,
            addend: 0,
        });
    }
    Ok(NativeSlowPartialWrapper {
        code,
        relocations,
        core_call_offset: relocation_offsets[2],
        ticketless_core_call_offset: ticketless_core_index
            .map(|index| relocation_offsets[index]),
        resume_tail_call_offset: resume_tail_index.map(|index| relocation_offsets[index]),
        continuation_resume_tail_call_offset: continuation_resume_tail_index
            .map(|index| relocation_offsets[index]),
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "compact capabilities and full verifiers share one explicit fail-closed target lowering"
)]
fn aarch64_emit_frozen_compact_entry(
    assembler: &mut Aarch64Assembler,
    format: FrozenCompactNativeFormat,
    try_older: Aarch64Label,
    call_preflight: Aarch64Label,
    compact_enter: Aarch64Label,
    guard_mode: FrozenCompactGuardMode,
) -> Result<(), ObjectError> {
    let offset = |value: usize, context| {
        u16::try_from(value).map_err(|_| ObjectError::ArithmeticOverflow(context))
    };
    if guard_mode
        .variable_span_source_class_count()
        .is_some_and(|count| !(1..=256).contains(&count))
    {
        return Err(ObjectError::InvalidModule(
            "AArch64 compact reverse verifier has an invalid source class count",
        ));
    }

    // The tail layouts overlap, so select the format solely through its
    // distinct V1 flag. Other generations branch to the older validator
    // before this format's extent or tail fields are consumed.
    assembler.instruction(aarch64_load_w_imm(
        8,
        0,
        offset(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET, "AArch64 V3 flags")?,
    )?)?;
    aarch64_load_u32_constant(
        assembler,
        9,
        if guard_mode.expects_reverse_supertransition() {
            format.flag() | FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION
        } else {
            format.flag()
        },
    )?;
    assembler.instruction(aarch64_cmp_w(8, 9)?)?;
    if guard_mode.expects_reverse_supertransition() {
        let accepted_flags = assembler.label()?;
        assembler.branch_cond(AARCH64_EQ, accepted_flags)?;
        aarch64_load_u32_constant(
            assembler,
            9,
            format.flag(),
        )?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, try_older)?;
        assembler.bind(accepted_flags)?;
    } else {
        assembler.branch_cond(AARCH64_NE, try_older)?;
    }

    // Every live exclusive handle owns the maximum V6 envelope. The active
    // seal authenticates its immutable setup proof; only the audit path needs
    // to re-read the smaller format's logical extent and descriptor mirrors.
    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_x_imm(
            8,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET,
                "AArch64 V3 header extent offset",
            )?,
        )?)?;
        aarch64_load_u64_constant(
            assembler,
            9,
            u64::try_from(format.header_bytes())
                .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 compact header extent"))?,
        )?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
    }

    assembler.instruction(aarch64_load_x_imm(
        8,
        0,
        offset(
            FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL_OFFSET,
            "AArch64 V3 active seal",
        )?,
    )?)?;
    aarch64_load_u64_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL)?;
    assembler.instruction(aarch64_cmp_x(8, 9)?)?;
    assembler.branch_cond(AARCH64_NE, call_preflight)?;

    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_x_imm(
            8,
            0,
            offset(FROZEN_PREPARED_HEADER_V1_MAGIC_OFFSET, "AArch64 V3 magic")?,
        )?)?;
        aarch64_load_u64_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_MAGIC)?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;

        assembler.instruction(aarch64_load_w_imm(
            8,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_ABI_VERSION_OFFSET,
                "AArch64 V3 ABI version",
            )?,
        )?)?;
        aarch64_load_u32_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_ABI_VERSION)?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
    }

    // The scalar capability and full verifier remain valid for portable
    // targets. An explicitly ASIMD-capable target loads both unaligned halves,
    // OR-reduces their exact bytewise XOR, and branches once. V16..V19 are
    // caller-saved and no scanner constants are live at this entry.
    if guard_mode.uses_simd_identity() {
        let header = offset(
            FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET,
            "AArch64 compact SIMD identity offset",
        )?;
        assembler.instruction(aarch64_load_pair_q(16, 17, 6, 0)?)?;
        assembler.instruction(aarch64_load_pair_q(18, 19, 0, header)?)?;
        assembler.instruction(aarch64_eor_16b(16, 16, 18)?)?;
        assembler.instruction(aarch64_eor_16b(17, 17, 19)?)?;
        assembler.instruction(aarch64_orr_16b(16, 16, 17)?)?;
        assembler.instruction(aarch64_umaxv_16b(16, 16)?)?;
        assembler.instruction(aarch64_umov_b0(8, 16)?)?;
        assembler.branch_nonzero_w(8, call_preflight)?;
    } else {
        // Compare all four u64 words; the linked identity address in X6 is not
        // repurposed until the exact 256-bit comparison is complete.
        for identity_word in 0_usize..4 {
            let word_offset = identity_word
                .checked_mul(core::mem::size_of::<u64>())
                .ok_or(ObjectError::ArithmeticOverflow("AArch64 V3 identity word"))?;
            assembler.instruction(aarch64_load_x_imm(
                8,
                6,
                offset(word_offset, "AArch64 V3 linked identity word")?,
            )?)?;
            let header_offset = FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET
                .checked_add(word_offset)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "AArch64 V3 header identity word",
                ))?;
            assembler.instruction(aarch64_load_x_imm(
                9,
                0,
                offset(header_offset, "AArch64 V3 header identity word")?,
            )?)?;
            assembler.instruction(aarch64_cmp_x(8, 9)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }
    }

    if let Some(source_class_count) = guard_mode.variable_span_source_class_count() {
        assembler.instruction(aarch64_load_x_imm(
            8,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET,
                "AArch64 V3 reverse rows",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_x_imm(8, 0)?)?;
        assembler.branch_cond(AARCH64_EQ, call_preflight)?;
        assembler.instruction(aarch64_and_low_x(9, 8, 2)?)?;
        assembler.instruction(aarch64_cmp_x_imm(9, 0)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;

        assembler.instruction(aarch64_load_x_imm(
            8,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET,
                "AArch64 V3 reverse live cells",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_x_imm(8, source_class_count)?)?;
        assembler.branch_cond(AARCH64_LO, call_preflight)?;
        aarch64_load_u64_constant(
            assembler,
            9,
            u64::from(DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK),
        )?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_HI, call_preflight)?;
        assembler.instruction(aarch64_movz_x(10, source_class_count, 0)?)?;
        assembler.instruction(aarch64_udiv_x(9, 8, 10)?)?;
        assembler.instruction(aarch64_msub_x(9, 9, 10, 8)?)?;
        assembler.instruction(aarch64_cmp_x_imm(9, 0)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;

        assembler.instruction(aarch64_load_w_imm(
            11,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_REVERSE_INITIAL_ROW_OFFSET,
                "AArch64 V3 reverse initial row",
            )?,
        )?)?;
        aarch64_load_u32_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW)?;
        assembler.instruction(aarch64_cmp_w(11, 9)?)?;
        assembler.branch_cond(AARCH64_EQ, call_preflight)?;
        assembler.instruction(aarch64_udiv_x(9, 11, 10)?)?;
        assembler.instruction(aarch64_msub_x(9, 9, 10, 11)?)?;
        assembler.instruction(aarch64_cmp_x_imm(9, 0)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
        assembler.instruction(aarch64_add_x_reg(11, 11, 10)?)?;
        assembler.instruction(aarch64_cmp_x(11, 8)?)?;
        assembler.branch_cond(AARCH64_HI, call_preflight)?;
    } else if guard_mode.is_full_verifier() {
        for (field, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET,
                "AArch64 V3 reverse rows",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET,
                "AArch64 V3 reverse live cells",
            ),
        ] {
            assembler.instruction(aarch64_load_x_imm(8, 0, offset(field, context)?)?)?;
            assembler.instruction(aarch64_cmp_x_imm(8, 0)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }
        assembler.instruction(aarch64_load_w_imm(
            8,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_REVERSE_INITIAL_ROW_OFFSET,
                "AArch64 V3 reverse initial row",
            )?,
        )?)?;
        aarch64_load_u32_constant(assembler, 9, FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW)?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
    }

    assembler.instruction(aarch64_add_x_imm(
        13,
        0,
        offset(
            format.tail_offset(),
            "AArch64 compact tail offset",
        )?,
    )?)?;
    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_x_imm(
            8,
            13,
            offset(
                format.ready_seal_offset(),
                "AArch64 V3 ready seal",
            )?,
        )?)?;
        aarch64_load_u64_constant(assembler, 9, format.ready_seal())?;
        assembler.instruction(aarch64_cmp_x(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
        assembler.instruction(aarch64_load_w_imm(
            8,
            13,
            offset(
                format.format_version_offset(),
                "AArch64 V3 format version",
            )?,
        )?)?;
        aarch64_load_u32_constant(assembler, 9, format.format_version())?;
        assembler.instruction(aarch64_cmp_w(8, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
    }

    if guard_mode.is_full_verifier() {
        // The active capability covers these setup-validated immutable
        // mirrors, pointer constraints, and the complete geometry below.
        // Retain this mode as an independently emitted full verifier.
        for (header_field, tail_field, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_FORWARD_ROWS_ADDRESS_OFFSET,
                format.rows_address_offset(),
                "AArch64 V3 rows mirror",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_CACHE_IDENTITY_OFFSET,
                format.cache_identity_offset(),
                "AArch64 V3 cache identity mirror",
            ),
        ] {
            assembler.instruction(aarch64_load_x_imm(
                8,
                0,
                offset(header_field, context)?,
            )?)?;
            assembler.instruction(aarch64_load_x_imm(
                9,
                13,
                offset(tail_field, context)?,
            )?)?;
            assembler.instruction(aarch64_cmp_x(8, 9)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }

        assembler.instruction(aarch64_load_x_imm(
            8,
            13,
            offset(
                format.rows_address_offset(),
                "AArch64 V3 rows address",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_x_imm(8, 0)?)?;
        assembler.branch_cond(AARCH64_EQ, call_preflight)?;
        if !format.is_u8() {
            assembler.instruction(aarch64_and_low_x(
                9,
                8,
                if format == FrozenCompactNativeFormat::PairSupertransitionV11 {
                    2
                } else {
                    1
                },
            )?)?;
            assembler.instruction(aarch64_cmp_x_imm(9, 0)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }
    }

    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_x_imm(
            8,
            13,
            offset(
                format.cache_identity_offset(),
                "AArch64 V3 cache identity",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_x_imm(8, 0)?)?;
        assembler.branch_cond(AARCH64_EQ, call_preflight)?;
    }

    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_w_imm(
            10,
            13,
            offset(format.state_count_offset(), "AArch64 V3 states")?,
        )?)?;
        assembler.branch_zero_w(10, call_preflight)?;
        if format.is_u8() {
            assembler.instruction(aarch64_cmp_w_imm(10, 127)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        } else if format.is_state_ordinal() {
            aarch64_load_u32_constant(assembler, 8, 0x7fff)?;
            assembler.instruction(aarch64_cmp_w(10, 8)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        } else if format.is_quad_supertransition() {
            aarch64_load_u32_constant(assembler, 8, 0x1fff)?;
            assembler.instruction(aarch64_cmp_w(10, 8)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        }
        assembler.instruction(aarch64_load_w_imm(
            11,
            13,
            offset(format.class_count_offset(), "AArch64 V3 classes")?,
        )?)?;
        assembler.branch_zero_w(11, call_preflight)?;
        assembler.instruction(aarch64_cmp_w_imm(11, 256)?)?;
        assembler.branch_cond(AARCH64_HI, call_preflight)?;
        if format.is_pair_supertransition() {
            assembler.instruction(aarch64_cmp_w_imm(11, 2)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_cmp_w_imm(
                11,
                if format.is_dense_pair_supertransition() {
                    8
                } else {
                    4
                },
            )?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        } else if format.is_quad_supertransition() {
            assembler.instruction(aarch64_cmp_w_imm(11, 2)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_cmp_w_imm(11, 4)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        }
        if format.is_direct_byte() {
            assembler.instruction(aarch64_cmp_w_imm(11, 256)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }
        assembler.instruction(aarch64_load_w_imm(
            12,
            13,
            offset(
                format.row_shift_offset(),
                "AArch64 compact row shift",
            )?,
        )?)?;
        if format.is_quad_supertransition() {
            assembler.branch_nonzero_w(12, call_preflight)?;
            assembler.instruction(aarch64_mul_x(9, 11, 11)?)?;
            assembler.instruction(aarch64_mul_x(8, 9, 11)?)?;
            assembler.instruction(aarch64_add_x_reg(9, 9, 8)?)?;
            assembler.instruction(aarch64_mul_x(8, 8, 11)?)?;
            assembler.instruction(aarch64_add_x_reg(9, 9, 8)?)?;
            assembler.instruction(aarch64_add_x_reg(9, 9, 11)?)?;
        } else if format.is_dense_pair_supertransition() {
            assembler.branch_nonzero_w(12, call_preflight)?;
            assembler.instruction(aarch64_mul_x(9, 11, 11)?)?;
            assembler.instruction(aarch64_add_x_imm(9, 9, 1)?)?;
        } else if format.is_pair_supertransition() {
            assembler.instruction(aarch64_cmp_w_imm(12, 1)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_cmp_w_imm(12, 2)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
            assembler.instruction(aarch64_movz_x(9, 1, 0)?)?;
            assembler.instruction(aarch64_lslv_x(9, 9, 12)?)?;
            assembler.instruction(aarch64_cmp_x(9, 11)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_lsr_x_imm(7, 9, 1)?)?;
            assembler.instruction(aarch64_cmp_x(11, 7)?)?;
            assembler.branch_cond(AARCH64_LS, call_preflight)?;
            assembler.instruction(aarch64_mul_x(9, 9, 9)?)?;
            assembler.instruction(aarch64_add_x_imm(9, 9, 1)?)?;
        } else if format.is_u8() {
            assembler.instruction(aarch64_cmp_w_imm(12, 8)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
            assembler.instruction(aarch64_movz_x(9, 1, 0)?)?;
            assembler.instruction(aarch64_lslv_x(9, 9, 12)?)?;
            assembler.instruction(aarch64_cmp_x(9, 11)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_lsr_x_imm(7, 9, 1)?)?;
            assembler.instruction(aarch64_cmp_x(11, 7)?)?;
            assembler.branch_cond(AARCH64_LS, call_preflight)?;
            assembler.instruction(aarch64_mov_x(8, 12)?)?;
        } else if format.is_state_ordinal() {
            assembler.instruction(aarch64_cmp_w_imm(12, 1)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_cmp_w_imm(12, 9)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;

            // Reconstruct next_power_of_two(class_count) exactly. The
            // descriptor's row shift is in bytes, so its physical-cell
            // exponent is shift-1.
            assembler.instruction(aarch64_sub_w_imm(8, 12, 1)?)?;
            assembler.instruction(aarch64_movz_x(9, 1, 0)?)?;
            assembler.instruction(aarch64_lslv_x(9, 9, 8)?)?;
            assembler.instruction(aarch64_cmp_x(9, 11)?)?;
            assembler.branch_cond(AARCH64_LO, call_preflight)?;
            assembler.instruction(aarch64_lsr_x_imm(7, 9, 1)?)?;
            assembler.instruction(aarch64_cmp_x(11, 7)?)?;
            assembler.branch_cond(AARCH64_LS, call_preflight)?;
        } else {
            assembler.branch_nonzero_w(12, call_preflight)?;
            // V4/V9 are unpadded, so physical and logical class counts are
            // identical and need no shift reconstruction.
            assembler.instruction(aarch64_mov_x(9, 11)?)?;
        }
        assembler.instruction(aarch64_load_w_imm(
            7,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_ROW_STRIDE_OFFSET,
                "AArch64 V3 row stride",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_w(7, 9)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;

        if format.is_pair_supertransition() {
            assembler.instruction(aarch64_mul_x(7, 10, 9)?)?;
            aarch64_load_u32_constant(
                assembler,
                8,
                if format.is_dense_pair_supertransition() {
                    u32::from(DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK)
                } else {
                    DYNAMIC_NATIVE_ROWS_V11_NEXT_BLOCK_TOKEN_MASK
                },
            )?;
            if format.is_dense_pair_supertransition() {
                // V13 destination tokens name block starts, not the complete
                // final block. Keep X7 as the live-cell extent for its mirror
                // and compare the exact final one-based start separately.
                assembler.instruction(aarch64_sub_x_reg(6, 7, 9)?)?;
                assembler.instruction(aarch64_add_x_imm(6, 6, 1)?)?;
                assembler.instruction(aarch64_cmp_x(6, 8)?)?;
            } else {
                assembler.instruction(aarch64_cmp_x(7, 8)?)?;
            }
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        } else if format.is_quad_supertransition() {
            assembler.instruction(aarch64_mul_x(7, 10, 9)?)?;
            // As on x86, authenticate the exact last block-start token while
            // retaining X7 as the complete payload extent for the mirror.
            assembler.instruction(aarch64_sub_x_reg(8, 7, 9)?)?;
            assembler.instruction(aarch64_add_x_imm(8, 8, 1)?)?;
            aarch64_load_u32_constant(
                assembler,
                6,
                u32::from(DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK),
            )?;
            assembler.instruction(aarch64_cmp_x(8, 6)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        } else if format.is_state_ordinal() {
            assembler.instruction(aarch64_lslv_x(7, 10, 8)?)?;
        } else {
            assembler.instruction(aarch64_mul_x(7, 10, 9)?)?;
            aarch64_load_u32_constant(assembler, 8, 0x7fff)?;
            assembler.instruction(aarch64_cmp_x(7, 8)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        }
        assembler.instruction(aarch64_load_x_imm(
            12,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_FORWARD_LIVE_CELLS_OFFSET,
                "AArch64 V3 live cells",
            )?,
        )?)?;
        assembler.instruction(aarch64_cmp_x(7, 12)?)?;
        assembler.branch_cond(AARCH64_NE, call_preflight)?;
        // Setup canonicalizes every compact encoding before format selection.
        // Full verification authenticates the exact zero mirrors, while the
        // production active capability retains its setup-proven fast guard.
        assembler.instruction(aarch64_load_w_imm(
            6,
            13,
            offset(
                format.initial_state_offset(),
                "AArch64 compact initial state",
            )?,
        )?)?;
        assembler.branch_nonzero_w(6, call_preflight)?;
        assembler.instruction(aarch64_load_w_imm(
            7,
            0,
            offset(
                FROZEN_PREPARED_HEADER_V1_FORWARD_INITIAL_ROW_OFFSET,
                "AArch64 compact initial row",
            )?,
        )?)?;
        assembler.branch_nonzero_w(7, call_preflight)?;

        let (dead_cell, accept_mask, next_state_mask) = match format {
            FrozenCompactNativeFormat::DenseQuadSupertransitionV14 => (
                0,
                u32::from(DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::PairSupertransitionV11 => (
                0,
                DYNAMIC_NATIVE_ROWS_V11_ANY_ACCEPT_MASK,
                DYNAMIC_NATIVE_ROWS_V11_NEXT_BLOCK_TOKEN_MASK,
            ),
            FrozenCompactNativeFormat::DensePairSupertransitionV13 => (
                0,
                u32::from(DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::StateOrdinalDirectU8V10 => (
                u32::from(DYNAMIC_NATIVE_ROWS_V10_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V10_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V10_NEXT_STATE_TOKEN_MASK),
            ),
            FrozenCompactNativeFormat::StateOrdinalMappedU8V12 => (
                u32::from(DYNAMIC_NATIVE_ROWS_V12_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V12_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V12_NEXT_STATE_TOKEN_MASK),
            ),
            _ => (
                u32::from(DYNAMIC_NATIVE_ROWS_V3_DEAD_CELL),
                u32::from(DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK),
                u32::from(DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK),
            ),
        };
        for (field, expected, context) in [
            (
                FROZEN_PREPARED_HEADER_V1_UNFILLED_CELL_OFFSET,
                dead_cell,
                "AArch64 compact dead cell",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_ACCEPT_MASK_OFFSET,
                accept_mask,
                "AArch64 compact accept mask",
            ),
            (
                FROZEN_PREPARED_HEADER_V1_NEXT_ROW_TOKEN_MASK_OFFSET,
                next_state_mask,
                "AArch64 compact next-state mask",
            ),
        ] {
            assembler.instruction(aarch64_load_w_imm(7, 0, offset(field, context)?)?)?;
            aarch64_load_u32_constant(assembler, 8, expected)?;
            assembler.instruction(aarch64_cmp_w(7, 8)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }
    }

    if guard_mode.is_full_verifier() {
        // Compact non-loop formats normalize complete immutable rows by
        // suppressing mutable learned-loop ownership. The full verifier
        // authenticates that normalization independently of the capability.
        assembler.instruction(aarch64_load_w_imm(
            7,
            13,
            offset(format.loop_count_offset(), "AArch64 V3 loop count")?,
        )?)?;
        assembler.branch_nonzero_w(7, call_preflight)?;
        aarch64_load_u32_constant(assembler, 8, u32::MAX)?;
        for loop_index in 0..NATIVE_ROWS_LOOP_ROW_CAPACITY {
            let loop_offset = format.loop_states_offset()
                .checked_add(
                    loop_index
                        .checked_mul(core::mem::size_of::<u32>())
                        .ok_or(ObjectError::ArithmeticOverflow("AArch64 V3 loop state"))?,
                )
                .ok_or(ObjectError::ArithmeticOverflow("AArch64 V3 loop state"))?;
            assembler.instruction(aarch64_load_w_imm(
                7,
                13,
                offset(loop_offset, "AArch64 V3 inactive loop state")?,
            )?)?;
            assembler.instruction(aarch64_cmp_w(7, 8)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
        }

        if format == FrozenCompactNativeFormat::UnaryExistsV5 {
            assembler.instruction(aarch64_load_w_imm(
                7,
                13,
                offset(
                    FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET,
                    "AArch64 V5 first accept step",
                )?,
            )?)?;
            assembler.instruction(aarch64_load_w_imm(
                8,
                13,
                offset(
                    FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_COMPLEMENT_OFFSET,
                    "AArch64 V5 first accept complement",
                )?,
            )?)?;
            assembler.instruction(aarch64_eor_w(8, 8, 7)?)?;
            aarch64_load_u32_constant(assembler, 9, u32::MAX)?;
            assembler.instruction(aarch64_cmp_w(8, 9)?)?;
            assembler.branch_cond(AARCH64_NE, call_preflight)?;
            assembler.instruction(aarch64_load_w_imm(
                8,
                13,
                offset(format.state_count_offset(), "AArch64 V5 state bound")?,
            )?)?;
            assembler.instruction(aarch64_cmp_w(7, 8)?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
        }

        if format.has_loop_plans() {
            assembler.instruction(aarch64_load_w_imm(
                7,
                13,
                offset(
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_PLAN_COUNT_OFFSET,
                    "AArch64 V6 loop plan count",
                )?,
            )?)?;
            assembler.branch_zero_w(7, call_preflight)?;
            assembler.instruction(aarch64_cmp_w_imm(
                7,
                u16::try_from(NATIVE_ROWS_LOOP_ROW_CAPACITY)
                    .map_err(|_| ObjectError::ArithmeticOverflow("AArch64 V6 loop capacity"))?,
            )?)?;
            assembler.branch_cond(AARCH64_HI, call_preflight)?;
            assembler.instruction(aarch64_load_w_imm(
                8,
                13,
                offset(FROZEN_DYNAMIC_ROWS_V6_RESERVED_OFFSET, "AArch64 V6 reserved")?,
            )?)?;
            assembler.branch_nonzero_w(8, call_preflight)?;
            for (field, context) in [
                (
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_ADDRESS_OFFSET,
                    "AArch64 V6 loop index address",
                ),
                (
                    FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_LENGTH_OFFSET,
                    "AArch64 V6 loop index length",
                ),
            ] {
                assembler.instruction(aarch64_load_x_imm(8, 13, offset(field, context)?)?)?;
                assembler.instruction(aarch64_cmp_x_imm(8, 0)?)?;
                assembler.branch_cond(AARCH64_EQ, call_preflight)?;
            }
        }
    }

    // Preserve the standalone full verifier instruction contract. Production
    // lowering saves the bounds once before selecting a compact format.
    if guard_mode.is_full_verifier() {
        assembler.instruction(aarch64_load_x_imm(8, 31, 24)?)?;
        assembler.instruction(aarch64_store_x(8, 31, 48)?)?;
        assembler.instruction(aarch64_load_x_imm(8, 31, 32)?)?;
        assembler.instruction(aarch64_store_x(8, 31, 56)?)?;
    }

    if format == FrozenCompactNativeFormat::UnaryExistsV5 {
        assembler.instruction(aarch64_load_w_imm(
            7,
            13,
            offset(
                FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET,
                "AArch64 V5 retained first accept step",
            )?,
        )?)?;
    }
    assembler.branch(compact_enter)?;
    Ok(())
}

fn aarch64_emit_frozen_compact_v3_entry(
    assembler: &mut Aarch64Assembler,
    try_v2: Aarch64Label,
    call_preflight: Aarch64Label,
    v3_enter: Aarch64Label,
    guard_mode: FrozenCompactGuardMode,
) -> Result<(), ObjectError> {
    aarch64_emit_frozen_compact_entry(
        assembler,
        FrozenCompactNativeFormat::StateOrdinalV3,
        try_v2,
        call_preflight,
        v3_enter,
        guard_mode,
    )
}

