    /// Six exact transition columns are each represented by two graph
    /// classes. Two pairs name distinct incomplete destinations and therefore
    /// become equal only under authenticated collapsed-hole semantics. Every
    /// row retains its own live self transition, preventing row interning,
    /// while six equally frequent values prevent bounded sparse rows from
    /// superseding the column quotient.
    struct ColumnQuotientFixture {
        byte_classes: [u8; 256],
        class_representatives: [u8; 12],
        forward_cells: Vec<ForwardCell>,
    }

    impl ColumnQuotientFixture {
        const CLASS_COUNT: usize = 12;
        const QUOTIENT_CLASS_COUNT: usize = 6;
        const COMPLETE_ROWS: usize = 96;
        const DISCOVERED_STATES: usize = Self::COMPLETE_ROWS + 4;

        fn new() -> Self {
            let mut byte_classes = [0_u8; 256];
            for class in 1..Self::CLASS_COUNT {
                byte_classes[class * 2] = u8::try_from(class).unwrap();
            }
            let class_representatives = core::array::from_fn(|class| {
                u8::try_from(class * 2).unwrap()
            });
            let complete_rows = u32::try_from(Self::COMPLETE_ROWS).unwrap();
            let mut forward_cells = Vec::with_capacity(
                Self::COMPLETE_ROWS * Self::CLASS_COUNT,
            );
            for state in 0..Self::COMPLETE_ROWS {
                let state = u32::try_from(state).unwrap();
                let next = (state + 1) % complete_rows;
                let next_next = (state + 2) % complete_rows;
                for class in 0..Self::CLASS_COUNT {
                    let cell = if state == 0 && class >= 6 {
                        ForwardCell::new(0, false)
                    } else {
                        match class {
                            0 | 1 => ForwardCell::new(state, false),
                            2 | 3 => ForwardCell::new(next, false),
                            4 | 5 => ForwardCell::new(next_next, true),
                            6 | 7 => ForwardCell::new(NO_DFA_STATE, false),
                            8 => ForwardCell::new(complete_rows, false),
                            9 => ForwardCell::new(complete_rows + 1, false),
                            10 => ForwardCell::new(complete_rows + 2, true),
                            11 => ForwardCell::new(complete_rows + 3, true),
                            _ => unreachable!("bounded quotient fixture class"),
                        }
                    };
                    forward_cells.push(cell);
                }
            }
            Self {
                byte_classes,
                class_representatives,
                forward_cells,
            }
        }

        fn view<'a>(
            &'a self,
            base: NativeProgramView<'a>,
            collapse_partial_holes: bool,
        ) -> NativeProgramView<'a> {
            NativeProgramView {
                dfa: NativeDfaView {
                    initial_state: 0,
                    initial_pending: false,
                    initial_terminal: false,
                    byte_classes: &self.byte_classes,
                    class_count: Self::CLASS_COUNT,
                    class_representatives: &self.class_representatives,
                    forward_cells: &self.forward_cells,
                    reverse_initial: None,
                    reverse_cells: &[],
                },
                partial_discovered_states: Some(Self::DISCOVERED_STATES),
                collapse_partial_holes,
                exact_match_width: None,
                max_match_width: None,
                exact_product_width: None,
                retained_prefix_requirement: None,
                retained_suffix_requirement: None,
                ..base
            }
        }
    }

    fn default_exception_partial_view<'a>(
        fixture: &'a DefaultExceptionPartialFixture,
        compiled: &'a CompiledRegex,
    ) -> NativeProgramView<'a> {
        fixture.view(
            compiled
                .program()
                .native_partial_dfa_view()
                .expect("partial base view")
                .native,
        )
    }

    fn build_forced_default_exception_table(
        view: NativeProgramView<'_>,
        architecture: Architecture,
        maximum: usize,
    ) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
        let plan = derive_native_default_exception_plan(
            view.dfa,
            view.partial_discovered_states,
            view.collapse_partial_holes,
            architecture,
        )
        .expect("synthetic default-exception plan");
        build_native_dfa_table_with_cost_model_and_data_limit_once(
            view,
            architecture,
            NativeVectorFilterCostModel::Established,
            true,
            maximum,
            Some(plan),
        )
    }

    fn derive_forced_hybrid_sparse_plan(
        view: NativeProgramView<'_>,
        architecture: Architecture,
        exact_rows: Option<&NativeExactRowInternPlan>,
    ) -> (NativeDefaultExceptionPlan, NativeHybridSparsePlan) {
        let comparison = derive_native_default_exception_plan(
            view.dfa,
            view.partial_discovered_states,
            view.collapse_partial_holes,
            architecture,
        )
        .expect("synthetic hybrid sparse comparison plan");
        let hybrid = derive_native_hybrid_sparse_plan(view, comparison, exact_rows)
            .expect("synthetic hybrid sparse variable-row plan");
        (comparison, hybrid)
    }

    fn build_forced_hybrid_sparse_table(
        view: NativeProgramView<'_>,
        architecture: Architecture,
        maximum: usize,
        exact_rows: Option<&NativeExactRowInternPlan>,
    ) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
        let (_, plan) = derive_forced_hybrid_sparse_plan(view, architecture, exact_rows);
        build_native_dfa_table_with_cost_model_and_data_limit_once_with_exact_rows_and_asimd_policy(
            view,
            architecture,
            NativeVectorFilterCostModel::Established,
            true,
            maximum,
            None,
            exact_rows,
            false,
            None,
            None,
            Some(&plan),
            architecture == Architecture::Aarch64,
            true,
        )
    }

    fn lower_forced_default_exception_table_for_target(
        view: NativeProgramView<'_>,
        target: Target,
    ) -> Result<NativeLowering, ObjectError> {
        let maximum = usize::try_from(CELL_NEXT_MASK)
            .map_err(|_| ObjectError::ArithmeticOverflow("native table address limit"))?;
        let vector_cost_model = native_vector_filter_cost_model_for_target(target, true);
        let relation_vector_owns_route = direct_relation_vector_owns_route(target);
        let plan = derive_native_default_exception_plan(
            view.dfa,
            view.partial_discovered_states,
            view.collapse_partial_holes,
            target.architecture,
        )
        .expect("synthetic default-exception plan");
        let (mut data, mut layout) =
            build_native_dfa_table_with_cost_model_and_data_limit_once_with_asimd_policy(
                view,
                target.architecture,
                vector_cost_model,
                relation_vector_owns_route,
                maximum,
                Some(plan),
                target.features.has(CpuFeature::Aarch64Asimd),
            )?;
        let sve_filter_plan = install_aarch64_sve_filter_plan_with_limit(
            &mut data,
            layout,
            target,
            maximum,
        )?;
        let sve_suffix_kind = install_aarch64_sve_suffix_kind_with_limit(
            &mut data,
            layout,
            target,
            maximum,
        )?;
        install_aarch64_sve_loop_storage_with_limit(
            &mut data,
            &mut layout,
            target,
            maximum,
        )?;
        let entry_contract = NativeDfaEntryContract::PreparedPartialCore;
        let emission = match target.architecture {
            Architecture::X86_64 => {
                lower_x86_64_dfa_with_entry_contract(
                    layout,
                    target.features,
                    entry_contract,
                )?
            }
            Architecture::Aarch64 => lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
                layout,
                target.features,
                target.operating_system,
                sve_filter_plan,
                sve_suffix_kind,
                entry_contract,
            )?,
        };
        let start_accelerator = selected_start_accelerator(
            layout,
            target,
            sve_filter_plan,
            sve_suffix_kind,
            emission.scanner,
        );
        Ok(NativeLowering {
            code: emission.code,
            data,
            relocations: emission.relocations,
            slow_partial_table: None,
            needs_runtime: false,
            start_accelerator,
            anchored_prefix_filter_bytes: layout
                .prefix_filter
                .map_or(0, |filter| filter.guaranteed_bytes),
            synchronizing_accept_reverse_lowered: false,
        })
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the exact packed-table oracle computes offsets within validated row geometry"
    )]
    fn scalable_default_exception_packed_at(
        data: &[u8],
        layout: NativeDfaLayout,
        view: NativeProgramView<'_>,
        state: usize,
        byte: u8,
    ) -> u32 {
        let (capacity, key) = match layout.transitions {
            TransitionLayout::DefaultSparseExceptions(capacity) => {
                (capacity, view.dfa.byte_classes[usize::from(byte)])
            }
            TransitionLayout::DefaultByteSparseExceptions(capacity) => (capacity, byte),
            other => panic!("expected scalable default-exception rows, got {other:?}"),
        };
        let row_bytes = native_default_exception_row_bytes(capacity, layout.cells).unwrap();
        let value_offset = native_default_exception_value_offset(capacity, layout.cells).unwrap();
        let row_start = usize::try_from(layout.forward_offset).unwrap() + state * row_bytes;
        let cell_bytes = layout.cells.bytes();
        let mut packed = read_native_packed_cell(data, row_start, layout.cells);
        for slot in 0..native_default_exception_physical_slots(capacity) {
            if data[row_start + cell_bytes + slot] == key {
                let value = row_start + value_offset + slot * cell_bytes;
                packed = read_native_packed_cell(data, value, layout.cells);
                break;
            }
        }
        packed
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the oracle walks authenticated variable-row extents and indexes one validated record"
    )]
    fn hybrid_sparse_packed_at(
        data: &[u8],
        layout: NativeDfaLayout,
        view: NativeProgramView<'_>,
        physical_state: usize,
        byte: u8,
    ) -> u32 {
        let (long_capacity, key) = match layout.transitions {
            TransitionLayout::HybridSparseExceptions(capacity) => {
                (capacity, view.dfa.byte_classes[usize::from(byte)])
            }
            TransitionLayout::HybridByteSparseExceptions(capacity) => (capacity, byte),
            other => panic!("expected hybrid sparse rows, got {other:?}"),
        };
        let cell_bytes = layout.cells.bytes();
        let short_row_bytes = native_hybrid_sparse_short_row_bytes(layout.cells).unwrap();
        let long_row_bytes =
            native_default_exception_row_bytes(long_capacity, layout.cells).unwrap();
        let mut row_start = usize::try_from(layout.forward_offset).unwrap();
        for _ in 0..physical_state {
            let short = data[row_start + cell_bytes + 15]
                == data[row_start + cell_bytes + 16];
            row_start += if short {
                short_row_bytes
            } else {
                long_row_bytes
            };
        }
        let short = data[row_start + cell_bytes + 15]
            == data[row_start + cell_bytes + 16];
        let capacity = if short {
            NATIVE_HYBRID_SHORT_EXCEPTION_CAPACITY
        } else {
            long_capacity
        };
        let value_offset = if short {
            native_hybrid_sparse_short_value_offset(layout.cells).unwrap()
        } else {
            native_default_exception_value_offset(long_capacity, layout.cells).unwrap()
        };
        let mut packed = read_native_packed_cell(data, row_start, layout.cells);
        for slot in 0..usize::from(capacity) {
            if data[row_start + cell_bytes + slot] == key {
                packed = read_native_packed_cell(
                    data,
                    row_start + value_offset + slot * cell_bytes,
                    layout.cells,
                );
                break;
            }
        }
        packed
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the test oracle indexes one already validated fixed-stride ordinal row"
    )]
    fn ordinal_map_packed_at(
        data: &[u8],
        layout: NativeDfaLayout,
        domain_count: usize,
        physical_state: usize,
        key: u8,
    ) -> u32 {
        let value_capacity = match layout.transitions {
            TransitionLayout::OrdinalMapClasses(capacity)
            | TransitionLayout::OrdinalMapBytes(capacity)
            | TransitionLayout::OrdinalOffsetClasses(capacity)
            | TransitionLayout::OrdinalOffsetBytes(capacity) => capacity,
            other => panic!("expected ordinal-map rows, got {other:?}"),
        };
        let row_bytes = native_ordinal_map_row_bytes(
            value_capacity,
            domain_count,
            layout.cells,
        )
        .unwrap();
        let row_start = usize::try_from(layout.forward_offset).unwrap()
            + physical_state * row_bytes;
        match layout.transitions {
            TransitionLayout::OrdinalOffsetClasses(_)
            | TransitionLayout::OrdinalOffsetBytes(_) => {
                let offset = usize::from(data[row_start + usize::from(key)]);
                let value_offset = native_ordinal_offset_map_value_offset(
                    domain_count,
                    layout.cells,
                )
                .unwrap();
                assert!(offset >= value_offset);
                assert!((offset - value_offset).is_multiple_of(layout.cells.bytes()));
                read_native_packed_cell(data, row_start + offset, layout.cells)
            }
            TransitionLayout::OrdinalMapClasses(_) | TransitionLayout::OrdinalMapBytes(_) => {
                let value_bytes =
                    native_ordinal_map_value_bytes(value_capacity, layout.cells).unwrap();
                let ordinal =
                    usize::from(data[row_start + value_bytes + usize::from(key)]);
                assert!(ordinal <= usize::from(value_capacity));
                read_native_packed_cell(
                    data,
                    row_start + ordinal * layout.cells.bytes(),
                    layout.cells,
                )
            }
            _ => unreachable!("guarded ordinal-map layout"),
        }
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the test oracle indexes one already validated fixed-stride bit-slice row"
    )]
    fn bit_slice_packed_at(
        data: &[u8],
        layout: NativeDfaLayout,
        domain_count: usize,
        physical_state: usize,
        key: u8,
    ) -> u32 {
        let capacity = match layout.transitions {
            TransitionLayout::BitSliceClasses(capacity)
            | TransitionLayout::BitSliceBytes(capacity) => capacity,
            other => panic!("expected bit-slice rows, got {other:?}"),
        };
        assert_eq!(capacity, NATIVE_BIT_SLICE_VALUE_CAPACITY);
        let row_bytes = native_bit_slice_row_bytes(domain_count, layout.cells).unwrap();
        let bitmap_offset = native_bit_slice_bitmap_offset(layout.cells).unwrap();
        let row_start = usize::try_from(layout.forward_offset).unwrap()
            + physical_state * row_bytes;
        let key = usize::from(key);
        let ordinal = usize::from(
            data[row_start + bitmap_offset + key / NATIVE_BIT_SLICE_BYTE_BITS]
                >> u32::try_from(key % NATIVE_BIT_SLICE_BYTE_BITS).unwrap()
                & 1,
        );
        read_native_packed_cell(
            data,
            row_start + ordinal * layout.cells.bytes(),
            layout.cells,
        )
    }

    #[derive(Clone, Copy)]
    struct LinkedSparseNativeFixture {
        byte_cells: [ForwardCell; CLASS_MAP_BYTES],
        partial: NativePartialDfaLayout,
    }

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct LinkedSparseExpected {
        status: u32,
        first: Option<usize>,
        second: Option<usize>,
        position: Option<usize>,
    }

    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_arguments,
        clippy::too_many_lines,
        reason = "the test fixture constructs one exact native sparse record and its independent byte oracle"
    )]
    fn linked_sparse_native_fixture(
        target: Target,
        exception_capacity: u8,
        exception_count: usize,
        cells: NativeCellEncoding,
        keys: NativeDefaultExceptionKeys,
        collapse_holes: bool,
        output: OutputContract,
        sparse_boundary_profile: NativeSparseBoundaryProfile,
    ) -> Result<(NativeLowering, LinkedSparseNativeFixture), ObjectError> {
        assert!(usize::from(exception_capacity) > MAX_NATIVE_DEFAULT_EXCEPTIONS);
        assert!(exception_count <= usize::from(exception_capacity));
        assert!(sparse_boundary_profile.is_valid());
        assert!(matches!(
            cells,
            NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32
        ));
        assert!(matches!(
            keys,
            NativeDefaultExceptionKeys::Classes | NativeDefaultExceptionKeys::Bytes
        ));
        let transitions = keys.transitions(exception_capacity);
        let row_bytes = native_default_exception_row_bytes(exception_capacity, cells)
            .expect("linked sparse row geometry");
        let forward_offset =
            native_table_prefix_bytes(transitions, cells, CLASS_MAP_BYTES)
                .expect("linked sparse table prefix");
        let reverse_offset = forward_offset
            .checked_add(row_bytes)
            .ok_or(ObjectError::ArithmeticOverflow(
                "linked sparse machine extent",
            ))?;
        let last_live_token = encode_native_row_offset(forward_offset, cells).ok_or(
            ObjectError::InvalidModule("linked sparse initial row token"),
        )?;
        let partial = NativePartialDfaLayout {
            hole_token_base: u32::try_from(last_live_token.checked_add(1).ok_or(
                ObjectError::ArithmeticOverflow("linked sparse hole base"),
            )?)
            .map_err(|_| ObjectError::ArithmeticOverflow("linked sparse hole base"))?,
            resume_states: 4,
            collapse_holes,
        };

        let class_map: [u8; CLASS_MAP_BYTES] = core::array::from_fn(|byte| {
            u8::try_from((byte * 73 + 19) & usize::from(u8::MAX)).unwrap()
        });
        let default = ForwardCell::new(0, false);
        let mut key_cells = [default; CLASS_MAP_BYTES];
        let mut exceptions = [None; MAX_NATIVE_SPARSE_EXCEPTIONS];
        let capacity = usize::from(exception_capacity);
        for slot in 0..exception_count {
            // Exact integer spacing exercises low, interior, and high keys at
            // every capacity. At 255 this is precisely 0..=254, leaving byte
            // 255 as the sole default query.
            let key = u8::try_from(slot * CLASS_MAP_BYTES / capacity).unwrap();
            let cell = match slot % 8 {
                0 => ForwardCell::new(0, true),
                1 => ForwardCell::new(1, false),
                2 => ForwardCell::new(2, true),
                3 => ForwardCell::new(NO_DFA_STATE, false),
                4 => ForwardCell::new(NO_DFA_STATE, true),
                5 => ForwardCell::new(3, false),
                6 => ForwardCell::new(0, true),
                _ => ForwardCell::new(4, true),
            };
            key_cells[usize::from(key)] = cell;
            exceptions[slot] = Some((key, cell));
        }
        let byte_cells = core::array::from_fn(|byte| {
            let key = match keys {
                NativeDefaultExceptionKeys::Classes => class_map[byte],
                NativeDefaultExceptionKeys::Bytes => u8::try_from(byte).unwrap(),
                NativeDefaultExceptionKeys::Boundaries => {
                    unreachable!("linked sparse fixture excludes boundaries")
                }
            };
            key_cells[usize::from(key)]
        });
        let mut data = Vec::new();
        if keys == NativeDefaultExceptionKeys::Classes {
            data.extend_from_slice(&class_map);
        }
        append_native_default_exception_record(
            &mut data,
            default,
            &exceptions,
            exception_count,
            exception_capacity,
            cells,
            row_bytes,
            |cell| {
                pack_native_partial_forward_cell(
                    cell.next(),
                    cell.accepted(),
                    forward_offset,
                    row_bytes,
                    1,
                    false,
                    None,
                    partial,
                    cells,
                )
            },
        )?;
        if data.len() != reverse_offset {
            return Err(ObjectError::InvalidModule(
                "linked sparse fixture emitted an unexpected machine extent",
            ));
        }

        let needs_asimd_lane_index = target.architecture == Architecture::Aarch64
            && transitions.uses_vector_sparse_lookup()
            && target.features.has(CpuFeature::Aarch64Asimd);
        let asimd_lane_index_offset = if needs_asimd_lane_index {
            let aligned = data
                .len()
                .checked_add(AARCH64_FIRST_LANE_INDEX.len() - 1)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "linked sparse ASIMD lane alignment",
                ))?
                & !(AARCH64_FIRST_LANE_INDEX.len() - 1);
            data.resize(aligned, 0);
            data.extend_from_slice(&AARCH64_FIRST_LANE_INDEX);
            Some(u32::try_from(aligned).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked sparse ASIMD lane offset")
            })?)
        } else {
            None
        };
        let layout = NativeDfaLayout {
            transitions,
            cells,
            bit_slice_domain_count: None,
            forward_offset: u32::try_from(forward_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked sparse forward offset")
            })?,
            reverse_offset: u32::try_from(reverse_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked sparse reverse offset")
            })?,
            sparse_boundary_profile: Some(sparse_boundary_profile),
            asimd_lane_index_offset,
            initial_pending: false,
            initial_terminal: false,
            start_scanner_preserves_pending: false,
            has_reverse: false,
            partial: Some(partial),
            exact_span_width: (output == OutputContract::Span).then_some(1),
            exact_prefix_match_width: None,
            output,
            start_filter: None,
            exact_start_byte_set: None,
            exact_start_storage: None,
            suffix_filter: None,
            mandatory_teddy: None,
            declined_redundant_root_reverse: false,
            seeded_reverse: None,
            loop_skip: None,
            loop_skip_secondary: None,
            vector_filter: None,
            prefix_filter: None,
            prefix_relation: None,
            prefix_block: None,
            prefix_fast_forward: None,
        };
        let emission = match target.architecture {
            Architecture::X86_64 => lower_x86_64_dfa_with_entry_contract(
                layout,
                target.features,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
            Architecture::Aarch64 => lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
                layout,
                target.features,
                target.operating_system,
                None,
                None,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
        };
        Ok((
            NativeLowering {
                code: emission.code,
                data,
                relocations: emission.relocations,
                slow_partial_table: None,
                needs_runtime: false,
                start_accelerator: StartAccelerator::Scalar,
                anchored_prefix_filter_bytes: 0,
                synchronizing_accept_reverse_lowered: false,
            },
            LinkedSparseNativeFixture {
                byte_cells,
                partial,
            },
        ))
    }

    #[derive(Clone, Copy)]
    struct LinkedHybridSparseNativeFixture {
        byte_cells: [[ForwardCell; CLASS_MAP_BYTES]; 2],
        partial: NativePartialDfaLayout,
        entry_byte: u8,
    }

    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_arguments,
        clippy::too_many_lines,
        reason = "the linked fixture emits two self-describing rows and an independent byte oracle"
    )]
    fn linked_hybrid_sparse_native_fixture(
        target: Target,
        cells: NativeCellEncoding,
        keys: NativeDefaultExceptionKeys,
        collapse_holes: bool,
    ) -> Result<(NativeLowering, LinkedHybridSparseNativeFixture), ObjectError> {
        const CAPACITY: u8 = 31;
        const ENTRY_KEY: u8 = 73;
        assert!(matches!(
            cells,
            NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32
        ));
        assert!(matches!(
            keys,
            NativeDefaultExceptionKeys::Classes | NativeDefaultExceptionKeys::Bytes
        ));
        let transitions = native_hybrid_sparse_transitions(keys, CAPACITY)
            .expect("linked hybrid transition layout");
        let short_row_bytes = native_hybrid_sparse_short_row_bytes(cells)
            .expect("linked hybrid short row geometry");
        let long_row_bytes = native_default_exception_row_bytes(CAPACITY, cells)
            .expect("linked hybrid long row geometry");
        let forward_offset = native_table_prefix_bytes(transitions, cells, CLASS_MAP_BYTES)
            .expect("linked hybrid table prefix");
        let long_row_offset = forward_offset
            .checked_add(short_row_bytes)
            .ok_or(ObjectError::ArithmeticOverflow(
                "linked hybrid long row offset",
            ))?;
        let reverse_offset = long_row_offset
            .checked_add(long_row_bytes)
            .ok_or(ObjectError::ArithmeticOverflow(
                "linked hybrid machine extent",
            ))?;
        let last_live_token = encode_native_row_offset(long_row_offset, cells).ok_or(
            ObjectError::InvalidModule("linked hybrid final live token"),
        )?;
        let partial = NativePartialDfaLayout {
            hole_token_base: u32::try_from(last_live_token.checked_add(1).ok_or(
                ObjectError::ArithmeticOverflow("linked hybrid hole base"),
            )?)
            .map_err(|_| ObjectError::ArithmeticOverflow("linked hybrid hole base"))?,
            resume_states: 2,
            collapse_holes,
        };
        let row_offsets = [
            u32::try_from(forward_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("linked hybrid short row"))?,
            u32::try_from(long_row_offset)
                .map_err(|_| ObjectError::ArithmeticOverflow("linked hybrid long row"))?,
        ];

        let class_map: [u8; CLASS_MAP_BYTES] = core::array::from_fn(|byte| {
            u8::try_from((byte * 73 + 19) & usize::from(u8::MAX)).unwrap()
        });
        let entry_byte = match keys {
            NativeDefaultExceptionKeys::Classes => u8::try_from(
                class_map
                    .iter()
                    .position(|&class| class == ENTRY_KEY)
                    .expect("linked hybrid entry class"),
            )
            .unwrap(),
            NativeDefaultExceptionKeys::Bytes => ENTRY_KEY,
            NativeDefaultExceptionKeys::Boundaries => {
                unreachable!("linked hybrid fixture excludes boundaries")
            }
        };

        let short_default = ForwardCell::new(0, false);
        let short_exception = ForwardCell::new(1, false);
        let mut short_key_cells = [short_default; CLASS_MAP_BYTES];
        short_key_cells[usize::from(ENTRY_KEY)] = short_exception;
        let mut short_exceptions = [None; MAX_NATIVE_SPARSE_EXCEPTIONS];
        short_exceptions[0] = Some((ENTRY_KEY, short_exception));

        let long_default = ForwardCell::new(1, false);
        let mut long_key_cells = [long_default; CLASS_MAP_BYTES];
        let mut long_exceptions = [None; MAX_NATIVE_SPARSE_EXCEPTIONS];
        for slot in 0..usize::from(CAPACITY) {
            let key = u8::try_from(slot * CLASS_MAP_BYTES / usize::from(CAPACITY)).unwrap();
            let cell = match slot % 8 {
                0 => ForwardCell::new(1, true),
                1 => ForwardCell::new(0, false),
                2 => ForwardCell::new(2, false),
                3 => ForwardCell::new(3, true),
                4 => ForwardCell::new(NO_DFA_STATE, false),
                5 => ForwardCell::new(NO_DFA_STATE, true),
                6 => ForwardCell::new(1, false),
                _ => ForwardCell::new(0, true),
            };
            long_key_cells[usize::from(key)] = cell;
            long_exceptions[slot] = Some((key, cell));
        }
        let byte_cells = [short_key_cells, long_key_cells].map(|key_cells| {
            core::array::from_fn(|byte| {
                let key = match keys {
                    NativeDefaultExceptionKeys::Classes => class_map[byte],
                    NativeDefaultExceptionKeys::Bytes => u8::try_from(byte).unwrap(),
                    NativeDefaultExceptionKeys::Boundaries => {
                        unreachable!("linked hybrid fixture excludes boundaries")
                    }
                };
                key_cells[usize::from(key)]
            })
        });

        let pack = |cell: ForwardCell| {
            pack_native_partial_forward_cell_with_variable_rows(
                cell.next(),
                cell.accepted(),
                2,
                false,
                None,
                partial,
                cells,
                None,
                &row_offsets,
            )
        };
        let mut data = Vec::new();
        if keys == NativeDefaultExceptionKeys::Classes {
            data.extend_from_slice(&class_map);
        }
        append_native_hybrid_sparse_short_record(
            &mut data,
            short_default,
            &short_exceptions,
            1,
            cells,
            pack,
        )?;
        append_native_default_exception_record(
            &mut data,
            long_default,
            &long_exceptions,
            usize::from(CAPACITY),
            CAPACITY,
            cells,
            long_row_bytes,
            pack,
        )?;
        if data.len() != reverse_offset {
            return Err(ObjectError::InvalidModule(
                "linked hybrid fixture emitted an unexpected machine extent",
            ));
        }

        let needs_asimd_lane_index = target.architecture == Architecture::Aarch64
            && target.features.has(CpuFeature::Aarch64Asimd);
        let asimd_lane_index_offset = if needs_asimd_lane_index {
            let aligned = data
                .len()
                .checked_add(AARCH64_FIRST_LANE_INDEX.len() - 1)
                .ok_or(ObjectError::ArithmeticOverflow(
                    "linked hybrid ASIMD lane alignment",
                ))?
                & !(AARCH64_FIRST_LANE_INDEX.len() - 1);
            data.resize(aligned, 0);
            data.extend_from_slice(&AARCH64_FIRST_LANE_INDEX);
            Some(u32::try_from(aligned).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked hybrid ASIMD lane offset")
            })?)
        } else {
            None
        };
        let layout = NativeDfaLayout {
            transitions,
            cells,
            bit_slice_domain_count: None,
            forward_offset: row_offsets[0],
            reverse_offset: u32::try_from(reverse_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked hybrid reverse offset")
            })?,
            sparse_boundary_profile: None,
            asimd_lane_index_offset,
            initial_pending: false,
            initial_terminal: false,
            start_scanner_preserves_pending: false,
            has_reverse: false,
            partial: Some(partial),
            exact_span_width: None,
            exact_prefix_match_width: None,
            output: OutputContract::SelectedEnd,
            start_filter: None,
            exact_start_byte_set: None,
            exact_start_storage: None,
            suffix_filter: None,
            mandatory_teddy: None,
            declined_redundant_root_reverse: false,
            seeded_reverse: None,
            loop_skip: None,
            loop_skip_secondary: None,
            vector_filter: None,
            prefix_filter: None,
            prefix_relation: None,
            prefix_block: None,
            prefix_fast_forward: None,
        };
        if !native_default_exception_layout_is_valid(&layout) {
            return Err(ObjectError::InvalidModule(
                "linked hybrid layout failed validation",
            ));
        }
        let emission = match target.architecture {
            Architecture::X86_64 => lower_x86_64_dfa_with_entry_contract(
                layout,
                target.features,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
            Architecture::Aarch64 => lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
                layout,
                target.features,
                target.operating_system,
                None,
                None,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
        };
        Ok((
            NativeLowering {
                code: emission.code,
                data,
                relocations: emission.relocations,
                slow_partial_table: None,
                needs_runtime: false,
                start_accelerator: StartAccelerator::Scalar,
                anchored_prefix_filter_bytes: 0,
                synchronizing_accept_reverse_lowered: false,
            },
            LinkedHybridSparseNativeFixture {
                byte_cells,
                partial,
                entry_byte,
            },
        ))
    }

    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_arguments,
        clippy::too_many_lines,
        reason = "the linked fixture constructs one exact two-value bitmap row and its independent byte oracle"
    )]
    fn linked_bit_slice_native_fixture(
        target: Target,
        cells: NativeCellEncoding,
        keys: NativeOrdinalMapKeys,
        collapse_holes: bool,
        output: OutputContract,
        alternate: ForwardCell,
    ) -> Result<(NativeLowering, LinkedSparseNativeFixture), ObjectError> {
        assert!(matches!(
            cells,
            NativeCellEncoding::Compact16 | NativeCellEncoding::Wide32
        ));
        let transitions = keys.transitions(
            NativeLocalMapKind::BitSlice1,
            NATIVE_BIT_SLICE_VALUE_CAPACITY,
        );
        let domain_count = match keys {
            NativeOrdinalMapKeys::Classes => NATIVE_BIT_SLICE_WORD_BITS,
            NativeOrdinalMapKeys::Bytes => CLASS_MAP_BYTES,
        };
        let row_bytes = native_bit_slice_row_bytes(domain_count, cells)
            .expect("linked bit-slice row geometry");
        let forward_offset =
            native_table_prefix_bytes(transitions, cells, CLASS_MAP_BYTES)
                .expect("linked bit-slice table prefix");
        let reverse_offset = forward_offset
            .checked_add(row_bytes)
            .ok_or(ObjectError::ArithmeticOverflow(
                "linked bit-slice machine extent",
            ))?;
        let last_live_token = encode_native_row_offset(forward_offset, cells).ok_or(
            ObjectError::InvalidModule("linked bit-slice initial row token"),
        )?;
        let partial = NativePartialDfaLayout {
            hole_token_base: u32::try_from(last_live_token.checked_add(1).ok_or(
                ObjectError::ArithmeticOverflow("linked bit-slice hole base"),
            )?)
            .map_err(|_| ObjectError::ArithmeticOverflow("linked bit-slice hole base"))?,
            resume_states: 4,
            collapse_holes,
        };

        let class_map: [u8; CLASS_MAP_BYTES] = core::array::from_fn(|byte| {
            u8::try_from((byte * 73 + 19) % domain_count).unwrap()
        });
        let default = ForwardCell::new(0, false);
        let key_cells = (0..domain_count)
            .map(|key| {
                if key.count_ones() % 2 == 0 {
                    default
                } else {
                    alternate
                }
            })
            .collect::<Vec<_>>();
        let byte_cells = core::array::from_fn(|byte| {
            let key = match keys {
                NativeOrdinalMapKeys::Classes => class_map[byte],
                NativeOrdinalMapKeys::Bytes => u8::try_from(byte).unwrap(),
            };
            key_cells[usize::from(key)]
        });
        let mut packed_domain = vec![0_u32; domain_count];
        for (key, &cell) in key_cells.iter().enumerate() {
            packed_domain[key] = pack_native_partial_forward_cell(
                cell.next(),
                cell.accepted(),
                forward_offset,
                row_bytes,
                1,
                false,
                None,
                partial,
                cells,
            )?;
        }
        let mut data = Vec::new();
        if keys == NativeOrdinalMapKeys::Classes {
            data.extend_from_slice(&class_map);
        }
        append_native_bit_slice_record(
            &mut data,
            &packed_domain,
            cells,
            row_bytes,
        )?;
        if data.len() != reverse_offset {
            return Err(ObjectError::InvalidModule(
                "linked bit-slice fixture emitted an unexpected machine extent",
            ));
        }

        let layout = NativeDfaLayout {
            transitions,
            cells,
            bit_slice_domain_count: Some(u16::try_from(domain_count).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked bit-slice domain")
            })?),
            forward_offset: u32::try_from(forward_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked bit-slice forward offset")
            })?,
            reverse_offset: u32::try_from(reverse_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked bit-slice reverse offset")
            })?,
            sparse_boundary_profile: None,
            asimd_lane_index_offset: None,
            initial_pending: false,
            initial_terminal: false,
            start_scanner_preserves_pending: false,
            has_reverse: false,
            partial: Some(partial),
            exact_span_width: (output == OutputContract::Span).then_some(1),
            exact_prefix_match_width: None,
            output,
            start_filter: None,
            exact_start_byte_set: None,
            exact_start_storage: None,
            suffix_filter: None,
            mandatory_teddy: None,
            declined_redundant_root_reverse: false,
            seeded_reverse: None,
            loop_skip: None,
            loop_skip_secondary: None,
            vector_filter: None,
            prefix_filter: None,
            prefix_relation: None,
            prefix_block: None,
            prefix_fast_forward: None,
        };
        let emission = match target.architecture {
            Architecture::X86_64 => lower_x86_64_dfa_with_entry_contract(
                layout,
                target.features,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
            Architecture::Aarch64 => lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
                layout,
                target.features,
                target.operating_system,
                None,
                None,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
        };
        Ok((
            NativeLowering {
                code: emission.code,
                data,
                relocations: emission.relocations,
                slow_partial_table: None,
                needs_runtime: false,
                start_accelerator: StartAccelerator::Scalar,
                anchored_prefix_filter_bytes: 0,
                synchronizing_accept_reverse_lowered: false,
            },
            LinkedSparseNativeFixture {
                byte_cells,
                partial,
            },
        ))
    }

    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_arguments,
        clippy::too_many_lines,
        reason = "the linked fixture constructs one exact map-first dictionary row and its independent byte oracle"
    )]
    fn linked_ordinal_offset_native_fixture(
        target: Target,
        cells: NativeCellEncoding,
        collapse_holes: bool,
        output: OutputContract,
    ) -> Result<(NativeLowering, LinkedSparseNativeFixture), ObjectError> {
        const DOMAIN_COUNT: usize = 64;
        const VALUE_CAPACITY: u8 = 4;
        assert!(native_ordinal_offset_map_is_eligible(
            VALUE_CAPACITY,
            DOMAIN_COUNT,
            cells,
        ));
        let transitions = TransitionLayout::OrdinalOffsetClasses(VALUE_CAPACITY);
        let row_bytes = native_ordinal_map_row_bytes(VALUE_CAPACITY, DOMAIN_COUNT, cells)
            .expect("linked ordinal offset row geometry");
        let forward_offset = native_table_prefix_bytes(transitions, cells, DOMAIN_COUNT)
            .expect("linked ordinal offset table prefix");
        let reverse_offset = forward_offset
            .checked_add(row_bytes)
            .ok_or(ObjectError::ArithmeticOverflow(
                "linked ordinal offset machine extent",
            ))?;
        let last_live_token = encode_native_row_offset(forward_offset, cells).ok_or(
            ObjectError::InvalidModule("linked ordinal offset initial row token"),
        )?;
        let partial = NativePartialDfaLayout {
            hole_token_base: u32::try_from(last_live_token.checked_add(1).ok_or(
                ObjectError::ArithmeticOverflow("linked ordinal offset hole base"),
            )?)
            .map_err(|_| ObjectError::ArithmeticOverflow("linked ordinal offset hole base"))?,
            resume_states: 4,
            collapse_holes,
        };

        let class_map: [u8; CLASS_MAP_BYTES] = core::array::from_fn(|byte| {
            u8::try_from((byte * 73 + 19) % DOMAIN_COUNT).unwrap()
        });
        let key_cells: [ForwardCell; DOMAIN_COUNT] = core::array::from_fn(|key| {
            match key % 5 {
                0 => ForwardCell::new(0, false),
                1 => ForwardCell::new(0, true),
                2 => ForwardCell::new(NO_DFA_STATE, false),
                3 => ForwardCell::new(1, false),
                _ => ForwardCell::new(2, true),
            }
        });
        let byte_cells = core::array::from_fn(|byte| {
            key_cells[usize::from(class_map[byte])]
        });
        let mut packed_domain = [0_u32; DOMAIN_COUNT];
        for (key, &cell) in key_cells.iter().enumerate() {
            packed_domain[key] = pack_native_partial_forward_cell(
                cell.next(),
                cell.accepted(),
                forward_offset,
                row_bytes,
                1,
                false,
                None,
                partial,
                cells,
            )?;
        }
        let mut data = class_map.to_vec();
        append_native_ordinal_map_record(
            &mut data,
            &packed_domain,
            VALUE_CAPACITY,
            cells,
            row_bytes,
            true,
        )?;
        if data.len() != reverse_offset {
            return Err(ObjectError::InvalidModule(
                "linked ordinal offset fixture emitted an unexpected machine extent",
            ));
        }

        let layout = NativeDfaLayout {
            transitions,
            cells,
            bit_slice_domain_count: None,
            forward_offset: u32::try_from(forward_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked ordinal offset forward offset")
            })?,
            reverse_offset: u32::try_from(reverse_offset).map_err(|_| {
                ObjectError::ArithmeticOverflow("linked ordinal offset reverse offset")
            })?,
            sparse_boundary_profile: None,
            asimd_lane_index_offset: None,
            initial_pending: false,
            initial_terminal: false,
            start_scanner_preserves_pending: false,
            has_reverse: false,
            partial: Some(partial),
            exact_span_width: (output == OutputContract::Span).then_some(1),
            exact_prefix_match_width: None,
            output,
            start_filter: None,
            exact_start_byte_set: None,
            exact_start_storage: None,
            suffix_filter: None,
            mandatory_teddy: None,
            declined_redundant_root_reverse: false,
            seeded_reverse: None,
            loop_skip: None,
            loop_skip_secondary: None,
            vector_filter: None,
            prefix_filter: None,
            prefix_relation: None,
            prefix_block: None,
            prefix_fast_forward: None,
        };
        let emission = match target.architecture {
            Architecture::X86_64 => lower_x86_64_dfa_with_entry_contract(
                layout,
                target.features,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
            Architecture::Aarch64 => lower_aarch64_dfa_with_entry_contract_and_suffix_kind(
                layout,
                target.features,
                target.operating_system,
                None,
                None,
                NativeDfaEntryContract::PreparedPartialCore,
            )?,
        };
        Ok((
            NativeLowering {
                code: emission.code,
                data,
                relocations: emission.relocations,
                slow_partial_table: None,
                needs_runtime: false,
                start_accelerator: StartAccelerator::Scalar,
                anchored_prefix_filter_bytes: 0,
                synchronizing_accept_reverse_lowered: false,
            },
            LinkedSparseNativeFixture {
                byte_cells,
                partial,
            },
        ))
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the two-byte exhaustive oracle advances a cursor within a validated window"
    )]
    fn linked_sparse_expected(
        fixture: LinkedSparseNativeFixture,
        output: OutputContract,
        haystack: [u8; 2],
        start: usize,
        end: usize,
    ) -> LinkedSparseExpected {
        let mut pending = None;
        for position in start..end {
            let cell = fixture.byte_cells[usize::from(haystack[position])];
            let next_position = position + 1;
            if cell.accepted() {
                if output == OutputContract::Exists {
                    return LinkedSparseExpected {
                        status: 1,
                        first: None,
                        second: None,
                        position: None,
                    };
                }
                pending = Some(next_position);
            }
            match cell.next() {
                NO_DFA_STATE => break,
                0 => {}
                next => {
                    if next_position == end {
                        break;
                    }
                    let resume = usize::try_from(next - 1).unwrap();
                    return LinkedSparseExpected {
                        status: NATIVE_PARTIAL_STATUS_RESUME,
                        first: Some(if fixture.partial.collapse_holes {
                            0
                        } else {
                            resume
                        }),
                        second: pending,
                        position: Some(next_position),
                    };
                }
            }
        }
        let Some(selected_end) = pending else {
            return LinkedSparseExpected {
                status: 0,
                first: None,
                second: None,
                position: None,
            };
        };
        match output {
            OutputContract::Exists => unreachable!("Exists returns at its accepting edge"),
            OutputContract::SelectedEnd => LinkedSparseExpected {
                status: 1,
                first: None,
                second: Some(selected_end),
                position: None,
            },
            OutputContract::Span => LinkedSparseExpected {
                status: 1,
                first: Some(selected_end - 1),
                second: Some(selected_end),
                position: None,
            },
        }
    }

    #[allow(
        clippy::arithmetic_side_effects,
        reason = "the two-row oracle advances only within its validated search window"
    )]
    fn linked_hybrid_sparse_expected(
        fixture: LinkedHybridSparseNativeFixture,
        haystack: &[u8],
    ) -> LinkedSparseExpected {
        let mut state = 0_usize;
        let mut pending = None;
        for (position, &byte) in haystack.iter().enumerate() {
            let cell = fixture.byte_cells[state][usize::from(byte)];
            let next_position = position + 1;
            if cell.accepted() {
                pending = Some(next_position);
            }
            match cell.next() {
                NO_DFA_STATE => break,
                next @ 0..=1 => {
                    state = usize::try_from(next).unwrap();
                }
                next => {
                    if next_position == haystack.len() {
                        break;
                    }
                    let resume = usize::try_from(next - 2).unwrap();
                    return LinkedSparseExpected {
                        status: NATIVE_PARTIAL_STATUS_RESUME,
                        first: Some(if fixture.partial.collapse_holes {
                            0
                        } else {
                            resume
                        }),
                        second: pending,
                        position: Some(next_position),
                    };
                }
            }
        }
        let Some(selected_end) = pending else {
            return LinkedSparseExpected {
                status: 0,
                first: None,
                second: None,
                position: None,
            };
        };
        LinkedSparseExpected {
            status: 1,
            first: None,
            second: Some(selected_end),
            position: None,
        }
    }

    #[cfg(target_arch = "x86_64")]
    fn linked_sparse_host_target() -> Target {
        let base = if cfg!(target_os = "linux") {
            Target::x86_64_linux()
        } else {
            Target::x86_64_macos()
        };
        let features = match std::env::var("FRE_AOT_SPARSE_LINK_TIER").as_deref() {
            Ok("avx2") => {
                assert!(std::arch::is_x86_feature_detected!("avx2"));
                FeatureSet::of(CpuFeature::X86Avx2)
            }
            Ok("avx512") => {
                assert!(std::arch::is_x86_feature_detected!("avx512f"));
                assert!(std::arch::is_x86_feature_detected!("avx512bw"));
                FeatureSet::of(CpuFeature::X86Avx512F)
                    .with(CpuFeature::X86Avx512Bw)
            }
            Ok("sse2") | Err(_) => FeatureSet::EMPTY,
            Ok(tier) => panic!("unsupported x86 sparse linked tier {tier:?}"),
        };
        base.with_features(features).unwrap()
    }

    #[cfg(target_arch = "aarch64")]
    fn linked_sparse_host_target() -> Target {
        let base = if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let features = match std::env::var("FRE_AOT_SPARSE_LINK_TIER").as_deref() {
            Ok("scalar") => FeatureSet::EMPTY,
            Ok("sve") => {
                assert!(cfg!(target_os = "linux"));
                assert!(std::arch::is_aarch64_feature_detected!("sve"));
                FeatureSet::of(CpuFeature::Aarch64Sve)
            }
            Ok("sve2") => {
                assert!(cfg!(target_os = "linux"));
                assert!(std::arch::is_aarch64_feature_detected!("sve"));
                assert!(std::arch::is_aarch64_feature_detected!("sve2"));
                FeatureSet::of(CpuFeature::Aarch64Sve)
                    .with(CpuFeature::Aarch64Sve2)
            }
            Ok("asimd-sve2") => {
                assert!(cfg!(target_os = "linux"));
                assert!(std::arch::is_aarch64_feature_detected!("sve"));
                assert!(std::arch::is_aarch64_feature_detected!("sve2"));
                asimd
                    .with(CpuFeature::Aarch64Sve)
                    .with(CpuFeature::Aarch64Sve2)
            }
            Ok("asimd") | Err(_) => asimd,
            Ok(tier) => panic!("unsupported AArch64 sparse linked tier {tier:?}"),
        };
        base.with_features(features).unwrap()
    }

    #[cfg(target_arch = "x86_64")]
    fn append_linked_sparse_wrapper_assembly(
        source: &mut String,
        index: usize,
        symbol: &str,
    ) {
        use std::fmt::Write as _;

        let prefix = if cfg!(target_os = "macos") { "_" } else { "" };
        let wrapper = format!("{prefix}fre_sparse_wrap_{index}");
        let core = format!("{prefix}{symbol}");
        writeln!(source, ".p2align 4\n.globl {wrapper}").unwrap();
        if cfg!(target_os = "linux") {
            writeln!(source, ".type {wrapper},@function").unwrap();
        }
        writeln!(source, "{wrapper}:").unwrap();
        source.push_str(
            "pushq %rbx\npushq %rbp\npushq %r12\npushq %r13\npushq %r14\npushq %r15\npushq %r9\n\
             movq $0x919,%rbx\nmovq $0x920,%rbp\nmovq $0x912,%r12\nmovq $0x913,%r13\n\
             movq $0x914,%r14\nmovq $0x915,%r15\n",
        );
        writeln!(source, "call {core}").unwrap();
        writeln!(
            source,
            "popq %r9\nmovq %r10,0(%r9)\nmovq %r11,8(%r9)\nmovq %rdx,16(%r9)\n\
             movq $0,24(%r9)\ncmpq $0x919,%rbx\njne .Lfre_sparse_bad_{index}\n\
             cmpq $0x920,%rbp\njne .Lfre_sparse_bad_{index}\ncmpq $0x912,%r12\n\
             jne .Lfre_sparse_bad_{index}\ncmpq $0x913,%r13\njne .Lfre_sparse_bad_{index}\n\
             cmpq $0x914,%r14\njne .Lfre_sparse_bad_{index}\ncmpq $0x915,%r15\n\
             jne .Lfre_sparse_bad_{index}\njmp .Lfre_sparse_restore_{index}\n\
             .Lfre_sparse_bad_{index}:\nmovq $1,24(%r9)\n.Lfre_sparse_restore_{index}:\n\
             popq %r15\npopq %r14\npopq %r13\npopq %r12\npopq %rbp\npopq %rbx\nret"
        )
        .unwrap();
        if cfg!(target_os = "linux") {
            writeln!(source, ".size {wrapper},.-{wrapper}").unwrap();
        }
    }

    #[cfg(target_arch = "aarch64")]
    fn append_linked_sparse_wrapper_assembly(
        source: &mut String,
        index: usize,
        symbol: &str,
    ) {
        use std::fmt::Write as _;

        let prefix = if cfg!(target_os = "macos") { "_" } else { "" };
        let wrapper = format!("{prefix}fre_sparse_wrap_{index}");
        let core = format!("{prefix}{symbol}");
        writeln!(source, ".p2align 4\n.globl {wrapper}").unwrap();
        if cfg!(target_os = "linux") {
            writeln!(source, ".type {wrapper},%function").unwrap();
        }
        writeln!(source, "{wrapper}:").unwrap();
        source.push_str(
            "sub sp,sp,#240\nstp x19,x20,[sp,#0]\nstp x21,x22,[sp,#16]\n\
             stp x23,x24,[sp,#32]\nstp x25,x26,[sp,#48]\nstp x27,x28,[sp,#64]\n\
             stp x29,x30,[sp,#80]\nstp q8,q9,[sp,#96]\nstp q10,q11,[sp,#128]\n\
             stp q12,q13,[sp,#160]\nstp q14,q15,[sp,#192]\nstr x5,[sp,#224]\n\
             mov x19,#0x919\nmov x20,#0x920\nmov x21,#0x921\nmov x22,#0x922\n\
             mov x23,#0x923\nmov x24,#0x924\nmov x25,#0x925\nmov x26,#0x926\n\
             mov x27,#0x927\nmov x28,#0x928\nmov x29,#0x929\n\
             mov x10,#0x808\nfmov d8,x10\nmov x10,#0x809\nfmov d9,x10\n\
             mov x10,#0x80a\nfmov d10,x10\nmov x10,#0x80b\nfmov d11,x10\n\
             mov x10,#0x80c\nfmov d12,x10\nmov x10,#0x80d\nfmov d13,x10\n\
             mov x10,#0x80e\nfmov d14,x10\nmov x10,#0x80f\nfmov d15,x10\n",
        );
        writeln!(source, "bl {core}").unwrap();
        writeln!(
            source,
            "ldr x9,[sp,#224]\nstp x6,x7,[x9,#0]\nstr x2,[x9,#16]\nstr xzr,[x9,#24]\n\
             cmp x19,#0x919\nb.ne .Lfre_sparse_bad_{index}\ncmp x20,#0x920\nb.ne .Lfre_sparse_bad_{index}\n\
             cmp x21,#0x921\nb.ne .Lfre_sparse_bad_{index}\ncmp x22,#0x922\nb.ne .Lfre_sparse_bad_{index}\n\
             cmp x23,#0x923\nb.ne .Lfre_sparse_bad_{index}\ncmp x24,#0x924\nb.ne .Lfre_sparse_bad_{index}\n\
             cmp x25,#0x925\nb.ne .Lfre_sparse_bad_{index}\ncmp x26,#0x926\nb.ne .Lfre_sparse_bad_{index}\n\
             cmp x27,#0x927\nb.ne .Lfre_sparse_bad_{index}\ncmp x28,#0x928\nb.ne .Lfre_sparse_bad_{index}\n\
             cmp x29,#0x929\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d8\ncmp x11,#0x808\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d9\ncmp x11,#0x809\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d10\ncmp x11,#0x80a\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d11\ncmp x11,#0x80b\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d12\ncmp x11,#0x80c\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d13\ncmp x11,#0x80d\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d14\ncmp x11,#0x80e\nb.ne .Lfre_sparse_bad_{index}\n\
             fmov x11,d15\ncmp x11,#0x80f\nb.ne .Lfre_sparse_bad_{index}\n\
             b .Lfre_sparse_restore_{index}\n.Lfre_sparse_bad_{index}:\nmov x10,#1\nstr x10,[x9,#24]\n\
             .Lfre_sparse_restore_{index}:\nldp q14,q15,[sp,#192]\nldp q12,q13,[sp,#160]\n\
             ldp q10,q11,[sp,#128]\nldp q8,q9,[sp,#96]\nldp x29,x30,[sp,#80]\n\
             ldp x27,x28,[sp,#64]\nldp x25,x26,[sp,#48]\nldp x23,x24,[sp,#32]\n\
             ldp x21,x22,[sp,#16]\nldp x19,x20,[sp,#0]\nadd sp,sp,#240\nret"
        )
        .unwrap();
        if cfg!(target_os = "linux") {
            writeln!(source, ".size {wrapper},.-{wrapper}").unwrap();
        }
    }

    fn build_forced_exact_row_intern_table(
        view: NativeProgramView<'_>,
        architecture: Architecture,
        vector_cost_model: NativeVectorFilterCostModel,
        relation_vector_owns_route: bool,
        maximum: usize,
    ) -> Result<(Vec<u8>, NativeDfaLayout), ObjectError> {
        let plan = derive_native_exact_row_intern_plan(
            view.dfa,
            view.partial_discovered_states,
            view.collapse_partial_holes,
        )
        .expect("synthetic exact-row intern plan");
        build_native_dfa_table_with_cost_model_and_data_limit_once_with_exact_rows(
            view,
            architecture,
            vector_cost_model,
            relation_vector_owns_route,
            maximum,
            None,
            Some(&plan),
            false,
            None,
        )
    }

