    #[test]
    fn ordered_finite_sparse_rows_compact_and_authenticate_large_languages() {
        let compiled = ordered_finite_test_program(
            &dense_correlated_finite_pattern(true),
            OutputContract::Span,
        );
        let view = compiled
            .program()
            .native_finite_language_view()
            .expect("large finite-language sidecar");
        let dense = native_finite_language_dense_layout(view)
            .expect("large fixture still retains optional complete rows");
        let sparse = native_finite_language_sparse_layout(view)
            .expect("large fixture compact failure rows");
        assert_eq!(sparse.representation, NativeFiniteLanguageRepresentation::SparseFailure);
        assert!(sparse.required_data_bytes < dense.required_data_bytes);
        assert_eq!(
            usize::try_from(sparse.sparse_edge_count).unwrap(),
            view.sparse_transition_count(),
        );
        assert_eq!(view.sparse_transition_count(), view.state_count() - 1);

        let data = materialize_native_finite_language_data(view, sparse)
            .expect("finite native allocation")
            .expect("materialize compact finite image");
        assert!(validate_native_finite_language_data(view, sparse, &data).is_some());
        let mut damaged = data;
        let first_meta = usize::try_from(sparse.row_offset).unwrap() + 4;
        damaged[first_meta] ^= 1;
        assert!(validate_native_finite_language_data(view, sparse, &damaged).is_none());

        let (lowering, report) = lower_optional_native_finite_language_with_data_limit(
            view,
            Target::x86_64_linux(),
            sparse.required_data_bytes,
        )
        .unwrap()
        .expect("compact image survives a ceiling below dense rows");
        assert_eq!(lowering.data.len(), sparse.required_data_bytes);
        assert_eq!(report.native_data_bytes, sparse.required_data_bytes);

        let selected = compile_ordered_finite_sparse_native_fallback(
            &dense_correlated_finite_pattern(true),
            OutputContract::Span,
            Target::x86_64_linux(),
        );
        assert!(selected.receipt().ordered_finite_language_aot.is_some());
    }

    #[test]
    fn ordered_finite_sparse_backends_follow_failure_links_on_both_isas() {
        let compiled = ordered_finite_test_program(
            &dense_correlated_finite_pattern(true),
            OutputContract::Span,
        );
        let view = compiled.program().native_finite_language_view().unwrap();
        let layout = native_finite_language_sparse_layout(view).unwrap();
        let (x86, x86_relocations) =
            lower_x86_64_native_finite_language(OutputContract::Span, layout).unwrap();
        assert!(x86.windows(4).any(|bytes| bytes == [0x44, 0x8b, 0x5b, 0x04]));
        assert!(x86.windows(4).any(|bytes| bytes == [0x41, 0x83, 0xfb, 0x01]));
        assert!(x86.windows(4).any(|bytes| bytes == [0x41, 0x83, 0xfb, 0x04]));
        assert!(x86.windows(2).any(|bytes| bytes == [0x8b, 0x1b]));
        assert!(
            x86.windows(4).any(|bytes| bytes == [0x48, 0x83, 0xfe, 0x04]),
            "sparse x86 must batch four independent root probes",
        );
        assert!(
            x86.windows(4).any(|bytes| bytes == [0x48, 0x83, 0xc2, 0x04]),
            "sparse x86 root misses must advance one four-byte batch",
        );
        assert!(x86.windows(2).any(|bytes| bytes == [0x09, 0xf0]));
        assert!(x86.windows(3).any(|bytes| bytes == [0x44, 0x09, 0xd8]));
        assert!(x86.windows(3).any(|bytes| bytes == [0x44, 0x09, 0xe8]));
        assert!(x86.windows(4).any(|bytes| bytes == [0xc6, 0x04, 0x24, 0x01]));
        assert!(x86.windows(4).any(|bytes| bytes == [0x48, 0x83, 0xc4, 0x08]));
        assert!(
            x86.windows(5)
                .filter(|bytes| *bytes == [0x41, 0x0f, 0xb7, 0x34, 0x41])
                .count()
                >= 2,
            "sparse x86 must retain separate root-only and failure-retry loads",
        );
        assert!(
            x86.windows(2)
                .filter(|bytes| *bytes == [0x85, 0xf6])
                .count()
                >= 2,
            "both x86 root loads must recognize the zero root-row token",
        );
        assert_eq!(x86_relocations.len(), 1);

        let (aarch64, aarch64_relocations) =
            lower_aarch64_native_finite_language(OutputContract::Span, layout).unwrap();
        let words = aarch64
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert!(words.contains(&aarch64_load_w_imm(12, 6, 4).unwrap()));
        assert!(words.contains(&aarch64_load_w_imm(14, 6, 0).unwrap()));
        assert!(words.contains(&aarch64_cmp_w_imm(12, 1).unwrap()));
        assert!(words.contains(&aarch64_cmp_w_imm(12, 4).unwrap()));
        assert!(words.contains(&aarch64_cmp_x_imm(1, 4).unwrap()));
        assert!(words.contains(&aarch64_orr_w(7, 7, 8).unwrap()));
        assert!(words.contains(&aarch64_orr_w(7, 7, 12).unwrap()));
        assert!(words.contains(&aarch64_orr_w(7, 7, 14).unwrap()));
        assert!(words.contains(&aarch64_add_x_imm(2, 2, 4).unwrap()));
        assert!(words.contains(&aarch64_sub_x_imm(31, 31, 16).unwrap()));
        assert!(words.contains(&aarch64_store_x(1, 31, 0).unwrap()));
        assert!(words.contains(&aarch64_load_w_imm(1, 31, 0).unwrap()));
        assert!(words.contains(&aarch64_add_x_imm(31, 31, 16).unwrap()));
        assert!(
            words
                .iter()
                .filter(|&&word| word == aarch64_load_h_uxtw(14, 5, 7).unwrap())
                .count()
                >= 2,
            "sparse AArch64 must retain separate root-only and failure-retry loads",
        );
        assert_eq!(aarch64_relocations.len(), 2);
    }

    fn dense_correlated_finite_pattern(variable_width: bool) -> String {
        let mut pattern = String::from("(?-u:");
        for byte in 0_u8..65 {
            if byte != 0 {
                pattern.push('|');
            }
            for _ in 0..8 {
                pattern.push_str(&format!("\\x{byte:02x}"));
            }
            if variable_width && byte == 64 {
                pattern.push_str("\\x40");
            }
        }
        pattern.push(')');
        pattern
    }

    fn cache_large_branching_finite_pattern(roots: u8, branches: u8, width: usize) -> String {
        let mut pattern = String::from("(?-u:");
        let mut ordinal = 0_usize;
        for root in 0_u8..roots {
            for branch in 0_u8..branches {
                if ordinal != 0 {
                    pattern.push('|');
                }
                pattern.push_str(&format!("\\x{root:02x}\\x{branch:02x}"));
                let tail = root.wrapping_add(branch) % roots;
                for _ in 2..width {
                    pattern.push_str(&format!("\\x{tail:02x}"));
                }
                ordinal += 1;
            }
        }
        pattern.push(')');
        pattern
    }

    #[test]
    fn cache_large_compressed_binary_tries_select_compact_rows_before_the_hard_ceiling() {
        let compiled = ordered_finite_test_program(
            &cache_large_branching_finite_pattern(64, 2, 18),
            OutputContract::Span,
        );
        let view = compiled
            .program()
            .native_finite_language_view()
            .expect("cache-large finite-language sidecar");
        let dense = native_finite_language_dense_layout(view)
            .expect("cache-large fixture complete rows");
        let sparse = native_finite_language_sparse_layout(view)
            .expect("cache-large fixture compact rows");
        let dense_cost = NativeFiniteLanguageCost::estimate(view, dense).unwrap();
        let sparse_cost = NativeFiniteLanguageCost::estimate(view, sparse).unwrap();
        assert!(sparse_cost.one_edge_states * 2 >= sparse_cost.states);
        assert_eq!(sparse_cost.root_bytes, 64);
        assert_eq!(sparse_cost.source_count, 128);
        assert_eq!(sparse_cost.leaf_states, 128);
        assert_eq!(sparse_cost.two_edge_states, 64);
        assert_eq!(
            sparse_cost.leaf_states
                + sparse_cost.one_edge_states
                + sparse_cost.two_edge_states,
            sparse_cost.states - 1,
        );
        assert!(sparse_cost.compact_working_set_preferred_to(dense_cost));
        assert!(sparse_cost.preferred_to(Some(dense_cost)));
        assert!(!dense_cost.preferred_to(Some(sparse_cost)));
        assert!(!NativeFiniteLanguageCost {
            leaf_states: 0,
            ..sparse_cost
        }
        .compact_working_set_preferred_to(dense_cost));
        assert!(!NativeFiniteLanguageCost {
            two_edge_states: 0,
            ..sparse_cost
        }
        .compact_working_set_preferred_to(dense_cost));
        let low_coverage_one_edge_states = sparse_cost.states / 2;
        assert!(!NativeFiniteLanguageCost {
            leaf_states: sparse_cost
                .leaf_states
                .checked_add(
                    sparse_cost
                        .one_edge_states
                        .checked_sub(low_coverage_one_edge_states)
                        .unwrap(),
                )
                .unwrap(),
            one_edge_states: low_coverage_one_edge_states,
            ..sparse_cost
        }
        .compact_working_set_preferred_to(dense_cost));
        assert!(!sparse_cost.compact_working_set_preferred_to(NativeFiniteLanguageCost {
            data_bytes: 512 * 1024 - 1,
            ..dense_cost
        }));
        assert!(!NativeFiniteLanguageCost {
            data_bytes: dense_cost.data_bytes / 8 + 1,
            ..sparse_cost
        }
        .compact_working_set_preferred_to(dense_cost));
        let (lowering, report) = lower_optional_native_finite_language_with_data_limit(
            view,
            Target::x86_64_linux(),
            usize::MAX,
        )
        .unwrap()
        .expect("compact working-set lowering");
        assert!(report.sparse_failure);
        assert_eq!(lowering.data.len(), sparse.required_data_bytes);
        assert!(sparse.required_data_bytes * 8 <= dense.required_data_bytes);
    }

    #[test]
    fn structurally_preferred_finite_language_competes_before_complete_dfa() {
        let pattern = dense_correlated_finite_pattern(true);
        for target in [
            Target::x86_64_linux(),
            Target::x86_64_macos(),
            Target::aarch64_linux(),
            Target::aarch64_macos(),
        ] {
            let compiled = compile(
                CompileRequest::new(pattern.clone(), target)
                    .mode(CompileMode::Optimizing)
                    .output(OutputContract::Span),
            )
            .expect("compile early finite-language portfolio fixture");
            assert_eq!(compiled.receipt().engine, EngineKind::OrderedDfa);
            assert!(compiled.receipt().dfa.is_some());
            let finite_view = compiled
                .program()
                .native_finite_language_view()
                .expect("authenticated finite-language sidecar");
            let finite_layout = native_finite_language_layout(finite_view)
                .expect("finite-language target-neutral layout");
            let finite_cost = NativeFiniteLanguageCost::estimate(finite_view, finite_layout)
                .expect("finite-language structural cost");
            let complete_view = compiled
                .program()
                .native_dfa_view()
                .expect("complete semantic DFA remains in the stable program");
            let complete_cost = NativeCompleteDfaCost::estimate(&complete_view)
                .expect("valid complete-DFA cost")
                .expect("variable-width Span comparison");
            assert!(
                compiled.receipt().ordered_finite_language_aot.is_some(),
                "finite={finite_cost:?} complete={complete_cost:?}",
            );
            assert!(compiled.module().required_runtime_symbol().is_none());
            assert_eq!(compiled.receipt().start_accelerator, StartAccelerator::None);
            assert!(
                compiled
                    .receipt()
                    .passes
                    .contains(&crate::OptimizationPass::OrderedFiniteLanguageLowering),
            );
            assert!(
                !compiled
                    .receipt()
                    .passes
                    .contains(&crate::OptimizationPass::UniversalOrderedTnfa),
            );
            assert!(!complete_cost.has_accelerator);
            assert!(finite_cost.transition_cells < complete_cost.transition_cells);
            assert!(finite_cost.data_bytes < complete_cost.minimum_data_bytes);
            assert!(finite_cost.minimum_width >= 8);
            assert!(finite_cost.preferred_to_complete_dfa(complete_cost));
        }
    }

    #[test]
    fn early_finite_portfolio_preserves_faster_complete_dfa_routes() {
        let fixed = compile(
            CompileRequest::new(
                dense_correlated_finite_pattern(false),
                Target::x86_64_linux(),
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::Span),
        )
        .expect("compile exact-width finite control");
        assert_eq!(fixed.receipt().engine, EngineKind::OrderedDfa);
        assert!(fixed.receipt().exact_match_width.is_some());
        assert!(fixed.receipt().ordered_finite_language_aot.is_none());

        let exists = compile(
            CompileRequest::new(
                dense_correlated_finite_pattern(true),
                Target::x86_64_linux(),
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::Exists),
        )
        .expect("compile one-pass Exists control");
        assert_eq!(exists.receipt().engine, EngineKind::OrderedDfa);
        assert!(exists.program().native_finite_language_view().is_some());
        assert!(
            NativeCompleteDfaCost::estimate(
                &exists
                    .program()
                    .native_dfa_view()
                    .expect("complete Exists semantic DFA"),
            )
            .expect("valid Exists DFA")
            .is_none(),
        );
        assert!(exists.receipt().ordered_finite_language_aot.is_none());
        assert!(exists.module().required_runtime_symbol().is_none());

        let accelerated = ordered_finite_test_program("a|ab|bab|ba", OutputContract::Span);
        let complete_view = accelerated
            .program()
            .native_dfa_view()
            .expect("complete accelerated semantic DFA");
        let complete_cost = NativeCompleteDfaCost::estimate(&complete_view)
            .expect("valid accelerated complete-DFA cost")
            .expect("variable-width Span comparison");
        assert!(complete_cost.has_accelerator);
        assert!(accelerated.receipt().ordered_finite_language_aot.is_none());
        assert_ne!(accelerated.receipt().start_accelerator, StartAccelerator::None);

        let variable_pattern = dense_correlated_finite_pattern(true);
        let admitted = compile(
            CompileRequest::new(variable_pattern.clone(), Target::x86_64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Span),
        )
        .expect("compile admitted early finite candidate");
        let finite_bytes = admitted
            .receipt()
            .ordered_finite_language_aot
            .expect("early finite receipt")
            .native_data_bytes;
        let bounded = crate::compile_with_slow_aot_limits(
            CompileRequest::new(variable_pattern, Target::x86_64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Span),
            SlowAotLimits {
                max_native_data_bytes: finite_bytes
                    .checked_sub(1)
                    .expect("finite image is nonempty"),
                ..SlowAotLimits::default()
            },
        )
        .expect("finite data decline preserves complete semantic DFA");
        assert_eq!(bounded.receipt().engine, EngineKind::OrderedDfa);
        assert!(bounded.receipt().ordered_finite_language_aot.is_none());
        assert!(bounded.module().required_runtime_symbol().is_none());
    }

    struct OrderedFiniteFallbackFixture {
        compiled: CompiledRegex,
        finite_data_bytes: usize,
        prior_owner_data_bytes: usize,
        data_limit: usize,
    }

    fn compile_ordered_finite_native_fallback(
        pattern: &str,
        output: OutputContract,
        target: Target,
    ) -> OrderedFiniteFallbackFixture {
        let probe = compile(
            CompileRequest::new(pattern, target)
                .mode(CompileMode::Optimizing)
                .output(output),
        )
        .expect("compile target-specific finite-language fallback probe");
        let finite_data_bytes = native_finite_language_layout(
            probe
                .program()
                .native_finite_language_view()
                .expect("finite-language fallback probe"),
        )
        .expect("finite-language fallback probe layout")
        .required_data_bytes;
        let prior_owner_data_bytes = probe.module().sections()[PROGRAM_SECTION].bytes().len();
        let data_limit = prior_owner_data_bytes
            .checked_sub(finite_data_bytes)
            .filter(|&gap| gap > 1)
            .and_then(|gap| finite_data_bytes.checked_add(gap / 2))
            .unwrap_or(finite_data_bytes);
        drop(probe);
        let compiled = crate::compile_with_slow_aot_limits(
            CompileRequest::new(pattern, target)
                .mode(CompileMode::Optimizing)
                .output(output)
                .limits(CompileLimitsV1 {
                    determinize: DeterminizeLimits {
                        max_states: 0,
                        ..DeterminizeLimits::default()
                    },
                    ..CompileLimitsV1::default()
                }),
            SlowAotLimits {
                determinize: DeterminizeLimits {
                    max_states: 0,
                    max_transitions: 0,
                    max_work: 0,
                },
                max_allocation_bytes: 8 * 1024 * 1024,
                max_native_data_bytes: data_limit,
            },
        )
        .expect("compile forced ordered finite-language fallback");
        assert_eq!(compiled.receipt().engine, EngineKind::OrderedNfa);
        assert!(!compiled.program().has_nfa_exact_product());
        let view = compiled
            .program()
            .native_finite_language_view()
            .expect("forced fallback retains authenticated finite view");
        let layout = native_finite_language_layout(view).expect("forced fallback row layout");
        assert_eq!(
            compiled.module().sections()[PROGRAM_SECTION].bytes().len(),
            layout.required_data_bytes,
        );
        assert!(compiled.module().required_runtime_symbol().is_none());
        OrderedFiniteFallbackFixture {
            compiled,
            finite_data_bytes,
            prior_owner_data_bytes,
            data_limit,
        }
    }

    fn compile_ordered_finite_sparse_native_fallback(
        pattern: &str,
        output: OutputContract,
        target: Target,
    ) -> CompiledRegex {
        let probe = compile(
            CompileRequest::new(pattern, target)
                .mode(CompileMode::Optimizing)
                .output(output),
        )
        .expect("compile compact finite-language probe");
        let view = probe
            .program()
            .native_finite_language_view()
            .expect("compact finite-language probe sidecar");
        let sparse = native_finite_language_sparse_layout(view)
            .expect("compact finite-language probe layout");
        if let Some(dense) = native_finite_language_dense_layout(view) {
            assert!(sparse.required_data_bytes < dense.required_data_bytes);
        }
        let sparse_bytes = sparse.required_data_bytes;
        drop(probe);

        let compiled = crate::compile_with_slow_aot_limits(
            CompileRequest::new(pattern, target)
                .mode(CompileMode::Optimizing)
                .output(output)
                .limits(CompileLimitsV1 {
                    determinize: DeterminizeLimits {
                        max_states: 0,
                        ..DeterminizeLimits::default()
                    },
                    ..CompileLimitsV1::default()
                }),
            SlowAotLimits {
                determinize: DeterminizeLimits {
                    max_states: 0,
                    max_transitions: 0,
                    max_work: 0,
                },
                max_allocation_bytes: 32 * 1024 * 1024,
                max_native_data_bytes: sparse_bytes,
            },
        )
        .expect("compile compact ordered finite-language fallback");
        assert_eq!(compiled.receipt().engine, EngineKind::OrderedNfa);
        let report = compiled
            .receipt()
            .ordered_finite_language_aot
            .expect("compact finite-language receipt");
        assert!(report.sparse_failure);
        assert_eq!(report.native_data_bytes, sparse_bytes);
        assert_eq!(
            compiled.module().sections()[PROGRAM_SECTION].bytes().len(),
            sparse_bytes,
        );
        assert!(compiled.module().required_runtime_symbol().is_none());
        compiled
    }

    #[test]
    fn ordered_finite_receipt_is_authenticated_and_not_restored() {
        let target = Target::x86_64_linux();
        let output = OutputContract::Span;
        let pattern = "a|ab|bab|ba";
        let fixture = compile_ordered_finite_native_fallback(pattern, output, target);
        assert!(fixture.finite_data_bytes < fixture.data_limit);
        assert!(fixture.data_limit < fixture.prior_owner_data_bytes);
        let compiled = fixture.compiled;
        let view = compiled
            .program()
            .native_finite_language_view()
            .expect("source-derived finite-language sidecar");
        let layout = native_finite_language_layout(view).expect("finite-language layout");
        let report = compiled
            .receipt()
            .ordered_finite_language_aot
            .expect("selected finite-language receipt");

        assert_eq!(
            report,
            OrderedFiniteLanguageAotReport {
                states: view.state_count(),
                classes: view.class_count(),
                transition_cells: view.transition_count(),
                sparse_failure: false,
                stored_transition_records: view.transition_count(),
                sparse_edges_offset: 0,
                row_stride: usize::try_from(layout.row_stride).unwrap(),
                output_in_row_offset: usize::try_from(layout.output_in_row_offset).unwrap(),
                cell_bytes: layout.cells.bytes(),
                maximum_width: usize::try_from(layout.maximum_width).unwrap(),
                source_count: usize::try_from(view.source_count).unwrap(),
                source_bytes: view.total_source_bytes,
                native_data_bytes: layout.required_data_bytes,
            },
        );
        assert_eq!(
            compiled.module().ordered_finite_language_aot_report(),
            Some(&report),
        );
        assert!(compiled.receipt().slow_aot.is_none());
        assert!(compiled.receipt().slow_context_aot.is_none());
        assert!(compiled.receipt().compiler_k0_aot.is_none());
        assert!(!compiled.receipt().runtime_helper_required);
        let passes = &compiled.receipt().passes;
        let finite = passes
            .iter()
            .position(|&pass| pass == crate::OptimizationPass::OrderedFiniteLanguageLowering)
            .expect("ordered finite-language lowering pass");
        let instruction_selection = passes
            .iter()
            .position(|&pass| pass == crate::OptimizationPass::TargetInstructionSelection)
            .expect("target instruction-selection pass");
        assert!(finite < instruction_selection);
        assert!(passes.contains(&crate::OptimizationPass::UniversalOrderedTnfa));
        assert!(!passes.contains(&crate::OptimizationPass::RuntimeAdapterLowering));

        let fast = crate::compile(
            CompileRequest::new(pattern, target)
                .mode(CompileMode::Fast)
                .output(output),
        )
        .expect("compile fast finite-language control");
        assert!(fast.receipt().ordered_finite_language_aot.is_none());
        assert!(
            fast.module()
                .ordered_finite_language_aot_report()
                .is_none()
        );

        let serialized = compiled.program().serialize().expect("serialize fallback");
        let restored = crate::CompiledProgram::deserialize(&serialized)
            .expect("restore finite-language semantic program");
        assert_eq!(restored.serialize().unwrap(), serialized);
        assert!(restored.native_finite_language_view().is_none());
        let restored_module = CompiledModule::lower_optimizing_with_limits(
            &restored,
            target,
            SlowAotLimits {
                determinize: DeterminizeLimits {
                    max_states: 0,
                    max_transitions: 0,
                    max_work: 0,
                },
                max_allocation_bytes: 0,
                max_native_data_bytes: 8 * 1024 * 1024,
            },
        )
        .expect("re-lower restored finite-language semantic program");
        assert!(
            restored_module
                .ordered_finite_language_aot_report()
                .is_none()
        );
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "links and exhaustively executes ordered finite-language scalar objects on the host ISA"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in linked differential keeps all output contracts, windows, and ABI assertions auditable"
    )]
    fn linked_host_ordered_finite_language_matches_fast_for_every_window() {
        use std::{fmt::Write as _, fs, process::Command, time::SystemTime};

        let target = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        let sparse_pattern = dense_correlated_finite_pattern(true);
        let hybrid_pattern = cache_large_branching_finite_pattern(32, 4, 16);
        let mut hybrid_last = vec![2_u8; 16];
        hybrid_last[0] = 31;
        hybrid_last[1] = 3;
        let mut hybrid_near_miss = hybrid_last.clone();
        hybrid_near_miss[15] = 3;
        let mut hybrid_failure_retry = vec![5_u8, 2, 7, 6, 1];
        hybrid_failure_retry.extend(core::iter::repeat_n(7_u8, 14));
        let cases = vec![
            (
                "a|ab|bab|ba",
                generated_byte_strings(b"abz", 3),
                false,
            ),
            (
                "ab|a|ba|bab",
                generated_byte_strings(b"abz", 3),
                false,
            ),
            (
                sparse_pattern.as_str(),
                vec![
                    Vec::new(),
                    vec![0; 7],
                    vec![0; 8],
                    vec![1; 8],
                    vec![64; 8],
                    vec![64; 9],
                    vec![99, 2, 2, 2, 2, 2, 2, 2, 2, 100],
                    vec![99, 98, 2, 2, 2, 2, 2, 2, 2, 2, 100],
                    vec![99, 98, 97, 2, 2, 2, 2, 2, 2, 2, 2, 100],
                ],
                true,
            ),
            (
                hybrid_pattern.as_str(),
                vec![
                    Vec::new(),
                    vec![0; 16],
                    hybrid_last,
                    hybrid_near_miss,
                    hybrid_failure_retry,
                ],
                true,
            ),
        ];
        let nonce = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-ordered-finite-{}-{nonce}",
            std::process::id(),
        ));
        fs::create_dir_all(&directory).expect("create ordered-finite linker directory");
        let mut source = String::from("#include <stdint.h>\n#include <stddef.h>\n");
        let mut calls = String::from("int main(void){size_t r[2];uint32_t s;\n");
        let mut objects = Vec::new();
        let mut artifact = 0_usize;

        for (pattern, haystacks, sparse) in cases {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled = if sparse {
                    compile_ordered_finite_sparse_native_fallback(pattern, output, target)
                } else {
                    compile_ordered_finite_native_fallback(pattern, output, target).compiled
                };
                let reference = compile(
                    CompileRequest::new(pattern, target)
                        .mode(CompileMode::Fast)
                        .output(output),
                )
                .expect("compile fast ordered finite-language reference");
                let symbol = compiled.module().entry_symbol();
                writeln!(
                    source,
                    "extern uint32_t {symbol}(const unsigned char*,size_t,size_t,size_t,size_t*);",
                )
                .expect("write ordered-finite declaration");
                let object = directory.join(format!("case{artifact}.o"));
                fs::write(&object, compiled.object()).expect("write ordered-finite object");
                objects.push(object);

                for (haystack_index, haystack) in haystacks.iter().enumerate() {
                    let bytes = if haystack.is_empty() {
                        "0".to_owned()
                    } else {
                        haystack
                            .iter()
                            .map(u8::to_string)
                            .collect::<Vec<_>>()
                            .join(",")
                    };
                    writeln!(
                        source,
                        "static const unsigned char h{artifact}_{haystack_index}[]={{{bytes}}};",
                    )
                    .expect("write ordered-finite haystack");
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let expected = reference
                                .search(haystack, SearchWindow::new(start, end))
                                .expect("fast ordered-finite expected result");
                            writeln!(
                                calls,
                                "r[0]=91;r[1]=92;s={symbol}(h{artifact}_{haystack_index},{},{start},{end},r);",
                                haystack.len(),
                            )
                            .expect("write ordered-finite call");
                            let failure = 10 + artifact;
                            match expected {
                                MatchResult::Exists(found) => writeln!(
                                    calls,
                                    "if(s!={}||r[0]!=0||r[1]!=0)return {failure};",
                                    u8::from(found),
                                ),
                                MatchResult::SelectedEnd(Some(match_end)) => writeln!(
                                    calls,
                                    "if(s!=1||r[0]!={match_end}||r[1]!={match_end})return {failure};",
                                ),
                                MatchResult::Span(Some((match_start, match_end))) => writeln!(
                                    calls,
                                    "if(s!=1||r[0]!={match_start}||r[1]!={match_end})return {failure};",
                                ),
                                MatchResult::SelectedEnd(None) | MatchResult::Span(None) => {
                                    writeln!(
                                        calls,
                                        "if(s!=0||r[0]!=0||r[1]!=0)return {failure};",
                                    )
                                }
                            }
                            .expect("write ordered-finite result assertion");
                        }
                    }
                }
                writeln!(
                    calls,
                    "r[0]=93;r[1]=94;s={symbol}(h{artifact}_0,(size_t)-1,0,0,r);if(s!=2||r[0]!=93||r[1]!=94)return {};",
                    100 + artifact,
                )
                .expect("write ordered-finite invalid ABI assertion");
                artifact += 1;
            }
        }
        calls.push_str("return 0;}\n");
        source.push_str(&calls);
        let c_path = directory.join("ordered_finite.c");
        let executable = directory.join("ordered_finite");
        fs::write(&c_path, source).expect("write ordered-finite C harness");
        let compiler = if cfg!(target_os = "macos") { "clang" } else { "cc" };
        let status = Command::new(compiler)
            .arg("-O0")
            .arg(&c_path)
            .args(&objects)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link ordered-finite native differential");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute ordered-finite native differential");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr),
        );
        fs::remove_dir_all(&directory).expect("remove ordered-finite linker directory");
    }

