    #[test]
    #[ignore = "links and executes the additive prepared entry against an ABI-checking hole stub"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in native test keeps table tracing, object linking, window checks, and side-exit ABI assertions together"
    )]
    fn linked_host_partial_prepared_entry_falls_back_when_short_and_marshals_long_holes() {
        use std::{fmt::Write as _, fs, process::Command};

        #[derive(Clone, Copy, Debug)]
        struct Hole {
            state: usize,
            position: usize,
            pending_end: Option<usize>,
        }

        fn trace(
            view: &NativePartialProgramView<'_>,
            bytes: &[u8],
            start: usize,
            end: usize,
        ) -> Option<Hole> {
            let mut row = 0_usize;
            let mut position = start;
            let mut pending_end = view.dfa.initial_pending.then_some(start);
            while position < end {
                let class =
                    usize::from(view.dfa.byte_classes[usize::from(*bytes.get(position)?)]);
                let cell = view.dfa.packed_cells.get(row.checked_add(class)?)?.raw();
                position = position.checked_add(1)?;
                if cell & PARTIAL_CELL_ACCEPTED != 0 {
                    pending_end = Some(position);
                }
                let next = cell & !PARTIAL_CELL_ACCEPTED;
                if next == PARTIAL_CELL_DEAD {
                    return None;
                }
                if next >= PARTIAL_CELL_HOLE_BASE {
                    return (position < end).then_some(Hole {
                        state: usize::try_from(next - PARTIAL_CELL_HOLE_BASE).ok()?,
                        position,
                        pending_end,
                    });
                }
                row = usize::try_from(next).ok()?;
            }
            None
        }

        fn c_bytes(bytes: &[u8]) -> String {
            bytes
                .iter()
                .map(u8::to_string)
                .collect::<Vec<_>>()
                .join(",")
        }

        let target = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        let limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 8,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        let compiled = compile(
            CompileRequest::new(
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)|a*",
                target,
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::SelectedEnd)
            .limits(limits),
        )
        .expect("host prepared partial object");
        let view = compiled
            .program()
            .native_partial_dfa_view()
            .expect("host partial native view");
        let public_core = lower_native_dfa(view.native, target)
            .expect("lower public host core")
            .expect("host core preserves its scanner");
        let private_core = &compiled.module().symbols()[PARTIAL_NATIVE_CORE_SYMBOL];
        let removed_entry_bytes = match target.architecture {
            Architecture::X86_64 => 82,
            Architecture::Aarch64 => 84,
        };
        assert_eq!(
            usize::try_from(private_core.size).unwrap(),
            public_core.code.len() - removed_entry_bytes,
            "the linked differential must execute the trusted local core"
        );
        let witness = generated_byte_strings(&[0, b'a', b'b', b'c', b'x', b'y', b'Q', b'z'], 6)
            .into_iter()
            .find_map(|bytes| trace(&view, &bytes, 0, bytes.len()).map(|hole| (bytes, hole)))
            .expect("reachable interior partial hole");
        let (hole_bytes, relative_hole) = witness;
        let window_start = 2_usize;
        let narrowed_start = window_start + 16;
        let window_end = window_start + PARTIAL_DFA_MIN_INPUT_BYTES;
        let mut haystack = vec![b'!'; window_end + 1];
        haystack[narrowed_start..narrowed_start + hole_bytes.len()]
            .copy_from_slice(&hole_bytes);
        let hole = Hole {
            state: relative_hole.state,
            position: relative_hole.position + narrowed_start,
            pending_end: relative_hole.pending_end.map(|end| end + narrowed_start),
        };
        let final_hole_end = hole.position;
        let expected_final = compiled
            .search(&haystack, SearchWindow::new(window_start, final_hole_end))
            .expect("portable final-hole result");
        let (fallback_status, fallback_start, fallback_end) = match expected_final {
            MatchResult::SelectedEnd(Some(end)) => (1_u32, end, end),
            MatchResult::SelectedEnd(None) => (0_u32, 0, 0),
            _ => panic!("unexpected prepared test output contract"),
        };

        let directory = std::env::temp_dir().join(format!(
            "fre-aot-partial-prepared-{}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create prepared linker directory");
        let object = directory.join("prepared.o");
        fs::write(&object, compiled.object()).expect("write prepared object");
        let symbol = compiled
            .module()
            .prepared_entry_symbol()
            .expect("prepared symbol");
        let identity = compiled.program().artifact_identity();
        let pending_end = hole.pending_end.unwrap_or(usize::MAX);
        let mut source = format!(
            "#include <stddef.h>\n#include <stdint.h>\n#include <string.h>\n\
             typedef void *handle_t;typedef struct{{size_t start;size_t end;}} window_t;\n\
             extern uint32_t {symbol}(handle_t,const unsigned char*,size_t,size_t,size_t,size_t*);\n\
             static const unsigned char identity[32]={{{}}};\n\
             static const unsigned char haystack[]={{{}}};\n\
             static int expect_path;static int fallback_calls;static int preflight_calls;\n\
             uint32_t fre_aot_regex_runtime_search_v1(const unsigned char*a,const unsigned char*b,size_t c,size_t d,size_t e,size_t*f){{(void)a;(void)b;(void)c;(void)d;(void)e;(void)f;return 98U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_v1(\
               handle_t h,const unsigned char*p,size_t n,size_t s,size_t e,size_t*r){{\
               fallback_calls++;\
               if(h==(handle_t)0)return 5U;\
               if(p==NULL||r==NULL||s>e||e>n)return 2U;\
               if(h!=(handle_t)(uintptr_t)0x1234U||p!=haystack||n!=sizeof(haystack)||s!={window_start}U)return 89U;\
               if(expect_path==1&&e=={final_hole_end}U){{r[0]={fallback_start}U;r[1]={fallback_end}U;return {fallback_status}U;}}\
               return 89U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_partial_preflight_v1(\
               handle_t h,const unsigned char*p,size_t n,size_t s,size_t e,size_t*r,const unsigned char*d,window_t*w){{\
               preflight_calls++;if(h==(handle_t)0)return 5U;\
               if(p==NULL||r==NULL||d==NULL||w==NULL||s>e||e>n)return 2U;\
               if(h!=(handle_t)(uintptr_t)0x1234U||p!=haystack||n!=sizeof(haystack)||\
                  s!={window_start}U||e!={window_end}U||memcmp(d,identity,32U)!=0)return 88U;\
               if(expect_path==2){{w->start={narrowed_start}U;w->end=e;return 6U;}}\
               if(expect_path==3){{r[0]=321U;r[1]=654U;return 76U;}}return 88U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_from_partial_preflight_compact_v3(\
               handle_t h,const unsigned char*p,size_t n,size_t*r,\
               size_t state,size_t position,size_t pend){{\
               if(expect_path!=2||h!=(handle_t)(uintptr_t)0x1234U||p!=haystack||n!=sizeof(haystack)||\
                  r==NULL||\
                  state!={}U||position!={}U||pend!={pending_end}U)return 90U;\
               r[0]=123U;r[1]=456U;return 77U;}}\n\
             int main(void){{size_t r[2]={{91U,92U}};uint32_t status;\n",
            c_bytes(&identity),
            c_bytes(&haystack),
            hole.state,
            hole.position,
        );
        writeln!(
            source,
            "expect_path=1;fallback_calls=0;preflight_calls=0;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),{window_start}U,{final_hole_end}U,r);if(status!={fallback_status}U||r[0]!={fallback_start}U||r[1]!={fallback_end}U||fallback_calls!=1||preflight_calls!=0)return 10;"
        )
        .unwrap();
        writeln!(
            source,
            "expect_path=2;fallback_calls=0;preflight_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),{window_start}U,{window_end}U,r);if(status!=77U||r[0]!=123U||r[1]!=456U||fallback_calls!=0||preflight_calls!=1)return 11;"
        )
        .unwrap();
        writeln!(
            source,
            "expect_path=3;fallback_calls=0;preflight_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),{window_start}U,{window_end}U,r);if(status!=76U||r[0]!=321U||r[1]!=654U||fallback_calls!=0||preflight_calls!=1)return 12;"
        )
        .unwrap();
        writeln!(
            source,
            "expect_path=0;fallback_calls=0;preflight_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)0,haystack,sizeof(haystack),{window_start}U,{window_end}U,r);if(status!=5U||r[0]!=91U||r[1]!=92U||fallback_calls!=0||preflight_calls!=1)return 13;"
        )
        .unwrap();
        writeln!(
            source,
            "fallback_calls=0;preflight_calls=0;status={symbol}((handle_t)0,haystack,sizeof(haystack),{window_start}U,{window_start}U,r);if(status!=5U||fallback_calls!=1||preflight_calls!=0)return 14;"
        )
        .unwrap();
        writeln!(
            source,
            "fallback_calls=0;preflight_calls=0;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),{window_end}U,{window_start}U,r);if(status!=2U||fallback_calls!=0||preflight_calls!=1)return 15;"
        )
        .unwrap();
        writeln!(
            source,
            "fallback_calls=0;preflight_calls=0;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),sizeof(haystack),sizeof(haystack)+1U,r);if(status!=2U||fallback_calls!=1||preflight_calls!=0)return 16;"
        )
        .unwrap();
        source.push_str("return 0;}\n");
        let c_path = directory.join("prepared.c");
        let executable = directory.join("prepared");
        fs::write(&c_path, source).expect("write prepared C harness");
        let c_compiler = if cfg!(target_os = "macos") {
            "clang"
        } else {
            "cc"
        };
        let status = Command::new(c_compiler)
            .arg("-O0")
            .arg(&c_path)
            .arg(&object)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link prepared native harness");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute prepared native harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        fs::remove_dir_all(&directory).expect("remove prepared linker directory");
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "requires `cargo build -p fre-aot-regex-runtime --lib`; links the real exclusive runtime"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in differential proves real preflight, native rows, K0 continuation, and empty-window fallback in one linked process"
    )]
    fn linked_host_partial_preflight_native_core_and_real_continuation_match_runtime() {
        use std::{fs, process::Command, time::SystemTime};

        fn reaches_interior_hole(
            view: &NativePartialProgramView<'_>,
            bytes: &[u8],
            start: usize,
            end: usize,
        ) -> bool {
            let mut row = 0_usize;
            let mut position = start;
            while position < end {
                let Some(&byte) = bytes.get(position) else {
                    return false;
                };
                let class = usize::from(view.dfa.byte_classes[usize::from(byte)]);
                let Some(index) = row.checked_add(class) else {
                    return false;
                };
                let Some(cell) = view.dfa.packed_cells.get(index).map(|cell| cell.raw())
                else {
                    return false;
                };
                position += 1;
                let next = cell & !PARTIAL_CELL_ACCEPTED;
                if next == PARTIAL_CELL_DEAD {
                    return false;
                }
                if next >= PARTIAL_CELL_HOLE_BASE {
                    return position < end;
                }
                let Ok(next) = usize::try_from(next) else {
                    return false;
                };
                row = next;
            }
            false
        }

        fn c_bytes(bytes: &[u8]) -> String {
            bytes
                .iter()
                .map(u8::to_string)
                .collect::<Vec<_>>()
                .join(",")
        }

        let mut target = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        if cfg!(target_arch = "aarch64") {
            target = target
                .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                .unwrap();
        }
        let limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 8,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        let compiled = compile(
            CompileRequest::new("a+Q|[b-c][a-b]{1,5}(?:x+|y+)", target)
                .mode(CompileMode::Optimizing)
                .output(OutputContract::SelectedEnd)
                .limits(limits),
        )
        .expect("host selective partial object");
        let view = compiled
            .program()
            .native_partial_dfa_view()
            .expect("host selective partial view");
        let witness = generated_byte_strings(&[0, b'a', b'b', b'c', b'x', b'y', b'Q', b'z'], 6)
            .into_iter()
            .find(|bytes| reaches_interior_hole(&view, bytes, 0, bytes.len()))
            .expect("reachable interior hole witness");
        let mut haystack = vec![b'!'; PARTIAL_DFA_MIN_INPUT_BYTES + 64];
        haystack[..witness.len()].copy_from_slice(&witness);
        assert!(reaches_interior_hole(&view, &haystack, 0, haystack.len()));
        assert_eq!(
            compiled
                .module()
                .relocations()
                .iter()
                .filter(|relocation| relocation.symbol == PARTIAL_RUNTIME_SYMBOL)
                .count(),
            1,
            "the known native hole must have exactly one real continuation call"
        );

        let symbol = compiled
            .module()
            .prepared_entry_symbol()
            .expect("prepared selective symbol");
        let (program_symbol, program_len) = compiled
            .module()
            .required_runtime_program()
            .expect("prepared runtime program alias");
        let identity = compiled.program().artifact_identity();

        let current_exe = std::env::current_exe().expect("current test executable");
        let profile_dir = current_exe
            .parent()
            .and_then(std::path::Path::parent)
            .expect("Cargo profile directory");
        let static_runtime = profile_dir.join("libfre_aot_regex_runtime.a");
        assert!(
            static_runtime.is_file(),
            "build the linked runtime first: cargo build -p fre-aot-regex-runtime --lib ({})",
            static_runtime.display()
        );

        let nonce = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-real-partial-{}-{nonce}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create real-runtime linker directory");
        let object = directory.join("prepared.o");
        fs::write(&object, compiled.object()).expect("write prepared object");

        let no_match_len = PARTIAL_DFA_MIN_INPUT_BYTES + 64;
        let source = format!(
            "#include <stddef.h>\n#include <stdint.h>\n\
             typedef void *handle_t;\
             typedef struct{{size_t start;size_t end;}} result_t;\
             typedef struct{{size_t start;size_t end;}} window_t;\n\
             extern const unsigned char {program_symbol}[];\n\
             extern uint32_t {symbol}(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_prepare_exclusive_v1(const unsigned char*,size_t,handle_t*);\n\
             extern uint32_t fre_aot_regex_runtime_search_exclusive_v1(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_search_exclusive_partial_preflight_v1(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*,const unsigned char*,window_t*);\n\
             extern uint32_t fre_aot_regex_runtime_destroy_exclusive_v1(handle_t);\n\
             static const unsigned char identity[32]={{{}}};\n\
             static const unsigned char haystack[]={{{}}};\n\
             static const unsigned char no_match_haystack[{no_match_len}]={{0}};\n\
             static int prepare(handle_t *h){{return fre_aot_regex_runtime_prepare_exclusive_v1({program_symbol},{program_len}U,h)==0U;}}\n\
             static int destroy(handle_t h){{return fre_aot_regex_runtime_destroy_exclusive_v1(h)==0U;}}\n\
             static int run_hole(void){{\
               handle_t probe=0,native=0,baseline=0;result_t pr={{91U,92U}},nr={{93U,94U}},br={{95U,96U}};window_t w={{97U,98U}};\
               if(!prepare(&probe)||!prepare(&native)||!prepare(&baseline))return 10;\
               uint32_t ps=fre_aot_regex_runtime_search_exclusive_partial_preflight_v1(probe,haystack,sizeof(haystack),0U,sizeof(haystack),&pr,identity,&w);\
               if(ps!=6U||w.start!=0U||w.end!=sizeof(haystack))return 11;\
               uint32_t ns={symbol}(native,haystack,sizeof(haystack),0U,sizeof(haystack),&nr);\
               uint32_t bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,haystack,sizeof(haystack),0U,sizeof(haystack),&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return 12;\
               if(!destroy(probe)||!destroy(native)||!destroy(baseline))return 13;return 0;}}\n\
             static int run_native_no_match(void){{\
               handle_t probe=0,native=0,baseline=0;result_t pr={{91U,92U}},nr={{93U,94U}},br={{95U,96U}};window_t w={{97U,98U}};\
               if(!prepare(&probe)||!prepare(&native)||!prepare(&baseline))return 30;\
               uint32_t ps=fre_aot_regex_runtime_search_exclusive_partial_preflight_v1(probe,no_match_haystack,sizeof(no_match_haystack),0U,sizeof(no_match_haystack),&pr,identity,&w);\
               if(ps!=6U||w.start!=0U||w.end!=sizeof(no_match_haystack))return 31;\
               uint32_t ns={symbol}(native,no_match_haystack,sizeof(no_match_haystack),0U,sizeof(no_match_haystack),&nr);\
               uint32_t bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,no_match_haystack,sizeof(no_match_haystack),0U,sizeof(no_match_haystack),&br);\
               if(ns!=0U||nr.start!=0U||nr.end!=0U||ns!=bs||nr.start!=br.start||nr.end!=br.end)return 32;\
               if(!destroy(probe)||!destroy(native)||!destroy(baseline))return 33;return 0;}}\n\
             static int run_empty_window(void){{\
               handle_t native=0,baseline=0;result_t nr={{93U,94U}},br={{95U,96U}};\
               if(!prepare(&native)||!prepare(&baseline))return 20;\
               uint32_t ns={symbol}(native,haystack,sizeof(haystack),0U,0U,&nr);\
               uint32_t bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,haystack,sizeof(haystack),0U,0U,&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return 21;\
               if(!destroy(native)||!destroy(baseline))return 22;return 0;}}\n\
             int main(void){{int status=run_hole();if(status!=0)return status;status=run_native_no_match();if(status!=0)return status;return run_empty_window();}}\n",
            c_bytes(&identity),
            c_bytes(&haystack),
        );
        let c_path = directory.join("prepared.c");
        let executable = directory.join("prepared");
        fs::write(&c_path, source).expect("write real-runtime C harness");
        let c_compiler = if cfg!(target_os = "macos") { "clang" } else { "cc" };
        let status = Command::new(c_compiler)
            .arg("-O0")
            .arg(&c_path)
            .arg(&object)
            .arg(&static_runtime)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link real-runtime native harness");
        assert!(status.success(), "real-runtime native harness failed to link");
        let output = Command::new(&executable)
            .output()
            .expect("execute real-runtime native harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        fs::remove_dir_all(&directory).expect("remove real-runtime linker directory");
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "requires `cargo build -p fre-aot-regex-runtime --lib`; links every output contract against the real exclusive runtime"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in linked differential proves every output contract and the Span selected-end postflight in native machine code"
    )]
    fn linked_host_partial_prepared_all_outputs_match_real_runtime() {
        use std::{fs, process::Command, time::SystemTime};

        fn first_interior_hole(
            view: &NativePartialProgramView<'_>,
            bytes: &[u8],
        ) -> Option<usize> {
            let mut row = 0_usize;
            let mut position = 0_usize;
            while position < bytes.len() {
                let class = usize::from(view.dfa.byte_classes[usize::from(bytes[position])]);
                let cell = view.dfa.packed_cells.get(row.checked_add(class)?)?.raw();
                position = position.checked_add(1)?;
                let next = cell & !PARTIAL_CELL_ACCEPTED;
                if next == PARTIAL_CELL_DEAD {
                    return None;
                }
                if next >= PARTIAL_CELL_HOLE_BASE {
                    return (position < bytes.len()).then_some(position);
                }
                row = usize::try_from(next).ok()?;
            }
            None
        }

        fn local_selected_end(
            view: &NativePartialProgramView<'_>,
            bytes: &[u8],
            start: usize,
            end: usize,
        ) -> Option<usize> {
            let mut row = 0_usize;
            let mut position = start;
            let mut pending = view.dfa.initial_pending.then_some(start);
            while position < end {
                let byte = *bytes.get(position)?;
                let class = usize::from(view.dfa.byte_classes[usize::from(byte)]);
                let cell = view
                    .dfa
                    .packed_cells
                    .get(row.checked_add(class)?)?
                    .raw();
                position = position.checked_add(1)?;
                if cell & PARTIAL_CELL_ACCEPTED != 0 {
                    pending = Some(position);
                }
                let next = cell & !PARTIAL_CELL_ACCEPTED;
                if next == PARTIAL_CELL_DEAD {
                    return pending;
                }
                if next >= PARTIAL_CELL_HOLE_BASE {
                    return if position == end { pending } else { None };
                }
                row = usize::try_from(next).ok()?;
            }
            pending
        }

        fn c_bytes(bytes: &[u8]) -> String {
            bytes
                .iter()
                .map(u8::to_string)
                .collect::<Vec<_>>()
                .join(",")
        }

        let mut target = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        if cfg!(target_arch = "aarch64") {
            target = target
                .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                .unwrap();
        }
        let limits = partial_loop_limits();
        let current_exe = std::env::current_exe().expect("current test executable");
        let profile_dir = current_exe
            .parent()
            .and_then(std::path::Path::parent)
            .expect("Cargo profile directory");
        let static_runtime = profile_dir.join("libfre_aot_regex_runtime.a");
        assert!(
            static_runtime.is_file(),
            "build the linked runtime first: cargo build -p fre-aot-regex-runtime --lib ({})",
            static_runtime.display()
        );

        let nonce = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-real-partial-all-{}-{nonce}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create all-output linker directory");
        let mut haystack = vec![b'!'; PARTIAL_DFA_MIN_INPUT_BYTES + 64];
        haystack[0] = b'A';
        haystack.push(b'Z');
        let hole_exit = PARTIAL_DFA_MIN_INPUT_BYTES;
        let mut hole_haystack = vec![b'!'; hole_exit + 65];
        hole_haystack[0] = b'A';
        hole_haystack[hole_exit] = b'a';
        *hole_haystack.last_mut().unwrap() = b'Z';
        let no_match_len = PARTIAL_DFA_MIN_INPUT_BYTES + 64;

        for (case, output) in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ]
        .into_iter()
        .enumerate()
        {
            let compiled = compile(
                CompileRequest::new(PARTIAL_LOOP_PATTERN, target)
                    .mode(CompileMode::Optimizing)
                    .output(output)
                    .limits(limits),
            )
            .unwrap_or_else(|error| panic!("host partial {output:?}: {error}"));
            let view = compiled
                .program()
                .native_partial_dfa_view()
                .unwrap_or_else(|| panic!("missing host partial view for {output:?}"));
            let native_layout = build_native_dfa_table_for_architecture(
                view.native,
                target.architecture,
            )
            .unwrap()
            .1;
            let loop_skip = native_layout
                .loop_skip
                .unwrap_or_else(|| panic!("missing host partial loop for {output:?}"));
            assert!(!loop_skip.accepting);
            assert_eq!(loop_skip.filter.candidate_bytes, 3);
            assert_eq!(
                first_interior_hole(&view, &hole_haystack),
                Some(hole_exit + 1)
            );
            // The normal optimizing pipeline may finish and publish the
            // materialized K0 after retaining this exact partial view. This
            // linked differential deliberately exercises the partial prepared
            // object, so lower the retained view without that later candidate.
            let module = CompiledModule::lower_serialized(
                compiled.program().serialize().unwrap(),
                None,
                false,
                None,
                None,
                None,
                Some(view),
                compiled.program().native_dynamic_rows_view(),
                None,
                target,
            )
            .unwrap_or_else(|error| panic!("lower partial-only {output:?}: {error}"));
            assert!(module.prepared_entry_symbol().is_some());
            assert_eq!(
                module.required_prepared_runtime_symbol(),
                Some(PARTIAL_RUNTIME_V3_SYMBOL_NAME),
                "forced prepared fixture must bind compact-v3: {output:?}",
            );
            assert_eq!(
                module
                    .required_prepared_span_recovery_runtime_symbol()
                    .is_some(),
                output == OutputContract::Span
            );

            if output == OutputContract::Span {
                let expected = compiled
                    .search(&haystack, SearchWindow::new(0, haystack.len()))
                    .unwrap();
                let MatchResult::Span(Some((_, selected_end))) = expected else {
                    panic!("Span fixture did not match: {expected:?}");
                };
                let mut workspace = compiled.program().prepare_workspace().unwrap();
                let preflight = compiled
                    .program()
                    .preflight_retained_partial_with_workspace(
                        &haystack,
                        SearchWindow::new(0, haystack.len()),
                        &mut workspace,
                        compiled.program().artifact_identity(),
                    )
                    .unwrap();
                let crate::program::RetainedPartialPreflight::Enter(native_window) = preflight
                else {
                    panic!("Span fixture did not enter native rows: {preflight:?}");
                };
                assert_eq!(
                    local_selected_end(
                        &view,
                        &haystack,
                        native_window.start(),
                        native_window.end(),
                    ),
                    Some(selected_end),
                    "fixture must exercise native status 4"
                );
            }

            let symbol = module.prepared_entry_symbol().unwrap();
            let (program_symbol, program_len) = module.required_runtime_program().unwrap();
            let object = directory.join(format!("prepared-{case}.o"));
            fs::write(
                &object,
                emit_object(
                    &module,
                    ObjectFormat::for_target(target),
                    usize::MAX,
                )
                .expect("emit all-output prepared object"),
            )
            .expect("write all-output object");
            let source = format!(
                "#include <stddef.h>\n#include <stdint.h>\n\
                 typedef void *handle_t;typedef struct{{size_t start;size_t end;}} result_t;\n\
                 extern const unsigned char {program_symbol}[];\n\
                 extern uint32_t {symbol}(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
                 extern uint32_t fre_aot_regex_runtime_prepare_exclusive_v1(const unsigned char*,size_t,handle_t*);\n\
                 extern uint32_t fre_aot_regex_runtime_search_exclusive_v1(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
                 extern uint32_t fre_aot_regex_runtime_destroy_exclusive_v1(handle_t);\n\
                 static const unsigned char haystack[]={{{}}};\n\
                 static const unsigned char hole_haystack[]={{{}}};\n\
                 static const unsigned char no_match[{no_match_len}]={{0}};\n\
                 static int prepare(handle_t*h){{return fre_aot_regex_runtime_prepare_exclusive_v1({program_symbol},{program_len}U,h)==0U;}}\n\
                 static int destroy(handle_t h){{return fre_aot_regex_runtime_destroy_exclusive_v1(h)==0U;}}\n\
                 static int compare(const unsigned char*p,size_t n,size_t s,size_t e){{\
                   handle_t native=0,baseline=0;result_t nr={{91U,92U}},br={{93U,94U}};\
                   if(!prepare(&native)||!prepare(&baseline))return 1;\
                   uint32_t ns={symbol}(native,p,n,s,e,&nr);\
                   uint32_t bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,p,n,s,e,&br);\
                   if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return 2;\
                   if(!destroy(native)||!destroy(baseline))return 3;return 0;}}\n\
                 int main(void){{int s=compare(haystack,sizeof(haystack),0U,sizeof(haystack));\
                   if(s!=0)return 10+s;s=compare(hole_haystack,sizeof(hole_haystack),0U,sizeof(hole_haystack));\
                   if(s!=0)return 20+s;s=compare(no_match,sizeof(no_match),0U,sizeof(no_match));\
                   if(s!=0)return 30+s;s=compare(haystack,sizeof(haystack),sizeof(haystack),sizeof(haystack));\
                   return s==0?0:40+s;}}\n",
                c_bytes(&haystack),
                c_bytes(&hole_haystack),
            );
            let c_path = directory.join(format!("prepared-{case}.c"));
            let executable = directory.join(format!("prepared-{case}"));
            fs::write(&c_path, source).expect("write all-output C harness");
            let c_compiler = if cfg!(target_os = "macos") {
                "clang"
            } else {
                "cc"
            };
            let status = Command::new(c_compiler)
                .arg("-O0")
                .arg(&c_path)
                .arg(&object)
                .arg(&static_runtime)
                .arg("-o")
                .arg(&executable)
                .status()
                .expect("link all-output real-runtime harness");
            assert!(status.success(), "failed to link {output:?}");
            let result = Command::new(&executable)
                .output()
                .expect("execute all-output real-runtime harness");
            assert!(
                result.status.success(),
                "{output:?}: status={:?} stdout={} stderr={}",
                result.status.code(),
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        fs::remove_dir_all(&directory).expect("remove all-output linker directory");
    }

    #[cfg(all(target_arch = "aarch64", target_os = "macos"))]
    #[test]
    #[ignore = "cross-links x86_64 Mach-O and executes the prepared ABI through Rosetta"]
    #[allow(
        clippy::too_many_lines,
        reason = "the Rosetta probe keeps x86 SysV stack outputs, final statuses, short fallback, and identity authentication together"
    )]
    fn linked_x86_macos_partial_preflight_abi_executes_under_rosetta() {
        use std::{fmt::Write as _, fs, process::Command};

        let mut limits = CompileLimitsV1::default();
        limits.determinize.max_states = 8;
        let compiled = compile(
            CompileRequest::new(
                r"(?-u:[\x00-\xFF])*(?:a+Q|[b-c][a-b]{1,5}(?:x+|y+))Z",
                Target::x86_64_macos(),
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::SelectedEnd)
            .limits(limits),
        )
        .expect("x86 macOS partial preflight object");
        assert!(compiled.program().native_partial_dfa_view().is_some());
        let symbol = compiled
            .module()
            .prepared_entry_symbol()
            .expect("x86 prepared symbol");
        let identity = compiled.program().artifact_identity();
        let identity_bytes = identity
            .iter()
            .map(u8::to_string)
            .collect::<Vec<_>>()
            .join(",");

        let directory = std::env::temp_dir().join(format!(
            "fre-aot-x86-partial-preflight-{}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create x86 preflight directory");
        let object = directory.join("preflight.o");
        fs::write(&object, compiled.object()).expect("write x86 preflight object");
        let mut source = format!(
            "#include <stddef.h>\n#include <stdint.h>\n#include <string.h>\n\
             typedef void *handle_t;typedef struct{{size_t start;size_t end;}} window_t;\n\
             extern uint32_t {symbol}(handle_t,const unsigned char*,size_t,size_t,size_t,size_t*);\n\
             static const unsigned char identity[32]={{{identity_bytes}}};\n\
             static const unsigned char haystack[320]={{0}};\n\
             static int mode;static int preflight_calls;static int fallback_calls;\n\
             uint32_t fre_aot_regex_runtime_search_v1(const unsigned char*a,const unsigned char*b,size_t c,size_t d,size_t e,size_t*f){{(void)a;(void)b;(void)c;(void)d;(void)e;(void)f;return 98U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_v1(handle_t h,const unsigned char*p,size_t n,size_t s,size_t e,size_t*r){{\
               fallback_calls++;if(mode!=2||h!=(handle_t)(uintptr_t)0x1234U||p!=haystack||n!=sizeof(haystack)||s!=0U||e!=100U||r==NULL)return 89U;\
               r[0]=9U;r[1]=9U;return 77U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_from_partial_preflight_compact_v3(handle_t h,const unsigned char*p,size_t n,size_t*r,size_t a,size_t b,size_t z){{\
               (void)h;(void)p;(void)n;(void)r;(void)a;(void)b;(void)z;return 90U;}}\n\
             uint32_t fre_aot_regex_runtime_search_exclusive_partial_preflight_v1(handle_t h,const unsigned char*p,size_t n,size_t s,size_t e,size_t*r,const unsigned char*d,window_t*w){{\
               preflight_calls++;if(h!=(handle_t)(uintptr_t)0x1234U||p!=haystack||n!=sizeof(haystack)||s!=0U||e!=sizeof(haystack)||r==NULL||w==NULL||memcmp(d,identity,32U)!=0)return 88U;\
               if(mode==0){{r[0]=123U;r[1]=123U;return 1U;}}\
               if(mode==1){{w->start=sizeof(haystack);w->end=sizeof(haystack);return 6U;}}\
               if(mode==3){{r[0]=321U;r[1]=654U;return 76U;}}return 87U;}}\n\
             int main(void){{size_t r[2];uint32_t status;\n"
        );
        writeln!(
            source,
            "mode=0;preflight_calls=0;fallback_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),0U,sizeof(haystack),r);if(status!=1U||r[0]!=123U||r[1]!=123U||preflight_calls!=1||fallback_calls!=0)return 10;"
        )
        .unwrap();
        writeln!(
            source,
            "mode=1;preflight_calls=0;fallback_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),0U,sizeof(haystack),r);if(status!=0U||r[0]!=0U||r[1]!=0U||preflight_calls!=1||fallback_calls!=0)return 11;"
        )
        .unwrap();
        writeln!(
            source,
            "mode=2;preflight_calls=0;fallback_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),0U,100U,r);if(status!=77U||r[0]!=9U||r[1]!=9U||preflight_calls!=0||fallback_calls!=1)return 12;"
        )
        .unwrap();
        writeln!(
            source,
            "mode=3;preflight_calls=0;fallback_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)(uintptr_t)0x1234U,haystack,sizeof(haystack),0U,sizeof(haystack),r);if(status!=76U||r[0]!=321U||r[1]!=654U||preflight_calls!=1||fallback_calls!=0)return 13;"
        )
        .unwrap();
        writeln!(
            source,
            "mode=0;preflight_calls=0;fallback_calls=0;r[0]=91U;r[1]=92U;status={symbol}((handle_t)0,haystack,sizeof(haystack),0U,sizeof(haystack),r);if(status!=5U||r[0]!=91U||r[1]!=92U||preflight_calls!=0||fallback_calls!=0)return 14;"
        )
        .unwrap();
        source.push_str("return 0;}\n");

        let c_path = directory.join("preflight.c");
        let executable = directory.join("preflight");
        fs::write(&c_path, source).expect("write x86 preflight harness");
        let status = Command::new("clang")
            .args(["-O0", "-arch", "x86_64"])
            .arg(&c_path)
            .arg(&object)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link x86 preflight harness");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute x86 preflight harness through Rosetta");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        fs::remove_dir_all(&directory).expect("remove x86 preflight directory");
    }

    #[test]
    fn aarch64_pair_load_store_encodings_cover_the_signed_scaled_range() {
        assert_eq!(aarch64_store_pair_x(0, 1, 31, 0).unwrap(), 0xa900_07e0);
        assert_eq!(aarch64_load_pair_x(0, 1, 31, 0).unwrap(), 0xa940_07e0);
        assert_eq!(aarch64_store_pair_x(19, 30, 31, 96).unwrap(), 0xa906_7bf3);
        assert_eq!(aarch64_load_pair_x(19, 30, 31, 96).unwrap(), 0xa946_7bf3);
        assert_eq!(aarch64_store_pair_x(0, 1, 2, -512).unwrap(), 0xa920_0440);
        assert_eq!(aarch64_store_pair_x(0, 1, 2, 504).unwrap(), 0xa91f_8440);
        assert_eq!(aarch64_load_pair_x(0, 1, 2, -512).unwrap(), 0xa960_0440);
        assert_eq!(aarch64_load_pair_x(0, 1, 2, 504).unwrap(), 0xa95f_8440);
        for offset in [-520, -1, 1, 512] {
            assert!(aarch64_store_pair_x(0, 1, 2, offset).is_err());
            assert!(aarch64_load_pair_x(0, 1, 2, offset).is_err());
        }
        assert!(aarch64_store_pair_x(32, 1, 2, 0).is_err());
        assert!(aarch64_load_pair_x(0, 32, 2, 0).is_err());
        assert!(aarch64_store_pair_x(0, 1, 32, 0).is_err());
    }

    #[test]
    fn aarch64_machine_peephole_pairs_only_safe_unanchored_memory_operations() {
        let words = |code: Vec<u8>| {
            code.chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>()
        };

        let mut stores = Aarch64Assembler::new();
        stores
            .instruction(aarch64_store_x(0, 2, 0).unwrap())
            .unwrap();
        stores
            .instruction(aarch64_store_x(1, 2, 8).unwrap())
            .unwrap();
        assert_eq!(
            words(stores.finish().unwrap()),
            [aarch64_store_pair_x(0, 1, 2, 0).unwrap()]
        );

        let mut loads = Aarch64Assembler::new();
        loads
            .instruction(aarch64_load_x_imm(0, 2, 0).unwrap())
            .unwrap();
        loads
            .instruction(aarch64_load_x_imm(1, 2, 8).unwrap())
            .unwrap();
        assert_eq!(
            words(loads.finish().unwrap()),
            [aarch64_load_pair_x(0, 1, 2, 0).unwrap()]
        );

        for (first, second) in [
            (
                aarch64_load_x_imm(2, 2, 0).unwrap(),
                aarch64_load_x_imm(1, 2, 8).unwrap(),
            ),
            (
                aarch64_load_x_imm(0, 2, 0).unwrap(),
                aarch64_load_x_imm(0, 2, 8).unwrap(),
            ),
            (
                aarch64_store_x(0, 2, 512).unwrap(),
                aarch64_store_x(1, 2, 520).unwrap(),
            ),
        ] {
            let mut unsafe_pair = Aarch64Assembler::new();
            unsafe_pair.instruction(first).unwrap();
            unsafe_pair.instruction(second).unwrap();
            assert_eq!(words(unsafe_pair.finish().unwrap()), [first, second]);
        }

        let mut targeted = Aarch64Assembler::new();
        let second = targeted.label().unwrap();
        targeted
            .instruction(aarch64_store_x(0, 2, 0).unwrap())
            .unwrap();
        targeted.bind(second).unwrap();
        targeted
            .instruction(aarch64_store_x(1, 2, 8).unwrap())
            .unwrap();
        targeted.branch(second).unwrap();
        let targeted_words = words(targeted.finish().unwrap());
        assert_eq!(targeted_words[..2], [
            aarch64_store_x(0, 2, 0).unwrap(),
            aarch64_store_x(1, 2, 8).unwrap(),
        ]);

        let mut relocated = Aarch64Assembler::new();
        relocated
            .instruction(aarch64_store_x(0, 2, 0).unwrap())
            .unwrap();
        relocated
            .instruction(aarch64_store_x(1, 2, 8).unwrap())
            .unwrap();
        let mut relocation_offsets = [4_usize];
        let relocated_words = words(
            relocated
                .finish_with_offsets(&mut relocation_offsets)
                .unwrap(),
        );
        assert_eq!(relocation_offsets, [4]);
        assert_eq!(relocated_words, [
            aarch64_store_x(0, 2, 0).unwrap(),
            aarch64_store_x(1, 2, 8).unwrap(),
        ]);
    }

    #[test]
    fn aarch64_compare_and_test_branch_fixups_have_exact_encodings() {
        assert_eq!(aarch64_load_byte_post_imm(6, 2, 1).unwrap(), 0x3840_1446);
        assert_eq!(aarch64_load_byte_post_imm(8, 2, 1).unwrap(), 0x3840_1448);
        assert!(aarch64_load_byte_post_imm(6, 2, 256).is_err());

        let mut assembler = Aarch64Assembler::new();
        let target = assembler.label().unwrap();
        assembler.branch_bit_set_w(8, 31, target).unwrap();
        assembler.branch_zero_w(6, target).unwrap();
        assembler.instruction(0xd503_201f).unwrap(); // nop
        assembler.bind(target).unwrap();
        let words = assembler
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(words, [0x37f8_0068, 0x3400_0046, 0xd503_201f]);

        let mut wide = Aarch64Assembler::new();
        let target = wide.label().unwrap();
        wide.branch_bit_set_x(10, 63, target).unwrap();
        wide.branch_zero_x(16, target).unwrap();
        wide.branch_nonzero_x(7, target).unwrap();
        wide.instruction(0xd503_201f).unwrap(); // nop
        wide.bind(target).unwrap();
        let words = wide
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(words, [0xb7f8_008a, 0xb400_0070, 0xb500_0047, 0xd503_201f]);

        let mut invalid = Aarch64Assembler::new();
        let label = invalid.label().unwrap();
        assert!(invalid.branch_bit_set_w(8, 32, label).is_err());
        assert!(invalid.branch_bit_set_x(8, 64, label).is_err());
        assert!(invalid.branch_bit_clear_w(8, 32, label).is_err());
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one target-aware cross-ISA audit proves rotated bounds, root re-entry, and pointer-cursor contracts"
    )]
    fn compact_hot_loops_are_bottom_tested_and_pointer_advanced_cross_isa() {
        fn x86_bound_pairs(
            code: &[u8],
            opcode: u8,
            backward: bool,
        ) -> Vec<(usize, usize)> {
            code.windows(3)
                .enumerate()
                .filter_map(|(compare, window)| {
                    if window != [0x48, 0x39, 0xca]
                        || x86_test_normalized_branch_opcode(code, compare + 3) != Some(opcode)
                    {
                        return None;
                    }
                    let (target, _) = x86_test_branch_target(code, compare + 3)?;
                    ((target < compare) == backward).then_some((compare, target))
                })
                .collect()
        }

        fn x86_bound_tests(code: &[u8], opcode: u8, backward: bool) -> usize {
            x86_bound_pairs(code, opcode, backward).len()
        }

        fn aarch64_words(code: &[u8]) -> Vec<u32> {
            code.chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect()
        }

        fn aarch64_conditional_branch_target(words: &[u32], branch: usize) -> Option<usize> {
            let instruction = *words.get(branch)?;
            if instruction & 0xff00_0010 != 0x5400_0000 {
                return None;
            }
            let immediate = i32::try_from((instruction >> 5) & 0x7_ffff).ok()?;
            let displacement = (immediate << 13) >> 13;
            let branch = isize::try_from(branch).ok()?;
            usize::try_from(branch.checked_add(isize::try_from(displacement).ok()?)?).ok()
        }

        fn aarch64_bound_pairs(
            words: &[u32],
            condition: u8,
            backward: bool,
        ) -> Vec<(usize, usize)> {
            let compare = aarch64_cmp_x(2, 3).unwrap();
            words
                .windows(2)
                .enumerate()
                .filter_map(|(compare_index, pair)| {
                    if pair[0] != compare
                        || pair[1] & 0xff00_001f
                            != 0x5400_0000 | u32::from(condition)
                    {
                        return None;
                    }
                    let target = aarch64_conditional_branch_target(words, compare_index + 1)?;
                    ((target < compare_index) == backward)
                        .then_some((compare_index, target))
                })
                .collect()
        }

        fn aarch64_bound_tests(code: &[u8], condition: u8, backward: bool) -> usize {
            aarch64_bound_pairs(&aarch64_words(code), condition, backward).len()
        }

        fn assert_rooted_x86_compact_bounds(code: &[u8], context: &str) {
            let compare_bytes = [0x48, 0x39, 0xca];
            let bounds = x86_bound_pairs(code, 0x82, true);
            assert_eq!(
                bounds.len(),
                32,
                "{context}: two V7 resumes, V8/V10/V4, and all V6/V3/V12 shifts need conditional backedges"
            );
            for &(compare, target) in &bounds {
                assert_ne!(
                    &code[target..target + compare_bytes.len()],
                    compare_bytes.as_slice(),
                    "{context}: a compact backedge must not retain a top bound pair"
                );
                assert!(
                    !code[target..compare]
                        .windows(compare_bytes.len())
                        .enumerate()
                        .any(|(offset, window)| {
                            window == compare_bytes
                                && x86_test_normalized_branch_opcode(
                                    code,
                                    target + offset + compare_bytes.len(),
                                ) == Some(0x83)
                        }),
                    "{context}: a rooted compact body must contain no top boundary test"
                );
            }

            let v4_update_bytes = [0x4e, 0x8d, 0x44, 0x56, 0xfe];
            let v4_updates = code
                .windows(v4_update_bytes.len())
                .enumerate()
                .filter_map(|(offset, window)| {
                    (window == v4_update_bytes
                        && code[offset + v4_update_bytes.len()..]
                            .starts_with(&compare_bytes))
                    .then_some(offset)
                })
                .collect::<Vec<_>>();
            assert_eq!(
                v4_updates.len(),
                1,
                "{context}: exact rooted V4 immediate-bottom loop count; V7 probes its loop index first"
            );
            let root_compare = [0x4c, 0x3b, 0x44, 0x24, 0x50];
            let raw_load = [0x44, 0x0f, 0xb6, 0x14, 0x17];
            let map_load = [0x47, 0x0f, 0xb6, 0x14, 0x11];
            let cell_load = [0x47, 0x0f, 0xb7, 0x14, 0x50];
            let mut mapped = 0_usize;
            let mut direct = 0_usize;
            for v4_update in v4_updates {
                let v4_compare = v4_update + v4_update_bytes.len();
                assert_eq!(
                    &code[v4_compare..v4_compare + compare_bytes.len()],
                    compare_bytes.as_slice(),
                    "{context}: V4 update must be followed by its bottom bound"
                );
                assert_eq!(
                    x86_test_normalized_branch_opcode(code, v4_compare + compare_bytes.len()),
                    Some(0x82),
                    "{context}: V4 bottom bound must be position < end"
                );
                let (v4_scan, _) = x86_test_branch_target(
                    code,
                    v4_compare + compare_bytes.len(),
                )
                .expect("rooted x86 V4 bottom backedge");
                assert_eq!(
                    &code[v4_scan..v4_scan + root_compare.len()],
                    root_compare.as_slice(),
                    "{context}: V4 backedge must reach compact root dispatch"
                );
                let body = &code[v4_scan..v4_update];
                let raw = body
                    .windows(raw_load.len())
                    .position(|window| window == raw_load)
                    .expect("rooted x86 V4 raw-byte load");
                let after_raw = raw + raw_load.len();
                if body[after_raw..].starts_with(&map_load) {
                    let after_map = after_raw + map_load.len();
                    assert!(body[after_map..].starts_with(&cell_load));
                    mapped += 1;
                } else {
                    assert!(body[after_raw..].starts_with(&cell_load));
                    direct += 1;
                }
            }
            assert_eq!(mapped, 1, "{context}: exact mapped V4 loop count");
            assert_eq!(direct, 0, "{context}: dominated V9 loop must be absent");
        }

        fn assert_rooted_aarch64_compact_bounds(words: &[u32], context: &str) {
            let compare = aarch64_cmp_x(2, 3).unwrap();
            let bounds = aarch64_bound_pairs(words, AARCH64_LO, true);
            assert_eq!(
                bounds.len(),
                25,
                "{context}: two V7 and two shared V6 resumes plus V8/V10/V4 and V3/V12 shifts need conditional backedges"
            );
            for &(compare_index, target) in &bounds {
                assert_ne!(
                    words[target], compare,
                    "{context}: a compact backedge must not retain a top bound pair"
                );
                assert!(
                    !words[target..compare_index].windows(2).any(|pair| {
                        pair[0] == compare
                            && pair[1] & 0xff00_001f
                                == 0x5400_0000 | u32::from(AARCH64_HS)
                    }),
                    "{context}: a rooted compact body must contain no top boundary test"
                );
            }

            let v4_update_word = aarch64_add_x_uxtw(11, 15, 8, 1).unwrap();
            let v4_updates = words
                .iter()
                .enumerate()
                .filter_map(|(index, &word)| {
                    (word == v4_update_word && words.get(index + 1) == Some(&compare))
                        .then_some(index)
                })
                .collect::<Vec<_>>();
            assert_eq!(
                v4_updates.len(),
                1,
                "{context}: exact rooted V4 immediate-bottom loop count; V7 probes its loop index first"
            );
            let raw_load = aarch64_load_byte_reg(8, 0, 2).unwrap();
            let map_load = aarch64_load_byte_reg(8, 14, 8).unwrap();
            let cell_load = aarch64_load_h_uxtw(8, 11, 8).unwrap();
            let mut mapped = 0_usize;
            let mut direct = 0_usize;
            for v4_update in v4_updates {
                assert_eq!(
                    words[v4_update + 1],
                    compare,
                    "{context}: V4 update must be followed by its bottom bound"
                );
                assert_eq!(
                    words[v4_update + 2] & 0xff00_001f,
                    0x5400_0000 | u32::from(AARCH64_LO),
                    "{context}: V4 bottom bound must be position < end"
                );
                let v4_scan = aarch64_conditional_branch_target(words, v4_update + 2)
                    .expect("rooted AArch64 V4 bottom backedge");
                assert_eq!(
                    words[v4_scan],
                    aarch64_cmp_x(11, 1).unwrap(),
                    "{context}: V4 backedge must reach compact root dispatch"
                );
                let body = &words[v4_scan..v4_update];
                let raw = body
                    .iter()
                    .position(|&word| word == raw_load)
                    .expect("rooted AArch64 V4 raw-byte load");
                if body.get(raw + 1) == Some(&map_load) {
                    assert_eq!(body.get(raw + 2), Some(&cell_load));
                    mapped += 1;
                } else {
                    assert_eq!(body.get(raw + 1), Some(&cell_load));
                    direct += 1;
                }
            }
            assert_eq!(mapped, 1, "{context}: exact mapped V4 loop count");
            assert_eq!(direct, 0, "{context}: dominated V9 loop must be absent");
        }

        let v4_postindexed = aarch64_load_byte_post_imm(8, 2, 1).unwrap();
        let v3_postindexed = aarch64_load_byte_post_imm(6, 2, 1).unwrap();
        let v4_indexed = aarch64_load_byte_reg(8, 0, 2).unwrap();
        let v3_indexed = aarch64_load_byte_reg(6, 0, 2).unwrap();
        let v4_postindexed_body = [
            v4_postindexed,
            aarch64_load_byte_reg(8, 14, 8).unwrap(),
            aarch64_load_h_uxtw(8, 11, 8).unwrap(),
        ];
        let v4_direct_postindexed_body = [
            v4_postindexed,
            aarch64_load_h_uxtw(8, 11, 8).unwrap(),
        ];
        let v3_postindexed_body = [
            v3_postindexed,
            aarch64_load_byte_reg(6, 14, 6).unwrap(),
            aarch64_load_h_uxtw(8, 11, 6).unwrap(),
        ];
        let v8_postindexed_body = [v3_postindexed, aarch64_load_h_uxtw(8, 11, 6).unwrap()];
        let v12_postindexed_body = [
            v3_postindexed,
            aarch64_load_byte_reg(6, 14, 6).unwrap(),
            aarch64_load_byte_reg(8, 11, 6).unwrap(),
        ];
        let v4_indexed_body = [
            v4_indexed,
            aarch64_load_byte_reg(8, 14, 8).unwrap(),
            aarch64_load_h_uxtw(8, 11, 8).unwrap(),
        ];
        let v4_direct_indexed_body = [
            v4_indexed,
            aarch64_load_h_uxtw(8, 11, 8).unwrap(),
        ];
        let v3_indexed_body = [
            v3_indexed,
            aarch64_load_byte_reg(6, 14, 6).unwrap(),
            aarch64_load_h_uxtw(8, 11, 6).unwrap(),
        ];
        let v8_indexed_body = [v3_indexed, aarch64_load_h_uxtw(8, 11, 6).unwrap()];
        let v12_indexed_body = [
            v3_indexed,
            aarch64_load_byte_reg(6, 14, 6).unwrap(),
            aarch64_load_byte_reg(8, 11, 6).unwrap(),
        ];
        let pointer_setup = [
            aarch64_add_x_reg(2, 0, 2).unwrap(),
            aarch64_add_x_reg(3, 0, 3).unwrap(),
        ];

        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(2)),
        ] {
            let x86 = lower_x86_64_dynamic_rows_prepared_for_output(
                None,
                FeatureSet::EMPTY,
                output,
                exact_span_width,
                true,
            )
            .unwrap();
            assert_eq!(
                x86_bound_tests(&x86.code, 0x82, true),
                12,
                "x86 singleton, two V7 resumes, and all V6 shifts retain end-relative backedges while V3/V4/V8/V10/V12 use exact pair bounds for {output:?}"
            );
            let x86_mapped_v4 = [
                0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f,
                0xb7, 0x14, 0x50,
            ];
            let x86_pointer_mapped_v4 = [
                0x44, 0x0f, 0xb6, 0x12, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f, 0xb7,
                0x14, 0x50,
            ];
            let x86_direct_v4 = [
                0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb7, 0x14, 0x50,
            ];
            let x86_pointer_direct_v4 = [
                0x44, 0x0f, 0xb6, 0x12, 0x47, 0x0f, 0xb7, 0x14, 0x50,
            ];
            let x86_mapped_u8 = [
                0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f,
                0xb6, 0x14, 0x10,
            ];
            let x86_pointer_mapped_u8 = [
                0x44, 0x0f, 0xb6, 0x12, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f, 0xb6,
                0x14, 0x10,
            ];
            assert_eq!(
                x86.code
                    .windows(x86_mapped_v4.len())
                    .filter(|window| *window == x86_mapped_v4)
                    .count(),
                if output == OutputContract::Exists { 12 } else { 10 },
                "x86 mapped V7/V6 retain offsets while V3/V4 endpoint tails use pointers for {output:?}"
            );
            assert_eq!(
                x86.code
                    .windows(x86_pointer_mapped_v4.len())
                    .filter(|window| *window == x86_pointer_mapped_v4)
                    .count(),
                if output == OutputContract::Exists { 0 } else { 2 },
                "x86 pointer-form V3/V4 scalar tails for {output:?}"
            );
            assert_eq!(
                x86.code
                    .windows(x86_direct_v4.len())
                    .filter(|window| *window == x86_direct_v4)
                    .count(),
                usize::from(output == OutputContract::Exists),
                "x86 offset-form direct-byte u16 V8 body for {output:?}"
            );
            assert_eq!(
                x86.code
                    .windows(x86_pointer_direct_v4.len())
                    .filter(|window| *window == x86_pointer_direct_v4)
                    .count(),
                usize::from(output != OutputContract::Exists),
                "x86 pointer-form direct-byte u16 V8 body for {output:?}"
            );
            assert_eq!(
                x86.code
                    .windows(x86_mapped_u8.len())
                    .filter(|window| *window == x86_mapped_u8)
                    .count(),
                usize::from(output == OutputContract::Exists),
                "x86 offset-form compact-u8 V12 scalar tail for {output:?}"
            );
            assert_eq!(
                x86.code
                    .windows(x86_pointer_mapped_u8.len())
                    .filter(|window| *window == x86_pointer_mapped_u8)
                    .count(),
                usize::from(output != OutputContract::Exists),
                "x86 pointer-form compact-u8 V12 scalar tail for {output:?}"
            );

            let arm = lower_aarch64_dynamic_rows_prepared_for_output(
                None,
                output,
                exact_span_width,
                true,
            )
            .unwrap();
            assert_eq!(
                aarch64_bound_tests(&arm.code, AARCH64_LO, true),
                5,
                "AArch64 singleton, two V7 and two shared V6 resumes retain end-relative backedges while V3/V4/V8/V10/V12 use exact pair bounds for {output:?}"
            );
            let words = aarch64_words(&arm.code);
            let setup_count = words
                .windows(pointer_setup.len())
                .filter(|window| *window == pointer_setup)
                .count();
            if output == OutputContract::Exists {
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v4_postindexed_body)
                        .count(),
                    0,
                    "scanner-free V4 uses explicit paired byte loads"
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v4_direct_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v3_postindexed_body)
                        .count(),
                    0,
                    "scanner-free V3 uses explicit paired byte loads"
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v8_postindexed_body)
                        .count(),
                    0,
                    "scanner-free V8 uses explicit paired byte loads"
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v12_postindexed_body)
                        .count(),
                    0,
                    "scanner-free V12 uses explicit paired byte loads"
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v4_indexed_body)
                        .count(),
                    1,
                    "V7 retains the offset cursor needed by loop-scan continuation"
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v4_direct_indexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v3_indexed_body)
                        .count(),
                    1,
                    "V6 retains the offset cursor needed by loop-scan continuation"
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v8_indexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v12_indexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    setup_count, 6,
                    "singleton, V8/V10/V12, mapped V4, and V3 convert selected cursors once while V6/V7 retain offsets"
                );
            } else {
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v4_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v4_direct_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v3_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v8_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v12_postindexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v4_indexed_body)
                        .count(),
                    2
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v4_direct_indexed_body)
                        .count(),
                    0
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v3_indexed_body)
                        .count(),
                    2,
                    "V6 retains one indexed body and all V3 shifts share one scalar tail"
                );
                assert_eq!(
                    words
                        .windows(2)
                        .filter(|body| *body == v8_indexed_body)
                        .count(),
                    1
                );
                assert_eq!(
                    words
                        .windows(3)
                        .filter(|body| *body == v12_indexed_body)
                        .count(),
                    1,
                    "all V12 shifts share one scalar endpoint tail"
                );
                assert_eq!(setup_count, 0, "endpoint contracts retain offset cursors");
            }
        }

        let mut membership = [0_u64; 4];
        let byte = usize::from(b'a');
        membership[byte / 64] |= 1_u64 << (byte % 64);
        let root_filter = plan_dynamic_root_filter(NativeDynamicRootRequirement {
            scan_offset: 0,
            membership,
        })
        .unwrap()
        .expect("nontrivial compact-loop root filter");
        let avx512 = FeatureSet::of(CpuFeature::X86Avx512F)
            .with(CpuFeature::X86Avx512Bw);
        for (features, accelerator) in [
            (FeatureSet::EMPTY, StartAccelerator::X86Sse2),
            (
                FeatureSet::of(CpuFeature::X86Avx2),
                StartAccelerator::X86Avx2,
            ),
            (avx512, StartAccelerator::X86Avx512Bw),
        ] {
            for (output, exact_span_width) in [
                (OutputContract::Exists, None),
                (OutputContract::SelectedEnd, None),
                (OutputContract::Span, Some(2)),
            ] {
                let rooted_x86 = lower_x86_64_dynamic_rows_prepared_for_output(
                    Some(root_filter),
                    features,
                    output,
                    exact_span_width,
                    true,
                )
                .unwrap();
                assert_eq!(
                    rooted_x86
                        .scanner
                        .expect("rooted x86 scanner receipt")
                        .start_accelerator(),
                    accelerator
                );
                let context = format!("x86/{accelerator:?}/{output:?}");
                assert_rooted_x86_compact_bounds(&rooted_x86.code, &context);
            }
        }

        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let sve = FeatureSet::of(CpuFeature::Aarch64Sve);
        let sve2 = sve.with(CpuFeature::Aarch64Sve2);
        let arm_tiers = [
            (
                "scalar-linux",
                Target::aarch64_linux(),
                StartAccelerator::Scalar,
            ),
            (
                "asimd-macos",
                Target::aarch64_macos().with_features(asimd).unwrap(),
                StartAccelerator::Aarch64Asimd,
            ),
            (
                "sve-linux",
                Target::aarch64_linux().with_features(sve).unwrap(),
                StartAccelerator::Aarch64Sve,
            ),
            (
                "sve2-linux",
                Target::aarch64_linux().with_features(sve2).unwrap(),
                StartAccelerator::Aarch64Sve2,
            ),
            (
                "mixed-sve-linux",
                Target::aarch64_linux()
                    .with_features(asimd.with(CpuFeature::Aarch64Sve))
                    .unwrap(),
                StartAccelerator::Aarch64Sve,
            ),
            (
                "mixed-sve2-linux",
                Target::aarch64_linux()
                    .with_features(asimd.union(sve2))
                    .unwrap(),
                StartAccelerator::Aarch64Sve2,
            ),
        ];
        for (tier, target, accelerator) in arm_tiers {
            let mut data = vec![0_u8; 32];
            let root = install_aarch64_dynamic_root_plan(
                &mut data,
                0,
                root_filter,
                target,
            )
            .unwrap();
            assert_eq!(root.scanner.start_accelerator(), accelerator, "{tier}");
            for (output, exact_span_width) in [
                (OutputContract::Exists, None),
                (OutputContract::SelectedEnd, None),
                (OutputContract::Span, Some(2)),
            ] {
                let rooted_arm = lower_aarch64_dynamic_rows_prepared_for_output(
                    Some(root),
                    output,
                    exact_span_width,
                    true,
                )
                .unwrap();
                let context = format!("AArch64/{tier}/{output:?}");
                let rooted_words = aarch64_words(&rooted_arm.code);
                assert_rooted_aarch64_compact_bounds(&rooted_words, &context);
                assert_eq!(
                    rooted_words
                        .iter()
                        .filter(|&&word| word == v4_postindexed || word == v3_postindexed)
                        .count(),
                    0,
                    "{context}: rooted entries retain offset loads"
                );
                assert_eq!(
                    rooted_words
                        .windows(pointer_setup.len())
                        .filter(|window| *window == pointer_setup)
                        .count(),
                    0,
                    "{context}: root re-entry retains offset cursors"
                );
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one cross-ISA shape audit proves the singleton selector, load elimination, decoder, and backedge together"
    )]
    fn scanner_free_v4_singleton_rows_have_byte_independent_hot_loops_cross_isa() {
        fn byte_occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        fn aarch64_conditional_target(words: &[u32], branch: usize) -> Option<usize> {
            let instruction = *words.get(branch)?;
            if instruction & 0xff00_0010 != 0x5400_0000 {
                return None;
            }
            let immediate = i32::try_from((instruction >> 5) & 0x7_ffff).ok()?;
            let displacement = (immediate << 13) >> 13;
            usize::try_from(
                isize::try_from(branch)
                    .ok()?
                    .checked_add(isize::try_from(displacement).ok()?)?,
            )
            .ok()
        }

        let class_count_offset = u8::try_from(FROZEN_DYNAMIC_ROWS_V3_CLASS_COUNT_OFFSET).unwrap();
        let x86_class_guard = [0x41, 0x83, 0x7b, class_count_offset, 1];
        let x86_singleton_load = [0x45, 0x0f, 0xb7, 0x10];
        let x86_hay_load = [0x44, 0x0f, 0xb6, 0x14, 0x17];
        let x86_class_load = [0x47, 0x0f, 0xb6, 0x14, 0x11];
        let x86_update = [0x4e, 0x8d, 0x44, 0x56, 0xfe];
        let x86_pointer_setup = [0x48, 0x01, 0xfa, 0x48, 0x01, 0xf9, 0x31, 0xff];
        let x86_pointer_complete = [0x49, 0x89, 0xfb, 0x4c, 0x2b, 0x5c, 0x24, 0x18];
        let avx512 = FeatureSet::of(CpuFeature::X86Avx512F)
            .with(CpuFeature::X86Avx512Bw)
            .with(CpuFeature::X86Avx512Vl);
        for (tier, features) in [
            ("sse2", FeatureSet::EMPTY),
            ("avx2", FeatureSet::of(CpuFeature::X86Avx2)),
            ("avx512", avx512),
        ] {
            for (output, exact_span_width) in [
                (OutputContract::Exists, None),
                (OutputContract::SelectedEnd, None),
                (OutputContract::Span, Some(2)),
            ] {
                let emission = lower_x86_64_dynamic_rows_prepared_for_output(
                    None,
                    features,
                    output,
                    exact_span_width,
                    true,
                )
                .unwrap();
                let code = emission.code.as_slice();
                let context = format!("x86/{tier}/{output:?}");
                assert_eq!(
                    byte_occurrences(code, &x86_pointer_setup),
                    if output == OutputContract::Exists { 0 } else { 8 },
                    "{context}: singleton V4 and all seven no-helper compact entries pointerize once each"
                );
                assert_eq!(
                    byte_occurrences(code, &x86_pointer_complete),
                    if output == OutputContract::Exists { 0 } else { 1 },
                    "{context}: scanner-free no-helper formats share one pointer-to-offset completion"
                );
                assert_eq!(byte_occurrences(code, &x86_class_guard), 1, "{context}");
                assert_eq!(
                    byte_occurrences(code, &x86_singleton_load),
                    1,
                    "{context}: one singleton cell load"
                );
                let guard = code
                    .windows(x86_class_guard.len())
                    .position(|window| window == x86_class_guard)
                    .unwrap();
                let guard_branch = guard + x86_class_guard.len();
                assert_eq!(
                    x86_test_normalized_branch_opcode(code, guard_branch),
                    Some(0x85),
                    "{context}: non-singleton V4 must select the ordinary loop"
                );
                let (class_mapped, _) = x86_test_branch_target(code, guard_branch).unwrap();
                assert_eq!(
                    &code[class_mapped..class_mapped + 3],
                    &[0x4c, 0x8d, 0x8f],
                    "{context}: the failed singleton guard must install the class map"
                );

                let singleton = code
                    .windows(x86_singleton_load.len())
                    .position(|window| window == x86_singleton_load)
                    .unwrap();
                assert_eq!(
                    &code[singleton..singleton + 7],
                    &[0x45, 0x0f, 0xb7, 0x10, 0x48, 0xff, 0xc2],
                    "{context}: the hot body must load only row[0] and advance"
                );
                let update = singleton
                    + code[singleton..class_mapped]
                        .windows(x86_update.len())
                        .position(|window| window == x86_update)
                        .unwrap();
                assert_eq!(
                    byte_occurrences(&code[singleton..update], &x86_hay_load),
                    0,
                    "{context}: singleton loop must not read a hay byte"
                );
                assert_eq!(
                    byte_occurrences(&code[singleton..update], &x86_class_load),
                    0,
                    "{context}: singleton loop must not read the class map"
                );
                let compare = update + x86_update.len();
                assert_eq!(&code[compare..compare + 3], &[0x48, 0x39, 0xca]);
                assert_eq!(
                    x86_test_normalized_branch_opcode(code, compare + 3),
                    Some(0x82),
                    "{context}: singleton backedge must use unsigned position < end"
                );
                assert_eq!(
                    x86_test_branch_target(code, compare + 3).map(|(target, _)| target),
                    Some(singleton),
                    "{context}: singleton loop must be bottom-tested"
                );
                if output == OutputContract::Exists {
                    assert!(code[singleton..update]
                        .windows(4)
                        .any(|window| window == [0x66, 0x45, 0x85, 0xd2]));
                    assert_eq!(
                        byte_occurrences(
                            &code[singleton..update],
                            &[0x41, 0x81, 0xe2, 0xff, 0x7f, 0, 0],
                        ),
                        0,
                        "{context}: Exists keeps the unmasked live token"
                    );
                } else {
                    assert_eq!(
                        byte_occurrences(
                            &code[singleton..update],
                            &[0x48, 0x89, 0x54, 0x24, 0x60],
                        ),
                        0,
                        "{context}: scanner-free V4 does not spill accepting endpoints"
                    );
                    assert_eq!(
                        byte_occurrences(
                            &code[singleton..update],
                            &[0x48, 0x0f, 0x48, 0xfa],
                        ),
                        1,
                        "{context}: accepting cells select the consumed endpoint into RDI without a branch"
                    );
                    assert_eq!(
                        byte_occurrences(
                            &code[singleton..update],
                            &[0x41, 0x81, 0xe2, 0xff, 0x7f, 0, 0],
                        ),
                        1,
                        "{context}: endpoint loops strip the accept bit"
                    );
                }
            }
        }

        assert_eq!(aarch64_load_halfword_imm(8, 11, 0).unwrap(), 0x7940_0168);
        assert!(aarch64_load_halfword_imm(8, 11, 1).is_err());
        let arm_guard = [
            aarch64_load_w_imm(
                8,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_CLASS_COUNT_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_cmp_w_imm(8, 1).unwrap(),
        ];
        let arm_singleton_load = aarch64_load_halfword_imm(8, 11, 0).unwrap();
        let arm_hay_load = aarch64_load_byte_reg(8, 0, 2).unwrap();
        let arm_class_load = aarch64_load_byte_reg(8, 14, 8).unwrap();
        let arm_update = aarch64_add_x_uxtw(11, 15, 8, 1).unwrap();
        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(2)),
        ] {
            // Scanner-free AArch64 lowering is deliberately tier-neutral: the
            // same scalar row core is used by scalar, ASIMD, SVE, SVE2, and
            // mixed-feature target entries because no root scanner is active.
            let emission = lower_aarch64_dynamic_rows_prepared_for_output(
                None,
                output,
                exact_span_width,
                true,
            )
            .unwrap();
            let words = emission
                .code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            let context = format!("AArch64/{output:?}");
            let guard = words
                .windows(arm_guard.len())
                .position(|window| window == arm_guard)
                .unwrap();
            assert_eq!(
                words
                    .windows(arm_guard.len())
                    .filter(|window| *window == arm_guard)
                    .count(),
                1,
                "{context}: one authenticated singleton selector"
            );
            assert_eq!(
                words[guard + arm_guard.len()] & 0xff00_001f,
                0x5400_0000 | u32::from(AARCH64_NE),
                "{context}: non-singleton V4 must select the ordinary loop"
            );
            let class_mapped = aarch64_conditional_target(&words, guard + arm_guard.len())
                .expect("AArch64 V4 class-mapped branch");
            assert_eq!(
                words[class_mapped],
                aarch64_mov_x(11, 15).unwrap(),
                "{context}: class-mapped V4 must install canonical row zero"
            );
            let singleton = words
                .iter()
                .position(|&word| word == arm_singleton_load)
                .unwrap();
            assert_eq!(
                words.iter().filter(|&&word| word == arm_singleton_load).count(),
                1,
                "{context}: one immediate singleton cell load"
            );
            assert_eq!(words[singleton + 1], aarch64_add_x_imm(2, 2, 1).unwrap());
            let update = singleton
                + words[singleton..class_mapped]
                    .iter()
                    .position(|&word| word == arm_update)
                    .unwrap();
            assert!(!words[singleton..update].contains(&arm_hay_load), "{context}");
            assert!(!words[singleton..update].contains(&arm_class_load), "{context}");
            assert_eq!(words[update + 1], aarch64_cmp_x(2, 3).unwrap());
            assert_eq!(
                words[update + 2] & 0xff00_001f,
                0x5400_0000 | u32::from(AARCH64_LO),
                "{context}: singleton backedge must use position < end"
            );
            assert_eq!(
                aarch64_conditional_target(&words, update + 2),
                Some(singleton),
                "{context}: singleton loop must be bottom-tested"
            );
            if output == OutputContract::Exists {
                assert!(!words[singleton..update]
                    .contains(&aarch64_and_low_w(8, 8, 15).unwrap()));
            } else {
                assert_eq!(
                    words[singleton..update]
                        .iter()
                        .filter(|&&word| word == aarch64_mov_x(4, 2).unwrap())
                        .count(),
                    1,
                    "{context}: accepting cells retain the consumed endpoint in X4"
                );
                assert!(words[singleton..update]
                    .contains(&aarch64_and_low_w(8, 8, 15).unwrap()));
            }
        }
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one exact cross-target audit proves the stackless leaf boundary and both framed loop routes"
    )]
    fn aarch64_scanner_free_immutable_exists_is_a_stackless_leaf_cross_target() {
        fn words(module: &CompiledModule) -> Vec<u32> {
            let symbol = &module.symbols[module.prepared_entry_symbol_index.unwrap()];
            assert_eq!(symbol.section, Some(TEXT_SECTION));
            let begin = usize::try_from(symbol.offset).unwrap();
            let end = begin.checked_add(usize::try_from(symbol.size).unwrap()).unwrap();
            module.sections[TEXT_SECTION].data[begin..end]
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect()
        }

        fn flag_words(flag: u32) -> [u32; 3] {
            if flag == FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS {
                return [
                    aarch64_load_w_imm(
                        9,
                        0,
                        u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
                    )
                    .unwrap(),
                    aarch64_movz_x(8, u16::try_from(flag).unwrap(), 0).unwrap(),
                    aarch64_cmp_w(9, 8).unwrap(),
                ];
            }
            [
                aarch64_load_w_imm(
                    8,
                    0,
                    u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
                )
                .unwrap(),
                aarch64_movz_x(9, u16::try_from(flag).unwrap(), 0).unwrap(),
                aarch64_cmp_w(8, 9).unwrap(),
            ]
        }

        fn branch_target(words: &[u32], index: usize) -> usize {
            let word = words[index];
            assert_eq!(word & 0xfc00_0000, 0x1400_0000, "expected B at {index}");
            let immediate = ((word & 0x03ff_ffff) << 6).cast_signed() >> 6;
            index
                .checked_add_signed(isize::try_from(immediate).unwrap())
                .unwrap()
        }

        let raw = scanner_free_nonloop_pair_raw();
        let program = scanner_free_dynamic_program(raw, OutputContract::Exists);
        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let sve = FeatureSet::of(CpuFeature::Aarch64Sve);
        let sve2 = sve.with(CpuFeature::Aarch64Sve2);
        let targets = [
            ("linux-asimd", Target::aarch64_linux().with_features(asimd).unwrap()),
            ("linux-sve", Target::aarch64_linux().with_features(sve).unwrap()),
            ("linux-sve2", Target::aarch64_linux().with_features(sve2).unwrap()),
            ("macos-asimd", Target::aarch64_macos().with_features(asimd).unwrap()),
            ("macos-sve", Target::aarch64_macos().with_features(sve).unwrap()),
            ("macos-sve2", Target::aarch64_macos().with_features(sve2).unwrap()),
        ];

        for (context, target) in targets {
            let module = lower_without_materialized_k0(&program, target);
            let object = crate::emit_object(
                &module,
                ObjectFormat::for_target(target),
                usize::MAX,
            )
            .unwrap_or_else(|error| panic!("{context}: {error}"));
            assert!(!object.is_empty(), "{context}");
            let words = words(&module);

            let retained_args = [
                aarch64_mov_x(16, 0).unwrap(),
                aarch64_mov_x(17, 3).unwrap(),
            ];
            assert_eq!(
                words.windows(retained_args.len())
                    .filter(|window| *window == retained_args)
                    .count(),
                1,
                "{context}"
            );

            let flags = [
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V7, true),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V6, true),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3, false),
                (FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS, true),
            ];
            let selections = flags
                .iter()
                .map(|&(flag, framed)| {
                    let needle = flag_words(flag);
                    let index = words
                        .windows(needle.len())
                        .position(|window| window == needle)
                        .unwrap_or_else(|| panic!("{context}: missing flag {flag:#x}"));
                    (index, framed)
                })
                .collect::<Vec<_>>();
            assert!(
                selections.windows(2).all(|pair| pair[0].0 < pair[1].0),
                "{context}"
            );

            let frame = words
                .iter()
                .position(|&word| word == aarch64_sub_x_imm(31, 31, 96).unwrap())
                .unwrap();
            assert!(
                selections[9].0 < frame && frame < selections[10].0,
                "{context}: every compact guard must precede the legacy frame"
            );

            for (format_index, pair) in selections.windows(2).enumerate().take(10) {
                let branches = (pair[0].0..pair[1].0)
                    .filter(|&index| words[index] & 0xfc00_0000 == 0x1400_0000)
                    .collect::<Vec<_>>();
                if format_index == 9 {
                    assert!(!branches.is_empty(), "{context}: selector {format_index}");
                } else {
                    assert_eq!(branches.len(), 1, "{context}: selector {format_index}");
                }
                let target = branch_target(&words, branches[0]);
                if pair[0].1 {
                    let route = if format_index == 1 { 1 } else { 2 };
                    assert_eq!(
                        words[target],
                        aarch64_movz_w(12, route).unwrap(),
                        "{context}: V7/V6 must select a framed route"
                    );
                    assert_eq!(branch_target(&words, target + 1), frame, "{context}");
                } else {
                    assert!(target > selections[10].0, "{context}: selector {format_index}");
                    assert_ne!(target, frame, "{context}: selector {format_index}");
                }
            }

            let scan_window = [
                aarch64_mov_x(0, 1).unwrap(),
                aarch64_mov_x(1, 2).unwrap(),
                aarch64_mov_x(2, 17).unwrap(),
                aarch64_mov_x(3, 4).unwrap(),
            ];
            assert_eq!(
                words.windows(scan_window.len())
                    .filter(|window| *window == scan_window)
                    .count(),
                8,
                "{context}: seven table formats plus V4's singleton route"
            );
            let store_zero_result = aarch64_store_pair_x(31, 31, 5, 0).unwrap();
            for status in [0_u16, 1] {
                let exit = [
                    aarch64_movz_w(0, status).unwrap(),
                    store_zero_result,
                    0xd65f_03c0,
                ];
                assert_eq!(
                    words.windows(exit.len()).filter(|window| *window == exit).count(),
                    1,
                    "{context}: stackless status {status}"
                );
            }
            let simd_identity = aarch64_load_pair_q(16, 17, 6, 0).unwrap();
            assert_eq!(
                words.contains(&simd_identity),
                target.features.has(CpuFeature::Aarch64Asimd),
                "{context}"
            );
        }
    }

    #[cfg(all(target_arch = "aarch64", any(target_os = "linux", target_os = "macos")))]
    #[test]
    #[ignore = "requires `cargo build -p fre-aot-regex-runtime --lib`; links the stackless Exists leaf at ASIMD, pure-SVE, and pure-SVE2 target tiers"]
    fn linked_host_aarch64_stackless_exists_feature_tiers_match_runtime() {
        let window = SearchWindow::new(5, 69);
        let absent = (0..73)
            .map(|index| if index & 1 == 0 { 0_u8 } else { 1_u8 })
            .collect::<Vec<_>>();
        let warm = absent.clone();
        let mut matching = absent.clone();
        matching[37..39].copy_from_slice(&[3, 3]);
        let program = scanner_free_dynamic_program(
            scanner_free_direct_u16_columns_raw(),
            OutputContract::Exists,
        );
        let mut workspace = program.prepare_workspace().unwrap();
        let storage = program
            .compiler_private_frozen_dynamic_rows_storage_v3(
                &mut workspace,
                512 * 1024,
                512 * 1024,
            )
            .expect("linked stackless V8 owner");
        assert_eq!(storage.format_version(), FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION);

        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let sve = FeatureSet::of(CpuFeature::Aarch64Sve);
        let sve2 = sve.with(CpuFeature::Aarch64Sve2);
        let base = if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        for (tier, features) in [("asimd", asimd), ("sve", sve), ("sve2", sve2)] {
            let target = base.with_features(features).unwrap();
            link_real_dynamic_first_hole_cases(
                &program,
                target,
                false,
                true,
                false,
                &format!("StacklessExists-{tier}"),
                window,
                &[
                    LinkedDynamicFirstHoleCase {
                        warm: &warm,
                        novel: &matching,
                        expected_status: 1,
                        expected_start: 0,
                        expected_end: 0,
                    },
                    LinkedDynamicFirstHoleCase {
                        warm: &warm,
                        novel: &absent,
                        expected_status: 0,
                        expected_start: 0,
                        expected_end: 0,
                    },
                ],
            );
        }
    }

    #[test]
    fn compact_entries_precede_legacy_short_window_crossover_cross_isa() {
        let x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::SelectedEnd,
            None,
            true,
            false,
        )
        .unwrap();
        let x86_frame = [0x48, 0x83, 0xec, 104];
        let mut x86_v12_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        x86_v12_flag
            .extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12.to_le_bytes());
        let x86_minimum = [
            0x48,
            0x3d,
            u8::try_from(DYNAMIC_NATIVE_ROWS_MIN_INPUT_BYTES).unwrap(),
            0,
            0,
            0,
        ];
        let x86_position = |needle: &[u8]| {
            x86.code
                .windows(needle.len())
                .position(|window| window == needle)
                .unwrap()
        };
        assert!(x86_position(&x86_frame) < x86_position(&x86_v12_flag));
        assert!(x86_position(&x86_v12_flag) < x86_position(&x86_minimum));
        assert_eq!(
            x86.code
                .windows(x86_minimum.len())
                .filter(|window| *window == x86_minimum)
                .count(),
            1
        );

        let arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
            None,
            OutputContract::SelectedEnd,
            None,
            true,
            false,
        )
        .unwrap();
        let words = arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_frame = aarch64_sub_x_imm(31, 31, 96).unwrap();
        let arm_v12_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        let arm_minimum = aarch64_cmp_x_imm(
            8,
            u16::try_from(DYNAMIC_NATIVE_ROWS_MIN_INPUT_BYTES).unwrap(),
        )
        .unwrap();
        let frame_position = words.iter().position(|&word| word == arm_frame).unwrap();
        let flag_position = words
            .windows(arm_v12_flag.len())
            .position(|window| window == arm_v12_flag)
            .unwrap();
        let minimum_position = words
            .iter()
            .position(|&word| word == arm_minimum)
            .unwrap();
        assert!(frame_position < flag_position);
        assert!(flag_position < minimum_position);
        assert_eq!(words.iter().filter(|&&word| word == arm_minimum).count(), 1);
    }

    #[test]
    fn scanner_free_immutable_exists_keeps_x86_leaf_frame_off_hot_entry() {
        let exists = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::Exists,
            None,
            true,
            true,
        )
        .unwrap();
        let selected = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::SelectedEnd,
            None,
            true,
            true,
        )
        .unwrap();
        let frame = [0x48, 0x83, 0xec, 104];
        let mut v5_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        v5_flag.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5.to_le_bytes());
        let mut v12_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        v12_flag.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12.to_le_bytes());
        let position = |code: &[u8], needle: &[u8]| {
            code.windows(needle.len())
                .position(|window| window == needle)
                .unwrap_or_else(|| panic!("missing x86 sequence {needle:02x?}"))
        };

        let exists_flag = position(&exists.code, &v5_flag);
        let exists_frame = position(&exists.code, &frame);
        let selected_flag = position(&selected.code, &v12_flag);
        let selected_frame = position(&selected.code, &frame);
        assert!(exists_flag < exists_frame);
        assert!(selected_frame < selected_flag);

        // XMM4..XMM10 retain handle, haystack, length, start, end, output,
        // and linked identity. The active guard consumes only XMM0..XMM3.
        for save in [
            [0x66, 0x48, 0x0f, 0x6e, 0xe7],
            [0x66, 0x48, 0x0f, 0x6e, 0xee],
            [0x66, 0x48, 0x0f, 0x6e, 0xf2],
            [0x66, 0x48, 0x0f, 0x6e, 0xf9],
            [0x66, 0x4d, 0x0f, 0x6e, 0xc0],
            [0x66, 0x4d, 0x0f, 0x6e, 0xc9],
            [0x66, 0x4c, 0x0f, 0x6e, 0xd0],
        ] {
            assert!(position(&exists.code, &save) < exists_flag);
        }
        assert!(!exists.code[..exists_flag]
            .windows(frame.len())
            .any(|window| window == frame));

        let no_match_leaf = [
            0x31, 0xc0, 0x66, 0x4d, 0x0f, 0x7e, 0xc9, 0x49, 0x89, 0x01, 0x49, 0x89, 0x41,
            0x08, 0xc3,
        ];
        let match_leaf = [
            0x31, 0xc0, 0x66, 0x4d, 0x0f, 0x7e, 0xc9, 0x49, 0x89, 0x01, 0x49, 0x89, 0x41,
            0x08, 0xb8, 1, 0, 0, 0, 0xc3,
        ];
        assert!(exists
            .code
            .windows(no_match_leaf.len())
            .any(|window| window == no_match_leaf));
        assert!(exists
            .code
            .windows(match_leaf.len())
            .any(|window| window == match_leaf));
    }

    #[test]
    fn compact_u8_v12_and_direct_v8_v10_codegen_omit_dead_v9_production() {
        fn byte_occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        fn word_occurrences(words: &[u32], needle: &[u32]) -> usize {
            words
                .windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let filter = dynamic_root_test_filter(b"a", 0);
        let x86_runtime_class_gate = [
            0x41,
            0x81,
            0x7b,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_CLASS_COUNT_OFFSET).unwrap(),
            0x00,
            0x01,
            0x00,
            0x00,
        ];
        let x86_flag_compare = |flag: u32| {
            let mut compare = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            compare.extend_from_slice(&flag.to_le_bytes());
            compare
        };
        let x86_v8_flag = x86_flag_compare(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8);
        let x86_v9_flag = x86_flag_compare(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9);
        let x86_v10_flag = x86_flag_compare(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10);
        let x86_v12_flag = x86_flag_compare(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12);
        let x86_mapped_body = [
            0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f, 0xb7, 0x14,
            0x50,
        ];
        let x86_direct_body = [0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb7, 0x14, 0x50];
        let x86_direct_u8_body = [0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb6, 0x14, 0x10];
        let x86_mapped_u8_body = [
            0x44, 0x0f, 0xb6, 0x14, 0x17, 0x47, 0x0f, 0xb6, 0x14, 0x11, 0x47, 0x0f,
            0xb6, 0x14, 0x10,
        ];
        for (context, root) in [
            ("scanner-free", None),
            ("rooted", Some(X86DynamicRootPlan::Range(filter))),
        ] {
            let without = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
                root,
                FeatureSet::EMPTY,
                OutputContract::Exists,
                None,
                true,
                false,
            )
            .unwrap();
            let with = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
                root,
                FeatureSet::EMPTY,
                OutputContract::Exists,
                None,
                true,
                true,
            )
            .unwrap();
            assert!(without.code.len() < with.code.len(), "x86 {context}");
            for (emission, direct_count, flag_count) in [(&without, 0, 0), (&with, 1, 1)] {
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_runtime_class_gate),
                    0,
                    "x86 {context}: ordinary V4 must never select a raw loop by C=256"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_direct_body),
                    direct_count,
                    "x86 {context}: raw-byte direct body"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_direct_u8_body),
                    flag_count,
                    "x86 {context}: compact-u8 V10 body"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_mapped_body),
                    if root.is_some() { 20 } else { 12 },
                    "x86 {context}: mapped V7/V6/V4/V3 bodies"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_mapped_u8_body),
                    if root.is_some() { 9 } else { 1 },
                    "x86 {context}: mapped compact-u8 V12 bodies"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_v8_flag),
                    flag_count,
                    "x86 {context}: exact V8 flag selector"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_v9_flag),
                    0,
                    "x86 {context}: dominated V9 has no production selector"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_v10_flag),
                    flag_count,
                    "x86 {context}: exact V10 flag selector"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &x86_v12_flag),
                    1,
                    "x86 {context}: exact V12 flag selector"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &[0x48, 0x83, 0xf8, 0x06]),
                    if root.is_some() { flag_count } else { 0 },
                    "x86 {context}: V8 root representation"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &[0x48, 0x83, 0xf8, 0x07]),
                    0,
                    "x86 {context}: dominated V9 has no root representation"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &[0x48, 0x83, 0xf8, 0x08]),
                    if root.is_some() { flag_count } else { 0 },
                    "x86 {context}: V10 root representation"
                );
                assert_eq!(
                    byte_occurrences(&emission.code, &[0x48, 0x83, 0xf8, 0x09]),
                    usize::from(root.is_some()),
                    "x86 {context}: V12 root representation"
                );
            }
        }

        let arm_runtime_class_gate = [
            aarch64_load_w_imm(
                8,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_CLASS_COUNT_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_cmp_w_imm(8, 256).unwrap(),
        ];
        let arm_flag_selector = |flag: u32| {
            [
                aarch64_load_w_imm(
                    8,
                    0,
                    u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
                )
                .unwrap(),
                aarch64_movz_x(9, u16::try_from(flag).unwrap(), 0).unwrap(),
                aarch64_cmp_w(8, 9).unwrap(),
            ]
        };
        let arm_v8_flag = arm_flag_selector(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8);
        let arm_v9_flag = arm_flag_selector(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9);
        let arm_v10_flag = arm_flag_selector(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10);
        let arm_v12_flag = arm_flag_selector(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12);
        let mut data = vec![0_u8; 32];
        let rooted =
            install_aarch64_dynamic_root_plan(&mut data, 0, filter, Target::aarch64_linux())
                .unwrap();
        for (context, root) in [
            ("scanner-free", None),
            ("rooted", Some(Aarch64DynamicScannerPlan::Range(rooted))),
        ] {
            let without = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
                root,
                OutputContract::Exists,
                None,
                true,
                false,
            )
            .unwrap();
            let with = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
                root,
                OutputContract::Exists,
                None,
                true,
                true,
            )
            .unwrap();
            assert!(without.code.len() < with.code.len(), "AArch64 {context}");
            let legacy_raw_load = if root.is_some() {
                aarch64_load_byte_reg(8, 0, 2).unwrap()
            } else {
                aarch64_load_byte_post_imm(8, 2, 1).unwrap()
            };
            let paired_v4_raw_load = if root.is_some() {
                aarch64_load_byte_reg(8, 0, 2).unwrap()
            } else {
                aarch64_load_byte_imm(8, 2, 0).unwrap()
            };
            let mapped_body = [
                paired_v4_raw_load,
                aarch64_load_byte_reg(8, 14, 8).unwrap(),
                aarch64_load_h_uxtw(8, 11, 8).unwrap(),
            ];
            let indexed_mapped_body = [
                aarch64_load_byte_reg(8, 0, 2).unwrap(),
                aarch64_load_byte_reg(8, 14, 8).unwrap(),
                aarch64_load_h_uxtw(8, 11, 8).unwrap(),
            ];
            let direct_v9_body = [
                legacy_raw_load,
                aarch64_load_h_uxtw(8, 11, 8).unwrap(),
            ];
            let v8_raw_load = if root.is_some() {
                aarch64_load_byte_reg(6, 0, 2).unwrap()
            } else {
                aarch64_load_byte_imm(6, 2, 0).unwrap()
            };
            let direct_v8_body = [v8_raw_load, aarch64_load_h_uxtw(8, 11, 6).unwrap()];
            let paired_u8_raw_load = if root.is_some() {
                aarch64_load_byte_reg(6, 0, 2).unwrap()
            } else {
                aarch64_load_byte_imm(6, 2, 0).unwrap()
            };
            let direct_v10_body = [
                paired_u8_raw_load,
                aarch64_load_byte_reg(8, 11, 6).unwrap(),
            ];
            let mapped_v12_body = [
                paired_u8_raw_load,
                aarch64_load_byte_reg(6, 14, 6).unwrap(),
                aarch64_load_byte_reg(8, 11, 6).unwrap(),
            ];
            for (emission, direct_count) in [(&without, 0), (&with, 1)] {
                let words = emission
                    .code
                    .chunks_exact(4)
                    .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                    .collect::<Vec<_>>();
                assert_eq!(
                    word_occurrences(&words, &arm_runtime_class_gate),
                    0,
                    "AArch64 {context}: ordinary V4 must never select a raw loop by C=256"
                );
                assert_eq!(
                    word_occurrences(&words, &direct_v9_body),
                    0,
                    "AArch64 {context}: dominated V9 has no production body"
                );
                assert_eq!(
                    word_occurrences(&words, &direct_v8_body),
                    direct_count,
                    "AArch64 {context}: raw-byte V8 body"
                );
                assert_eq!(
                    word_occurrences(&words, &direct_v10_body),
                    direct_count,
                    "AArch64 {context}: compact-u8 V10 body"
                );
                assert_eq!(
                    word_occurrences(&words, &mapped_v12_body),
                    if root.is_some() { 9 } else { 1 },
                    "AArch64 {context}: mapped compact-u8 V12 bodies"
                );
                assert_eq!(
                    word_occurrences(&words, &mapped_body),
                    if root.is_some() { 2 } else { 1 },
                    "AArch64 {context}: mapped V4 plus indexed V7 when the cursor representation agrees"
                );
                assert_eq!(
                    word_occurrences(&words, &indexed_mapped_body),
                    if root.is_some() { 2 } else { 1 },
                    "AArch64 {context}: V7 retains its offset cursor while rooted V4 shares that representation"
                );
                assert_eq!(
                    word_occurrences(&words, &arm_v8_flag),
                    direct_count,
                    "AArch64 {context}: exact V8 flag selector"
                );
                assert_eq!(
                    word_occurrences(&words, &arm_v9_flag),
                    0,
                    "AArch64 {context}: dominated V9 has no production selector"
                );
                assert_eq!(
                    word_occurrences(&words, &arm_v10_flag),
                    direct_count,
                    "AArch64 {context}: exact V10 flag selector"
                );
                assert_eq!(
                    word_occurrences(&words, &arm_v12_flag),
                    1,
                    "AArch64 {context}: exact V12 flag selector"
                );
                assert_eq!(
                    words
                        .iter()
                        .filter(|&&word| word == aarch64_cmp_x_imm(8, 6).unwrap())
                        .count(),
                    if root.is_some() { direct_count } else { 0 },
                    "AArch64 {context}: V8 root representation"
                );
                assert_eq!(
                    words
                        .iter()
                        .filter(|&&word| word == aarch64_cmp_x_imm(8, 7).unwrap())
                        .count(),
                    0,
                    "AArch64 {context}: dominated V9 has no root representation"
                );
                assert_eq!(
                    words
                        .iter()
                        .filter(|&&word| word == aarch64_cmp_x_imm(8, 8).unwrap())
                        .count(),
                    if root.is_some() { direct_count } else { 0 },
                    "AArch64 {context}: V10 root representation"
                );
                assert_eq!(
                    words
                        .iter()
                        .filter(|&&word| word == aarch64_cmp_x_imm(8, 9).unwrap())
                        .count(),
                    usize::from(root.is_some()),
                    "AArch64 {context}: V12 root representation"
                );
            }
        }
    }

    #[test]
    fn compact_format_full_verifiers_require_exact_u8_geometry_cross_isa() {
        fn byte_occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        assert_eq!(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8, 1 << 9);
        assert_eq!(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9, 1 << 10);
        assert_eq!(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10, 1 << 11);
        assert_eq!(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12, 1 << 13);
        let x86_class_256 = [0x41, 0x81, 0xf8, 0x00, 0x01, 0x00, 0x00];
        let arm_class_256 = aarch64_cmp_w_imm(11, 256).unwrap();
        for (format, flag, version, seal) in [
            (
                FrozenCompactNativeFormat::StateOrdinalDirectV8,
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8,
                FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION,
                FROZEN_PREPARED_HEADER_V8_READY_SEAL,
            ),
            (
                FrozenCompactNativeFormat::CellOffsetDirectV9,
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9,
                FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION,
                FROZEN_PREPARED_HEADER_V9_READY_SEAL,
            ),
            (
                FrozenCompactNativeFormat::StateOrdinalDirectU8V10,
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10,
                FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION,
                FROZEN_PREPARED_HEADER_V10_READY_SEAL,
            ),
            (
                FrozenCompactNativeFormat::StateOrdinalMappedU8V12,
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12,
                FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION,
                FROZEN_PREPARED_HEADER_V12_READY_SEAL,
            ),
        ] {
            let mut x86 = X86Assembler::new();
            let try_older = x86.label().unwrap();
            let preflight = x86.label().unwrap();
            let enter = x86.label().unwrap();
            x86_emit_frozen_compact_entry(
                &mut x86,
                format,
                try_older,
                preflight,
                enter,
                FrozenCompactGuardMode::FullVerifier,
            )
            .unwrap();
            for label in [try_older, preflight, enter] {
                x86.bind(label).unwrap();
                x86.instruction(&[0xc3]).unwrap();
            }
            let x86 = x86.finish().unwrap();
            let mut flag_compare = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            flag_compare.extend_from_slice(&flag.to_le_bytes());
            assert_eq!(byte_occurrences(&x86, &flag_compare), 1);
            let mut format_compare = vec![
                0x41,
                0x81,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
            ];
            format_compare.extend_from_slice(&version.to_le_bytes());
            assert_eq!(byte_occurrences(&x86, &format_compare), 1);
            let mut ready_seal = vec![0x49, 0xba];
            ready_seal.extend_from_slice(&seal.to_le_bytes());
            assert_eq!(byte_occurrences(&x86, &ready_seal), 1);
            assert_eq!(
                byte_occurrences(&x86, &x86_class_256),
                if format.is_direct_byte() { 2 } else { 1 },
                "{format:?}: inclusive maximum plus optional exact direct-byte C=256 proof"
            );
            if format.is_u8() {
                assert_eq!(byte_occurrences(&x86, &[0x83, 0xf8, 0x7f]), 1);
                assert_eq!(
                    byte_occurrences(&x86, &[0x83, 0xf9, 0x08]),
                    1,
                    "compact-u8 must bound its physical-row exponent"
                );
                assert_eq!(byte_occurrences(&x86, &[0x48, 0xd3, 0xe2]), 1);
                assert_eq!(
                    byte_occurrences(&x86, &[0x41, 0xf6, 0xc2, 0x01]),
                    0,
                    "compact-u8 ownership must not assume u16 pointer alignment"
                );
            }

            let mut arm = Aarch64Assembler::new();
            let try_older = arm.label().unwrap();
            let preflight = arm.label().unwrap();
            let enter = arm.label().unwrap();
            aarch64_emit_frozen_compact_entry(
                &mut arm,
                format,
                try_older,
                preflight,
                enter,
                FrozenCompactGuardMode::FullVerifier,
            )
            .unwrap();
            for label in [try_older, preflight, enter] {
                arm.bind(label).unwrap();
                arm.instruction(0xd503_201f).unwrap();
            }
            let arm = arm
                .finish()
                .unwrap()
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(
                arm.iter().filter(|&&word| word == arm_class_256).count(),
                if format.is_direct_byte() { 2 } else { 1 },
                "{format:?}: inclusive maximum plus optional exact direct-byte C=256 proof"
            );
            if format.is_u8() {
                assert!(arm.contains(&aarch64_cmp_w_imm(10, 127).unwrap()));
                assert!(arm.contains(&aarch64_cmp_w_imm(12, 8).unwrap()));
                assert!(arm.contains(&aarch64_lslv_x(9, 9, 12).unwrap()));
                assert!(
                    !arm.contains(&aarch64_and_low_x(9, 8, 1).unwrap()),
                    "compact-u8 ownership must not assume u16 pointer alignment"
                );
            }
            let flag_selector = [
                aarch64_load_w_imm(
                    8,
                    0,
                    u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
                )
                .unwrap(),
                aarch64_movz_x(9, u16::try_from(flag).unwrap(), 0).unwrap(),
                aarch64_cmp_w(8, 9).unwrap(),
            ];
            assert_eq!(
                arm.windows(flag_selector.len())
                    .filter(|words| *words == flag_selector)
                    .count(),
                1
            );
        }
    }

    #[test]
    fn reverse_supertransition_active_guards_admit_exact_base_and_combined_flags() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let format = FrozenCompactNativeFormat::CellOffsetV4;
        let base_flag = format.flag();
        let combined_flag = base_flag | FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION;
        let x86_flag_compare = |flag: u32| {
            let mut bytes = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(&flag.to_le_bytes());
            bytes
        };
        let mut x86 = X86Assembler::new();
        let x86_try_older = x86.label().unwrap();
        let x86_preflight = x86.label().unwrap();
        let x86_enter = x86.label().unwrap();
        x86_emit_frozen_compact_entry(
            &mut x86,
            format,
            x86_try_older,
            x86_preflight,
            x86_enter,
            FrozenCompactGuardMode::ActiveCapabilitySimdIdentityReverseSupertransition,
        )
        .unwrap();
        for label in [x86_try_older, x86_preflight, x86_enter] {
            x86.bind(label).unwrap();
            x86.instruction(&[0xc3]).unwrap();
        }
        let x86 = x86.finish().unwrap();
        assert_eq!(occurrences(&x86, &x86_flag_compare(combined_flag)), 1);
        assert_eq!(occurrences(&x86, &x86_flag_compare(base_flag)), 1);
        assert_eq!(
            occurrences(
                &x86,
                &[
                    0x48,
                    0x81,
                    0x7f,
                    u8::try_from(FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET).unwrap(),
                ],
            ),
            0,
            "active owner capability must not pay the full extent verifier"
        );

        let mut arm = Aarch64Assembler::new();
        let arm_try_older = arm.label().unwrap();
        let arm_preflight = arm.label().unwrap();
        let arm_enter = arm.label().unwrap();
        aarch64_emit_frozen_compact_entry(
            &mut arm,
            format,
            arm_try_older,
            arm_preflight,
            arm_enter,
            FrozenCompactGuardMode::ActiveCapabilityReverseSupertransition,
        )
        .unwrap();
        for label in [arm_try_older, arm_preflight, arm_enter] {
            arm.bind(label).unwrap();
            arm.instruction(0xd503_201f).unwrap();
        }
        let arm_words = arm
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let combined_selector = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(9, u16::try_from(base_flag).unwrap(), 0).unwrap(),
            aarch64_movk_x(9, 1, 1).unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_words
                .windows(combined_selector.len())
                .filter(|words| *words == combined_selector)
                .count(),
            1
        );
        let base_selector = [
            aarch64_movz_x(9, u16::try_from(base_flag).unwrap(), 0).unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_words
                .windows(base_selector.len())
                .filter(|words| *words == base_selector)
                .count(),
            1
        );
        assert!(!arm_words.contains(
            &aarch64_load_x_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET).unwrap(),
            )
            .unwrap()
        ));
    }

    #[test]
    fn reverse_supertransition_postflight_is_emitted_cross_isa() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        let mut modifier_test = vec![
            0xf7,
            0x40,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        modifier_test.extend_from_slice(
            &FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION.to_le_bytes(),
        );
        assert_eq!(occurrences(&x86.code, &modifier_test), 1);
        assert!(x86.code.windows(4).any(|bytes| {
            bytes
                == [
                    0x48,
                    0x8b,
                    0x78,
                    u8::try_from(FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET).unwrap(),
                ]
        }));
        let mut format_load = vec![0x44, 0x8b, 0x97];
        format_load.extend_from_slice(
            &i32::try_from(FROZEN_REVERSE_SUPERTRANSITION_V1_FORMAT_VERSION_OFFSET)
                .unwrap()
                .to_le_bytes(),
        );
        assert_eq!(occurrences(&x86.code, &format_load), 1);
        let mut inline_map = vec![0x4c, 0x8d, 0x87];
        inline_map.extend_from_slice(
            &i32::try_from(FROZEN_REVERSE_SUPERTRANSITION_V1_CLASS_MAP_OFFSET)
                .unwrap()
                .to_le_bytes(),
        );
        assert_eq!(occurrences(&x86.code, &inline_map), 1);
        assert!(x86.code.windows(4).any(|bytes| {
            bytes
                == [
                    0x48,
                    0x8b,
                    0x78,
                    u8::try_from(FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET).unwrap(),
                ]
        }));
        assert!(occurrences(&x86.code, &[0x0f, 0xb7, 0x04, 0x41]) >= 2);

        let arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
            None,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        let arm_words = arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert!(arm_words.contains(
            &aarch64_load_x_imm(
                6,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_REVERSE_LIVE_CELLS_OFFSET).unwrap(),
            )
            .unwrap()
        ));
        assert!(arm_words.contains(
            &aarch64_load_w_imm(
                10,
                6,
                u16::try_from(FROZEN_REVERSE_SUPERTRANSITION_V1_FORMAT_VERSION_OFFSET).unwrap(),
            )
            .unwrap()
        ));
        assert!(arm_words.contains(
            &aarch64_add_x_imm(
                14,
                6,
                u16::try_from(FROZEN_REVERSE_SUPERTRANSITION_V1_CLASS_MAP_OFFSET).unwrap(),
            )
            .unwrap()
        ));
        assert!(arm_words.contains(&aarch64_madd_w(10, 10, 17, 16).unwrap()));
        assert!(arm_words.contains(&aarch64_load_h_uxtw(10, 11, 10).unwrap()));
        assert!(arm_words.contains(
            &aarch64_load_x_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET).unwrap(),
            )
            .unwrap()
        ));
    }

    #[test]
    fn compact_variable_span_full_verifier_checks_reverse_geometry_cross_isa() {
        let source_class_count = 7_u16;
        let mut x86 = X86Assembler::new();
        let x86_try_older = x86.label().unwrap();
        let x86_preflight = x86.label().unwrap();
        let x86_enter = x86.label().unwrap();
        x86_emit_frozen_compact_entry(
            &mut x86,
            FrozenCompactNativeFormat::CellOffsetV4,
            x86_try_older,
            x86_preflight,
            x86_enter,
            FrozenCompactGuardMode::FullVerifierVariableSpan(source_class_count),
        )
        .unwrap();
        for label in [x86_try_older, x86_preflight, x86_enter] {
            x86.bind(label).unwrap();
            x86.instruction(&[0xc3]).unwrap();
        }
        let x86 = x86.finish().unwrap();
        assert_eq!(
            x86.windows(3)
                .filter(|bytes| *bytes == [0x48, 0xf7, 0xf1])
                .count(),
            2,
            "live extent and initial row require exact source-stride remainders"
        );
        assert!(x86.windows(4).any(|bytes| {
            bytes
                == [
                    0x4c,
                    0x8b,
                    0x57,
                    u8::try_from(FROZEN_PREPARED_HEADER_V1_REVERSE_ROWS_ADDRESS_OFFSET)
                        .unwrap(),
                ]
        }));
        assert!(x86.windows(4).any(|bytes| bytes == [0x41, 0xf6, 0xc2, 0x03]));

        let mut arm = Aarch64Assembler::new();
        let arm_try_older = arm.label().unwrap();
        let arm_preflight = arm.label().unwrap();
        let arm_enter = arm.label().unwrap();
        aarch64_emit_frozen_compact_entry(
            &mut arm,
            FrozenCompactNativeFormat::CellOffsetV4,
            arm_try_older,
            arm_preflight,
            arm_enter,
            FrozenCompactGuardMode::FullVerifierVariableSpan(source_class_count),
        )
        .unwrap();
        for label in [arm_try_older, arm_preflight, arm_enter] {
            arm.bind(label).unwrap();
            arm.instruction(0xd503_201f).unwrap();
        }
        let arm = arm
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert!(arm.contains(&aarch64_udiv_x(9, 8, 10).unwrap()));
        assert!(arm.contains(&aarch64_msub_x(9, 9, 10, 8).unwrap()));
        assert!(arm.contains(&aarch64_udiv_x(9, 11, 10).unwrap()));
        assert!(arm.contains(&aarch64_msub_x(9, 9, 10, 11).unwrap()));
        assert!(arm.contains(&aarch64_and_low_x(9, 8, 2).unwrap()));

        for invalid in [0_u16, 257] {
            let mut x86 = X86Assembler::new();
            let labels = [
                x86.label().unwrap(),
                x86.label().unwrap(),
                x86.label().unwrap(),
            ];
            assert!(x86_emit_frozen_compact_entry(
                &mut x86,
                FrozenCompactNativeFormat::CellOffsetV4,
                labels[0],
                labels[1],
                labels[2],
                FrozenCompactGuardMode::FullVerifierVariableSpan(invalid),
            )
            .is_err());
            assert!(x86.code.is_empty(), "invalid x86 geometry is transactional");

            let mut arm = Aarch64Assembler::new();
            let labels = [
                arm.label().unwrap(),
                arm.label().unwrap(),
                arm.label().unwrap(),
            ];
            assert!(aarch64_emit_frozen_compact_entry(
                &mut arm,
                FrozenCompactNativeFormat::CellOffsetV4,
                labels[0],
                labels[1],
                labels[2],
                FrozenCompactGuardMode::FullVerifierVariableSpan(invalid),
            )
            .is_err());
            assert!(
                arm.code.is_empty(),
                "invalid AArch64 geometry is transactional"
            );
        }
    }

    #[test]
    fn frozen_dynamic_stride_arithmetic_has_exact_cross_isa_encodings() {
        assert_eq!(aarch64_udiv_x(11, 10, 8).unwrap(), 0x9ac8_094b);
        assert_eq!(aarch64_msub_x(12, 11, 8, 10).unwrap(), 0x9b08_a96c);
        assert!(aarch64_udiv_x(32, 10, 8).is_err());
        assert!(aarch64_msub_x(12, 11, 32, 10).is_err());

        let x86 = lower_x86_64_dynamic_rows_prepared(None, FeatureSet::EMPTY).unwrap();
        assert_eq!(
            x86.code
                .windows(3)
                .filter(|bytes| *bytes == [0x48, 0xf7, 0xf1])
                .count(),
            6,
            "live, initial, and four loop rows each require an unsigned remainder check"
        );
        assert!(
            x86.code
                .windows(6)
                .any(|bytes| bytes == [0x81, 0xf9, 0x00, 0x01, 0x00, 0x00]),
            "x86 must admit the inclusive 256-class stride boundary"
        );

        let arm = lower_aarch64_dynamic_rows_prepared(None).unwrap();
        let words = arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            words
                .iter()
                .filter(|&&word| word == aarch64_udiv_x(11, 10, 8).unwrap())
                .count(),
            1,
            "AArch64 live-cell divisibility check"
        );
        assert_eq!(
            words
                .iter()
                .filter(|&&word| word == aarch64_udiv_x(11, 9, 8).unwrap())
                .count(),
            5,
            "AArch64 initial and loop-row divisibility checks"
        );
        assert!(words.contains(&aarch64_cmp_w_imm(8, 256).unwrap()));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one structural audit covers V14 geometry, exact tails, and both serial target loops"
    )]
    fn quad_supertransition_v14_is_exact_scanner_free_and_cross_isa() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let x86_flag = {
            let mut bytes = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(
                &FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14.to_le_bytes(),
            );
            bytes
        };
        let x86_version = {
            let mut bytes = vec![
                0x41,
                0x81,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(&FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION.to_le_bytes());
            bytes
        };
        let x86_ready = {
            let mut bytes = vec![0x49, 0xba];
            bytes.extend_from_slice(&FROZEN_PREPARED_HEADER_V14_READY_SEAL.to_le_bytes());
            bytes
        };
        let mut x86_guard = X86Assembler::new();
        let x86_try_older = x86_guard.label().unwrap();
        let x86_preflight = x86_guard.label().unwrap();
        let x86_enter = x86_guard.label().unwrap();
        x86_emit_frozen_compact_v14_entry(
            &mut x86_guard,
            x86_try_older,
            x86_preflight,
            x86_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [x86_try_older, x86_preflight, x86_enter] {
            x86_guard.bind(label).unwrap();
            x86_guard.instruction(&[0xc3]).unwrap();
        }
        let x86_guard = x86_guard.finish().unwrap();
        assert_eq!(occurrences(&x86_guard, &x86_flag), 1);
        assert_eq!(occurrences(&x86_guard, &x86_version), 1);
        assert_eq!(occurrences(&x86_guard, &x86_ready), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0xf6, 0xc2, 0x01]), 1);
        assert_eq!(occurrences(&x86_guard, &[0x3d, 0xff, 0x1f, 0, 0]), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0x83, 0xf8, 0x04]), 1);
        assert_eq!(
            occurrences(
                &x86_guard,
                &[
                    0x49, 0x89, 0xc2, 0x49, 0x29, 0xd2, 0x49, 0xff, 0xc2, 0x49, 0x81, 0xfa,
                    0xff, 0x1f, 0, 0,
                ],
            ),
            1,
            "V14 must prove its exact final aligned block-start token"
        );

        let mut arm_guard = Aarch64Assembler::new();
        let arm_try_older = arm_guard.label().unwrap();
        let arm_preflight = arm_guard.label().unwrap();
        let arm_enter = arm_guard.label().unwrap();
        aarch64_emit_frozen_compact_v14_entry(
            &mut arm_guard,
            arm_try_older,
            arm_preflight,
            arm_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [arm_try_older, arm_preflight, arm_enter] {
            arm_guard.bind(label).unwrap();
            arm_guard.instruction(0xd503_201f).unwrap();
        }
        let arm_guard = arm_guard.finish().unwrap();
        let arm_guard_words = arm_guard
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        let arm_combined_flag = [
            arm_flag[0],
            arm_flag[1],
            aarch64_movk_x(9, 1, 1).unwrap(),
            arm_flag[2],
        ];
        assert_eq!(
            arm_guard_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            1
        );
        assert!(arm_guard_words.contains(&aarch64_and_low_x(9, 8, 1).unwrap()));
        assert!(arm_guard_words.contains(&aarch64_cmp_w_imm(11, 4).unwrap()));
        assert!(arm_guard_words.windows(4).any(|words| {
            words
                == [
                    aarch64_sub_x_reg(8, 7, 9).unwrap(),
                    aarch64_add_x_imm(8, 8, 1).unwrap(),
                    aarch64_movz_x(6, DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK, 0).unwrap(),
                    aarch64_cmp_x(8, 6).unwrap(),
                ]
        }));
        let mut arm_ready = Aarch64Assembler::new();
        aarch64_load_u64_constant(
            &mut arm_ready,
            9,
            FROZEN_PREPARED_HEADER_V14_READY_SEAL,
        )
        .unwrap();
        let arm_ready = arm_ready.finish().unwrap();
        assert_eq!(occurrences(&arm_guard, &arm_ready), 1);

        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(2)),
        ] {
            let context = format!("{output:?}/width={exact_span_width:?}");
            let x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
                None,
                FeatureSet::EMPTY,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            assert_eq!(occurrences(&x86.code, &x86_flag), 1, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_version), 0, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_ready), 0, "{context}");
            assert!(
                occurrences(&x86.code, &[0x47, 0x8d, 0x14, 0x53]) >= 6,
                "C=2 fused Horner LEAs: {context}"
            );
            assert_eq!(
                occurrences(
                    &x86.code,
                    &[0x47, 0x8d, 0x14, 0x52, 0x45, 0x01, 0xda],
                ),
                6,
                "C=3 Horner LEA/add pairs: {context}"
            );
            assert!(
                occurrences(&x86.code, &[0x47, 0x8d, 0x14, 0x93]) >= 6,
                "C=4 fused Horner LEAs: {context}"
            );
            for block_bytes in [60_u32, 240, 680] {
                let mut scale = vec![0x45, 0x69, 0xd2];
                scale.extend_from_slice(&block_bytes.to_le_bytes());
                assert_eq!(
                    occurrences(&x86.code, &scale),
                    0,
                    "V14 cell-offset tokens need no scaling for block={block_bytes}: {context}"
                );
                let mut bias = vec![0x48, 0x81, 0xee];
                bias.extend_from_slice(&block_bytes.to_le_bytes());
                assert_eq!(occurrences(&x86.code, &bias), 0, "{context}");
            }
            for tail_offset in [16_u32, 24, 28, 81, 108, 117, 256, 320, 336] {
                let mut add = vec![0x41, 0x81, 0xc2];
                add.extend_from_slice(&tail_offset.to_le_bytes());
                assert!(occurrences(&x86.code, &add) >= 1, "{context}");
            }
            assert!(
                occurrences(&x86.code, &[0x4e, 0x8d, 0x44, 0x56, 0xfe]) >= 3,
                "every admitted alphabet needs a direct cell-offset backedge: {context}"
            );
            assert_eq!(
                occurrences(&x86.code, &[0x41, 0xc1, 0xeb, 0x0d]),
                if output == OutputContract::Exists { 0 } else { 12 },
                "main plus three exact-tail distance decoders per alphabet: {context}"
            );

            let arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
                None,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            let arm_words = arm
                .code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(
                arm_words
                    .windows(arm_flag.len())
                    .filter(|words| *words == arm_flag)
                    .count(),
                1,
                "{context}"
            );
            assert_eq!(occurrences(&arm.code, &arm_ready), 0, "{context}");
            assert!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_w_lsl(8, 10, 8, 1).unwrap())
                    .count()
                    >= 6,
                "C=2 fused Horner ADDs: {context}"
            );
            assert_eq!(
                arm_words
                    .windows(2)
                    .filter(|words| {
                        *words
                            == [
                                aarch64_add_w_lsl(8, 8, 8, 1).unwrap(),
                                aarch64_add_w_reg(8, 8, 10).unwrap(),
                            ]
                    })
                    .count(),
                6,
                "C=3 Horner shifted-ADD pairs: {context}"
            );
            assert!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_w_lsl(8, 10, 8, 2).unwrap())
                    .count()
                    >= 6,
                "C=4 fused Horner ADDs: {context}"
            );
            for block_bytes in [60_u16, 240, 680] {
                assert_eq!(
                    arm_words
                        .iter()
                        .filter(|&&word| {
                            word == aarch64_movz_x(12, block_bytes, 0).unwrap()
                        })
                        .count(),
                    0,
                    "{context}"
                );
                assert_eq!(
                    arm_words
                        .iter()
                        .filter(|&&word| {
                            word == aarch64_sub_x_imm(15, 15, block_bytes).unwrap()
                        })
                        .count(),
                    0,
                    "{context}"
                );
            }
            for tail_offset in [16_u16, 24, 28, 81, 108, 117, 256, 320, 336] {
                assert!(
                    arm_words
                        .iter()
                        .filter(|&&word| {
                            word == aarch64_add_x_imm(8, 8, tail_offset).unwrap()
                        })
                        .count()
                        >= 1,
                    "{context}"
                );
            }
            assert!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_x_uxtw(11, 15, 8, 1).unwrap())
                    .count()
                    >= 3,
                "one cell-offset backedge per admitted alphabet: {context}"
            );
            assert!(!arm_words.contains(&aarch64_add_x_reg(11, 15, 8).unwrap()));
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_lsr_w_imm(9, 8, 13).unwrap())
                    .count(),
                if output == OutputContract::Exists { 0 } else { 12 },
                "main plus three exact-tail distance decoders per alphabet: {context}"
            );
        }

        let variable_x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&variable_x86.code, &x86_flag), 1);
        let variable_arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
            None,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        let variable_arm_words = variable_arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            variable_arm_words
                .windows(arm_combined_flag.len())
                .filter(|words| *words == arm_combined_flag)
                .count(),
            1
        );
        let mut membership = [0_u64; 4];
        membership[usize::from(b'a') / 64] |= 1_u64 << (usize::from(b'a') % 64);
        let root_filter = plan_dynamic_root_filter(NativeDynamicRootRequirement {
            scan_offset: 0,
            membership,
        })
        .unwrap()
        .expect("nontrivial V14 exclusion root filter");
        let rooted_x86 = lower_x86_64_dynamic_rows_prepared_for_output(
            Some(root_filter),
            FeatureSet::EMPTY,
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&rooted_x86.code, &x86_flag), 0);

        let arm_target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .unwrap();
        let mut arm_data = vec![0_u8; 32];
        let arm_root = install_aarch64_dynamic_root_plan(
            &mut arm_data,
            0,
            root_filter,
            arm_target,
        )
        .unwrap();
        let rooted_arm = lower_aarch64_dynamic_rows_prepared_for_output(
            Some(arm_root),
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        let rooted_arm_words = rooted_arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            rooted_arm_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            0
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one structural audit covers dense V13 authentication, pair bounds, and both serial target loops"
    )]
    fn dense_pair_supertransition_v13_is_exact_scanner_free_and_cross_isa() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let x86_flag = {
            let mut bytes = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(
                &FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13.to_le_bytes(),
            );
            bytes
        };
        let x86_version = {
            let mut bytes = vec![
                0x41,
                0x81,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(&FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION.to_le_bytes());
            bytes
        };
        let x86_ready = {
            let mut bytes = vec![0x49, 0xba];
            bytes.extend_from_slice(&FROZEN_PREPARED_HEADER_V13_READY_SEAL.to_le_bytes());
            bytes
        };

        let mut x86_guard = X86Assembler::new();
        let x86_try_older = x86_guard.label().unwrap();
        let x86_preflight = x86_guard.label().unwrap();
        let x86_enter = x86_guard.label().unwrap();
        x86_emit_frozen_compact_v13_entry(
            &mut x86_guard,
            x86_try_older,
            x86_preflight,
            x86_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [x86_try_older, x86_preflight, x86_enter] {
            x86_guard.bind(label).unwrap();
            x86_guard.instruction(&[0xc3]).unwrap();
        }
        let x86_guard = x86_guard.finish().unwrap();
        assert_eq!(occurrences(&x86_guard, &x86_flag), 1);
        assert_eq!(occurrences(&x86_guard, &x86_version), 1);
        assert_eq!(occurrences(&x86_guard, &x86_ready), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0xf6, 0xc2, 0x01]), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0x83, 0xf8, 0x08]), 1);
        assert_eq!(
            occurrences(
                &x86_guard,
                &[
                    0x49, 0x89, 0xc2, 0x49, 0x29, 0xd2, 0x49, 0xff, 0xc2, 0x49, 0x81, 0xfa,
                    0xff, 0x3f, 0x00, 0x00,
                ],
            ),
            1,
            "V13 must prove its exact final aligned block-start token"
        );

        let mut arm_guard = Aarch64Assembler::new();
        let arm_try_older = arm_guard.label().unwrap();
        let arm_preflight = arm_guard.label().unwrap();
        let arm_enter = arm_guard.label().unwrap();
        aarch64_emit_frozen_compact_v13_entry(
            &mut arm_guard,
            arm_try_older,
            arm_preflight,
            arm_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [arm_try_older, arm_preflight, arm_enter] {
            arm_guard.bind(label).unwrap();
            arm_guard.instruction(0xd503_201f).unwrap();
        }
        let arm_guard = arm_guard.finish().unwrap();
        let arm_guard_words = arm_guard
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_guard_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            1
        );
        assert!(arm_guard_words.contains(&aarch64_and_low_x(9, 8, 1).unwrap()));
        assert!(arm_guard_words.contains(&aarch64_cmp_w_imm(11, 8).unwrap()));
        assert!(arm_guard_words.contains(&aarch64_movz_x(8, 0x3fff, 0).unwrap()));
        assert!(arm_guard_words.windows(4).any(|words| {
            words
                == [
                    aarch64_movz_x(8, DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK, 0).unwrap(),
                    aarch64_sub_x_reg(6, 7, 9).unwrap(),
                    aarch64_add_x_imm(6, 6, 1).unwrap(),
                    aarch64_cmp_x(6, 8).unwrap(),
                ]
        }));
        let mut arm_ready = Aarch64Assembler::new();
        aarch64_load_u64_constant(
            &mut arm_ready,
            9,
            FROZEN_PREPARED_HEADER_V13_READY_SEAL,
        )
        .unwrap();
        let arm_ready = arm_ready.finish().unwrap();
        assert_eq!(occurrences(&arm_guard, &arm_ready), 1);

        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(2)),
        ] {
            let context = format!("{output:?}/width={exact_span_width:?}");
            let x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
                None,
                FeatureSet::EMPTY,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            assert_eq!(occurrences(&x86.code, &x86_flag), 1, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_version), 0, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_ready), 0, "{context}");
            assert!(
                occurrences(&x86.code, &[0x47, 0x0f, 0xb7, 0x14, 0x50]) >= 1,
                "V13 must use one indexed u16 pair load: {context}"
            );
            assert!(
                occurrences(&x86.code, &[0x4e, 0x8d, 0x44, 0x56, 0xfe]) >= 1,
                "V13 must decode one-based u16 block tokens directly: {context}"
            );
            assert_eq!(
                occurrences(&x86.code, &[0x47, 0x0f, 0xb7, 0x1c, 0x58]),
                1,
                "V13 must load its exact odd-tail bitmap: {context}"
            );

            let arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
                None,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            let arm_words = arm
                .code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(
                arm_words
                    .windows(arm_flag.len())
                    .filter(|words| *words == arm_flag)
                    .count(),
                1,
                "{context}"
            );
            assert_eq!(occurrences(&arm.code, &arm_ready), 0, "{context}");
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_madd_w(8, 8, 12, 10).unwrap())
                    .count(),
                1,
                "one fused dense-pair key MADD: {context}"
            );
            assert!(arm_words.contains(&aarch64_load_h_uxtw(8, 11, 8).unwrap()));
            assert!(arm_words.contains(&aarch64_add_x_uxtw(11, 15, 8, 1).unwrap()));
            assert!(arm_words.contains(&aarch64_load_h_uxtw(10, 11, 9).unwrap()));
        }

        let variable_x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&variable_x86.code, &x86_flag), 1);

        let mut membership = [0_u64; 4];
        membership[usize::from(b'a') / 64] |= 1_u64 << (usize::from(b'a') % 64);
        let root_filter = plan_dynamic_root_filter(NativeDynamicRootRequirement {
            scan_offset: 0,
            membership,
        })
        .unwrap()
        .expect("nontrivial V13 exclusion root filter");
        let rooted_x86 = lower_x86_64_dynamic_rows_prepared_for_output(
            Some(root_filter),
            FeatureSet::EMPTY,
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&rooted_x86.code, &x86_flag), 0);

        let arm_target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .unwrap();
        let mut arm_data = vec![0_u8; 32];
        let arm_root = install_aarch64_dynamic_root_plan(
            &mut arm_data,
            0,
            root_filter,
            arm_target,
        )
        .unwrap();
        let rooted_arm = lower_aarch64_dynamic_rows_prepared_for_output(
            Some(arm_root),
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        let rooted_arm_words = rooted_arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            rooted_arm_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            0
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one structural audit covers the exact legacy V11 verifier and proves its dominated body is absent from production entries"
    )]
    fn pair_supertransition_v11_verifier_is_exact_but_production_entries_omit_it() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let x86_flag = {
            let mut bytes = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(
                &FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11.to_le_bytes(),
            );
            bytes
        };
        let x86_version = {
            let mut bytes = vec![
                0x41,
                0x81,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(&FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION.to_le_bytes());
            bytes
        };
        let x86_ready = {
            let mut bytes = vec![0x49, 0xba];
            bytes.extend_from_slice(&FROZEN_PREPARED_HEADER_V11_READY_SEAL.to_le_bytes());
            bytes
        };

        let mut x86_guard = X86Assembler::new();
        let x86_try_older = x86_guard.label().unwrap();
        let x86_preflight = x86_guard.label().unwrap();
        let x86_enter = x86_guard.label().unwrap();
        x86_emit_frozen_compact_v11_entry(
            &mut x86_guard,
            x86_try_older,
            x86_preflight,
            x86_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [x86_try_older, x86_preflight, x86_enter] {
            x86_guard.bind(label).unwrap();
            x86_guard.instruction(&[0xc3]).unwrap();
        }
        let x86_guard = x86_guard.finish().unwrap();
        assert_eq!(occurrences(&x86_guard, &x86_flag), 1);
        assert_eq!(occurrences(&x86_guard, &x86_version), 1);
        assert_eq!(occurrences(&x86_guard, &x86_ready), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0xf6, 0xc2, 0x03]), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0x83, 0xf8, 0x02]), 1);
        assert_eq!(occurrences(&x86_guard, &[0x41, 0x83, 0xf8, 0x04]), 1);
        assert_eq!(
            occurrences(&x86_guard, &[0x48, 0x3d, 0xff, 0xff, 0xff, 0x1f]),
            1,
            "V11 must prove its complete one-based u32 token extent"
        );

        let mut arm_guard = Aarch64Assembler::new();
        let arm_try_older = arm_guard.label().unwrap();
        let arm_preflight = arm_guard.label().unwrap();
        let arm_enter = arm_guard.label().unwrap();
        aarch64_emit_frozen_compact_v11_entry(
            &mut arm_guard,
            arm_try_older,
            arm_preflight,
            arm_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [arm_try_older, arm_preflight, arm_enter] {
            arm_guard.bind(label).unwrap();
            arm_guard.instruction(0xd503_201f).unwrap();
        }
        let arm_guard = arm_guard.finish().unwrap();
        let arm_guard_words = arm_guard
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_guard_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            1
        );
        assert!(arm_guard_words.contains(&aarch64_and_low_x(9, 8, 2).unwrap()));
        assert!(arm_guard_words.contains(&aarch64_cmp_w_imm(11, 2).unwrap()));
        assert!(arm_guard_words.contains(&aarch64_cmp_w_imm(11, 4).unwrap()));
        let mut arm_ready = Aarch64Assembler::new();
        aarch64_load_u64_constant(
            &mut arm_ready,
            9,
            FROZEN_PREPARED_HEADER_V11_READY_SEAL,
        )
        .unwrap();
        let arm_ready = arm_ready.finish().unwrap();
        assert_eq!(occurrences(&arm_guard, &arm_ready), 1);

        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(2)),
        ] {
            let context = format!("{output:?}/width={exact_span_width:?}");
            let x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
                None,
                FeatureSet::EMPTY,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            assert_eq!(occurrences(&x86.code, &x86_flag), 0, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_version), 0, "{context}");
            assert_eq!(occurrences(&x86.code, &x86_ready), 0, "{context}");
            assert_eq!(
                occurrences(&x86.code, &[0x47, 0x8d, 0x14, 0x53]),
                6,
                "V14 C=2 fused pair keys: {context}"
            );
            assert_eq!(
                occurrences(&x86.code, &[0x47, 0x8d, 0x14, 0x93]),
                6,
                "V14 C=4 fused pair keys: {context}"
            );
            assert_eq!(
                occurrences(&x86.code, &[0x47, 0x8b, 0x14, 0x90]),
                1,
                "only the legacy pointer-row load remains: {context}"
            );
            assert_eq!(
                occurrences(&x86.code, &[0x4e, 0x8d, 0x44, 0x96, 0xfc]),
                1,
                "only the legacy pointer-row update remains: {context}"
            );
            assert_eq!(occurrences(&x86.code, &[0x45, 0x8b, 0x58, 0x10]), 0);
            assert_eq!(occurrences(&x86.code, &[0x45, 0x8b, 0x58, 0x40]), 0);
            let initial_bound_prefix = [0x4c, 0x8d, 0x5a, 0x01, 0x49, 0x39, 0xcb];
            assert_eq!(
                x86.code
                    .windows(initial_bound_prefix.len())
                    .enumerate()
                    .filter(|(offset, bytes)| {
                        if *bytes != initial_bound_prefix {
                            return false;
                        }
                        matches!(
                            x86.code.get(offset + initial_bound_prefix.len()..),
                            Some([0x73, _, ..] | [0x0f, 0x83, _, _, _, _, ..])
                        )
                    })
                    .count(),
                1,
                "the dense V13 body must protect its second-byte load"
            );

            let arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
                None,
                output,
                exact_span_width,
                true,
                false,
            )
            .unwrap();
            let arm_words = arm
                .code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(
                arm_words
                    .windows(arm_flag.len())
                    .filter(|words| *words == arm_flag)
                    .count(),
                0,
                "{context}"
            );
            assert_eq!(occurrences(&arm.code, &arm_ready), 0, "{context}");
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_w_lsl(8, 10, 8, 1).unwrap())
                    .count(),
                6,
                "V14 C=2 fused pair keys: {context}"
            );
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_w_lsl(8, 10, 8, 2).unwrap())
                    .count(),
                6,
                "V14 C=4 fused pair keys: {context}"
            );
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_load_w_uxtw(8, 11, 8).unwrap())
                    .count(),
                0,
                "dominated V11 u32 pair loads must be absent: {context}"
            );
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_x_uxtw(11, 15, 8, 2).unwrap())
                    .count(),
                0,
                "dominated V11 block updates must be absent: {context}"
            );
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| {
                        word == aarch64_load_w_imm(10, 11, 16).unwrap()
                            || word == aarch64_load_w_imm(10, 11, 64).unwrap()
                    })
                    .count(),
                0,
                "dominated V11 odd-tail bitmaps must be absent: {context}"
            );
            let initial_bound_prefix = [
                aarch64_add_x_imm(9, 2, 1).unwrap(),
                aarch64_cmp_x(9, 3).unwrap(),
            ];
            assert_eq!(
                arm_words
                    .windows(3)
                    .filter(|words| {
                        words.starts_with(&initial_bound_prefix)
                            && words[2] & 0xff00_000f
                                == 0x5400_0000 | u32::from(AARCH64_HS)
                    })
                    .count(),
                1,
                "the dense V13 body must protect byte two: {context}"
            );
        }

        let variable_x86 = lower_x86_64_dynamic_rows_prepared_for_output_with_plan(
            None,
            FeatureSet::EMPTY,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&variable_x86.code, &x86_flag), 0);
        let variable_arm = lower_aarch64_dynamic_rows_prepared_for_output_with_plan(
            None,
            OutputContract::Span,
            None,
            true,
            true,
        )
        .unwrap();
        let variable_arm_words = variable_arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            variable_arm_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            0
        );

        let mut membership = [0_u64; 4];
        let byte = usize::from(b'a');
        membership[byte / 64] |= 1_u64 << (byte % 64);
        let root_filter = plan_dynamic_root_filter(NativeDynamicRootRequirement {
            scan_offset: 0,
            membership,
        })
        .unwrap()
        .expect("nontrivial V11 exclusion root filter");
        let rooted_x86 = lower_x86_64_dynamic_rows_prepared_for_output(
            Some(root_filter),
            FeatureSet::EMPTY,
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        assert_eq!(occurrences(&rooted_x86.code, &x86_flag), 0);

        let arm_target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .unwrap();
        let mut arm_data = vec![0_u8; 32];
        let arm_root = install_aarch64_dynamic_root_plan(
            &mut arm_data,
            0,
            root_filter,
            arm_target,
        )
        .unwrap();
        let rooted_arm = lower_aarch64_dynamic_rows_prepared_for_output(
            Some(arm_root),
            OutputContract::Exists,
            None,
            true,
        )
        .unwrap();
        let rooted_arm_words = rooted_arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            rooted_arm_words
                .windows(arm_flag.len())
                .filter(|words| *words == arm_flag)
                .count(),
            0
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one cross-ISA audit keeps compact generation selection, authentication, and row addressing together"
    )]
    fn frozen_compact_authentication_and_u16_hot_loops_are_exact_cross_isa() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        assert_eq!(
            aarch64_add_x_lsl(11, 15, 6, 1).unwrap(),
            0x8b00_0000 | (6_u32 << 16) | (1_u32 << 10) | (15_u32 << 5) | 11
        );
        assert_eq!(
            aarch64_add_x_lsl(11, 15, 6, 9).unwrap(),
            0x8b00_0000 | (6_u32 << 16) | (9_u32 << 10) | (15_u32 << 5) | 11
        );
        assert!(aarch64_add_x_lsl(11, 15, 6, 64).is_err());
        assert_eq!(
            aarch64_add_w_lsl(8, 10, 8, 2).unwrap(),
            0x0b00_0000 | (8_u32 << 16) | (2_u32 << 10) | (10_u32 << 5) | 8
        );
        assert!(aarch64_add_w_lsl(8, 10, 8, 32).is_err());
        assert_eq!(
            aarch64_madd_w(8, 8, 12, 10).unwrap(),
            0x1b00_0000 | (12_u32 << 16) | (10_u32 << 10) | (8_u32 << 5) | 8
        );
        assert_eq!(
            aarch64_madd_x(11, 6, 12, 15).unwrap(),
            0x9b00_0000 | (12_u32 << 16) | (15_u32 << 10) | (6_u32 << 5) | 11
        );
        assert_eq!(
            aarch64_add_x_uxtw(11, 15, 8, 1).unwrap(),
            0x8b20_4000 | (8_u32 << 16) | (1_u32 << 10) | (15_u32 << 5) | 11
        );
        assert!(aarch64_add_x_uxtw(11, 15, 8, 5).is_err());
        assert_eq!(
            aarch64_mul_x(7, 10, 9).unwrap(),
            0x9b00_7c00 | (9_u32 << 16) | (10_u32 << 5) | 7
        );
        assert_eq!(aarch64_lslv_x(9, 9, 8).unwrap(), 0x9ac8_2129);

        let mut x86_v4_auth = X86Assembler::new();
        let x86_v4_try_v3 = x86_v4_auth.label().unwrap();
        let x86_v4_preflight = x86_v4_auth.label().unwrap();
        let x86_v4_enter = x86_v4_auth.label().unwrap();
        x86_emit_frozen_compact_v4_entry(
            &mut x86_v4_auth,
            x86_v4_try_v3,
            x86_v4_preflight,
            x86_v4_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [x86_v4_try_v3, x86_v4_preflight, x86_v4_enter] {
            x86_v4_auth.bind(label).unwrap();
            x86_v4_auth.instruction(&[0xc3]).unwrap();
        }
        let x86_v4_auth = x86_v4_auth.finish().unwrap();
        let mut x86_v4_capability = X86Assembler::new();
        let x86_v4_capability_try_v3 = x86_v4_capability.label().unwrap();
        let x86_v4_capability_preflight = x86_v4_capability.label().unwrap();
        let x86_v4_capability_enter = x86_v4_capability.label().unwrap();
        x86_emit_frozen_compact_v4_entry(
            &mut x86_v4_capability,
            x86_v4_capability_try_v3,
            x86_v4_capability_preflight,
            x86_v4_capability_enter,
            FrozenCompactGuardMode::ActiveCapability,
        )
        .unwrap();
        for label in [
            x86_v4_capability_try_v3,
            x86_v4_capability_preflight,
            x86_v4_capability_enter,
        ] {
            x86_v4_capability.bind(label).unwrap();
            x86_v4_capability.instruction(&[0xc3]).unwrap();
        }
        let x86_v4_capability_instruction_count =
            x86_v4_capability.instruction_offsets.len();
        let x86_v4_capability = x86_v4_capability.finish().unwrap();
        let mut v4_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        v4_flag.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4.to_le_bytes());
        assert_eq!(occurrences(&x86_v4_auth, &v4_flag), 1);
        assert_eq!(occurrences(&x86_v4_capability, &v4_flag), 1);
        let mut v4_ready_seal = vec![0x49, 0xba];
        v4_ready_seal.extend_from_slice(&FROZEN_PREPARED_HEADER_V4_READY_SEAL.to_le_bytes());
        assert_eq!(occurrences(&x86_v4_auth, &v4_ready_seal), 1);
        assert_eq!(occurrences(&x86_v4_capability, &v4_ready_seal), 0);
        assert_eq!(
            occurrences(
                &x86_v4_auth,
                &[
                    0x41,
                    0x83,
                    0x7b,
                    u8::try_from(FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET).unwrap(),
                    0,
                ],
            ),
            1,
            "V4 must authenticate its zero row-shift discriminator"
        );
        assert_eq!(occurrences(&x86_v4_auth, &[0x44, 0x89, 0xc2]), 1);
        assert_eq!(occurrences(&x86_v4_auth, &[0x48, 0x0f, 0xaf, 0xc2]), 1);
        assert_eq!(
            occurrences(&x86_v4_auth, &[0x48, 0x3d, 0xff, 0x7f, 0x00, 0x00]),
            1,
            "V4 must prove the complete live-cell extent fits its token"
        );
        assert_eq!(
            occurrences(&x86_v4_capability, &[0x48, 0x3d, 0xff, 0x7f, 0x00, 0x00]),
            0,
            "the V4 capability guard must omit setup-proven live-cell geometry"
        );

        let mut x86_auth = X86Assembler::new();
        let x86_try_v2 = x86_auth.label().unwrap();
        let x86_preflight = x86_auth.label().unwrap();
        let x86_v3_enter = x86_auth.label().unwrap();
        x86_emit_frozen_compact_v3_entry(
            &mut x86_auth,
            x86_try_v2,
            x86_preflight,
            x86_v3_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [x86_try_v2, x86_preflight, x86_v3_enter] {
            x86_auth.bind(label).unwrap();
            x86_auth.instruction(&[0xc3]).unwrap();
        }
        let x86_auth = x86_auth.finish().unwrap();

        let mut x86_capability = X86Assembler::new();
        let x86_capability_try_v2 = x86_capability.label().unwrap();
        let x86_capability_preflight = x86_capability.label().unwrap();
        let x86_capability_enter = x86_capability.label().unwrap();
        x86_emit_frozen_compact_v3_entry(
            &mut x86_capability,
            x86_capability_try_v2,
            x86_capability_preflight,
            x86_capability_enter,
            FrozenCompactGuardMode::ActiveCapability,
        )
        .unwrap();
        for label in [
            x86_capability_try_v2,
            x86_capability_preflight,
            x86_capability_enter,
        ] {
            x86_capability.bind(label).unwrap();
            x86_capability.instruction(&[0xc3]).unwrap();
        }
        let x86_capability_instruction_count = x86_capability.instruction_offsets.len();
        let x86_capability = x86_capability.finish().unwrap();

        let canonical_descriptor_initial = [
            0x41,
            0x83,
            0x7b,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_INITIAL_STATE_OFFSET).unwrap(),
            0,
        ];
        let canonical_header_initial = [
            0x83,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FORWARD_INITIAL_ROW_OFFSET).unwrap(),
            0,
        ];
        for full_verifier in [&x86_auth, &x86_v4_auth] {
            assert_eq!(occurrences(full_verifier, &canonical_descriptor_initial), 1);
            assert_eq!(occurrences(full_verifier, &canonical_header_initial), 1);
        }
        for active_capability in [&x86_capability, &x86_v4_capability] {
            assert_eq!(
                occurrences(active_capability, &canonical_descriptor_initial),
                0,
                "active capability must rely on setup-authenticated canonical geometry"
            );
            assert_eq!(occurrences(active_capability, &canonical_header_initial), 0);
        }

        let mut v3_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        v3_flag.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &v3_flag), 1);
        assert_eq!(occurrences(&x86_capability, &v3_flag), 1);
        let mut v3_extent = vec![
            0x48,
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET).unwrap(),
        ];
        v3_extent.extend_from_slice(
            &u32::try_from(FROZEN_PREPARED_HEADER_V3_BYTES)
                .unwrap()
                .to_le_bytes(),
        );
        assert_eq!(occurrences(&x86_auth, &v3_extent), 1);
        assert_eq!(occurrences(&x86_capability, &v3_extent), 0);
        let mut active_seal = vec![0x49, 0xba];
        active_seal.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &active_seal), 1);
        assert_eq!(occurrences(&x86_capability, &active_seal), 1);
        let mut header_magic = vec![0x49, 0xba];
        header_magic.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_MAGIC.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &header_magic), 1);
        assert_eq!(occurrences(&x86_capability, &header_magic), 0);
        let mut header_abi = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_ABI_VERSION_OFFSET).unwrap(),
        ];
        header_abi.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_ABI_VERSION.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &header_abi), 1);
        assert_eq!(occurrences(&x86_capability, &header_abi), 0);
        let mut ready_seal = vec![0x49, 0xba];
        ready_seal.extend_from_slice(&FROZEN_PREPARED_HEADER_V3_READY_SEAL.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &ready_seal), 1);
        assert_eq!(occurrences(&x86_capability, &ready_seal), 0);
        let mut format_version = vec![
            0x41,
            0x81,
            0x7b,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
        ];
        format_version.extend_from_slice(&FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION.to_le_bytes());
        assert_eq!(occurrences(&x86_auth, &format_version), 1);
        assert_eq!(occurrences(&x86_capability, &format_version), 0);
        let cache_nonzero = [
            0x4d,
            0x8b,
            0x53,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_CACHE_IDENTITY_OFFSET).unwrap(),
            0x4d,
            0x85,
            0xd2,
        ];
        assert_eq!(occurrences(&x86_auth, &cache_nonzero), 1);
        assert_eq!(occurrences(&x86_capability, &cache_nonzero), 0);
        let tail_address = {
            let mut bytes = vec![0x4c, 0x8d, 0x9f];
            bytes.extend_from_slice(
                &i32::try_from(FROZEN_PREPARED_HEADER_V3_DYNAMIC_ROWS_OFFSET)
                    .unwrap()
                    .to_le_bytes(),
            );
            bytes
        };
        assert_eq!(occurrences(&x86_auth, &tail_address), 1);
        assert_eq!(occurrences(&x86_capability, &tail_address), 1);
        let retained_window = [
            0x4c, 0x8b, 0x54, 0x24, 0x28, 0x4c, 0x89, 0x54, 0x24, 0x40, 0x4c, 0x8b, 0x54,
            0x24, 0x30, 0x4c, 0x89, 0x54, 0x24, 0x48,
        ];
        assert_eq!(occurrences(&x86_auth, &retained_window), 1);
        assert_eq!(
            occurrences(&x86_capability, &retained_window),
            0,
            "production saves the exact public window once before format selection"
        );
        for identity_word in 0_usize..4 {
            let byte_offset = u8::try_from(identity_word * core::mem::size_of::<u64>()).unwrap();
            let linked_load = if byte_offset == 0 {
                vec![0x4c, 0x8b, 0x10]
            } else {
                vec![0x4c, 0x8b, 0x50, byte_offset]
            };
            assert_eq!(occurrences(&x86_auth, &linked_load), 1);
            assert_eq!(occurrences(&x86_capability, &linked_load), 1);
            let header_offset = u8::try_from(
                FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET + usize::from(byte_offset),
            )
            .unwrap();
            assert_eq!(
                occurrences(&x86_auth, &[0x4c, 0x3b, 0x57, header_offset]),
                1
            );
            assert_eq!(
                occurrences(
                    &x86_capability,
                    &[0x4c, 0x3b, 0x57, header_offset],
                ),
                1
            );
        }
        let x86_full_geometry = [0x3d, 0xff, 0x7f, 0x00, 0x00];
        assert_eq!(occurrences(&x86_auth, &x86_full_geometry), 1);
        assert_eq!(occurrences(&x86_capability, &x86_full_geometry), 0);
        let x86_rows_mirror = [
            0x4c,
            0x8b,
            0x57,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FORWARD_ROWS_ADDRESS_OFFSET).unwrap(),
            0x4d,
            0x3b,
            0x53,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_ROWS_ADDRESS_OFFSET).unwrap(),
        ];
        assert_eq!(occurrences(&x86_auth, &x86_rows_mirror), 1);
        assert_eq!(occurrences(&x86_capability, &x86_rows_mirror), 0);
        let x86_loop_normalization = [
            0x41,
            0x83,
            0x7b,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V3_LOOP_COUNT_OFFSET).unwrap(),
            0,
        ];
        assert_eq!(occurrences(&x86_auth, &x86_loop_normalization), 1);
        assert_eq!(
            occurrences(&x86_capability, &x86_loop_normalization),
            0,
            "the active seal covers setup-authenticated loop normalization"
        );
        assert_eq!(occurrences(&x86_v4_auth, &x86_loop_normalization), 1);
        assert_eq!(
            occurrences(&x86_v4_capability, &x86_loop_normalization),
            0,
            "the V4 active seal covers setup-authenticated loop normalization"
        );
        assert_eq!(
            x86_capability_instruction_count,
            22,
            "19 guard instructions plus three bound return sentinels"
        );
        assert_eq!(x86_v4_capability_instruction_count, 22);
        assert!(
            x86_capability.len().saturating_add(96) < x86_auth.len(),
            "the x86 capability guard must remove a material amount of per-call geometry work"
        );
        assert!(
            x86_v4_capability.len().saturating_add(96) < x86_v4_auth.len(),
            "the x86 V4 capability guard must remove a material amount of per-call geometry work"
        );

        let x86 = lower_x86_64_dynamic_rows_prepared(None, FeatureSet::EMPTY).unwrap();
        assert_eq!(
            occurrences(&x86.code, &[0x47, 0x0f, 0xb7, 0x14, 0x50]),
            47,
            "V14, V13, V8, paired V7/V6, paired V3/V4 first cells, and their scalar tails need scaled u16 loads"
        );
        assert_eq!(
            occurrences(&x86.code, &[0x4e, 0x8d, 0x04, 0x16]),
            58,
            "paired V8/V6 and both ordered V3/V10/V12 transitions need state-ordinal backedges"
        );
        assert_eq!(
            occurrences(&x86.code, &[0x49, 0x89, 0xf0]),
            34,
            "V14/V13, singleton, V8/V10/V12, V7/V4, and every V6/V3/V12 entry install row zero"
        );
        assert_eq!(
            occurrences(&x86.code, &[0x4e, 0x8d, 0x04, 0x46]),
            0,
            "V4 must not scale a published initial-row mirror"
        );
        assert_eq!(
            occurrences(&x86.code, &[0x4e, 0x8d, 0x44, 0x56, 0xfe]),
            10,
            "three V14 alphabets plus V13, singleton, paired V7, and mapped V4 need direct rows+token*2-2 backedges"
        );
        let mut v2_flag = vec![
            0x81,
            0x7f,
            u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
        ];
        v2_flag.extend_from_slice(&FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS.to_le_bytes());
        let compact_flag = |flag: u32| {
            let mut bytes = vec![
                0x81,
                0x7f,
                u8::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            ];
            bytes.extend_from_slice(&flag.to_le_bytes());
            bytes
        };
        let v5_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5);
        let v7_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V7);
        let v6_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V6);
        let v8_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8);
        let v9_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9);
        let v10_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10);
        let v11_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11);
        let v12_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12);
        let v13_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13);
        let v14_flag = compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14);
        let v5_selection = x86
            .code
            .windows(v5_flag.len())
            .position(|window| window == v5_flag.as_slice())
            .unwrap();
        let v7_selection = x86
            .code
            .windows(v7_flag.len())
            .position(|window| window == v7_flag.as_slice())
            .unwrap();
        let v6_selection = x86
            .code
            .windows(v6_flag.len())
            .position(|window| window == v6_flag.as_slice())
            .unwrap();
        let v14_selection = x86
            .code
            .windows(v14_flag.len())
            .position(|window| window == v14_flag.as_slice())
            .unwrap();
        let v13_selection = x86
            .code
            .windows(v13_flag.len())
            .position(|window| window == v13_flag.as_slice())
            .unwrap();
        assert_eq!(
            occurrences(&x86.code, &v11_flag),
            0,
            "the V13-dominated V11 capability must not occupy production entries"
        );
        let v10_selection = x86
            .code
            .windows(v10_flag.len())
            .position(|window| window == v10_flag.as_slice())
            .unwrap();
        let v12_selection = x86
            .code
            .windows(v12_flag.len())
            .position(|window| window == v12_flag.as_slice())
            .unwrap();
        assert_eq!(
            occurrences(&x86.code, &v9_flag),
            0,
            "the V10-dominated V9 capability must not occupy production entries"
        );
        let v8_selection = x86
            .code
            .windows(v8_flag.len())
            .position(|window| window == v8_flag.as_slice())
            .unwrap();
        let v4_selection = x86
            .code
            .windows(v4_flag.len())
            .position(|window| window == v4_flag.as_slice())
            .unwrap();
        let v3_selection = x86
            .code
            .windows(v3_flag.len())
            .position(|window| window == v3_flag.as_slice())
            .unwrap();
        let v2_selection = x86
            .code
            .windows(v2_flag.len())
            .position(|window| window == v2_flag.as_slice())
            .unwrap();
        assert!(
            v5_selection < v7_selection
                && v7_selection < v6_selection
                && v6_selection < v14_selection
                && v14_selection < v13_selection
                && v13_selection < v10_selection
                && v10_selection < v12_selection
                && v12_selection < v8_selection
                && v8_selection < v4_selection
                && v4_selection < v3_selection
                && v3_selection < v2_selection,
            "V5, V7, V6, V14, V13, V10, V12, V8, V4, V3, and V2 must retain priority order"
        );
        assert_eq!(
            occurrences(&x86.code[v5_selection..v2_selection], &x86_full_geometry),
            0,
            "production x86 compact entries must use active-capability guards"
        );
        let scanner_free_ceiling = [0x48, 0x3d, 0xff, 0x0f, 0x00, 0x00];
        assert_eq!(occurrences(&x86.code, &scanner_free_ceiling), 2);
        let first_ceiling = x86
            .code
            .windows(scanner_free_ceiling.len())
            .position(|window| window == scanner_free_ceiling)
            .unwrap();
        assert!(
            v3_selection < first_ceiling && first_ceiling < v2_selection,
            "x86 must select and authenticate the compact capability before the legacy scanner-free ceiling"
        );

        let mut arm_v4_auth = Aarch64Assembler::new();
        let arm_v4_try_v3 = arm_v4_auth.label().unwrap();
        let arm_v4_preflight = arm_v4_auth.label().unwrap();
        let arm_v4_enter = arm_v4_auth.label().unwrap();
        aarch64_emit_frozen_compact_v4_entry(
            &mut arm_v4_auth,
            arm_v4_try_v3,
            arm_v4_preflight,
            arm_v4_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [arm_v4_try_v3, arm_v4_preflight, arm_v4_enter] {
            arm_v4_auth.bind(label).unwrap();
            arm_v4_auth.instruction(0xd503_201f).unwrap();
        }
        let arm_v4_auth = arm_v4_auth.finish().unwrap();
        let arm_v4_auth_words = arm_v4_auth
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let mut arm_v4_capability = Aarch64Assembler::new();
        let arm_v4_capability_try_v3 = arm_v4_capability.label().unwrap();
        let arm_v4_capability_preflight = arm_v4_capability.label().unwrap();
        let arm_v4_capability_enter = arm_v4_capability.label().unwrap();
        aarch64_emit_frozen_compact_v4_entry(
            &mut arm_v4_capability,
            arm_v4_capability_try_v3,
            arm_v4_capability_preflight,
            arm_v4_capability_enter,
            FrozenCompactGuardMode::ActiveCapability,
        )
        .unwrap();
        for label in [
            arm_v4_capability_try_v3,
            arm_v4_capability_preflight,
            arm_v4_capability_enter,
        ] {
            arm_v4_capability.bind(label).unwrap();
            arm_v4_capability.instruction(0xd503_201f).unwrap();
        }
        let arm_v4_capability = arm_v4_capability.finish().unwrap();
        let arm_v4_capability_words = arm_v4_capability
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert!(arm_v4_auth_words.contains(
            &aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4).unwrap(),
                0,
            )
            .unwrap()
        ));
        assert!(arm_v4_auth_words.contains(
            &aarch64_load_w_imm(
                12,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_ROW_SHIFT_OFFSET).unwrap(),
            )
            .unwrap()
        ));
        assert!(arm_v4_auth_words.contains(&aarch64_mul_x(7, 10, 9).unwrap()));
        assert!(!arm_v4_auth_words.contains(&aarch64_mul_x(12, 6, 9).unwrap()));
        let mut arm_v4_ready = Aarch64Assembler::new();
        aarch64_load_u64_constant(&mut arm_v4_ready, 9, FROZEN_PREPARED_HEADER_V4_READY_SEAL)
            .unwrap();
        let arm_v4_ready = arm_v4_ready.finish().unwrap();
        assert_eq!(occurrences(&arm_v4_auth, &arm_v4_ready), 1);
        assert_eq!(occurrences(&arm_v4_capability, &arm_v4_ready), 0);

        let mut arm_auth = Aarch64Assembler::new();
        let arm_try_v2 = arm_auth.label().unwrap();
        let arm_preflight = arm_auth.label().unwrap();
        let arm_v3_enter = arm_auth.label().unwrap();
        aarch64_emit_frozen_compact_v3_entry(
            &mut arm_auth,
            arm_try_v2,
            arm_preflight,
            arm_v3_enter,
            FrozenCompactGuardMode::FullVerifier,
        )
        .unwrap();
        for label in [arm_try_v2, arm_preflight, arm_v3_enter] {
            arm_auth.bind(label).unwrap();
            arm_auth.instruction(0xd503_201f).unwrap();
        }
        let arm_auth = arm_auth.finish().unwrap();
        let arm_auth_words = arm_auth
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();

        let mut arm_capability = Aarch64Assembler::new();
        let arm_capability_try_v2 = arm_capability.label().unwrap();
        let arm_capability_preflight = arm_capability.label().unwrap();
        let arm_capability_enter = arm_capability.label().unwrap();
        aarch64_emit_frozen_compact_v3_entry(
            &mut arm_capability,
            arm_capability_try_v2,
            arm_capability_preflight,
            arm_capability_enter,
            FrozenCompactGuardMode::ActiveCapability,
        )
        .unwrap();
        for label in [
            arm_capability_try_v2,
            arm_capability_preflight,
            arm_capability_enter,
        ] {
            arm_capability.bind(label).unwrap();
            arm_capability.instruction(0xd503_201f).unwrap();
        }
        let arm_capability = arm_capability.finish().unwrap();
        let arm_capability_words = arm_capability
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();

        for (full_verifier, active_capability) in [
            (&arm_auth_words, &arm_capability_words),
            (&arm_v4_auth_words, &arm_v4_capability_words),
        ] {
            for (canonical_initial_load, register) in [
                (
                    aarch64_load_w_imm(
                        6,
                        13,
                        u16::try_from(FROZEN_DYNAMIC_ROWS_V3_INITIAL_STATE_OFFSET).unwrap(),
                    )
                    .unwrap(),
                    6_u32,
                ),
                (
                    aarch64_load_w_imm(
                        7,
                        0,
                        u16::try_from(FROZEN_PREPARED_HEADER_V1_FORWARD_INITIAL_ROW_OFFSET)
                            .unwrap(),
                    )
                    .unwrap(),
                    7_u32,
                ),
            ] {
                let load = full_verifier
                    .iter()
                    .position(|&word| word == canonical_initial_load)
                    .unwrap();
                let branch = *full_verifier.get(load + 1).unwrap();
                assert_eq!(
                    branch & 0xff00_001f,
                    0x3500_0000 | register,
                    "canonical compact root uses CBNZ"
                );
                assert!(!active_capability.contains(&canonical_initial_load));
            }
        }

        assert!(arm_auth_words.contains(
            &aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3).unwrap(),
                0,
            )
            .unwrap()
        ));
        assert!(arm_capability_words.contains(
            &aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3).unwrap(),
                0,
            )
            .unwrap()
        ));
        let arm_v3_extent = [
            aarch64_load_x_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_HEADER_BYTES_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V3_BYTES).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_x(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_v3_extent.len())
                .filter(|words| *words == arm_v3_extent)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_v3_extent.len())
                .filter(|words| *words == arm_v3_extent)
                .count(),
            0,
            "the active seal covers the immutable maximum physical envelope"
        );
        for identity_word in 0_usize..4 {
            let byte_offset = u16::try_from(identity_word * core::mem::size_of::<u64>()).unwrap();
            assert_eq!(
                arm_auth_words
                    .iter()
                    .filter(|&&word| {
                        word == aarch64_load_x_imm(8, 6, byte_offset).unwrap()
                    })
                    .count(),
                1
            );
            assert_eq!(
                arm_capability_words
                    .iter()
                    .filter(|&&word| {
                        word == aarch64_load_x_imm(8, 6, byte_offset).unwrap()
                    })
                    .count(),
                1
            );
            let header_offset = u16::try_from(
                FROZEN_PREPARED_HEADER_V1_ARTIFACT_IDENTITY_OFFSET + usize::from(byte_offset),
            )
            .unwrap();
            assert_eq!(
                arm_auth_words
                    .iter()
                    .filter(|&&word| {
                        word == aarch64_load_x_imm(9, 0, header_offset).unwrap()
                    })
                    .count(),
                1
            );
            assert_eq!(
                arm_capability_words
                    .iter()
                    .filter(|&&word| {
                        word == aarch64_load_x_imm(9, 0, header_offset).unwrap()
                    })
                    .count(),
                1
            );
        }
        let mut arm_active = Aarch64Assembler::new();
        aarch64_load_u64_constant(&mut arm_active, 9, FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL)
            .unwrap();
        let arm_active = arm_active.finish().unwrap();
        assert_eq!(occurrences(&arm_auth, &arm_active), 1);
        assert_eq!(occurrences(&arm_capability, &arm_active), 1);
        let mut arm_magic = Aarch64Assembler::new();
        aarch64_load_u64_constant(&mut arm_magic, 9, FROZEN_PREPARED_HEADER_V1_MAGIC)
            .unwrap();
        let arm_magic = arm_magic.finish().unwrap();
        assert_eq!(occurrences(&arm_auth, &arm_magic), 1);
        assert_eq!(occurrences(&arm_capability, &arm_magic), 0);
        let arm_abi = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_ABI_VERSION_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_ABI_VERSION).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_abi.len())
                .filter(|words| *words == arm_abi)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_abi.len())
                .filter(|words| *words == arm_abi)
                .count(),
            0
        );
        let mut arm_ready = Aarch64Assembler::new();
        aarch64_load_u64_constant(&mut arm_ready, 9, FROZEN_PREPARED_HEADER_V3_READY_SEAL)
            .unwrap();
        let arm_ready = arm_ready.finish().unwrap();
        assert_eq!(occurrences(&arm_auth, &arm_ready), 1);
        assert_eq!(occurrences(&arm_capability, &arm_ready), 0);
        let arm_format = [
            aarch64_load_w_imm(
                8,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_format.len())
                .filter(|words| *words == arm_format)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_format.len())
                .filter(|words| *words == arm_format)
                .count(),
            0
        );
        let arm_cache_nonzero = [
            aarch64_load_x_imm(
                8,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_CACHE_IDENTITY_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_cmp_x_imm(8, 0).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_cache_nonzero.len())
                .filter(|words| *words == arm_cache_nonzero)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_cache_nonzero.len())
                .filter(|words| *words == arm_cache_nonzero)
                .count(),
            0
        );
        let arm_tail_address = aarch64_add_x_imm(
            13,
            0,
            u16::try_from(FROZEN_PREPARED_HEADER_V3_DYNAMIC_ROWS_OFFSET).unwrap(),
        )
        .unwrap();
        assert_eq!(
            arm_auth_words
                .iter()
                .filter(|&&word| word == arm_tail_address)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .iter()
                .filter(|&&word| word == arm_tail_address)
                .count(),
            1
        );
        let arm_retained_window = [
            aarch64_load_x_imm(8, 31, 24).unwrap(),
            aarch64_store_x(8, 31, 48).unwrap(),
            aarch64_load_x_imm(8, 31, 32).unwrap(),
            aarch64_store_x(8, 31, 56).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_retained_window.len())
                .filter(|words| *words == arm_retained_window)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_retained_window.len())
                .filter(|words| *words == arm_retained_window)
                .count(),
            0,
            "production saves the exact public window once before format selection"
        );
        let arm_full_geometry = aarch64_load_w_imm(
            10,
            13,
            u16::try_from(FROZEN_DYNAMIC_ROWS_V3_STATE_COUNT_OFFSET).unwrap(),
        )
        .unwrap();
        assert_eq!(
            arm_auth_words
                .iter()
                .filter(|&&word| word == arm_full_geometry)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .iter()
                .filter(|&&word| word == arm_full_geometry)
                .count(),
            0
        );
        assert_eq!(
            arm_v4_auth_words
                .iter()
                .filter(|&&word| word == arm_full_geometry)
                .count(),
            1
        );
        assert_eq!(
            arm_v4_capability_words
                .iter()
                .filter(|&&word| word == arm_full_geometry)
                .count(),
            0
        );
        let arm_rows_mirror = [
            aarch64_load_x_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FORWARD_ROWS_ADDRESS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_load_x_imm(
                9,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V3_ROWS_ADDRESS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_cmp_x(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_auth_words
                .windows(arm_rows_mirror.len())
                .filter(|words| *words == arm_rows_mirror)
                .count(),
            1
        );
        assert_eq!(
            arm_capability_words
                .windows(arm_rows_mirror.len())
                .filter(|words| *words == arm_rows_mirror)
                .count(),
            0
        );
        assert_eq!(
            arm_v4_auth_words
                .windows(arm_rows_mirror.len())
                .filter(|words| *words == arm_rows_mirror)
                .count(),
            1
        );
        assert_eq!(
            arm_v4_capability_words
                .windows(arm_rows_mirror.len())
                .filter(|words| *words == arm_rows_mirror)
                .count(),
            0
        );
        let arm_loop_normalization = aarch64_load_w_imm(
            7,
            13,
            u16::try_from(FROZEN_DYNAMIC_ROWS_V3_LOOP_COUNT_OFFSET).unwrap(),
        )
        .unwrap();
        assert_eq!(
            arm_capability_words
                .iter()
                .filter(|&&word| word == arm_loop_normalization)
                .count(),
            0,
            "the active seal covers setup-authenticated loop normalization"
        );
        assert_eq!(
            arm_v4_auth_words
                .iter()
                .filter(|&&word| word == arm_loop_normalization)
                .count(),
            1
        );
        assert_eq!(
            arm_v4_capability_words
                .iter()
                .filter(|&&word| word == arm_loop_normalization)
                .count(),
            0,
            "the V4 active seal covers setup-authenticated loop normalization"
        );
        assert_eq!(
            arm_capability_words.len(),
            32,
            "29 guard instructions plus three bound NOP sentinels"
        );
        assert_eq!(arm_v4_capability_words.len(), 32);
        assert!(
            arm_capability.len().saturating_add(96) < arm_auth.len(),
            "the AArch64 capability guard must remove a material amount of per-call geometry work"
        );
        assert!(
            arm_v4_capability.len().saturating_add(96) < arm_v4_auth.len(),
            "the AArch64 V4 capability guard must remove a material amount of per-call geometry work"
        );

        let arm = lower_aarch64_dynamic_rows_prepared(None).unwrap();
        let arm_words = arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_load_h_uxtw(8, 11, 6).unwrap())
                .count(),
            15,
            "paired V6/V7, V8, the first V3 cell for every shift, and the shared V3 scalar tail"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_load_h_uxtw(8, 11, 10).unwrap())
                .count(),
            11,
            "the second unrolled V3 cell for every shift plus paired V4/V8 use their independently loaded columns"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_load_h_uxtw(8, 11, 8).unwrap())
                .count(),
            16,
            "V14/V13/V7 plus paired V4 first cell and its scalar tail"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_add_x_uxtw(11, 15, 8, 1).unwrap())
                .count(),
            10,
            "three V14 alphabets plus V13, singleton, paired V7, and mapped V4 need biased-base cell-offset backedges"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_add_x_uxtw(11, 15, 11, 1).unwrap())
                .count(),
            0,
            "V4 must not rebuild a noncanonical initial-row mirror"
        );
        for shift in 1_u8..=9 {
            assert_eq!(
                arm_words
                    .iter()
                    .filter(|&&word| word == aarch64_add_x_lsl(11, 15, 6, shift).unwrap())
                    .count(),
                match shift {
                    1..=7 => 4,
                    8 => 6,
                    9 => 4,
                    _ => unreachable!(),
                },
                "shift={shift} accounts exactly for both ordered V3/V10/V12 transitions and unchanged direct formats"
            );
        }
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_add_x_lsl(11, 15, 6, 0).unwrap())
                .count(),
            2,
            "V12 P=1 needs one unshifted update per ordered transition"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_mov_x(11, 15).unwrap())
                .count(),
            26,
            "V14/V13, singleton, V8/V10/V12, V7/V4, shared V6, and every V3/V12 entry install row zero"
        );
        assert!(arm_words.contains(
            &aarch64_add_x_imm(
                14,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_CLASS_MAP_OFFSET).unwrap(),
            )
            .unwrap()
        ));
        let arm_v3_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_capability_words
                .windows(arm_v3_flag.len())
                .filter(|words| *words == arm_v3_flag)
                .count(),
            1,
            "the AArch64 capability guard must select only the exact V3 flag"
        );
        let arm_v4_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        assert_eq!(
            arm_v4_capability_words
                .windows(arm_v4_flag.len())
                .filter(|words| *words == arm_v4_flag)
                .count(),
            1,
            "the AArch64 capability guard must select only the exact V4 flag"
        );
        let arm_compact_flag = |flag: u32| {
            [
                aarch64_load_w_imm(
                    8,
                    0,
                    u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
                )
                .unwrap(),
                aarch64_movz_x(9, u16::try_from(flag).unwrap(), 0).unwrap(),
                aarch64_cmp_w(8, 9).unwrap(),
            ]
        };
        let arm_v5_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5);
        let arm_v7_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V7);
        let arm_v6_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V6);
        let arm_v10_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10);
        let arm_v11_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11);
        let arm_v12_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12);
        let arm_v13_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13);
        let arm_v14_flag = arm_compact_flag(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14);
        let arm_v8_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        let arm_v9_flag = [
            aarch64_load_w_imm(
                8,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                9,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(8, 9).unwrap(),
        ];
        let arm_v2_flag = [
            aarch64_load_w_imm(
                9,
                0,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAGS_OFFSET).unwrap(),
            )
            .unwrap(),
            aarch64_movz_x(
                8,
                u16::try_from(FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS).unwrap(),
                0,
            )
            .unwrap(),
            aarch64_cmp_w(9, 8).unwrap(),
        ];
        let arm_v5_selection = arm_words
            .windows(arm_v5_flag.len())
            .position(|words| words == arm_v5_flag)
            .unwrap();
        let arm_v7_selection = arm_words
            .windows(arm_v7_flag.len())
            .position(|words| words == arm_v7_flag)
            .unwrap();
        let arm_v6_selection = arm_words
            .windows(arm_v6_flag.len())
            .position(|words| words == arm_v6_flag)
            .unwrap();
        let arm_v14_selection = arm_words
            .windows(arm_v14_flag.len())
            .position(|words| words == arm_v14_flag)
            .unwrap();
        let arm_v13_selection = arm_words
            .windows(arm_v13_flag.len())
            .position(|words| words == arm_v13_flag)
            .unwrap();
        assert_eq!(
            arm_words
                .windows(arm_v11_flag.len())
                .filter(|words| *words == arm_v11_flag)
                .count(),
            0,
            "the V13-dominated V11 capability must not occupy production entries"
        );
        let arm_v10_selection = arm_words
            .windows(arm_v10_flag.len())
            .position(|words| words == arm_v10_flag)
            .unwrap();
        let arm_v12_selection = arm_words
            .windows(arm_v12_flag.len())
            .position(|words| words == arm_v12_flag)
            .unwrap();
        assert_eq!(
            arm_words
                .windows(arm_v9_flag.len())
                .filter(|words| *words == arm_v9_flag)
                .count(),
            0,
            "the V10-dominated V9 capability must not occupy production entries"
        );
        let arm_v8_selection = arm_words
            .windows(arm_v8_flag.len())
            .position(|words| words == arm_v8_flag)
            .unwrap();
        let arm_v4_selection = arm_words
            .windows(arm_v4_flag.len())
            .position(|words| words == arm_v4_flag)
            .unwrap();
        let arm_v3_selection = arm_words
            .windows(arm_v3_flag.len())
            .position(|words| words == arm_v3_flag)
            .unwrap();
        let arm_v2_selection = arm_words
            .windows(arm_v2_flag.len())
            .position(|words| words == arm_v2_flag)
            .unwrap();
        assert!(
            arm_v5_selection < arm_v7_selection
                && arm_v7_selection < arm_v6_selection
                && arm_v6_selection < arm_v14_selection
                && arm_v14_selection < arm_v13_selection
                && arm_v13_selection < arm_v10_selection
                && arm_v10_selection < arm_v12_selection
                && arm_v12_selection < arm_v8_selection
                && arm_v8_selection < arm_v4_selection
                && arm_v4_selection < arm_v3_selection
                && arm_v3_selection < arm_v2_selection
        );
        assert_eq!(
            arm_words[arm_v5_selection..arm_v2_selection]
                .iter()
                .filter(|&&word| word == arm_full_geometry)
                .count(),
            0,
            "production AArch64 compact entries must use active-capability guards"
        );
        let arm_scanner_free_ceiling = aarch64_cmp_x_imm(
            8,
            u16::try_from(FROZEN_SCANNER_FREE_DYNAMIC_ROWS_MAX_INPUT_BYTES).unwrap(),
        )
        .unwrap();
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == arm_scanner_free_ceiling)
                .count(),
            2
        );
        let arm_first_ceiling = arm_words
            .iter()
            .position(|&word| word == arm_scanner_free_ceiling)
            .unwrap();
        assert!(
            arm_v3_selection < arm_first_ceiling && arm_first_ceiling < arm_v2_selection,
            "AArch64 must select and authenticate the compact capability before the legacy scanner-free ceiling"
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one cross-ISA audit covers both specialized compact capability shapes"
    )]
    fn frozen_compact_specialized_entry_checks_are_full_verifier_only_cross_isa() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        fn x86_entry(
            format: FrozenCompactNativeFormat,
            guard_mode: FrozenCompactGuardMode,
        ) -> (Vec<u8>, usize) {
            let mut assembler = X86Assembler::new();
            let try_older = assembler.label().unwrap();
            let call_preflight = assembler.label().unwrap();
            let compact_enter = assembler.label().unwrap();
            x86_emit_frozen_compact_entry(
                &mut assembler,
                format,
                try_older,
                call_preflight,
                compact_enter,
                guard_mode,
            )
            .unwrap();
            for label in [try_older, call_preflight, compact_enter] {
                assembler.bind(label).unwrap();
                assembler.instruction(&[0xc3]).unwrap();
            }
            let instruction_count = assembler.instruction_offsets.len();
            (assembler.finish().unwrap(), instruction_count)
        }

        fn arm_entry(
            format: FrozenCompactNativeFormat,
            guard_mode: FrozenCompactGuardMode,
        ) -> Vec<u8> {
            let mut assembler = Aarch64Assembler::new();
            let try_older = assembler.label().unwrap();
            let call_preflight = assembler.label().unwrap();
            let compact_enter = assembler.label().unwrap();
            aarch64_emit_frozen_compact_entry(
                &mut assembler,
                format,
                try_older,
                call_preflight,
                compact_enter,
                guard_mode,
            )
            .unwrap();
            for label in [try_older, call_preflight, compact_enter] {
                assembler.bind(label).unwrap();
                assembler.instruction(0xd503_201f).unwrap();
            }
            assembler.finish().unwrap()
        }

        let (x86_v5_full, _) = x86_entry(
            FrozenCompactNativeFormat::UnaryExistsV5,
            FrozenCompactGuardMode::FullVerifier,
        );
        let (x86_v5_active, x86_v5_active_instruction_count) = x86_entry(
            FrozenCompactNativeFormat::UnaryExistsV5,
            FrozenCompactGuardMode::ActiveCapability,
        );
        let x86_v5_step = [
            0x45,
            0x8b,
            0x53,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET).unwrap(),
        ];
        let x86_v5_complement = [
            0x41,
            0x33,
            0x43,
            u8::try_from(FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_COMPLEMENT_OFFSET).unwrap(),
        ];
        assert_eq!(occurrences(&x86_v5_full, &x86_v5_step), 2);
        assert_eq!(
            occurrences(&x86_v5_active, &x86_v5_step),
            1,
            "V5 retains only the value consumed by its body"
        );
        assert_eq!(occurrences(&x86_v5_full, &x86_v5_complement), 1);
        assert_eq!(occurrences(&x86_v5_active, &x86_v5_complement), 0);
        assert_eq!(x86_v5_active_instruction_count, 23);

        let arm_v5_full = arm_entry(
            FrozenCompactNativeFormat::UnaryExistsV5,
            FrozenCompactGuardMode::FullVerifier,
        );
        let arm_v5_active = arm_entry(
            FrozenCompactNativeFormat::UnaryExistsV5,
            FrozenCompactGuardMode::ActiveCapability,
        );
        let arm_v5_full_words = arm_v5_full
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_v5_active_words = arm_v5_active
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let arm_v5_step = aarch64_load_w_imm(
            7,
            13,
            u16::try_from(FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_OFFSET).unwrap(),
        )
        .unwrap();
        let arm_v5_complement = aarch64_load_w_imm(
            8,
            13,
            u16::try_from(FROZEN_DYNAMIC_ROWS_V5_FIRST_ACCEPT_STEP_COMPLEMENT_OFFSET).unwrap(),
        )
        .unwrap();
        assert_eq!(
            arm_v5_full_words
                .iter()
                .filter(|&&word| word == arm_v5_step)
                .count(),
            2
        );
        assert_eq!(
            arm_v5_active_words
                .iter()
                .filter(|&&word| word == arm_v5_step)
                .count(),
            1,
            "V5 retains only the value consumed by its body"
        );
        assert_eq!(
            arm_v5_full_words
                .iter()
                .filter(|&&word| word == arm_v5_complement)
                .count(),
            1
        );
        assert_eq!(
            arm_v5_active_words
                .iter()
                .filter(|&&word| word == arm_v5_complement)
                .count(),
            0
        );
        assert_eq!(arm_v5_active_words.len(), 33);

        for format in [
            FrozenCompactNativeFormat::StateOrdinalV6,
            FrozenCompactNativeFormat::CellOffsetV7,
        ] {
            let (x86_full, _) =
                x86_entry(format, FrozenCompactGuardMode::FullVerifier);
            let (x86_active, x86_active_instruction_count) =
                x86_entry(format, FrozenCompactGuardMode::ActiveCapability);
            let x86_plan_count = [
                0x41,
                0x83,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V6_LOOP_PLAN_COUNT_OFFSET).unwrap(),
                1,
            ];
            let x86_plan_address = [
                0x49,
                0x83,
                0x7b,
                u8::try_from(FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_ADDRESS_OFFSET).unwrap(),
                0,
            ];
            assert_eq!(occurrences(&x86_full, &x86_plan_count), 1, "{format:?}");
            assert_eq!(occurrences(&x86_active, &x86_plan_count), 0, "{format:?}");
            assert_eq!(occurrences(&x86_full, &x86_plan_address), 1, "{format:?}");
            assert_eq!(occurrences(&x86_active, &x86_plan_address), 0, "{format:?}");
            assert_eq!(x86_active_instruction_count, 22, "{format:?}");

            let arm_full = arm_entry(format, FrozenCompactGuardMode::FullVerifier);
            let arm_active = arm_entry(format, FrozenCompactGuardMode::ActiveCapability);
            let arm_full_words = arm_full
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            let arm_active_words = arm_active
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            let arm_plan_count = aarch64_load_w_imm(
                7,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V6_LOOP_PLAN_COUNT_OFFSET).unwrap(),
            )
            .unwrap();
            let arm_plan_address = aarch64_load_x_imm(
                8,
                13,
                u16::try_from(FROZEN_DYNAMIC_ROWS_V6_LOOP_INDEX_ADDRESS_OFFSET).unwrap(),
            )
            .unwrap();
            assert_eq!(
                arm_full_words
                    .iter()
                    .filter(|&&word| word == arm_plan_count)
                    .count(),
                1,
                "{format:?}"
            );
            assert_eq!(
                arm_active_words
                    .iter()
                    .filter(|&&word| word == arm_plan_count)
                    .count(),
                0,
                "{format:?}"
            );
            assert_eq!(
                arm_full_words
                    .iter()
                    .filter(|&&word| word == arm_plan_address)
                    .count(),
                1,
                "{format:?}"
            );
            assert_eq!(
                arm_active_words
                    .iter()
                    .filter(|&&word| word == arm_plan_address)
                    .count(),
                0,
                "{format:?}"
            );
            assert_eq!(arm_active_words.len(), 32, "{format:?}");
        }
    }

    #[test]
    fn frozen_compact_loop_v6_v7_lowering_and_symbols_are_cross_target_exact() {
        fn occurrences(code: &[u8], needle: &[u8]) -> usize {
            code.windows(needle.len())
                .filter(|window| *window == needle)
                .count()
        }

        let x86 = lower_x86_64_dynamic_rows_prepared(None, FeatureSet::EMPTY).unwrap();
        assert_eq!(
            x86.relocations
                .iter()
                .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL)
                .count(),
            2,
            "V7 and V6 each own one helper callsite"
        );
        let mut v7_threshold = vec![0x49, 0x81, 0xfa];
        v7_threshold.extend_from_slice(
            &u32::try_from(FROZEN_COMPACT_LOOP_SCAN_MIN_BYTES)
                .unwrap()
                .to_le_bytes(),
        );
        let mut v6_threshold = vec![0x49, 0x81, 0xf8];
        v6_threshold.extend_from_slice(
            &u32::try_from(FROZEN_COMPACT_LOOP_SCAN_MIN_BYTES)
                .unwrap()
                .to_le_bytes(),
        );
        assert_eq!(occurrences(&x86.code, &v7_threshold), 1);
        assert_eq!(occurrences(&x86.code, &v6_threshold), 1);
        let x86_loop_calls = x86
            .relocations
            .iter()
            .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL)
            .collect::<Vec<_>>();
        for (relocation, remaining_move) in x86_loop_calls
            .iter()
            .zip([[0x4c, 0x89, 0xd2], [0x4c, 0x89, 0xc2]])
        {
            let displacement = usize::try_from(relocation.offset).unwrap();
            let abi_start = displacement.checked_sub(8).unwrap();
            let mut expected = vec![0x48, 0x8d, 0x3c, 0x17];
            expected.extend_from_slice(&remaining_move);
            expected.push(0xe8);
            assert_eq!(
                &x86.code[abi_start..displacement],
                expected.as_slice(),
                "the trusted V2 call must pass source/scanner/length without reloading the prepared handle"
            );
        }
        for word in 0_usize..4 {
            let offset = FROZEN_COMPACT_LOOP_PLAN_V1_MEMBERS_OFFSET
                + word * core::mem::size_of::<u64>();
            assert_eq!(
                occurrences(
                    &x86.code,
                    &[0x48, 0x83, 0x78, u8::try_from(offset).unwrap(), 0xff],
                ),
                2,
                "both formats must derive all-byte completion from every bitmap word"
            );
        }

        let arm = lower_aarch64_dynamic_rows_prepared(None).unwrap();
        assert_eq!(
            arm.relocations
                .iter()
                .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL)
                .count(),
            2,
            "V7 and V6 each own one AArch64 helper callsite"
        );
        let arm_words = arm
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| {
                    word
                        == aarch64_cmp_x_imm(
                            12,
                            u16::try_from(FROZEN_COMPACT_LOOP_SCAN_MIN_BYTES).unwrap(),
                        )
                        .unwrap()
                })
                .count(),
            1,
            "V7 retains its remaining-length scratch in X12"
        );
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| {
                    word
                        == aarch64_cmp_x_imm(
                            7,
                            u16::try_from(FROZEN_COMPACT_LOOP_SCAN_MIN_BYTES).unwrap(),
                        )
                        .unwrap()
                })
                .count(),
            1,
            "V6 keeps its invariant stride in X12 and uses X7 for remaining length"
        );
        assert!(arm_words.contains(&aarch64_madd_x(11, 6, 12, 15).unwrap()));
        assert!(!arm_words.contains(&aarch64_lslv_x(10, 6, 12).unwrap()));
        assert_eq!(
            arm_words
                .iter()
                .filter(|&&word| word == aarch64_load_byte_reg(8, 10, 6).unwrap())
                .count(),
            2,
            "both compact formats use an O(1) immutable byte index"
        );
        let arm_loop_calls = arm
            .relocations
            .iter()
            .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL)
            .collect::<Vec<_>>();
        let arm_source = aarch64_add_x_reg(0, 0, 2).unwrap().to_le_bytes();
        let arm_v7_length = aarch64_mov_x(2, 12).unwrap().to_le_bytes();
        let arm_v6_length = aarch64_mov_x(2, 7).unwrap().to_le_bytes();
        let mut v7_lengths = 0_usize;
        let mut v6_lengths = 0_usize;
        for relocation in arm_loop_calls {
            let branch = usize::try_from(relocation.offset).unwrap();
            assert_eq!(&arm.code[branch - 8..branch - 4], &arm_source);
            let length = &arm.code[branch - 4..branch];
            if length == arm_v7_length {
                v7_lengths += 1;
            } else if length == arm_v6_length {
                v6_lengths += 1;
            } else {
                panic!("trusted loop call uses an unexpected length register");
            }
        }
        assert_eq!((v7_lengths, v6_lengths), (1, 1));
        assert_eq!(
            DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL_NAME,
            "fre_aot_regex_runtime_scan_frozen_loop_v2"
        );

        let avx2 = FeatureSet::of(CpuFeature::X86Sse2).with(CpuFeature::X86Avx2);
        let sve2 = FeatureSet::of(CpuFeature::Aarch64Asimd)
            .with(CpuFeature::Aarch64Sve)
            .with(CpuFeature::Aarch64Sve2);
        let targets = [
            Target::x86_64_linux().with_features(avx2).unwrap(),
            Target::x86_64_macos().with_features(avx2).unwrap(),
            Target::aarch64_linux().with_features(sve2).unwrap(),
            Target::aarch64_macos()
                .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                .unwrap(),
        ];
        for target in targets {
            let compiled = compile_with_k0_but_without_slow(
                CompileRequest::new(r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)", target)
                    .mode(CompileMode::Optimizing)
                    .output(OutputContract::SelectedEnd)
                    .limits(CompileLimitsV1 {
                        determinize: DeterminizeLimits {
                            max_states: 0,
                            ..DeterminizeLimits::default()
                        },
                        ..CompileLimitsV1::default()
                    }),
            );
            assert_eq!(compiled.program().engine_kind(), EngineKind::OrderedNfa);
            assert!(compiled.program().native_dynamic_rows_view().is_some());
            let module = lower_without_materialized_k0(compiled.program(), target);
            assert_eq!(
                module.required_prepared_dynamic_rows_loop_scan_runtime_symbol(),
                Some(DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL_NAME),
                "{target:?}"
            );
            assert_eq!(
                module
                    .relocations()
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL
                    })
                    .count(),
                2,
                "{target:?}"
            );
            let object = emit_object(
                &module,
                ObjectFormat::for_target(target),
                usize::MAX,
            )
            .unwrap_or_else(|error| panic!("emit compact loop for {target:?}: {error}"));
            assert!(!object.is_empty(), "{target:?}");
        }

        // Keep the no-host AVX-512 selection compiled and relocation-audited;
        // arbitrary-set loop scanning safely uses the runtime's AVX2 leaf on
        // current AVX-512 hosts until a profitable dedicated leaf exists.
        let avx512 = FeatureSet::of(CpuFeature::X86Sse2)
            .with(CpuFeature::X86Avx2)
            .with(CpuFeature::X86Avx512F)
            .with(CpuFeature::X86Avx512Bw)
            .with(CpuFeature::X86Avx512Vl);
        assert!(lower_x86_64_dynamic_rows_prepared(None, avx512).is_ok());
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the exhaustive semantic proof and both compact ISA encodings form one decoder audit"
    )]
    fn frozen_compact_v3_dead_token_decoders_are_exact_cross_isa() {
        type DecodedCell = (bool, Option<u32>);

        fn former_x86_decode(cell: u16) -> DecodedCell {
            let token = u32::from(cell & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK);
            let zero_based = token.wrapping_sub(1);
            (
                cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0,
                (zero_based
                    <= u32::from(DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK - 1))
                .then_some(zero_based),
            )
        }

        fn former_aarch64_decode(cell: u16) -> DecodedCell {
            let token = u32::from(cell & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK);
            let zero_based = token.wrapping_sub(1);
            (
                cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0,
                ((zero_based >> 15) == 0).then_some(zero_based),
            )
        }

        fn zero_test_decode(cell: u16) -> DecodedCell {
            let token = cell & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
            (
                cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0,
                token.checked_sub(1).map(u32::from),
            )
        }

        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        enum ExistsDecode {
            Match,
            Dead,
            Token(u16),
        }

        fn exists_sign_zero_decode(cell: u16) -> ExistsDecode {
            if i16::from_ne_bytes(cell.to_ne_bytes()).is_negative() {
                ExistsDecode::Match
            } else {
                cell.checked_sub(1)
                    .map_or(ExistsDecode::Dead, ExistsDecode::Token)
            }
        }

        fn x86_conditional_branch_len(
            code: &[u8],
            offset: usize,
            short_opcode: u8,
            near_opcode: u8,
        ) -> Option<usize> {
            match code.get(offset..) {
                Some([opcode, _, ..]) if *opcode == short_opcode => Some(2),
                Some([0x0f, opcode, _, _, _, _, ..]) if *opcode == near_opcode => Some(6),
                _ => None,
            }
        }

        fn assert_x86_decode_shape(
            code: &[u8],
            output: OutputContract,
            compact_possible: bool,
            context: &str,
        ) {
            const TOKEN_MASK: [u8; 7] = [0x41, 0x81, 0xe2, 0xff, 0x7f, 0x00, 0x00];
            const EXISTS_TOKEN_TEST: [u8; 4] = [0x66, 0x45, 0x85, 0xd2];
            const DECREMENT: [u8; 3] = [0x41, 0xff, 0xca];
            const V4_BACKEDGE: [u8; 5] = [0x4e, 0x8d, 0x44, 0x56, 0xfe];
            const FORMER_MAX_COMPARE: [u8; 7] =
                [0x41, 0x81, 0xfa, 0xfe, 0x7f, 0x00, 0x00];
            const V1_TOKEN_MASK: [u8; 7] =
                [0x41, 0x81, 0xe2, 0xff, 0xff, 0xff, 0x1f];
            const V1_TEST: [u8; 3] = [0x45, 0x85, 0xd2];
            const V1_SET_ROW: [u8; 6] = [0x45, 0x89, 0xd0, 0x41, 0xff, 0xc8];
            const V1_SET_POINTER_ROW: [u8; 5] = [0x4e, 0x8d, 0x44, 0x96, 0xfc];

            let (v3_decoders, v4_decoders) = if output == OutputContract::Exists {
                let mut v3 = 0_usize;
                let mut v4 = 0_usize;
                for (offset, window) in code.windows(EXISTS_TOKEN_TEST.len()).enumerate() {
                    if window != EXISTS_TOKEN_TEST {
                        continue;
                    }
                    let sign_branch = offset + EXISTS_TOKEN_TEST.len();
                    let Some(sign_bytes) =
                        x86_conditional_branch_len(code, sign_branch, 0x78, 0x88)
                    else {
                        continue;
                    };
                    let zero_branch = sign_branch + sign_bytes;
                    let Some(zero_bytes) =
                        x86_conditional_branch_len(code, zero_branch, 0x74, 0x84)
                    else {
                        continue;
                    };
                    let after_zero = zero_branch + zero_bytes;
                    if code[after_zero..].starts_with(&DECREMENT) {
                        v3 += 1;
                    } else if code[after_zero..].starts_with(&V4_BACKEDGE) {
                        v4 += 1;
                    }
                }
                assert_eq!(
                    code.windows(TOKEN_MASK.len())
                        .filter(|window| *window == TOKEN_MASK)
                        .count(),
                    0,
                    "{context}: Exists compact loops must not mask non-accepting tokens"
                );
                (v3, v4)
            } else {
                let mut v3 = 0_usize;
                let mut v4 = 0_usize;
                for (offset, window) in code.windows(TOKEN_MASK.len()).enumerate() {
                    if window != TOKEN_MASK {
                        continue;
                    }
                    let after_mask = offset + TOKEN_MASK.len();
                    if let Some(zero_bytes) =
                        x86_conditional_branch_len(code, after_mask, 0x74, 0x84)
                    {
                        if code[after_mask + zero_bytes..].starts_with(&DECREMENT) {
                            v3 += 1;
                        }
                        continue;
                    }
                    if !code[after_mask..].starts_with(&[0x45, 0x85, 0xd2]) {
                        continue;
                    }
                    let zero_branch = after_mask + 3;
                    let Some(zero_bytes) =
                        x86_conditional_branch_len(code, zero_branch, 0x74, 0x84)
                    else {
                        continue;
                    };
                    if code[zero_branch + zero_bytes..].starts_with(&V4_BACKEDGE) {
                        v4 += 1;
                    }
                }
                (v3, v4)
            };
            let expected_v3_decoders = if compact_possible { 19 } else { 0 };
            let expected_v4_decoders = if compact_possible { 2 } else { 0 };
            assert_eq!(
                v3_decoders, expected_v3_decoders,
                "{context}: exact reachable V6/V8 and V3 decoder count"
            );
            assert_eq!(
                v4_decoders, expected_v4_decoders,
                "{context}: exact reachable V7/V4 decoder count"
            );
            assert_eq!(
                v3_decoders + v4_decoders,
                expected_v3_decoders + expected_v4_decoders,
                "{context}: only reachable immutable compact rows retain decoders"
            );
            assert_eq!(
                code.windows(FORMER_MAX_COMPARE.len())
                    .filter(|window| *window == FORMER_MAX_COMPARE)
                    .count(),
                0,
                "{context}: V3 must not retain the authenticated-range comparison"
            );

            let v1_prefix_bytes = V1_TOKEN_MASK.len() + V1_TEST.len();
            let v1_decoders = code
                .windows(v1_prefix_bytes)
                .enumerate()
                .filter(|(_, window)| {
                    window.starts_with(&V1_TOKEN_MASK)
                        && window[V1_TOKEN_MASK.len()..].starts_with(&V1_TEST)
                })
                .map(|(decoder, _)| {
                    let branch = decoder + v1_prefix_bytes;
                    let branch_bytes = match code.get(branch..) {
                        Some([0x74, _, ..]) => 2,
                        Some([0x0f, 0x84, _, _, _, _, ..]) => 6,
                        _ => panic!(
                            "{context}: V1/V2 zero branch changed at {branch:#x}: {:02x?}",
                            code.get(branch.saturating_sub(24)..branch.saturating_add(24))
                                .unwrap_or_default()
                        ),
                    };
                    branch + branch_bytes
                })
                .collect::<Vec<_>>();
            assert_eq!(
                v1_decoders.len(),
                2,
                "{context}: offset-row and pointer-row V1/V2 decoders must remain disjoint"
            );
            assert_eq!(
                v1_decoders
                    .iter()
                    .filter(|&&after_branch| {
                        code[after_branch..].starts_with(&V1_SET_ROW)
                    })
                    .count(),
                1,
                "{context}: the offset-row V1/V2 decoder changed"
            );
            assert_eq!(
                v1_decoders
                    .iter()
                    .filter(|&&after_branch| {
                        code[after_branch..].starts_with(&V1_SET_POINTER_ROW)
                    })
                    .count(),
                1,
                "{context}: the pointer-row V1/V2 decoder changed"
            );
        }

        fn assert_aarch64_decode_shape(
            code: &[u8],
            output: OutputContract,
            compact_possible: bool,
            context: &str,
        ) {
            let words = code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            let v3_mask = aarch64_and_low_w(6, 8, 15).unwrap();
            let v4_mask = aarch64_and_low_w(8, 8, 15).unwrap();
            let (v3_decoders, v4_decoders, v7_decoders) = if output == OutputContract::Exists {
                let v3_decrement = aarch64_sub_w_imm(6, 8, 1).unwrap();
                let v4_backedge = aarch64_add_x_uxtw(11, 15, 8, 1).unwrap();
                let v3 = words
                    .windows(3)
                    .filter(|window| {
                        window[0] & 0xfff8_001f == 0x3778_0008
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == v3_decrement
                    })
                    .count();
                let v4 = words
                    .windows(3)
                    .filter(|window| {
                        window[0] & 0xfff8_001f == 0x3778_0008
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == v4_backedge
                    })
                    .count();
                let v7 = words
                    .windows(5)
                    .filter(|window| {
                        window[0] & 0xfff8_001f == 0x3778_0008
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == v4_mask
                            && window[3] == v3_decrement
                            && window[4] == v4_backedge
                    })
                    .count();
                assert_eq!(
                    words
                        .iter()
                        .filter(|&&word| word == v3_mask || word == v4_mask)
                        .count(),
                    usize::from(compact_possible),
                    "{context}: only V7 masks its live token to form the loop-index key"
                );
                (v3, v4, v7)
            } else {
                let v3_decrement = aarch64_sub_w_imm(6, 6, 1).unwrap();
                let v7_decrement = aarch64_sub_w_imm(6, 8, 1).unwrap();
                let v4_backedge = aarch64_add_x_uxtw(11, 15, 8, 1).unwrap();
                let v3 = words
                    .windows(3)
                    .filter(|window| {
                        window[0] == v3_mask
                            && window[1] & 0xff00_001f == 0x3400_0006
                            && window[2] == v3_decrement
                    })
                    .count();
                let v4 = words
                    .windows(3)
                    .filter(|window| {
                        window[0] == v4_mask
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == v4_backedge
                    })
                    .count();
                let v7 = words
                    .windows(4)
                    .filter(|window| {
                        window[0] == v4_mask
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == v7_decrement
                            && window[3] == v4_backedge
                    })
                    .count();
                (v3, v4, v7)
            };
            let expected_v3_decoders = if compact_possible { 11 } else { 0 };
            let expected_v4_decoders = usize::from(compact_possible);
            let expected_v7_decoders = usize::from(compact_possible);
            assert_eq!(
                v3_decoders, expected_v3_decoders,
                "{context}: reachable V8, shared V6, and V3 loops need exact decoders"
            );
            assert_eq!(
                v4_decoders, expected_v4_decoders,
                "{context}: reachable V4 needs one direct cell-offset decoder"
            );
            assert_eq!(
                v7_decoders, expected_v7_decoders,
                "{context}: reachable V7 needs a separate loop-index decoder"
            );
            assert_eq!(
                v3_decoders + v4_decoders + v7_decoders,
                expected_v3_decoders + expected_v4_decoders + expected_v7_decoders,
                "{context}: only reachable immutable compact rows retain decoders"
            );

            let v1_mask = aarch64_and_low_w(8, 8, 29).unwrap();
            let v1_set_row = aarch64_sub_w_imm(11, 8, 1).unwrap();
            let v1_set_pointer_row = aarch64_add_x_lsl(11, 15, 8, 2).unwrap();
            let v1_decoders = words
                .windows(2)
                .enumerate()
                .filter(|(_, window)| {
                    window[0] == v1_mask
                        && window[1] & 0xff00_001f == 0x3400_0008
                })
                .map(|(decoder, _)| decoder + 2)
                .collect::<Vec<_>>();
            assert_eq!(
                v1_decoders.len(),
                2,
                "{context}: offset-row and pointer-row V1/V2 decoders must remain disjoint"
            );
            assert_eq!(
                v1_decoders
                    .iter()
                    .filter(|&&after_branch| words[after_branch] == v1_set_row)
                    .count(),
                1,
                "{context}: the offset-row V1/V2 decoder must remain unchanged"
            );
            assert_eq!(
                v1_decoders
                    .iter()
                    .filter(|&&after_branch| words[after_branch] == v1_set_pointer_row)
                    .count(),
                1,
                "{context}: the pointer-row V1/V2 decoder must remain unchanged"
            );
        }

        fn assert_x86_u8_decode_shape(
            code: &[u8],
            output: OutputContract,
            compact_possible: bool,
            context: &str,
        ) {
            const EXISTS_TEST: [u8; 3] = [0x45, 0x84, 0xd2];
            const TOKEN_MASK: [u8; 4] = [0x41, 0x83, 0xe2, 0x7f];
            const DECREMENT: [u8; 3] = [0x41, 0xff, 0xca];
            let decoders = if output == OutputContract::Exists {
                let mut count = 0_usize;
                for (offset, window) in code.windows(EXISTS_TEST.len()).enumerate() {
                    if window != EXISTS_TEST {
                        continue;
                    }
                    let sign_branch = offset + EXISTS_TEST.len();
                    let Some(sign_bytes) =
                        x86_conditional_branch_len(code, sign_branch, 0x78, 0x88)
                    else {
                        continue;
                    };
                    let zero_branch = sign_branch + sign_bytes;
                    let Some(zero_bytes) =
                        x86_conditional_branch_len(code, zero_branch, 0x74, 0x84)
                    else {
                        continue;
                    };
                    if code[zero_branch + zero_bytes..].starts_with(&DECREMENT) {
                        count += 1;
                    }
                }
                count
            } else {
                let mut count = 0_usize;
                for (offset, window) in code.windows(TOKEN_MASK.len()).enumerate() {
                    if window != TOKEN_MASK {
                        continue;
                    }
                    let zero_branch = offset + TOKEN_MASK.len();
                    if x86_conditional_branch_len(code, zero_branch, 0x74, 0x84)
                        .is_some_and(|branch_bytes| {
                            code[zero_branch + branch_bytes..].starts_with(&DECREMENT)
                        })
                    {
                        count += 1;
                    }
                }
                count
            };
            assert_eq!(
                decoders,
                if compact_possible { 10 } else { 0 },
                "{context}: reachable V10 and V12 shifts need byte-cell decoders"
            );
            assert_eq!(
                code.windows(TOKEN_MASK.len())
                    .filter(|window| *window == TOKEN_MASK)
                    .count(),
                if output == OutputContract::Exists {
                    0
                } else if compact_possible {
                    10
                } else {
                    0
                },
                "{context}: byte-token masks belong only to endpoint contracts"
            );
        }

        fn assert_aarch64_u8_decode_shape(
            code: &[u8],
            output: OutputContract,
            compact_possible: bool,
            context: &str,
        ) {
            let words = code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            let token_mask = aarch64_and_low_w(6, 8, 7).unwrap();
            let decoders = if output == OutputContract::Exists {
                let decrement = aarch64_sub_w_imm(6, 8, 1).unwrap();
                words
                    .windows(3)
                    .filter(|window| {
                        window[0] & 0xfff8_001f == 0x3738_0008
                            && window[1] & 0xff00_001f == 0x3400_0008
                            && window[2] == decrement
                    })
                    .count()
            } else {
                let decrement = aarch64_sub_w_imm(6, 6, 1).unwrap();
                words
                    .windows(3)
                    .filter(|window| {
                        window[0] == token_mask
                            && window[1] & 0xff00_001f == 0x3400_0006
                            && window[2] == decrement
                    })
                    .count()
            };
            assert_eq!(
                decoders,
                if compact_possible { 10 } else { 0 },
                "{context}: reachable V10 and V12 shifts need byte-cell decoders"
            );
            assert_eq!(
                words.iter().filter(|&&word| word == token_mask).count(),
                if output == OutputContract::Exists {
                    0
                } else if compact_possible {
                    10
                } else {
                    0
                },
                "{context}: byte-token masks belong only to endpoint contracts"
            );
        }

        // A maximum-state V3 descriptor admits every low-token value in a
        // logical cell, with either acceptance value. Iterating every raw u16
        // therefore covers the union of all admitted logical cell classes.
        // Padded cells have the stricter independently authenticated value 0.
        for cell in u16::MIN..=u16::MAX {
            let decoded = zero_test_decode(cell);
            assert_eq!(former_x86_decode(cell), decoded, "x86 cell={cell:#06x}");
            assert_eq!(
                former_aarch64_decode(cell),
                decoded,
                "AArch64 cell={cell:#06x}"
            );
            let expected_exists = if decoded.0 {
                ExistsDecode::Match
            } else {
                decoded.1.map_or(ExistsDecode::Dead, |token| {
                    ExistsDecode::Token(u16::try_from(token).unwrap())
                })
            };
            assert_eq!(
                exists_sign_zero_decode(cell),
                expected_exists,
                "Exists cell={cell:#06x}"
            );
        }
        for (cell, expected) in [
            (0x0000_u16, (false, None)),
            (0x8000_u16, (true, None)),
            (0x0001_u16, (false, Some(0))),
            (0x8001_u16, (true, Some(0))),
            (0x7fff_u16, (false, Some(0x7ffe))),
            (0xffff_u16, (true, Some(0x7ffe))),
        ] {
            assert_eq!(zero_test_decode(cell), expected);
        }

        // The V10/V12 encoding is the exact byte-width analogue: bit 7 is
        // acceptance, low seven bits are the one-based state token, and zero
        // is the sole closed transition. Exhaust all 256 physical values.
        for cell in u8::MIN..=u8::MAX {
            let token = cell & DYNAMIC_NATIVE_ROWS_V10_NEXT_STATE_TOKEN_MASK;
            let decoded = (
                cell & DYNAMIC_NATIVE_ROWS_V10_ACCEPT_MASK != 0,
                token.checked_sub(1),
            );
            assert_eq!(
                decoded.0,
                cell & DYNAMIC_NATIVE_ROWS_V12_ACCEPT_MASK != 0
            );
            assert_eq!(
                token,
                cell & DYNAMIC_NATIVE_ROWS_V12_NEXT_STATE_TOKEN_MASK
            );
            let exists = if decoded.0 {
                ExistsDecode::Match
            } else {
                decoded.1.map_or(ExistsDecode::Dead, |state| {
                    ExistsDecode::Token(u16::from(state))
                })
            };
            let sign_zero = if i8::from_ne_bytes([cell]).is_negative() {
                ExistsDecode::Match
            } else {
                cell.checked_sub(1).map_or(ExistsDecode::Dead, |state| {
                    ExistsDecode::Token(u16::from(state))
                })
            };
            assert_eq!(sign_zero, exists, "compact-u8 cell={cell:#04x}");
        }

        // Scanner-free preflight enters only the pointer-row V1/V2 route, so
        // its offset-row decoder is unreachable and stripped. A real graph
        // root keeps both older representations live while this audit checks
        // that the V6/V7 decoders remain distinct from compact u16
        // V3/V4/V8. The disjoint byte-width checks below count V10 and
        // every V12 shift separately.
        let mut membership = [0_u64; 4];
        let byte = usize::from(b'a');
        membership[byte / 64] |= 1_u64 << (byte % 64);
        let root_filter = plan_dynamic_root_filter(NativeDynamicRootRequirement {
            scan_offset: 0,
            membership,
        })
        .unwrap()
        .expect("nontrivial decoder-audit root filter");
        let arm_target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .unwrap();
        let mut arm_data = vec![0_u8; 32];
        let arm_root = install_aarch64_dynamic_root_plan(
            &mut arm_data,
            0,
            root_filter,
            arm_target,
        )
        .unwrap();

        for (output, exact_span_width) in [
            (OutputContract::Exists, None),
            (OutputContract::SelectedEnd, None),
            (OutputContract::Span, Some(1)),
            (OutputContract::Span, None),
        ] {
            let context = format!("{output:?}/width={exact_span_width:?}");
            let compact_possible = true;
            let x86 = lower_x86_64_dynamic_rows_prepared_for_output(
                Some(root_filter),
                FeatureSet::EMPTY,
                output,
                exact_span_width,
                true,
            )
            .unwrap();
            assert_x86_decode_shape(&x86.code, output, compact_possible, &context);
            assert_x86_u8_decode_shape(&x86.code, output, compact_possible, &context);
            assert_eq!(
                x86.relocations
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL
                    })
                    .count(),
                if compact_possible { 2 } else { 0 },
                "x86/{context}: loop helper relocations follow compact reachability"
            );

            let arm = lower_aarch64_dynamic_rows_prepared_for_output(
                Some(arm_root),
                output,
                exact_span_width,
                true,
            )
            .unwrap();
            assert_aarch64_decode_shape(&arm.code, output, compact_possible, &context);
            assert_aarch64_u8_decode_shape(&arm.code, output, compact_possible, &context);
            assert_eq!(
                arm.relocations
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == DYNAMIC_ROWS_LOOP_SCAN_RUNTIME_SYMBOL
                    })
                    .count(),
                if compact_possible { 2 } else { 0 },
                "AArch64/{context}: loop helper relocations follow compact reachability"
            );
        }
    }

    #[test]
    fn aarch64_conditional_diamonds_invert_every_branch_family() {
        type EmitConditional = fn(&mut Aarch64Assembler, Aarch64Label) -> Result<(), ObjectError>;

        fn branch_eq(
            assembler: &mut Aarch64Assembler,
            target: Aarch64Label,
        ) -> Result<(), ObjectError> {
            assembler.branch_cond(AARCH64_EQ, target)
        }

        fn branch_zero(
            assembler: &mut Aarch64Assembler,
            target: Aarch64Label,
        ) -> Result<(), ObjectError> {
            assembler.branch_zero_w(6, target)
        }

        fn branch_nonzero(
            assembler: &mut Aarch64Assembler,
            target: Aarch64Label,
        ) -> Result<(), ObjectError> {
            assembler.branch_nonzero_w(7, target)
        }

        fn branch_bit_clear(
            assembler: &mut Aarch64Assembler,
            target: Aarch64Label,
        ) -> Result<(), ObjectError> {
            assembler.branch_bit_clear_w(8, 0, target)
        }

        fn branch_bit_set(
            assembler: &mut Aarch64Assembler,
            target: Aarch64Label,
        ) -> Result<(), ObjectError> {
            assembler.branch_bit_set_w(9, 0, target)
        }

        let cases: [(EmitConditional, u32); 5] = [
            (branch_eq, 0x5400_0041),        // b.ne false
            (branch_zero, 0x3500_0046),      // cbnz w6, false
            (branch_nonzero, 0x3400_0047),   // cbz w7, false
            (branch_bit_clear, 0x3700_0048), // tbnz w8, #0, false
            (branch_bit_set, 0x3600_0049),   // tbz w9, #0, false
        ];
        for (emit_conditional, expected) in cases {
            let mut assembler = Aarch64Assembler::new();
            let true_target = assembler.label().unwrap();
            let false_target = assembler.label().unwrap();
            emit_conditional(&mut assembler, true_target).unwrap();
            assembler.branch(false_target).unwrap();
            assembler.bind(true_target).unwrap();
            assembler.instruction(0xd503_201f).unwrap(); // nop
            assembler.bind(false_target).unwrap();
            assembler.instruction(0xd65f_03c0).unwrap(); // ret

            let words = assembler
                .finish()
                .unwrap()
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(words, [expected, 0xd503_201f, 0xd65f_03c0]);
        }

        for condition in 0_u8..=0x0d {
            let mut assembler = Aarch64Assembler::new();
            let true_target = assembler.label().unwrap();
            let false_target = assembler.label().unwrap();
            assembler.branch_cond(condition, true_target).unwrap();
            assembler.branch(false_target).unwrap();
            assembler.bind(true_target).unwrap();
            assembler.instruction(0xd503_201f).unwrap(); // nop
            assembler.bind(false_target).unwrap();
            assembler.instruction(0xd65f_03c0).unwrap(); // ret

            let words = assembler
                .finish()
                .unwrap()
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(words[0], 0x5400_0040 | u32::from(condition ^ 1));
            assert_eq!(words.len(), 3);
        }
    }

    #[test]
    fn aarch64_al_and_nv_diamonds_remain_unmodified() {
        for (condition, expected) in [(0x0e, 0x5400_004e), (0x0f, 0x5400_004f)] {
            let mut assembler = Aarch64Assembler::new();
            let true_target = assembler.label().unwrap();
            let false_target = assembler.label().unwrap();
            assembler.branch_cond(condition, true_target).unwrap();
            assembler.branch(false_target).unwrap();
            assembler.bind(true_target).unwrap();
            assembler.instruction(0xd503_201f).unwrap(); // nop
            assembler.bind(false_target).unwrap();
            assembler.instruction(0xd65f_03c0).unwrap(); // ret

            let words = assembler
                .finish()
                .unwrap()
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert_eq!(words, [expected, 0x1400_0002, 0xd503_201f, 0xd65f_03c0]);
        }
    }

    #[test]
    fn aarch64_test_bit_diamond_uses_exact_final_positive_range() {
        let mut fits_after_deletion = Aarch64Assembler::new();
        let true_target = fits_after_deletion.label().unwrap();
        let false_target = fits_after_deletion.label().unwrap();
        fits_after_deletion
            .branch_bit_clear_w(0, 0, true_target)
            .unwrap();
        fits_after_deletion.branch(false_target).unwrap();
        fits_after_deletion.bind(true_target).unwrap();
        for _ in 0..8_190 {
            fits_after_deletion.instruction(0xd503_201f).unwrap(); // nop
        }
        fits_after_deletion.bind(false_target).unwrap();
        fits_after_deletion.instruction(0xd65f_03c0).unwrap(); // ret
        let words = fits_after_deletion
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(words.len(), 8_192);
        assert_eq!(words[0], 0x3703_ffe0); // tbnz false at +8191 words

        let mut remains_out_of_range = Aarch64Assembler::new();
        let true_target = remains_out_of_range.label().unwrap();
        let false_target = remains_out_of_range.label().unwrap();
        remains_out_of_range
            .branch_bit_clear_w(0, 0, true_target)
            .unwrap();
        remains_out_of_range.branch(false_target).unwrap();
        remains_out_of_range.bind(true_target).unwrap();
        for _ in 0..8_191 {
            remains_out_of_range.instruction(0xd503_201f).unwrap(); // nop
        }
        remains_out_of_range.bind(false_target).unwrap();
        remains_out_of_range.instruction(0xd65f_03c0).unwrap(); // ret
        let words = remains_out_of_range
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(words.len(), 8_194);
        assert_eq!(words[0], 0x3600_0040); // tbz true remains
        assert_eq!(words[1], 0x1400_2000); // b false remains
    }

