    #[test]
    fn aarch64_relocated_branches_are_opaque_to_control_flow_rewrites() {
        let mut assembler = Aarch64Assembler::new();
        let trampoline = assembler.label().unwrap();
        let after_trampoline = assembler.label().unwrap();
        let done = assembler.label().unwrap();

        assembler.branch_cond(AARCH64_EQ, trampoline).unwrap();
        assembler.branch(after_trampoline).unwrap();
        assembler.bind(trampoline).unwrap();
        let link_owned_branch = assembler.code.len();
        assembler.branch(done).unwrap();
        assembler.bind(after_trampoline).unwrap();
        assembler.instruction(0xd503_201f).unwrap(); // nop
        assembler.bind(done).unwrap();
        assembler.instruction(0xd65f_03c0).unwrap(); // ret

        let mut relocation_offsets = [link_owned_branch];
        let words = assembler
            .finish_with_offsets(&mut relocation_offsets)
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(relocation_offsets, [4]);
        assert_eq!(
            words,
            [
                0x5400_0041, // b.ne skips the link-owned true trampoline
                0x1400_0002, // relocated branch is retained
                0xd503_201f,
                0xd65f_03c0,
            ]
        );
    }

    #[test]
    fn aarch64_branch_compaction_remaps_relocations_transactionally() {
        let mut assembler = Aarch64Assembler::new();
        let relocated = assembler.label().unwrap();
        assembler.branch(relocated).unwrap();
        assembler.bind(relocated).unwrap();
        let adrp = assembler.instruction(0x9000_0005).unwrap();
        assembler.instruction(0xd65f_03c0).unwrap(); // ret
        let old_end = assembler.code.len();
        let mut relocation_offsets = [adrp, old_end];
        let code = assembler
            .finish_with_offsets(&mut relocation_offsets)
            .unwrap();
        assert_eq!(relocation_offsets, [0, 8]);
        assert_eq!(
            code.chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>(),
            [0x9000_0005, 0xd65f_03c0]
        );

        let mut invalid = Aarch64Assembler::new();
        let unbound = invalid.label().unwrap();
        invalid.branch(unbound).unwrap();
        let original = invalid.clone();
        let mut unchanged_offsets = [0_usize];
        assert!(invalid.control_flow_optimized(&unchanged_offsets).is_err());
        assert_eq!(invalid, original);
        assert!(
            invalid
                .clone()
                .finish_with_offsets(&mut unchanged_offsets)
                .is_err()
        );
        assert_eq!(unchanged_offsets, [0]);
        assert_eq!(invalid, original);
    }

    #[test]
    #[allow(
        clippy::items_after_statements,
        reason = "the local lane oracle is kept beside the exact encoding assertions it models"
    )]
    fn aarch64_first_candidate_lowering_has_exact_encodings_and_lane_oracle() {
        assert_eq!(aarch64_bsl_16b(24, 29, 31).unwrap(), 0x6e7f_1fb8);
        assert_eq!(aarch64_bsl_16b(24, 28, 31).unwrap(), 0x6e7f_1f98);
        assert_eq!(aarch64_add_16b(28, 28, 30).unwrap(), 0x4e3e_879c);
        assert_eq!(aarch64_umin_16b(24, 24, 25).unwrap(), 0x6e39_6f18);
        assert_eq!(aarch64_uminv_16b(24, 24).unwrap(), 0x6e31_ab18);
        assert_eq!(aarch64_csel_x(7, 7, 2, AARCH64_EQ).unwrap(), 0x9a82_00e7);

        let mut assembler = Aarch64Assembler::new();
        aarch64_emit_first_candidate_in_batch(&mut assembler, 24).unwrap();
        let words = assembler
            .finish()
            .unwrap()
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            words,
            [
                aarch64_orr_16b(28, 29, 29).unwrap(),
                aarch64_bsl_16b(24, 28, 31).unwrap(),
                aarch64_add_16b(28, 28, 30).unwrap(),
                aarch64_bsl_16b(25, 28, 31).unwrap(),
                aarch64_add_16b(28, 28, 30).unwrap(),
                aarch64_bsl_16b(26, 28, 31).unwrap(),
                aarch64_add_16b(28, 28, 30).unwrap(),
                aarch64_bsl_16b(27, 28, 31).unwrap(),
                aarch64_umin_16b(24, 24, 25).unwrap(),
                aarch64_umin_16b(26, 26, 27).unwrap(),
                aarch64_umin_16b(24, 24, 26).unwrap(),
                aarch64_uminv_16b(24, 24).unwrap(),
                aarch64_umov_b0(12, 24).unwrap(),
                aarch64_add_x_reg(2, 2, 12).unwrap(),
            ]
        );

        fn lowered_first_lane(masks: &[[u8; 16]]) -> Option<usize> {
            let mut selected = 64_u8;
            for (block, mask) in masks.iter().enumerate() {
                for (lane, &candidate) in mask.iter().enumerate() {
                    let absolute = u8::try_from(block * 16 + lane).unwrap();
                    let lowered = if candidate == 0xff { absolute } else { 64 };
                    selected = selected.min(lowered);
                }
            }
            (usize::from(selected) < masks.len() * 16).then_some(usize::from(selected))
        }

        for blocks in [1_usize, 2, 4] {
            let empty = vec![[0_u8; 16]; blocks];
            assert_eq!(lowered_first_lane(&empty), None);
            for expected in 0..blocks * 16 {
                let mut masks = empty.clone();
                masks[expected / 16][expected % 16] = 0xff;
                if expected + 7 < blocks * 16 {
                    masks[(expected + 7) / 16][(expected + 7) % 16] = 0xff;
                }
                assert_eq!(lowered_first_lane(&masks), Some(expected));
            }
        }

        let compiled = compile(
            CompileRequest::new("[abcd]", Target::aarch64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Exists),
        )
        .unwrap();
        let (data, layout) = build_native_dfa_table_for_architecture(
            compiled.program().native_dfa_view().unwrap(),
            Architecture::Aarch64,
        )
        .unwrap();
        let offset = usize::try_from(layout.asimd_lane_index_offset.unwrap()).unwrap();
        assert_eq!(offset % AARCH64_FIRST_LANE_INDEX.len(), 0);
        assert_eq!(
            &data[offset..offset + AARCH64_FIRST_LANE_INDEX.len()],
            &AARCH64_FIRST_LANE_INDEX
        );
        assert_eq!(data.len(), offset + AARCH64_FIRST_LANE_INDEX.len());
    }

    #[test]
    fn concrete_aarch64_targets_retain_first_lane_data_only_for_asimd_routes() {
        let portable = Target::aarch64_linux();
        let compiled = compile(
            CompileRequest::new("[abcd]", portable)
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Exists),
        )
        .unwrap();
        let view = compiled.program().native_dfa_view().unwrap();
        let build_for = |target| {
            build_native_dfa_table_for_target_with_cost_model_and_data_limit(
                view,
                target,
                native_vector_filter_cost_model_for_target(target, true),
                direct_relation_vector_owns_route(target),
                usize::MAX,
            )
            .unwrap()
        };

        let pure_sve = portable
            .with_features(FeatureSet::of(CpuFeature::Aarch64Sve))
            .unwrap();
        let pure_sve2 = portable
            .with_features(
                FeatureSet::of(CpuFeature::Aarch64Sve).with(CpuFeature::Aarch64Sve2),
            )
            .unwrap();
        for target in [portable, pure_sve, pure_sve2, Target::aarch64_macos()] {
            let (_, layout) = build_for(target);
            assert_eq!(
                layout.asimd_lane_index_offset, None,
                "target without ASIMD retained ASIMD-only data: {target:?}"
            );
        }

        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let mixed_sve = portable
            .with_features(asimd.with(CpuFeature::Aarch64Sve))
            .unwrap();
        let mixed_sve2 = portable
            .with_features(
                asimd
                    .with(CpuFeature::Aarch64Sve)
                    .with(CpuFeature::Aarch64Sve2),
            )
            .unwrap();
        for target in [
            portable.with_features(asimd).unwrap(),
            mixed_sve,
            mixed_sve2,
            Target::aarch64_macos().with_features(asimd).unwrap(),
        ] {
            let (_, layout) = build_for(target);
            assert!(
                layout.asimd_lane_index_offset.is_some(),
                "ASIMD-capable target lost runtime fallback data: {target:?}"
            );
        }

        let (conservative_data, conservative_layout) =
            build_native_dfa_table_for_architecture(view, Architecture::Aarch64).unwrap();
        let (portable_data, portable_layout) = build_for(portable);
        assert!(conservative_layout.asimd_lane_index_offset.is_some());
        assert_eq!(portable_layout.asimd_lane_index_offset, None);
        assert!(portable_data.len() < conservative_data.len());
    }

