    #[test]
    fn aarch64_sve_immediate_dup_setup_covers_every_byte_in_one_instruction() {
        for immediate in u8::MIN..=u8::MAX {
            for destination in 0_u8..=31 {
                let word = aarch64_sve_dup_b_imm(destination, immediate).unwrap();
                assert_eq!(word & 0x1f, u32::from(destination));
                assert_eq!((word >> 5) & 0xff, u32::from(immediate));
                assert_eq!(word & 0xffff_e000, 0x2538_c000);
            }

            let mut filter = EMPTY_NATIVE_START_FILTER;
            filter.ranges[0] = NativeByteRange {
                start: immediate,
                end: immediate,
            };
            filter.range_count = 1;
            filter.candidate_bytes = 1;
            let mut assembler = Aarch64Assembler::new();
            aarch64_emit_sve_filter_setup(
                &mut assembler,
                filter,
                Aarch64SveFilterKind::Sve,
                0,
            )
            .unwrap();
            assert_eq!(
                assembler.finish().unwrap(),
                aarch64_sve_dup_b_imm(16, immediate)
                    .unwrap()
                    .to_le_bytes()
            );
        }

        let mut range = EMPTY_NATIVE_START_FILTER;
        range.ranges[0] = NativeByteRange {
            start: 0x00,
            end: 0xff,
        };
        range.range_count = 1;
        range.candidate_bytes = 256;
        let mut assembler = Aarch64Assembler::new();
        aarch64_emit_sve_filter_setup(
            &mut assembler,
            range,
            Aarch64SveFilterKind::Sve,
            0,
        )
        .unwrap();
        let mut expected = Vec::new();
        expected.extend_from_slice(&aarch64_sve_dup_b_imm(16, 0x00).unwrap().to_le_bytes());
        expected.extend_from_slice(&aarch64_sve_dup_b_imm(17, 0xff).unwrap().to_le_bytes());
        assert_eq!(assembler.finish().unwrap(), expected);
    }

    #[test]
    fn aarch64_sve_brkb_incp_model_matches_every_active_first_lane() {
        for destination in 0_u8..=31 {
            for predicate in 0_u8..=15 {
                let word = aarch64_sve_incp_b(destination, predicate).unwrap();
                assert_eq!(word & 0x1f, u32::from(destination));
                assert_eq!((word >> 5) & 0x0f, u32::from(predicate));
                assert_eq!(word & 0xffff_fc00, 0x252c_8800);
            }
        }

        for vector_length in (16_usize..=256).step_by(16) {
            for active_lanes in 1_usize..=vector_length {
                for first_candidate in 0_usize..active_lanes {
                    // BRKB P2.B, P0/Z, Pc.B leaves exactly the active P0
                    // lanes preceding the first active candidate in P2.
                    let p2_count = (0..vector_length)
                        .filter(|&lane| lane < active_lanes && lane < first_candidate)
                        .count();
                    let candidate_base = 17_usize;
                    assert_eq!(candidate_base + p2_count, candidate_base + first_candidate);
                }
            }
        }
    }

    #[test]
    fn aarch64_sve_constants_use_ordinary_aapcs64_scratch_registers() {
        // The public entry has no scalable arguments/results. AAPCS64 6.1.3
        // therefore classifies Z16..Z31 as caller-saved; 6.1.4 classifies all
        // predicates as caller-saved. Keep constants out of Z8..Z15 so their
        // callee-saved low V-register halves never need a preservation frame.
        let registers = (0..MAX_START_FILTER_RANGES)
            .map(|index| aarch64_sve_filter_constant_register(index).unwrap())
            .collect::<Vec<_>>();
        assert_eq!(registers, (16_u8..=23).collect::<Vec<_>>());
    }

    #[test]
    fn aarch64_sve_batched_and_predicated_tail_model_matches_scalar_for_all_vls() {
        fn scalar_first(
            haystack: &[u8],
            start: usize,
            end: usize,
            scan_offset: usize,
            maximum_scan_offset: usize,
        ) -> Option<usize> {
            (start..end)
                .take_while(|&candidate| candidate + maximum_scan_offset < end)
                .find(|&candidate| haystack[candidate + scan_offset] == b'Z')
        }

        fn sve_first(
            haystack: &[u8],
            mut position: usize,
            end: usize,
            scan_offset: usize,
            maximum_scan_offset: usize,
            vector_length: usize,
            maximum_batch_vector_length: Option<usize>,
        ) -> Option<usize> {
            let safe_end = end.saturating_sub(maximum_scan_offset);
            if position >= safe_end {
                return None;
            }
            if maximum_batch_vector_length.is_some_and(|maximum| vector_length <= maximum) {
                while safe_end - position >= 4 * vector_length {
                    if let Some(candidate) = (position..position + 4 * vector_length)
                        .find(|&candidate| haystack[candidate + scan_offset] == b'Z')
                    {
                        return Some(candidate);
                    }
                    position += 4 * vector_length;
                }
            }
            while safe_end - position >= vector_length {
                if let Some(candidate) = (position..position + vector_length)
                    .find(|&candidate| haystack[candidate + scan_offset] == b'Z')
                {
                    return Some(candidate);
                }
                position += vector_length;
            }
            (position..safe_end).find(|&candidate| haystack[candidate + scan_offset] == b'Z')
        }

        for vector_length in (16_usize..=256).step_by(16) {
            for (scan_offset, maximum_scan_offset) in [(0_usize, 0_usize), (0, 1), (1, 1), (1, 3)] {
                for start in [0_usize, 3] {
                    let mut lengths = vec![0, 1, maximum_scan_offset, maximum_scan_offset + 1];
                    for vectors in [1_usize, 4, 5] {
                        let boundary = vectors * vector_length + maximum_scan_offset;
                        lengths.extend([
                            boundary.saturating_sub(1),
                            boundary,
                            boundary + 1,
                            boundary + 2,
                        ]);
                    }
                    lengths.sort_unstable();
                    lengths.dedup();
                    for maximum_batch_vector_length in [None, Some(16_usize), Some(128)] {
                        for &length in &lengths {
                            let end = start + length;
                            let mut haystack = vec![b'x'; end];
                            assert_eq!(
                                sve_first(
                                    &haystack,
                                    start,
                                    end,
                                    scan_offset,
                                    maximum_scan_offset,
                                    vector_length,
                                    maximum_batch_vector_length,
                                ),
                                scalar_first(&haystack, start, end, scan_offset, maximum_scan_offset,)
                            );
                            let safe_end = end.saturating_sub(maximum_scan_offset);
                            for candidate in start..safe_end {
                                haystack[candidate + scan_offset] = b'Z';
                                assert_eq!(
                                    sve_first(
                                        &haystack,
                                        start,
                                        end,
                                        scan_offset,
                                        maximum_scan_offset,
                                        vector_length,
                                        maximum_batch_vector_length,
                                    ),
                                    scalar_first(
                                        &haystack,
                                        start,
                                        end,
                                        scan_offset,
                                        maximum_scan_offset,
                                    ),
                                    "vl={vector_length}, batch_max={maximum_batch_vector_length:?}, scan={scan_offset}, max={maximum_scan_offset}, start={start}, end={end}, candidate={candidate}"
                                );
                                haystack[candidate + scan_offset] = b'x';
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn aarch64_sve_multicol_batched_and_tail_model_matches_scalar_for_all_vls() {
        const MAXIMUM_SCAN_OFFSET: usize = 3;

        fn is_filter_candidate(
            haystack: &[u8],
            candidate: usize,
            secondary_offsets: [usize; 2],
        ) -> bool {
            haystack[candidate] == b'q'
                && secondary_offsets
                    .into_iter()
                    .all(|offset| haystack[candidate + offset] == b'e')
        }

        fn scalar_filter_first(
            haystack: &[u8],
            start: usize,
            end: usize,
            secondary_offsets: [usize; 2],
        ) -> Option<usize> {
            (start..end.saturating_sub(MAXIMUM_SCAN_OFFSET))
                .find(|&candidate| is_filter_candidate(haystack, candidate, secondary_offsets))
        }

        fn scalar_match(haystack: &[u8], start: usize, end: usize) -> Option<usize> {
            (start..end.saturating_sub(MAXIMUM_SCAN_OFFSET))
                .find(|&candidate| &haystack[candidate..candidate + 4] == b"qeee")
        }

        fn sve_filter_first(
            haystack: &[u8],
            mut position: usize,
            end: usize,
            vector_length: usize,
            maximum_batch_vector_length: Option<usize>,
            secondary_offsets: [usize; 2],
        ) -> Option<usize> {
            let safe_end = end.saturating_sub(MAXIMUM_SCAN_OFFSET);
            if position >= safe_end {
                return None;
            }
            if maximum_batch_vector_length.is_some_and(|maximum| vector_length <= maximum) {
                while safe_end - position >= 4 * vector_length {
                    if let Some(candidate) = (position..position + 4 * vector_length)
                        .find(|&candidate| {
                            is_filter_candidate(haystack, candidate, secondary_offsets)
                        })
                    {
                        return Some(candidate);
                    }
                    position += 4 * vector_length;
                }
            }
            while safe_end - position >= vector_length {
                if let Some(candidate) = (position..position + vector_length)
                    .find(|&candidate| {
                        is_filter_candidate(haystack, candidate, secondary_offsets)
                    })
                {
                    return Some(candidate);
                }
                position += vector_length;
            }
            (position..safe_end)
                .find(|&candidate| is_filter_candidate(haystack, candidate, secondary_offsets))
        }

        fn sve_match(
            haystack: &[u8],
            mut position: usize,
            end: usize,
            vector_length: usize,
            maximum_batch_vector_length: Option<usize>,
            secondary_offsets: [usize; 2],
        ) -> Option<usize> {
            while let Some(candidate) = sve_filter_first(
                haystack,
                position,
                end,
                vector_length,
                maximum_batch_vector_length,
                secondary_offsets,
            ) {
                if &haystack[candidate..candidate + 4] == b"qeee" {
                    return Some(candidate);
                }
                position = candidate + 1;
            }
            None
        }

        for secondary_offsets in [[3_usize, 2_usize], [2, 3]] {
            for vector_length in (16_usize..=256).step_by(16) {
                for start in [0_usize, 3] {
                    let mut lengths =
                        vec![0, 1, MAXIMUM_SCAN_OFFSET, MAXIMUM_SCAN_OFFSET + 1];
                    for vectors in [1_usize, 4, 5] {
                        let boundary = vectors * vector_length + MAXIMUM_SCAN_OFFSET;
                        lengths.extend([
                            boundary.saturating_sub(1),
                            boundary,
                            boundary + 1,
                            boundary + 2,
                        ]);
                    }
                    lengths.sort_unstable();
                    lengths.dedup();
                    for maximum_batch_vector_length in [None, Some(16_usize), Some(128)] {
                        for &length in &lengths {
                            let end = start + length;
                            let mut haystack = vec![b'x'; end];
                            let safe_end = end.saturating_sub(MAXIMUM_SCAN_OFFSET);
                            // Exercise rejected primary lanes before and between
                            // complete graph-column intersections.
                            for candidate in (start..safe_end).step_by(5) {
                                haystack[candidate] = b'q';
                            }
                            assert_eq!(
                                sve_filter_first(
                                    &haystack,
                                    start,
                                    end,
                                    vector_length,
                                    maximum_batch_vector_length,
                                    secondary_offsets,
                                ),
                                scalar_filter_first(&haystack, start, end, secondary_offsets)
                            );
                            assert_eq!(
                                sve_match(
                                    &haystack,
                                    start,
                                    end,
                                    vector_length,
                                    maximum_batch_vector_length,
                                    secondary_offsets,
                                ),
                                scalar_match(&haystack, start, end)
                            );
                            // Seed complete graph-filter hits that the DFA
                            // rejects at offset one, then verify scanner re-entry.
                            for candidate in (start..safe_end).step_by(7) {
                                haystack[candidate] = b'q';
                                haystack[candidate + 2] = b'e';
                                haystack[candidate + 3] = b'e';
                            }
                            assert_eq!(
                                sve_match(
                                    &haystack,
                                    start,
                                    end,
                                    vector_length,
                                    maximum_batch_vector_length,
                                    secondary_offsets,
                                ),
                                scalar_match(&haystack, start, end)
                            );
                            for candidate in start..safe_end {
                                let positions = [
                                    candidate,
                                    candidate + 1,
                                    candidate + 2,
                                    candidate + 3,
                                ];
                                let previous = positions.map(|position| haystack[position]);
                                haystack[candidate..candidate + 4].copy_from_slice(b"qeee");
                                assert_eq!(
                                    sve_match(
                                        &haystack,
                                        start,
                                        end,
                                        vector_length,
                                        maximum_batch_vector_length,
                                        secondary_offsets,
                                    ),
                                    scalar_match(&haystack, start, end),
                                    "columns={secondary_offsets:?}, vl={vector_length}, batch_max={maximum_batch_vector_length:?}, start={start}, end={end}, candidate={candidate}"
                                );
                                for (position, byte) in positions.into_iter().zip(previous) {
                                    haystack[position] = byte;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn exact_multicolumn_mask_model_is_exhaustive_over_truth_orders_and_tails() {
        fn permutations(column_count: usize) -> Vec<Vec<usize>> {
            fn visit(prefix: &mut Vec<usize>, remaining: &mut Vec<usize>, out: &mut Vec<Vec<usize>>) {
                if remaining.is_empty() {
                    out.push(prefix.clone());
                    return;
                }
                for index in 0..remaining.len() {
                    let column = remaining.remove(index);
                    prefix.push(column);
                    visit(prefix, remaining, out);
                    prefix.pop();
                    remaining.insert(index, column);
                }
            }
            let mut out = Vec::new();
            visit(
                &mut Vec::new(),
                &mut (0..column_count).collect(),
                &mut out,
            );
            out
        }

        const LANES: usize = 4;
        for column_count in 2_usize..=MAX_VECTOR_FILTER_COLUMNS {
            let assignments = 1_usize << (column_count * LANES);
            for encoded in 0..assignments {
                let masks = (0..column_count)
                    .map(|column| {
                        (0..LANES).fold(0_u8, |mask, lane| {
                            let bit = column * LANES + lane;
                            mask | (u8::from(encoded & (1_usize << bit) != 0) << lane)
                        })
                    })
                    .collect::<Vec<_>>();
                for order in permutations(column_count) {
                    for active_lanes in 0..=LANES {
                        let active = if active_lanes == LANES {
                            u8::MAX >> (8 - LANES)
                        } else {
                            (1_u8 << active_lanes) - 1
                        };
                        let vector = order
                            .iter()
                            .fold(active, |mask, &column| mask & masks[column]);
                        let scalar = (0..active_lanes).fold(0_u8, |mask, lane| {
                            let matches = (0..column_count)
                                .all(|column| masks[column] & (1_u8 << lane) != 0);
                            mask | (u8::from(matches) << lane)
                        });
                        assert_eq!(
                            vector, scalar,
                            "columns={column_count}, encoded={encoded:#x}, order={order:?}, active={active_lanes}"
                        );
                    }
                }
            }
        }

        // Four-vector batches must select the first matching lane in source
        // order after every column has been intersected independently.
        for block in 0_usize..4 {
            for lane in 0_usize..LANES {
                let mut masks = [[0_u8; MAX_VECTOR_FILTER_COLUMNS]; 4];
                for column in &mut masks[block] {
                    *column |= 1_u8 << lane;
                }
                let selected = masks.iter().enumerate().find_map(|(candidate_block, columns)| {
                    let intersection = columns.iter().fold(u8::MAX, |mask, column| mask & column);
                    (intersection != 0).then(|| {
                        candidate_block * LANES
                            + usize::try_from(intersection.trailing_zeros()).unwrap()
                    })
                });
                assert_eq!(selected, Some(block * LANES + lane));
            }
        }
    }

    #[test]
    fn x86_assembler_threads_finite_jump_chains_but_preserves_cycles() {
        let mut assembler = X86Assembler::new();
        let trampoline = assembler.label().unwrap();
        let target = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], trampoline).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(trampoline).unwrap();
        assembler.branch(&[0xe9], target).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(target).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assert_eq!(
            assembler.finish().unwrap(),
            [0x74, 0x04, 0x90, 0xeb, 0x01, 0x90, 0x90]
        );

        let mut assembler = X86Assembler::new();
        let first = assembler.label().unwrap();
        let second = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], first).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(first).unwrap();
        assembler.branch(&[0xe9], second).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(second).unwrap();
        assembler.branch(&[0xe9], first).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assert_eq!(
            assembler.finish().unwrap(),
            [0x74, 0x01, 0x90, 0xeb, 0x01, 0x90, 0xeb, 0xfb, 0x90]
        );

        let mut assembler = X86Assembler::new();
        let trampoline = assembler.label().unwrap();
        let target = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], trampoline).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(trampoline).unwrap();
        assembler.branch(&[0xe9], target).unwrap();
        for _ in 0..200 {
            assembler.instruction(&[0x90]).unwrap();
        }
        assembler.bind(target).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assert_eq!(&assembler.finish().unwrap()[..3], &[0x74, 0x01, 0x90]);
    }

    #[test]
    fn x86_assembler_inverts_conditional_jump_diamonds_before_relaxation() {
        let mut assembler = X86Assembler::new();
        let taken = assembler.label().unwrap();
        let failed = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], taken).unwrap();
        assembler.branch(&[0xe9], failed).unwrap();
        assembler.bind(taken).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(failed).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assert_eq!(assembler.finish().unwrap(), [0x75, 0x01, 0x90, 0x90]);

        let mut assembler = X86Assembler::new();
        let taken = assembler.label().unwrap();
        let failed = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], taken).unwrap();
        assembler.branch(&[0xe9], failed).unwrap();
        assembler.bind(taken).unwrap();
        for _ in 0..200 {
            assembler.instruction(&[0x90]).unwrap();
        }
        assembler.bind(failed).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        let code = assembler.finish().unwrap();
        assert_eq!(&code[..6], &[0x0f, 0x85, 0xc8, 0, 0, 0]);
        assert_eq!(code.len(), 207);

        let mut assembler = X86Assembler::new();
        let trampoline = assembler.label().unwrap();
        let taken = assembler.label().unwrap();
        let failed = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x85], trampoline).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.branch(&[0x0f, 0x84], taken).unwrap();
        assembler.bind(trampoline).unwrap();
        assembler.branch(&[0xe9], failed).unwrap();
        assembler.bind(taken).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assembler.bind(failed).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        let finished = assembler.finish_with_label_offsets().unwrap();
        let incoming_target = x86_test_branch_target(&finished.code, 0).unwrap().0;
        assert_eq!(incoming_target, finished.label_offset(failed).unwrap());

        let mut assembler = X86Assembler::new();
        let taken = assembler.label().unwrap();
        let looping = assembler.label().unwrap();
        assembler.branch(&[0x0f, 0x84], taken).unwrap();
        assembler.bind(looping).unwrap();
        assembler.branch(&[0xe9], looping).unwrap();
        assembler.bind(taken).unwrap();
        assert_eq!(assembler.finish().unwrap(), [0x74, 0x02, 0xeb, 0xfe]);
    }

    #[test]
    fn x86_assembler_removes_unreachable_branches_after_terminators() {
        let mut assembler = X86Assembler::new();
        let first = assembler.label().unwrap();
        let second = assembler.label().unwrap();
        assembler.instruction(&[0xc3]).unwrap();
        assembler.bind(first).unwrap();
        assembler.branch(&[0xe9], second).unwrap();
        assembler.bind(second).unwrap();
        assembler.branch(&[0xe9], first).unwrap();
        assert_eq!(assembler.finish().unwrap(), [0xc3]);

        let mut assembler = X86Assembler::new();
        let dead = assembler.label().unwrap();
        assembler.instruction(&[0xe9]).unwrap();
        push_bytes(&mut assembler.code, &[0; 4]).unwrap();
        assembler.branch(&[0x0f, 0x84], dead).unwrap();
        assembler.bind(dead).unwrap();
        assembler.instruction(&[0x90]).unwrap();
        assert_eq!(assembler.finish().unwrap(), [0xe9, 0, 0, 0, 0, 0x90]);
    }

    #[test]
    fn x86_assembler_keeps_cfg_reached_by_a_raw_internal_jump() {
        let mut assembler = X86Assembler::new();
        let taken = assembler.label().unwrap();
        let done = assembler.label().unwrap();

        // This raw rel32 jump targets the next instruction. Unlike a RET, its
        // bytes alone do not prove that the destination leaves this CFG.
        assembler.instruction(&[0xe9]).unwrap();
        push_bytes(&mut assembler.code, &[0; 4]).unwrap();
        assembler.branch(&[0x0f, 0x84], taken).unwrap();
        assembler.instruction(&[0xb8, 1, 0, 0, 0]).unwrap();
        assembler.branch(&[0xe9], done).unwrap();
        assembler.bind(taken).unwrap();
        assembler.instruction(&[0xb8, 2, 0, 0, 0]).unwrap();
        assembler.bind(done).unwrap();
        assembler.instruction(&[0xc3]).unwrap();

        assert_eq!(
            assembler.finish().unwrap(),
            [
                0xe9, 0, 0, 0, 0, 0x74, 0x07, 0xb8, 1, 0, 0, 0, 0xeb, 0x05, 0xb8, 2, 0, 0, 0, 0xc3,
            ]
        );
    }

    #[test]
    fn sparse_batch_admission_uses_stable_frequency_and_instruction_cost() {
        let one_range = |start: u8, end: u8| {
            let mut filter = EMPTY_NATIVE_START_FILTER;
            filter.ranges[0] = NativeByteRange { start, end };
            filter.range_count = 1;
            filter.candidate_bytes = u16::from(end) - u16::from(start) + 1;
            filter
        };

        let rare = one_range(1, 1);
        assert_eq!(estimated_filter_frequency_units(rare), 1);
        assert!(use_aarch64_filter_batch(rare));
        for kind in [
            X86StartFilterKind::Sse2,
            X86StartFilterKind::Avx2,
            X86StartFilterKind::Avx512Bw,
        ] {
            assert!(x86_use_sparse_filter_mask_batch(rare, kind));
        }

        // Cardinality alone used to reject this five-byte range. The stable
        // model assigns two units to each digit, making it cheap enough for
        // the exact-lane 64-byte batch.
        let digits = one_range(b'3', b'7');
        assert_eq!(digits.candidate_bytes, 5);
        assert_eq!(estimated_filter_frequency_units(digits), 10);
        assert!(use_aarch64_filter_batch(digits));

        let common = one_range(b'e', b'e');
        assert_eq!(estimated_filter_frequency_units(common), 24);
        assert!(!use_aarch64_filter_batch(common));

        let mut expensive = EMPTY_NATIVE_START_FILTER;
        for (index, byte) in (1_u8..=8).enumerate() {
            expensive.ranges[index] = NativeByteRange {
                start: byte,
                end: byte,
            };
        }
        expensive.range_count = 8;
        expensive.candidate_bytes = 8;
        assert!(estimated_filter_frequency_units(expensive) <= 8);
        assert!(vector_filter_instruction_units(expensive) > MAX_VECTOR_FILTER_INSTRUCTION_UNITS);
        assert!(!use_aarch64_filter_batch(expensive));
    }

    #[test]
    fn sve_batch_admission_derives_a_runtime_vl_ceiling_from_graph_cost() {
        let exact = |byte: u8| {
            let mut filter = EMPTY_NATIVE_START_FILTER;
            filter.ranges[0] = NativeByteRange {
                start: byte,
                end: byte,
            };
            filter.range_count = 1;
            filter.candidate_bytes = 1;
            filter
        };
        let byte_with_units = |expected| {
            (u8::MIN..=u8::MAX)
                .find(|&byte| estimated_byte_frequency_units(byte) == expected)
                .unwrap()
        };
        for (units, maximum_vl) in [(1_u16, 128_u16), (2, 64), (4, 32), (8, 16)] {
            let filter = exact(byte_with_units(units));
            assert_eq!(estimated_filter_frequency_units(filter), units);
            assert_eq!(
                aarch64_sve_batch_max_vector_bytes(filter, Aarch64SveFilterKind::Sve),
                Some(maximum_vl)
            );
        }
        for units in [16_u16, 24, 32] {
            let filter = exact(byte_with_units(units));
            assert_eq!(
                aarch64_sve_batch_max_vector_bytes(filter, Aarch64SveFilterKind::Sve),
                None
            );
        }

        // Five cheap exact alternatives exceed the base-SVE hot instruction
        // cap (five compares plus four ORs), but SVE2 MATCH still forms the
        // same graph membership in one instruction and earns a 16-byte gate.
        let mut fragmented = EMPTY_NATIVE_START_FILTER;
        for (index, byte) in (u8::MIN..=u8::MAX)
            .filter(|&byte| estimated_byte_frequency_units(byte) == 1)
            .take(5)
            .enumerate()
        {
            fragmented.ranges[index] = NativeByteRange {
                start: byte,
                end: byte,
            };
            fragmented.range_count =
                u8::try_from(index.checked_add(1).expect("five fixed alternatives")).unwrap();
            fragmented.candidate_bytes = u16::from(fragmented.range_count);
        }
        assert_eq!(fragmented.range_count, 5);
        assert_eq!(vector_filter_instruction_units(fragmented), 9);
        assert_eq!(estimated_filter_frequency_units(fragmented), 5);
        assert_eq!(
            aarch64_sve_batch_max_vector_bytes(fragmented, Aarch64SveFilterKind::Sve),
            None
        );
        assert_eq!(
            aarch64_sve_batch_max_vector_bytes(
                fragmented,
                Aarch64SveFilterKind::Sve2 {
                    match_table_offset: 0,
                },
            ),
            Some(16)
        );
    }

